class TokenBucket:
    def __init__(self, capacity: int, fill_rate: float):
        self.capacity = float(capacity)
        self._tokens = float(capacity)
        self.fill_rate = float(fill_rate)
        self.timestamp = time.time()

    async def consume(self, tokens: int = 1):
        while True:
            now = time.time()
            if self._tokens < self.capacity:
                self._tokens += self.fill_rate * (now - self.timestamp)
                if self._tokens > self.capacity:
                    self._tokens = self.capacity
            self.timestamp = now
            if self._tokens >= tokens:
                self._tokens -= tokens
                return True
            await asyncio.sleep(0.1)

class Scanner(ScannerChartMixin, ScannerTelemetryMixin, ScannerRecalculationMixin):
    CORE_CORRELATED_INDICES = {"NIFTY", "BANKNIFTY", "SENSEX"}
    MIDCAP_CORRELATED_INDEX = "MIDCPNIFTY"
    LATE_RECLAIM_BASKET_INDICES = {"NIFTY", "BANKNIFTY", "SENSEX", "MIDCPNIFTY"}

    """Continuous scanning engine — optimized, best-signal selection"""

