    def _update_dashboard_cache(self, payload: Dict[str, Any]) -> None:
        cache = getattr(self, "dashboard_cache", None)
        if cache is not None:
            cached_payload = dict(payload or {})
            cached_payload["calibration"] = self.outcome_calibration.validation_status()
            cache.update(cached_payload)

    def _publish_config_snapshot(self) -> None:
        snapshot = dict(getattr(self, "latest_results", {}) or {})
        snapshot["mode"] = self.mode
        snapshot["config"] = self.get_broadcast_config()
        snapshot["timestamp"] = datetime.now(IST).isoformat()
        trade_summary = ((snapshot.get("trades") or {}).get("summary") or {})
        self._sync_engine_lab_active_row(snapshot, trade_summary)
        self.latest_results = snapshot
        self._update_dashboard_cache(snapshot)

    def _engine_lab_enabled(self) -> bool:
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "engine_lab_enabled", True), True):
            return False
        if (
            self._setting_enabled(getattr(settings, "engine_lab_real_mode_only", False), False)
            and str(getattr(self, "mode", "") or "").upper() != "REAL"
        ):
            return False
        return True

    def _make_engine_lab_trade_manager(self):
        temp = object.__new__(TradeManager)
        temp.broker = None
        temp.ui_logger = None
        temp.max_positions = int(getattr(self.trades, "max_positions", 3) or 3)
        temp.session_end = getattr(self.trades, "session_end", dtime(15, 25))
        temp.product_type = str(getattr(self.trades, "product_type", "CARRYFORWARD") or "CARRYFORWARD")
        temp.open_trades = {}
        temp.closed_trades = []
        temp._trade_counter = 0
        temp._lock = threading.RLock()
        temp._state_file = ""
        temp._last_mark_to_market_save = 0.0
        temp._last_protective_sync = {}
        temp._last_protective_status_poll = {}
        temp._last_recovery_alert = {}
        temp.orphan_positions = {}
        temp.futures_sl_pct = self.futures_sl_pct
        temp.options_sl_pct = self.options_sl_pct
        temp.scanner = self
        temp.mode = "HISTORICAL"
        return temp

    def _engine_lab_actual_cache_fingerprint(self) -> Tuple[Any, ...]:
        settings = get_settings()

        def freeze(value: Any) -> Any:
            if isinstance(value, dict):
                return tuple(sorted((str(k), freeze(v)) for k, v in value.items()))
            if isinstance(value, (list, tuple, set)):
                return tuple(freeze(v) for v in value)
            return value

        candle_fp = []
        for inst in list(getattr(self, "active_indices", []) or []):
            for tf in ("1min", "5min", "15min"):
                frame = self.candles.get_candles(inst, tf)
                if frame is None or frame.empty:
                    candle_fp.append((inst, tf, 0, ""))
                    continue
                idx = frame.index[-1]
                candle_fp.append((inst, tf, len(frame), idx.isoformat() if hasattr(idx, "isoformat") else str(idx)))
        return (
            "actual-v2",
            str(getattr(self, "mode", "") or "").upper(),
            int(getattr(self, "backtest_days", 1) or 1),
            tuple(getattr(self, "active_indices", []) or []),
            freeze(settings.get_ut_engine_params()),
            str(getattr(settings, "signal_grade_preference", "") or ""),
            str(getattr(settings, "inst_pref", getattr(self, "inst_pref", "AUTO")) or ""),
            str(getattr(settings, "option_strike_selection", "BOTH") or ""),
            tuple(sorted((getattr(self, "user_lots", {}) or {}).items())),
            tuple(sorted((getattr(self, "user_lots_fut", {}) or {}).items())),
            tuple(candle_fp),
        )

    def _run_engine_lab_actual_historical_sweep(self) -> Dict[str, Dict[str, Any]]:
        if str(getattr(self, "mode", "") or "").upper() != "HISTORICAL":
            return {}
        cache_key = self._engine_lab_actual_cache_fingerprint()
        if cache_key == getattr(self, "_engine_lab_actual_cache_key", None):
            return dict(getattr(self, "_engine_lab_actual_cache", {}) or {})

        settings = get_settings()
        previous = {
            "scanner_engine": str(getattr(settings, "scanner_engine", "utbot") or "utbot").lower(),
            "mtf": self.mtf,
            "trades": self.trades,
            "cached_results": getattr(self, "_cached_results", {}),
            "candidate_process_cache": getattr(self, "_candidate_process_cache", {}),
            "last_signal_time": getattr(self, "_last_signal_time", {}),
            "session_trade_candidates": getattr(self, "_session_trade_candidates", {}),
            "latest_trade_candidates": getattr(self, "_latest_trade_candidates", {}),
            "latest_exit_candidates": getattr(self, "_latest_exit_candidates", {}),
            "latest_filtered_candidates": getattr(self, "_latest_filtered_candidates", {}),
            "dir_census": getattr(self, "_dir_census", None),
            "dir_census_seen": getattr(self, "_dir_census_seen", None),
            "dir_census_date": getattr(self, "_dir_census_date", None),
            "risk_trades": getattr(getattr(self, "risk_manager", None), "trades", None),
            "risk_daily_loss_breached": getattr(getattr(self, "risk_manager", None), "daily_loss_breached", False),
            "risk_fut_loss_breached": getattr(getattr(self, "risk_manager", None), "fut_loss_breached", False),
            "risk_opt_loss_breached": getattr(getattr(self, "risk_manager", None), "opt_loss_breached", False),
        }

        rows: Dict[str, Dict[str, Any]] = {}
        started = time.time()
        try:
            for mode in ENGINE_LAB_MODES:
                settings.scanner_engine = mode
                self.mtf = MultiTimeframeEngine(settings.get_ut_engine_params())
                self.trades = self._make_engine_lab_trade_manager()
                if getattr(self, "risk_manager", None) is not None:
                    self.risk_manager.trades = self.trades
                    self.risk_manager.daily_loss_breached = False
                    self.risk_manager.fut_loss_breached = False
                    self.risk_manager.opt_loss_breached = False
                self._cached_results = {}
                self._candidate_process_cache = {}
                self._last_signal_time = {}
                self._session_trade_candidates = {}
                self._latest_trade_candidates = {}
                self._latest_exit_candidates = {}
                self._latest_filtered_candidates = {}
                self._dir_census = {"LONG": 0, "SHORT": 0}
                self._dir_census_seen = set()
                self._dir_census_date = None
                for inst in list(getattr(self, "active_indices", []) or []):
                    cfg = self.config.get("indices", {}).get(inst)
                    if cfg:
                        self._process_instrument(inst, cfg)
                payload = self.trades.get_dashboard_payload(
                    is_historical=True,
                    backtest_days=int(getattr(self, "backtest_days", 1) or 1),
                    inst_pref=str(getattr(self, "inst_pref", "AUTO") or "AUTO"),
                )
                summary = payload.get("summary", {}) or {}
                rows[mode] = {
                    "basis": "ACTUAL BACKTEST",
                    "trades": int(summary.get("total_trades", 0) or 0),
                    "open": int(summary.get("open_count", 0) or 0),
                    "wins": int(summary.get("wins", 0) or 0),
                    "losses": int(summary.get("losses", 0) or 0),
                    "win_rate": round(float(summary.get("win_rate", 0.0) or 0.0), 1),
                    "total_money": round(float(summary.get("daily_pnl", 0.0) or 0.0), 2),
                    "fut_pnl": round(float(summary.get("fut_pnl", 0.0) or 0.0), 2),
                    "opt_pnl": round(float(summary.get("opt_pnl", 0.0) or 0.0), 2),
                    "profit_factor": round(float(summary.get("profit_factor", 0.0) or 0.0), 2),
                    "sharpe": round(float(summary.get("sharpe_ratio", 0.0) or 0.0), 2),
                    "sharpe_display": str(summary.get("sharpe_ratio_display", "") or ""),
                    "max_drawdown": round(float(summary.get("max_drawdown", 0.0) or 0.0), 2),
                }
        except Exception as exc:
            logger.warning(f"Engine Lab actual historical sweep failed: {exc}")
            rows = {}
        finally:
            settings.scanner_engine = previous["scanner_engine"]
            self.mtf = previous["mtf"]
            self.trades = previous["trades"]
            self._cached_results = previous["cached_results"]
            self._candidate_process_cache = previous["candidate_process_cache"]
            self._last_signal_time = previous["last_signal_time"]
            self._session_trade_candidates = previous["session_trade_candidates"]
            self._latest_trade_candidates = previous["latest_trade_candidates"]
            self._latest_exit_candidates = previous["latest_exit_candidates"]
            self._latest_filtered_candidates = previous["latest_filtered_candidates"]
            self._dir_census = previous["dir_census"] if previous["dir_census"] is not None else {}
            self._dir_census_seen = previous["dir_census_seen"] if previous["dir_census_seen"] is not None else set()
            self._dir_census_date = previous["dir_census_date"]
            if getattr(self, "risk_manager", None) is not None:
                self.risk_manager.trades = previous["risk_trades"]
                self.risk_manager.daily_loss_breached = previous["risk_daily_loss_breached"]
                self.risk_manager.fut_loss_breached = previous["risk_fut_loss_breached"]
                self.risk_manager.opt_loss_breached = previous["risk_opt_loss_breached"]

        self._engine_lab_actual_cache_key = cache_key
        self._engine_lab_actual_cache = dict(rows)
        logger.info(
            "Engine Lab actual historical sweep: "
            f"{len(rows)}/{len(ENGINE_LAB_MODES)} engines in {time.time() - started:.2f}s"
        )
        return dict(rows)

    def _engine_lab_snapshot(self, include_actual_sweep: bool = True) -> Dict[str, Any]:
        lab = getattr(self, "engine_lab", None)
        if lab is None:
            return {"enabled": False, "rows": [], "summary": {}, "updated_at": ""}
        if not self._engine_lab_enabled():
            snapshot = lab.snapshot()
            snapshot["enabled"] = False
            return snapshot
        if str(getattr(self, "mode", "") or "").upper() == "HISTORICAL":
            return self._engine_lab_compute_snapshot(include_actual_sweep=include_actual_sweep)
        return self._engine_lab_snapshot_nonblocking()

    def _engine_lab_snapshot_for_scan(self) -> Dict[str, Any]:
        """Fast scan-loop lab payload.

        The all-engine actual backtest sweep swaps scanner trade books in place.
        Running it inside the scan loop makes multi-day historical rebuilds look
        like scanner hangs. The scan payload therefore publishes the lightweight
        shadow lab immediately; dashboard/trades overlays still make the active
        engine exact without blocking recalculation.
        """
        include_actual = str(getattr(self, "mode", "") or "").upper() != "HISTORICAL"
        return self._engine_lab_snapshot(include_actual_sweep=include_actual)

    def _engine_lab_snapshot_nonblocking(self) -> Dict[str, Any]:
        """Serve the last lab snapshot and refresh it off the scan loop.

        A tick-updated lab pass costs ~1s across all lab engines x 4 indices x 3 TFs;
        computing it inline would stall the 1s scan cycle and the 100ms trade
        monitor sharing this event loop. Live mode answers from the last snapshot
        and refreshes on a worker thread, throttled by engine_lab_refresh_seconds.
        """
        now = time.time()
        refresh_seconds = max(
            2.0, float(getattr(get_settings(), "engine_lab_refresh_seconds", 10.0) or 10.0)
        )
        last_refresh = float(getattr(self, "_engine_lab_live_refreshed_at", 0.0) or 0.0)
        if (now - last_refresh) >= refresh_seconds and not getattr(self, "_engine_lab_refresh_inflight", False):
            self._engine_lab_refresh_inflight = True
            frames = self._engine_lab_collect_frames(copy=True)

            def _refresh() -> None:
                try:
                    self._lower_current_thread_priority()
                    # No actual-sweep here: the sweep mutates scanner trade books and
                    # must never run on a worker thread (mode could flip mid-refresh).
                    self._engine_lab_compute_snapshot(frames, include_actual_sweep=False)
                    self._engine_lab_live_refreshed_at = time.time()
                except Exception as exc:
                    logger.debug(f"Engine Lab background refresh failed: {exc}")
                finally:
                    self._engine_lab_refresh_inflight = False

            try:
                asyncio.get_running_loop()
                # Dedicated single-thread executor: lab work never shares a queue
                # with LTP/broker tasks and can never run more than one refresh.
                self._engine_lab_executor.submit(_refresh)
            except RuntimeError:
                # No running loop (tests / manual callers): compute inline.
                _refresh()
        return self.engine_lab.snapshot()

    @staticmethod
    def _lower_current_thread_priority() -> None:
        """Drop the calling thread to below-normal OS priority (Windows).

        Lab refreshes are pure diagnostics; when the OS has to choose between this
        thread and the scanner loop / broker threads, it must never pick the lab.
        """
        if os.name != "nt":
            return
        try:
            import ctypes

            thread_priority_below_normal = -1
            handle = ctypes.windll.kernel32.GetCurrentThread()
            ctypes.windll.kernel32.SetThreadPriority(handle, thread_priority_below_normal)
        except Exception:
            pass

    def _engine_lab_collect_frames(self, copy: bool = False) -> Dict[str, Dict[str, Any]]:
        """Per-instrument analysis windows; copy=True hands worker threads their own
        frames so they never share live candle buffers with the scan loop."""
        candles_by_instrument: Dict[str, Dict[str, Any]] = {}
        for inst in list(getattr(self, "active_indices", []) or []):
            tf_map = {}
            for tf in ("1min", "5min", "15min"):
                frame = self.candles.get_candles(inst, tf)
                if frame is not None:
                    window = self._live_analysis_window(frame, tf)
                    if window is not None:
                        tf_map[tf] = window.copy() if copy else window
            if tf_map:
                candles_by_instrument[inst] = tf_map
        return candles_by_instrument

    def _engine_lab_compute_snapshot(
        self,
        candles_by_instrument: Optional[Dict[str, Dict[str, Any]]] = None,
        include_actual_sweep: bool = True,
    ) -> Dict[str, Any]:
        lab = self.engine_lab
        try:
            params = get_settings().get_ut_engine_params()
            lab.rebuild_if_params_changed(params)
            if candles_by_instrument is None:
                candles_by_instrument = self._engine_lab_collect_frames()
            if not candles_by_instrument:
                return lab.snapshot()
            lot_sizes = {
                inst: int((self.config.get("indices", {}).get(inst) or {}).get("lot_size", 1) or 1)
                for inst in candles_by_instrument
            }
            snapshot = lab.process(
                candles_by_instrument=candles_by_instrument,
                active_engine=str(getattr(get_settings(), "scanner_engine", "") or "").lower(),
                capital=float(getattr(self, "capital_fut", 0.0) or 0.0) + float(getattr(self, "capital_opt", 0.0) or 0.0),
                risk_pct=float(getattr(self, "risk_fut_pct", 1.0) or 1.0),
                lots_by_instrument=dict(getattr(self, "user_lots", {}) or {}),
                lot_size_by_instrument=lot_sizes,
            )
            actual_rows = self._run_engine_lab_actual_historical_sweep() if include_actual_sweep else {}
            if actual_rows:
                active_mode = str(getattr(get_settings(), "scanner_engine", "") or "").lower()
                active_summary: Dict[str, Any] = {}
                try:
                    active_summary = (self._build_dashboard_trade_payload().get("summary", {}) or {})
                except Exception as exc:
                    logger.debug(f"Engine Lab active summary overlay skipped: {exc}")
                for row in snapshot.get("rows", []) or []:
                    mode = str(row.get("engine", "") or "").lower()
                    actual = actual_rows.get(mode)
                    if not actual:
                        continue
                    if mode == active_mode and active_summary:
                        actual = {
                            **actual,
                            "basis": "ACTUAL BACKTEST",
                            "trades": int(active_summary.get("total_trades", 0) or 0),
                            "open": int(active_summary.get("open_count", 0) or 0),
                            "wins": int(active_summary.get("wins", 0) or 0),
                            "losses": int(active_summary.get("losses", 0) or 0),
                            "win_rate": round(float(active_summary.get("win_rate", 0.0) or 0.0), 1),
                            "total_money": round(float(active_summary.get("daily_pnl", 0.0) or 0.0), 2),
                            "fut_pnl": round(float(active_summary.get("fut_pnl", 0.0) or 0.0), 2),
                            "opt_pnl": round(float(active_summary.get("opt_pnl", 0.0) or 0.0), 2),
                            "profit_factor": round(float(active_summary.get("profit_factor", 0.0) or 0.0), 2),
                            "sharpe": round(float(active_summary.get("sharpe_ratio", 0.0) or 0.0), 2),
                            "sharpe_display": str(active_summary.get("sharpe_ratio_display", "") or ""),
                            "max_drawdown": round(float(active_summary.get("max_drawdown", 0.0) or 0.0), 2),
                        }
                    Scanner._apply_engine_lab_actual_row(
                        row,
                        actual,
                        display_basis=actual.get("basis", "ACTUAL BACKTEST"),
                    )
                snapshot["summary"]["actual_engines"] = len(actual_rows)
                snapshot["summary"]["basis"] = "ACTUAL BACKTEST"
            elif not include_actual_sweep:
                summary = snapshot.setdefault("summary", {})
                summary.setdefault("basis", "RAW SHADOW")
                summary["actual_deferred"] = True
            return snapshot
        except Exception as exc:
            logger.debug(f"Engine Lab snapshot failed: {exc}")
            snapshot = lab.snapshot()
            snapshot["error"] = str(exc)
            return snapshot

    @staticmethod
    def _apply_engine_lab_actual_row(
        row: Dict[str, Any],
        actual: Dict[str, Any],
        *,
        display_basis: str,
    ) -> None:
        """Overlay trade-manager results without mixing in shadow replay points."""
        row["actual_result"] = True
        row["display_basis"] = display_basis
        row["raw_signals"] = row.get("raw_signals", row.get("signals", 0))
        row["raw_open"] = row.get("raw_open", row.get("open", 0))
        row["raw_open_rows"] = row.get("raw_open_rows", list(row.get("open_rows", []) or []))
        row["raw_net_points"] = row.get("raw_net_points", row.get("net_points"))
        row["raw_open_points"] = row.get("raw_open_points", row.get("open_points"))
        row["raw_total_points"] = row.get("raw_total_points", row.get("total_points"))
        for lane_key in (
            "lane_A_signals",
            "lane_B_signals",
            "lane_A_pnl",
            "lane_B_pnl",
            "dual_concurrent_pnl",
            "lane_jaccard",
        ):
            row[f"raw_{lane_key}"] = row.get(f"raw_{lane_key}", row.get(lane_key))
        row["signals"] = int(actual.get("trades", row.get("signals", 0)) or 0)
        row["open"] = int(actual.get("open", row.get("open", 0)) or 0)
        row["closed"] = int(actual.get("trades", row.get("closed", 0)) or 0)
        row["wins"] = int(actual.get("wins", row.get("wins", 0)) or 0)
        row["losses"] = int(actual.get("losses", row.get("losses", 0)) or 0)
        row["win_rate"] = round(float(actual.get("win_rate", row.get("win_rate", 0.0)) or 0.0), 1)
        row["total_money"] = round(float(actual.get("total_money", row.get("total_money", 0.0)) or 0.0), 2)
        row["fut_pnl"] = round(float(actual.get("fut_pnl", row.get("fut_pnl", 0.0)) or 0.0), 2)
        row["opt_pnl"] = round(float(actual.get("opt_pnl", row.get("opt_pnl", 0.0)) or 0.0), 2)
        row["profit_factor"] = round(float(actual.get("profit_factor", row.get("profit_factor", 0.0)) or 0.0), 2)
        row["sharpe"] = round(float(actual.get("sharpe", row.get("sharpe", 0.0)) or 0.0), 2)
        row["sharpe_display"] = str(actual.get("sharpe_display", row.get("sharpe_display", "")) or "")
        row["max_drawdown"] = round(float(actual.get("max_drawdown", row.get("max_drawdown", 0.0)) or 0.0), 2)
        row["net_points"] = None
        row["open_points"] = None
        row["total_points"] = None
        row["gross_gain"] = None
        row["gross_loss"] = None
        row["open_rows"] = []

    def _sync_engine_lab_active_row(
        self,
        snapshot: Dict[str, Any],
        trade_summary: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Retarget cached Engine Lab rows after a cheap config/trades refresh.

        The lab snapshot is expensive in historical mode, so dashboard endpoints may
        reuse a cached lab table while refreshing config or trade totals. Keep the
        active marker and the active row's trade-manager metrics aligned with the
        current scanner engine so the UI never shows a stale active engine.
        """
        if not isinstance(snapshot, dict):
            return snapshot
        lab = snapshot.get("engine_lab")
        if not isinstance(lab, dict):
            return snapshot
        rows = lab.get("rows")
        if not isinstance(rows, list):
            return snapshot

        active_mode = str(getattr(get_settings(), "scanner_engine", "") or "").lower()
        if not active_mode:
            return snapshot
        lab["active_engine"] = active_mode

        summary = trade_summary or ((snapshot.get("trades") or {}).get("summary") or {})
        for row in rows:
            if not isinstance(row, dict):
                continue
            mode = str(row.get("engine", "") or "").lower()
            is_active = mode == active_mode
            row["active"] = is_active
            if not is_active or not summary:
                continue
            Scanner._apply_engine_lab_actual_row(
                row,
                {
                    "trades": summary.get("total_trades", row.get("signals", 0)),
                    "open": summary.get("open_count", row.get("open", 0)),
                    "wins": summary.get("wins", row.get("wins", 0)),
                    "losses": summary.get("losses", row.get("losses", 0)),
                    "win_rate": summary.get("win_rate", row.get("win_rate", 0.0)),
                    "total_money": summary.get("daily_pnl", row.get("total_money", 0.0)),
                    "fut_pnl": summary.get("fut_pnl", row.get("fut_pnl", 0.0)),
                    "opt_pnl": summary.get("opt_pnl", row.get("opt_pnl", 0.0)),
                    "profit_factor": summary.get("profit_factor", row.get("profit_factor", 0.0)),
                    "sharpe": summary.get("sharpe_ratio", row.get("sharpe", 0.0)),
                    "sharpe_display": summary.get("sharpe_ratio_display", row.get("sharpe_display", "")),
                    "max_drawdown": summary.get("max_drawdown", row.get("max_drawdown", 0.0)),
                },
                display_basis=(
                    "ACTUAL BACKTEST"
                    if str(getattr(self, "mode", "") or "").upper() == "HISTORICAL"
                    else row.get("display_basis", "LIVE")
                ),
            )
        return snapshot

    def apply_scanner_engine_switch(self, mode: str) -> Dict[str, Any]:
        """Switch scanner engine and invalidate the right historical generation.

        A scanner-engine change alters signal identity, chart markers, trade rows,
        and P&L in HISTORICAL mode. Treat it like a full backtest setting change
        instead of a light chart refresh, otherwise the dashboard can temporarily
        reuse rows generated by the previous engine.
        """
        allowed = {"utbot", "ema", "consensus", "auto", "utbot_ema", "utbot_consensus", "quad_union", "utbot_prime", "quad_prime", "adaptive_hybrid", "adaptive_dual", "quality_hybrid"}
        normalized = str(mode or "utbot").lower()
        if normalized not in allowed:
            normalized = "utbot"

        settings = get_settings()
        previous = str(getattr(settings, "scanner_engine", "utbot") or "utbot").lower()
        settings.scanner_engine = normalized

        mtf = getattr(self, "mtf", None)
        if mtf is not None and hasattr(mtf, "set_scanner_engine"):
            applied = mtf.set_scanner_engine(normalized)
            if applied:
                normalized = str(applied).lower()
                settings.scanner_engine = normalized

        self.invalidate_chart_caches()
        for attr_name in ("_cached_hist_signals", "_cached_hist_closed_count"):
            if hasattr(self, attr_name):
                delattr(self, attr_name)
        for cache_name in (
            "_latest_filtered_candidates",
            "_missed_reentry_candidates",
            "_last_signal_time",
            "_last_signal_identity",
            "_last_live_signal_candle_time",
            "_pending_live_signals",
            "_post_repaint_recheck",
        ):
            cache = getattr(self, cache_name, None)
            if hasattr(cache, "clear"):
                cache.clear()
        if hasattr(mtf, "_result_cache"):
            mtf._result_cache.clear()
        if hasattr(mtf, "_data_hash"):
            mtf._data_hash.clear()

        queued_recalculation = str(getattr(self, "mode", "") or "").upper() == "HISTORICAL"
        if queued_recalculation:
            try:
                self.trades.closed_trades = [
                    trade for trade in self.trades.closed_trades
                    if not (str(getattr(trade, "id", "")).startswith("H_") or str(getattr(trade, "id", "")).startswith("EOD_"))
                ]
                self.trades.open_trades = {}
            except Exception:
                pass
            try:
                self.perf.reset()
            except Exception:
                pass
            self.scan_count = 0
            self._hist_candidates_loaded = False
            self._next_simulation_id()
            self._stamp_simulation_diagnostics()
            self._historical_rebuild_pending = True
            self._set_recalculation_status(
                "queued",
                "scanner-engine-switch",
                previous_scanner_engine=previous,
                scanner_engine=normalized,
            )
            self.queue_full_recalculation("scanner-engine-switch")

        self._publish_config_snapshot()
        schedule_settings_save(settings)
        return {
            "scanner_engine": normalized,
            "previous_scanner_engine": previous,
            "recalculation_queued": queued_recalculation,
        }

    def set_chart_stream_enabled(self, enabled: bool) -> bool:
        """Toggle dashboard chart payload generation without affecting trading."""
        self.chart_stream_enabled = bool(enabled)
        if not self.chart_stream_enabled:
                self.latest_results = self.get_latest_results(include_full_charts=False) or self.latest_results
                self._update_dashboard_cache(self.latest_results)
        logger.info(f"Chart stream: {'ENABLED' if self.chart_stream_enabled else 'DISABLED'}")
        return self.chart_stream_enabled

    def allows_historical_trade_creation(self) -> bool:
        """Only offline historical/backtest mode may create simulated trade rows."""
        return str(getattr(self, "mode", "") or "").upper() == "HISTORICAL"

    def historical_session_cutoff_date(self, now: Optional[datetime] = None):
        """Last session date allowed in historical mode.

        Today's live session becomes historical only after the market handoff
        time. Before that, historical views/backfills stay on completed data.
        """
        now_ist = now or datetime.now(IST)
        if getattr(now_ist, "tzinfo", None) is None:
            now_ist = IST.localize(now_ist)
        else:
            now_ist = now_ist.astimezone(IST)

        handoff = dtime(15, 30)
        session_day = datetime.fromisoformat(str(self._get_current_session_day())).date()
        # Overnight, _get_current_session_day already resolves to the previous
        # completed market session. Do not subtract another trading day.
        if now_ist.date() > session_day or now_ist.time() >= handoff:
            return session_day

        try:
            dates = [
                datetime.fromisoformat(str(day)).date()
                for day in db.list_session_signal_dates()
                if datetime.fromisoformat(str(day)).date() < session_day
            ]
            if dates:
                return dates[-1]
        except Exception:
            pass
        return session_day - timedelta(days=1)

    def _warm_memory_allowed(self) -> bool:
        return str(getattr(self, "mode", "") or "").upper() == "REAL"

    def _warm_memory_cutoff(self) -> datetime:
        now_fn = getattr(self.warm_memory, "_now", None)
        now = now_fn() if callable(now_fn) else datetime.now(IST)
        return now - getattr(self.warm_memory, "ttl", timedelta(minutes=15))

    def _build_warm_memory_payload(self) -> Dict[str, Any]:
        cutoff = self._warm_memory_cutoff()
        candles: Dict[str, Dict[str, list]] = {}
        for instrument in list(getattr(self, "active_indices", []) or []):
            tf_map = {}
            for tf in ("1min", "5min", "15min"):
                rows = dataframe_to_records(self.candles.get_candles(instrument, tf), cutoff)
                if rows:
                    tf_map[tf] = rows
            if tf_map:
                candles[instrument] = tf_map

        session_candidates: Dict[str, list] = {}
        for instrument, book in (getattr(self, "_session_trade_candidates", {}) or {}).items():
            rows = []
            for candidate in (book or {}).values():
                if not self._candidate_matches_live_session_day(candidate):
                    continue
                row = self._serialize_trade_candidate(candidate)
                if str(row.get("id") or "").startswith(("H_", "EOD_")):
                    continue
                rows.append(row)
            if rows:
                session_candidates[instrument] = rows[-150:]

        pending_live_signals = []
        pending_source = (
            (getattr(self, "_pending_live_signals", {}) or {})
            if self._intracandle_signals_enabled()
            else {}
        )
        for key, item in pending_source.items():
            if not isinstance(item, dict):
                continue
            candidate = item.get("candidate")
            buffered_at = item.get("timestamp")
            if candidate is None or buffered_at is None:
                continue
            row = self._serialize_trade_candidate(candidate)
            row["source_signal_type"] = str(
                getattr(candidate, "source_signal_type", "")
                or ("BUY" if getattr(candidate, "direction", "") == "LONG" else "SELL")
            )
            sig_timestamp = item.get("sig_timestamp") or getattr(candidate, "signal_timestamp", None)
            pending_live_signals.append({
                "key": str(key),
                "buffered_at": buffered_at.isoformat(),
                "sig_timestamp": sig_timestamp.isoformat() if sig_timestamp is not None else "",
                "candidate": row,
            })

        return {
            "mode": self.mode,
            "signal_fire_mode": self._signal_fire_mode(),
            "session_day": getattr(self, "_session_candidate_day", self._get_current_session_day()),
            "active_indices": list(getattr(self, "active_indices", []) or []),
            "candles": candles,
            "latest_prices": dict(getattr(self.candles, "_latest_prices", {}) or {}),
            "session_candidates": session_candidates,
            "pending_live_signals": pending_live_signals,
            "latest_results": self.latest_results or {},
            "open_trade_ids": list(getattr(self.trades, "open_trades", {}) or {}),
        }

    def _save_warm_memory(self, force: bool = False) -> bool:
        if not getattr(self, "warm_memory", None) or not self._warm_memory_allowed():
            return False
        try:
            if self.warm_memory.save(self._build_warm_memory_payload(), force=force):
                logger.debug("Warm memory checkpoint saved.")
                return True
        except Exception as exc:
            logger.debug(f"Warm memory checkpoint skipped: {exc}")
        return False

    def _restore_warm_memory(self) -> None:
        if not getattr(self, "warm_memory", None) or not self._warm_memory_allowed():
            return
        payload = self.warm_memory.load()
        if not payload:
            return
        if payload.get("session_day") != getattr(self, "_session_candidate_day", self._get_current_session_day()):
            return
        restored_candles = 0
        for instrument, tf_map in (payload.get("candles") or {}).items():
            if instrument not in set(getattr(self, "active_indices", []) or []):
                continue
            for tf, records in (tf_map or {}).items():
                df = records_to_dataframe(records or [])
                if df.empty:
                    continue
                self.candles.update_candles(instrument, df, tf)
                restored_candles += len(df)

        for instrument, price in (payload.get("latest_prices") or {}).items():
            try:
                self.candles.update_latest_price(instrument, float(price))
            except Exception:
                pass

        restored_candidates = 0
        sqlite_ledger_present = any(
            bool(book)
            for book in (getattr(self, "_session_trade_candidates", {}) or {}).values()
        )
        warm_candidate_rows = {} if sqlite_ledger_present else (payload.get("session_candidates") or {})
        for instrument, rows in warm_candidate_rows.items():
            for row in rows or []:
                candidate = self._candidate_from_payload(row)
                if not candidate or not self._candidate_matches_live_session_day(candidate):
                    continue
                if str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper() == "NO_ENTRY":
                    continue
                book = self._session_trade_candidates.setdefault(instrument, {})
                history_key = self._candidate_history_key(candidate)
                existing = book.get(history_key)
                if (
                    existing is not None
                    and str(getattr(existing, "action", "ENTRY") or "ENTRY").upper() == "ENTRY"
                    and bool(getattr(existing, "accepted_by_gate", False))
                ):
                    # SQLite is the authoritative session ledger. Warm memory may
                    # restore candles, but cannot replace an already accepted contract.
                    continue
                book[history_key] = candidate
                restored_candidates += 1

        restored_pending = 0
        restore_pending = (
            self._intracandle_signals_enabled()
            and str(payload.get("signal_fire_mode") or "INTRACANDLE").upper()
            == self._signal_fire_mode()
        )
        for item in (payload.get("pending_live_signals") or []) if restore_pending else []:
            if not isinstance(item, dict):
                continue
            candidate = self._candidate_from_payload(item.get("candidate") or {})
            if not candidate or not self._candidate_matches_live_session_day(candidate):
                continue
            try:
                buffered_at = datetime.fromisoformat(str(item.get("buffered_at") or ""))
                sig_timestamp = datetime.fromisoformat(str(item.get("sig_timestamp") or ""))
            except (TypeError, ValueError):
                continue
            if buffered_at.tzinfo is not None:
                buffered_at = buffered_at.astimezone(IST).replace(tzinfo=None)
            if sig_timestamp.tzinfo is not None:
                sig_timestamp = sig_timestamp.astimezone(IST).replace(tzinfo=None)
            expected_key = f"{candidate.instrument}_{candidate.timeframe}_{candidate.direction}"
            key = str(item.get("key") or expected_key)
            if key != expected_key:
                continue
            source_signal_type = str(
                (item.get("candidate") or {}).get("source_signal_type")
                or ("BUY" if candidate.direction == "LONG" else "SELL")
            )
            setattr(candidate, "source_signal_type", source_signal_type)
            self._pending_live_signals[key] = {
                "timestamp": buffered_at,
                "candidate": candidate,
                "sig_timestamp": sig_timestamp,
                "recovered": True,
            }
            restored_pending += 1

        latest = payload.get("latest_results") or {}
        if isinstance(latest, dict) and latest.get("mode") == self.mode:
            self.latest_results = latest
            self._update_dashboard_cache(latest)

        self._warm_memory_loaded = True
        logger.info(
            f"Warm memory restored: {restored_candles} candle row(s), "
            f"{restored_candidates} live signal row(s), "
            f"{restored_pending} pending stabilization buffer(s)."
        )

    @staticmethod
    def _setting_enabled(value, default: bool = True) -> bool:
        if isinstance(value, bool):
            return value
        if value is None:
            return default
        if isinstance(value, (int, float)):
            return value != 0
        text = str(value).strip().lower()
        if text in {"1", "true", "yes", "y", "on"}:
            return True
        if text in {"0", "false", "no", "n", "off", ""}:
            return False
        return bool(value)

    @staticmethod
    def _strict_setting_enabled(value, default: bool = False) -> bool:
        """Fail-closed bool parser for execution-affecting configure toggles."""
        if isinstance(value, bool):
            return value
        if value is None:
            return default
        if isinstance(value, (int, float)):
            return value != 0
        text = str(value).strip().lower()
        if text in {"1", "true", "yes", "y", "on"}:
            return True
        if text in {"0", "false", "no", "n", "off", ""}:
            return False
        return default

    @staticmethod
    def _signal_fire_mode() -> str:
        settings = get_settings()
        getter = getattr(settings, "get_signal_fire_mode", None)
        if callable(getter):
            return getter()
        return (
            "INTRACANDLE"
            if bool(getattr(settings, "live_intrabar_signal_entries", True))
            else "CANDLE_CLOSE"
        )

    @classmethod
    def _intracandle_signals_enabled(cls) -> bool:
        return cls._signal_fire_mode() == "INTRACANDLE"

    @staticmethod
    def _candidate_source_is_intrabar(candidate, now: Optional[datetime] = None) -> bool:
        if bool(getattr(candidate, "missed_signal_reentry", False)):
            return False
        signal_ts = getattr(candidate, "signal_timestamp", None)
        if signal_ts is None:
            return False
        now = now or datetime.now(IST)
        if getattr(now, "tzinfo", None) is not None:
            now = now.astimezone(IST).replace(tzinfo=None)
        if getattr(signal_ts, "tzinfo", None) is not None:
            signal_ts = signal_ts.astimezone(IST).replace(tzinfo=None)
        minutes = {"1min": 1, "5min": 5, "15min": 15}.get(
            str(getattr(candidate, "timeframe", "") or ""),
            5,
        )
        return now < signal_ts + timedelta(minutes=minutes)

    @staticmethod
    def _normalize_signal_grade_preference(value) -> str:
        """Keep UI/API/env grade settings on one canonical vocabulary."""
        raw = str(value or "auto").strip().upper().replace(" ", "")
        aliases = {
            "": "auto",
            "AUTO": "auto",
            "SMART": "auto",
            "B": "B",
            "B+": "B+",
            "BPLUS": "B+",
            "B_PLUS": "B+",
            "A": "A",
            "A+": "A+",
            "APLUS": "A+",
            "A_PLUS": "A+",
        }
        return aliases.get(raw, "auto")

    def _surface_readiness_warnings(self, readiness) -> None:
        """Log what the readiness check found but does not consider a blocker.

        validate_real_mode_readiness returns "blockers" AND "warnings". Every call site
        read only the blockers, so the warnings were computed and thrown away on every
        arming — the same "primitive wired to no consumer" this audit keeps finding, and
        this time it swallowed the things the operator most needs to hear. On
        2026-08-07 the discarded list was:

          * broker free cash is 11,255.40, below the 50,000 floor for one index lot —
            RMS will refuse entries until the account is funded
          * slippage_opt_pct is 0 — option P&L is modelled with NO slippage
          * 32 setting(s) in .env have no consumer and do nothing

        readiness["ok"] was True throughout. The system armed REAL knowing it could not
        fund a single lot, and said nothing.

        Warnings never block; they are deliberately not promoted to blockers. This only
        makes them audible.
        """
        try:
            warnings = (readiness or {}).get("warnings") or []
        except AttributeError:
            return
        for warning in warnings:
            logger.warning(f"REAL readiness warning: {warning}")
        # One notification, not one per warning: the dashboard toast is a summary and
        # the detail is in the log.
        if warnings and self.on_notification:
            try:
                self.on_notification(
                    f"REAL armed with {len(warnings)} readiness warning(s) — see the log",
                    "warning",
                )
            except Exception as exc:
                logger.debug(f"Readiness warning notification failed: {exc}")

    def configure(self, capital_total=None, capital_fut=None, capital_opt=None, risk_fut_pct=None, risk_opt_pct=None,
                  lots=None, lots_fut=None, mode=None, reset=False, futures_sl_pct=None, options_sl_pct=None,
                  fut_cost=None, opt_cost=None, backtest_days=None, auto_mode=None, inst_pref=None, strike_selection=None, active_indices=None,
                  grade_preference=None, concurrency_guard=None, dynamic_risk_enabled=None,
                  dynamic_risk_hybrid=None, confirm_real_mode=False, real_mode_verification=None, ut_preset=None,
                  timeframe_entry_policy=None, max_trades_per_index=None, max_consecutive_losses=None,
                  index_cooldown_minutes=None, futures_shadow_enabled=None, signal_fire_mode=None,
                  persist_settings=True, **kwargs):
        from config.settings import get_settings
        settings = get_settings()
        self._last_configure_block_reason = ""

        def real_mode_confirmed() -> bool:
            verification_text = str(real_mode_verification or kwargs.get("real_mode_verification", "")).strip().upper()
            return verification_text in {"YES", "REAL"}

        requested_mode = str(mode or "").upper()
        current_mode = str(getattr(self, "mode", "") or "").upper()
        if requested_mode == "REAL" and current_mode != "REAL":
            if not real_mode_confirmed():
                self._last_configure_block_reason = "explicit REAL confirmation required"
                logger.warning("REAL mode blocked: explicit one-step confirmation is required.")
                if self.on_notification:
                    self.on_notification("REAL mode blocked. Confirm YES to switch to REAL.", "error")
                return False
            readiness = validate_real_mode_readiness(settings, getattr(self, "data", None))
            self._surface_readiness_warnings(readiness)
            if getattr(settings, "production_safe_mode_required", True) and not readiness.get("ok"):
                blockers = readiness.get("blockers") or ["readiness failed"]
                reason = "; ".join(str(item) for item in blockers)
                self._last_configure_block_reason = reason
                logger.error(f"REAL mode blocked by safe mode: {reason}")
                if self.on_notification:
                    self.on_notification(f"REAL mode blocked: {reason}", "error")
                return False

        if (
            requested_mode
            and current_mode == "REAL"
            and requested_mode != "REAL"
            and self.trades.has_live_exposure()
        ):
            self._last_configure_block_reason = "live broker exposure is active"
            logger.critical("Mode switch blocked while REAL broker exposure is active.")
            if self.on_notification:
                self.on_notification(
                    "Close and reconcile all REAL positions before switching mode.",
                    "error",
                )
            return False

        if reset and current_mode == "REAL" and self.trades.has_live_exposure():
            self._last_configure_block_reason = "live broker exposure is active"
            logger.critical("P&L reset blocked while REAL broker exposure is active.")
            if self.on_notification:
                self.on_notification(
                    "P&L reset blocked until all REAL positions are broker-flat.",
                    "error",
                )
            return False

        if (
            auto_mode is not None
            and self._strict_setting_enabled(auto_mode, False)
            and (requested_mode or current_mode) == "REAL"
        ):
            verification_text = str(real_mode_verification or kwargs.get("real_mode_verification", "")).strip().upper()
            if not confirm_real_mode or verification_text not in {"YES", "REAL"}:
                self._last_configure_block_reason = "explicit REAL auto-execution confirmation required"
                logger.warning("REAL auto-execution blocked: explicit verification is required.")
                if self.on_notification:
                    self.on_notification(
                        "REAL auto-execution blocked. Confirm to enable Auto Mode in REAL.",
                        "error",
                    )
                return False
            # Audit fix (HIGH-2): the HISTORICAL→REAL readiness gate above only runs when
            # requested_mode=="REAL" and we are not already REAL. By the time a human
            # toggles Auto Mode, the 09:00 premarket worker has usually already armed REAL,
            # so this toggle sends mode=None and skips that gate entirely — arming unattended
            # auto-execution on nothing more than a confirmation string. Re-validate broker
            # connectivity / warmup / feed freshness here before enabling auto-execution.
            if current_mode == "REAL" or requested_mode == "REAL":
                readiness = validate_real_mode_readiness(settings, getattr(self, "data", None))
                self._surface_readiness_warnings(readiness)
                if getattr(settings, "production_safe_mode_required", True) and not readiness.get("ok"):
                    blockers = readiness.get("blockers") or ["readiness failed"]
                    reason = "; ".join(str(item) for item in blockers)
                    self._last_configure_block_reason = f"auto-execution readiness failed: {reason}"
                    logger.error(f"REAL auto-execution blocked by safe mode: {reason}")
                    if self.on_notification:
                        self.on_notification(
                            f"REAL auto-execution blocked: {reason}",
                            "error",
                        )
                    return False


        # Only apply explicitly-provided values. A partial configure (e.g. the auto-mode
        # toggle) forwards every other field as None via msg.get(); without this guard the
        # loop would null out ~25 advanced settings (price-action/regime-veto/volume-spike/
        # time-cutoffs) on every toggle, silently disabling features and blanking the UI.
        regime_refresh_settings = {
            "regime_early_trend_er_promotion_enabled",
            "regime_early_trend_er_period",
            "regime_early_trend_er_threshold",
            "regime_early_trend_er_adx_ceiling",
            "regime_early_trend_er_range_day_min_confidence",
            "quality_hybrid_min_vote_score",
            "quality_hybrid_broad_agreement",
            "quality_hybrid_chop_min_agreement",
            "quality_hybrid_trend_adx",
            "quality_hybrid_trend_er",
            "quality_hybrid_thrust_volume_ratio",
            "quality_hybrid_thrust_range_atr",
            "quality_hybrid_thrust_close_loc",
        }
        advanced_refresh_changed = False
        for k, v in kwargs.items():
            if v is not None:
                old_value = getattr(settings, k, None)
                setattr(settings, k, v)
                if k in regime_refresh_settings and old_value != v:
                    advanced_refresh_changed = True

        needs_full_refresh = advanced_refresh_changed

        if signal_fire_mode is not None:
            old_signal_mode = self._signal_fire_mode()
            try:
                new_signal_mode = settings.set_signal_fire_mode(signal_fire_mode)
            except (AttributeError, ValueError):
                logger.warning(f"Rejected unsupported signal fire mode: {signal_fire_mode}")
                return False
            if old_signal_mode != new_signal_mode:
                if hasattr(self.mtf, "apply_engine_params"):
                    self.mtf.apply_engine_params(settings.get_ut_engine_params())
                self._pending_live_signals.clear()
                self._pending_opposite_exit.clear()
                self._live_signal_recheck_eligible.clear()
                self._live_signal_recheck_at.clear()
                needs_full_refresh = True
                label = "Intra-candle" if new_signal_mode == "INTRACANDLE" else "Closed candle"
                logger.info(f"UT1 signal timing changed to {label}.")
                self.log_event(f"UT1 signals: {label}", "system")

        if futures_shadow_enabled is not None:
            old_val = self._strict_setting_enabled(
                getattr(settings, "futures_shadow_enabled", False),
                False,
            )
            new_val = self._strict_setting_enabled(futures_shadow_enabled, False)
            if old_val != new_val:
                settings.futures_shadow_enabled = new_val
                needs_full_refresh = True
                logger.info(
                    "Historical futures-shadow comparison "
                    f"{'enabled' if new_val else 'disabled'}; live orders are unaffected."
                )

        if concurrency_guard is not None:
            old_val = getattr(settings, "ut_concurrency_guard", True)
            new_val = self._setting_enabled(concurrency_guard, True)
            if old_val != new_val:
                settings.ut_concurrency_guard = new_val
                needs_full_refresh = True
                logger.info(f"🛡ï¸  Concurrency Guard updated via configure: {new_val}")

        if strike_selection is not None:
            strike_selection = str(strike_selection or "BOTH").upper()
            if strike_selection not in {"ATM", "ITM", "BOTH"}:
                strike_selection = "BOTH"
            if getattr(settings, "option_strike_selection", "BOTH") != strike_selection:
                settings.option_strike_selection = strike_selection
                needs_full_refresh = True
                logger.info(f"Strike Selection updated: {strike_selection}")

        if grade_preference is not None:
            grade_preference = self._normalize_signal_grade_preference(grade_preference)
            if getattr(settings, "signal_grade_preference", "auto") != grade_preference:
                settings.signal_grade_preference = grade_preference
                needs_full_refresh = True
                logger.info(f"Signal Grade Preference updated: {grade_preference}")

        if ut_preset is not None:
            preset = str(ut_preset or "AGGRESSIVE").upper()
            if getattr(settings, "ut_preset", "AGGRESSIVE") != preset:
                settings.ut_preset = preset
                if hasattr(self.mtf, "apply_engine_params"):
                    self.mtf.apply_engine_params(settings.get_ut_engine_params())
                needs_full_refresh = True
                logger.info(f"UT Bot Preset updated: {preset}")

        if timeframe_entry_policy is not None:
            policy = str(timeframe_entry_policy or "PRIMARY_15").upper()
            if policy not in {"PRIMARY_15", "INCLUDE_5MIN"}:
                policy = "PRIMARY_15"
            if getattr(settings, "ut_timeframe_entry_policy", "PRIMARY_15") != policy:
                settings.ut_timeframe_entry_policy = policy
                needs_full_refresh = True
                logger.info(f"Timeframe entry policy updated: {policy}")

        if max_trades_per_index is not None:
            value = max(1, min(20, int(max_trades_per_index)))
            self.max_trades_per_index = value
            settings.max_trades_per_index = value
        if max_consecutive_losses is not None:
            value = max(1, min(10, int(max_consecutive_losses)))
            self.max_consecutive_losses = value
            settings.max_consecutive_losses = value
        if index_cooldown_minutes is not None:
            value = max(0.0, min(120.0, float(index_cooldown_minutes)))
            self.index_cooldown_minutes = value
            settings.index_cooldown_minutes = value

        if capital_total is not None:
            new_capital_total = float(capital_total)
            if new_capital_total != self.capital_total:
                self.capital_total = new_capital_total
                settings.capital_total = new_capital_total
                needs_full_refresh = True
                logger.info(f"Total Capital updated: {self.capital_total:,.0f}")

        if auto_mode is not None:
            self.auto_mode = self._strict_setting_enabled(auto_mode, False)
            logger.info(f"🔄 Auto Mode: {'ENABLED' if self.auto_mode else 'DISABLED'}")

        if inst_pref and inst_pref != self.inst_pref:
            self.inst_pref = inst_pref
            settings.inst_pref = inst_pref
            needs_full_refresh = True
            logger.info(f"🔄 Instrument Preference changed to: {self.inst_pref}")

        requested_backtest_days = (
            max(1, min(30, int(backtest_days)))
            if backtest_days is not None
            else None
        )
        if requested_backtest_days is not None and requested_backtest_days != self.backtest_days:
            self.backtest_days = requested_backtest_days
            settings.default_backtest_days = self.backtest_days
            needs_full_refresh = True
            logger.info(f"🔄 Backtest window changed to: {self.backtest_days} days")
            self._next_simulation_id() # Update sim ID to force full broadcast
            self._stamp_simulation_diagnostics()
            self._hist_candidates_loaded = False  # Force reload of session candidates

        if capital_fut is not None and float(capital_fut) != self.capital_fut:
            self.capital_fut = float(capital_fut)
            settings.capital_fut = self.capital_fut
            needs_full_refresh = True
        if capital_opt is not None and float(capital_opt) != self.capital_opt:
            self.capital_opt = float(capital_opt)
            settings.capital_opt = self.capital_opt
            needs_full_refresh = True
        if risk_fut_pct is not None and float(risk_fut_pct) != self.risk_fut_pct:
            self.risk_fut_pct = float(risk_fut_pct)
            settings.risk_fut_pct = self.risk_fut_pct
            needs_full_refresh = True
        if risk_opt_pct is not None and float(risk_opt_pct) != self.risk_opt_pct:
            self.risk_opt_pct = float(risk_opt_pct)
            settings.risk_opt_pct = self.risk_opt_pct
            needs_full_refresh = True
            
        if fut_cost is not None and fut_cost != getattr(settings, "fut_cost", 200):
            settings.fut_cost = float(fut_cost)
            self.fut_cost = float(fut_cost)
            needs_full_refresh = True
        if opt_cost is not None and opt_cost != getattr(settings, "opt_cost", 80):
            settings.opt_cost = float(opt_cost)
            self.opt_cost = float(opt_cost)
            needs_full_refresh = True

        if lots and lots != self.user_lots:
            self.user_lots.update(lots)
            needs_full_refresh = True

        if lots_fut and lots_fut != self.user_lots_fut:
            self.user_lots_fut.update(lots_fut)
            needs_full_refresh = True

        if futures_sl_pct is not None and float(futures_sl_pct) != self.futures_sl_pct:
            self.futures_sl_pct = float(futures_sl_pct)
            settings.futures_sl_pct = self.futures_sl_pct
            needs_full_refresh = True
        if options_sl_pct is not None and float(options_sl_pct) != self.options_sl_pct:
            self.options_sl_pct = float(options_sl_pct)
            settings.options_sl_pct = self.options_sl_pct
            needs_full_refresh = True

        # ——— SYNC TO TRADE MANAGER ———
        self.trades.update_risk_settings(self.futures_sl_pct, self.options_sl_pct)

        # ——— SYNC TO RISK MANAGER (Circuit Breaker) ———
        self.risk_manager.update_settings(
            max_daily_loss_pct=self.max_daily_loss_pct,
            risk_fut_pct=self.risk_fut_pct,
            risk_opt_pct=self.risk_opt_pct,
            futures_sl_pct=self.futures_sl_pct,
            options_sl_pct=self.options_sl_pct,
            max_trade_loss_abs=float(getattr(settings, "max_trade_loss_abs", 0.0) or 0.0),
            capital_fut=self.capital_fut,
            capital_opt=self.capital_opt,
            capital_total=self.capital_total,
            circuit_breaker_slippage_bps=float(
                getattr(settings, "circuit_breaker_slippage_bps", 10.0) or 10.0
            ),
        )

        if active_indices is not None and active_indices != self.active_indices:
            self.active_indices = active_indices
            settings.active_indices = active_indices
            needs_full_refresh = True
            logger.info(f"🔄 Active Indices updated: {self.active_indices}")

        if mode:
            # Mode Map: HISTORICAL, REAL
            old_mode = self.mode

            self.mode = mode
            self.trades.mode = mode
            settings.trading_mode = mode
            logger.info(f"🔄 Mode switched: {old_mode} ➔ {mode}")

            # If switching TO or FROM Historical, we need a full state purge
            if mode == "HISTORICAL" or old_mode == "HISTORICAL":
                needs_full_refresh = True
                self._hist_candidates_loaded = False
                # Replayed regimes are written into the SAME caches live management reads,
                # stamped as current. Purge on both edges: leaving HISTORICAL so live
                # trailing never trails on a past session's label, entering it so the
                # replay starts deterministically instead of from live intelligence.
                if self._setting_enabled(
                    getattr(settings, "purge_intel_cache_on_mode_change", True), True
                ):
                    self._purge_intel_regime_caches(reason=f"mode_{old_mode}_to_{mode}")

            # Leaving HISTORICAL (or entering REAL/PAPER): strip same-day ghosts so
            # live budgets / opposite-trade guards never see simulation rows.
            if str(mode).upper() != "HISTORICAL" and (
                str(old_mode).upper() == "HISTORICAL"
                or str(mode).upper() in {"REAL", "PAPER", "MANUAL"}
            ):
                self._purge_session_contamination(
                    reason=f"mode_{old_mode}_to_{mode}",
                    force_counter_rebuild=True,
                )

            # â• â• â•  HOT-SWAP BROKER â• â• â•
            if mode == "REAL":
                # â”€â”€â”€ REAL BROKER INITIALIZATION (Dynamic) â”€â”€â”€
                # If real_broker is missing, try to connect and initialize it now
                if not hasattr(self.trades, "real_broker") or not self.trades.real_broker:
                    logger.info("📡 Attempting dynamic REAL broker connection...")
                    from data.kite_auth import get_kite_auth
                    from trading.kite_broker import KiteBroker

                    # Ask the AUTHORITY, not the latch. self.data.is_connected is a plain
                    # attribute written at connect()/rebind_kite() and never revoked, so
                    # after a mid-session token death it is stale-True: the reconnect was
                    # skipped, KiteBroker was built around kite=None, and the log still
                    # said "connection successful" while every entry and every protective
                    # exit was refused terminally by _require_api.
                    kite_auth = get_kite_auth(settings)
                    if kite_auth.kite is None or not self.data.is_connected:
                        self.data.connect()
                        kite_auth = get_kite_auth(settings)

                    if kite_auth.kite is not None:
                        # account_id/instance_id are REQUIRED for the cross-process
                        # execution lease. Without account_id the broker builds no lease
                        # at all and every guard silently fails OPEN — two UT1 processes
                        # could then net each other's positions on one account, which is
                        # the exact thing the lease exists to prevent.
                        #
                        # This built a SmartApiBroker from data.smart_api until the Kite
                        # migration. That attribute is permanently None now and the
                        # account id came from angelone_client_id, so the fallback would
                        # have produced a broker that could not trade AND had no lease —
                        # failing open on the one guard that must never fail open.
                        new_real_broker = KiteBroker(
                            kite=kite_auth.kite,
                            auth=kite_auth,
                            account_id=str(getattr(settings, "kite_user_id", "") or "").strip(),
                            instance_id=f"UT1:{getattr(settings, 'dashboard_port', '')}",
                        )
                        self.trades.real_broker = new_real_broker
                        self.data.on_kite_reauth = new_real_broker.replace_api
                        logger.info("âœ… Dynamic Kite broker connection successful")
                    else:
                        # No broker is constructed here on purpose. A KiteBroker around
                        # kite=None accepts orders and refuses every one of them at
                        # _require_api, which reads as a working REAL mode.
                        logger.error("â Œ CRITICAL: No Kite session for REAL mode — log in at /api/kite_login")

                if hasattr(self.trades, "real_broker") and self.trades.real_broker:
                    # Claim the cross-process account lease as part of entering REAL.
                    # It used to be acquired only in main.py at startup, and only when
                    # trading_mode was ALREADY REAL — so every session that reached REAL
                    # via this switch (which is the normal premarket path) ran with an
                    # unclaimed lease and had all its orders refused at execution time.
                    # ESTABLISHED, then ACQUIRED — main.py's REAL startup requires both
                    # and this path required only the second. acquire_execution_lease
                    # returns True when there is no lease to take (a broker built with a
                    # blank kite_user_id has _execution_lease None), which is deliberate
                    # so the fixtures in 50-odd test files keep working. The consequence
                    # here was the opposite of the intent: an account-less broker sailed
                    # through the only check and armed REAL with no lease at all. This
                    # switch IS the normal premarket path, so it failed OPEN on exactly
                    # the route most sessions take.
                    established = getattr(
                        self.trades.real_broker, "execution_lease_established", None
                    )
                    if callable(established) and not established():
                        reason = (
                            "REAL refused: broker has no account execution lease "
                            "(kite_user_id is blank)"
                        )
                        logger.critical(f"❌ {reason}")
                        self._last_configure_block_reason = reason
                        self.mode = "HISTORICAL"  # fail closed, never trade unprotected
                        self.trades.broker = getattr(self.trades, "mock_broker", self.trades.broker)
                        self.trades.mode = self.mode
                        if self.on_notification:
                            self.on_notification(reason, "error")
                        return False
                    acquire = getattr(self.trades.real_broker, "acquire_execution_lease", None)
                    if callable(acquire) and not acquire():
                        reason = ""
                        reader = getattr(
                            self.trades.real_broker, "execution_lease_block_reason", None
                        )
                        if callable(reader):
                            reason = reader()
                        reason = reason or "REAL broker account is owned by another UT1 process"
                        logger.critical(f"â Œ REAL mode refused: {reason}")
                        self._last_configure_block_reason = reason
                        self.mode = "HISTORICAL"  # fail closed, never trade unprotected
                        self.trades.broker = getattr(self.trades, "mock_broker", self.trades.broker)
                        self.trades.mode = self.mode
                        if self.on_notification:
                            self.on_notification(f"REAL mode refused: {reason}", "error")
                        return False
                    self.trades.broker = self.trades.real_broker
                    logger.info("📡 Broker Hot-Swapped to: LIVE EXECUTION (Zerodha Kite)")
                else:
                    logger.error("❌ CRITICAL: Attempted REAL mode without Broker connection!")
                    self._last_configure_block_reason = "Kite broker not connected"
                    self.mode = "HISTORICAL" # Safety fallback
                    self.trades.broker = getattr(self.trades, "mock_broker", self.trades.broker)
                    # Sync trade manager mode back to fallback
                    self.trades.mode = self.mode
                    if self.on_notification:
                        self.on_notification("Failed to switch to REAL mode! Kite not connected.", "error")
            else:
                # Historical Mode: Signals analysed from Real Historical Data
                self.trades.broker = getattr(self.trades, "mock_broker", self.trades.broker)
                logger.info(f"📡 Broker Mode: {mode} (Signal-Based Analysis)")

            self.log_event(f"System Mode: {mode}", "system")

        if reset:
            # User explicitly requested a full reset of P&L and cache
            if self.trades.reset_pnl() is False:
                return False
            self.perf.reset()
            self._cached_results.clear()
            getattr(self, "_signal_preflight_cache", {}).clear()
            getattr(self, "_intel_cache", {}).clear()
            getattr(self, "_intel_cache_time", {}).clear()
            getattr(self, "_timeframe_regimes", {}).clear()
            getattr(self, "latest_regimes", {}).clear()
            for attr in list(self.__dict__.keys()):
                if attr.startswith("chart_cache_"):
                    delattr(self, attr)
            if hasattr(self, "_cached_hist_signals"):
                delattr(self, "_cached_hist_signals")
            if hasattr(self, "_cached_hist_closed_count"):
                delattr(self, "_cached_hist_closed_count")

            self._next_simulation_id()
            self._stamp_simulation_diagnostics()

            if hasattr(self.mtf, "_result_cache"):
                self.mtf._result_cache.clear()
            if hasattr(self.mtf, "_data_hash"):
                self.mtf._data_hash.clear()
            if hasattr(self, "_session_trade_candidates"):
                self._session_trade_candidates.clear()
                self._persist_session_trade_candidates()
            if hasattr(self, "_latest_trade_candidates"):
                self._latest_trade_candidates.clear()
            if hasattr(self, "_latest_exit_candidates"):
                self._latest_exit_candidates.clear()
            if hasattr(self, "_last_signal_time"):
                self._last_signal_time.clear()
            if hasattr(self, "_last_signal_identity"):
                self._last_signal_identity.clear()
            if hasattr(self, "_last_live_signal_candle_time"):
                self._last_live_signal_candle_time.clear()
            if hasattr(self, "_pending_live_signals"):
                self._pending_live_signals.clear()
            if hasattr(self, "_post_repaint_recheck"):
                self._post_repaint_recheck.clear()

            # Reset scan count to trigger initial logic in next cycle
            self.scan_count = 0
            if self.mode == "REAL":
                self.latest_results = {
                    **(self.latest_results or {}),
                    "mode": self.mode,
                    "config": self.get_broadcast_config(),
                    "trades": self._build_dashboard_trade_payload(),
                    "timestamp": datetime.now(IST).isoformat(),
                }
                self._update_dashboard_cache(self.latest_results)
            else:
                self._historical_rebuild_pending = True
                self._set_recalculation_status("queued", "reset")
                self.queue_full_recalculation("reset")
        elif needs_full_refresh:
            # Switch modes or settings refresh - DO NOT clear real closed/open trades of today!
            # Purge ghost / H_ / EOD_ / hist-provenance simulation rows (T... ghosts
            # used to survive and inflate daily trade counters in REAL).
            self._purge_session_contamination(
                reason="configure_full_refresh",
                force_counter_rebuild=True,
            )
            self.perf.reset()
            self._cached_results.clear()
            getattr(self, "_signal_preflight_cache", {}).clear()
            getattr(self, "_intel_cache", {}).clear()
            getattr(self, "_intel_cache_time", {}).clear()
            getattr(self, "_timeframe_regimes", {}).clear()
            getattr(self, "latest_regimes", {}).clear()
            for attr in list(self.__dict__.keys()):
                if attr.startswith("chart_cache_"):
                    delattr(self, attr)
            if hasattr(self, "_cached_hist_signals"):
                delattr(self, "_cached_hist_signals")
            if hasattr(self, "_cached_hist_closed_count"):
                delattr(self, "_cached_hist_closed_count")

            self._next_simulation_id()
            self._stamp_simulation_diagnostics()

            if hasattr(self.mtf, "_result_cache"):
                self.mtf._result_cache.clear()
            if hasattr(self.mtf, "_data_hash"):
                self.mtf._data_hash.clear()
            
            # DO NOT clear self._session_trade_candidates, as it holds today's live/paper session signals.
            # Only clear the volatile latest display caches
            if hasattr(self, "_latest_trade_candidates"):
                self._latest_trade_candidates.clear()
            if hasattr(self, "_latest_exit_candidates"):
                self._latest_exit_candidates.clear()
            if hasattr(self, "_last_signal_time"):
                self._last_signal_time.clear()
            if hasattr(self, "_last_signal_identity"):
                self._last_signal_identity.clear()
            if hasattr(self, "_last_live_signal_candle_time"):
                self._last_live_signal_candle_time.clear()
            if hasattr(self, "_pending_live_signals"):
                self._pending_live_signals.clear()
            if hasattr(self, "_post_repaint_recheck"):
                self._post_repaint_recheck.clear()

            # Reload session candidates from the correct path for the new mode/settings
            self._load_session_trade_candidates()

            self.scan_count = 0
            if self.mode == "REAL":
                self.latest_results = {
                    **(self.latest_results or {}),
                    "mode": self.mode,
                    "config": self.get_broadcast_config(),
                    "trades": self._build_dashboard_trade_payload(),
                    "timestamp": datetime.now(IST).isoformat(),
                }
                self._update_dashboard_cache(self.latest_results)
            else:
                self._historical_rebuild_pending = True
                self._set_recalculation_status("queued", "settings-refresh")
                self.queue_full_recalculation("settings-refresh")

        self._publish_config_snapshot()

        # Persist UI/operator edits off the hot path; runtime-only workers can opt out
        # so the app still starts in HISTORICAL and arms REAL/manual at 09:00.
        if persist_settings:
            schedule_settings_save(settings)

        return True





















    async def perform_system_recalibration(self):
        """
        Recalibrates the system by releasing locks, resetting HFT semaphores,
        clearing calculation/UI caches, and forcing a fresh market data sync,
        while preserving all live/historical trades and session data.
        """
        logger.info("🔄 SYSTEM RECALIBRATION: Initializing 1-second system refresh...")
        
        # 1. Release stuck locks
        self._calculation_lock = False
        self.is_calculating = False
        if hasattr(self, "_ltp_semaphore"):
            self._ltp_semaphore = asyncio.Semaphore(5)

        # 2. Clear chart serialization, math, and engine caches
        self._cached_results.clear()
        
        # Clear specific chart cache attributes
        for attr in list(self.__dict__.keys()):
            if attr.startswith("chart_cache_"):
                delattr(self, attr)

        if hasattr(self.mtf, "_result_cache"):
            self.mtf._result_cache.clear()
        if hasattr(self.mtf, "_data_hash"):
            self.mtf._data_hash.clear()

        # 3. Force re-fetching data without clearing trades or P&L
        all_indices = self.config.get("indices", {})
        indices = {k: v for k, v in all_indices.items() if k in self.active_indices}
        
        # Reset fetch timestamps to force data retrieval even in offline markets
        self._last_data_fetch.clear()
        
        # Fetch fresh data
        try:
            await self._fetch_all_data(indices, force=True)
        except Exception as e:
            logger.error(f"Error fetching data during recalibration: {e}")
            
        # 4. Trigger scan cycle calculation update immediately
        self._next_simulation_id() # Signal UI of refresh
        logger.success("✅ SYSTEM RECALIBRATION: System refreshed and recalibrated successfully!")

    async def _background_initial_setup(self, indices: Dict):
        """Heavy initialization run in background to prevent event loop freeze"""
        was_warmup = getattr(self, "is_warmup", False)
        self.is_warmup = True
        try:
            startup_now = datetime.now(IST)
            run_live_startup_refresh = self._is_real_mode_startup_refresh_window(startup_now)

            # 1. Build the selected chart first, then hydrate the rest in the
            # background. This avoids startup stalls where 9 history calls block
            # the dashboard before the user can see anything useful.
            active_inst = getattr(self, "active_chart_instrument", "NIFTY")
            active_tf = getattr(self, "active_chart_tf", "5min")
            active_cfg = indices.get(active_inst)
            # User-selected 2-30 day windows are applied by the serialized
            # recalculation queue after this fast one-day hydration.
            startup_days = 1
            if active_cfg:
                await self._fetch_all_data(
                    {active_inst: active_cfg},
                    force=True,
                    timeframes=[active_tf],
                    days_back_override=startup_days,
                )
            if run_live_startup_refresh:
                await self._run_startup_market_refresh(indices, startup_now)
            else:
                await self._fetch_all_data(
                    indices,
                    force=False,
                    days_back_override=startup_days,
                )

            # Build or load one process-restart bundle for hundreds of option
            # contracts. The selected chart is already hydrated above, so this
            # runs off the event loop without delaying first dashboard paint.
            loop = asyncio.get_running_loop()
            self._option_history_bundle_status = await loop.run_in_executor(
                None,
                self.signal_processor._option_history_store.ensure_bundle,
            )
            logger.info(
                "Option history bundle ready: "
                f"{self._option_history_bundle_status}"
            )

            # 2. SYNC INTELLIGENCE HISTORY (Zero-Skip Memory)
            if self.mode == "REAL" and (run_live_startup_refresh or self.data.is_market_open()):
                logger.info("Live market startup: session refresh handled current intelligence; skipping deep historical replay to keep REAL mode responsive.")
            else:
                await self._sync_intelligence_history(indices)

            # 2b. PRE-FETCH PREVIOUS CLOSES (Latency Fix)
            logger.info("📡 Pre-fetching previous closes for latency optimization...")
            for name in indices:
                self.data.get_previous_close(name)
            self.log_event("📡 Market Data Baselines (Prev Closes) Synchronized", "data")

            # 3. If we are in a live mode after market hours, re-simulate TODAY
            # This populates the Results table with today's performance if state was empty
            if (
                self.mode == "REAL"
                and not self.data.is_market_open()
                and not self.trades.open_trades
                and not self.trades.closed_trades
            ):
                logger.info("🔥 WARM STARTUP: Re-simulating today's activity for dashboard population...")
                # Temporarily enable calculation to backfill
                old_power = self.system_power
                self.system_power = "ON"
                self.is_warmup = True

                # Process all instruments once to trigger signal/trade generation from history
                tasks = [self._process_instrument_async(name, cfg) for name, cfg in indices.items()]
                trade_signals = await asyncio.gather(*tasks)

                self.system_power = old_power
                self.is_warmup = False
                self.log_event("🔥 Warm Startup Complete: All index histories restored", "success")
                logger.info("🔥 WARM STARTUP: All index histories restored.")

        except Exception as e:
            logger.error(f"â Œ Error in background initial setup: {e}")
            self.log_event(f"â Œ Error in background initial setup: {e}", "error")

        finally:
            self._initial_setup_completed = True
            # Initial setup runs exactly once at startup; after it completes the
            # system is live and must NOT stay in warmup. Restoring ``was_warmup``
            # here was buggy: scan_count==1 pre-sets is_warmup=True before this
            # task starts, so the restore left it stuck True for the whole session
            # and silently suppressed every "trade" event from the live tape.
            self.is_warmup = False
            self._initial_setup_task = None

    def _schedule_initial_setup(self, indices: Dict) -> bool:
        """Schedule startup hydration once, even when settings reset scan_count."""
        if self._initial_setup_completed:
            return False
        task = self._initial_setup_task
        if task is not None and not task.done():
            return False
        self._initial_setup_task = asyncio.create_task(self._background_initial_setup(indices))
        return True

    def _is_trading_day(self, now_ist: datetime) -> bool:
        """Return True for Mon-Fri NSE trading days, excluding configured holidays."""
        try:
            if hasattr(self.data, "is_special_trading_session") and self.data.is_special_trading_session(now_ist):
                return True
        except Exception:
            pass
        if now_ist.weekday() >= 5:
            return False
        try:
            if hasattr(self.data, "is_market_holiday") and self.data.is_market_holiday(now_ist):
                return False
        except Exception:
            pass
        return True

    def _morning_refresh_is_complete_for_day(self, session_day: str) -> bool:
        return getattr(self, "_morning_refresh_last_date", None) == session_day

    def _live_open_catchup_due(self, session_day: str, now_ist: datetime) -> bool:
        """True when a capped/incomplete premarket warm still owes one live-open pass.

        Separate from _morning_refresh_is_complete_for_day on purpose: that flag bounds
        the retry loop and must keep saying "stop retrying", while this answers the
        different question of whether the day was actually warmed. Latched by
        _morning_refresh_catchup_done_date so it can only ever answer True once a day.
        """
        if getattr(self, "_morning_refresh_catchup_done_date", None) == session_day:
            return False
        summary = self._morning_refresh_summary_for_day(session_day)
        if not summary or summary.get("complete"):
            return False
        if not self._setting_enabled(
            getattr(get_settings(), "morning_refresh_catchup_at_live_open", True), True
        ):
            return False
        try:
            return now_ist.time() >= self._clock_setting("real_mode_live_start", "09:15:00")
        except Exception:
            return False

    def _morning_refresh_summary_for_day(self, session_day: str) -> Dict[str, Any]:
        summary = getattr(self, "_morning_refresh_summary", None) or {}
        if str(summary.get("session_day") or "") != str(session_day):
            return {}
        return dict(summary)

    def _evaluate_morning_refresh_quality(
        self,
        summary: Dict[str, Any],
        n_indices: int,
    ) -> Tuple[bool, List[str]]:
        """Return (complete, missing_keys) against configured thresholds."""
        settings = get_settings()
        n_indices = max(1, int(n_indices or 1))
        missing: List[str] = []

        if self._setting_enabled(getattr(settings, "morning_refresh_require_history", True), True):
            if not bool(summary.get("history")):
                missing.append("history")
        if self._setting_enabled(getattr(settings, "morning_refresh_require_expiry", True), True):
            if not bool(summary.get("expiry")):
                missing.append("expiry")
        if self._setting_enabled(getattr(settings, "morning_refresh_require_all_quotes", True), True):
            if int(summary.get("index_quotes") or 0) < n_indices:
                missing.append("quotes")
        if self._setting_enabled(getattr(settings, "morning_refresh_require_all_chains", True), True):
            if int(summary.get("chains") or 0) < n_indices:
                missing.append("chains")
        if self._setting_enabled(getattr(settings, "morning_refresh_require_vix", False), False):
            if not bool(summary.get("vix")):
                missing.append("vix")

        # Per-index gaps (for partial re-warm)
        per_idx = summary.get("indices") or {}
        if isinstance(per_idx, dict):
            for name, row in per_idx.items():
                if not isinstance(row, dict):
                    continue
                if self._setting_enabled(getattr(settings, "morning_refresh_require_all_quotes", True), True):
                    if not row.get("quote"):
                        missing.append(f"quote:{name}")
                if self._setting_enabled(getattr(settings, "morning_refresh_require_all_chains", True), True):
                    if not row.get("chain"):
                        missing.append(f"chain:{name}")

        # De-dupe while preserving order
        seen = set()
        ordered = []
        for key in missing:
            if key not in seen:
                seen.add(key)
                ordered.append(key)
        return (len(ordered) == 0), ordered

    def _schedule_morning_market_refresh(
        self,
        indices: Dict,
        now_ist: datetime,
        *,
        reason: str = "scheduled",
        force_full: bool = False,
    ) -> None:
        """Launch market-session refresh (full or partial missing-key re-warm)."""
        session_day = now_ist.date().isoformat()
        if getattr(self, "_morning_refresh_inflight", False):
            logger.info("Morning market refresh already running; skipping duplicate schedule.")
            return
        if self._morning_refresh_is_complete_for_day(session_day) and not force_full:
            logger.info("Morning market refresh already completed for this session.")
            return

        attempts = getattr(self, "_morning_refresh_attempts", None)
        if not isinstance(attempts, dict):
            self._morning_refresh_attempts = {}
            attempts = self._morning_refresh_attempts
        max_attempts = max(1, int(getattr(get_settings(), "morning_refresh_max_attempts", 3) or 3))
        used = int(attempts.get(session_day, 0) or 0)
        if used >= max_attempts and not force_full:
            logger.warning(
                f"Morning refresh attempt cap ({max_attempts}) reached for {session_day}; "
                "accepting incomplete warm state for this process day."
            )
            # Stop blocking scans forever after max attempts
            self._morning_refresh_last_date = session_day
            summary = self._morning_refresh_summary_for_day(session_day)
            summary["complete"] = False
            summary["accepted_incomplete"] = True
            self._morning_refresh_summary = summary
            return

        self._morning_refresh_inflight = True
        try:
            asyncio.create_task(
                self._morning_market_refresh(
                    indices,
                    session_day,
                    force_full=force_full,
                    reason=reason,
                )
            )
        except RuntimeError:
            self._morning_refresh_inflight = False
            logger.error("Morning market refresh could not be scheduled; no running event loop.")

    @staticmethod
    def _clock_setting(setting_name: str, default: str) -> dtime:
        label = str(getattr(get_settings(), setting_name, default) or default).strip()
        for fmt in ("%H:%M:%S", "%H:%M"):
            try:
                return datetime.strptime(label, fmt).time()
            except ValueError:
                continue
        return datetime.strptime(default, "%H:%M:%S" if len(default.split(":")) == 3 else "%H:%M").time()

    def _is_real_mode_premarket_arm_window(self, now_ist: datetime) -> bool:
        """REAL-mode prep window: connect/warm data before regular market open."""
        current = now_ist.time()
        start = self._clock_setting("real_mode_premarket_arm_start", "09:00:00")
        live_start = self._clock_setting("real_mode_live_start", "09:15:00")
        return start <= current < live_start

    def _dashboard_quote_session(
        self,
        market_quote: Dict[str, Any],
        now_ist: Optional[datetime] = None,
    ) -> Tuple[str, str, bool, bool]:
        """Normalize index-card quote session labels for the configured pre-open.

        Broker/provider session labels can still say CLOSED while pre-open ticks
        are flowing. The scanner owns the configured 09:00-09:15 prep window, so
        dashboard cards should use that schedule for display metadata while the
        actual LTP/source remains broker-provided.
        """
        now_ist = now_ist or datetime.now(IST)
        raw_session = str(
            (market_quote or {}).get("session")
            or (market_quote or {}).get("quote_label")
            or "unknown"
        ).upper()
        raw_label = str(
            (market_quote or {}).get("quote_label")
            or (market_quote or {}).get("session")
            or raw_session
        ).upper()
        is_preopen = bool((market_quote or {}).get("is_preopen", False))
        is_settlement = bool((market_quote or {}).get("preopen_settlement", False))

        try:
            if (
                getattr(self, "mode", "") == "REAL"
                and self._is_trading_day(now_ist)
                and self._is_real_mode_premarket_arm_window(now_ist)
            ):
                raw_label = raw_session = "PRE-OPEN"
                is_preopen = True
                settle_end = self._clock_setting("real_mode_premarket_settle_end", "09:08:00")
                is_settlement = now_ist.time() <= settle_end
        except Exception:
            pass

        return raw_label, raw_session, is_preopen, is_settlement

    def _is_real_mode_startup_refresh_window(self, now_ist: datetime) -> bool:
        """Startup catch-up window for REAL mode before scanning/trading resumes."""
        if getattr(self, "mode", "") != "REAL":
            return False
        if not self._is_trading_day(now_ist):
            return False
        if self._is_real_mode_premarket_arm_window(now_ist):
            return True
        try:
            is_live_market = bool(self.data.is_market_open(now_ist))
        except TypeError:
            is_live_market = bool(self.data.is_market_open())
        except Exception:
            is_live_market = False
        if not is_live_market:
            return False
        restart_end = self._clock_setting(
            "real_mode_mid_session_restart_refresh_end",
            "15:00:00",
        )
        return now_ist.time() <= restart_end

    async def _run_startup_market_refresh(self, indices: Dict, now_ist: datetime) -> bool:
        """Run the daily market warmup inline during REAL startup/restart."""
        session_day = now_ist.date().isoformat()
        if self._morning_refresh_is_complete_for_day(session_day):
            return False
        if getattr(self, "_morning_refresh_inflight", False):
            return True
        self._morning_refresh_inflight = True
        self.log_event(
            "Live startup refresh: rebuilding missing candles, feeds, expiry, chains, and intel before scanning resumes.",
            "data",
        )
        await self._morning_market_refresh(
            indices,
            session_day,
            force_full=True,
            reason="startup",
        )
        return True

    def _ensure_market_session_refresh(self, indices: Dict, now_ist: datetime) -> bool:
        """Ensure live-session data is warmed before signal processing.

        Returns True while the scanner should hold normal signal work (refresh
        running or still incomplete in prep/catch-up windows).
        """
        session_day = now_ist.date().isoformat()
        if self._morning_refresh_is_complete_for_day(session_day):
            # An "accepted incomplete" day is NOT a warmed day. The attempt cap sets
            # _morning_refresh_last_date purely to stop blocking scans forever, but
            # completeness is also what this early return tests, so the 09:15 catch-up
            # below became unreachable for exactly the days that needed it most:
            # pre-open the option chains are empty, so with require_all_chains every
            # attempt between 09:00 and 09:15 fails and burns the budget.
            #
            # Handled here rather than by loosening _morning_refresh_is_complete_for_day:
            # that would let the flow fall through, re-schedule, re-hit the cap and return
            # True on every scan — holding signal work for the session, which is the
            # failure the cap was written to prevent. Completeness must keep gating the
            # retry loop, so this grants exactly ONE pass and re-arms immediately: the
            # latch is set BEFORE scheduling, so it cannot loop even if the pass fails.
            if self._live_open_catchup_due(session_day, now_ist):
                self._morning_refresh_catchup_done_date = session_day
                attempts = getattr(self, "_morning_refresh_attempts", None)
                if isinstance(attempts, dict):
                    attempts[session_day] = 0
                self.log_event(
                    "Live-open catch-up refresh: re-warming missing morning keys after "
                    "capped premarket pass.",
                    "data",
                )
                self._schedule_morning_market_refresh(
                    indices,
                    now_ist,
                    reason="live_open_catchup",
                    force_full=False,
                )
            # Non-blocking, matching the live_incomplete_partial branch below: the day
            # already holds partial data, and holding signal work at the open — the one
            # moment it matters most — to wait on a provider that has already failed its
            # premarket attempts is the worse trade. The re-warm lands in the background.
            return False
        if getattr(self, "_morning_refresh_inflight", False):
            return True
        if not self._is_trading_day(now_ist):
            return False

        summary = self._morning_refresh_summary_for_day(session_day)
        incomplete = bool(summary) and not bool(summary.get("complete"))
        live_start = self._clock_setting("real_mode_live_start", "09:15:00")
        catchup_enabled = self._setting_enabled(
            getattr(get_settings(), "morning_refresh_catchup_at_live_open", True), True
        )
        catchup_done = getattr(self, "_morning_refresh_catchup_done_date", None) == session_day

        # 09:15+ catch-up: one forced partial/full re-warm if still incomplete
        if (
            incomplete
            and catchup_enabled
            and not catchup_done
            and now_ist.time() >= live_start
        ):
            self._morning_refresh_catchup_done_date = session_day
            self.log_event(
                "Live-open catch-up refresh: re-warming missing morning keys after incomplete premarket pass.",
                "data",
            )
            self._schedule_morning_market_refresh(
                indices,
                now_ist,
                reason="live_open_catchup",
                force_full=False,
            )
            return True

        if self._is_real_mode_premarket_arm_window(now_ist):
            settle_end = self._clock_setting("real_mode_premarket_settle_end", "09:08:00")
            refresh_end = self._clock_setting("real_mode_premarket_refresh_end", "09:14:30")
            if now_ist.time() <= settle_end:
                phase = "pre-open settlement"
            elif now_ist.time() <= refresh_end:
                phase = "pre-open analysis"
            else:
                phase = "market-open handoff"
            self.log_event(
                f"{phase.title()} refresh window active; warming live data before trading starts.",
                "data",
            )
            self._schedule_morning_market_refresh(
                indices,
                now_ist,
                reason=phase,
                force_full=not incomplete,
            )
            return True

        try:
            is_live_market = bool(self.data.is_market_open(now_ist))
        except TypeError:
            is_live_market = bool(self.data.is_market_open())
        except Exception:
            is_live_market = False

        if is_live_market:
            # Incomplete day mid-session: partial re-warm missing keys only.
            # NON-BLOCKING (2026-07-10): the day already has partial data — keep
            # scanning while the re-warm runs in the background instead of
            # holding signal work for every retry of a flaky provider.
            if incomplete:
                if not getattr(self, "_morning_refresh_inflight", False):
                    self.log_event(
                        "Market open with incomplete morning warm; re-warming missing keys in background.",
                        "data",
                    )
                    self._schedule_morning_market_refresh(
                        indices,
                        now_ist,
                        reason="live_incomplete_partial",
                        force_full=False,
                    )
                return False
            self.log_event("Market session warmup required before live scanning; starting refresh.", "data")
            self._schedule_morning_market_refresh(
                indices,
                now_ist,
                reason="live_session",
                force_full=True,
            )
            return True

        return False

    async def _morning_market_refresh(
        self,
        indices: Dict,
        session_day: str,
        *,
        force_full: bool = False,
        reason: str = "scheduled",
    ) -> None:
        """Warm market-critical data; complete only if quality thresholds pass.

        Incomplete runs store missing_keys and allow partial re-warm / 09:15 catch-up.
        """
        started = time.time()
        attempts = getattr(self, "_morning_refresh_attempts", None)
        if not isinstance(attempts, dict):
            self._morning_refresh_attempts = {}
            attempts = self._morning_refresh_attempts
        attempts[session_day] = int(attempts.get(session_day, 0) or 0) + 1
        attempt_n = attempts[session_day]

        prior = self._morning_refresh_summary_for_day(session_day)
        prior_missing = set(prior.get("missing_keys") or [])
        partial = (
            (not force_full)
            and bool(prior)
            and not bool(prior.get("complete"))
            and bool(prior_missing)
        )

        summary: Dict[str, Any] = {
            "session_day": session_day,
            "attempt": attempt_n,
            "reason": reason,
            "partial": partial,
            "index_quotes": 0,
            "vix": bool(prior.get("vix")) if partial else False,
            "futures": int(prior.get("futures") or 0) if partial else 0,
            "option_tokens": int(prior.get("option_tokens") or 0) if partial else 0,
            "option_ltp": int(prior.get("option_ltp") or 0) if partial else 0,
            "chains": 0,
            "intel": 0,
            "history": bool(prior.get("history")) if partial else False,
            "expiry": bool(prior.get("expiry")) if partial else False,
            "indices": dict(prior.get("indices") or {}) if partial else {},
            "missing_keys": [],
            "complete": False,
        }
        # Normalize per-index rows
        if not isinstance(summary["indices"], dict):
            summary["indices"] = {}

        try:
            active_indices = {k: v for k, v in (indices or {}).items() if k in self.active_indices}
            if not active_indices:
                active_indices = {
                    k: v for k, v in self.config.get("indices", {}).items() if k in self.active_indices
                }
            n_active = len(active_indices) or 1
            for name in active_indices:
                summary["indices"].setdefault(
                    name, {"quote": False, "chain": False, "intel": False, "fut": False}
                )

            mode_label = "partial missing-key" if partial else "full"
            self.log_event(
                f"Morning refresh ({mode_label}, attempt {attempt_n}, reason={reason}): "
                "warming index, VIX, futures, options, expiry, and intel data",
                "data",
            )

            need_expiry = (not partial) or ("expiry" in prior_missing)
            need_history = (not partial) or ("history" in prior_missing)
            need_vix = (not partial) or ("vix" in prior_missing) or any(
                k.startswith("quote:") for k in prior_missing
            )
            # Per-index work set
            if partial:
                names_need_quote = {
                    k.split(":", 1)[1]
                    for k in prior_missing
                    if k.startswith("quote:")
                }
                names_need_chain = {
                    k.split(":", 1)[1]
                    for k in prior_missing
                    if k.startswith("chain:")
                }
                # Prefer per-index missing keys. Expand to all only when the
                # aggregate failed without any per-index detail recorded.
                if "quotes" in prior_missing and not names_need_quote:
                    names_need_quote |= set(active_indices.keys())
                if "chains" in prior_missing and not names_need_chain:
                    names_need_chain |= set(active_indices.keys())
                # Always re-check any index that failed either
                names_to_warm = names_need_quote | names_need_chain
                if not names_to_warm and (need_history or need_expiry or need_vix):
                    names_to_warm = set()  # globals only
                elif not names_to_warm:
                    names_to_warm = set(active_indices.keys())
            else:
                names_need_quote = set(active_indices.keys())
                names_need_chain = set(active_indices.keys())
                names_to_warm = set(active_indices.keys())

            if need_expiry:
                try:
                    self.market_info = self.expiry.pre_market_check()
                    summary["expiry"] = True
                except Exception as exc:
                    summary["expiry"] = False
                    logger.error(f"Morning refresh expiry/rollover check failed: {exc}")

            if need_history:
                try:
                    await self._fetch_all_data(
                        active_indices, force=True, timeframes=["1min", "5min", "15min"]
                    )
                    self._last_full_history_refresh = time.time()
                    summary["history"] = True
                except Exception as exc:
                    summary["history"] = False
                    logger.error(f"Morning refresh history fetch failed: {exc}")

            loop = asyncio.get_event_loop()
            session_date = datetime.fromisoformat(session_day).date()
            parallelism = max(
                1,
                int(getattr(get_settings(), "morning_refresh_parallelism", 3) or 3),
            )
            refresh_semaphore = asyncio.Semaphore(parallelism)

            async def bounded_to_thread(func, *args):
                async with refresh_semaphore:
                    return await asyncio.to_thread(func, *args)

            async def prewarm_index(name, cfg, want_quote: bool, want_chain: bool):
                quote = None
                previous_close = None
                chain_result = None
                tasks = []
                keys = []
                if want_quote:
                    tasks.append(bounded_to_thread(self.data.get_index_quote, name))
                    keys.append("quote")
                    tasks.append(bounded_to_thread(self.data.get_previous_close, name))
                    keys.append("previous_close")
                if want_chain:
                    tasks.append(
                        bounded_to_thread(
                            self._get_option_chain_cached,
                            name,
                            cfg,
                            True,
                            True,
                        )
                    )
                    keys.append("chain_result")
                if not tasks:
                    return name, {}
                results = await asyncio.gather(*tasks, return_exceptions=True)
                out = {}
                for key, val in zip(keys, results):
                    out[key] = val
                return name, out

            warm_jobs = []
            for name, cfg in active_indices.items():
                if name not in names_to_warm and partial:
                    continue
                warm_jobs.append(
                    prewarm_index(
                        name,
                        cfg,
                        want_quote=(name in names_need_quote) or not partial,
                        want_chain=(name in names_need_chain) or not partial,
                    )
                )
            prewarmed = {}
            if warm_jobs:
                warmed = await asyncio.gather(*warm_jobs)
                prewarmed = dict(warmed)

            vix_task = None
            if need_vix:
                vix_task = asyncio.create_task(
                    asyncio.to_thread(self.data.get_ltp, "NSE", "INDIAVIX", "99926017")
                )

            for name, cfg in active_indices.items():
                row = summary["indices"].setdefault(
                    name, {"quote": False, "chain": False, "intel": False, "fut": False}
                )
                # Preserve prior successes on partial runs
                if partial and name not in names_to_warm:
                    if row.get("quote"):
                        summary["index_quotes"] += 1
                    if row.get("chain"):
                        summary["chains"] += 1
                    if row.get("intel"):
                        summary["intel"] += 1
                    continue

                token = cfg.get("token", "")
                exchange = cfg.get("exchange", "NSE")
                spot = 0.0
                do_quote = (name in names_need_quote) or not partial
                do_chain = (name in names_need_chain) or not partial

                if do_quote:
                    row["quote"] = False
                    try:
                        quote = prewarmed.get(name, {}).get("quote")
                        if isinstance(quote, Exception):
                            raise quote
                        if quote is not None:
                            spot = float((quote or {}).get("ltp", 0.0) or 0.0)
                            if spot > 0:
                                self.candles.update_latest_price(name, spot)
                                row["quote"] = True
                    except Exception as exc:
                        logger.debug(f"Morning refresh index quote failed for {name}: {exc}")

                    if spot <= 0 and token:
                        try:
                            spot = await loop.run_in_executor(
                                None,
                                lambda t=token, n=name, e=exchange: self.data.get_latest_price_by_token(t, n, e),
                            )
                            if spot and spot > 0:
                                self.candles.update_latest_price(name, float(spot))
                                spot = float(spot)
                                row["quote"] = True
                        except Exception as exc:
                            logger.debug(f"Morning refresh fallback index LTP failed for {name}: {exc}")

                    if row.get("quote"):
                        summary["index_quotes"] += 1

                    try:
                        previous_close = prewarmed.get(name, {}).get("previous_close")
                        if isinstance(previous_close, Exception):
                            raise previous_close
                    except Exception as exc:
                        logger.debug(f"Morning refresh previous close failed for {name}: {exc}")

                else:
                    if row.get("quote"):
                        summary["index_quotes"] += 1
                    spot = float(self.candles.get_latest_price(name) or 0.0)

                info = (self.market_info or {}).get(name, {}) if isinstance(self.market_info, dict) else {}
                fut_symbol = info.get("current_fut") or ""
                fut_token = info.get("current_fut_token") or ""
                if fut_symbol and fut_token and (do_quote or not partial):
                    fut_exchange = "BFO" if name == "SENSEX" else "NFO"
                    try:
                        fut_ltp = await loop.run_in_executor(
                            None,
                            lambda e=fut_exchange, s=fut_symbol, t=fut_token: self.data.get_ltp(e, s, t),
                        )
                        if fut_ltp and fut_ltp > 0:
                            summary["futures"] += 1
                            row["fut"] = True
                    except Exception as exc:
                        logger.debug(f"Morning refresh futures LTP failed for {name}: {exc}")

                if spot and spot > 0 and (do_quote or do_chain or not partial):
                    strike_interval = cfg.get("strike_interval", 50)
                    atm = round(float(spot) / strike_interval) * strike_interval
                    opt_exchange = cfg.get("option_exchange", "BFO" if name == "SENSEX" else "NFO")
                    for opt_type in ("CE", "PE"):
                        try:
                            opt_info = self.data.get_option_token(name, atm, opt_type, session_date)
                            if not opt_info:
                                opt_info = self.data.get_option_token(name, atm, opt_type)
                            if opt_info:
                                summary["option_tokens"] += 1
                                opt_ltp = await loop.run_in_executor(
                                    None,
                                    lambda e=opt_exchange, s=opt_info.get("symbol", ""), t=opt_info.get("token", ""): self.data.get_ltp(e, s, t),
                                )
                                if opt_ltp and opt_ltp > 0:
                                    token_key = str(opt_info.get("token", ""))
                                    self._premium_cache[token_key] = {"price": float(opt_ltp), "time": time.time()}
                                    self._premium_cache[f"{name}-{opt_type}"] = {
                                        "price": float(opt_ltp),
                                        "time": time.time(),
                                    }
                                    summary["option_ltp"] += 1
                        except Exception as exc:
                            logger.debug(f"Morning refresh option {name} {opt_type} failed: {exc}")

                if do_chain:
                    row["chain"] = False
                    row["intel"] = False
                    try:
                        chain_result = prewarmed.get(name, {}).get("chain_result")
                        if chain_result is None and not partial:
                            # full path always requested chain
                            pass
                        if isinstance(chain_result, Exception):
                            raise chain_result
                        chain, quality = (None, {}) if chain_result is None else chain_result
                        if chain is not None and hasattr(chain, "empty") and not chain.empty:
                            summary["chains"] += 1
                            row["chain"] = True
                        elif chain is not None and not hasattr(chain, "empty") and chain:
                            summary["chains"] += 1
                            row["chain"] = True

                        candle_5min_raw = self.candles.get_candles(name, "5min")
                        candle_1min_raw = self.candles.get_candles(name, "1min")
                        candle_5min = self._live_analysis_window(candle_5min_raw, "5min")
                        candle_1min = self._live_analysis_window(candle_1min_raw, "1min")
                        latest_spot = float(spot or self.candles.get_latest_price(name) or 0.0)
                        if latest_spot > 0 and self._regime_history_ready(candle_5min):
                            previous_close = float(
                                (prewarmed.get(name, {}) or {}).get("previous_close") or 0.0
                            )
                            if previous_close <= 0:
                                previous_close = self._previous_close_for(name)
                            _, change_pct = self._price_change_pct_for(
                                name,
                                latest_spot,
                                previous_close=previous_close,
                            )
                            dte = self._days_to_expiry_for(name, session_date)
                            strike_interval = cfg.get("strike_interval", 50)
                            vol_context = self._get_live_volatility_context()
                            contexts = self._build_intelligence_contexts(
                                name,
                                candle_5min,
                                spot=latest_spot,
                                previous_close=previous_close,
                                volatility_context=vol_context,
                                as_of=datetime.now(IST),
                            )
                            warmed_any = False
                            for tf in ("5min", "15min"):
                                candle_tf = (
                                    candle_5min
                                    if tf == "5min"
                                    else self._live_analysis_window(
                                        self.candles.get_candles(name, tf), tf
                                    )
                                )
                                if not self._regime_history_ready(candle_tf):
                                    continue
                                intel_res = await loop.run_in_executor(
                                    None,
                                    lambda n=name, t=tf, ctf=candle_tf, c1=candle_1min, ch=chain, sp=latest_spot, q=quality, d=dte, si=strike_interval, vc=vol_context, iv=self._instrument_iv_observations(name), pcp=change_pct, ctx=contexts: self.intel.analyze(
                                        instrument=n,
                                        timeframe=t,
                                        candle_df=ctf,
                                        candle_1min_df=c1,
                                        options_chain=ch,
                                        spot_price=sp,
                                        strike_interval=si,
                                        days_to_expiry=d,
                                        price_change_pct=pcp,
                                        chain_quality=q,
                                        volatility_value=vc.get("value"),
                                        volatility_percentile=vc.get("percentile"),
                                        volatility_source=vc.get("source", ""),
                                        instrument_iv_observations=iv,
                                        session_context=ctx.get("session_context"),
                                        anchor_regime=ctx.get("anchor_regime"),
                                        breadth_context=ctx.get("breadth_context"),
                                    ),
                                )
                                if self._intel_result_cacheable(intel_res):
                                    self._cache_timeframe_intel(
                                        name, tf, intel_res, mirror_legacy=(tf == "5min")
                                    )
                                    self._record_instrument_iv(name, intel_res)
                                    warmed_any = True
                            if warmed_any:
                                summary["intel"] += 1
                                row["intel"] = True
                    except Exception as exc:
                        logger.debug(f"Morning refresh option chain/intel failed for {name}: {exc}")
                else:
                    if row.get("chain"):
                        summary["chains"] += 1
                    if row.get("intel"):
                        summary["intel"] += 1

            if vix_task is not None:
                try:
                    vix = await vix_task
                    summary["vix"] = bool(vix and vix > 0)
                    if summary["vix"]:
                        self._premium_cache["INDIAVIX"] = {"price": float(vix), "time": time.time()}
                except Exception as exc:
                    logger.debug(f"Morning refresh VIX failed: {exc}")
                    summary["vix"] = False

            # Recompute aggregate counts from per-index for accuracy on partial merges
            if partial:
                summary["index_quotes"] = sum(
                    1 for r in summary["indices"].values() if isinstance(r, dict) and r.get("quote")
                )
                summary["chains"] = sum(
                    1 for r in summary["indices"].values() if isinstance(r, dict) and r.get("chain")
                )
                summary["intel"] = sum(
                    1 for r in summary["indices"].values() if isinstance(r, dict) and r.get("intel")
                )

            complete, missing = self._evaluate_morning_refresh_quality(summary, n_active)
            summary["missing_keys"] = missing
            summary["complete"] = complete
            self._morning_refresh_summary = summary

            elapsed = time.time() - started
            if complete:
                self._morning_refresh_last_date = session_day
                msg = (
                    "Morning refresh COMPLETE: "
                    f"idx={summary['index_quotes']}/{n_active}, "
                    f"fut={summary['futures']}, opt_tokens={summary['option_tokens']}, "
                    f"opt_ltp={summary['option_ltp']}, chains={summary['chains']}/{n_active}, "
                    f"intel={summary['intel']}, vix={'OK' if summary['vix'] else 'MISS'}, "
                    f"attempt={attempt_n}, {elapsed:.1f}s"
                )
                logger.info(msg)
                self.log_event(msg, "success")
            else:
                # Do NOT set last_date — allows retry / partial re-warm / 09:15 catch-up
                if getattr(self, "_morning_refresh_last_date", None) == session_day:
                    self._morning_refresh_last_date = None
                msg = (
                    "Morning refresh INCOMPLETE: "
                    f"idx={summary['index_quotes']}/{n_active}, "
                    f"chains={summary['chains']}/{n_active}, "
                    f"history={summary.get('history')}, expiry={summary.get('expiry')}, "
                    f"vix={'OK' if summary['vix'] else 'MISS'}, "
                    f"missing={missing}, attempt={attempt_n}, {elapsed:.1f}s"
                )
                logger.warning(msg)
                self.log_event(msg, "warning")
        except Exception as exc:
            logger.error(f"Morning market refresh failed: {exc}")
            self.log_event(f"Morning refresh failed: {exc}", "error")
            # Preserve prior partial progress; ensure incomplete state
            fail_summary = self._morning_refresh_summary_for_day(session_day) or summary
            fail_summary["session_day"] = session_day
            fail_summary["complete"] = False
            fail_summary["error"] = str(exc)
            if not fail_summary.get("missing_keys"):
                fail_summary["missing_keys"] = ["history", "expiry", "quotes", "chains"]
            self._morning_refresh_summary = fail_summary
            if getattr(self, "_morning_refresh_last_date", None) == session_day:
                self._morning_refresh_last_date = None
        finally:
            self._morning_refresh_inflight = False

    async def run(self):
        self.is_running = True
        self._event_loop = asyncio.get_running_loop()
        logger.info(f"Scanner started - {len(self.active_indices)} active indices x 3 TFs")

        # Launch high-priority background workers.
        asyncio.create_task(self._background_ltp_worker())
        asyncio.create_task(self._background_intel_worker())
        asyncio.create_task(self._background_history_worker())
        asyncio.create_task(self._background_hft_worker())
        asyncio.create_task(self._background_recovery_checkpoint_worker())
        asyncio.create_task(self._background_signal_report_worker())
        asyncio.create_task(self._smart_health_monitor_loop())

        while self.is_running:
            try:
                # â• â• â•  CONTINUOUS SCANNING (Calculation Only - Fast Path) â• â• â•
                await self._scan_cycle()
                await asyncio.sleep(self.scan_interval)
            except Exception as e:
                import traceback
                logger.error(f"Scanner error: {e}\n{traceback.format_exc()}")
                backoff = max(
                    0.25,
                    float(getattr(get_settings(), "scanner_exception_backoff_seconds", 1.0) or 1.0),
                )
                await asyncio.sleep(backoff)

    async def _background_hft_worker(self):
        """High-Frequency Trade Monitoring (100ms loop) for Spike Readiness"""
        logger.info("âš¡ HFT Trade Monitor Started (100ms loop)")
        while self.is_running:
            try:
                # allow_blocking=False: this runs on the scanner EVENT LOOP every
                # 100ms, and a blocking Fyers chain or Kite LTP here stalls the 1s
                # scan cycle and every dashboard _call_on_scanner_loop with it
                # (observed as api_chart TimeoutError after 5s).
                # The 1s scan path used to be described here as "the authoritative
                # fetch". It is not, and must not be: it runs on this same loop.
                # _premium_refresh_worker does that fetch on a daemon thread.
                self._update_active_trades(allow_blocking=False)
                await asyncio.sleep(0.1) # 100ms check loop
            except Exception as e:
                logger.error(f"Error in HFT worker: {e}")
                await asyncio.sleep(1)

    async def _background_recovery_checkpoint_worker(self):
        """Persist a rolling crash-recovery checkpoint independent of scan completion."""
        while self.is_running:
            try:
                saved = self._save_warm_memory()
                if saved:
                    self._persist_session_trade_candidates()
                    save_state = getattr(getattr(self, "trades", None), "save_state", None)
                    if callable(save_state):
                        await asyncio.to_thread(save_state)
                    self._recovery_checkpoint_count = int(getattr(self, "_recovery_checkpoint_count", 0) or 0) + 1
                    self._last_recovery_checkpoint_at = datetime.now(IST).isoformat()
                    self._last_recovery_checkpoint_error = ""
                await asyncio.sleep(5)
            except Exception as exc:
                self._last_recovery_checkpoint_error = str(exc)
                logger.debug(f"Recovery checkpoint worker skipped: {exc}")
                await asyncio.sleep(5)

    async def _background_signal_report_worker(self):
        """Refresh today's missed/rejected signal report without blocking scans."""
        while self.is_running:
            try:
                await asyncio.to_thread(self.generate_daily_signal_report)
                tracker = getattr(self, "rtracker", None)
                last_report = float(getattr(self, "_last_rtracker_report_at", 0.0) or 0.0)
                if tracker is not None and time.time() - last_report >= 1800.0:
                    self._last_rtracker_report_at = time.time()
                    weeks = int(getattr(get_settings(), "rtracker_report_weeks", 8) or 8)
                    await asyncio.to_thread(tracker.generate_weekly_reports, weeks=weeks)
            except Exception as exc:
                logger.debug(f"Daily signal report refresh skipped: {exc}")
            await asyncio.sleep(300)

    async def _background_ltp_worker(self):
        """Constant high-priority LTP polling utilizing 85% of SmartAPI throughput"""
        while self.is_running:
            try:
                if not self.data.is_market_open() and not self.trades.open_trades:
                    await asyncio.sleep(5)
                    continue
                indices = {k: v for k, v in self.config.get("indices", {}).items() if k in self.active_indices}
                tasks = []
                for name, cfg in indices.items():
                    token = cfg.get("token")
                    if token:
                        tasks.append(self._fetch_ltp_raw(name, token, cfg.get("exchange", "NSE")))

                if tasks:
                    await asyncio.gather(*tasks)

                # Stagger to utilize ~15 pings/sec (Safe under 20/sec limit)
                await asyncio.sleep(0.2)
            except Exception as e:
                logger.debug(f"LTP Worker error: {e}")
                await asyncio.sleep(1)

    async def _fetch_ltp_raw(self, name, token, exchange="NSE"):
        try:
            loop = asyncio.get_event_loop()
            await self._ltp_rate_limiter.consume(1)
            async with self._ltp_semaphore:
                live_price = await loop.run_in_executor(
                    None,
                    lambda: self.data.get_latest_price_by_token(
                        token=token, symbol=name,
                        exchange=exchange
                    )
                )
                if live_price and live_price > 0:
                    self.candles.update_latest_price(name, live_price)
        except Exception as e: logger.debug(f"Ignored exception: {e}")

    async def _background_intel_worker(self):
        """Background Options Intel Fetcher (PCR, OI, Greeks) — Non-Blocking"""
        while self.is_running:
            try:
                indices = {k: v for k, v in self.config.get("indices", {}).items() if k in self.active_indices}
                for name, cfg in indices.items():
                    spot = self.candles.get_latest_price(name)
                    if spot <= 0: continue

                    try:
                        options_chain, chain_quality = await asyncio.get_event_loop().run_in_executor(
                            None, lambda: self._get_option_chain_cached(name, cfg)
                        )
                        if options_chain is not None:
                            depth_context = self._get_depth_context(name, cfg)
                            chain_quality = {**chain_quality, "depth": depth_context}
                            # Pre-calculate intel in background for entry context (5min)
                            # and own-timeframe active-trade context (15min runners).
                            candle_5min = self._live_analysis_window(self.candles.get_candles(name, "5min"), "5min")
                            candle_1min = self._live_analysis_window(self.candles.get_candles(name, "1min"), "1min")
                            if not self._regime_history_ready(candle_5min):
                                self._clear_timeframe_intel(name, "5min")
                                await asyncio.sleep(5)
                                continue

                            vol_context = self._get_live_volatility_context()
                            previous_close = self._previous_close_for(name)
                            _, change_pct = self._price_change_pct_for(
                                name,
                                spot,
                                previous_close=previous_close,
                            )
                            dte = self._days_to_expiry_for(name, datetime.now(IST))
                            contexts = self._build_intelligence_contexts(
                                name,
                                candle_5min,
                                spot=spot,
                                previous_close=previous_close,
                                volatility_context=vol_context,
                                as_of=datetime.now(IST),
                            )
                            intel_res = None
                            for tf in ("5min", "15min"):
                                candle_tf = candle_5min if tf == "5min" else self._live_analysis_window(self.candles.get_candles(name, tf), tf)
                                if not self._regime_history_ready(candle_tf):
                                    self._clear_timeframe_intel(name, tf)
                                    continue
                                intel_tf = self.intel.analyze(
                                    instrument=name, timeframe=tf, candle_df=candle_tf,
                                    candle_1min_df=candle_1min, options_chain=options_chain,
                                    spot_price=spot, strike_interval=cfg.get("strike_interval", 50),
                                    days_to_expiry=dte, price_change_pct=change_pct,
                                    chain_quality=chain_quality,
                                    volatility_value=vol_context.get("value"),
                                    volatility_percentile=vol_context.get("percentile"),
                                    volatility_source=vol_context.get("source", ""),
                                    instrument_iv_observations=self._instrument_iv_observations(name),
                                    session_context=contexts.get("session_context"),
                                    anchor_regime=contexts.get("anchor_regime"),
                                    breadth_context=contexts.get("breadth_context"),
                                )
                                if self._intel_result_cacheable(intel_tf):
                                    self._cache_timeframe_intel(name, tf, intel_tf, mirror_legacy=(tf == "5min"))
                                    self._record_instrument_iv(name, intel_tf)
                                if tf == "5min":
                                    intel_res = intel_tf
                            if intel_res is not None:
                                self._record_bar_aligned_intelligence(name, options_chain, intel_res, chain_quality, depth_context)
                    except Exception as e: logger.debug(f"Ignored exception: {e}")
                    await asyncio.sleep(5) # Stagger between instruments
                await asyncio.sleep(25) # Main interval
            except Exception as e:
                await asyncio.sleep(5)

    async def _background_history_worker(self):
        """Background OHLCV sync. In REAL mode keep scans light and refresh deep candles separately."""
        while self.is_running:
            try:
                indices = {k: v for k, v in self.config.get("indices", {}).items() if k in self.active_indices}
                if self.mode == "HISTORICAL":
                    # Historical simulations fetch their required window during recalculation.
                    # Re-polling deep history every minute after that competes with scan cycles
                    # and has caused multi-second dashboard stalls.
                    await asyncio.sleep(max(300, self._data_fetch_interval))
                    continue
                if self.mode == "REAL":
                    await self._fetch_all_data(indices, timeframes=["1min"])
                    last_full = getattr(self, "_last_full_history_refresh", 0.0)
                    if time.time() - last_full >= 300.0:
                        await self._fetch_all_data(indices, timeframes=["5min", "15min"])
                        self._last_full_history_refresh = time.time()
                else:
                    await self._fetch_all_data(indices)
                await asyncio.sleep(self._data_fetch_interval)
            except Exception as e:

                logger.debug(f"Caught bare exception: {e}")
                await asyncio.sleep(10)


    async def _smart_health_monitor_loop(self):
        """Periodically emits system health and market regime logs."""
        import asyncio
        from datetime import datetime
        import time
        from config.settings import get_settings
        
        last_log_time = 0.0
        
        while getattr(self, "is_running", True):
            now = datetime.now(IST)
            # Market hours: 09:15 to 15:30 IST
            try:
                start_time = datetime.strptime("09:15", "%H:%M").time()
                end_time = datetime.strptime("15:30", "%H:%M").time()
                is_live = start_time <= now.time() <= end_time
            except Exception:
                is_live = False
                
            interval = 1800 if is_live else 7200 # 30 mins live, 2 hrs off-market

            # Checked on its own faster cadence than the health LOG below: a volume
            # feed dying is the kind of thing that must not wait up to 30 minutes to
            # be noticed, and this only fires on a TRANSITION so it cannot spam.
            if is_live:
                try:
                    # to_thread even though the cheap path is in-memory: this loop drives
                    # nothing else, and a surprise blocking call here stalls the scan
                    # cycle, the LTP worker, the intel worker and the HFT monitor together.
                    await asyncio.to_thread(self._alert_volume_source_degradation)
                except Exception as exc:
                    logger.debug(f"Volume source health check failed: {exc}")

            current_time = time.time()
            if current_time - last_log_time >= interval:
                # 1. Regime State
                regimes = getattr(self, "latest_regimes", {})
                regime_str = ", ".join([f"{k}: {v}" for k, v in list(regimes.items())[:3]]) if regimes else "UNKNOWN"
                
                # 2. ADX Momentum
                adx_str = "Neutral"
                try:
                    if getattr(self, "_cached_results", None):
                        adxs = []
                        for k, v in self._cached_results.items():
                            if v and "adx" in v:
                                adxs.append(v["adx"])
                        if adxs:
                            avg_adx = sum(adxs) / len(adxs)
                            adx_str = f"Strong ({avg_adx:.1f})" if avg_adx >= 25 else (f"Building ({avg_adx:.1f})" if avg_adx >= 20 else f"Weak ({avg_adx:.1f})")
                except Exception:
                    pass
                    
                # 3. Trade Capacity — effective total = guard-dependent bucket caps (CORE+MIDCAP).
                open_trades_count = len(self.trade_manager.open_trades) if getattr(self, "trade_manager", None) and hasattr(self.trade_manager, "open_trades") else 0
                try:
                    max_trades = self._active_bucket_cap("CORE") + self._active_bucket_cap("MIDCAP")
                except Exception:
                    max_trades = getattr(get_settings(), "max_concurrent_positions", 6)
                
                # 4. Data Health (latency)
                ltp_health = "OK"
                last_ltp = getattr(self.data, "_last_ltp_time", 0.0) if hasattr(self, "data") else 0.0
                if current_time - last_ltp > 60:
                    ltp_health = "STALE"
                
                log_msg = f"System Health: {regime_str} | ADX: {adx_str} | Capacity: {open_trades_count}/{max_trades} | Data: {ltp_health}"
                self.log_event(log_msg, "system")
                last_log_time = current_time
                
            await asyncio.sleep(60) # Wake up every minute to check if interval has passed

    def log_event(self, message: str, type: str = "info"):
        """Add one canonical event to the dashboard tape.

        Several signal gates deliberately overlap. Exact short-window dedupe here
        is the final safety net preventing two callers from rendering the same
        event twice while preserving legitimate later occurrences.
        """
        # Suppress trade-related logs during historical warmup to avoid UI noise
        if getattr(self, "is_warmup", False) and type == "trade":
            return False

        event_type = str(type or "info").strip().lower()
        event_message = re.sub(r"\s+", " ", str(message or "").strip())
        if not event_message:
            return False

        now_mono = time.monotonic()
        dedupe_seconds = max(
            0.0,
            float(
                getattr(
                    get_settings(),
                    "activity_event_dedupe_seconds",
                    2.0,
                )
                or 0.0
            ),
        )
        recent = getattr(self, "_activity_recent_events", None)
        if recent is None:
            self._activity_recent_events = {}
            recent = self._activity_recent_events
        event_key = f"{event_type}|{event_message.casefold()}"
        last_seen = recent.get(event_key)
        if (
            dedupe_seconds > 0.0
            and last_seen is not None
            and now_mono - last_seen < dedupe_seconds
        ):
            return False
        recent[event_key] = now_mono
        prune_before = now_mono - max(30.0, dedupe_seconds * 10.0)
        if len(recent) > 500:
            self._activity_recent_events = {
                key: seen_at
                for key, seen_at in recent.items()
                if seen_at >= prune_before
            }

        icons = {
            "info": "ℹ️",
            "success": "✅",
            "warning": "⚠️",
            "error": "❌",
            "trade": "🔔",
            "system": "⚙️",
            "data": "📊",
            "intel": "🧠"
        }
        icon = icons.get(event_type, "🔹")
        self.activity_log.appendleft({
            "id": uuid.uuid4().hex,
            "time": datetime.now(IST).strftime("%H:%M:%S"),
            "msg": f"{icon} {event_message}",
            "type": event_type
        })
        self._persist_rejected_signal_event(event_message, event_type)
        return True

    def _persist_rejected_signal_event(self, message: str, event_type: str = "trade") -> None:
        """Persist signal rejection/block events for the daily missed-signal report."""
        if getattr(self, "mode", "") == "HISTORICAL" or getattr(self, "is_warmup", False):
            return
        text = str(message or "").strip()
        lowered = text.lower()
        decision_terms = (
            "signal rejected",
            "entry blocked",
            "signal blocked",
            "discarded signal",
            "signal discarded",
            "skipping buffering",
            "discarding matured signal",
            "repainted during",
            "repaint guard",
            "stale buffered signal",
            "future-timestamp signal",
            "signal waiting",
            "signal ignored",
            "concurrency guard: blocked",
            "live gate: blocked",
        )
        if not any(term in lowered for term in decision_terms):
            return

        now = datetime.now(IST)
        instrument = next(
            (
                name
                for name in ("MIDCPNIFTY", "BANKNIFTY", "SENSEX", "NIFTY")
                if re.search(rf"\b{name}\b", text, flags=re.IGNORECASE)
            ),
            "",
        )
        tf_match = re.search(r"\b(1min|5min|15min)\b", text, flags=re.IGNORECASE)
        direction_match = re.search(r"\b(LONG|SHORT|BUY|SELL)\b", text, flags=re.IGNORECASE)
        status = "REJECTED" if "reject" in lowered or "blocked" in lowered else "MISSED"
        reason = text.rsplit(" - ", 1)[-1] if " - " in text else text
        event_id = str(
            uuid.uuid5(
                uuid.NAMESPACE_URL,
                f"{now.date().isoformat()}|{instrument}|{tf_match.group(1) if tf_match else ''}|"
                f"{direction_match.group(1) if direction_match else ''}|{text}",
            )
        )
        try:
            db.save_signal_decision(
                {
                    "id": event_id,
                    "date": now.date().isoformat(),
                    "timestamp": now.isoformat(),
                    "instrument": instrument,
                    "timeframe": tf_match.group(1).lower() if tf_match else "",
                    "direction": direction_match.group(1).upper() if direction_match else "",
                    "status": status,
                    "reason": reason,
                    "message": text,
                    "source": f"activity:{event_type}",
                }
            )
            if hasattr(self, "_diag_inc_unique"):
                self._diag_inc_unique("rejects", str(reason), event_id)
        except Exception as exc:
            logger.debug(f"Signal decision persistence skipped: {exc}")

    def log_signal_decision_once(self, key: str, message: str, type: str = "trade"):
        """Log live signal decisions without spamming the activity panel every scan."""
        seen = getattr(self, "_activity_signal_decision_keys", None)
        if seen is None:
            self._activity_signal_decision_keys = set()
            seen = self._activity_signal_decision_keys
        if key in seen:
            return
        seen.add(key)
        if len(seen) > 1000:
            self._activity_signal_decision_keys = set(list(seen)[-500:])
        self.log_event(message, type)

    def _notify_trade_event(self) -> None:
        """Request an immediate dashboard trade/signal-panel refresh on entry/exit.

        Drops the scanner broadcast throttle and pokes the dashboard's trade
        updater (thread-safe) so a newly opened or closed position shows on the
        panel without waiting for the next ~1s periodic tick.
        """
        self._last_broadcast_time = 0.0
        cb = getattr(self, "on_trade_event", None)
        if cb is None:
            return
        try:
            cb()
        except Exception as exc:
            logger.debug(f"Immediate trade-panel notify skipped: {exc}")

    def _record_live_inflight_skip(self, instrument: str) -> None:
        """Raise a visible warning when live scans repeatedly skip an instrument."""
        counts = getattr(self, "_live_inflight_skip_counts", None)
        if counts is None:
            self._live_inflight_skip_counts = {}
            counts = self._live_inflight_skip_counts
        counts[instrument] = counts.get(instrument, 0) + 1

        if counts[instrument] < 3:
            return

        now = time.time()
        last_alerts = getattr(self, "_live_inflight_last_alert", None)
        if last_alerts is None:
            self._live_inflight_last_alert = {}
            last_alerts = self._live_inflight_last_alert
        if now - last_alerts.get(instrument, 0.0) < 60.0:
            return

        last_alerts[instrument] = now
        msg = (
            f"Live scan backlog: {instrument} skipped {counts[instrument]} times "
            "because the previous processing task is still running. Reversal detection may be delayed."
        )
        logger.warning(msg)
        self.log_event(msg, "warning")
        self._notify(msg, "warning")

    def _clear_live_inflight_skip(self, instrument: str) -> None:
        counts = getattr(self, "_live_inflight_skip_counts", None)
        if isinstance(counts, dict):
            counts.pop(instrument, None)

    def _record_live_processing_timeout(self, instrument: str, timeout_seconds: float) -> None:
        now = time.time()
        last_alerts = getattr(self, "_live_inflight_last_alert", None)
        if last_alerts is None:
            self._live_inflight_last_alert = {}
            last_alerts = self._live_inflight_last_alert
        key = f"{instrument}:timeout"
        if now - last_alerts.get(key, 0.0) < 60.0:
            return

        last_alerts[key] = now
        msg = (
            f"Live scan timeout: {instrument} did not finish within {timeout_seconds:.1f}s. "
            "Signal and reversal detection may be stale until processing catches up."
        )
        logger.warning(msg)
        self.log_event(msg, "warning")
        self._notify(msg, "warning")

    def _build_live_fallback_result(self, name: str, cfg: Dict, reason: str) -> Tuple[Dict, List[TradeCandidate]]:
        """Keep live monitoring alive when the full analysis worker is stale."""
        try:
            self._check_session_candidates_breaches(name)
        except Exception as exc:
            logger.debug(f"Fallback session breach check failed for {name}: {exc}")

        display_candidates = self._get_session_trade_candidates(name)
        if not display_candidates:
            display_candidates = (
                self._latest_exit_candidates.get(name, [])
                + self._latest_trade_candidates.get(name, [])
            )
        try:
            self._refresh_trade_candidates(display_candidates, cfg)
        except Exception as exc:
            logger.debug(f"Fallback candidate refresh failed for {name}: {exc}")

        prev_ui = {}
        try:
            prev_ui = ((self.latest_results or {}).get("instruments") or {}).get(name) or {}
        except Exception:
            prev_ui = {}

        ui_data = dict(prev_ui) if isinstance(prev_ui, dict) else {}
        spot = self.candles.get_latest_price(name)
        if (not spot or spot <= 0) and isinstance(prev_ui, dict):
            spot = float(prev_ui.get("spot_price") or prev_ui.get("ltp") or 0.0)

        ui_data.setdefault("mtf", {})
        ui_data.setdefault("intelligence", {})
        ui_data.setdefault("chart", {})
        ui_data["ltp"] = float(spot or 0.0)
        ui_data["spot_price"] = float(spot or 0.0)
        ui_data["trade_candidates"] = [self._serialize_trade_candidate(c) for c in display_candidates]
        ui_data["fallback_active"] = True
        ui_data["fallback_reason"] = reason
        ui_data["quote_source"] = "fallback_cache"
        ui_data["error"] = reason
        return ui_data, []

    def _repaint_signal_status(self, candidate: TradeCandidate, sig_timestamp) -> str:
        """Why the buffered arrow no longer matches — not merely THAT it does not.

        The two ways to fail are not the same evidence and must not earn the same
        treatment:

          VANISHED — nothing prints at that timestamp any more. The indicator has
                     WITHDRAWN its claim, so the momentum override is allowed to ask
                     whether the market still supports the trade on its own merits.
          FLIPPED  — a signal is still there, but it now prints the OPPOSITE side.
                     That is evidence AGAINST the trade, not an absence of evidence,
                     and no amount of confirming context makes a BUY correct while
                     the source says SELL on the very same bar.

        UNKNOWN covers "cannot tell": no cached scan yet, or no timestamp to match on.
        Callers treat it like VANISHED, which is what this code has always done.
        """
        if sig_timestamp is None:
            return "UNKNOWN"
        # getattr, not attribute access: partial scanners are a real pattern here, and a
        # missing cache is exactly the "cannot tell" case this function already names.
        cache = getattr(self, "_cached_results", None) or {}
        cached_res = cache.get(f"{getattr(candidate, 'instrument', '')}_{getattr(candidate, 'timeframe', '')}") or {}
        signals = list(cached_res.get("signals") or [])
        if not signals:
            return "UNKNOWN"

        target_type = getattr(candidate, "source_signal_type", None) or ("BUY" if candidate.direction == "LONG" else "SELL")
        # Repaint stabilization is identity-only: original timestamp + type.
        # Price can move during the stabilization window and is handled later
        # by candidate selection/execution pricing, not repaint validation.
        match_sig = None
        for s in signals:
            s_ts = getattr(s, "timestamp", None)
            if s_ts:
                t1 = s_ts.replace(tzinfo=None)
                t2 = sig_timestamp.replace(tzinfo=None)
                if abs((t1 - t2).total_seconds()) <= 1.0:
                    match_sig = s
                    break

        if not match_sig:
            # The signal at this timestamp has disappeared (repainted)
            return "VANISHED"

        # Verify the type/direction still matches. Price is intentionally ignored.
        found_type = str(getattr(match_sig, "signal_type", "") or "").upper()
        if found_type != str(target_type or "").upper():
            return "FLIPPED" if found_type in {"BUY", "SELL"} else "VANISHED"

        return "PRESENT"

    def _repaint_absence_is_definite(self, candidate: TradeCandidate, sig_timestamp) -> bool:
        """True only when the arrow is PROVABLY gone or flipped — never on 'cannot tell'.

        `_repaint_signal_status` returns UNKNOWN for an empty scan cache, and the cache is
        cleared out from under an in-flight repaint check by ordinary operator actions: a
        settings save (configure), perform_system_recalibration, a scanner-engine switch
        (invalidate_chart_caches) and the day rollover all call `_cached_results.clear()`.

        Reading that through a True/False wrapper made "I cannot see the arrow" identical
        to "the arrow is gone", so a click during a live trade booked a REPAINT_ABORT on
        no evidence. Callers re-check on a timer, so refusing to conclude costs one cycle.
        """
        try:
            return self._repaint_signal_status(candidate, sig_timestamp) in {"VANISHED", "FLIPPED"}
        except Exception:
            # Fail SAFE: an unreadable status is "cannot tell", not "gone".
            return False

    def _live_utbot_signal_still_present(self, candidate: TradeCandidate, sig_timestamp) -> bool:
        """True when the UT1 signal with the same timestamp still matches this candidate."""
        return self._repaint_signal_status(candidate, sig_timestamp) == "PRESENT"

    def _evict_superseded_opposite_buffer(self, candidate: TradeCandidate, sig_timestamp) -> None:
        """Drop an older buffered arrow when the same chart prints the other way.

        The pending buffer is keyed by instrument+timeframe+DIRECTION, so a LONG and a
        SHORT on the same chart occupy two independent slots and each runs its own
        stabilization timer. Nothing evicts the loser. A stale LONG whose bar has since
        turned bearish can therefore mature and enter alongside the fresh SHORT — and
        because options are always BOUGHT here, that is a long CE and a long PE opened
        minutes apart, paying two premiums and two spreads on one chart, with theta
        working against both. Nobody decided to put that straddle on.

        Only an OLDER arrow is evicted. If the incoming one is the stale side, the
        repaint gate rejects it on its own terms and this stays out of the way.
        """
        instrument = getattr(candidate, "instrument", "")
        timeframe = getattr(candidate, "timeframe", "")
        direction = str(getattr(candidate, "direction", "") or "").upper()
        opposite = "SHORT" if direction == "LONG" else "LONG" if direction == "SHORT" else ""
        if not opposite:
            return
        stale_key = f"{instrument}_{timeframe}_{opposite}"
        stale = (getattr(self, "_pending_live_signals", None) or {}).get(stale_key)
        if not stale:
            return

        new_ts = self._naive_ist_time(sig_timestamp)
        old_ts = self._naive_ist_time(stale.get("sig_timestamp"))
        if new_ts is not None and old_ts is not None and old_ts > new_ts:
            # The buffered arrow is the NEWER one; let it run its own timer.
            return

        self._pending_live_signals.pop(stale_key, None)
        self._diag_inc("stabilization", "evicted_opposite")
        stale_candidate = stale.get("candidate")
        logger.warning(
            f"[STABILIZATION] Evicting buffered {opposite} for {instrument} {timeframe}: "
            f"the same chart now prints {direction}."
        )
        self.log_event(
            f"Buffered {opposite} signal dropped for {instrument} {timeframe}: superseded by "
            f"a {direction} arrow on the same chart.",
            "warning",
        )
        if stale_candidate is not None:
            try:
                self._rtracker_record_candidate(
                    stale_candidate,
                    decision="REJECTED",
                    reason=f"Superseded by an opposite {direction} arrow on the same chart",
                    source="stabilization_opposite_evict",
                )
                self._forget_signal_display_rows(stale_candidate)
            except Exception:
                logger.debug("Opposite-buffer eviction bookkeeping failed", exc_info=True)

    def _live_signal_candle_has_closed(
        self,
        candidate: TradeCandidate,
        sig_timestamp,
        now: Optional[datetime] = None,
    ) -> bool:
        """Return whether the source candle has closed for repaint tracking."""
        if sig_timestamp is None:
            return False

        tf_minutes = {"1min": 1, "5min": 5, "15min": 15}.get(
            str(getattr(candidate, "timeframe", "") or ""),
            5,
        )

        sig_time = sig_timestamp
        if getattr(sig_time, "tzinfo", None) is not None:
            sig_time = sig_time.astimezone(IST).replace(tzinfo=None)

        if now is None:
            now = self._session_squareoff_clock()
        if getattr(now, "tzinfo", None) is not None:
            now = now.astimezone(IST).replace(tzinfo=None)

        return now >= (sig_time + timedelta(minutes=tf_minutes))

    @staticmethod
    def _repaint_signal_type(candidate) -> str:
        source_type = str(getattr(candidate, "source_signal_type", "") or "").upper()
        if source_type in {"BUY", "SELL"}:
            return source_type
        direction = str(getattr(candidate, "direction", "") or "").upper()
        return "BUY" if direction == "LONG" else "SELL"

    @staticmethod
    def _naive_ist_time(value) -> Optional[datetime]:
        if value is None:
            return None
        if getattr(value, "tzinfo", None) is not None:
            return value.astimezone(IST).replace(tzinfo=None)
        return value

    def _post_repaint_recheck_interval_seconds(self) -> float:
        return max(
            1.0,
            float(getattr(get_settings(), "live_repaint_post_exit_recheck_seconds", 60.0) or 60.0),
        )

    def _mark_post_repaint_recheck(
        self,
        candidate,
        sig_timestamp=None,
        now: Optional[datetime] = None,
        source: str = "repaint_abort",
    ) -> None:
        """Allow the same forming candle to be reconsidered once per minute after a repaint abort."""
        if not bool(getattr(get_settings(), "live_repaint_candle_lockout", True)):
            return
        timeframe = str(getattr(candidate, "timeframe", "") or "")
        if timeframe not in {"5min", "15min"}:
            return
        sig_time = self._naive_ist_time(sig_timestamp or getattr(candidate, "signal_timestamp", None))
        if sig_time is None:
            return
        now_time = self._naive_ist_time(now or datetime.now(IST))
        if now_time is None:
            return
        tf_minutes = {"5min": 5, "15min": 15}.get(timeframe, 5)
        if now_time >= sig_time + timedelta(minutes=tf_minutes):
            return

        instrument = str(getattr(candidate, "instrument", "") or "")
        if not instrument:
            return
        signal_type = self._repaint_signal_type(candidate)
        dedup_key = f"{instrument}_{timeframe}"
        identity = f"{sig_time.isoformat()}|{signal_type}"
        interval = self._post_repaint_recheck_interval_seconds()
        store = getattr(self, "_post_repaint_recheck", None)
        if not isinstance(store, dict):
            self._post_repaint_recheck = {}
            store = self._post_repaint_recheck
        store[dedup_key] = {
            "identity": identity,
            "signal_timestamp": sig_time,
            "timeframe": timeframe,
            "armed_at": now_time,
            "next_check": now_time + timedelta(seconds=interval),
            "source": source,
        }
        self._diag_inc("repaint_guard", "post_repaint_recheck_armed")

    def _post_repaint_recheck_due(
        self,
        instrument: str,
        timeframe: str,
        signal_type: str,
        sig_timestamp,
        now: Optional[datetime] = None,
        pending: bool = False,
    ) -> bool:
        if pending:
            return False
        timeframe = str(timeframe or "")
        if timeframe not in {"5min", "15min"}:
            return False
        sig_time = self._naive_ist_time(sig_timestamp)
        now_time = self._naive_ist_time(now or datetime.now(IST))
        if sig_time is None or now_time is None:
            return False
        dedup_key = f"{instrument}_{timeframe}"
        store = getattr(self, "_post_repaint_recheck", None)
        marker = store.get(dedup_key) if isinstance(store, dict) else None
        if not isinstance(marker, dict):
            return False

        identity = f"{sig_time.isoformat()}|{str(signal_type or '').upper()}"
        marker_identity = str(marker.get("identity", "") or "")
        if marker_identity != identity:
            marker_ts = marker.get("signal_timestamp")
            if isinstance(marker_ts, datetime) and sig_time > marker_ts:
                store.pop(dedup_key, None)
            return False

        tf_minutes = {"5min": 5, "15min": 15}.get(timeframe, 5)
        if now_time >= sig_time + timedelta(minutes=tf_minutes):
            store.pop(dedup_key, None)
            return False

        interval = self._post_repaint_recheck_interval_seconds()
        next_check = marker.get("next_check")
        if not isinstance(next_check, datetime):
            armed_at = marker.get("armed_at") if isinstance(marker.get("armed_at"), datetime) else now_time
            next_check = armed_at + timedelta(seconds=interval)
        if now_time < next_check:
            return False

        marker["last_check"] = now_time
        marker["next_check"] = now_time + timedelta(seconds=interval)
        self._diag_inc("repaint_guard", "post_repaint_recheck_due")
        return True

    def _repaint_close_check_in_window(self, sig_timestamp, timeframe, latest_time) -> bool:
        """Whether a post-close repaint determination is still valid.

        Repaint is an INTRABAR concept: it is only meaningful while the source
        candle is forming, plus a brief grace at the close moment so a normally
        running scanner can make the final check. Once that grace passes, the
        candle has long confirmed and a still-open trade is a NORMAL tracked
        position — it must never be repaint-aborted afterwards.
        """
        if sig_timestamp is None or latest_time is None:
            return False
        tf_minutes = {"1min": 1, "5min": 5, "15min": 15}.get(str(timeframe or ""), 5)
        sig_time = sig_timestamp
        if getattr(sig_time, "tzinfo", None) is not None:
            sig_time = sig_time.astimezone(IST).replace(tzinfo=None)
        lt = latest_time
        if getattr(lt, "tzinfo", None) is not None:
            lt = lt.astimezone(IST).replace(tzinfo=None)
        close_dt = sig_time + timedelta(minutes=tf_minutes)
        grace = max(0.0, float(getattr(get_settings(), "repaint_close_check_grace_seconds", 90.0) or 90.0))
        return lt <= close_dt + timedelta(seconds=grace)

    def _calculation_lock_timeout(self) -> float:
        live_timeout = max(
            2.0,
            float(
                getattr(
                    get_settings(),
                    "live_calculation_lock_timeout_seconds",
                    12.0,
                )
                or 12.0
            ),
        )
        if self.mode == "HISTORICAL" or getattr(self, "is_warmup", False):
            return max(75.0, live_timeout)
        return live_timeout

    def _closed_market_idle_allowed(self) -> bool:
        """Avoid recomputing unchanged charts when REAL mode has nothing active."""
        if getattr(self, "mode", "") != "REAL":
            return False
        if not getattr(self, "_initial_setup_completed", False):
            return False
        if getattr(getattr(self, "trades", None), "open_trades", {}):
            return False
        for instrument in (getattr(self, "_session_trade_candidates", {}) or {}):
            if self._active_session_entry_candidates(instrument):
                return False
        return True

    def _prune_runtime_caches(self, force: bool = False) -> int:
        """Physically evict expired fast-path entries instead of waiting for daily reset."""
        now = time.time()
        interval = max(
            5.0,
            float(
                getattr(
                    get_settings(),
                    "runtime_cache_prune_interval_seconds",
                    60.0,
                )
                or 60.0
            ),
        )
        if not force and now - getattr(self, "_last_runtime_cache_prune", 0.0) < interval:
            return 0
        self._last_runtime_cache_prune = now

        removed = 0
        timed_caches = (
            (getattr(self, "_premium_cache", {}), max(10.0, interval * 2.0)),
            (getattr(self, "_candidate_ltp_cache", {}), max(10.0, interval * 2.0)),
            (getattr(self, "_candidate_process_cache", {}), max(30.0, interval * 2.0)),
        )
        for cache, max_age in timed_caches:
            for key, value in list(cache.items()):
                stamp = value.get("time", 0.0) if isinstance(value, dict) else 0.0
                if stamp <= 0 or now - stamp > max_age:
                    cache.pop(key, None)
                    removed += 1

        option_cache = getattr(getattr(self, "signal_processor", None), "_option_history_cache", None)
        if isinstance(option_cache, dict) and len(option_cache) > 500:
            overflow = len(option_cache) - 500
            for key in list(option_cache)[:overflow]:
                option_cache.pop(key, None)
                removed += 1
        symbol_cache = getattr(
            getattr(self, "signal_processor", None),
            "_option_symbol_history_cache",
            None,
        )
        if isinstance(symbol_cache, dict) and len(symbol_cache) > 250:
            overflow = len(symbol_cache) - 250
            attempted = getattr(
                getattr(self, "signal_processor", None),
                "_option_history_fetch_attempted",
                set(),
            )
            for key in list(symbol_cache)[:overflow]:
                symbol_cache.pop(key, None)
                attempted.discard(key)
                removed += 1
        return removed

    async def _scan_cycle(self):
        # ═══ LOCK WATCHDOG (Must be at the very top to break deadlocks) ═══
        if getattr(self, "_calculation_lock", False):
            if (
                hasattr(self, "_lock_time")
                and time.time() - self._lock_time > self._calculation_lock_timeout()
            ):
                logger.error(
                    f"Calculation lock exceeded {self._calculation_lock_timeout():.1f}s. "
                    "Releasing the stale scan gate."
                )
                self._calculation_lock = False
            else:
                # logger.warning("🚫 Scan cycle blocked: Calculation lock active.")
                return

        self.scan_count += 1
        t0 = time.time()
        self.risk_manager.check_circuit_breaker()
        results = {"timestamp": datetime.now(IST).isoformat(), "instruments": {}, "activity_log": self.activity_log}

        # Filter indices based on active_indices setting
        all_indices = self.config.get("indices", {})
        indices = {k: v for k, v in all_indices.items() if k in self.active_indices}

        if self.scan_count == 1 and not self._initial_setup_completed:
            self.log_event("📥 Initializing deep history fetch & warm startup in background...", "system")
            # Run the heavy initialization in the background to prevent screen freeze
            self.is_warmup = True
            self._schedule_initial_setup(indices)

        # ══ DAILY SESSION RESET (At 09:00 AM IST) ══
        cycle_is_warmup = getattr(self, "is_warmup", False)

        now_ist = datetime.now(IST)
        self._prune_runtime_caches()
        self._rollover_session_if_needed(now_ist)
        if False and now_ist.hour == 9 and now_ist.minute == 0:
            if not getattr(self, "_daily_reset_done", False):
                self.log_event("🧹 New Session Prep: Clearing yesterday's trades and cache...", "system")
                if hasattr(self, "trades") and getattr(self.trades, "open_trades", {}):
                    logger.critical("🚨 ORPHANED TRADES DETECTED at 09:00 AM! Broker reconciliation required.")
                self.trades.reset_pnl()
                self._session_candidate_day = now_ist.date().isoformat()
                self._session_trade_candidates.clear()
                self._persist_session_trade_candidates()
                
                # Evict all options-specific in-memory caches to prevent memory bloat
                self._last_opposite_exit_signal_time.clear()
                self._pending_opposite_exit.clear()
                self._last_intel_fetch.clear()
                self._chain_cache.clear()
                self._chain_quality_cache.clear()
                self._last_chain_fetch.clear()
                self._premium_cache.clear()
                self._candidate_ltp_cache.clear()
                self._candidate_process_cache.clear()
                self._cached_results.clear()
                
                # Prune market data provider tick caches to clear yesterday's tokens
                if hasattr(self.data, "_ws_cache"):
                    self.data._ws_cache.clear()
                if hasattr(self.data, "_ltp_cache"):
                    self.data._ltp_cache.clear()
                if hasattr(self.data, "_api_hist_cache"):
                    self.data._api_hist_cache.clear()
                if hasattr(self.data, "_last_api_hist_fetch"):
                    self.data._last_api_hist_fetch.clear()
                logger.info("🧹 In-memory options, history, greeks, and WS caches evicted.")
                
                try:
                    self.market_info = self.expiry.pre_market_check()
                    logger.info("🔄 Pre-Session Expiries Master reloaded successfully.")
                except Exception as e:
                    logger.error(f"❌ Failed to run pre-market check at daily reset: {e}")
                self._daily_reset_done = True
                logger.info("🧹 Pre-Session Refresh: TradeManager reset for the new day.")
        elif now_ist.hour == 9 and now_ist.minute == 17:
            self._daily_reset_done = False # Reset readiness flag for next session

        if self.mode == "REAL" and not cycle_is_warmup and self._ensure_market_session_refresh(indices, now_ist):
            self.is_calculating = False
            return

        # ══ DAILY DATA MAINTENANCE (At 15:45 PM IST) ══
        if now_ist.hour == 15 and now_ist.minute == 45:
            if not getattr(self, "_daily_maintenance_done", False):
                self.log_event("🧹 Running Daily Data Maintenance & Pruning...", "system")
                asyncio.get_event_loop().run_in_executor(None, lambda: self.data_manager.run_daily_maintenance(list(self.active_indices)))
                self._daily_maintenance_done = True
        elif now_ist.hour == 15 and now_ist.minute == 47:
            self._daily_maintenance_done = False

        # â• â•  PERIODIC OFFICIAL CANDLE SYNC (Every 60s) â• â•
        # Ensures chart is 100% accurate with broker even if polling missed a tick
        # â• â•  SYSTEM POWER & MARKET STATUS CHECK â• â•
        is_market_open = self.data.is_market_open()

        # EOD Square-off monitoring (Always active if trades or manual signal rows exist)
        session_now = self._session_squareoff_clock()
        self._force_exit_session_candidates_at_eod(session_now)
        # Orphans count as exposure here, not just local rows. An orphan makes
        # can_open_trade refuse EVERY entry ("Broker-only orphan position requires
        # reconciliation"), so on a day that starts with one — the first-start-of-day case
        # the orphan sweep exists for — open_trades stays empty for the whole session and
        # this gate never opens. check_session_end, and the orphan sweep at the end of it,
        # would then never run: the position carries overnight in exactly the silence the
        # sweep was written to end.
        if self.trades.open_trades or getattr(self.trades, "orphan_positions", None):
            if self.mode != "HISTORICAL":
                expired = self.trades.expire_stale_open_trades(now=session_now, reason="STALE_SESSION_END")
                if expired:
                    self.log_event(f"Closed {expired} stale prior-session trade(s)", "warning")
            # Expiry-day gamma trades square off early (before the EOD kill) to dodge theta crush.
            self.trades.check_expiry_gamma_time_exit(current_time=session_now)
            self.trades.check_session_end(current_time=session_now)

        # Calculation Gate: Only blocked by SYSTEM POWER (not market hours)
        if self.system_power == "OFF":
            self.is_calculating = False
            results.update({
                "system_power": "OFF",
                "is_calculating": False,
                "market_status": "SYSTEM OFF",
                "mode": self.mode,
                "gateway_status": self.data.get_source_health(),
                "config": self.get_broadcast_config(),
                "engine_lab": self._engine_lab_snapshot_for_scan(),
                "trades": self._build_dashboard_trade_payload(),
                "scan_count": self.scan_count,
                "latency": 0,
                "timestamp": datetime.now(IST).isoformat()
            })
            self.latest_results = results
            self._update_dashboard_cache(results)
            self._save_warm_memory()
            if self.on_update:
                try: await self.on_update(results)
                except Exception as e:
                    logger.error(f"Failed to broadcast update: {e}")
            return

        # Market Status Tagging
        market_status = "OPEN" if is_market_open else "CLOSED"
        results["market_status"] = market_status

        if not is_market_open and self._closed_market_idle_allowed():
            previous = self.latest_results if isinstance(self.latest_results, dict) else {}
            results.update({
                "instruments": dict(previous.get("instruments") or {}),
                "system_power": self.system_power,
                "is_calculating": False,
                "mode": self.mode,
                "gateway_status": self.data.get_source_health(),
                "config": self.get_broadcast_config(),
                "engine_lab": self._engine_lab_snapshot_for_scan(),
                "trades": self._build_dashboard_trade_payload(),
                "scan_count": self.scan_count,
                "latency": round((time.time() - t0) * 1000),
                "timestamp": datetime.now(IST).isoformat(),
                "simulation_id": self.simulation_id,
            })
            self.latest_results = results
            self._update_dashboard_cache(results)
            self.last_scan_time = datetime.now(IST)
            self.is_calculating = False
            if self.on_update and time.time() - getattr(self, "_last_broadcast_time", 0) >= 1.0:
                self._last_broadcast_time = time.time()
                await self.on_update(results)
            return

        if self._historical_recalculation_blocks_scan():
            previous = self.latest_results if isinstance(self.latest_results, dict) else {}
            results.update({
                "instruments": dict(previous.get("instruments") or {}),
                "system_power": self.system_power,
                "is_calculating": False,
                "mode": self.mode,
                "gateway_status": self.data.get_source_health(),
                "config": self.get_broadcast_config(),
                "engine_lab": self._engine_lab_snapshot_for_scan(),
                "trades": self._build_dashboard_trade_payload(),
                "scan_count": self.scan_count,
                "latency": round((time.time() - t0) * 1000),
                "timestamp": datetime.now(IST).isoformat(),
                "simulation_id": self.simulation_id,
            })
            self.latest_results = results
            self._update_dashboard_cache(results)
            self.last_scan_time = datetime.now(IST)
            self.is_calculating = False
            if self.on_update and time.time() - getattr(self, "_last_broadcast_time", 0) >= 1.0:
                self._last_broadcast_time = time.time()
                await self.on_update(results)
            return

        self.is_calculating = True

        # Optimization: Clear results to prevent stale data ghosting
        results["instruments"] = {}

        self._calculation_lock = True
        self._lock_time = time.time()
        scan_started_at = datetime.now(IST)
        self._active_scan_started_at = scan_started_at
        self._active_scan_progress_at = scan_started_at
        self._active_scan_processed_indices = 0
        self._active_scan_total_indices = 0
        cycle_simulation_id = int(self.simulation_id)
        cycle_backtest_days = int(getattr(self, "backtest_days", 1) or 1)
        self._active_scan_backtest_days = cycle_backtest_days
        if (
            self.mode == "HISTORICAL"
            and bool(getattr(self, "_historical_rebuild_pending", False))
            and str((getattr(self, "_recalculation_status", {}) or {}).get("status", "") or "").lower() == "awaiting_scan"
        ):
            previous_recalc = dict(getattr(self, "_recalculation_status", {}) or {})
            worker_payload = previous_recalc.get("worker", {})
            if not isinstance(worker_payload, dict):
                worker_payload = {}
            worker_duration_seconds = previous_recalc.get("worker_duration_seconds")
            if worker_duration_seconds is None:
                worker_duration_seconds = worker_payload.get("duration_seconds")
            self._set_recalculation_status(
                "scan_running",
                "historical-scan-running",
                scan_started_at=scan_started_at.isoformat(),
                simulation_id=cycle_simulation_id,
                scanner_engine=str(getattr(get_settings(), "scanner_engine", "utbot") or "utbot").lower(),
                active_indices=list(getattr(self, "active_indices", []) or []),
                loaded_rows=previous_recalc.get("loaded_rows", 0),
                worker=worker_payload,
                pre_scan_duration_seconds=previous_recalc.get("duration_seconds"),
                worker_duration_seconds=worker_duration_seconds,
            )
        try:
            # Force full chart broadcast if simulation_id changed or first scan
            is_full_chart_needed = (
                getattr(self, "_last_sent_sim_id", 0) != self.simulation_id
            )

            # If we need a full chart, force a data fetch to ensure candles match the new days_back
            if is_full_chart_needed and self.scan_count > 1 and self.mode != "REAL":
                logger.info(f"🔄 FORCING FULL HISTORY FETCH ({cycle_backtest_days} days) for Simulation: {self.simulation_id}")
                await self._fetch_all_data(
                    indices,
                    force=True,
                    days_back_override=cycle_backtest_days,
                )

            async def process_task(name, cfg):
                try:
                    index_started = time.time()
                    timeout_seconds = 60.0 if (self.mode == "HISTORICAL" or cycle_is_warmup) else float(getattr(get_settings(), "live_index_timeout_seconds", 6.0) or 6.0)
                    existing_future = getattr(self, "_live_processing_futures", {}).get(name)
                    if (
                        self.mode != "HISTORICAL"
                        and not cycle_is_warmup
                        and existing_future is not None
                        and not existing_future.done()
                    ):
                        self._diag_inc("timeouts", f"{name}_skipped_inflight")
                        self._diag_inc("timeouts", "skipped_inflight")
                        logger.warning(f"Skipping {name}: previous processing task is still running.")
                        self._record_live_inflight_skip(name)
                        self._diagnostics.setdefault("index_processing_ms", {})[name] = round((time.time() - index_started) * 1000)
                        return name, self._build_live_fallback_result(name, cfg, "Previous processing task still running")

                    spot = self.candles.get_latest_price(name)
                    if spot <= 0:
                        spot = await asyncio.get_event_loop().run_in_executor(
                            None,
                            lambda: self.data.get_ltp(cfg.get("exchange", "NSE"), name, cfg.get("token", "")),
                        )
                        if spot and spot > 0:
                            self.candles.update_latest_price(name, spot)

                    loop = asyncio.get_event_loop()
                    try:
                        processing_future = loop.run_in_executor(None, lambda: self._process_instrument(name, cfg))
                        if self.mode != "HISTORICAL" and not cycle_is_warmup:
                            self._live_processing_futures[name] = processing_future
                            self._live_processing_started[name] = time.time()

                            def _clear_live_future(done_future, inst=name):
                                if getattr(self, "_live_processing_futures", {}).get(inst) is done_future:
                                    self._live_processing_futures.pop(inst, None)
                                    self._live_processing_started.pop(inst, None)

                            processing_future.add_done_callback(_clear_live_future)

                        if self.mode == "HISTORICAL":
                            # Historical replays must be deterministic. If an
                            # executor future is timed out, the thread keeps
                            # running and can still append historical trades
                            # after the dashboard has published a "final" count.
                            ui_data, candidate = await asyncio.shield(processing_future)
                        else:
                            ui_data, candidate = await asyncio.wait_for(
                                asyncio.shield(processing_future),
                                timeout=timeout_seconds,
                            )
                        if self.mode != "HISTORICAL" and not cycle_is_warmup:
                            self._clear_live_inflight_skip(name)
                        self._diagnostics.setdefault("index_processing_ms", {})[name] = round((time.time() - index_started) * 1000)
                        return name, (ui_data, candidate)
                    except asyncio.TimeoutError:
                        self._diag_inc("timeouts", name)
                        # Designed degradation, not a hang: the shielded future
                        # keeps computing and lands next cycle; this cycle serves
                        # the stale fallback (typical cause: broker history I/O
                        # burst sharing the executor — 2026-07-10 11:29 cluster).
                        logger.warning(
                            f"{name} exceeded the {timeout_seconds:.0f}s per-index budget; "
                            "serving stale fallback this cycle (computation continues in background)."
                        )
                        if self.mode != "HISTORICAL" and not cycle_is_warmup:
                            self._record_live_processing_timeout(name, timeout_seconds)
                        self._diagnostics.setdefault("index_processing_ms", {})[name] = round((time.time() - index_started) * 1000)
                        return name, self._build_live_fallback_result(name, cfg, "Timeout")
                    except Exception as e:
                        logger.error(f"Error processing {name}: {e}")
                        self._diagnostics.setdefault("index_processing_ms", {})[name] = round((time.time() - index_started) * 1000)
                        return name, ({"error": str(e)}, [])
                except Exception as e:
                    logger.error(f"Outer error processing {name}: {e}")
                    return name, ({"error": str(e)}, [])

            # â• â•  Process each instrument in PARALLEL â• â•
            tasks = []
            for name in self.active_indices:
                cfg = self.config.get("indices", {}).get(name)
                if cfg:
                    tasks.append(process_task(name, cfg))
            self._active_scan_total_indices = len(tasks)

            if not tasks:
                # logger.warning("âš ï¸  No active indices selected for scanning.")
                return

            def mark_scan_progress(processed: int) -> None:
                progress_at = datetime.now(IST)
                self._active_scan_progress_at = progress_at
                self._active_scan_processed_indices = processed
                status_payload = dict(getattr(self, "_recalculation_status", {}) or {})
                if str(status_payload.get("status", "") or "").lower() == "scan_running":
                    status_payload.update(
                        {
                            "last_progress_at": progress_at.isoformat(),
                            "processed_indices": processed,
                            "total_indices": len(tasks),
                            "index_processing_ms": dict(
                                (getattr(self, "_diagnostics", {}) or {}).get("index_processing_ms", {}) or {}
                            ),
                        }
                    )
                    self._recalculation_status = status_payload

            if self.mode == "HISTORICAL":
                # Historical replay mutates shared scanner state such as trade
                # ledgers and session direction census. Run in a stable order so
                # the same candle inputs and settings produce the same results.
                scan_results = []
                for task in tasks:
                    scan_results.append(await task)
                    mark_scan_progress(len(scan_results))
            else:
                scan_results = await asyncio.gather(*tasks)
            if not self._scan_generation_is_current(cycle_simulation_id):
                logger.info(
                    "Discarding obsolete scan generation "
                    f"{cycle_simulation_id}; current simulation is {self.simulation_id}."
                )
                return

            # â• â•  COORDINATE SIGNALS (Correlation Filter) â• â•
            candidates: List[TradeCandidate] = []
            for name, result_pair in scan_results:
                if isinstance(result_pair, tuple) and len(result_pair) == 2:
                    ui_data, candidate = result_pair
                    results["instruments"][name] = ui_data
                    if candidate:
                        if isinstance(candidate, list):
                            candidates.extend(candidate)
                        else:
                            candidates.append(candidate)
                else:
                    results["instruments"][name] = result_pair

            if candidates and self.mode != "HISTORICAL":
                fresh_candidates = []
                for candidate in candidates:
                    if self._is_stale_realtime_entry_candidate(candidate):
                        signal_ts = getattr(candidate, "signal_timestamp", None)
                        msg = (
                            f"Ignoring stale REAL-mode signal: {candidate.instrument} "
                            f"{candidate.direction} {candidate.timeframe} @ {signal_ts}. "
                            "It was no longer fresh when received."
                        )
                        logger.warning(msg)
                        ts_key = signal_ts.isoformat(timespec="seconds") if signal_ts else ""
                        self.log_signal_decision_once(
                            f"{candidate.instrument}|{candidate.timeframe}|{candidate.direction}|{ts_key}|stale-real",
                            msg,
                            "trade",
                        )
                        self._rtracker_record_candidate(
                            candidate,
                            decision="REJECTED",
                            reason="Stale REAL-mode signal",
                            source="stale_realtime_gate",
                        )
                        continue
                    fresh_candidates.append(candidate)
                candidates = fresh_candidates

            if candidates or self._pending_live_signals:
                if self.mode != "HISTORICAL":
                    display_only_candidates = [
                        c for c in candidates
                        if getattr(c, "action", "ENTRY") == "NO_ENTRY" or (not self.data.is_market_open() and not getattr(self, "is_warmup", False))
                    ]
                    if display_only_candidates:
                        for display_candidate in display_only_candidates:
                            self._remember_filtered_candidate(display_candidate)
                    candidates = [
                        c for c in candidates
                        if getattr(c, "action", "ENTRY") != "NO_ENTRY" and (self.data.is_market_open() or getattr(self, "is_warmup", False))
                    ]
                    reentry_candidates = self._collect_missed_signal_reentries(candidates)
                    if reentry_candidates:
                        candidates.extend(reentry_candidates)
                await self._coordinate_and_execute(candidates)
            self._refresh_session_signal_payloads(results)

            # Update active trades (PnL and Trailing Stops).
            #
            # allow_blocking=False here too. The 100ms worker was moved off the blocking
            # path earlier with a comment promising "the 1s scan path below still does the
            # authoritative fetch" — but this call is ALSO on the scanner event loop, so
            # it stalls exactly what that fix set out to protect, just once a second
            # instead of ten times. Today's log carries 39 "Error in periodic trades
            # updater" TimeoutErrors clustered through live hours (13:20-14:51); that
            # updater budgets 5s on _call_on_scanner_loop, so the loop was blocked longer
            # than five seconds, 39 times, while the market was open. A blocked loop is
            # not scanning and not evaluating exits.
            #
            # Nothing is lost by dropping the blocking fetch: _premium_refresh_worker
            # already calls _get_live_premium_cached(allow_blocking=True) on a daemon
            # thread, single-flighted per token, and populates _premium_cache for both
            # callers. The authoritative fetch still happens — off the loop, where it
            # belongs. That promise in the older comment was true when it was written and
            # stopped being true when the background refresher took the job over.
            self._update_active_trades(allow_blocking=False)

            elapsed = time.time() - t0
            latency_ms = round(elapsed * 1000)
            self._diagnostics.setdefault("latency", {})["last_ms"] = latency_ms
            if latency_ms >= 5000 or self.scan_count % 20 == 0:
                self._publish_system_performance_alerts(latency_ms=latency_ms)

            # â• â• â•  Final Payload Construction â• â• â•
            perf_stats = self.perf.calculate(self.trades.closed_trades)
            summary_data = self.trades.get_summary()
            summary_data.update(perf_stats)

            # Build intelligence map (keys = instrument names used by dashboard tabs).
            # Ensure session_context / mood_horizons always present for Regime panel.
            intel_map = {}
            prediction_map = {}
            for name, ui_data in results.get("instruments", {}).items():
                if isinstance(ui_data, dict):
                    intel_payload = ui_data.get("intelligence", {}) or {}
                    if isinstance(intel_payload, dict):
                        sc = intel_payload.get("session_context")
                        agg = intel_payload.get("aggregate") if isinstance(
                            intel_payload.get("aggregate"), dict
                        ) else {}
                        if not isinstance(sc, dict) or not sc:
                            # Rebuild thin session_context from aggregate so mood
                            # grid never renders empty zeros.
                            sc = {
                                "day_type": agg.get("day_type") or agg.get("effective_day_type") or "UNDECIDED",
                                "bias": agg.get("session_bias") or agg.get("effective_bias") or "NEUTRAL",
                                "confidence": float(agg.get("phase_confidence") or 0.0),
                                "effective_day_type": agg.get("effective_day_type") or agg.get("day_type") or "UNDECIDED",
                                "effective_bias": agg.get("effective_bias") or agg.get("session_bias") or "NEUTRAL",
                                "phase_confidence": float(agg.get("phase_confidence") or 0.0),
                                "mood_horizons": agg.get("mood_horizons") or {},
                                "reason": "AGGREGATE_FALLBACK",
                            }
                            intel_payload = dict(intel_payload)
                            intel_payload["session_context"] = sc
                        elif not isinstance(sc.get("mood_horizons"), dict) or not sc.get("mood_horizons"):
                            mh = agg.get("mood_horizons") if isinstance(agg, dict) else None
                            if isinstance(mh, dict) and mh:
                                sc = dict(sc)
                                sc["mood_horizons"] = mh
                                intel_payload = dict(intel_payload)
                                intel_payload["session_context"] = sc
                        ui_data["intelligence"] = intel_payload
                    intel_map[name] = intel_payload if isinstance(intel_payload, dict) else {}
                    # Alias uppercase so UI instrument tabs always resolve.
                    intel_map[str(name or "").upper()] = intel_map[name]
                    prediction_map[name] = ui_data.get("pre_candle_prediction", {})

                    # CRITICAL PERFORMANCE FIX: Strip heavy chart data except on resets/init
                    # Also strip for non-active tab to save bandwidth
                    if not getattr(self, "chart_stream_enabled", True):
                        ui_data["chart"] = {}
                    elif not is_full_chart_needed:
                        if "chart" in ui_data:
                            stripped_chart = {}
                            for tf, v in ui_data["chart"].items():
                                stripped_chart[tf] = {
                                    "state": v.get("state"),
                                    "candles": [v["candles"][-1]] if v.get("candles") else [],
                                    "trailing_stop": [v["trailing_stop"][-1]] if v.get("trailing_stop") else [],
                                    "markers": v.get("markers", [])
                                }
                            ui_data["chart"] = stripped_chart

            # â• â•  BROADCAST CONFIG â• â•
            config_data = self.get_broadcast_config()
            scan_completed_at = datetime.now(IST)
            self.last_scan_time = scan_completed_at
            self.is_calculating = False
            self._calculation_lock = False
            if self._historical_scan_can_complete():
                previous_recalc = dict(getattr(self, "_recalculation_status", {}) or {})
                scan_duration_seconds = round(elapsed, 2)
                total_duration_seconds = scan_duration_seconds
                started_at = previous_recalc.get("started_at")
                if started_at:
                    try:
                        started_dt = datetime.fromisoformat(str(started_at))
                        if started_dt.tzinfo is None:
                            started_dt = IST.localize(started_dt)
                        total_duration_seconds = round((scan_completed_at - started_dt.astimezone(IST)).total_seconds(), 2)
                    except Exception:
                        total_duration_seconds = scan_duration_seconds
                worker_payload = previous_recalc.get("worker", {})
                if not isinstance(worker_payload, dict):
                    worker_payload = {}
                worker_duration_seconds = previous_recalc.get("worker_duration_seconds")
                if worker_duration_seconds is None:
                    worker_duration_seconds = worker_payload.get("duration_seconds")
                pre_scan_duration_seconds = previous_recalc.get("pre_scan_duration_seconds")
                if pre_scan_duration_seconds is None:
                    pre_scan_duration_seconds = previous_recalc.get("duration_seconds")
                scan_wait_duration_seconds = None
                if total_duration_seconds >= scan_duration_seconds:
                    known_worker_seconds = float(worker_duration_seconds or 0.0)
                    scan_wait_duration_seconds = round(
                        max(0.0, total_duration_seconds - scan_duration_seconds - known_worker_seconds),
                        2,
                    )
                self._historical_rebuild_pending = False
                self._historical_completed_simulation_id = int(self.simulation_id)
                self._set_recalculation_status(
                    "idle",
                    "complete",
                    duration_seconds=total_duration_seconds,
                    total_duration_seconds=total_duration_seconds,
                    scan_duration_seconds=scan_duration_seconds,
                    worker_duration_seconds=worker_duration_seconds,
                    pre_scan_duration_seconds=pre_scan_duration_seconds,
                    scan_wait_duration_seconds=scan_wait_duration_seconds,
                    worker=worker_payload,
                    loaded_rows=previous_recalc.get("loaded_rows", 0),
                    simulation_id=int(self.simulation_id),
                    scanner_engine=str(getattr(get_settings(), "scanner_engine", "utbot") or "utbot").lower(),
                    active_indices=list(getattr(self, "active_indices", []) or []),
                    index_processing_ms=dict((getattr(self, "_diagnostics", {}) or {}).get("index_processing_ms", {}) or {}),
                )

            # Self-heal mid-session restarts that already loaded the SQLite
            # ledger before this rehydrate path existed (or after a hot reload).
            if (
                getattr(self, "mode", "") != "HISTORICAL"
                and getattr(self, "_diagnostics_rehydrated_day", "")
                != getattr(self, "_session_candidate_day", self._get_current_session_day())
            ):
                try:
                    self._rehydrate_live_diagnostics_from_session(
                        getattr(self, "_session_candidate_day", self._get_current_session_day())
                    )
                except Exception:
                    pass

            results.update({
                "system_power": self.system_power,
                "is_calculating": False,
                "mode": self.mode,
                "gateway_status": self.data.get_source_health(),
                "instruments": results.get("instruments", {}),
                "config": config_data,
                "intelligence": intel_map,
                "pre_candle_prediction": prediction_map,
                "diagnostics": self._get_diagnostics_payload(),
                "engine_lab": self._engine_lab_snapshot_for_scan(),
                "trades": self._build_dashboard_trade_payload(),
                "scan_count": self.scan_count,
                "latency": latency_ms,
                # Previous cycle's END-TO-END duration. `latency` above stops before
                # the payload build, the dashboard cache, the warm-memory write and
                # the broadcast itself, so on its own it hides the slowest tail.
                "cycle_ms": self._last_cycle_ms,
                "timestamp": scan_completed_at.isoformat(),
                "simulation_id": self.simulation_id
            })
            self.latest_results = results
            self._update_dashboard_cache(results)
            self._last_sent_sim_id = self.simulation_id
            self._save_warm_memory()

            # â• â•  DASHBOARD THROTTLE â• â•
            # Force broadcast if data updated OR at least every 1s
            now_time = time.time()
            should_broadcast = (
                is_full_chart_needed or
                len(candidates) > 0 or
                (now_time - getattr(self, "_last_broadcast_time", 0)) >= 1.0
            )

            if self.on_update and should_broadcast:
                self._last_broadcast_time = now_time
                try:
                    await self.on_update(results)
                except Exception as e:
                    logger.error(f"Failed to broadcast update: {e}")

            # Everything is done now, so this is the real cost of a cycle. The
            # high-latency and freeze alarms are judged on it rather than on
            # `latency_ms`, which stopped before the payload build, the chart
            # stripping, the dashboard cache, the warm-memory disk write and the
            # broadcast — the very work a freeze is most likely to be stuck in.
            cycle_ms = round((time.time() - t0) * 1000)
            self._last_cycle_ms = cycle_ms
            self._diagnostics.setdefault("latency", {})["last_cycle_ms"] = cycle_ms

            if cycle_ms > 10000 and not cycle_is_warmup:
                self._diag_inc("latency", "high_latency_events")
                logger.warning(f"⚠️ High Latency: {cycle_ms}ms (scan phase {latency_ms}ms)")

            if cycle_ms > 30000 and self.scan_count > 2 and not getattr(self, "is_warmup", False):
                self.log_event(f"⚠️ System Freeze/Hang Detected (Latency: {cycle_ms}ms). Please click the UT1 Logo (Top-Left) to hard-refresh.", "error")

            if self.scan_count % 10 == 0:
                logger.info(f"âœ… Scan Cycle {self.scan_count} Finished | Latency: {latency_ms}ms | Cycle: {cycle_ms}ms")
        finally:
            self._calculation_lock = False
            self.is_calculating = False
            self._active_scan_backtest_days = None
            self._active_scan_started_at = None
            self._active_scan_progress_at = None
            self._active_scan_processed_indices = 0
            self._active_scan_total_indices = 0
            if hasattr(self, "_flush_deferred_recalculation_after_scan"):
                try:
                    self._flush_deferred_recalculation_after_scan()
                except Exception as exc:
                    logger.warning(f"Deferred recalculation queue failed after scan release: {exc}")

    # â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â•
    # PARALLEL DATA FETCH — major latency fix
    # â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â•
    async def _fetch_all_data(self, indices: Dict, force=False, timeframes: Optional[List[str]] = None, days_back_override: Optional[int] = None):
        """Fetch data for all instruments, only when cache expired"""
        now = time.time()
        tasks = []
        selected_timeframes = timeframes or ["1min", "5min", "15min"]
        for name, cfg in indices.items():
            for tf in selected_timeframes:
                cache_key = f"{name}_{tf}"
                last = self._last_data_fetch.get(cache_key, 0)
                if force or now - last >= self._data_fetch_interval:
                    tasks.append(
                        self._fetch_one(
                            name,
                            cfg,
                            tf,
                            days_back_override=days_back_override,
                        )
                    )
                    self._last_data_fetch[cache_key] = now

        if tasks:
            await asyncio.gather(*tasks, return_exceptions=True)

    async def _fetch_one(
        self,
        name,
        cfg,
        tf,
        days_back_override: Optional[int] = None,
    ):
        """Fetch one instrument-timeframe from Yahoo (in thread pool)"""
        loop = asyncio.get_event_loop()
        # Use instance-specific settings (reflects UI changes)
        user_days = (
            int(days_back_override)
            if days_back_override is not None
            else getattr(self, "backtest_days", 2)
        )

        # Weekend/Holiday Buffer: Fetch 3x the requested days to ensure enough 'market days'
        # Yahoo Finance period counts calendar days, not trading days.
        # STABILITY FIX: Always fetch at least 15 days to ensure EMA/ATR convergence
        fetch_days = max(15, user_days * 3)

        # Scaling & Limits:
        # 1m: Max 7 days (Yahoo hard limit)
        # 5m/15m: Always fetch max available (approx 59 days) for absolute indicator stability
        if tf == "1min":
            final_fetch_days = min(7, fetch_days)
        else:
            # Convergence: 20 days is plenty for indicator stability while keeping it fast
            final_fetch_days = min(30, max(20, fetch_days))

        try:
            async with self._api_semaphore:
                await self._history_rate_limiter.consume(1)
                # Keep background history below broker burst limits while live scans run.
                await asyncio.sleep(0.75)
                df = await loop.run_in_executor(
                    None,
                    lambda: self.data.get_historical_candles(
                        cfg["token"], cfg["exchange"], tf,
                        days_back=final_fetch_days, instrument_name=name,
                    ),
                )
            if df is not None and len(df) > 0:
                self.candles.update_candles(name, df, tf)
        except Exception as e:
            logger.error(f"Fetch failed for {name} {tf}: {e}")

    async def _sync_intelligence_history(self, indices: Dict):
        """
        Populate intelligence memory for the current session's history.
        Ensures 'Memory' is full from 9:15 AM to current time.
        """
        logger.info("🧠 Syncing Intelligence History (9:15 AM to Now)...")
        today = datetime.now(IST).date()
        loop = asyncio.get_event_loop()

        for name, cfg in indices.items():
            df_5m = self.candles.get_candles(name, "5min")
            if df_5m is None or df_5m.empty: continue

            # Filter for today's session
            today_data = df_5m[df_5m.index.date == today]
            if today_data.empty: continue

            # Process only the last 12 candles (1 hour) to build recent history and avoid O(N^2) startup lag
            tasks = []
            start_idx = max(0, len(today_data) - 12)
            for i in range(start_idx, len(today_data)):
                # We can't get historical options chain, but we can reconstruct Technical Intelligence
                sub_df = today_data.iloc[:i+1]
                ts = sub_df.index[-1].timestamp()

                # Check if already in memory
                if name in self.intel_memory.memory and ts in self.intel_memory.memory[name]["timestamps"]:
                    continue

                # Analyze Technical components only for history (Options chain is current-only)
                hist_dt = sub_df.index[-1].to_pydatetime()
                hist_vix = self._get_historical_vix(hist_dt)
                hist_vix_percentile = self._vix_percentile(hist_vix, hist_dt)
                hist_spot = float(sub_df["close"].iloc[-1])
                hist_prev_close = self._previous_close_for(name) or float(sub_df["open"].iloc[0])
                _, hist_change_pct = self._price_change_pct_for(
                    name,
                    hist_spot,
                    previous_close=hist_prev_close,
                )
                hist_contexts = self._build_intelligence_contexts(
                    name,
                    sub_df,
                    spot=hist_spot,
                    previous_close=hist_prev_close,
                    volatility_context={"value": hist_vix, "percentile": hist_vix_percentile},
                    as_of=hist_dt,
                )
                hist_dte = self._days_to_expiry_for(name, hist_dt)
                tasks.append(loop.run_in_executor(
                    None,
                    lambda s=sub_df, t=ts, vv=hist_vix, vp=hist_vix_percentile, sp=hist_spot, pcp=hist_change_pct, ctx=hist_contexts, d=hist_dte: (t, self.intel.analyze(
                        instrument=name, timeframe="5min", candle_df=s,
                        options_chain=None,
                        spot_price=sp,
                        days_to_expiry=d,
                        price_change_pct=pcp,
                        volatility_value=vv,
                        volatility_percentile=vp,
                        volatility_source="india_vix_daily_percentile" if vp is not None else "india_vix_insufficient_history",
                        session_context=ctx.get("session_context"),
                        anchor_regime=ctx.get("anchor_regime"),
                        breadth_context=ctx.get("breadth_context"),
                    ))
                ))

            if tasks:
                results = await asyncio.gather(*tasks)
                for ts, intel in results:
                    self.intel_memory.record(name, ts, intel)

        self._schedule_intel_memory_save()
        self.log_event(f"âœ… Intelligence & History Sync Complete for all indices", "success")
        logger.info("âœ… Intelligence Memory Synchronized")

    # â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â•
    # PROCESS INSTRUMENT — cache results, avoid double-compute
    # â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â•
    def _schedule_intel_memory_save(self) -> None:
        """Persist intelligence memory away from the scan hot path."""
        if getattr(self, "_intel_save_inflight", False):
            return
        self._intel_save_inflight = True

        def _save():
            try:
                self.intel_memory.save()
            finally:
                self._intel_save_inflight = False

        try:
            asyncio.get_event_loop().run_in_executor(None, _save)
        except RuntimeError:
            _save()

    def _assess_chain_quality(self, name: str, chain: Optional[pd.DataFrame], meta: Optional[Dict] = None) -> Dict:
        meta = dict(meta or {})
        strike_count = int(len(chain)) if chain is not None else 0
        fetched_at = float(meta.get("fetched_at", time.time()))
        age = max(0.0, time.time() - fetched_at)
        fallback = bool(meta.get("fallback", strike_count <= 1))
        if strike_count >= 10 and not fallback:
            score = 95
        elif strike_count >= 5 and not fallback:
            score = 75
        elif strike_count == 1:
            score = 35
        else:
            score = 0
        expiry_aligned = bool(meta.get("expiry_aligned", meta.get("source") != "fyers"))
        if meta.get("source") == "fyers" and not expiry_aligned:
            score = min(score, 50)
        return {
            "instrument": name,
            "source": meta.get("source", "unknown" if strike_count else "none"),
            "strike_count": strike_count,
            "age_seconds": round(age, 1),
            "score": score,
            "fallback": fallback,
            "stale": False,
            "active_expiry": meta.get("active_expiry", ""),
            "expiry_aligned": expiry_aligned,
        }

    def _intel_analysis_ttl_seconds(self) -> float:
        """How long a computed intelligence bundle stays usable.

        Deliberately NOT intelligence_cache_ttl_seconds. That one is a network budget —
        the option chain is a broker round trip — and the analysis stacked on top is
        candle math over an already-cached chain. Sharing one number meant the cheap
        thing inherited the expensive thing's staleness, so the evidence behind an entry
        could be 90 seconds old on a setup that trades 1-minute bars.

        Falls back to the chain TTL when unset so an older .env keeps its old behaviour
        rather than silently getting a 3x busier scanner.
        """
        settings = get_settings()
        try:
            value = float(getattr(settings, "intelligence_analysis_ttl_seconds", 0.0) or 0.0)
        except (TypeError, ValueError):
            value = 0.0
        if value > 0:
            return value
        try:
            return float(getattr(settings, "intelligence_cache_ttl_seconds", 90.0) or 90.0)
        except (TypeError, ValueError):
            return 90.0

    def _get_option_chain_cached(self, name: str, cfg: Dict, force: bool = False, allow_fetch: bool = True) -> Tuple[pd.DataFrame, Dict]:
        settings = get_settings()
        ttl = float(getattr(settings, "intelligence_cache_ttl_seconds", 30.0))
        now = time.time()
        cached = self._chain_cache.get(name)
        last = self._last_chain_fetch.get(name, 0.0)
        if not force and cached is not None and now - last <= ttl:
            quality = dict(self._chain_quality_cache.get(name, self._assess_chain_quality(name, cached)))
            quality["age_seconds"] = round(now - last, 1)
            quality["stale"] = False
            return cached, quality

        if not allow_fetch:
            if cached is not None:
                age = now - last
                quality = dict(self._chain_quality_cache.get(name, self._assess_chain_quality(name, cached)))
                quality["age_seconds"] = round(age, 1)
                # `stale` disqualifies the chain from intelligence (OI/PCR/Greeks) in
                # IntelligenceAggregator. Deferring a re-fetch does NOT make a chain
                # unusable — only real age does. Flagging every deferred read as stale
                # meant that in REAL mode, where allow_fetch is False once a chain is
                # cached, every scan after the short cache TTL handed intelligence a
                # "stale" chain, which it then dropped: PCR/OI showed 0/unavailable all
                # session even though the chain was being fetched successfully.
                max_age = float(
                    getattr(settings, "option_chain_intelligence_max_age_seconds", 300.0) or 300.0
                )
                quality["stale"] = age > max_age
                return cached, quality
            empty = pd.DataFrame()
            quality = self._assess_chain_quality(
                name,
                empty,
                {"source": "deferred", "fallback": True, "fetched_at": now},
            )
            quality["stale"] = True
            return empty, quality

        try:
            chain = self.data.get_option_chain(name, cfg.get("option_exchange", "NFO"))
        except Exception as e:
            logger.warning(f"Option chain fetch failed for {name}: {e}")
            chain = cached if cached is not None else pd.DataFrame()
        finally:
            self._last_chain_fetch[name] = now

        if chain is None:
            chain = pd.DataFrame()
        meta = getattr(self.data, "_option_chain_meta", {}).get(name, {})
        quality = self._assess_chain_quality(name, chain, meta)
        if not chain.empty:
            self._chain_cache[name] = chain
            self._chain_quality_cache[name] = quality
        elif cached is not None:
            quality = dict(self._chain_quality_cache.get(name, self._assess_chain_quality(name, cached)))
            quality["age_seconds"] = round(now - last, 1)
            quality["stale"] = True
            chain = cached
        return chain, quality

    def _get_depth_context(self, name: str, cfg: Dict) -> Dict[str, Any]:
        getter = getattr(self.data, "get_order_book_snapshot", None)
        if not callable(getter):
            return {"ofr": 1.0, "source": "unavailable", "usable": False}
        try:
            depth = getter(cfg.get("exchange", "NSE"), name, str(cfg.get("token", "")))
            if isinstance(depth, dict) and depth:
                return depth
        except Exception as exc:
            logger.debug(f"Depth/OFR fetch skipped for {name}: {exc}")
        return {"ofr": 1.0, "source": "unavailable", "usable": False}

    @staticmethod
    def _timeframe_intel_key(instrument: str, timeframe: str = "5min") -> str:
        tf = str(timeframe or "5min").lower()
        if tf not in {"1min", "5min", "15min"}:
            tf = "5min"
        return f"{str(instrument or '').upper()}_{tf}"

    def _cache_timeframe_intel(
        self,
        instrument: str,
        timeframe: str,
        intel_result: Optional[Dict[str, Any]],
        *,
        at: Optional[float] = None,
        mirror_legacy: bool = False,
    ) -> None:
        """Cache intelligence/regime per timeframe while keeping 5min legacy keys."""
        if not isinstance(intel_result, dict):
            return
        tf = str(timeframe or "5min").lower()
        key = self._timeframe_intel_key(instrument, tf)
        now = float(at if at is not None else time.time())
        # Stamp the bundle with its own capture time. _intel_age_seconds otherwise has
        # nothing embedded to read and falls through to _last_intel_fetch[instrument] --
        # the BARE key, which is only written for 5min (or a legacy mirror). A 15min
        # trade's staleness guard was therefore measuring how recently the 5MIN bundle
        # refreshed, so a frozen 15min bundle never aged past the 90s bound and could
        # fire OI_PCR_REVERSAL on evidence captured much earlier.
        #
        # Stamping beats swapping in the timeframe-qualified key: when 15min history is
        # not ready the reader legitimately RETURNS the 5min bundle, and this ages
        # whichever bundle was actually handed back. Assigned, not setdefault, so it
        # stays exactly in step with _intel_cache_time[key] on every re-cache.
        intel_result["as_of"] = now
        self._intel_cache[key] = intel_result
        if not hasattr(self, "_intel_cache_time"):
            self._intel_cache_time = {}
        if not hasattr(self, "_last_intel_fetch"):
            self._last_intel_fetch = {}
        self._intel_cache_time[key] = now
        self._last_intel_fetch[key] = now

        regime_payload = intel_result.get("regime", {}) if isinstance(intel_result.get("regime"), dict) else {}
        regime = str(regime_payload.get("regime") or "UNKNOWN").upper()
        if not hasattr(self, "_timeframe_regimes"):
            self._timeframe_regimes = {}
        self._timeframe_regimes[key] = regime

        # MACD acceleration needs the PREVIOUS reading, and the payload carries only the
        # current one. Keep the last value per instrument+timeframe, exactly as the regime
        # label above is kept, so entry pricing can tell an expanding histogram from a
        # stalling one. Two floats per key; nothing is persisted.
        try:
            macd_now = float(regime_payload.get("macd_histogram") or 0.0)
        except (TypeError, ValueError):
            macd_now = 0.0
        if not hasattr(self, "_timeframe_macd"):
            self._timeframe_macd = {}
        previous = self._timeframe_macd.get(key, (0.0, 0.0))[0]
        self._timeframe_macd[key] = (macd_now, float(previous))

        # Most entry/dashboard code historically reads instrument-only 5min context.
        if mirror_legacy or tf == "5min":
            name = str(instrument or "").upper()
            self._intel_cache[name] = intel_result
            self._intel_cache_time[name] = now
            self._last_intel_fetch[name] = now
            if not hasattr(self, "latest_regimes"):
                self.latest_regimes = {}
            self.latest_regimes[name] = regime

    def _entry_momentum_urgency(self, candidate) -> float:
        """How fast the premium is leaving the bid, for this candidate's own timeframe.

        Zero whenever the answer is unknown — no MACD reading, no previous reading, an
        unrecognised timeframe. Absence of evidence must not read as urgency, or every
        entry would take the market on the first bar after a restart.
        """
        try:
            from engine.order_pricing import momentum_urgency

            instrument = str(getattr(candidate, "instrument", "") or "").upper()
            timeframe = str(getattr(candidate, "timeframe", "") or "").lower()
            if not instrument or not timeframe:
                return 0.0
            key = self._timeframe_intel_key(instrument, timeframe)
            now, previous = (getattr(self, "_timeframe_macd", {}) or {}).get(key, (0.0, 0.0))
            return momentum_urgency(now, previous, getattr(candidate, "direction", ""))
        except Exception as exc:
            logger.debug(f"Entry momentum urgency unavailable: {exc}")
            return 0.0

    def _cached_timeframe_intel(
        self,
        instrument: str,
        timeframe: str = "5min",
        *,
        allow_fallback: bool = True,
    ) -> Optional[Dict[str, Any]]:
        tf = str(timeframe or "5min").lower()
        name = str(instrument or "").upper()
        key = self._timeframe_intel_key(name, tf)
        cache = getattr(self, "_intel_cache", {}) or {}
        result = cache.get(key)
        if result is not None:
            return result
        if tf == "5min":
            return cache.get(name)
        if allow_fallback:
            return cache.get(self._timeframe_intel_key(name, "5min")) or cache.get(name)
        return None

    def _clear_timeframe_intel(self, instrument: str, timeframe: str = "5min") -> None:
        tf = str(timeframe or "5min").lower()
        name = str(instrument or "").upper()
        key = self._timeframe_intel_key(name, tf)
        getattr(self, "_intel_cache", {}).pop(key, None)
        getattr(self, "_intel_cache_time", {}).pop(key, None)
        getattr(self, "_last_intel_fetch", {}).pop(key, None)
        getattr(self, "_timeframe_regimes", {}).pop(key, None)
        if tf == "5min":
            getattr(self, "_intel_cache", {}).pop(name, None)
            getattr(self, "_intel_cache_time", {}).pop(name, None)
            getattr(self, "_last_intel_fetch", {}).pop(name, None)
            getattr(self, "latest_regimes", {}).pop(name, None)

    def _purge_intel_regime_caches(self, reason: str = "") -> int:
        """Drop every cached intelligence/regime label. Used on HISTORICAL transitions.

        A replay calls _process_instrument exactly like a live scan, so it writes the
        regime it computed from *past* candles into `_intel_cache` / `_timeframe_regimes`
        / `latest_regimes` — stamped with `time.time()`, i.e. as if it were current. The
        mode switch purges trade ledgers (`_purge_session_contamination`) but left these
        untouched, so on the way back to REAL the replayed label was served as fresh live
        intelligence for the whole `intelligence_cache_ttl_seconds` window, actively
        suppressing the real refresh that would have corrected it.

        Purging is fail-safe in both directions: a missing label reads as UNKNOWN, which
        entry treats as choppy (stricter grade floor), runner mode treats as
        not-own-timeframe (tighter give-back trail), and no exit path keys on. The only
        cost is one intelligence recomputation per instrument on the next scan.
        """
        cleared = 0
        for attr in ("_intel_cache", "_intel_cache_time", "_last_intel_fetch",
                     "_timeframe_regimes", "latest_regimes"):
            cache = getattr(self, attr, None)
            if isinstance(cache, dict) and cache:
                cleared += len(cache)
                cache.clear()
        if cleared:
            logger.info(
                f"🧹 Intelligence/regime caches purged ({cleared} entries) — {reason or 'mode change'}. "
                "Next scan recomputes from live candles."
            )
        return cleared

    def _trade_regime_is_own_timeframe(self, trade_like) -> bool:
        """Whether a regime label exists for the trade's OWN timeframe.

        _get_trade_regime deliberately falls back to the 5-minute label so trailing/EOD
        management always has something to work with. That borrowed label is fine for
        conservative tightening, but it must NOT be used to grant a privilege: a 15-minute
        trade could otherwise enter runner mode on a 5-minute regime, and sampled 5m/15m
        regimes disagree in 83% of same-timestamp pairs.
        """
        instrument = str(getattr(trade_like, "instrument", "") or "").upper()
        timeframe = str(getattr(trade_like, "timeframe", "5min") or "5min").lower()
        key = self._timeframe_intel_key(instrument, timeframe)
        tf_regimes = getattr(self, "_timeframe_regimes", {}) or {}
        latest = getattr(self, "latest_regimes", {}) or {}
        if tf_regimes.get(key) or latest.get(key):
            return True
        # The instrument-only entry IS the 5-minute label (mirror_legacy), so it counts
        # as own-timeframe only for 5-minute trades.
        return timeframe == "5min" and bool(latest.get(instrument))

    def _get_trade_regime(self, trade_like, default: str = "UNKNOWN") -> str:
        instrument = str(getattr(trade_like, "instrument", "") or "").upper()
        timeframe = str(getattr(trade_like, "timeframe", "5min") or "5min").lower()
        tf_regimes = getattr(self, "_timeframe_regimes", {}) or {}
        latest = getattr(self, "latest_regimes", {}) or {}
        key = self._timeframe_intel_key(instrument, timeframe)
        value = (
            tf_regimes.get(key)
            or latest.get(key)
            or (latest.get(instrument) if timeframe == "5min" else None)
            or tf_regimes.get(self._timeframe_intel_key(instrument, "5min"))
            or latest.get(instrument)
            or default
        )
        return str(value or default).upper()

    def _get_trade_intel(self, trade_like) -> Optional[Dict[str, Any]]:
        instrument = str(getattr(trade_like, "instrument", "") or "").upper()
        timeframe = str(getattr(trade_like, "timeframe", "5min") or "5min").lower()
        return self._get_timeframe_intel(instrument, timeframe)

    def _get_timeframe_intel(
        self,
        instrument: str,
        timeframe: str = "5min",
        *,
        chain: Optional[pd.DataFrame] = None,
        chain_quality: Optional[Dict[str, Any]] = None,
        depth_context: Optional[Dict[str, Any]] = None,
        spot: Optional[float] = None,
        cfg: Optional[Dict[str, Any]] = None,
        price_change_pct: float = 0.0,
        volatility_context: Optional[Dict[str, Any]] = None,
        session_context: Optional[Dict[str, Any]] = None,
        anchor_regime: Optional[Dict[str, Any]] = None,
        breadth_context: Optional[Dict[str, Any]] = None,
        now: Optional[float] = None,
        allow_fallback: bool = True,
    ) -> Optional[Dict[str, Any]]:
        """Return cached or freshly computed intelligence for a specific timeframe."""
        name = str(instrument or "").upper()
        tf = str(timeframe or "5min").lower()
        if tf not in {"1min", "5min", "15min"}:
            tf = "5min"
        cache_key = self._timeframe_intel_key(name, tf)
        now_val = float(now if now is not None else time.time())
        ttl = self._intel_analysis_ttl_seconds()
        cached = self._cached_timeframe_intel(name, tf, allow_fallback=False)
        cached_time = float(getattr(self, "_intel_cache_time", {}).get(cache_key, 0.0) or 0.0)
        if cached is not None and self._intel_result_cacheable(cached) and now_val - cached_time <= ttl:
            return cached

        cfg = cfg or (self.config.get("indices", {}).get(name, {}) if hasattr(self, "config") else {})
        try:
            candle_tf = self._live_analysis_window(self.candles.get_candles(name, tf), tf)
        except Exception:
            candle_tf = None
        if candle_tf is None or candle_tf.empty or not self._regime_history_ready(candle_tf):
            return self._cached_timeframe_intel(name, "5min", allow_fallback=True) if allow_fallback else None

        try:
            candle_1min = self._live_analysis_window(self.candles.get_candles(name, "1min"), "1min")
        except Exception:
            candle_1min = None
        try:
            spot_val = float(spot if spot is not None else self.candles.get_latest_price(name) or 0.0)
        except Exception:
            spot_val = 0.0
        if spot_val <= 0:
            try:
                spot_val = float(candle_tf["close"].iloc[-1])
            except Exception:
                spot_val = 0.0

        if chain is None or chain_quality is None:
            chain_cache = getattr(self, "_chain_cache", {}) or {}
            allow_fetch = getattr(self, "mode", "") == "HISTORICAL" or chain_cache.get(name) is None
            chain, chain_quality = self._get_option_chain_cached(name, cfg, allow_fetch=allow_fetch)
        if depth_context is None:
            depth_context = self._get_depth_context(name, cfg)
        chain_quality = {**(chain_quality or {}), "depth": depth_context}

        if volatility_context is None:
            try:
                volatility_context = self._get_live_volatility_context()
            except Exception:
                volatility_context = {}

        dte = self._days_to_expiry_for(name, datetime.now(IST))
        previous_close = self._previous_close_for(name)
        if abs(float(price_change_pct or 0.0)) < 0.0001:
            _, price_change_pct = self._price_change_pct_for(
                name,
                spot_val,
                previous_close=previous_close,
            )
        if session_context is None or anchor_regime is None or breadth_context is None:
            try:
                candle_5min_ctx = candle_tf if tf == "5min" else self._live_analysis_window(self.candles.get_candles(name, "5min"), "5min")
                contexts = self._build_intelligence_contexts(
                    name,
                    candle_5min_ctx,
                    spot=spot_val,
                    previous_close=previous_close,
                    volatility_context=volatility_context,
                    as_of=datetime.now(IST),
                )
                session_context = session_context if session_context is not None else contexts.get("session_context")
                anchor_regime = anchor_regime if anchor_regime is not None else contexts.get("anchor_regime")
                breadth_context = breadth_context if breadth_context is not None else contexts.get("breadth_context")
            except Exception as exc:
                logger.debug(f"Timeframe context build failed for {name} {tf}: {exc}")

        try:
            iv_observations = []
            if hasattr(self, "_instrument_iv_observations"):
                iv_observations = self._instrument_iv_observations(name)
            result = self.intel.analyze(
                instrument=name,
                timeframe=tf,
                candle_df=candle_tf,
                candle_1min_df=candle_1min,
                options_chain=chain,
                spot_price=spot_val,
                strike_interval=int((cfg or {}).get("strike_interval", 50) or 50),
                days_to_expiry=dte,
                price_change_pct=price_change_pct,
                chain_quality=chain_quality,
                volatility_value=(volatility_context or {}).get("value"),
                volatility_percentile=(volatility_context or {}).get("percentile"),
                volatility_source=(volatility_context or {}).get("source", ""),
                instrument_iv_observations=iv_observations,
                session_context=session_context,
                anchor_regime=anchor_regime,
                breadth_context=breadth_context,
            )
        except Exception as exc:
            logger.debug(f"Timeframe intelligence failed for {name} {tf}: {exc}")
            return self._cached_timeframe_intel(name, "5min", allow_fallback=True) if allow_fallback else None

        if self._intel_result_cacheable(result):
            self._cache_timeframe_intel(name, tf, result, at=now_val, mirror_legacy=(tf == "5min"))
            record_iv = getattr(self, "_record_instrument_iv", None)
            if callable(record_iv):
                try:
                    record_iv(name, result)
                except Exception:
                    pass
        return result

    def _record_bar_aligned_intelligence(
        self,
        name: str,
        options_chain: Optional[pd.DataFrame],
        intel_result: Dict[str, Any],
        chain_quality: Dict[str, Any],
        depth_context: Dict[str, Any],
    ) -> None:
        try:
            self.intel_snapshots.push_snapshot(
                name,
                options_chain,
                intel_result=intel_result,
                depth=depth_context,
                quality=chain_quality,
            )
            for tf in ("1min", "5min", "15min"):
                tf_df = self.candles.get_candles(name, tf)
                if tf_df is not None and not tf_df.empty:
                    self.intel_snapshots.freeze_bar(name, tf, tf_df.index[-1])
        except Exception as exc:
            logger.debug(f"Bar-aligned intelligence snapshot skipped for {name}: {exc}")

    @staticmethod
    def _mtf_state_map(mtf_result) -> Dict[str, Dict[str, Any]]:
        return {
            "1min": ((getattr(mtf_result, "results_1min", None) or {}).get("state") or {}),
            "5min": ((getattr(mtf_result, "results_5min", None) or {}).get("state") or {}),
            "15min": ((getattr(mtf_result, "results_15min", None) or {}).get("state") or {}),
        }

    def _prediction_core_states(self, timeframe: str) -> Dict[str, Dict[str, Any]]:
        tf = str(timeframe or "5min").lower()
        states: Dict[str, Dict[str, Any]] = {}
        for instrument in sorted(self.CORE_CORRELATED_INDICES):
            result = (getattr(self, "_cached_results", {}) or {}).get(f"{instrument}_{tf}") or {}
            state = result.get("state") if isinstance(result, dict) else {}
            if isinstance(state, dict) and state:
                states[instrument] = state
        return states

    def _active_trade_for_prediction(self, instrument: str):
        name = str(instrument or "").upper()
        for trade in (getattr(getattr(self, "trades", None), "open_trades", {}) or {}).values():
            if str(getattr(trade, "instrument", "") or "").upper() == name:
                return trade
        return None

    def _prediction_trade_context(self, instrument: str) -> Dict[str, Any]:
        trade = self._active_trade_for_prediction(instrument)
        if trade is None:
            return {}
        return {
            "id": str(getattr(trade, "id", "") or ""),
            "direction": str(getattr(trade, "direction", "") or "").upper(),
            "timeframe": str(getattr(trade, "timeframe", "") or ""),
            "inst_type": str(getattr(trade, "inst_type", "") or ""),
            "pnl": float(getattr(trade, "pnl", 0.0) or 0.0),
            "peak_pnl": float(getattr(trade, "peak_pnl", 0.0) or 0.0),
            "entry_price": float(getattr(trade, "entry_price", 0.0) or 0.0),
            "current_price": float(getattr(trade, "current_price", 0.0) or 0.0),
        }

    def _prediction_option_context(self, instrument: str) -> Dict[str, Any]:
        trade = self._active_trade_for_prediction(instrument)
        if trade is None:
            return {}
        inst_type = str(getattr(trade, "inst_type", "") or "").upper()
        symbol = str(getattr(trade, "trading_symbol", "") or "")
        is_option = inst_type == "OPT" or "CE" in symbol.upper() or "PE" in symbol.upper()
        if not is_option:
            return {}
        current = float(getattr(trade, "current_price", 0.0) or 0.0)
        entry = float(getattr(trade, "entry_price", 0.0) or 0.0)
        now = time.time()
        key = str(getattr(trade, "id", "") or f"{instrument}|{symbol}")
        prev = (getattr(self, "_pre_candle_option_probe", {}) or {}).get(key) or {}
        acceleration = 0.0
        prev_price = float(prev.get("price") or 0.0)
        prev_time = float(prev.get("time") or 0.0)
        if current > 0 and prev_price > 0 and now > prev_time:
            acceleration = ((current - prev_price) / max(now - prev_time, 0.001)) * 60.0
        if current > 0:
            self._pre_candle_option_probe[key] = {"price": current, "time": now}
        return {
            "available": current > 0,
            "entry_price": entry,
            "current_price": current,
            "change_points": round(current - entry, 4) if current > 0 and entry > 0 else 0.0,
            "change_pct": round(((current - entry) / entry * 100.0), 4) if current > 0 and entry > 0 else 0.0,
            "acceleration_points_per_min": round(acceleration, 4),
        }

    # Every volume gate in this system is a RATIO against recent average — the 2.5x
    # surge that is the only way a 1min signal enters, the 1.6x/1.8x hybrid thrusts,
    # the 1.40x cascade, and the fast-opposite thrust EXIT guard. They all read one
    # number, so a dead volume feed silently disables the lot at once, entries and
    # exits alike. Index volume was zero for days before anyone noticed, because
    # nothing surfaced it. This is that missing surface.
    _VOLUME_DEGRADED_SOURCES = {"kite_index_futures", "none", ""}

    def _recent_candle_volume(self, instrument: str):
        """(bars_checked, is_dry) for the 1min series the volume gates actually read.

        "Dry" means enough recent bars exist and none of them carries volume — the shape
        of a feed outage as the ENGINE sees it, regardless of what any quote endpoint
        says. Too few bars is not dry: that is a warm-up, not an outage.
        """
        candles = getattr(self, "candles", None)
        if candles is None or not hasattr(candles, "get_candles"):
            return 0, False
        try:
            df = candles.get_candles(instrument, "1min")
        except Exception:
            return 0, False
        if df is None or "volume" not in getattr(df, "columns", []):
            return 0, False
        recent = df.tail(10)
        bars = int(len(recent))
        if bars < 5:
            return bars, False
        try:
            return bars, bool(float(pd.to_numeric(recent["volume"], errors="coerce").fillna(0).abs().sum()) <= 0.0)
        except Exception:
            return bars, False

    def volume_source_health(self, probe_broker: bool = True) -> Dict[str, Any]:
        """Per-instrument volume provenance, for the dashboard and the watchdog.

        probe_broker=False answers from in-memory state only. get_index_activity reaches
        the broker (a Fyers REST probe plus a Kite quote PER INDEX), so calling this on a
        timer from the scanner's event loop stalls every worker on it for the duration —
        and when Fyers is down, which is exactly when this matters, each probe waits out
        a full timeout. The watchdog uses the cheap path; the dashboard route and the CLI
        script, which are already off-loop and cached, use the full one.
        """
        data = getattr(self, "data", None)
        # ACTIVE indices only. Reporting a configured-but-inactive instrument as
        # "degraded" is a false alarm about a feed nobody is trading.
        active = list(getattr(self, "active_indices", None) or [])
        indices = {name: {} for name in active}
        if not indices:
            indices = dict(getattr(self, "config", {}).get("indices", {}) or {})

        rows: Dict[str, Any] = {}
        degraded: List[str] = []
        for name in indices:
            activity: Dict[str, Any] = {}
            if probe_broker:
                try:
                    if data is not None and hasattr(data, "get_index_activity"):
                        activity = data.get_index_activity(name) or {}
                except Exception as exc:
                    activity = {"source": "none", "error": str(exc)}
            else:
                # In-memory only: the tick path already maintains which feed last
                # supplied a cumulative total, and when.
                source = str(getattr(data, "_index_cum_volume_source", {}).get(name, "") or "")
                stamped = float(getattr(data, "_index_cum_volume_at", {}).get(name, 0.0) or 0.0)
                fresh = stamped > 0 and (time.time() - stamped) <= 120.0
                activity = {
                    "source": source if (source and fresh) else "none",
                    "unit": "contracts" if source == "kite_index_futures" else "shares",
                    "volume": float(getattr(data, "_index_cum_volume", {}).get(name, 0.0) or 0.0),
                    "comparable_to_thresholds": source != "kite_index_futures",
                    "fyers_online": source == "fyers_index" and fresh,
                    "futures": {},
                    "confirmation": "cached",
                }
            futures = (activity or {}).get("futures") or {}
            source = str(activity.get("source") or "none")
            row = {
                "instrument": name,
                "source": source,
                "unit": str(activity.get("unit") or "shares"),
                "volume": float(activity.get("volume") or 0.0),
                "comparable_to_thresholds": bool(activity.get("comparable_to_thresholds", True)),
                "fyers_online": bool(activity.get("fyers_online")),
                "fyers_volume_age_seconds": activity.get("fyers_volume_age_seconds"),
                "confirmation": str(activity.get("confirmation") or ""),
                "futures_available": bool(futures.get("available")),
                "futures_volume": float(futures.get("volume") or 0.0),
                "futures_oi": float(futures.get("oi") or 0.0),
                "futures_symbol": str(futures.get("tradingsymbol") or ""),
            }
            # What a feed COULD supply is not what reached the candles, and the gates
            # read the candles. During the 2026-07-27 outage the Fyers quote cache was
            # fine while the candle series was all zeros — a health check built on the
            # quote alone reports all-green through the exact failure it exists to catch.
            bars, dry = self._recent_candle_volume(name)
            row["candle_bars_checked"] = bars
            row["candle_volume_dry"] = dry
            row["degraded"] = bool(source in self._VOLUME_DEGRADED_SOURCES or dry)
            if row["degraded"]:
                degraded.append(name)
            rows[name] = row

        return {
            "instruments": rows,
            "degraded": degraded,
            "healthy": not degraded,
            # The fallback is deliberately silent in the trading path — that is the
            # point of a fallback — so "everything looks fine" is exactly how the
            # last outage hid. Say plainly which feed is actually in play.
            "summary": (
                "All indices on Fyers cash volume"
                if not degraded
                else (
                    "Volume degraded for: "
                    + ", ".join(
                        f"{n}({'candles dry' if rows[n]['candle_volume_dry'] else rows[n]['source']})"
                        for n in degraded
                    )
                )
            ),
        }

    def _alert_volume_source_degradation(self) -> None:
        """Warn once per transition when an index loses its primary volume feed."""
        try:
            # Cheap path: this runs on a timer and must never block the event loop.
            health = self.volume_source_health(probe_broker=False)
        except Exception:
            return
        previous = getattr(self, "_volume_degraded_seen", set())
        current = set(health.get("degraded") or [])
        newly = current - previous
        recovered = previous - current
        self._volume_degraded_seen = current
        for name in sorted(newly):
            row = (health.get("instruments") or {}).get(name, {})
            message = (
                f"{name} volume feed degraded to '{row.get('source')}' "
                f"(unit: {row.get('unit')}). Volume-ratio gates still work, but the "
                "cash-market series every threshold was calibrated on is gone."
            )
            logger.warning(f"📉 {message}")
            notifier = getattr(self, "on_notification", None)
            if callable(notifier):
                try:
                    notifier(message, "warning")
                except Exception:
                    pass
        for name in sorted(recovered):
            logger.info(f"📈 {name} volume feed recovered to primary cash volume.")

    def _prediction_volume_context(self, instrument: str, candle_1min: Optional[pd.DataFrame]) -> Dict[str, Any]:
        """Expose live index-volume reliability and tick activity to the read-only predictor."""
        name = str(instrument or "").upper()
        diag: Dict[str, Any] = {}
        try:
            data = getattr(self, "data", None)
            if hasattr(data, "get_index_tick_volume_diagnostics"):
                diag = (data.get_index_tick_volume_diagnostics() or {}).get(name, {}) or {}
        except Exception:
            diag = {}

        latest_volume = 0.0
        candle_tick_count = 0
        if candle_1min is not None and not candle_1min.empty:
            try:
                latest_volume = float(candle_1min.get("volume").iloc[-1] or 0.0)
            except Exception:
                latest_volume = 0.0
            try:
                if "tick_count" in candle_1min.columns:
                    candle_tick_count = int(float(candle_1min["tick_count"].iloc[-1] or 0))
            except Exception:
                candle_tick_count = 0

        # In-memory ONLY. This runs per instrument on the 1s scan interval, so calling
        # get_index_activity here meant a Fyers REST probe plus a Kite quote per index
        # EVERY SECOND, blocking the event loop — the scan cycle, the LTP worker, the
        # intel worker and the HFT monitor all wait behind it. The tick path already
        # maintains which feed supplied the last cumulative total; read that instead.
        volume_source = str(getattr(data, "_index_cum_volume_source", {}).get(name, "") or "")
        cum_volume = float(getattr(data, "_index_cum_volume", {}).get(name, 0.0) or 0.0)
        on_futures = volume_source == "kite_index_futures"

        diag_tick_count = int(float((diag or {}).get("tick_count_current_minute") or 0))
        volume_available = bool(latest_volume > 0.0 or (diag or {}).get("volume_available"))
        return {
            "instrument": name,
            "volume_available": volume_available,
            "volume_reliable": bool(latest_volume > 0.0 or (diag or {}).get("volume_reliable")),
            "volume_source": str((diag or {}).get("source") or ""),
            "volume_key": str((diag or {}).get("volume_key") or ""),
            "volume_fields": dict((diag or {}).get("volume_fields") or {}),
            "latest_1min_volume": round(latest_volume, 4),
            "tick_count_current_minute": max(diag_tick_count, candle_tick_count),
            "candle_tick_count": candle_tick_count,
            # Was hardcoded False, so the one diagnostic that could have revealed the
            # index-volume outage always reported the fallback as unavailable — even
            # once the fallback existed. Report what the provider actually resolved.
            "futures_volume_available": on_futures,
            "futures_volume": cum_volume if on_futures else 0.0,
            # Distinct from "volume_source" above, which reports the per-tick diagnostic
            # ("kite_ws"/"fyers_ws"). This is which FEED supplied the cumulative total,
            # and therefore which unit the numbers are in.
            "cumulative_volume_source": volume_source,
            "volume_unit": "contracts" if on_futures else "shares",
            "volume_comparable_to_thresholds": not on_futures,
        }

    def _log_pre_candle_prediction(self, instrument: str, timeframe: str, prediction: Dict[str, Any]) -> None:
        state = str((prediction or {}).get("state") or "")
        if state in {"", "PULLBACK_NOISE"}:
            return
        confidence = float((prediction or {}).get("confidence") or 0.0)
        if confidence < 0.50:
            return
        direction = str((prediction or {}).get("direction") or "FLAT")
        forming_start = str((prediction or {}).get("forming_start") or "")
        key = f"{str(instrument).upper()}_{str(timeframe).lower()}"
        now = time.time()
        marker = f"{forming_start}|{state}|{direction}"
        last_markers = getattr(self, "_pre_candle_prediction_last_log", {}) or {}
        last_alerts = getattr(self, "_pre_candle_prediction_last_alert_at", None)
        if last_alerts is None:
            last_alerts = {}
            self._pre_candle_prediction_last_alert_at = last_alerts
        if last_markers.get(key) == marker and now - float(last_alerts.get(key, 0.0) or 0.0) < 60.0:
            return
        self._pre_candle_prediction_last_log[key] = marker
        last_alerts[key] = now
        self.log_event(
            f"PRE-CANDLE {instrument} {timeframe}: {state} {direction} "
            f"conf {confidence:.0%} | {prediction.get('reason', '')}",
            "info",
        )

    def _build_pre_candle_predictions(
        self,
        name: str,
        mtf_result,
        intel_result: Dict[str, Any],
        candle_1min: Optional[pd.DataFrame],
        candle_5min: Optional[pd.DataFrame],
        candle_15min: Optional[pd.DataFrame],
    ) -> Dict[str, Dict[str, Any]]:
        """Build read-only forming-candle predictions for live verification."""
        predictions: Dict[str, Dict[str, Any]] = {}
        mtf_states = self._mtf_state_map(mtf_result)
        trade_context = self._prediction_trade_context(name)
        option_context = self._prediction_option_context(name)
        volume_context = self._prediction_volume_context(name, candle_1min)
        for tf, candle_tf in (("5min", candle_5min), ("15min", candle_15min)):
            intel_tf = (
                self._cached_timeframe_intel(name, tf, allow_fallback=True)
                if tf == "15min"
                else intel_result
            ) or intel_result
            prediction = build_pre_candle_prediction(
                instrument=name,
                timeframe=tf,
                candle_tf=candle_tf,
                candle_1min=candle_1min,
                candle_5min=candle_5min,
                mtf_states=mtf_states,
                intel_result=intel_tf,
                core_states=self._prediction_core_states(tf),
                trade_context=trade_context,
                option_context=option_context,
                volume_context=volume_context,
            )
            predictions[tf] = prediction
            self._log_pre_candle_prediction(name, tf, prediction)

        self._pre_candle_predictions[str(name or "").upper()] = predictions
        self._diagnostics.setdefault("pre_candle_prediction", {})[str(name or "").upper()] = {
            tf: {
                "state": item.get("state"),
                "direction": item.get("direction"),
                "confidence": item.get("confidence"),
                "progress": item.get("progress"),
                "reason": item.get("reason"),
            }
            for tf, item in predictions.items()
        }
        return predictions

    @staticmethod
    def _first_present_number(mapping, *keys) -> Optional[float]:
        """First key that EXISTS and parses to a finite number; None when none do.

        Deliberately NOT `m.get(a) or m.get(b) or default`. That idiom treats a real
        0.0 as absent, and the two are different measurements:

        - order flow is a buy/sell ratio, so 0.0 means every trade hit the sell side
          — the most bearish value the pillar can produce. `or 1.0` rewrote it as
          perfectly balanced and dropped its vote, silencing exactly the reading that
          most deserved to count;
        - a present 0.0 also fell through to the NEXT key, so a live zero could be
          answered with a stale alternate field.

        Malformed and non-finite values return None (unknown) rather than a default,
        because an unknown pillar must not vote — _peak_threat_exit_decision already
        states the rule: "'Unclear' is not 'against'". This codebase has paid for the
        opposite reading before (the 1min surge numerator read absent data as zero;
        a zero VIX read as a real measurement).
        """
        if not isinstance(mapping, dict):
            return None
        for key in keys:
            if key not in mapping:
                continue
            value = mapping.get(key)
            if value is None:
                continue
            try:
                number = float(value)
            except (TypeError, ValueError):
                logger.debug(f"Intel pillar {key}={value!r} is not a number; treated as unknown.")
                continue
            if number != number or abs(number) == float("inf"):
                logger.debug(f"Intel pillar {key}={value!r} is not finite; treated as unknown.")
                continue
            return number
        return None

    def _intel_pillar_votes(self, intel_result) -> Tuple[int, int, Optional[float], Optional[float]]:
        """(bearish, bullish, pcr_value, flow_ratio) from the OI/PCR/flow pillars.

        One definition of how the three pillars vote, so the entry reference and the
        live exit reading are always scored by the same rule. The two values are
        None when that pillar had nothing to say; an unknown pillar casts no vote in
        either direction.
        """
        if not isinstance(intel_result, dict):
            return 0, 0, None, None
        pcr = intel_result.get("pcr", {}) if isinstance(intel_result.get("pcr"), dict) else {}
        oi = intel_result.get("oi", {}) if isinstance(intel_result.get("oi"), dict) else {}
        flow = intel_result.get("order_flow", {}) if isinstance(intel_result.get("order_flow"), dict) else {}

        pcr_signal = str(pcr.get("contrarian_signal") or pcr.get("signal") or "NEUTRAL").upper()
        oi_signal = str(oi.get("signal") or "NEUTRAL").upper()
        flow_signal = str(flow.get("signal") or "NEUTRAL").upper()
        pcr_value = Scanner._first_present_number(pcr, "primary_pcr", "pcr_oi", "pcr")
        flow_ratio = Scanner._first_present_number(flow, "ratio", "buy_sell_ratio")

        bearish_votes = sum(
            [
                pcr_signal in {"BEARISH", "STRONG_BEARISH"},
                oi_signal == "BEARISH",
                flow_signal == "BEARISH" or (flow_ratio is not None and flow_ratio <= 0.85),
            ]
        )
        bullish_votes = sum(
            [
                pcr_signal in {"BULLISH", "STRONG_BULLISH"},
                oi_signal == "BULLISH",
                flow_signal == "BULLISH" or (flow_ratio is not None and flow_ratio >= 1.15),
            ]
        )
        return bearish_votes, bullish_votes, pcr_value, flow_ratio

    def _intel_adverse_votes(self, direction: str, intel_result) -> int:
        """Pillar votes AGAINST a position facing `direction`."""
        bearish, bullish, _pcr, _flow = Scanner._intel_pillar_votes(self, intel_result)
        return bullish if str(direction or "").upper() == "SHORT" else bearish

    def _intel_evidence_is_usable(self, intel_result) -> bool:
        """Whether the bundle actually carries OI/PCR/flow evidence.

        An absent option chain reads as PCR 0 with the flow ratio defaulted to 1.0,
        which scores zero votes either way — indistinguishable from a genuinely
        balanced book unless usability is asked about directly. 2026-08-12 09:15:10
        logged `PCR=0, Call Delta=0` for MIDCPNIFTY seven seconds after its entry:
        no chain had been fetched yet that session.
        """
        if not isinstance(intel_result, dict):
            return False
        pcr = intel_result.get("pcr", {}) if isinstance(intel_result.get("pcr"), dict) else {}
        oi = intel_result.get("oi", {}) if isinstance(intel_result.get("oi"), dict) else {}
        flow = intel_result.get("order_flow", {}) if isinstance(intel_result.get("order_flow"), dict) else {}
        # A PCR of exactly 0 is this codebase's own sentinel for an absent chain —
        # kite_market_data.put_call_ratio returns 0.0 for an empty frame — so it is
        # the one pillar where zero means "no evidence" rather than a reading.
        pcr_value = Scanner._first_present_number(pcr, "primary_pcr", "pcr_oi", "pcr")
        if pcr_value is not None and pcr_value > 0:
            return True
        if str(oi.get("signal") or "").upper() not in {"", "NEUTRAL"}:
            return True
        return Scanner._first_present_number(flow, "ratio", "buy_sell_ratio") is not None

    def _intel_reversal_is_new_evidence(
        self, trade_like, direction: str, intel_result
    ) -> Tuple[bool, str]:
        """Whether the book has turned against this trade SINCE it was accepted.

        OI_PCR_REVERSAL claims a reversal, so it owes a reference to have reversed
        from. Two ways it had none, both seen on 2026-08-12:

        - The entry was accepted before the day's first option chain existed
          (MIDCPNIFTY 09:15:03, `PCR=0` still at 09:15:10). The first usable reading,
          at 09:15:26, was then read as a reversal and closed the trade 24s after
          entry. It is the reference, not the trigger — so it is latched as one.
        - The book already leaned this way when the entry was accepted. The entry
          gate saw that and admitted the trade anyway; the same reading later is the
          condition it was accepted under, not a turn against it.

        Reference votes come from the entry snapshot (_entry_intel_snapshot, scored
        with the same _intel_pillar_votes rule) and otherwise from the first usable
        reading, latched onto the trade. Deteriorating evidence still exits: the
        adverse count only has to exceed the reference by one vote.
        """
        settings = get_settings()
        if not self._setting_enabled(
            getattr(settings, "intel_reversal_requires_new_evidence", True), True
        ):
            return True, ""
        # An unusable reading scores no votes anyway; leave it to the vote bar.
        if not Scanner._intel_evidence_is_usable(self, intel_result):
            return True, ""
        current = Scanner._intel_adverse_votes(self, direction, intel_result)
        entry_intel = getattr(trade_like, "entry_intel", None)
        reference = None
        source = ""
        if isinstance(entry_intel, dict) and entry_intel.get("adverse_votes") is not None:
            try:
                reference = int(entry_intel.get("adverse_votes"))
                source = "at entry"
            except (TypeError, ValueError):
                reference = None
        if reference is None:
            latched = getattr(trade_like, "_intel_reversal_baseline", None)
            if latched is None:
                try:
                    setattr(trade_like, "_intel_reversal_baseline", current)
                except Exception:
                    return True, ""
                latched = current
            try:
                reference = int(latched)
            except (TypeError, ValueError):
                return True, ""
            source = "at first reading (entry had no chain)"
        if current > reference:
            return True, ""
        return False, f"{current} adverse votes, same {reference} {source}"

    def _intel_reversal_reason(
        self,
        direction: str,
        intel_result: Optional[Dict[str, Any]],
        *,
        min_votes: Optional[int] = None,
        is_losing: bool = False,
    ) -> Optional[str]:
        if not isinstance(intel_result, dict):
            return None
        bearish_votes, bullish_votes, pcr_value, flow_ratio = Scanner._intel_pillar_votes(
            self, intel_result
        )

        direction = str(direction or "").upper()
        settings = get_settings()
        if min_votes is None:
            # Gap fix: while already losing, 2-pillar OI/PCR/flow is enough to
            # confirm reverse; winners still need full 3-vote consensus.
            if is_losing:
                min_votes = max(
                    1,
                    int(getattr(settings, "loss_guard_oi_pcr_votes_losing", 2) or 2),
                )
            else:
                min_votes = max(
                    2,
                    int(getattr(settings, "loss_guard_oi_pcr_votes_winning", 3) or 3),
                )
        min_votes = max(1, int(min_votes))

        # ── corroboration from the pillars this decision never looked at ──
        # The bundle already carries volume, regime and a divergence alert; only
        # PCR/OI/flow were ever read. Widening it by simply adding voters would be
        # wrong in BOTH directions: keeping min_votes at 2/3 while adding three more
        # ways to reach it makes every exit easier (cutting winners), and scaling
        # min_votes to 4/6 makes it unreachable for a LOSING trade, because the added
        # pillars are usually NEUTRAL — the loss-guard reversal would stop firing and
        # losers would be held longer. Both are the failure this codebase keeps
        # repeating: a threshold inherited across a change in what it measures.
        #
        # So corroboration may only move the bar in the direction that is safe:
        #   losing  + extras CONFIRM  -> exit one vote sooner  (cut the loser faster)
        #   winning + extras OPPOSE   -> demand one vote more  (protect the runner)
        # With neutral extras — the common case — behaviour is byte-identical to before.
        adjusted_min = min_votes
        corroboration = ""
        if self._setting_enabled(
            getattr(settings, "intel_reversal_corroboration_enabled", True), True
        ):
            confirm, oppose, detail = self._intel_reversal_corroboration(
                direction, intel_result
            )
            need = max(
                1, int(getattr(settings, "intel_reversal_corroboration_votes", 2) or 2)
            )
            if is_losing and confirm >= need:
                adjusted_min = max(1, min_votes - 1)
                corroboration = f" corroborated[{detail}]"
            elif not is_losing and oppose >= need:
                adjusted_min = min_votes + 1
                corroboration = f" contested[{detail}]"

        # A pillar that said nothing is reported as unknown. Printing the old
        # defaults (PCR 0.00, OFR 1.00) put a number that was never measured into
        # the exit record, which is how the absent-reads-as-zero defect stayed
        # invisible in the logs for so long.
        pcr_text = "n/a" if pcr_value is None else f"{pcr_value:.2f}"
        flow_text = "n/a" if flow_ratio is None else f"{flow_ratio:.2f}"
        if direction == "LONG" and bearish_votes >= adjusted_min:
            return (
                f"OI_PCR_REVERSAL bearish votes={bearish_votes}/{adjusted_min} "
                f"PCR={pcr_text} OFR={flow_text}{corroboration}"
            )
        if direction == "SHORT" and bullish_votes >= adjusted_min:
            return (
                f"OI_PCR_REVERSAL bullish votes={bullish_votes}/{adjusted_min} "
                f"PCR={pcr_text} OFR={flow_text}{corroboration}"
            )
        return None

    def _intel_reversal_corroboration(
        self, direction: str, intel_result: Optional[Dict[str, Any]]
    ) -> Tuple[int, int, str]:
        """(confirm, oppose, detail) from volume / regime / divergence.

        Reads only fields the bundle actually publishes — volume.signal is
        BULLISH_VOLUME|BEARISH_VOLUME|NEUTRAL, regime carries the smoothed label, and
        divergence_alert is a BOOLEAN trap flag (price rising while flow distributes),
        so it cannot vote a side. It counts toward CONFIRM only, because "price and
        flow disagree" is a reason to doubt the position, never a reason to hold it.
        """
        if not isinstance(intel_result, dict):
            return 0, 0, ""
        want_bear = str(direction or "").upper() == "LONG"
        confirm = oppose = 0
        parts = []

        vol = intel_result.get("volume") if isinstance(intel_result.get("volume"), dict) else {}
        vol_signal = str(vol.get("signal") or "NEUTRAL").upper()
        if "BEARISH" in vol_signal or "BULLISH" in vol_signal:
            vol_bear = "BEARISH" in vol_signal
            if vol_bear == want_bear:
                confirm += 1; parts.append("vol")
            else:
                oppose += 1

        reg = intel_result.get("regime") if isinstance(intel_result.get("regime"), dict) else {}
        label = str(
            reg.get("smoothed_regime") or reg.get("regime") or ""
        ).upper()
        if "DOWN" in label or "UP" in label:
            reg_bear = "DOWN" in label
            if reg_bear == want_bear:
                confirm += 1; parts.append("regime")
            else:
                oppose += 1

        if bool(intel_result.get("divergence_alert")):
            confirm += 1; parts.append("divergence")

        return confirm, oppose, "+".join(parts)

    def _intel_exit_blocked_by_trend(self, position, regime) -> bool:
        """Whether to IGNORE a contrarian OI/PCR reversal exit because the position is
        aligned with a trending regime. PCR is a mean-reversion (contrarian) indicator,
        so it fires constantly mid-trend; honouring it exits trend winners early. When
        the regime is trending in the position's own direction, ride the trend instead."""
        if not self._setting_enabled(
            getattr(get_settings(), "oi_pcr_reversal_skip_in_trend", True), True
        ):
            return False
        direction = str(getattr(position, "direction", "") or "").upper()
        side = "BUY" if direction == "LONG" else "SELL"
        return bool(is_trending_regime(regime) and regime_aligns(regime, side))

    def _request_premium_refresh(self, trade) -> None:
        """Refresh one contract's premium OFF the scanner loop.

        Mirrors the index-volume refresh, and for the same reason: the caller runs on the
        event loop, so a blocking Fyers chain plus a Kite REST LTP there stalls the scan
        cycle and every dashboard call marshalled onto that loop. Throttled per token, and
        the throttle is stamped only once a dispatch is certain -- stamping before the
        in-flight check is what starved three of four index volume refreshes.
        """
        key = str(getattr(trade, "symbol_token", "") or "")
        if not key:
            return
        now = time.time()
        try:
            ttl = float(getattr(get_settings(), "option_premium_cache_ttl_seconds", 2.0) or 2.0)
        except Exception:
            ttl = 2.0
        if now - float(self._premium_refresh_at.get(key, 0.0) or 0.0) < max(1.0, ttl):
            return
        with self._premium_refresh_guard:
            if key in self._premium_refresh_inflight:
                return
            self._premium_refresh_inflight.add(key)
            self._premium_refresh_at[key] = now
        try:
            threading.Thread(
                target=self._premium_refresh_worker,
                args=(trade, key),
                name=f"premium-{getattr(trade, 'trading_symbol', key)}",
                daemon=True,
            ).start()
        except Exception as exc:
            with self._premium_refresh_guard:
                self._premium_refresh_inflight.discard(key)
            logger.debug(f"Premium refresh dispatch failed for {key}: {exc}")

    def _premium_refresh_worker(self, trade, key: str) -> None:
        try:
            # The blocking path, run where blocking is harmless. It populates
            # _premium_cache, so the next 100ms pass reads it for free.
            self._get_live_premium_cached(trade, allow_blocking=True)
        except Exception as exc:
            logger.debug(f"Premium refresh failed for {key}: {exc}")
        finally:
            with self._premium_refresh_guard:
                self._premium_refresh_inflight.discard(key)

    def _get_live_premium_cached(self, trade, allow_blocking: bool = True) -> Optional[float]:
        if not getattr(trade, "symbol_token", "") or not getattr(trade, "trading_symbol", ""):
            return None
        settings = get_settings()
        ttl = float(getattr(settings, "option_premium_cache_ttl_seconds", 2.0))

        instrument = getattr(trade, "instrument", "")
        market_info = getattr(self, "market_info", {}).get(instrument, {})
        is_monthly = market_info.get("is_monthly_week", False) or instrument in {"BANKNIFTY", "MIDCPNIFTY"}
        is_rollover = market_info.get("is_monthly_rollover") if is_monthly else market_info.get("is_weekly_rollover")

        max_quote_age_current = float(getattr(settings, "option_contract_quote_max_age_seconds", 10.0) or 10.0)
        max_quote_age_next = float(getattr(settings, "option_contract_quote_max_age_next_expiry_seconds", 30.0) or 30.0)
        max_quote_age = max_quote_age_next if is_rollover else max_quote_age_current
        key = trade.symbol_token
        now = time.time()
        cached = self._premium_cache.get(key)
        if cached and now - cached.get("time", 0.0) <= ttl:
            cached_price = float(cached.get("price") or 0.0)
            if self._option_premium_quote_plausible(trade, cached_price):
                return cached_price
            self._premium_cache.pop(key, None)
        exchange = "BFO" if "SENSEX" in trade.trading_symbol.upper() else "NFO"

        # Subscribe as soon as a tradeable contract is resolved. The method is
        # idempotent, so later scans do not spam duplicate subscriptions.
        subscribe = getattr(self.data, "subscribe_tokens", None)
        if callable(subscribe):
            try:
                subscribe([str(trade.symbol_token)], exchange_type=3 if exchange == "BFO" else 2)
            except Exception as exc:
                logger.debug(f"Contract quote subscription failed for {trade.trading_symbol}: {exc}")

        # Fresh contract ticks/cache are authoritative and involve no network I/O.
        cached_contract = getattr(self.data, "get_cached_contract_ltp", None)
        if callable(cached_contract):
            try:
                price = float(
                    cached_contract(
                        exchange,
                        trade.trading_symbol,
                        trade.symbol_token,
                        max_age_seconds=max_quote_age,
                    )
                    or 0.0
                )
            except Exception as exc:
                logger.debug(f"Cached contract quote failed for {trade.trading_symbol}: {exc}")
                price = 0.0
            if price > 0 and self._option_premium_quote_plausible(trade, price):
                self._premium_cache[key] = {"price": price, "time": now}
                setattr(trade, "quote_source", "contract_ws_cache")
                setattr(trade, "quote_verified", True)
                return price

        # Everything above is memory-only. Everything below makes an HTTPS call, so on
        # the 100ms trade-monitor path it is dispatched off-thread instead: the caller
        # gets no premium THIS pass and a fresh one within a couple of seconds, rather
        # than the whole event loop waiting on Fyers.
        if not allow_blocking:
            self._request_premium_refresh(trade)
            return None

        # An exact active-expiry Fyers chain is the next live source. It must be
        # attempted before the synchronous Angel REST endpoint.
        chain_price = self._get_option_chain_premium(trade, max_age_seconds=max_quote_age)
        if chain_price and chain_price > 0 and self._option_premium_quote_plausible(trade, chain_price):
            self._premium_cache[key] = {"price": float(chain_price), "time": now}
            setattr(trade, "quote_source", "fyers_option_chain_exact")
            setattr(trade, "quote_verified", True)
            return float(chain_price)

        # Last resort: guarded, single-flight Angel REST. This path yields when
        # an order/exit/stop/position call is active or waiting.
        try:
            price = self.data.get_ltp(exchange, trade.trading_symbol, trade.symbol_token)
            if price and price > 0:
                price = float(price)
                quote_age = self._contract_quote_age_seconds(trade, now)
                if quote_age is not None and quote_age > max_quote_age:
                    self._log_stale_option_premium_once(trade, price, quote_age)
                elif self._option_premium_quote_plausible(trade, price):
                    self._premium_cache[key] = {"price": price, "time": now}
                    setattr(trade, "quote_source", "broker_contract_ltp")
                    setattr(trade, "quote_verified", True)
                    return price
                else:
                    self._log_bad_option_premium_once(trade, price, "live premium fetch")
        except Exception as e:
            logger.debug(f"Premium fetch failed for {trade.trading_symbol}: {e}")
        return None

    def _candidate_entry_mark_refusal(self, candidate) -> str:
        """Refuse an accepted OPT candidate whose recorded premium is no longer real.

        The real-order path reprices at execution — _execution_levels replaces the
        candidate's premium with _get_live_premium_cached before the order is built — and
        TradeManager.open_trade then validates the mark. The MANUAL path does neither: it
        stamps accepted_by_gate on the candidate as-is, and every P&L figure downstream is
        computed from that recorded price.

        2026-08-11 15:09:36: NIFTY 24500PE was accepted at 133.00 while spot stood at
        24453.65. On a same-day-expiry PE that strike is worth its intrinsic Rs.46, and
        the contract's true price was 40.65 — the mark was ~2.5 hours stale (the same
        contract legitimately printed 133 at 12:25, when spot was lower). Stop, target and
        R:R were all derived from it, EARLY_LOSS_CUT read a 13.89R loss 190 MILLISECONDS
        later, and the book took -Rs.6,083 that the market never charged.

        Two conditions, because either alone gives false refusals: the premium must
        diverge by a large FRACTION, and the gap must be material in RUPEES so a cheap
        contract ticking 5 paise is not treated as a stale mark.
        """
        settings = get_settings()
        if not self._setting_enabled(
            getattr(settings, "candidate_entry_mark_validation_enabled", True), True
        ):
            return ""
        if str(getattr(candidate, "inst_type", "") or "").upper() != "OPT":
            return ""
        try:
            mark = float(getattr(candidate, "price", 0.0) or 0.0)
        except (TypeError, ValueError):
            return ""
        if mark <= 0:
            return ""
        try:
            # Non-blocking: this runs inside the scan loop, and a missing quote must
            # cost the check rather than the cycle.
            fresh = self._get_live_premium_cached(candidate, allow_blocking=False)
        except Exception as exc:
            logger.debug(f"Entry-mark refresh failed for {getattr(candidate,'trading_symbol','')}: {exc}")
            return ""
        try:
            fresh = float(fresh or 0.0)
        except (TypeError, ValueError):
            return ""
        if fresh <= 0:
            # No opinion is not evidence of a good mark, but refusing on a missing quote
            # would stop trading whenever the feed hiccups.
            return ""
        qty = max(
            1,
            int(getattr(candidate, "lots", 0) or 0) * int(getattr(candidate, "lot_size", 0) or 0),
        )
        divergence = abs(mark - fresh) / mark
        gap_rs = abs(mark - fresh) * qty
        try:
            max_pct = float(
                getattr(settings, "candidate_entry_mark_max_divergence_pct", 25.0) or 25.0
            ) / 100.0
            min_gap = float(
                getattr(settings, "candidate_entry_mark_min_gap_rs", 500.0) or 500.0
            )
        except (TypeError, ValueError):
            max_pct, min_gap = 0.25, 500.0
        if max_pct > 0 and divergence > max_pct and gap_rs >= min_gap:
            return (
                f"entry mark {mark:.2f} is {divergence:.0%} from the live premium "
                f"{fresh:.2f} on {getattr(candidate, 'trading_symbol', '') or 'OPT'} "
                f"(Rs.{gap_rs:,.0f} of phantom P&L)"
            )
        return ""

    def _candidate_execution_touch_quote(self, candidate: TradeCandidate) -> Dict[str, Any]:
        """Best-effort executable bid/ask quote; never changes signal scoring."""
        if str(getattr(candidate, "inst_type", "") or "").upper() != "OPT":
            return {}
        trading_symbol = str(getattr(candidate, "trading_symbol", "") or "")
        token = str(getattr(candidate, "symbol_token", "") or "")
        if not trading_symbol or not token or not hasattr(self.data, "get_contract_touch_quote"):
            return {}
        try:
            settings = get_settings()
            max_age = float(getattr(settings, "execution_touch_quote_max_age_seconds", 1.5) or 1.5)
            exchange = "BFO" if "SENSEX" in trading_symbol.upper() else "NFO"
            quote = self.data.get_contract_touch_quote(exchange, trading_symbol, token, max_age_seconds=max_age)
            if not isinstance(quote, dict):
                quote = {}
        except Exception as exc:
            logger.debug(f"Touch quote refresh failed for {trading_symbol}: {exc}")
            quote = {}
        setattr(candidate, "execution_bid_price", float(quote.get("bid") or 0.0))
        setattr(candidate, "execution_ask_price", float(quote.get("ask") or 0.0))
        setattr(candidate, "execution_touch_source", str(quote.get("source") or ""))
        setattr(candidate, "execution_touch_age_seconds", float(quote.get("age_seconds") or 0.0))
        setattr(candidate, "execution_touch_usable", bool(quote.get("usable", False)))
        setattr(candidate, "execution_touch_reason", str(quote.get("reason") or ""))
        return quote

    @staticmethod
    def _cache_time_age_seconds(value, now: Optional[float] = None) -> Optional[float]:
        if value is None:
            return None
        now_ts = time.time() if now is None else float(now)
        if isinstance(value, datetime):
            ts = value.timestamp()
        else:
            try:
                ts = float(value)
            except (TypeError, ValueError):
                return None
        return max(0.0, now_ts - ts)

    def _contract_quote_age_seconds(self, trade, now: Optional[float] = None) -> Optional[float]:
        data = getattr(self, "data", None)
        if data is None:
            return None
        now_ts = time.time() if now is None else float(now)
        token = str(getattr(trade, "symbol_token", "") or "").strip()
        symbol = str(getattr(trade, "trading_symbol", "") or "").strip()
        ages = []
        ws_cache = getattr(data, "_ws_cache", {}) or {}
        for key in dict.fromkeys([token, token[3:] if token.startswith("999") else token, symbol]):
            cached = ws_cache.get(key)
            if isinstance(cached, dict) and float(cached.get("ltp", 0.0) or 0.0) > 0:
                age = self._cache_time_age_seconds(cached.get("time"), now_ts)
                if age is not None:
                    ages.append(age)
        ltp_cache = getattr(data, "_ltp_cache", {}) or {}
        for key in dict.fromkeys([symbol, token]):
            cached = ltp_cache.get(key)
            if isinstance(cached, dict) and float(cached.get("ltp", 0.0) or 0.0) > 0:
                age = self._cache_time_age_seconds(cached.get("time"), now_ts)
                if age is not None:
                    ages.append(age)
        return min(ages) if ages else None

    @staticmethod
    def _normalize_contract_symbol(value) -> str:
        text = str(value or "").upper().strip()
        return text.split(":", 1)[1] if ":" in text else text

    def _candidate_matches_active_option_contract(
        self,
        trade,
        instrument: str,
        option_type: str,
        strike: float,
    ) -> Optional[bool]:
        """Validate the Angel contract against the locally selected active expiry."""
        resolver = getattr(getattr(self, "data", None), "get_option_token", None)
        if not callable(resolver):
            return None
        try:
            resolved = resolver(instrument, strike, option_type)
        except Exception:
            return None
        if not isinstance(resolved, dict) or not resolved:
            return None
        expected_token = str(getattr(trade, "symbol_token", "") or "").strip()
        expected_symbol = self._normalize_contract_symbol(getattr(trade, "trading_symbol", ""))
        resolved_token = str(resolved.get("token") or resolved.get("symbol_token") or "").strip()
        resolved_symbol = self._normalize_contract_symbol(
            resolved.get("symbol") or resolved.get("trading_symbol") or resolved.get("tradingsymbol")
        )
        token_match = bool(expected_token and resolved_token and expected_token == resolved_token)
        symbol_match = bool(expected_symbol and resolved_symbol and expected_symbol == resolved_symbol)
        return token_match or symbol_match

    def _get_option_chain_premium(
        self,
        trade,
        max_age_seconds: float = 10.0,
    ) -> Optional[float]:
        """Fallback to broker option-chain LTP when direct contract LTP is absent."""
        data = getattr(self, "data", None)
        if data is None:
            return None
        instrument = str(getattr(trade, "instrument", "") or "").upper()
        option_type = str(getattr(trade, "option_type", "") or "").upper()
        strike = float(getattr(trade, "atm_strike", 0.0) or 0.0)
        if not instrument or option_type not in {"CE", "PE"} or strike <= 0:
            return None
        exchange = "BFO" if instrument == "SENSEX" else "NFO"
        direct_price = self._get_fyers_option_chain_premium_direct(trade, instrument, option_type, strike)
        if direct_price and direct_price > 0:
            return direct_price

        cached_getter = getattr(data, "get_cached_option_chain", None)
        try:
            if callable(cached_getter):
                chain = cached_getter(instrument, max_age_seconds=max_age_seconds)
            else:
                # Compatibility for light test/fallback providers. The production
                # provider never enters its Angel option-chain REST path here.
                chain_getter = getattr(data, "get_option_chain", None)
                if not callable(chain_getter):
                    return None
                chain = chain_getter(instrument, exchange)
        except Exception as exc:
            logger.debug(
                "Option-chain premium fallback failed for {} {} {:.0f}: {}",
                instrument,
                option_type,
                strike,
                exc,
            )
            return None
        if chain is None or getattr(chain, "empty", True):
            return None
        try:
            rows = chain[chain["strike"].astype(float).sub(strike).abs() < 0.01]
            if rows.empty:
                return None
            column = "call_ltp" if option_type == "CE" else "put_ltp"
            exact_row = self._option_chain_rows_match_contract(rows, trade, option_type)
            active_contract = self._candidate_matches_active_option_contract(
                trade, instrument, option_type, strike
            )
            if not exact_row and not (callable(cached_getter) and active_contract is True):
                logger.debug(
                    "Skipping strike-only option-chain fallback for {} {} {:.0f}; exact contract not present",
                    instrument,
                    option_type,
                    strike,
                )
                return None
            price = float(rows.iloc[0].get(column, 0.0) or 0.0)
            return price if price > 0 else None
        except Exception as exc:
            logger.debug(
                "Option-chain premium parse failed for {} {} {:.0f}: {}",
                instrument,
                option_type,
                strike,
                exc,
            )
            return None

    def _get_fyers_option_chain_premium_direct(
        self,
        trade,
        instrument: str,
        option_type: str,
        strike: float,
    ) -> Optional[float]:
        data = getattr(self, "data", None)
        fyers = getattr(data, "fyers", None)
        fyers_symbol = FYERS_INDEX_SYMBOLS.get(instrument)
        if fyers is None or not fyers_symbol:
            return None
        active_contract = self._candidate_matches_active_option_contract(
            trade, instrument, option_type, strike
        )
        if active_contract is False:
            return None
        try:
            from engine.expiry_manager import expiry_manager

            if not getattr(expiry_manager, "expiries", None):
                expiry_manager.pre_market_check()
            expiry_key = (
                "active_monthly"
                if instrument in {"BANKNIFTY", "MIDCPNIFTY"}
                else "active_weekly"
            )
            active_label = (
                expiry_manager.expiries.get(instrument, {}).get(expiry_key)
                if getattr(expiry_manager, "expiries", None)
                else ""
            )
            if not active_label:
                return None
            base_request = {"symbol": fyers_symbol, "strikecount": 30, "timestamp": ""}
            response = fyers.optionchain(data=base_request)
            expiry_timestamp = ""
            active_date = ""
            if active_label:
                active_date = datetime.strptime(active_label, "%d%b%Y").strftime("%d-%m-%Y")
            for expiry_row in (response or {}).get("data", {}).get("expiryData", []) or []:
                if str(expiry_row.get("date") or "") == active_date:
                    expiry_timestamp = str(expiry_row.get("expiry") or "")
                    break
            if not expiry_timestamp:
                return None
            response = fyers.optionchain(
                data={
                    "symbol": fyers_symbol,
                    "strikecount": 30,
                    "timestamp": expiry_timestamp,
                }
            )
            rows = (response or {}).get("data", {}).get("optionsChain", []) or []
            for row in rows:
                try:
                    if (
                        abs(float(row.get("strike_price") or 0.0) - strike) < 0.01
                        and str(row.get("option_type") or "").upper() == option_type
                        and (
                            active_contract is True
                            or self._option_chain_row_matches_contract(row, trade)
                        )
                    ):
                        price = float(row.get("ltp") or 0.0)
                        return price if price > 0 else None
                except Exception:
                    continue
        except Exception as exc:
            logger.debug(
                "Direct Fyers option-chain premium fetch failed for {} {} {:.0f}: {}",
                instrument,
                option_type,
                strike,
                exc,
            )
        return None

    @staticmethod
    def _option_chain_row_matches_contract(row, trade) -> bool:
        def _norm_symbol(value) -> str:
            text = str(value or "").upper().strip()
            if ":" in text:
                text = text.split(":", 1)[1]
            return text

        expected_symbol = _norm_symbol(getattr(trade, "trading_symbol", ""))
        expected_token = str(getattr(trade, "symbol_token", "") or "").strip()
        if hasattr(row, "get"):
            symbol = _norm_symbol(row.get("symbol") or row.get("trading_symbol") or row.get("tradingsymbol") or "")
            token = str(row.get("token") or row.get("symbol_token") or row.get("fyToken") or "").strip()
        else:
            symbol = token = ""
        if expected_token and token and token == expected_token:
            return True
        if expected_symbol and symbol and symbol == expected_symbol:
            return True
        return False

    def _option_chain_rows_match_contract(self, rows, trade, option_type: str) -> bool:
        option_prefix = "call" if option_type == "CE" else "put"
        for _idx, row in rows.iterrows():
            row_dict = row.to_dict()
            symbol = (
                row_dict.get(f"{option_prefix}_symbol")
                or row_dict.get(f"{option_prefix}_trading_symbol")
                or row_dict.get(f"{option_prefix}_tradingsymbol")
                or row_dict.get("symbol")
                or row_dict.get("trading_symbol")
                or row_dict.get("tradingsymbol")
            )
            token = (
                row_dict.get(f"{option_prefix}_token")
                or row_dict.get(f"{option_prefix}_symbol_token")
                or row_dict.get("token")
                or row_dict.get("symbol_token")
            )
            if self._option_chain_row_matches_contract({"symbol": symbol, "token": token}, trade):
                return True
        return False

    def _option_premium_quote_plausible(self, trade, premium: float) -> bool:
        """Reject option quotes that are clearly underlying/index prices."""
        try:
            premium = float(premium or 0.0)
        except (TypeError, ValueError):
            return False
        if premium <= 0:
            return False
        inst_type = str(getattr(trade, "inst_type", "") or "").upper()
        symbol = str(getattr(trade, "trading_symbol", "") or "").upper()
        if inst_type != "OPT" and "CE" not in symbol and "PE" not in symbol:
            return True

        entry = float(getattr(trade, "entry_price", getattr(trade, "price", 0.0)) or 0.0)
        target = float(getattr(trade, "target", 0.0) or 0.0)
        spot = (
            float(self.candles.get_latest_price(getattr(trade, "instrument", "")) or 0.0)
            if hasattr(self, "candles")
            else 0.0
        )
        if spot <= 0:
            spot = float(getattr(trade, "entry_spot", 0.0) or 0.0)
        strike = float(getattr(trade, "atm_strike", 0.0) or 0.0)
        opt_type = str(getattr(trade, "option_type", "") or "").upper()
        intrinsic = 0.0
        if spot > 0 and strike > 0:
            intrinsic = max(0.0, spot - strike) if opt_type == "CE" else max(0.0, strike - spot)

        bounds = [1000.0]
        if entry > 0:
            bounds.append(entry * 4.0)
        if target > 0:
            bounds.append(target * 3.0)
        if spot > 0:
            bounds.append((intrinsic or 0.0) + spot * 0.05)
            bounds.append(spot * 0.12)
        upper_bound = max(bounds)
        return premium <= upper_bound

    def _sanitize_option_mark(self, trade, premium: float, spot: float, source: str) -> float:
        """Keep every option mark in premium space before P&L or exit logic sees it."""
        premium = float(premium or 0.0)
        if self._option_premium_quote_plausible(trade, premium):
            return premium

        self._log_bad_option_premium_once(trade, premium, source)
        entry = float(getattr(trade, "entry_price", getattr(trade, "price", 0.0)) or 0.0)
        entry_spot = float(getattr(trade, "entry_spot", 0.0) or 0.0)
        multiplier = float(getattr(trade, "instrument_multiplier", 0.0) or 0.0)
        if entry > 0 and entry_spot > 0 and spot > 0 and multiplier != 0:
            fallback = max(0.05, entry + ((float(spot) - entry_spot) * multiplier))
            if self._option_premium_quote_plausible(trade, fallback):
                return fallback
        return max(0.05, entry)

    def _active_option_decision_mark(
        self,
        trade,
        spot: float,
        real_premium: Optional[float],
    ) -> Tuple[float, str, bool]:
        """Resolve live option mark for exit/trailing when contract LTP is delayed."""
        settings = get_settings()
        synthetic = (
            self._synthetic_option_mark(trade, float(spot))
            if float(getattr(trade, "entry_spot", 0.0) or 0.0) > 0
            else float(getattr(trade, "entry_price", 0.0) or 0.0)
        )
        synthetic = self._sanitize_option_mark(trade, synthetic, float(spot), "synthetic option decision mark")
        real = float(real_premium or 0.0)
        real_ok = real > 0 and self._option_premium_quote_plausible(trade, real)
        if not self._setting_enabled(getattr(settings, "option_internal_mark_on_stale_quote", True), True):
            return (real if real_ok else synthetic), "broker_contract_ltp" if real_ok else "synthetic_option_mark", real_ok
        if not real_ok:
            return synthetic, "synthetic_option_mark_no_contract_ltp", False

        quote_age = self._contract_quote_age_seconds(trade)
        max_age = max(
            0.25,
            float(getattr(settings, "option_internal_mark_quote_age_seconds", 3.0) or 3.0),
        )
        if quote_age is None or quote_age <= max_age:
            return real, "broker_contract_ltp", True

        min_diff_points = max(
            0.0,
            float(getattr(settings, "option_internal_mark_min_diff_points", 1.0) or 0.0),
        )
        min_diff_pct = max(
            0.0,
            float(getattr(settings, "option_internal_mark_min_diff_pct", 0.5) or 0.0),
        )
        min_diff = max(min_diff_points, real * (min_diff_pct / 100.0))
        if abs(synthetic - real) < min_diff:
            return real, "broker_contract_ltp_stale_but_close", True

        marker = f"{getattr(trade, 'id', '')}|{int(quote_age)}|{real:.2f}|{synthetic:.2f}"
        if getattr(trade, "_last_internal_mark_log", "") != marker:
            setattr(trade, "_last_internal_mark_log", marker)
            self.log_event(
                f"Using internal option mark for {trade.instrument} {getattr(trade, 'timeframe', '')}: "
                f"broker LTP {real:.2f} age {quote_age:.1f}s, internal {synthetic:.2f}.",
                "info",
            )
        return synthetic, "synthetic_option_mark_stale_contract_ltp", False

    def _allow_inferred_signal_recovery(self) -> bool:
        """Actual trades recover from SQLite/broker state, never from a chart arrow."""
        return False

    def _log_bad_option_premium_once(self, trade, premium: float, source: str) -> None:
        key = (
            f"{getattr(trade, 'instrument', '')}|{getattr(trade, 'trading_symbol', '')}|"
            f"{getattr(trade, 'symbol_token', '')}|{int(float(premium or 0.0))}|bad-option-premium"
        )
        self.log_signal_decision_once(
            key,
            (
                f"Bad option LTP ignored: {getattr(trade, 'instrument', '')} "
                f"{getattr(trade, 'trading_symbol', '')} returned {float(premium):.2f} from {source}; "
                "treated as instrument mismatch/underlying-price contamination"
            ),
            "warning",
        )

    def _log_stale_option_premium_once(self, trade, premium: float, age_seconds: float) -> None:
        key = (
            f"{getattr(trade, 'instrument', '')}|{getattr(trade, 'trading_symbol', '')}|"
            f"{getattr(trade, 'symbol_token', '')}|stale-option-premium"
        )
        self.log_signal_decision_once(
            key,
            (
                f"Stale option LTP ignored: {getattr(trade, 'instrument', '')} "
                f"{getattr(trade, 'trading_symbol', '')} returned {float(premium):.2f} "
                f"but quote age is {float(age_seconds):.1f}s"
            ),
            "warning",
        )

    def _get_live_fut_ltp_cached(self, trade) -> Optional[float]:
        if not getattr(trade, "symbol_token", "") or not getattr(trade, "trading_symbol", ""):
            return None
        ttl = 2.0
        key = f"FUT:{trade.symbol_token}"
        now = time.time()
        cached = self._candidate_ltp_cache.get(key)
        if cached and now - cached.get("time", 0.0) <= ttl:
            return cached.get("price")

        exchange = "BFO" if "SENSEX" in trade.trading_symbol.upper() else "NFO"
        try:
            price = self.data.get_ltp(exchange, trade.trading_symbol, trade.symbol_token)
            if price and price > 0:
                self._candidate_ltp_cache[key] = {"price": float(price), "time": now}
                return float(price)
        except Exception as e:
            logger.debug(f"FUT LTP fetch failed for {trade.trading_symbol}: {e}")
        return cached.get("price") if cached else None

    def _configured_option_sl_pct(self) -> float:
        """Current per-trade option premium SL cap, preferring scanner state."""
        settings = get_settings()
        for source in (
            getattr(self, "options_sl_pct", None),
            getattr(getattr(self, "trades", None), "options_sl_pct", None),
            getattr(settings, "options_sl_pct", 15.0),
        ):
            try:
                value = float(source)
            except (TypeError, ValueError):
                continue
            if value > 0:
                return value
        return 15.0

    @staticmethod
    def _trade_like_entry_price(trade_like) -> float:
        try:
            return float(
                getattr(
                    trade_like,
                    "price",
                    getattr(trade_like, "entry_price", 0.0),
                )
                or 0.0
            )
        except Exception:
            return 0.0

    @staticmethod
    def _trade_like_quantity(trade_like) -> int:
        try:
            quantity = int(getattr(trade_like, "quantity", 0) or 0)
            if quantity > 0:
                return quantity
        except Exception:
            pass
        try:
            return max(
                1,
                int(getattr(trade_like, "lots", 1) or 1)
                * int(getattr(trade_like, "lot_size", 1) or 1),
            )
        except Exception:
            return 1

    @staticmethod
    def _trade_like_price_direction(trade_like) -> str:
        if str(getattr(trade_like, "inst_type", "") or "").upper() == "OPT":
            return "LONG"
        return str(getattr(trade_like, "direction", "LONG") or "LONG").upper()

    @staticmethod
    def _risk_stop_valid(entry: float, stop: float, direction: str) -> bool:
        try:
            entry = float(entry or 0.0)
            stop = float(stop or 0.0)
        except Exception:
            return False
        if entry <= 0 or stop <= 0:
            return False
        if str(direction or "LONG").upper() == "SHORT":
            return stop > entry
        return stop < entry

    def _derived_initial_stop(self, trade_like) -> float:
        """Recover the immutable entry-risk stop for old/restored rows.

        Session rows and real trades both mutate their active stop while trailing.
        Profit-lock logic must use the original risk stop; otherwise a tightened
        stop above entry collapses R and creates tiny "smart profit" scalps.
        """
        entry = self._trade_like_entry_price(trade_like)
        if entry <= 0:
            return 0.0
        direction = self._trade_like_price_direction(trade_like)
        for attr in ("initial_stop", "trailing_stop", "stop", "current_stop"):
            try:
                stop = float(getattr(trade_like, attr, 0.0) or 0.0)
            except Exception:
                stop = 0.0
            if self._risk_stop_valid(entry, stop, direction):
                return stop

        inst_type = str(getattr(trade_like, "inst_type", "") or "").upper()
        if inst_type == "OPT":
            try:
                risk = self._option_premium_stop_distance_for_candidate(entry, trade_like)
            except Exception:
                risk = entry * (self._configured_option_sl_pct() / 100.0)
        else:
            try:
                risk = entry * (float(getattr(self, "futures_sl_pct", 0.2) or 0.2) / 100.0)
            except Exception:
                risk = entry * 0.002
        risk = max(0.05, float(risk or 0.0))
        return entry + risk if direction == "SHORT" else max(0.05, entry - risk)

    def _ensure_trade_like_initial_stop(self, trade_like) -> float:
        entry = self._trade_like_entry_price(trade_like)
        direction = self._trade_like_price_direction(trade_like)
        try:
            initial = float(getattr(trade_like, "initial_stop", 0.0) or 0.0)
        except Exception:
            initial = 0.0
        if not self._risk_stop_valid(entry, initial, direction):
            initial = self._derived_initial_stop(trade_like)
            try:
                setattr(trade_like, "initial_stop", float(initial or 0.0))
            except Exception:
                pass
        return float(initial or 0.0)

    def _profit_ladder_pnl(self, trade_like, peak_pnl: float, qty=None) -> float:
        """The peak figure the Rs.3,000 profit tiers should be READ on.

        The ladder's rungs were tuned on single-lot trades, so on a 3-lot position a
        Rs.3,000 peak is Rs.1,000 PER LOT -- a modest win treated as a major one.
        profit_lock_per_lot_basis rescales it, but only _profit_lock_floor and
        _profit_lock_arm_cap_rs honoured the flag. Four other consumers compared the RAW
        whole-position peak against the same Rs.3,000 rung, so a 3-lot trade peaking at
        Rs.4,500 was SMART_PROFIT_LOCK in one place and MAJOR_WIN_GUARD in another.

        Default OFF, so this returns peak_pnl unchanged unless the operator opts in.
        """
        try:
            peak = float(peak_pnl or 0.0)
        except (TypeError, ValueError):
            return 0.0
        try:
            if not self._setting_enabled(
                getattr(get_settings(), "profit_lock_per_lot_basis", False), False
            ):
                return peak
            counter = getattr(self, "_profit_lock_lot_count", None)
            lots = (
                counter(trade_like, qty)
                if callable(counter)
                else Scanner._profit_lock_lot_count(trade_like, qty)
            )
            return peak / float(lots) if lots > 1 else peak
        except Exception:
            return peak

    def _trade_like_initial_risk_rs(
        self,
        trade_like,
        qty: Optional[int] = None,
        inst_mult: float = 1.0,
    ) -> float:
        # A scaled-in trade carries the rupee risk it committed at ENTRY. Recomputing it
        # from the weighted-average entry would move the stop distance and therefore
        # redefine 1R: a trade up 1.5R reads as 0.9R the instant lots are added, and every
        # R-based exit rule changes behaviour because of a sizing decision rather than
        # anything the market did. Only set once a trade has actually scaled in.
        # `qty is None` alone made the freeze unreachable: BOTH hot callers pass qty
        # explicitly (the live exit ladders and the session ladder), so 1R silently
        # re-based on every scaled-in trade -- exactly what the comment above says must
        # not happen. Honour it whenever the caller is asking about the WHOLE position;
        # a genuine partial-quantity question still recomputes.
        frozen = float(getattr(trade_like, "frozen_initial_risk_rs", 0.0) or 0.0)
        if frozen > 0:
            try:
                whole = int(self._trade_like_quantity(trade_like) or 0)
            except Exception:
                whole = 0
            if qty is None or (whole > 0 and int(qty or 0) == whole):
                return frozen

        entry = self._trade_like_entry_price(trade_like)
        initial = self._ensure_trade_like_initial_stop(trade_like)
        if entry <= 0 or initial <= 0:
            return 0.0
        if qty is None:
            qty = self._trade_like_quantity(trade_like)
        try:
            mult = float(inst_mult or 1.0)
        except Exception:
            mult = 1.0
        if str(getattr(trade_like, "inst_type", "") or "").upper() == "OPT":
            mult = 1.0
        return abs(entry - initial) * max(1, int(qty or 1)) * max(0.0, mult)

    def _candidate_market_regime(self, candidate: TradeCandidate) -> str:
        regime = str(getattr(candidate, "market_regime", "") or "").strip()
        if regime:
            return regime
        try:
            return str(getattr(self, "latest_regimes", {}).get(candidate.instrument, "") or "")
        except Exception:
            return ""

    def _option_premium_stop_distance_for_candidate(
        self,
        premium: float,
        candidate: TradeCandidate,
    ) -> float:
        """Dynamic option premium stop distance under the configured per-trade cap.

        The operator setting is the normal premium-space cap (15% in current config).
        Existing signal-state overrides can tighten it: volume-spike entries use
        their dedicated tight stop, and expiry gamma windows can cap it further.
        """
        premium = float(premium or 0.0)
        if premium <= 0:
            return 0.0

        if (
            bool(getattr(candidate, "volume_spike_entry", False))
            or bool(getattr(candidate, "late_session_reclaim_entry", False))
            or bool(getattr(candidate, "one_way_cascade_entry", False))
            or bool(getattr(candidate, "missed_signal_reentry", False))
        ):
            tight_stop_pct = float(getattr(candidate, "tight_stop_pct", 0.0) or 0.0)
            if tight_stop_pct <= 0:
                setting_name = (
                    "one_way_cascade_options_sl_pct"
                    if bool(getattr(candidate, "one_way_cascade_entry", False))
                    else
                    "missed_signal_reentry_options_sl_pct"
                    if bool(getattr(candidate, "missed_signal_reentry", False))
                    else
                    "late_session_reclaim_options_sl_pct"
                    if bool(getattr(candidate, "late_session_reclaim_entry", False))
                    else "volume_spike_entry_options_sl_pct"
                )
                tight_stop_pct = float(getattr(get_settings(), setting_name, 5.0) or 5.0)
            return max(0.5, premium * (tight_stop_pct / 100.0))

        opt_sl_pct = Scanner._configured_option_sl_pct(self)

        # Keep the legacy choppy/ranging breathing behavior from SignalProcessor,
        # but only after the saved setting has been corrected to mean per-trade SL.
        regime = Scanner._candidate_market_regime(self, candidate)
        if is_risky_regime(regime):
            opt_sl_pct = max(opt_sl_pct, 15.0)

        # The expiry-day gamma clamp is applied LAST so it actually binds. It used to sit
        # above the risky-regime floor, which then raised the stop straight back to 15% —
        # and a choppy/ranging read is the normal condition on a 0DTE afternoon, i.e. the
        # tightening was discarded on exactly the trades it was written for. Wider is not
        # safer here: an expiring option decays to zero regardless, so a loose stop just
        # means more of the premium is gone before the exit fires.
        try:
            if self.expiry.in_gamma_window(candidate.instrument, self._session_squareoff_clock()):
                gamma_sl = float(getattr(get_settings(), "expiry_day_gamma_sl_pct", 10.0) or 10.0)
                opt_sl_pct = min(opt_sl_pct, gamma_sl)
        except Exception:
            pass
        return max(0.5, premium * (opt_sl_pct / 100.0))

    def _execution_levels(self, candidate: TradeCandidate) -> Tuple[float, float, float]:
        """Resolve contract-space entry, stop, and target levels for execution."""
        entry = float(candidate.price or 0.0)
        stop = float(candidate.stop or 0.0)
        target = float(candidate.target or 0.0)
        inst_type = str(getattr(candidate, "inst_type", "FUT") or "FUT").upper()

        if inst_type == "OPT":
            live_premium = self._get_live_premium_cached(candidate)
            if not live_premium or live_premium <= 0:
                self.log_signal_decision_once(
                    (
                        f"{candidate.instrument}|{candidate.timeframe}|"
                        f"{candidate.trading_symbol}|option-entry-quote-unavailable"
                    ),
                    (
                        f"Option execution blocked: {candidate.instrument} "
                        f"{candidate.trading_symbol} has no verified live premium"
                    ),
                    "warning",
                )
                return 0.0, 0.0, 0.0
            entry = float(live_premium)
            # Fast volume-spike entries ride a tight, premium-space stop with an
            # RR-based target off that tight risk (not the spot-derived target move),
            # so the protective stop matches the spike's stabilization sizing.
            risk = Scanner._option_premium_stop_distance_for_candidate(self, entry, candidate)
            # Keep the candidate's ATR-aware per-timeframe stop. SignalProcessor bounds
            # the premium stop to 4-10% (5min) / 6-15% (15min) with OPTION_STOP_TF_ATR_AWARE
            # on, and _option_premium_stop_distance_for_candidate has no ATR or timeframe
            # term at all — it returns the flat 15% cap. Recomputing here therefore threw
            # the graded stop away and sent every live option order out on the widest
            # allowed risk, up to 3.75x what the policy chose. The FUT branch below does
            # not do this: it preserves candidate risk_distance verbatim.
            #
            # min(), not replace: the execution-time function also applies the volume-spike
            # and expiry-gamma tightenings, and those must still bind. This can only make
            # the stop TIGHTER than the cap, never wider.
            cand_price = float(candidate.price or 0.0)
            cand_stop = float(candidate.stop or 0.0)
            if cand_price > 0 and 0.0 < cand_stop < cand_price:
                risk = min(risk, entry * ((cand_price - cand_stop) / cand_price))
            stop = max(0.05, entry - risk)
            # candidate.target and candidate.price are BOTH premium for an OPT candidate
            # (signal_processor sets live_trade_price = live_premium, then
            # candidate_target = live_trade_price + max_sl_dist * final_rr), so their
            # difference is already a premium distance. Multiplying it by the signed delta
            # applied the option's delta a SECOND time and shrank every normal option
            # target to roughly delta x the graded reward — a 2.0 RR realised as 1.0 at an
            # ATM delta of 0.5. The FUT branch and both sibling option paths do not do it.
            #
            # Guard on the candidate TARGET, not on the distance. With target 0.0 the
            # distance is abs(0 - price) = the whole premium, so "no target" produced a
            # fabricated target at twice the entry (and, while the delta was being applied
            # twice, at 1.5x). Either way it is a level that can never be reached, which
            # silently disables TARGET_HIT for that trade instead of leaving it unset.
            cand_target = float(candidate.target or 0.0)
            target_move = abs(cand_target - cand_price) if cand_target > 0 else 0.0
            target = entry + target_move if target_move > 0 else 0.0
            if (
                bool(getattr(candidate, "volume_spike_entry", False))
                or bool(getattr(candidate, "late_session_reclaim_entry", False))
                or bool(getattr(candidate, "one_way_cascade_entry", False))
                or bool(getattr(candidate, "missed_signal_reentry", False))
                or bool(getattr(candidate, "is_reversion_scalp", False))
            ):
                rr = max(1.0, float(getattr(candidate, "rr", 2.5) or 2.5))
                target = entry + (risk * rr) if risk > 0 else target
            return entry, stop, target

        live_future = self._get_live_fut_ltp_cached(candidate)
        if not live_future or live_future <= 0:
            return entry, stop, target

        risk_distance = abs(float(candidate.price or 0.0) - float(candidate.stop or 0.0))
        reward_distance = abs(float(candidate.target or 0.0) - float(candidate.price or 0.0))
        entry = float(live_future)
        if str(candidate.direction or "LONG").upper() == "SHORT":
            stop = entry + risk_distance
            target = entry - reward_distance if reward_distance > 0 else 0.0
        else:
            stop = entry - risk_distance
            target = entry + reward_distance if reward_distance > 0 else 0.0
        return entry, stop, target

    @staticmethod
    def _looks_like_synthetic_option_entry(candidate: TradeCandidate) -> bool:
        """Identify the retired spot*1.2% fallback that must never enter a live ledger."""
        if str(getattr(candidate, "inst_type", "") or "").upper() != "OPT":
            return False
        entry = float(getattr(candidate, "price", 0.0) or 0.0)
        entry_spot = float(getattr(candidate, "entry_spot", 0.0) or 0.0)
        if entry <= 0 or entry_spot <= 0:
            return False
        fallback = entry_spot * 0.012
        return abs(entry - fallback) <= max(0.25, fallback * 0.0015)

    def _rebase_option_candidate_to_verified_quote(
        self,
        candidate: TradeCandidate,
        premium: float,
    ) -> bool:
        """Repair a legacy spot-estimated option signal using a verified contract quote."""
        premium = float(premium or 0.0)
        if premium <= 0 or str(getattr(candidate, "inst_type", "") or "").upper() != "OPT":
            return False
        risk = Scanner._option_premium_stop_distance_for_candidate(self, premium, candidate)
        rr = max(1.0, float(getattr(candidate, "rr", 1.5) or 1.5))
        candidate.price = premium
        candidate.current_price = premium
        candidate.stop = premium - risk
        candidate.target = premium + (risk * rr)
        candidate.pnl = self._candidate_net_pnl(candidate, premium)
        setattr(candidate, "initial_stop", candidate.stop)
        setattr(candidate, "peak_pnl", 0.0)
        setattr(candidate, "max_drawdown", 0.0)
        setattr(candidate, "quote_verified", True)
        setattr(candidate, "quote_source", "broker_ltp_repair")
        return True

    @staticmethod
    def _fut_price_from_spot_level(trade, spot_level: float) -> float:
        """Convert a spot-index level into this trade's futures price space."""
        if not spot_level or spot_level <= 0:
            return float(spot_level or 0.0)
        entry_spot = float(getattr(trade, "entry_spot", 0.0) or 0.0)
        entry_price = float(getattr(trade, "entry_price", getattr(trade, "price", 0.0)) or 0.0)
        if entry_spot > 0 and entry_price > 0:
            return entry_price + (float(spot_level) - entry_spot)
        return float(spot_level)

    @staticmethod
    def _candidate_price_from_spot_level(candidate: TradeCandidate, spot_level: float) -> float:
        """Map an index level into a candidate's contract-price space."""
        if not spot_level or spot_level <= 0:
            return 0.0
        if str(getattr(candidate, "inst_type", "FUT") or "FUT").upper() != "OPT":
            return Scanner._fut_price_from_spot_level(candidate, spot_level)

        entry_spot = float(getattr(candidate, "entry_spot", 0.0) or 0.0)
        entry_price = float(getattr(candidate, "price", 0.0) or 0.0)
        if entry_spot <= 0 or entry_price <= 0:
            return 0.0
        multiplier = float(getattr(candidate, "multiplier", 0.5) or 0.5)
        return entry_price + ((float(spot_level) - entry_spot) * multiplier)

    @staticmethod
    def _candidate_trailing_stop_is_valid(
        candidate: TradeCandidate,
        stop_level: float,
        current_price: float,
    ) -> bool:
        """Reject mapped stops that land beyond the live contract price."""
        if stop_level <= 0 or current_price <= 0:
            return False
        is_option = str(getattr(candidate, "inst_type", "FUT") or "FUT").upper() == "OPT"
        if not is_option and str(getattr(candidate, "direction", "LONG") or "LONG").upper() == "SHORT":
            return stop_level >= current_price
        return stop_level <= current_price

    def _live_analysis_window(self, df: Optional[pd.DataFrame], timeframe: str) -> Optional[pd.DataFrame]:
        """Keep scans focused on the active window plus indicator warmup bars."""
        if df is None or df.empty:
            return df

        try:
            if self.mode == "HISTORICAL":
                active_dates = sorted(set(df.index.date))
                if not active_dates:
                    return df
                trade_days = max(1, int(getattr(self, "backtest_days", 1) or 1))
                trade_cutoff = active_dates[-min(len(active_dates), trade_days)]
                trade_df = df[pd.Series(df.index.date, index=df.index) >= trade_cutoff]
                if trade_df.empty:
                    return df.tail({"1min": 720, "5min": 240, "15min": 120}.get(timeframe, 240))
                warmup_bars = {"1min": 180, "5min": 60, "15min": 40}.get(timeframe, 60)
                warmup_df = df[df.index < trade_df.index[0]].tail(warmup_bars)
                window = pd.concat([warmup_df, trade_df])
                return window[~window.index.duplicated(keep="last")].sort_index()

            if self.mode != "REAL":
                return df

            today = datetime.now(IST).date()
            idx_dates = pd.Series(df.index.date, index=df.index)
            today_df = df[idx_dates == today]
            warmup_bars = {"1min": 180, "5min": 60, "15min": 40}.get(timeframe, 60)
            fallback_bars = {"1min": 360, "5min": 120, "15min": 80}.get(timeframe, 120)
            if today_df.empty:
                return df.tail(fallback_bars)
            warmup_df = df[df.index < today_df.index[0]].tail(warmup_bars)
            window = pd.concat([warmup_df, today_df])
            return window[~window.index.duplicated(keep="last")].sort_index()
        except Exception as e:
            logger.debug(f"Live analysis window fallback for {timeframe}: {e}")
            return df

    def _previous_close_for(self, instrument: str) -> float:
        name = str(instrument or "").upper()
        if not name:
            return 0.0
        cache = getattr(self, "_prev_close_cache", None)
        if cache is None:
            self._prev_close_cache = {}
            cache = self._prev_close_cache
        cached = float(cache.get(name, 0.0) or 0.0)
        if cached > 0:
            return cached
        try:
            provider = getattr(self, "data", None)
            if provider is not None and hasattr(provider, "get_previous_close"):
                cached = float(provider.get_previous_close(name) or 0.0)
                if cached > 0:
                    cache[name] = cached
                    return cached
        except Exception as exc:
            logger.debug(f"Previous close fetch failed for {name}: {exc}")
        return 0.0

    def _previous_close_at(self, instrument: str, frame: Optional[pd.DataFrame], ts) -> float:
        """Previous-session close as of ``ts``.

        Multi-day replays must grade each historical session against its own
        prior close, not today's; derive it from the candle frame whenever the
        frame carries the prior session, and only trust the broker value for
        the current session."""
        ts_date = None
        try:
            ts_date = ts.date() if hasattr(ts, "date") else None
        except Exception:
            ts_date = None
        if frame is not None and not getattr(frame, "empty", True) and ts_date is not None:
            try:
                dates = pd.Series(frame.index.date, index=frame.index)
                prior = frame[dates < ts_date]
                if not prior.empty:
                    value = float(prior["close"].iloc[-1])
                    if value > 0:
                        return value
            except Exception as exc:
                logger.debug(f"Frame previous-close derivation failed for {instrument}: {exc}")
            if ts_date != datetime.now(IST).date():
                return 0.0
        return self._previous_close_for(instrument)

    def _price_change_pct_for(
        self,
        instrument: str,
        spot: float,
        *,
        market_quote: Optional[Dict[str, Any]] = None,
        previous_close: float = 0.0,
    ) -> Tuple[float, float]:
        quote = market_quote or {}
        try:
            quote_pct = float(quote.get("change_pct", 0.0) or 0.0)
            quote_points = float(quote.get("change", 0.0) or 0.0)
            if quote_pct or quote_points:
                return quote_points, quote_pct
        except Exception:
            pass
        prev = float(previous_close or 0.0)
        if prev <= 0:
            prev = self._previous_close_for(instrument)
        spot_val = float(spot or 0.0)
        points = (spot_val - prev) if prev > 0 and spot_val > 0 else 0.0
        pct = (points / prev * 100.0) if prev > 0 else 0.0
        return points, pct

    def _days_to_expiry_for(self, instrument: str, as_of: Optional[Any] = None) -> float:
        try:
            if as_of is None:
                target_date = datetime.now(IST).date()
            elif hasattr(as_of, "date"):
                target_date = as_of.date()
            else:
                target_date = as_of
            return max(0.0, float(self.expiry.get_dte(str(instrument or "").upper(), target_date)))
        except Exception:
            return 7.0

    def _vix_open_for_session(self, as_of: Optional[Any] = None) -> Optional[float]:
        try:
            if as_of is None:
                session_date = datetime.now(IST).date()
            elif hasattr(as_of, "date"):
                session_date = as_of.date()
            else:
                session_date = as_of
            session_key = session_date.isoformat() if hasattr(session_date, "isoformat") else str(session_date)[:10]
            cache = getattr(self, "_vix_session_open_cache", None)
            if cache is None:
                self._vix_session_open_cache = {}
                cache = self._vix_session_open_cache
            if session_key in cache:
                return cache[session_key]
            candidates = []
            for key, value in (getattr(self, "_vix_data", {}) or {}).items():
                try:
                    text = str(key)
                    if text[:10] != session_key:
                        continue
                    hhmm = text[11:16] if len(text) >= 16 else ""
                    if hhmm and hhmm < "09:00":
                        continue
                    parsed = float(value or 0.0)
                    if parsed > 0:
                        candidates.append((text, parsed))
                except Exception:
                    continue
            if not candidates:
                # Do not cache the miss: VIX data may simply not be loaded yet
                # this early in the session; retry on the next call.
                return None
            candidates.sort(key=lambda item: item[0])
            cache[session_key] = candidates[0][1]
            return cache[session_key]
        except Exception:
            return None

    def _hourly_anchor_regime(
        self,
        instrument: str,
        candle_5min: Optional[pd.DataFrame] = None,
        *,
        as_of: Optional[Any] = None,
    ) -> Dict[str, Any]:
        try:
            frame = candle_5min
            if frame is None:
                frame = self.candles.get_candles(instrument, "5min")
            if frame is None or frame.empty:
                return {}
            work = frame.copy().sort_index()
            if as_of is not None:
                try:
                    work = work[work.index <= as_of]
                except Exception:
                    pass
            if len(work) < 60:
                return {
                    "regime": "UNKNOWN",
                    "timeframe": "60min",
                    "reason": f"Need 60+ source candles; have {len(work)}",
                    "ready_for_grading": False,
                    "candle_count": 0,
                }
            agg = {"open": "first", "high": "max", "low": "min", "close": "last"}
            if "volume" in work.columns:
                agg["volume"] = "sum"
            hourly = work.resample("60min", origin="start_day", label="right", closed="right").agg(agg)
            hourly = hourly.dropna(subset=["open", "high", "low", "close"])
            if "volume" not in hourly.columns:
                hourly["volume"] = 0.0
            if len(hourly) < 30:
                return {
                    "regime": "UNKNOWN",
                    "timeframe": "60min",
                    "reason": f"Need 30 hourly candles; have {len(hourly)}",
                    "ready_for_grading": False,
                    "candle_count": int(len(hourly)),
                }
            anchor = self._detect_regime_warmed(hourly, instrument, "60min")
            anchor["timeframe"] = "60min"
            anchor["source_bars"] = int(len(work))
            return anchor
        except Exception as exc:
            logger.debug(f"60min anchor regime failed for {instrument}: {exc}")
            return {}

    @staticmethod
    def _detect_regime_warmed(frame: pd.DataFrame, instrument: str, timeframe: str) -> Dict[str, Any]:
        """Stateless regime detection with deterministic smoothing warmup.

        A fresh detector has empty history, so its majority-vote smoothing and
        strong-ADX hysteresis are no-ops on a single call. Replaying the last
        few closed bars into one throwaway detector gives those stabilizers
        real history while staying deterministic and replay-safe."""
        detector = RegimeDetector()
        try:
            window = int(getattr(get_settings(), "regime_smoothing_window", 5) or 5)
        except Exception:
            window = 5
        steps = max(1, min(window, len(frame) - 29))
        result: Dict[str, Any] = {}
        for offset in range(steps - 1, -1, -1):
            sub = frame.iloc[: len(frame) - offset]
            result = detector.detect(sub, str(instrument or "").upper(), timeframe)
        result["smoothing_warmup_bars"] = steps
        return result

    def _breadth_regime_at(self, instrument: str, as_of) -> str:
        """Regime for one index at a historical timestamp.

        Replay breadth must not read the live intel cache — that would grade
        old signals with today's breadth."""
        try:
            bucket = pd.Timestamp(as_of).floor("5min")
            if bucket.tz is not None:
                bucket = bucket.tz_localize(None)
        except Exception:
            return "UNKNOWN"
        cache = getattr(self, "_breadth_asof_cache", None)
        if cache is None:
            self._breadth_asof_cache = {}
            cache = self._breadth_asof_cache
        key = (str(instrument or "").upper(), bucket)
        if key in cache:
            return cache[key]
        regime = "UNKNOWN"
        try:
            frame = self.candles.get_candles(instrument, "5min")
            if frame is not None and not frame.empty:
                sliced = frame[frame.index <= bucket]
                if len(sliced) >= 30:
                    detected = self._detect_regime_warmed(sliced.tail(240), instrument, "5min_breadth")
                    regime = str(detected.get("regime") or "UNKNOWN").upper()
        except Exception as exc:
            logger.debug(f"Breadth regime at {as_of} failed for {instrument}: {exc}")
        if len(cache) > 4096:
            cache.clear()
        cache[key] = regime
        return regime

    def _market_breadth_context(self, as_of=None) -> Dict[str, Any]:
        try:
            active = list(getattr(self, "active_indices", []) or [])
            if not active:
                active = ["NIFTY", "BANKNIFTY", "SENSEX", "MIDCPNIFTY"]
            regimes = getattr(self, "latest_regimes", {}) or {}
            # Timestamps within the last bar are "now" (live cache is the truth);
            # anything older is a replay grade and must use at-timestamp regimes.
            historical = False
            as_of_ts = None
            if as_of is not None:
                try:
                    as_of_ts = pd.Timestamp(as_of)
                    if as_of_ts.tz is not None:
                        as_of_ts = as_of_ts.tz_convert("Asia/Kolkata").tz_localize(None)
                    now_naive = pd.Timestamp(datetime.now(IST).replace(tzinfo=None))
                    historical = (now_naive - as_of_ts) > pd.Timedelta(seconds=300)
                except Exception:
                    historical = False
            scores = []
            bullish = []
            bearish = []
            neutral = []
            for inst in active:
                name = str(inst or "").upper()
                if historical:
                    regime = self._breadth_regime_at(name, as_of_ts)
                else:
                    intel = self._cached_timeframe_intel(name, "5min", allow_fallback=True)
                    regime_payload = intel.get("regime", {}) if isinstance(intel, dict) else {}
                    regime = str(regime_payload.get("regime") or regimes.get(name) or "UNKNOWN").upper()
                    agg = intel.get("aggregate", {}) if isinstance(intel, dict) else {}
                    try:
                        scores.append(float(agg.get("score", 0.0) or 0.0))
                    except Exception:
                        pass
                if regime in {"TRENDING_UP", "BREAKOUT_UP"}:
                    bullish.append(name)
                elif regime in {"TRENDING_DOWN", "BREAKOUT_DOWN"}:
                    bearish.append(name)
                else:
                    neutral.append(name)
            bias = "NEUTRAL"
            aligned = max(len(bullish), len(bearish))
            if len(bullish) >= 3:
                bias = "BULLISH"
            elif len(bearish) >= 3:
                bias = "BEARISH"
            return {
                "bias": bias,
                "aligned_count": aligned,
                "bullish_count": len(bullish),
                "bearish_count": len(bearish),
                "neutral_count": len(neutral),
                "bullish": bullish,
                "bearish": bearish,
                "neutral": neutral,
                "avg_intel_score": round(sum(scores) / len(scores), 2) if scores else 0.0,
            }
        except Exception as exc:
            logger.debug(f"Market breadth context failed: {exc}")
            return {"bias": "NEUTRAL", "aligned_count": 0}

    def _build_intelligence_contexts(
        self,
        instrument: str,
        candle_5min: Optional[pd.DataFrame],
        *,
        spot: float = 0.0,
        previous_close: float = 0.0,
        volatility_context: Optional[Dict[str, Any]] = None,
        as_of: Optional[Any] = None,
    ) -> Dict[str, Any]:
        try:
            analyzer = getattr(self, "session_context", None)
            if analyzer is None:
                analyzer = SessionContextAnalyzer()
                self.session_context = analyzer
            vol_ctx = volatility_context or {}
            vix_value = vol_ctx.get("value")
            vix_open = self._vix_open_for_session(as_of)
            session_ctx = analyzer.analyze(
                candle_5min,
                instrument=instrument,
                spot_price=float(spot or 0.0),
                previous_close=float(previous_close or 0.0),
                vix_value=vix_value,
                vix_open=vix_open,
            )
        except Exception as exc:
            logger.debug(f"Session context failed for {instrument}: {exc}")
            session_ctx = {}
        return {
            "session_context": session_ctx,
            "anchor_regime": self._hourly_anchor_regime(instrument, as_of=as_of),
            "breadth_context": self._market_breadth_context(as_of=as_of),
        }

    @staticmethod
    def _regime_history_ready(candle_5min: Optional[pd.DataFrame]) -> bool:
        return candle_5min is not None and len(candle_5min) >= 30

    @staticmethod
    def _plain_live_regime_label(regime: str, *, volume_state: str = "", direction: str = "") -> str:
        """Human labels for live MarketRegime codes (panel display)."""
        r = str(regime or "UNKNOWN").upper()
        d = str(direction or "").upper()
        if r in {"TRENDING_UP", "TREND_UP"}:
            label = "Trend Up"
        elif r in {"TRENDING_DOWN", "TREND_DOWN"}:
            label = "Trend Down"
        elif r in {"BREAKOUT_UP"}:
            label = "Breakout Up"
        elif r in {"BREAKOUT_DOWN"}:
            label = "Breakout Down"
        elif r in {"VOLATILE"}:
            label = "Volatile"
        elif r in {"RANGING", "CHOPPY", "SIDEWAYS"}:
            label = "Range / Choppy"
        elif r in {"UNKNOWN", ""}:
            label = "Warming up"
        else:
            label = r.replace("_", " ").title()
        vs = str(volume_state or "").upper()
        if vs in {"NO_VOLUME", "THIN"}:
            label = f"{label} · Thin vol"
        elif vs == "SURGE":
            label = f"{label} · Vol surge"
        # Do not append ADX/dir/RSI — those belong on other intel tiles.
        return label

    def _detect_tf_regime_snapshot(
        self,
        instrument: str,
        timeframe: str,
        *,
        session_context: Optional[Dict[str, Any]] = None,
        breadth_context: Optional[Dict[str, Any]] = None,
        lookback_bars: Optional[int] = None,
        force_redetect: bool = False,
    ) -> Dict[str, Any]:
        """Run (or reuse) RegimeDetector on a TF candle stream for the live panel.

        lookback_bars: if set, re-detect on the last N bars only (still needs ≥30
        bars for a full grade; shorter tails warm with whatever is available).
        force_redetect: skip cache (used for hour pocket / hybrid day inputs).
        """
        name = str(instrument or "").split()[0].upper()
        tf = str(timeframe or "5min").lower()
        # Prefer cached full intel regime (already smoothed) unless pocket lookback.
        cached = None
        if not force_redetect and not lookback_bars:
            try:
                cached = self._cached_timeframe_intel(name, tf, allow_fallback=False)
            except Exception:
                cached = None
        reg: Dict[str, Any] = {}
        vol_ratio = 0.0
        if isinstance(cached, dict):
            reg = cached.get("regime", {}) if isinstance(cached.get("regime"), dict) else {}
            vol = cached.get("volume", {}) if isinstance(cached.get("volume"), dict) else {}
            try:
                vol_ratio = float(
                    vol.get("display_volume_ratio")
                    or vol.get("relative_volume_ratio")
                    or vol.get("volume_ratio")
                    or 0.0
                )
            except Exception:
                vol_ratio = 0.0
        if not reg or str(reg.get("regime") or "UNKNOWN").upper() in {"", "UNKNOWN"} or lookback_bars or force_redetect:
            try:
                df = self._live_analysis_window(self.candles.get_candles(name, tf), tf)
            except Exception:
                df = None
            if df is not None and lookback_bars is not None and len(df) > 0:
                # Keep enough history for detector (≥30 when available).
                n = max(30, int(lookback_bars or 30))
                n = min(len(df), max(int(lookback_bars or n), 30 if len(df) >= 30 else len(df)))
                try:
                    df = df.tail(n)
                except Exception:
                    pass
            # CRITICAL isolation: never use self.intel.regime here.
            # Panel re-detects (esp. hour lookback / force_redetect) would append
            # to the shared RegimeDetector._regime_history under the same
            # "{instrument}_{timeframe}" key and corrupt trading intel smoothing,
            # gates, and trailing regime labels. Dashboard-only detector.
            if not isinstance(getattr(self, "_panel_regime_detector", None), RegimeDetector):
                self._panel_regime_detector = RegimeDetector()
            detector = self._panel_regime_detector
            try:
                if df is not None and len(df) >= 5:
                    # Distinct history key namespace so even if someone reuses
                    # intel.regime later, panel pockets stay isolated.
                    panel_tf = f"panel_{tf}"
                    if lookback_bars:
                        panel_tf = f"panel_{tf}_lb{int(lookback_bars)}"
                    reg = detector.detect(
                        df,
                        instrument=name,
                        timeframe=panel_tf,
                        session_context=session_context,
                        breadth_context=breadth_context,
                    ) or {}
            except Exception as exc:
                logger.debug(f"Regime snapshot failed {name} {tf}: {exc}")
                reg = {}
            # Volume ratio from last bars if intel missing.
            if vol_ratio <= 0 and df is not None and "volume" in getattr(df, "columns", []):
                try:
                    v = pd.to_numeric(df["volume"], errors="coerce").fillna(0.0)
                    if len(v) >= 6:
                        recent = float(v.iloc[-3:].mean() or 0.0)
                        prior = float(v.iloc[-20:-3].mean() or 0.0) if len(v) >= 20 else float(v.iloc[:-3].mean() or 0.0)
                        vol_ratio = (recent / prior) if prior > 0 else 0.0
                        # A ratio is unit-free, but only while the whole window shares
                        # one source. If index volume just failed over from Fyers cash
                        # volume to Kite futures contracts, the recent bars and the
                        # prior bars are different quantities and their ratio is an
                        # artefact of the join — ~0.006 (reads THIN) or ~175 (reads
                        # SURGE). Report UNKNOWN until the window is homogeneous again.
                        homogeneous = getattr(self.data, "volume_series_is_homogeneous", None)
                        if callable(homogeneous):
                            tf_minutes = {"1min": 1.0, "5min": 5.0, "15min": 15.0}.get(tf, 5.0)
                            if not homogeneous(name, tf_minutes, 20):
                                vol_ratio = 0.0
                except Exception:
                    vol_ratio = 0.0
        regime_code = str(reg.get("regime") or reg.get("smoothed_regime") or "UNKNOWN").upper()
        direction = str(reg.get("direction") or "NEUTRAL").upper()
        try:
            adx = float(reg.get("adx") or 0.0)
        except Exception:
            adx = 0.0
        try:
            conf_raw = float(reg.get("confidence") or 0.0)
        except Exception:
            conf_raw = 0.0
        # Detector confidence is typically 0–100; normalize to 0–1 for the panel.
        conf01 = conf_raw / 100.0 if conf_raw > 1.5 else conf_raw
        conf01 = max(0.0, min(1.0, float(conf01 or 0.0)))
        if vol_ratio > 0 and vol_ratio < 0.55:
            volume_state = "THIN"
        elif vol_ratio >= 2.0:
            volume_state = "SURGE"
        elif vol_ratio <= 0:
            volume_state = "UNKNOWN"
        else:
            volume_state = "NORMAL"
        display_code = regime_code
        # Choppy: ranging + weak ADX (still engine RANGING, display as Choppy)
        if regime_code in {"RANGING", "CHOPPY"} and adx > 0 and adx < 16:
            display_code = "CHOPPY"
        if display_code == "CHOPPY":
            plain = "Choppy"
            if volume_state == "THIN":
                plain = "Choppy · Thin vol"
            elif volume_state == "SURGE":
                plain = "Choppy · Vol surge"
        else:
            plain = self._plain_live_regime_label(
                regime_code,
                volume_state=volume_state,
                direction=direction,
            )
        return {
            "regime": regime_code,
            "display_regime": display_code,
            "label": plain,
            "adx": round(adx, 1),
            "direction": direction,
            "confidence": round(conf01, 3),
            "confidence_pct": int(round(conf01 * 100)),
            "volume_ratio": round(float(vol_ratio or 0.0), 2),
            "volume_state": volume_state,
            "timeframe": tf,
            "conviction_label": str(reg.get("conviction_label") or ""),
            "summary": str(reg.get("conviction_summary") or reg.get("description") or plain),
        }

    def _hybrid_session_day_regime(
        self,
        hour_snap: Dict[str, Any],
        m15_snap: Dict[str, Any],
    ) -> Dict[str, Any]:
        """Full-session-so-far day label: blend 1h (5m pocket) + 15m structure.

        - Agree → that regime (higher conf, blended ADX).
        - Disagree → 15m weighted for structure; 1h can win on breakout/volatile
          impulse when its ADX is stronger.
        """
        h = dict(hour_snap or {})
        d = dict(m15_snap or {})
        rh = str(h.get("regime") or "UNKNOWN").upper()
        rd = str(d.get("regime") or "UNKNOWN").upper()
        plain_h = self._plain_live_regime_label(rh, volume_state=str(h.get("volume_state") or ""))
        plain_d = self._plain_live_regime_label(rd, volume_state=str(d.get("volume_state") or ""))

        def _score(snap: Dict[str, Any]) -> float:
            try:
                adx = float(snap.get("adx") or 0.0)
            except Exception:
                adx = 0.0
            try:
                conf = float(snap.get("confidence") or 0.0)
            except Exception:
                conf = 0.0
            if conf > 1.5:
                conf = conf / 100.0
            code = str(snap.get("regime") or "").upper()
            impulse = 1.25 if code.startswith("BREAKOUT") or code == "VOLATILE" else 1.0
            return max(0.0, adx) * max(0.15, conf) * impulse

        if rd in {"", "UNKNOWN"} and rh in {"", "UNKNOWN"}:
            out = dict(d or h)
            out.update(
                {
                    "title": "Day (session hybrid)",
                    "blend": "warming",
                    "label": "Warming up",
                    "detail": "need 15m + 1h data",
                    "components": {"hour": rh, "m15": rd},
                }
            )
            return out
        if rd in {"", "UNKNOWN"}:
            out = dict(h)
            out["title"] = "Day (session hybrid)"
            out["blend"] = "hour_only"
            out["detail"] = f"1h {plain_h} (15m warming)"
            out["components"] = {"hour": rh, "m15": rd}
            return out
        if rh in {"", "UNKNOWN"}:
            out = dict(d)
            out["title"] = "Day (session hybrid)"
            out["blend"] = "15m_only"
            out["detail"] = f"15m {plain_d} (1h warming)"
            out["components"] = {"hour": rh, "m15": rd}
            return out

        if rh == rd:
            out = dict(d)
            out["confidence"] = max(float(h.get("confidence") or 0), float(d.get("confidence") or 0))
            out["confidence_pct"] = max(int(h.get("confidence_pct") or 0), int(d.get("confidence_pct") or 0))
            try:
                out["adx"] = round(max(float(h.get("adx") or 0), float(d.get("adx") or 0)), 1)
            except Exception:
                pass
            out["label"] = plain_d
            out["title"] = "Day (session hybrid)"
            out["blend"] = "agree"
            out["detail"] = f"15m+1h agree · {plain_d}"
            out["summary"] = f"Session hybrid: 15m & 1h both {rd}"
            out["components"] = {"hour": rh, "m15": rd}
            return out

        # Disagree: session structure (15m) gets a slight weight boost.
        score_h = _score(h)
        score_d = _score(d) * 1.12
        hour_impulse = rh.startswith("BREAKOUT") or rh == "VOLATILE"
        m15_impulse = rd.startswith("BREAKOUT") or rd == "VOLATILE"
        if hour_impulse and not m15_impulse and score_h >= score_d:
            winner, blend = h, "hour_impulse"
        elif score_d >= score_h:
            winner, blend = d, "15m_structure"
        else:
            winner, blend = h, "hour_leads"

        out = dict(winner)
        win_code = str(out.get("regime") or "UNKNOWN").upper()
        out["label"] = self._plain_live_regime_label(
            win_code, volume_state=str(out.get("volume_state") or "")
        )
        out["title"] = "Day (session hybrid)"
        out["blend"] = blend
        out["detail"] = f"15m {plain_d} · 1h {plain_h}"
        out["summary"] = (
            f"Session hybrid: 15m={rd} vs 1h={rh} → {win_code} ({blend})"
        )
        out["components"] = {"hour": rh, "m15": rd}
        # Confidence between the two when mixed.
        try:
            out["confidence_pct"] = int(
                round(0.5 * (int(h.get("confidence_pct") or 0) + int(d.get("confidence_pct") or 0)))
            )
            out["confidence"] = out["confidence_pct"] / 100.0
        except Exception:
            pass
        return out

    def _live_regime_horizons(
        self,
        instrument: str,
        *,
        session_context: Optional[Dict[str, Any]] = None,
        breadth_context: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Live multi-horizon regimes for the dashboard (not session day-type mood).

        - pulse  = 1min stream  (~1–5m tape)
        - hour   = last ~12–36 5min bars (tactical hour pocket)
        - day    = hybrid of hour pocket + full 15m session structure
        """
        name = str(instrument or "").split()[0].upper()
        pulse = self._detect_tf_regime_snapshot(
            name, "1min", session_context=session_context, breadth_context=breadth_context
        )
        # Hour pocket: re-detect on recent 5m bars (≈1–3h), not entire multi-day cache.
        hour = self._detect_tf_regime_snapshot(
            name,
            "5min",
            session_context=session_context,
            breadth_context=breadth_context,
            lookback_bars=36,
            force_redetect=True,
        )
        m15 = self._detect_tf_regime_snapshot(
            name, "15min", session_context=session_context, breadth_context=breadth_context
        )
        day = self._hybrid_session_day_regime(hour, m15)
        # Primary live = 5m hour pocket (closest to engine tactical tape).
        live = dict(hour)
        live["title"] = "Live (5m hour pocket)"
        pulse["title"] = "1–5m"
        hour["title"] = "Hourly (5m pocket)"
        day["title"] = "Day (15m + 1h hybrid)"
        return {
            "live": live,
            "pulse": pulse,
            "hour": hour,
            "day": day,
            "m15": m15,
            "updated_at": datetime.now(IST).replace(tzinfo=None).isoformat(),
        }

    @staticmethod
    def _intel_result_cacheable(intel_result: Optional[Dict]) -> bool:
        regime = (intel_result or {}).get("regime", {}) or {}
        return bool(
            str(regime.get("regime") or "UNKNOWN").upper() != "UNKNOWN"
            and regime.get("ready_for_grading", True)
            and int(regime.get("candle_count") or 30) >= 30
        )

    def _process_instrument(self, name: str, cfg: Dict) -> Tuple[Dict, List[TradeCandidate]]:
        """Main Analysis Pipeline — focused on speed and real-time accuracy"""
        lot_size = cfg.get("lot_size", 25)
        lots = self.user_lots.get(name, 1)
        strike_interval = cfg.get("strike_interval", 50)
        combined_cap = self.capital_fut + self.capital_opt

        # 1. Use background-cached LTP to prevent API rate limits and speed up processing
        market_quote = {}
        if hasattr(self.data, "get_index_quote"):
            try:
                market_quote = self.data.get_index_quote(name) or {}
            except Exception as exc:
                logger.debug(f"Index quote fetch failed for {name}: {exc}")

        quote_spot = float(market_quote.get("ltp", 0.0) or 0.0)
        if quote_spot > 0:
            self.candles.update_latest_price(name, quote_spot)

        spot = quote_spot if quote_spot > 0 else self.candles.get_latest_price(name)
        if spot <= 0:
            logger.warning(f"âš ï¸  Spot price for {name} is {spot}. Skipping scan.")
            return {"error": f"Invalid spot price: {spot}"}, []

        # â• â•  Daily Change (Optimized: Use Cache) â• â•
        quote_change = float(market_quote.get("change", 0.0) or 0.0)
        quote_change_pct = float(market_quote.get("change_pct", 0.0) or 0.0)
        quote_prev_close = float(
            market_quote.get("previous_close", 0.0)
            or market_quote.get("prev_close", 0.0)
            or 0.0
        )
        prev_close = quote_prev_close
        if quote_change or quote_change_pct:
            if quote_change == 0.0 and quote_prev_close > 0:
                quote_change = spot - quote_prev_close
            if quote_change_pct == 0.0 and quote_prev_close > 0:
                quote_change_pct = quote_change / quote_prev_close * 100.0
            change_points = quote_change
            change_pct = quote_change_pct
            if quote_prev_close > 0:
                if not hasattr(self, "_prev_close_cache"):
                    self._prev_close_cache = {}
                self._prev_close_cache[name] = quote_prev_close
        else:
            if not hasattr(self, "_prev_close_cache"):
                self._prev_close_cache = {}

            prev_close = quote_prev_close or self._prev_close_cache.get(name, 0)
            if prev_close <= 0:
                prev_close = self.data.get_previous_close(name)
                self._prev_close_cache[name] = prev_close

            change_points = (spot - prev_close) if prev_close > 0 else 0
            change_pct = ((change_points) / prev_close * 100) if prev_close > 0 else 0

        # 2. Update MTF and Analysis
        for tf in ["1min", "5min", "15min"]:
            data = self.candles.get_candles(name, tf)
            if data is not None:
                data = self._live_analysis_window(data, tf)
                self.mtf.update_data(name, tf, data)

        # Multi-TF analysis
        mtf_result = self.mtf.process_instrument(name, lot_size, lots, combined_cap, self.risk_fut_pct)

        # Cache per-TF process results for chart builder (avoid re-processing)
        for tf_key in ["1min", "5min", "15min"]:
            key = f"{name}_{tf_key}"
            tf_result = getattr(mtf_result, f"results_{tf_key}", None)
            if tf_result:
                self._cached_results[key] = tf_result
                logger.debug(f"Cached results for {key}")
            else:
                logger.debug(f"No results for {key}")

        results = {} # Will be populated with intelligence below

        # â• â•  MASTER SPOT RESOLUTION (Broker Priority Fix) â• â•
        candle_5min = self._live_analysis_window(self.candles.get_candles(name, "5min"), "5min")

        # â• â•  MASTER SPOT RESOLUTION (Broker Priority Fix) â• â•
        # Priority: Official Broker Spot -> Historical Fallback
        live_spot = quote_spot if quote_spot > 0 else self.candles.get_latest_price(name)
        hist_spot = candle_5min['close'].iloc[-1] if candle_5min is not None and not candle_5min.empty else 0

        # Use broker price if available, otherwise fallback to candle close
        spot = live_spot if (live_spot and live_spot > 0) else hist_spot

        # Debug Sync
        if self.scan_count % 10 == 0:
            logger.info(f"🔍 Price Resolution for {name}: Broker={live_spot}, Hist={hist_spot} -> Final={spot}")

        # simulation_id is only set during actual re-simulations (see configure())

        # â• â•  INTELLIGENCE â• â•
        allow_chain_fetch = self.mode == "HISTORICAL" or self._chain_cache.get(name) is None
        chain, chain_quality = self._get_option_chain_cached(name, cfg, allow_fetch=allow_chain_fetch)
        depth_context = self._get_depth_context(name, cfg)
        chain_quality = {**chain_quality, "depth": depth_context}
        candle_1min = self._live_analysis_window(self.candles.get_candles(name, "1min"), "1min")
        candle_15min = self._live_analysis_window(self.candles.get_candles(name, "15min"), "15min")

        # â• â•  Volume Spike Detection â• â•
        import time
        now = time.time()
        if candle_1min is not None and len(candle_1min) > 12:
            last_volume = candle_1min['volume'].iloc[-1]
            avg_volume = candle_1min['volume'].iloc[:-1].tail(12).mean()

            if avg_volume > 0 and last_volume >= 2 * avg_volume:
                last_alert = self._last_vol_alert_time.get(name, 0)
                if now - last_alert >=  30.0:
                    last_open = float(candle_1min['open'].iloc[-1])
                    last_close = float(candle_1min['close'].iloc[-1])
                    pressure = "BUYING" if last_close > last_open else "SELLING"
                    msg = f"🔈 VOLUME SPIKE ({pressure} PRESSURE) detected for {name}: Current volume ({last_volume:.0f}) is 2x+ the average ({avg_volume:.0f})!"
                    logger.warning(msg)
                    if self.on_notification:
                        self.on_notification(msg, "warning")
                    self._last_vol_alert_time[name] = now

        # Use background-cached intel if fresh enough (avoids redundant heavy computation)
        intel_ttl = self._intel_analysis_ttl_seconds()
        cached_intel = self._cached_timeframe_intel(name, "5min", allow_fallback=False)
        cached_intel_time = getattr(self, '_intel_cache_time', {}).get(self._timeframe_intel_key(name, "5min"), 0) or getattr(self, '_intel_cache_time', {}).get(name, 0)
        regime_history_ready = self._regime_history_ready(candle_5min)
        if not regime_history_ready:
            self._clear_timeframe_intel(name, "5min")
            cached_intel = None
        intel_is_fresh = (
            regime_history_ready
            and self._intel_result_cacheable(cached_intel)
            and (now - cached_intel_time) < intel_ttl
        )

        if intel_is_fresh:
            intel_result = cached_intel
        else:
            try:
                if self.mode == "HISTORICAL":
                    analysis_frame = (
                        candle_5min
                        if candle_5min is not None and not candle_5min.empty
                        else candle_1min
                    )
                    if analysis_frame is not None and not analysis_frame.empty:
                        raw_ts = analysis_frame.index[-1]
                        analysis_ts = (
                            raw_ts.to_pydatetime()
                            if hasattr(raw_ts, "to_pydatetime")
                            else raw_ts
                        )
                    else:
                        analysis_ts = self.candles.get_max_timestamp() or datetime.now(IST)
                    historical_vix = self._get_historical_vix(analysis_ts)
                    historical_percentile = self._vix_percentile(historical_vix, analysis_ts)
                    vol_context = {
                        "value": historical_vix,
                        "percentile": historical_percentile,
                        "source": (
                            "india_vix_daily_percentile"
                            if historical_percentile is not None
                            else "india_vix_insufficient_history"
                        ),
                    }
                else:
                    vol_context = self._get_live_volatility_context()
                iv_as_of = analysis_ts if self.mode == "HISTORICAL" else datetime.now(IST)
                context_previous_close = self._previous_close_for(name)
                dte = self._days_to_expiry_for(name, iv_as_of)
                contexts = self._build_intelligence_contexts(
                    name,
                    candle_5min,
                    spot=spot,
                    previous_close=context_previous_close,
                    volatility_context=vol_context,
                    as_of=iv_as_of,
                )
                intel_result = self.intel.analyze(
                    instrument=name,
                    timeframe="5min",
                    candle_df=candle_5min if candle_5min is not None else pd.DataFrame(),
                    candle_1min_df=candle_1min,
                    options_chain=chain,
                    spot_price=spot,
                    strike_interval=strike_interval,
                    days_to_expiry=dte,
                    price_change_pct=change_pct,
                    chain_quality=chain_quality,
                    volatility_value=vol_context.get("value"),
                    volatility_percentile=vol_context.get("percentile"),
                    volatility_source=vol_context.get("source", ""),
                    instrument_iv_observations=self._instrument_iv_observations(name, iv_as_of),
                    session_context=contexts.get("session_context"),
                    anchor_regime=contexts.get("anchor_regime"),
                    breadth_context=contexts.get("breadth_context"),
                )
                if self._intel_result_cacheable(intel_result):
                    self._cache_timeframe_intel(name, "5min", intel_result, at=now, mirror_legacy=True)
                    self._record_instrument_iv(name, intel_result, iv_as_of)

                if self._regime_history_ready(candle_15min):
                    try:
                        self._get_timeframe_intel(
                            name,
                            "15min",
                            chain=chain,
                            chain_quality=chain_quality,
                            depth_context=depth_context,
                            spot=spot,
                            cfg=cfg,
                            price_change_pct=change_pct,
                            volatility_context=vol_context,
                            session_context=contexts.get("session_context"),
                            anchor_regime=contexts.get("anchor_regime"),
                            breadth_context=contexts.get("breadth_context"),
                            now=now,
                            allow_fallback=False,
                        )
                    except Exception as exc:
                        logger.debug(f"15min intelligence warmup skipped for {name}: {exc}")

                # Log for verification
                pcr_val = intel_result.get('pcr', {}).get('pcr_oi', 0)
                call_delta = intel_result.get('greeks', {}).get('call', {}).get('delta', 0)
                logger.info(f"Intelligence for {name}: PCR={pcr_val}, Call Delta={call_delta}")
            except Exception as e:
                import traceback
                logger.error(f"Intelligence analysis failed for {name}: {e}\n{traceback.format_exc()}")
                intel_result = cached_intel or {
                    "pcr": {"pcr": 1.0, "signal": "NEUTRAL"},
                    "oi": {"signal": "NEUTRAL", "cumulative_analysis": {}},
                    "greeks": {},
                    "volume": {"buy_sell_ratio": 1.0},
                    "order_flow": {"ratio": 1.0},
                    "regime": {"regime": "UNKNOWN"}
                }

        # Multi-horizon live regimes for Regime panel (1–5m / hourly / day session).
        try:
            _sc = (intel_result or {}).get("session_context") if isinstance(intel_result, dict) else {}
            _br = (intel_result or {}).get("breadth_context") if isinstance(intel_result, dict) else {}
            horizons = self._live_regime_horizons(
                name,
                session_context=_sc if isinstance(_sc, dict) else None,
                breadth_context=_br if isinstance(_br, dict) else None,
            )
            if isinstance(intel_result, dict):
                intel_result = dict(intel_result)
                intel_result["regime_horizons"] = horizons
                # Keep aggregate in sync for UI fallbacks.
                agg = intel_result.get("aggregate") if isinstance(intel_result.get("aggregate"), dict) else {}
                agg = dict(agg)
                agg["regime_horizons"] = horizons
                intel_result["aggregate"] = agg
        except Exception as _rh_exc:
            logger.debug(f"regime_horizons build failed for {name}: {_rh_exc}")

        results["intelligence"] = intel_result # Store in results dict
        self._record_bar_aligned_intelligence(name, chain, intel_result, chain_quality, depth_context)
        try:
            pre_candle_prediction = self._build_pre_candle_predictions(
                name,
                mtf_result,
                intel_result,
                candle_1min,
                candle_5min,
                candle_15min,
            )
        except Exception as exc:
            logger.debug(f"Pre-candle prediction failed for {name}: {exc}")
            pre_candle_prediction = {}

        # â• â• â•  Record Intelligence Memory â• â• â•
        scan_ts = time.time()
        self.intel_memory.record(name, scan_ts, intel_result)
        if self.scan_count % 300 == 0: self._schedule_intel_memory_save() # Periodically persist

        intel_score = aggregate_intelligence_score(intel_result.get("aggregate", {}))
        regime = intel_result.get("regime", {}).get("regime", "UNKNOWN")
        if self._intel_result_cacheable(intel_result):
            # `at=now` only when this is a FRESH computation. On the cache-hit path
            # intel_result IS cached_intel, and re-stamping it renewed the TTL on every
            # read — a 90s bound that a 1s scan loop could push out indefinitely, so
            # intel had no enforced age at all. Preserve the original stamp instead:
            # _get_timeframe_intel already returns a hit without re-caching, which is
            # the correct pattern.
            self._cache_timeframe_intel(
                name, "5min", intel_result,
                at=(cached_intel_time if intel_is_fresh else now),
                mirror_legacy=True,
            )
        else:
            self.latest_regimes[name] = str(regime or "UNKNOWN").upper()

        # â• â• â•  ATM Strike Resolution â• â• â•
        atm_strike = round(spot / strike_interval) * strike_interval if spot > 0 else 0

        # â• â• â•  BEST SIGNAL SELECTION across timeframes â• â• â•
        signal_parts = []
        # The key is the cache's identity. 1min was absent from it, so a brand-new
        # 1-minute signal did not change the key and the 15-second REAL-mode cache
        # kept serving a candidate list computed before that signal existed.
        for tf_name, tf_result in (
            ("1min", getattr(mtf_result, "results_1min", None)),
            ("5min", mtf_result.results_5min),
            ("15min", mtf_result.results_15min),
        ):
            sigs = tf_result.get("signals", []) if tf_result else []
            last_sig = sigs[-1] if sigs else None
            if last_sig:
                signal_parts.append(
                    f"{tf_name}:{last_sig.timestamp}:{last_sig.signal_type}:{round(float(last_sig.price or 0), 2)}"
                )
            else:
                signal_parts.append(f"{tf_name}:none")
        decision_key = "|".join(signal_parts + [str(self.inst_pref), str(getattr(get_settings(), "signal_grade_preference", ""))])
        decision_cache = self._candidate_process_cache.get(name)
        has_forming_signal = self._mtf_has_forming_signal(mtf_result)
        if not regime_history_ready:
            candidates = []
            self._candidate_process_cache.pop(name, None)
            self.log_signal_decision_once(
                f"{name}|regime-warmup|{len(candle_5min) if candle_5min is not None else 0}",
                (
                    f"Signal grading deferred: {name} regime history warming "
                    f"({len(candle_5min) if candle_5min is not None else 0}/30 five-minute candles)"
                ),
                "data",
            )
        elif (
            self.mode == "REAL"
            and not has_forming_signal
            and decision_cache
            and decision_cache.get("key") == decision_key
            and now - decision_cache.get("time", 0.0) <= 15.0
        ):
            candidates = decision_cache.get("candidates", [])
        else:
            if self.mode == "HISTORICAL":
                regime_reset = getattr(
                    getattr(getattr(self, "intel", None), "regime", None),
                    "reset_history",
                    None,
                )
                if callable(regime_reset):
                    regime_reset(name)
            candidates = self.signal_processor.process_best_signal(
                name, mtf_result, intel_result, intel_score, regime,
                lots, lot_size, cfg, spot, atm_strike,
            )
            # R3: register direction votes as each index grades (same-scan peers)
            try:
                for _vc in list(candidates or []):
                    if getattr(_vc, "action", "ENTRY") != "ENTRY":
                        continue
                    self._register_heavy_trend_vote(
                        name,
                        str(getattr(_vc, "direction", "") or ""),
                        str(getattr(_vc, "timeframe", "") or ""),
                        signal_ts=getattr(_vc, "signal_timestamp", None),
                    )
            except Exception:
                pass
            if self.mode == "REAL" and not has_forming_signal:
                self._candidate_process_cache[name] = {
                    "key": decision_key,
                    "time": now,
                    "candidates": candidates,
                }
        source_snapshot = self.data.get_market_source_snapshot(name)
        candidates = self._filter_live_candidates_by_source(name, candidates, source_snapshot)
        display_candidates = self._get_session_trade_candidates(name)
        if not display_candidates:
            display_candidates = (
                self._latest_exit_candidates.get(name, [])
                + self._latest_trade_candidates.get(name, [])
            )
        self._refresh_trade_candidates(display_candidates, cfg)
        # Use first candidate for RR display if any
        primary_candidate = candidates[0] if candidates else None

        # â• â• â•  Build chart from CACHED results — NO re-processing â• â• â•
        chart_data = self._build_chart_from_cache(name) if getattr(self, "chart_stream_enabled", True) else {}

        # Optimization: Strip heavy chart data for instruments NOT in active_indices
        # (Though active_indices filter already applied in _scan_cycle, this is a safety check)

        # Calculate Trade State for UI
        active_trade = next((t for t in getattr(self.trades, 'open_trades', {}).values() if getattr(t, 'instrument', '') == name), None) if hasattr(self, 'trades') else None
        open_mtm = 0.0
        time_in_trade = '--'
        risk_exposure = 0.0
        if active_trade:
            open_mtm = (spot - active_trade.entry_price) * (1 if active_trade.direction == 'LONG' else -1) * lot_size
            duration_secs = (datetime.now().astimezone(IST) - active_trade.entry_time).total_seconds() if active_trade.entry_time else 0
            m, s = divmod(int(max(0, duration_secs)), 60)
            h, m = divmod(m, 60)
            time_in_trade = f'{h:02d}:{m:02d}:{s:02d}'
            stop_px = float(
                getattr(active_trade, "stop_loss", 0.0)
                or getattr(active_trade, "current_stop", 0.0)
                or getattr(active_trade, "trailing_stop", 0.0)
                or 0.0
            )
            risk_exposure = abs(active_trade.entry_price - stop_px) * lot_size * -1

        # Calculate ATR exhaustion (approx)
        state_5m = mtf_result.results_5min.get('state', {}) if mtf_result.results_5min else {}
        atr_val = float(state_5m.get('atr_value') or 0)
        try:
            atr_exhaustion_str = f'ATR {int(atr_val)} pts'
        except Exception:
            atr_exhaustion_str = '--'

        quote_label, quote_session, is_preopen, preopen_settlement = self._dashboard_quote_session(
            market_quote
        )

        ui_data = {
            'trade_state': {
                'open_mtm': open_mtm,
                'time_in_trade': time_in_trade,
                'risk_exposure': risk_exposure,
                'next_trigger': 'Ready',
                'overbought_oversold': self._overbought_oversold(name),
                'vwap_deviation': self._vwap_deviation(name),
                'atr_exhaustion': atr_exhaustion_str,
            },
            "mtf": {
                "confluence_score": mtf_result.confluence_score,
                "confluence_signal": mtf_result.confluence_signal,
                "state_1min": mtf_result.results_1min.get("state") if mtf_result.results_1min else None,
                "state_5min": mtf_result.results_5min.get("state") if mtf_result.results_5min else None,
                "state_15min": mtf_result.results_15min.get("state") if mtf_result.results_15min else None,
            },
            "intelligence": {
                "volume": intel_result.get("volume", {}),
                "oi": intel_result.get("oi", {}),
                "pcr": intel_result.get("pcr", {}),
                "greeks": intel_result.get("greeks", {}),
                "regime": intel_result.get("regime", {}),
                "order_flow": intel_result.get("order_flow", {}),
                "aggregate": intel_result.get("aggregate", {}),
                "market_structure": intel_result.get("market_structure", {}),
                "aroon": intel_result.get("aroon_context", {}),
                "wavetrend": intel_result.get("wavetrend", {}),
                "max_pain": intel_result.get("max_pain", {}),
                "potential_rr": primary_candidate.rr if primary_candidate else 1.5,
            },
            "pre_candle_prediction": pre_candle_prediction,
            "chart": chart_data,
            "signals": self.signals.get_active_signals(mode=self.mode),
            "trade_candidates": [self._serialize_trade_candidate(c) for c in display_candidates],
            "simulation_id": self.simulation_id,
            "atm_strike": atm_strike,
            "ltp": spot,
            "change_points": change_points,
            "change_pct": change_pct,
            "change": change_points,
            "prev_close": prev_close,
            "previous_close": prev_close,
            "quote_source": market_quote.get("source", "unknown"),
            "quote_label": quote_label,
            "quote_session": quote_session,
            "quote_age_seconds": market_quote.get("quote_age_seconds"),
            "is_preopen": is_preopen,
            "preopen_settlement": preopen_settlement,
            "market_source": source_snapshot,
            "spot_price": spot,
        }

        # â• â•  BROADCAST OPTIMIZATION â• â•
        # If this is the currently selected instrument in the dashboard, we MUST include chart data.
        # Otherwise, we strip it to save 90% of bandwidth.
        # Note: The main loop in _scan_cycle handles stripping based on is_full_chart_needed.

        return ui_data, candidates

    def _filter_live_candidates_by_source(
        self,
        instrument: str,
        candidates: List[TradeCandidate],
        source_snapshot: Dict[str, Any],
    ) -> List[TradeCandidate]:
        """Delayed/context-only data may manage exits but cannot authorize live entries."""
        if self.mode != "REAL" or bool(source_snapshot.get("entry_eligible")):
            return candidates

        allowed = []
        for candidate in candidates:
            action = str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper()
            if action != "ENTRY":
                allowed.append(candidate)
                continue
            signal_ts = getattr(candidate, "signal_timestamp", None)
            identity = "|".join(
                [
                    instrument,
                    str(getattr(candidate, "timeframe", "")),
                    str(signal_ts),
                    str(getattr(candidate, "direction", "")),
                ]
            )
            self._diag_inc_unique("source_fallback", "delayed_entry_blocked", identity)
            # loguru formats with {}, not %-style args, so this logged a literal "%s" and
            # never named the instrument — and it is the only line emitted when an entry
            # is refused. Name the instrument AND the sources it saw, because "no source
            # is fresh" without the ages is undiagnosable while the market is moving.
            observed = ", ".join(
                f"{src.get('source')}"
                f"[{'entry' if src.get('entry_eligible') else 'context'}"
                f"/{src.get('age_seconds')}s]"
                for src in (source_snapshot.get("sources") or [])
            ) or "none"
            logger.warning(
                f"Blocked live entry for {instrument} {getattr(candidate, 'timeframe', '')} "
                f"{getattr(candidate, 'direction', '')}: no entry-eligible broker source "
                f"is fresh; delayed data remains context-only. Sources seen: {observed}"
            )
            self._rtracker_record_candidate(
                candidate,
                decision="REJECTED",
                reason="No entry-eligible broker source is fresh",
                source="source_freshness_gate",
            )
        return allowed

    def _serialize_trade_candidate(self, candidate: TradeCandidate) -> Dict:
        """Serialize final post-filter trade candidates for the dashboard signal panel."""
        is_option = str(getattr(candidate, "inst_type", "") or "").upper() == "OPT"
        option_type = str(getattr(candidate, "option_type", "") or "").upper()
        candidate_id = str(getattr(candidate, "trade_id", "") or getattr(candidate, "id", "") or "")
        if not candidate_id:
            candidate_id = f"SESSION|{self._candidate_history_key(candidate)}"
            setattr(candidate, "trade_id", candidate_id)
        signal_ts = getattr(candidate, "signal_timestamp", None)
        entry_ts = getattr(candidate, "entry_timestamp", None) or signal_ts
        lifecycle_id = self._candidate_lifecycle_key(candidate)
        is_entry = str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper() != "EXIT"
        if is_entry:
            self._ensure_trade_like_initial_stop(candidate)
        display_stop = (
            float(getattr(candidate, "display_stop", candidate.stop) or 0.0)
            if is_entry
            else float(candidate.stop or 0.0)
        )
        display_target = (
            float(getattr(candidate, "display_target", candidate.target) or 0.0)
            if is_entry
            else float(candidate.target or 0.0)
        )
        mi_ctx = getattr(candidate, "market_intelligence_context", {}) or {}
        if not isinstance(mi_ctx, dict):
            mi_ctx = {}
        regime_ctx = mi_ctx.get("regime", {}) if isinstance(mi_ctx.get("regime"), dict) else {}
        market_structure = mi_ctx.get("market_structure", {}) if isinstance(mi_ctx.get("market_structure"), dict) else {}
        aroon_ctx = mi_ctx.get("aroon", {}) if isinstance(mi_ctx.get("aroon"), dict) else {}
        wavetrend_ctx = mi_ctx.get("wavetrend", {}) if isinstance(mi_ctx.get("wavetrend"), dict) else {}
        manual_exit_state = self._manual_signal_exit_state(candidate)
        return {
            "id": candidate_id,
            "lifecycle_id": lifecycle_id,
            "instrument": candidate.instrument,
            "direction": candidate.direction,
            "underlying_direction": candidate.direction,
            "trade_side": f"BUY {option_type}" if is_option and option_type else candidate.direction,
            "price": candidate.price,
            "entry_price": candidate.price,
            "current_price": candidate.current_price or candidate.price,
            "pnl": candidate.pnl,
            "stop": display_stop,
            "target": display_target,
            "current_stop": float(candidate.stop or 0.0),
            "current_target": float(candidate.target or 0.0),
            "display_stop": display_stop,
            "display_target": display_target,
            "lots": candidate.lots,
            "lot_size": candidate.lot_size,
            "grade": candidate.grade,
            "confidence": candidate.confidence,
            "timeframe": candidate.timeframe,
            "inst_type": candidate.inst_type,
            "option_type": candidate.option_type,
            "atm_strike": candidate.atm_strike,
            "multiplier": candidate.multiplier,
            "trading_symbol": candidate.trading_symbol,
            "option_symbol": candidate.trading_symbol if is_option else "",
            "symbol_token": candidate.symbol_token,
            "rr": candidate.rr,
            "score": candidate.score,
            "reasons": candidate.reasons,
            "status": getattr(candidate, "status", "TRADE SIGNAL"),
            "action": getattr(candidate, "action", "ENTRY"),
            "peak_pnl": float(getattr(candidate, "peak_pnl", 0.0) or 0.0),
            "max_drawdown": float(getattr(candidate, "max_drawdown", 0.0) or 0.0),
            # Persisted so a mid-session restart does not leave a trade with a path that
            # begins partway through — a truncated path reads as a position that never
            # visited levels it did visit, which is worse than no path at all.
            "pnl_path": [[float(t), float(p)] for t, p in (getattr(candidate, "pnl_path", None) or [])],
            "runner_mode": bool(getattr(candidate, "runner_mode", False)),
            "initial_stop": float(getattr(candidate, "initial_stop", getattr(candidate, "stop", 0.0)) or 0.0),
            "entry_spot": float(getattr(candidate, "entry_spot", 0.0) or 0.0),
            "scalp_lock_mode": bool(getattr(candidate, "scalp_lock_mode", False)),
            "location_risk": str(getattr(candidate, "location_risk", "") or ""),
            "location_position_pct": float(getattr(candidate, "location_position_pct", 0.0) or 0.0),
            "location_decision": str(getattr(candidate, "location_decision", "ALLOW") or "ALLOW"),
            "accepted_by_gate": bool(getattr(candidate, "accepted_by_gate", False)),
            "watch_only": bool(getattr(candidate, "watch_only", False)),
            "adx_value": float(getattr(candidate, "adx_value", 0.0) or 0.0),
            "impulse_confirmed": bool(getattr(candidate, "impulse_confirmed", False)),
            "is_explosive_bypass": bool(getattr(candidate, "is_explosive_bypass", False)),
            "power_move": bool(getattr(candidate, "power_move", False)),
            "fifteen_min_choppy_scalp_entry": bool(getattr(candidate, "fifteen_min_choppy_scalp_entry", False)),
            "market_wide_reversal_entry": bool(getattr(candidate, "market_wide_reversal_entry", False)),
            "one_way_cascade_entry": bool(getattr(candidate, "one_way_cascade_entry", False)),
            "one_way_cascade_context": getattr(candidate, "one_way_cascade_context", {}) or {},
            "fifteen_min_choppy_scalp_context": getattr(candidate, "fifteen_min_choppy_scalp_context", {}) or {},
            "market_regime": str(getattr(candidate, "market_regime", "") or ""),
            "regime_raw": str(regime_ctx.get("raw_regime", "") or ""),
            "regime_guarded": str(regime_ctx.get("guarded_regime", "") or ""),
            "regime_smoothed": str(regime_ctx.get("smoothed_regime", regime_ctx.get("regime", "")) or ""),
            "regime_conviction_label": str(regime_ctx.get("conviction_label", "") or ""),
            "regime_conviction_summary": str(regime_ctx.get("conviction_summary", "") or ""),
            "regime_conviction_vector": dict(regime_ctx.get("conviction_vector", {}) or {}),
            "intelligence_score": float(getattr(candidate, "intelligence_score", 0.0) or 0.0),
            "market_intelligence_context": mi_ctx,
            "strategy_revision": str(getattr(candidate, "strategy_revision", "") or ""),
            "strategy_direction_mode": str(getattr(candidate, "strategy_direction_mode", "") or ""),
            "data_provenance": str(getattr(candidate, "data_provenance", "") or ""),
            "price_action_verdict": str(getattr(candidate, "price_action_verdict", "") or ""),
            "price_action_score": float(getattr(candidate, "price_action_score", 0.0) or 0.0),
            "market_structure_signal": str(market_structure.get("signal", "") or ""),
            "market_structure_state": str(market_structure.get("state", "") or ""),
            "market_structure_poc": float(market_structure.get("poc", 0.0) or 0.0),
            "market_structure_vah": float(market_structure.get("vah", 0.0) or 0.0),
            "market_structure_val": float(market_structure.get("val", 0.0) or 0.0),
            "aroon_trend": str(aroon_ctx.get("trend", "") or ""),
            "aroon_freshness": str(aroon_ctx.get("freshness", "") or ""),
            "wavetrend_exhaustion": str(wavetrend_ctx.get("exhaustion", "") or ""),
            "quote_verified": bool(getattr(candidate, "quote_verified", False)),
            "quote_source": str(getattr(candidate, "quote_source", "") or ""),
            "entry_quote_verified": bool(getattr(candidate, "entry_quote_verified", getattr(candidate, "quote_verified", False))),
            "entry_quote_source": str(getattr(candidate, "entry_quote_source", "") or ""),
            "live_quote_stale": bool(getattr(candidate, "live_quote_stale", False)),
            "execution_bid_price": float(getattr(candidate, "execution_bid_price", 0.0) or 0.0),
            "execution_ask_price": float(getattr(candidate, "execution_ask_price", 0.0) or 0.0),
            "execution_touch_source": str(getattr(candidate, "execution_touch_source", "") or ""),
            "execution_touch_age_seconds": float(getattr(candidate, "execution_touch_age_seconds", 0.0) or 0.0),
            "execution_touch_usable": bool(getattr(candidate, "execution_touch_usable", False)),
            "execution_touch_reason": str(getattr(candidate, "execution_touch_reason", "") or ""),
            "source_engine": str(getattr(candidate, "source_engine", "") or ""),
            "source_engines": list(getattr(candidate, "source_engines", []) or []),
            "source_lane": str(getattr(candidate, "source_lane", "") or ""),
            "quad_union_entry": bool(getattr(candidate, "quad_union_entry", False)),
            "raw_union_entry": bool(getattr(candidate, "raw_union_entry", False)),
            "signal_fire_mode": str(
                getattr(candidate, "signal_fire_mode", "INTRACANDLE") or "INTRACANDLE"
            ),
            "entered_intracandle": bool(getattr(candidate, "entered_intracandle", True)),
            "exit_reason": getattr(candidate, "exit_reason", ""),
            "is_exit": getattr(candidate, "action", "ENTRY") == "EXIT",
            **manual_exit_state,
            "signal_timestamp": (
                signal_ts.isoformat()
                if signal_ts is not None
                else ""
            ),
            "source_signal_timestamp": (
                signal_ts.isoformat()
                if signal_ts is not None
                else ""
            ),
            "entry_timestamp": (
                entry_ts.isoformat()
                if entry_ts is not None
                else ""
            ),
            "entry_time": (
                entry_ts.isoformat()
                if entry_ts is not None
                else ""
            ),
            "exit_timestamp": (
                getattr(candidate, "exit_timestamp").isoformat()
                if getattr(candidate, "exit_timestamp", None)
                else ""
            ),
            "exit_price": (
                float(getattr(candidate, "exit_price", 0.0) or candidate.current_price or candidate.price)
                if getattr(candidate, "action", "ENTRY") == "EXIT"
                else 0.0
            ),
            "timestamp": (
                entry_ts.isoformat()
                if entry_ts is not None
                else ""
            ),
        }

    def _is_premium_long_candidate(self, candidate: TradeCandidate) -> bool:
        return str(getattr(candidate, "inst_type", "") or "").upper() == "OPT"

    def _candidate_price_direction(self, candidate: TradeCandidate) -> str:
        """Return direction in the traded contract's own price space."""
        if self._is_premium_long_candidate(candidate):
            return "LONG"
        return str(getattr(candidate, "direction", "LONG") or "LONG").upper()

    def _synthetic_option_mark(self, trade, current_spot: float) -> float:
        """Estimate option premium with signed delta + theta decay when no live quote.

        Previously delta-only (premium never decayed with time — overstated held-option
        value and mispriced stops). Now mirrors the historical-sim model so live and
        backtest agree: premium moves by (spot_change * signed delta) and erodes by a
        time-based theta decay (halved while moving in our favour).
        """
        if float(getattr(trade, "entry_spot", 0.0) or 0.0) <= 0:
            return float(getattr(trade, "entry_price", 0.0) or 0.0)
        entry_price = float(trade.entry_price)
        spot_change = float(current_spot) - float(trade.entry_spot)
        signed_delta = float(getattr(trade, "instrument_multiplier", 0.5) or 0.5)
        mark = entry_price + (spot_change * signed_delta)
        # ── Theta decay (parity with historical sim premium model) ──
        try:
            entry_time = getattr(trade, "entry_time", None)
            if entry_time is not None:
                et = entry_time if getattr(entry_time, "tzinfo", None) else IST.localize(entry_time)
                et = et.astimezone(IST)
                hours_held = (datetime.now(IST) - et).total_seconds() / 3600.0
                if hours_held > 0:
                    dte = self.expiry.get_dte(trade.instrument, et.date())
                    actual_dte = dte + 7 if dte <= 1 else dte
                    theta_rate = 0.05 if actual_dte == 0 else (0.02 if actual_dte == 1 else 0.005)
                    theta_decay = entry_price * theta_rate * hours_held
                    if (spot_change * signed_delta) > 0:  # premium moving in our favour
                        theta_decay *= 0.5
                    mark -= theta_decay
        except Exception as exc:
            logger.debug(f"Synthetic theta decay skipped for {getattr(trade, 'instrument', '')}: {exc}")
        return max(0.05, mark)

    def _candidate_gross_pnl(self, candidate: TradeCandidate, exit_px: float) -> float:
        if getattr(candidate, "action", "ENTRY") == "NO_ENTRY":
            return 0.0
        qty = int(getattr(candidate, "lots", 1) or 1) * int(getattr(candidate, "lot_size", 1) or 1)
        mult = getattr(candidate, "multiplier", 1.0) if getattr(candidate, "inst_type", "FUT") != "OPT" else 1.0
        if getattr(self, "_is_premium_long_candidate", lambda x: False)(candidate):
            return (exit_px - candidate.price) * qty * mult
        if candidate.direction == "LONG":
            return (exit_px - candidate.price) * qty * mult
        return (candidate.price - exit_px) * qty * mult

    def _candidate_net_pnl(self, candidate: TradeCandidate, exit_px: float) -> float:
        if getattr(candidate, "action", "ENTRY") == "NO_ENTRY":
            return 0.0
        settings = get_settings()
        # Dashboard/session signals are advisory marks, not simulated fills, so this must
        # stay deterministic in (entry, exit, qty) and add no per-tick slippage.
        #
        # The flat opt_cost/fut_cost IS the real broker bill: measured against Zerodha's
        # published rates, a NIFTY 232.85 x 65 option round trip is Rs.75 (brokerage 40 +
        # STT 15.14 + exchange 10.60 + GST 9.11 + stamp 0.45), and the four indices span
        # Rs.68-86 against a configured 80.
        #
        # estimate_trade_charges is deliberately NOT used here. Its own docstring says it
        # returns "flat cost + modeled slippage", and on these rows that slippage doubles
        # the figure to Rs.149-206. These are advisory marks, not simulated fills — the
        # exit price already IS where the row would print — so adding a modeled spread on
        # top charges the same cost twice. I had swapped this to the model on 2026-08-10
        # believing the flat figure understated the bill; it does not, and the comment
        # this replaced was right.
        charges = (
            float(getattr(settings, "opt_cost", 80.0) or 80.0)
            if self._is_premium_long_candidate(candidate)
            else float(getattr(settings, "fut_cost", 200.0) or 200.0)
        )
        return round(self._candidate_gross_pnl(candidate, exit_px) - charges, 2)

    # A ratio this far above anything the tape has ever produced is corrupt data, not a
    # market event. Measured across every stored series: the highest GENUINE reading is
    # 310x (SENSEX 1min, whose volume base is thin enough that one busy minute against a
    # small average is legitimate), and p99.9 across series runs 4.7-69x. A malformed bar
    # produced 1e12 in the stress harness and would have cleared every surge gate.
    #
    # 1000x sits ~3x above the highest real reading, so it cannot reject a genuine surge,
    # and it is many orders of magnitude below corruption. Treated as UNMEASURABLE rather
    # than clamped: a number this size is not evidence of anything, and this codebase's
    # recurring failure is exactly that — turning absent or broken data into a verdict.
    SURGE_RATIO_IMPLAUSIBLE = 1000.0

    @staticmethod
    def _surge_prior_mean(prior):
        """Average volume of the prior bars, or None when it cannot be measured.

        Bars with NO volume are excluded rather than averaged in. Index history carries
        volume 0 — that was the original outage — so a lookback at session open is mostly
        zero-volume historical bars plus a few live ones. Averaging the zeros drags the
        denominator down and FABRICATES a surge: 15 zero bars plus 6 identical live bars
        produced a 4.0x ratio, and 18 plus 3 produced 10.0x, both clearing the 2.5x gate
        that is the only route a 1min signal has into a live entry.

        Requires at least 5 measured bars, matching the volume profiler's threshold, so a
        thin window reads as unmeasurable rather than as a breakout.
        """
        try:
            volumes = pd.to_numeric(prior["volume"], errors="coerce").fillna(0.0)
        except Exception:
            return None
        measured = volumes[volumes > 0]
        if len(measured) < 5:
            return None
        mean = float(measured.mean())
        return mean if mean > 0 else None

    @staticmethod
    def _volume_window_is_homogeneous(recent) -> bool:
        """False when the window mixes volume units, so no ratio across it is meaningful.

        Index volume can switch mid-session between Fyers cash-market shares and the
        broker's near-month futures contracts. Both are legitimate; they are simply not
        the same quantity. Comparing a bar in one against an average of the other
        manufactures a surge out of a feed failover.
        """
        if "volume_basis" not in getattr(recent, "columns", []):
            return True
        try:
            seen = set()
            for value in recent["volume_basis"].tolist():
                text = str(value).strip()
                # Historical backfill frames carry no basis, so concatenating them with
                # live rows leaves NaN. float('nan') is TRUTHY, so an `or ""` test let
                # "nan" through as if it were a distinct unit — which marked every
                # post-backfill window mixed, returned None from the thrust metrics, and
                # silently re-killed the 1min surge signal this guard was added to
                # protect. Unknown is not a unit.
                if not text or text.lower() in {"nan", "none"}:
                    continue
                if text == "MIXED":
                    return False        # a resampled bucket that already spans a switch
                seen.add(text)
        except Exception:
            return True
        return len(seen) <= 1

    def _detect_power_move(
        self,
        instrument: str,
        timeframe: str,
        signal_type: str,
        adx_value: float = 0.0,
        intel_score: float = 0.0,
        trend_15m_agrees: bool = False,
        as_of=None,
    ) -> bool:
        """Data-confirmed power/breakout move detector — works live AND historical.

        Computes the volume-surge / range-expansion / directional-close metrics from
        the signal candle (latest, or the candle as-of a historical timestamp) and
        defers the all-4-factor decision to the policy function. Used by both the
        live path and the HISTORICAL backfill reconstruction.
        """
        try:
            settings = get_settings()
            if not self._setting_enabled(getattr(settings, "power_move_override_enabled", True), True):
                return False
            df = self.candles.get_candles(instrument, timeframe)
            if df is None or "volume" not in getattr(df, "columns", []):
                return False
            if as_of is not None:
                try:
                    df = df[df.index <= as_of]
                except Exception:
                    pass
            if len(df) < 6:
                return False
            lookback = max(5, int(getattr(settings, "power_move_volume_lookback", 20) or 20))
            recent = df.tail(lookback + 1)
            last = recent.iloc[-1]
            prior = recent.iloc[:-1]
            if len(prior) < 3:
                return False
            high = float(last["high"]); low = float(last["low"]); close = float(last["close"])
            rng = high - low
            if rng <= 0:
                return False
            if not Scanner._volume_window_is_homogeneous(recent):
                # The lookback straddles a volume-unit change (Fyers cash shares vs
                # near-month futures contracts, ~1000x apart). A ratio across that
                # boundary is ~100x with no change in participation whatsoever, and
                # it clears every surge gate — including the 2.5x that is the only
                # route a 1min signal has into a live entry. The per-candle rebase
                # cannot see this: it only protects the delta INSIDE one bar.
                return False
            prior_vol = Scanner._surge_prior_mean(prior)
            if prior_vol is None:
                return False
            volume_ratio = float(last["volume"]) / prior_vol
            tr = (prior["high"] - prior["low"]).abs()
            atr = float(tr.tail(14).mean()) if len(tr) else 0.0
            range_atr_ratio = (rng / atr) if atr > 0 else 0.0
            if str(signal_type).upper() in ("BUY", "LONG"):
                close_location = (close - low) / rng
            else:
                close_location = (high - close) / rng
            confirmed = SignalProcessor._power_move_confirmed(
                volume_ratio=volume_ratio,
                range_atr_ratio=range_atr_ratio,
                close_location=close_location,
                adx_value=float(adx_value or 0.0),
                intel_score=float(intel_score or 0.0),
                trend_15m_agrees=bool(trend_15m_agrees),
                settings=settings,
            )
            if confirmed:
                self.log_event(
                    f"⚡ POWER-MOVE confirmed: {instrument} {timeframe} {signal_type} "
                    f"(vol {volume_ratio:.1f}x, range {range_atr_ratio:.1f}x ATR, "
                    f"close {close_location:.0%} of range) — override eligible.",
                    "trade",
                )
            return confirmed
        except Exception as exc:
            logger.debug(f"Power-move detection failed for {instrument} {timeframe}: {exc}")
            return False

    def _candle_thrust_metrics(
        self,
        instrument: str,
        timeframe: str,
        signal_type: str,
        as_of=None,
    ) -> Optional[Dict[str, float]]:
        """Raw volume-surge / range-expansion / directional-close metrics for the signal candle.

        Shared metric extractor used by the fast volume-spike entry detector. Works live
        (latest candle) and historical (the candle as-of a timestamp, with strict
        no-future-leak slicing). Returns ``None`` when data is insufficient or the candle
        is degenerate (zero range), otherwise a dict with ``volume_ratio``,
        ``range_atr_ratio`` and ``close_location``.
        """
        try:
            df = self.candles.get_candles(instrument, timeframe)
            if df is None or "volume" not in getattr(df, "columns", []):
                return None
            if as_of is not None:
                try:
                    df = df[df.index <= as_of]
                except Exception:
                    pass
            if len(df) < 6:
                return None
            lookback = max(5, int(getattr(get_settings(), "power_move_volume_lookback", 20) or 20))
            recent = df.tail(lookback + 1)
            last = recent.iloc[-1]
            prior = recent.iloc[:-1]
            if len(prior) < 3:
                return None
            high = float(last["high"]); low = float(last["low"]); close = float(last["close"])
            rng = high - low
            if rng <= 0:
                return None
            if not Scanner._volume_window_is_homogeneous(recent):
                # The lookback straddles a volume-unit change (Fyers cash shares vs
                # near-month futures contracts, ~1000x apart). A ratio across that
                # boundary is ~100x with no change in participation whatsoever, and
                # it clears every surge gate — including the 2.5x that is the only
                # route a 1min signal has into a live entry. The per-candle rebase
                # cannot see this: it only protects the delta INSIDE one bar.
                return None
            prior_vol = Scanner._surge_prior_mean(prior)
            # The NUMERATOR was never guarded. _surge_prior_mean fixed the denominator
            # (zero bars were dragging it down and FABRICATING 4x/10x surges), but the
            # signal bar's own volume is read raw — and on a cash index the live right
            # edge carries no traded volume at all: measured 13 of the last 20 bars on
            # 1min for every index, versus 1/20 on 5min and 0/20 on 15min. A fresh 1min
            # signal therefore always computed 0 / prior_mean = 0.00x and could never
            # clear the 2.2x floor that this comment block itself calls "the only route
            # a 1min signal has into a live entry". That is why no 1min trade has ever
            # appeared, live or in backtest: the fix for the false positive created a
            # permanent false negative.
            #
            # 0.00x is a DEFINITE claim ("no surge") built from ABSENT data, which is
            # this codebase's cardinal error. Unmeasurable must read as unmeasurable.
            measured_vol = float(last.get("volume", 0.0) or 0.0)
            volume_basis = "TRADED"
            # Either side being unmeasurable sends this to the proxy. Checking the
            # denominator first and returning early would have killed the fallback in
            # exactly the case it exists for: on a cash index the WHOLE window can be
            # volume-less, so _surge_prior_mean answers None and the tick path would
            # never be reached.
            if measured_vol <= 0.0 or prior_vol is None:
                # Tick activity is the only participation measure a cash index publishes
                # in real time (CandleBuilder maintains tick_count per bar). Used for
                # BOTH sides of the ratio so it stays like-for-like, and tagged so the
                # gate can apply a threshold calibrated to ticks rather than to volume —
                # tick counts are far less dispersed than traded quantity, so reusing the
                # traded floor on them would be the same inherited-threshold mistake.
                if not Scanner._setting_enabled(
                    getattr(get_settings(), "surge_tick_proxy_enabled", False), False
                ):
                    # Ships OFF: a tick threshold cannot be calibrated until a live
                    # session has been recorded, and guessing one would re-run tonight's
                    # other finding (a threshold applied to a quantity it was not cut
                    # for). Until then this abstains, which is honest — and no worse
                    # than today, where the same bar silently scored 0.00x.
                    return None
                proxy = Scanner._surge_tick_ratio(recent)
                if proxy is None:
                    return None
                volume_ratio, surge_pct = proxy
                volume_basis = "TICK_ACTIVITY"
            else:
                volume_ratio = measured_vol / prior_vol
                surge_pct = Scanner._surge_percentile(
                    pd.to_numeric(prior["volume"], errors="coerce").fillna(0.0),
                    measured_vol,
                )
            tr = (prior["high"] - prior["low"]).abs()
            atr = float(tr.tail(14).mean()) if len(tr) else 0.0
            range_atr_ratio = (rng / atr) if atr > 0 else 0.0
            if str(signal_type).upper() in ("BUY", "LONG"):
                close_location = (close - low) / rng
            else:
                close_location = (high - close) / rng
            if not np.isfinite(volume_ratio) or volume_ratio > Scanner.SURGE_RATIO_IMPLAUSIBLE:
                logger.warning(
                    f"Implausible surge ratio for {instrument} {timeframe}: "
                    f"{volume_ratio:.1f}x on {volume_basis} — treating as unmeasurable."
                )
                return None
            # range/ATR has the identical shape and the identical failure. A dead-flat
            # window (a halt, a stale feed repeating one price, a motionless pre-open)
            # drives ATR toward zero, and the next real bar then divides by it: measured
            # 500,000x in the stress harness against gates that sit at 1.2-1.5x, so the
            # range test stops protecting anything. A truly flat window is already safe
            # (atr == 0 yields 0.0 and fails the gate); it is the NEAR-zero one that bites.
            #
            # Same measured discipline as above: the highest genuine reading across every
            # stored series is 279x (MIDCPNIFTY 1min — 1min legitimately reaches 130-280x
            # while 5min/15min stay under 17x), so a bound anywhere near the typical range
            # would reject real bars. The same 1000x ceiling clears it by ~3.6x.
            if not np.isfinite(range_atr_ratio) or range_atr_ratio > Scanner.SURGE_RATIO_IMPLAUSIBLE:
                logger.warning(
                    f"Implausible range/ATR for {instrument} {timeframe}: "
                    f"{range_atr_ratio:.1f}x — treating as unmeasurable."
                )
                return None
            return {
                "volume_ratio": volume_ratio,
                "range_atr_ratio": range_atr_ratio,
                "close_location": close_location,
                "volume_basis": volume_basis,
                "surge_percentile": float(surge_pct) if surge_pct is not None else -1.0,
            }
        except Exception as exc:
            logger.debug(f"Candle thrust metrics failed for {instrument} {timeframe}: {exc}")
            return None

    @staticmethod
    def _surge_tick_ratio(recent):
        """(ratio, percentile) of the signal bar's tick activity within its window.

        Same shape as _surge_prior_mean — zero bars are EXCLUDED rather than averaged
        in, and at least 5 measured bars are required, so a thin window reads as
        unmeasurable instead of as a breakout. Returns None when tick activity cannot be
        measured either, keeping "no data" distinct from "no surge".

        The PERCENTILE is what the gate judges, not the ratio. A fixed ratio floor is
        basis-dependent: traded volume is heavily tailed (a z-score of 5 still admits
        4.7% of 1min bars) while tick counts are near-Poisson, so reusing the 2.2x
        traded floor on ticks would admit almost nothing and leave 1min as dead as it
        was. Percentile rank is uniform for any continuous distribution, so the SAME
        threshold means the same thing on either measurement — "among the busiest N% of
        recent minutes for this instrument, right now".

        Calibrated on the real 1min candles: ratio>=2.2 admits 4.73% of measurable
        traded-volume bars, and rank>=97 admits 4.98% — the same strictness, expressed
        in a form that survives the change of basis.
        """
        try:
            import pandas as _pd

            if "tick_count" not in getattr(recent, "columns", []):
                return None
            ticks = _pd.to_numeric(recent["tick_count"], errors="coerce").fillna(0.0)
            if len(ticks) < 2:
                return None
            last_ticks = float(ticks.iloc[-1])
            prior = ticks.iloc[:-1]
            measured = prior[prior > 0]
            if last_ticks <= 0 or len(measured) < 5:
                return None
            mean = float(measured.mean())
            if mean <= 0:
                return None
            pct = 100.0 * float((measured < last_ticks).mean())
            return last_ticks / mean, pct
        except Exception:
            return None

    @staticmethod
    def _surge_percentile(prior_series, last_value):
        """Where the signal bar sits within its own measured window, 0-100."""
        try:
            measured = prior_series[prior_series > 0]
            if len(measured) < 5 or float(last_value) <= 0:
                return None
            return 100.0 * float((measured < float(last_value)).mean())
        except Exception:
            return None

    def _market_wide_reversal_context(
        self,
        instrument: str,
        timeframe: str,
        signal_type: str,
        signal_timestamp,
    ) -> Optional[Dict[str, Any]]:
        """Confirm synchronized 5m/15m reversal across core indices.

        A core signal can pass on 2/3 NIFTY, BANKNIFTY, SENSEX agreement.
        MIDCPNIFTY can join as a sympathy trade only when it has its own same-side
        raw signal and at least two core indices agree.
        """
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "market_wide_reversal_enabled", True), True):
            return None
        tf = str(timeframe or "")
        if tf not in {"5min", "15min"} or signal_timestamp is None:
            return None
        sig_type = str(signal_type or "").upper()
        if sig_type not in {"BUY", "SELL"}:
            return None
        try:
            ts = (
                signal_timestamp.astimezone(IST).replace(tzinfo=None)
                if getattr(signal_timestamp, "tzinfo", None) is not None
                else signal_timestamp
            )
        except Exception:
            return None

        max_skew_attr = (
            "market_wide_reversal_max_skew_seconds_15min"
            if tf == "15min"
            else "market_wide_reversal_max_skew_seconds_5min"
        )
        range_attr = (
            "market_wide_reversal_min_range_atr_ratio_15min"
            if tf == "15min"
            else "market_wide_reversal_min_range_atr_ratio_5min"
        )
        midcap_range_attr = (
            "market_wide_reversal_midcap_min_range_atr_ratio_15min"
            if tf == "15min"
            else "market_wide_reversal_midcap_min_range_atr_ratio_5min"
        )
        max_skew = max(0.0, float(getattr(settings, max_skew_attr, 900.0 if tf == "15min" else 180.0) or 0.0))
        min_core_votes = max(1, int(getattr(settings, "market_wide_reversal_core_votes", 2) or 2))
        min_total_votes = max(1, int(getattr(settings, "market_wide_reversal_total_votes", 2) or 2))
        min_range = max(
            0.0,
            float(
                getattr(
                    settings,
                    range_attr,
                    getattr(settings, "market_wide_reversal_min_range_atr_ratio", 1.10),
                )
                or 0.0
            ),
        )
        midcap_min_range = max(
            0.0,
            float(getattr(settings, midcap_range_attr, 0.45 if tf == "15min" else 0.65) or 0.0),
        )
        min_close = max(0.0, float(getattr(settings, "market_wide_reversal_min_close_location", 0.65) or 0.65))

        active = list(getattr(self, "active_indices", []) or [])
        if not active:
            active = ["NIFTY", "BANKNIFTY", "SENSEX", "MIDCPNIFTY"]

        candidate_base = str(instrument or "").split()[0].upper()
        votes: Dict[str, Dict[str, Any]] = {}
        for inst in active:
            result = (getattr(self, "_cached_results", {}) or {}).get(f"{inst}_{tf}") or {}
            best = None
            best_delta = None
            for sig in list(result.get("signals") or []):
                if str(getattr(sig, "signal_type", "") or "").upper() != sig_type:
                    continue
                sig_ts = getattr(sig, "timestamp", None)
                if sig_ts is None:
                    continue
                try:
                    sig_ts = (
                        sig_ts.astimezone(IST).replace(tzinfo=None)
                        if getattr(sig_ts, "tzinfo", None) is not None
                        else sig_ts
                    )
                    delta = abs((sig_ts - ts).total_seconds())
                except Exception:
                    continue
                if delta <= max_skew and (best_delta is None or delta < best_delta):
                    best = sig
                    best_delta = delta
            if best is None and inst == candidate_base:
                best = type("_SignalRef", (), {"timestamp": ts, "signal_type": sig_type})()
                best_delta = 0.0
            if best is None:
                continue

            metrics = self._candle_thrust_metrics(inst, tf, sig_type, as_of=getattr(best, "timestamp", ts)) or {}
            range_ratio = float(metrics.get("range_atr_ratio", 0.0) or 0.0)
            close_location = float(metrics.get("close_location", 0.0) or 0.0)
            midcap_core_sympathy = bool(
                inst == self.MIDCAP_CORRELATED_INDEX
                and candidate_base == self.MIDCAP_CORRELATED_INDEX
                and range_ratio >= midcap_min_range
                and close_location >= min_close
            )
            if (range_ratio < min_range or close_location < min_close) and not midcap_core_sympathy:
                continue
            votes[inst] = {
                "timestamp": getattr(best, "timestamp", ts),
                "range_atr_ratio": range_ratio,
                "close_location": close_location,
                "volume_ratio": float(metrics.get("volume_ratio", 0.0) or 0.0),
                "skew_seconds": float(best_delta or 0.0),
                "midcap_core_sympathy": midcap_core_sympathy,
            }

        if candidate_base and candidate_base not in votes:
            return None
        core_votes = sorted(inst for inst in votes if inst in self.CORE_CORRELATED_INDICES)
        total_votes = sorted(votes)
        if len(core_votes) < min_core_votes or len(total_votes) < min_total_votes:
            return None

        return {
            "enabled": True,
            "timeframe": tf,
            "signal_type": sig_type,
            "core_votes": len(core_votes),
            "total_votes": len(total_votes),
            "core_indices": core_votes,
            "indices": total_votes,
            "votes": votes,
            "reason": (
                f"market-wide {sig_type} reversal: core {len(core_votes)}/3, "
                f"total {len(total_votes)}, range>={min_range:.2f}x, close>={min_close:.0%}"
            ),
        }

    def _evaluate_market_ltp_shock(
        self,
        instrument: str,
        signal_type: str,
        signal_timestamp=None,
        timeframe: str = "5min",
    ) -> Optional[Dict[str, Any]]:
        """Detect multi-index LTP shock (dump or rally) over a short lookback.

        Bidirectional late-session path:
          SELL + multi-index drop ≥0.20–0.35% in ≤3–5 min + volume → PE short
          BUY  + multi-index rally of the same size → CE long
        Used to yield sticky TREND_DAY guards, relax opposite-trade waits, and
        shorten stabilization. Works on 1min/5min (15min still respects cutoff).
        """
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "market_ltp_shock_enabled", True), True):
            return None
        sig_type = str(signal_type or "").upper()
        if sig_type not in {"BUY", "SELL"}:
            return None
        tf = str(timeframe or "").lower()
        if tf == "1min" and not self._setting_enabled(
            getattr(settings, "market_ltp_shock_allow_1min", True), True
        ):
            return None
        if tf == "5min" and not self._setting_enabled(
            getattr(settings, "market_ltp_shock_allow_5min", True), True
        ):
            return None
        if tf == "15min":
            # Shock path is intentionally fast TF only — keep 15min cutoff rules.
            return None

        # Full-sensitivity window (default 14:00–15:10 IST). Outside it:
        #   mode "strong" — only genuine crash/melt-up bursts (>= outside strong
        #   floor across the voting indices) qualify; mode "off" — engine idle.
        in_window = True
        try:
            as_of_for_window = signal_timestamp
            if as_of_for_window is not None and getattr(as_of_for_window, "tzinfo", None) is not None:
                as_of_for_window = as_of_for_window.astimezone(IST).replace(tzinfo=None)
            if as_of_for_window is not None:
                t_now = as_of_for_window.time()
            else:
                t_now = datetime.now(IST).replace(tzinfo=None).time()
            win_start = str(
                getattr(settings, "market_ltp_shock_session_start", None)
                or getattr(settings, "market_ltp_shock_session_override_start", "14:00")
                or "14:00"
            )
            win_end = str(getattr(settings, "market_ltp_shock_session_end", "15:10") or "15:10")
            start_t = datetime.strptime(win_start, "%H:%M").time()
            end_t = datetime.strptime(win_end, "%H:%M").time()
            in_window = start_t <= t_now <= end_t
        except Exception:
            in_window = True
        outside_mode = str(
            getattr(settings, "market_ltp_shock_outside_window_mode", "strong") or "strong"
        ).lower()
        if not in_window and outside_mode != "strong":
            return None

        min_move = max(
            0.05,
            float(getattr(settings, "market_ltp_shock_min_move_pct", 0.20) or 0.20),
        )
        if not in_window:
            # Strong-tier only outside the window: raise the per-index floor so a
            # routine 0.20% opening drive can never hijack entries into scalps.
            min_move = max(
                min_move,
                float(
                    getattr(settings, "market_ltp_shock_outside_strong_move_pct", 0.35)
                    or 0.35
                ),
            )
        strong_move = max(
            min_move,
            float(getattr(settings, "market_ltp_shock_strong_move_pct", 0.35) or 0.35),
        )
        lookback_max = max(
            1,
            int(getattr(settings, "market_ltp_shock_lookback_minutes", 5) or 5),
        )
        lookback_min = max(
            1,
            min(
                lookback_max,
                int(getattr(settings, "market_ltp_shock_min_lookback_minutes", 3) or 3),
            ),
        )
        min_indices = max(1, int(getattr(settings, "market_ltp_shock_min_indices", 2) or 2))
        min_core = max(1, int(getattr(settings, "market_ltp_shock_min_core_indices", 2) or 2))
        min_vol = max(
            0.0,
            float(getattr(settings, "market_ltp_shock_min_volume_ratio", 1.10) or 1.10),
        )

        active = list(getattr(self, "active_indices", []) or []) or [
            "NIFTY",
            "BANKNIFTY",
            "SENSEX",
            "MIDCPNIFTY",
        ]
        candidate_base = str(instrument or "").split()[0].upper()
        direction = -1.0 if sig_type == "SELL" else 1.0

        try:
            as_of = signal_timestamp
            if as_of is not None and getattr(as_of, "tzinfo", None) is not None:
                as_of = as_of.astimezone(IST).replace(tzinfo=None)
        except Exception:
            as_of = None

        votes: Dict[str, Dict[str, Any]] = {}
        candles = getattr(self, "candles", None)
        for inst in active:
            try:
                df = None
                if candles is not None:
                    df = candles.get_candles(inst, "1min")
                if df is None or getattr(df, "empty", True):
                    continue
                frame = df
                if as_of is not None:
                    try:
                        frame = df[df.index <= pd.Timestamp(as_of)]
                    except Exception:
                        frame = df
                if frame is None or len(frame) < (lookback_min + 1):
                    continue

                best_move = 0.0
                best_lookback = lookback_min
                last_close = float(frame["close"].iloc[-1] or 0.0)
                if last_close <= 0:
                    # Fall back to live LTP injection if bar is empty.
                    live = float(candles.get_latest_price(inst) or 0.0) if candles is not None else 0.0
                    if live <= 0:
                        continue
                    last_close = live

                for lb in range(lookback_min, lookback_max + 1):
                    if len(frame) <= lb:
                        break
                    ref = float(frame["close"].iloc[-(lb + 1)] or 0.0)
                    if ref <= 0:
                        continue
                    move_pct = (last_close - ref) / ref * 100.0
                    signed = move_pct * direction
                    if signed >= best_move:
                        best_move = signed
                        best_lookback = lb

                if best_move < min_move:
                    continue

                # Volume confirmation on the shock window.
                vol_window = frame.iloc[-(best_lookback + 1) :]
                vol = pd.to_numeric(
                    vol_window.get("volume", pd.Series(0.0, index=vol_window.index)),
                    errors="coerce",
                ).fillna(0.0)
                prior = frame.iloc[max(0, len(frame) - (best_lookback + 1) * 4) : -(best_lookback + 1)]
                prior_vol = pd.to_numeric(
                    prior.get("volume", pd.Series(0.0, index=prior.index))
                    if not prior.empty
                    else pd.Series(dtype=float),
                    errors="coerce",
                ).fillna(0.0)
                avg_shock = float(vol.mean()) if len(vol) else 0.0
                avg_prior = float(prior_vol.mean()) if len(prior_vol) else 0.0
                vol_ratio = (avg_shock / avg_prior) if avg_prior > 0 else (1.0 if avg_shock > 0 else 0.0)
                # Allow pure price shock when volume is unavailable; require ratio when present.
                if avg_prior > 0 and vol_ratio < min_vol and best_move < strong_move:
                    continue

                votes[inst] = {
                    "move_pct": round(best_move * direction, 4),  # raw signed %
                    "abs_move_pct": round(best_move, 4),
                    "lookback_minutes": int(best_lookback),
                    "volume_ratio": round(vol_ratio, 3),
                    "last_close": round(last_close, 2),
                }
            except Exception:
                continue

        if candidate_base and candidate_base not in votes:
            return None
        core_votes = sorted(inst for inst in votes if inst in self.CORE_CORRELATED_INDICES)
        total_votes = sorted(votes)
        if len(core_votes) < min_core or len(total_votes) < min_indices:
            return None

        avg_abs = (
            sum(float(v.get("abs_move_pct", 0.0) or 0.0) for v in votes.values()) / max(1, len(votes))
        )
        strong = avg_abs >= strong_move or any(
            float(v.get("abs_move_pct", 0.0) or 0.0) >= strong_move for v in votes.values()
        )
        side_label = "dump" if sig_type == "SELL" else "rally"
        return {
            "enabled": True,
            "type": "market_ltp_shock",
            "signal_type": sig_type,
            "side": side_label,
            "in_window": bool(in_window),
            "strong": bool(strong),
            "avg_abs_move_pct": round(avg_abs, 4),
            "min_move_pct": min_move,
            "lookback_minutes": lookback_max,
            "core_votes": len(core_votes),
            "total_votes": len(total_votes),
            "core_indices": core_votes,
            "indices": total_votes,
            "votes": votes,
            "timeframe": tf,
            "session_override": True,
            "reason": (
                f"market LTP {side_label}: core {len(core_votes)}/3, "
                f"total {len(total_votes)}, avg |move|={avg_abs:.2f}% "
                f"in ≤{lookback_max}m (≥{min_move:.2f}%)"
            ),
        }

    def _one_way_cascade_context(
        self,
        instrument: str,
        timeframe: str,
        signal_type: str,
        signal_timestamp,
    ) -> Optional[Dict[str, Any]]:
        """Detect a synchronized one-way thrust across the index basket.

        Unlike late-session reclaim this is not time-boxed. It is deliberately
        stricter: a broad candle-evidence basket must agree before old location,
        regime-memory, or profit-lock logic is relaxed.
        """
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "one_way_cascade_enabled", True), True):
            return None
        sig_type = str(signal_type or "").upper()
        if sig_type not in {"BUY", "SELL"}:
            return None
        candidate_tf = str(timeframe or "")
        if candidate_tf not in {"1min", "5min", "15min"} or signal_timestamp is None:
            return None
        try:
            ts = (
                signal_timestamp.astimezone(IST).replace(tzinfo=None)
                if getattr(signal_timestamp, "tzinfo", None) is not None
                else signal_timestamp
            )
        except Exception:
            return None

        active = list(getattr(self, "active_indices", []) or []) or [
            "NIFTY",
            "BANKNIFTY",
            "SENSEX",
            "MIDCPNIFTY",
        ]
        candidate_base = str(instrument or "").split()[0].upper()
        min_core_votes = max(1, int(getattr(settings, "one_way_cascade_core_votes", 3) or 3))
        min_total_votes = max(1, int(getattr(settings, "one_way_cascade_total_votes", 3) or 3))
        min_volume_votes = max(1, int(getattr(settings, "one_way_cascade_volume_votes", 3) or 3))
        min_volume = max(0.0, float(getattr(settings, "one_way_cascade_min_volume_ratio", 1.40) or 1.40))
        min_close = max(0.0, float(getattr(settings, "one_way_cascade_min_close_location", 0.68) or 0.68))
        range_thresholds = {
            "1min": max(0.0, float(getattr(settings, "one_way_cascade_min_range_atr_ratio_1min", 1.50) or 1.50)),
            "5min": max(0.0, float(getattr(settings, "one_way_cascade_min_range_atr_ratio_5min", 1.20) or 1.20)),
            "15min": max(0.0, float(getattr(settings, "one_way_cascade_min_range_atr_ratio_15min", 0.75) or 0.75)),
        }
        # Let a 1m raw signal qualify from 1m/5m breadth; 5m/15m signals can also
        # use the higher-timeframe confirmation that was present during the move.
        scan_tfs = ["1min", "5min"]
        if candidate_tf == "15min":
            scan_tfs.append("15min")
        elif candidate_tf == "5min":
            scan_tfs.append("15min")

        votes: Dict[str, Dict[str, Any]] = {}
        for inst in active:
            best_tf = ""
            best_score = -1.0
            best_evidence: Dict[str, Any] = {}
            frame_evidence: Dict[str, Dict[str, Any]] = {}
            for tf in scan_tfs:
                metrics = self._candle_thrust_metrics(inst, tf, sig_type, as_of=ts) or {}
                range_ratio = float(metrics.get("range_atr_ratio", 0.0) or 0.0)
                close_location = float(metrics.get("close_location", 0.0) or 0.0)
                volume_ratio = float(metrics.get("volume_ratio", 0.0) or 0.0)
                reclaim = self._directional_reclaim_snapshot(inst, tf, sig_type, as_of=ts)
                structure_ok = bool(reclaim.get("reclaimed"))
                frame_evidence[tf] = {
                    "range_atr_ratio": range_ratio,
                    "close_location": close_location,
                    "volume_ratio": volume_ratio,
                    "structure_reclaimed": structure_ok,
                }
                if (
                    range_ratio < range_thresholds.get(tf, range_thresholds["5min"])
                    or close_location < min_close
                    or volume_ratio < min_volume
                    or not structure_ok
                ):
                    continue
                score = (range_ratio * 0.45) + (close_location * 0.35) + (volume_ratio * 0.20)
                if score > best_score:
                    best_score = score
                    best_tf = tf
                    best_evidence = dict(frame_evidence[tf])

            if not best_evidence:
                continue
            votes[inst] = {
                "best_timeframe": best_tf,
                "score": best_score,
                "frames": frame_evidence,
                **best_evidence,
            }

        if candidate_base and candidate_base not in votes:
            return None
        core_votes = sorted(inst for inst in votes if inst in self.CORE_CORRELATED_INDICES)
        total_votes = sorted(votes)
        volume_votes = sorted(
            inst for inst, vote in votes.items()
            if float(vote.get("volume_ratio", 0.0) or 0.0) >= min_volume
        )
        if (
            len(core_votes) < min_core_votes
            or len(total_votes) < min_total_votes
            or len(volume_votes) < min_volume_votes
        ):
            return None

        move_label = "one-way upside cascade" if sig_type == "BUY" else "one-way downside cascade"
        runner_lock_pct = min(
            0.98,
            max(0.50, float(getattr(settings, "one_way_cascade_runner_lock_pct", 0.85) or 0.85)),
        )
        return {
            "enabled": True,
            "type": "one_way_cascade",
            "move_label": move_label,
            "timeframe": candidate_tf,
            "signal_type": sig_type,
            "core_votes": len(core_votes),
            "total_votes": len(total_votes),
            "volume_votes": len(volume_votes),
            "core_indices": core_votes,
            "indices": total_votes,
            "volume_indices": volume_votes,
            "votes": votes,
            "force_scalp_lock": False,
            "suppress_profit_lock": True,
            "runner_lock_pct": runner_lock_pct,
            "tight_stop_pct": float(getattr(settings, "one_way_cascade_options_sl_pct", 5.0) or 5.0),
            "reason": (
                f"{move_label}: core {len(core_votes)}/3, total {len(total_votes)}, "
                f"volume {len(volume_votes)}>={min_volume_votes} at {min_volume:.2f}x, "
                f"trail locks {runner_lock_pct:.0%} of total gain"
            ),
        }

    def _trade_signal_type_for_cascade(self, trade_like) -> str:
        inst_type = str(getattr(trade_like, "inst_type", "") or "").upper()
        option_type = str(getattr(trade_like, "option_type", "") or "").upper()
        if inst_type == "OPT":
            if option_type == "CE":
                return "BUY"
            if option_type == "PE":
                return "SELL"
        direction = str(getattr(trade_like, "direction", "") or "").upper()
        return "BUY" if direction == "LONG" else "SELL" if direction == "SHORT" else ""

    def _trade_one_way_cascade_context(self, trade_like, latest_time=None) -> Optional[Dict[str, Any]]:
        if trade_like is None:
            return None
        sig_type = self._trade_signal_type_for_cascade(trade_like)
        if sig_type not in {"BUY", "SELL"}:
            return None
        ts = latest_time or getattr(trade_like, "signal_timestamp", None)
        if ts is None:
            return None
        return self._one_way_cascade_context(
            getattr(trade_like, "instrument", ""),
            getattr(trade_like, "timeframe", "5min"),
            sig_type,
            ts,
        )

    @staticmethod
    def _time_in_window(value: dtime, start: dtime, end: dtime) -> bool:
        if start <= end:
            return start <= value <= end
        return value >= start or value <= end

    def _cached_signal_near(
        self,
        instrument: str,
        timeframe: str,
        signal_type: str,
        reference_ts,
        max_skew: float,
    ):
        result = (getattr(self, "_cached_results", {}) or {}).get(f"{instrument}_{timeframe}") or {}
        best = None
        best_delta = None
        sig_type = str(signal_type or "").upper()
        try:
            ref = (
                reference_ts.astimezone(IST).replace(tzinfo=None)
                if getattr(reference_ts, "tzinfo", None) is not None
                else reference_ts
            )
        except Exception:
            return None, None
        for sig in list(result.get("signals") or []):
            if str(getattr(sig, "signal_type", "") or "").upper() != sig_type:
                continue
            sig_ts = getattr(sig, "timestamp", None)
            if sig_ts is None:
                continue
            try:
                sig_ts = (
                    sig_ts.astimezone(IST).replace(tzinfo=None)
                    if getattr(sig_ts, "tzinfo", None) is not None
                    else sig_ts
                )
                delta = abs((sig_ts - ref).total_seconds())
            except Exception:
                continue
            if delta <= max_skew and (best_delta is None or delta < best_delta):
                best = sig
                best_delta = delta
        return best, best_delta

    def _directional_reclaim_snapshot(
        self,
        instrument: str,
        timeframe: str,
        signal_type: str,
        as_of=None,
    ) -> Dict[str, Any]:
        try:
            df = self.candles.get_candles(instrument, timeframe)
            if df is None or len(df) < 6:
                return {}
            work = df.copy()
            if not isinstance(work.index, pd.DatetimeIndex):
                if "timestamp" not in work.columns:
                    return {}
                work["timestamp"] = pd.to_datetime(work["timestamp"], errors="coerce")
                work = work.dropna(subset=["timestamp"]).set_index("timestamp")
            work = work.sort_index()
            if as_of is not None:
                ts = pd.Timestamp(as_of)
                if ts.tzinfo is not None:
                    ts = ts.tz_convert(IST).tz_localize(None)
                work = work[work.index <= ts]
            if len(work) < 6:
                return {}
            closes = work["close"].astype(float)
            highs = work["high"].astype(float) if "high" in work.columns else closes
            lows = work["low"].astype(float) if "low" in work.columns else closes
            opens = work["open"].astype(float) if "open" in work.columns else closes
            close = float(closes.iloc[-1])
            high = float(highs.iloc[-1])
            low = float(lows.iloc[-1])
            open_price = float(opens.iloc[-1])
            prev_close = float(closes.iloc[-2])
            rng = max(0.0, high - low)
            if close <= 0 or rng <= 0:
                return {}
            ema9 = float(closes.ewm(span=9, adjust=False).mean().iloc[-1])
            ema21 = float(closes.ewm(span=21, adjust=False).mean().iloc[-1])
            prior_high = float(highs.iloc[:-1].tail(5).max())
            prior_low = float(lows.iloc[:-1].tail(5).min())
            sig = str(signal_type or "").upper()
            if sig == "BUY":
                close_location = (close - low) / rng
                ema_reclaim = close >= ema9 and close >= open_price and close >= prev_close
                structure_reclaim = close >= prior_high
            elif sig == "SELL":
                close_location = (high - close) / rng
                ema_reclaim = close <= ema9 and close <= open_price and close <= prev_close
                structure_reclaim = close <= prior_low
            else:
                return {}
            vwap_reclaim = False
            vwap = 0.0
            if "volume" in work.columns:
                recent = work.tail(min(len(work), 40))
                vol_sum = float(recent["volume"].sum() or 0.0)
                if vol_sum > 0:
                    vwap = float(((recent["close"] * recent["volume"]).sum()) / vol_sum)
                    if sig == "BUY":
                        vwap_reclaim = close > vwap and (prev_close <= vwap or close >= ema9)
                    else:
                        vwap_reclaim = close < vwap and (prev_close >= vwap or close <= ema9)
            reclaimed = bool(ema_reclaim or structure_reclaim or vwap_reclaim)
            return {
                "close": close,
                "ema9": ema9,
                "ema21": ema21,
                "close_location": max(0.0, min(1.0, float(close_location or 0.0))),
                "ema_reclaim": bool(ema_reclaim),
                "structure_reclaim": bool(structure_reclaim),
                "vwap_reclaim": bool(vwap_reclaim),
                "vwap": vwap,
                "reclaimed": reclaimed,
            }
        except Exception as exc:
            logger.debug(f"Directional reclaim snapshot failed for {instrument} {timeframe}: {exc}")
            return {}

    def _late_session_reclaim_context(
        self,
        instrument: str,
        timeframe: str,
        signal_type: str,
        signal_timestamp,
    ) -> Optional[Dict[str, Any]]:
        """Confirm a late broad-market 1m+5m directional move with tight scalp risk."""
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "late_session_reclaim_override_enabled", True), True):
            return None
        sig_type = str(signal_type or "").upper()
        if sig_type not in {"BUY", "SELL"}:
            return None
        tf = str(timeframe or "")
        if tf not in {"5min", "15min"} or signal_timestamp is None:
            return None
        try:
            ts = (
                signal_timestamp.astimezone(IST).replace(tzinfo=None)
                if getattr(signal_timestamp, "tzinfo", None) is not None
                else signal_timestamp
            )
            start = self._configured_session_time("late_session_reclaim_start", "14:25")
            end = self._configured_session_time("late_session_reclaim_end", "15:10")
            if not self._time_in_window(ts.time(), start, end):
                return None
        except Exception:
            return None

        max_skew = max(0.0, float(getattr(settings, "late_session_reclaim_max_skew_seconds", 240.0) or 240.0))
        min_core_votes = max(1, int(getattr(settings, "late_session_reclaim_core_votes", 3) or 3))
        min_total_votes = max(1, int(getattr(settings, "late_session_reclaim_total_votes", 3) or 3))
        min_reclaim_votes = max(1, int(getattr(settings, "late_session_reclaim_reclaim_votes", 2) or 2))
        min_close = max(0.0, float(getattr(settings, "late_session_reclaim_min_close_location", 0.55) or 0.55))
        min_volume = max(0.0, float(getattr(settings, "late_session_reclaim_min_volume_ratio", 1.10) or 1.10))
        min_volume_votes = max(1, int(getattr(settings, "late_session_reclaim_volume_votes", 3) or 3))

        active = list(getattr(self, "active_indices", []) or [])
        if not active:
            active = ["NIFTY", "BANKNIFTY", "SENSEX", "MIDCPNIFTY"]
        candidate_base = str(instrument or "").split()[0].upper()
        votes: Dict[str, Dict[str, Any]] = {}
        for inst in active:
            one_sig, one_delta = self._cached_signal_near(inst, "1min", sig_type, ts, max_skew)
            five_sig, five_delta = self._cached_signal_near(inst, "5min", sig_type, ts, max_skew)
            if five_sig is None and inst == candidate_base and tf == "5min":
                five_sig = type("_SignalRef", (), {"timestamp": ts, "signal_type": sig_type})()
                five_delta = 0.0
            if one_sig is None or five_sig is None:
                continue

            one_ts = getattr(one_sig, "timestamp", ts)
            five_ts = getattr(five_sig, "timestamp", ts)
            one_metrics = self._candle_thrust_metrics(inst, "1min", sig_type, as_of=one_ts) or {}
            five_metrics = self._candle_thrust_metrics(inst, "5min", sig_type, as_of=five_ts) or {}
            one_reclaim = self._directional_reclaim_snapshot(inst, "1min", sig_type, as_of=one_ts)
            five_reclaim = self._directional_reclaim_snapshot(inst, "5min", sig_type, as_of=five_ts)
            close_location = max(
                float(one_metrics.get("close_location", 0.0) or 0.0),
                float(five_metrics.get("close_location", 0.0) or 0.0),
                float(one_reclaim.get("close_location", 0.0) or 0.0),
                float(five_reclaim.get("close_location", 0.0) or 0.0),
            )
            volume_ratio = max(
                float(one_metrics.get("volume_ratio", 0.0) or 0.0),
                float(five_metrics.get("volume_ratio", 0.0) or 0.0),
            )
            if volume_ratio < min_volume:
                continue
            reclaimed = bool(one_reclaim.get("reclaimed") or five_reclaim.get("reclaimed"))
            if close_location < min_close:
                continue
            votes[inst] = {
                "one_min_skew_seconds": float(one_delta or 0.0),
                "five_min_skew_seconds": float(five_delta or 0.0),
                "close_location": close_location,
                "volume_ratio": volume_ratio,
                "reclaimed": reclaimed,
                "one_min": one_reclaim,
                "five_min": five_reclaim,
                "one_min_metrics": one_metrics,
                "five_min_metrics": five_metrics,
            }

        if candidate_base and candidate_base not in votes:
            return None
        core_universe = sorted(inst for inst in active if inst in self.LATE_RECLAIM_BASKET_INDICES)
        if not core_universe:
            core_universe = sorted(self.LATE_RECLAIM_BASKET_INDICES)
        core_votes = sorted(inst for inst in votes if inst in core_universe)
        total_votes = sorted(votes)
        reclaim_votes = sorted(inst for inst, vote in votes.items() if bool(vote.get("reclaimed")))
        volume_votes = sorted(inst for inst, vote in votes.items() if float(vote.get("volume_ratio", 0.0) or 0.0) >= min_volume)
        if (
            len(core_votes) < min_core_votes
            or len(total_votes) < min_total_votes
            or len(reclaim_votes) < min_reclaim_votes
            or len(volume_votes) < min_volume_votes
        ):
            return None

        move_label = "reclaim" if sig_type == "BUY" else "rollover"
        return {
            "enabled": True,
            "type": "late_session_reclaim",
            "move_label": move_label,
            "timeframe": tf,
            "signal_type": sig_type,
            "core_votes": len(core_votes),
            "total_votes": len(total_votes),
            "reclaim_votes": len(reclaim_votes),
            "volume_votes": len(volume_votes),
            "core_indices": core_votes,
            "core_universe": core_universe,
            "indices": total_votes,
            "reclaim_indices": reclaim_votes,
            "volume_indices": volume_votes,
            "votes": votes,
            "allow_regime_veto": True,
            "force_scalp_lock": True,
            "tight_stop_pct": float(getattr(settings, "late_session_reclaim_options_sl_pct", 5.0) or 5.0),
            "reason": (
                f"late-session synchronized {sig_type} {move_label}: basket core "
                f"{len(core_votes)}/{len(core_universe)}, "
                f"total {len(total_votes)}, structure {len(reclaim_votes)}, "
                f"volume {len(volume_votes)}>={min_volume_votes} at {min_volume:.2f}x "
                f"({getattr(settings, 'late_session_reclaim_start', '14:25')}-"
                f"{getattr(settings, 'late_session_reclaim_end', '15:10')})"
            ),
        }

    def _vwap_break_context(
        self,
        instrument: str,
        timeframe: str,
        signal_type: str,
        as_of=None,
    ) -> Optional[Dict[str, Any]]:
        """Return context when price has reclaimed/lost VWAP in signal direction."""
        try:
            df = self.candles.get_candles(instrument, timeframe)
            if df is None or len(df) < 5 or "volume" not in getattr(df, "columns", []):
                return None
            if as_of is not None:
                try:
                    ts = (
                        as_of.astimezone(IST).replace(tzinfo=None)
                        if getattr(as_of, "tzinfo", None) is not None
                        else as_of
                    )
                    df = df[df.index <= ts]
                except Exception:
                    pass
            if len(df) < 5:
                return None
            recent = df.tail(min(len(df), 40)).copy()
            vol_sum = float(recent["volume"].sum() or 0.0)
            if vol_sum <= 0:
                return None
            vwap = float(((recent["close"] * recent["volume"]).sum()) / vol_sum)
            last = recent.iloc[-1]
            close = float(last["close"])
            open_price = float(last["open"])
            if vwap <= 0:
                return None
            dev_pct = abs((close - vwap) / vwap) * 100.0
            min_dev = float(getattr(get_settings(), "reversal_entry_vwap_min_dev_pct", 0.03) or 0.03)
            sig = str(signal_type or "").upper()
            if sig == "SELL" and close < vwap and open_price >= vwap and dev_pct >= min_dev:
                return {
                    "type": "vwap_loss",
                    "reason": f"VWAP loss confirmed ({dev_pct:.2f}% below session VWAP)",
                    "vwap": vwap,
                    "dev_pct": dev_pct,
                }
            if sig == "BUY" and close > vwap and open_price <= vwap and dev_pct >= min_dev:
                return {
                    "type": "vwap_reclaim",
                    "reason": f"VWAP reclaim confirmed ({dev_pct:.2f}% above session VWAP)",
                    "vwap": vwap,
                    "dev_pct": dev_pct,
                }
        except Exception as exc:
            logger.debug(f"VWAP reversal context failed for {instrument} {timeframe}: {exc}")
        return None

    def _structure_break_context(
        self,
        instrument: str,
        timeframe: str,
        signal_type: str,
        as_of=None,
    ) -> Optional[Dict[str, Any]]:
        """Detect a simple lower-high breakdown / higher-low breakout without look-ahead."""
        try:
            df = self.candles.get_candles(instrument, timeframe)
            if df is None or len(df) < 8:
                return None
            if as_of is not None:
                try:
                    ts = (
                        as_of.astimezone(IST).replace(tzinfo=None)
                        if getattr(as_of, "tzinfo", None) is not None
                        else as_of
                    )
                    df = df[df.index <= ts]
                except Exception:
                    pass
            if len(df) < 8:
                return None
            recent = df.tail(8)
            last = recent.iloc[-1]
            prev = recent.iloc[:-1]
            sig = str(signal_type or "").upper()
            if sig == "SELL":
                prior_low = float(prev["low"].tail(5).min())
                lower_high = float(last["high"]) < float(prev["high"].tail(3).max())
                if float(last["close"]) < prior_low and lower_high:
                    return {
                        "type": "lower_high_breakdown",
                        "reason": "lower-high breakdown through recent swing low",
                        "swing_level": prior_low,
                    }
            elif sig == "BUY":
                prior_high = float(prev["high"].tail(5).max())
                higher_low = float(last["low"]) > float(prev["low"].tail(3).min())
                if float(last["close"]) > prior_high and higher_low:
                    return {
                        "type": "higher_low_breakout",
                        "reason": "higher-low breakout through recent swing high",
                        "swing_level": prior_high,
                    }
        except Exception as exc:
            logger.debug(f"Structure reversal context failed for {instrument} {timeframe}: {exc}")
        return None

    def _entry_reversal_relief_context(
        self,
        instrument: str,
        timeframe: str,
        signal_type: str,
        signal_timestamp=None,
        *,
        regime: str = "",
        confidence: float = 0.0,
    ) -> Optional[Dict[str, Any]]:
        """Shared entry-side relief when a counter-bias signal is a real reversal."""
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "reversal_entry_relief_enabled", True), True):
            return None
        try:
            if float(confidence or 0.0) < float(getattr(settings, "reversal_entry_min_confidence", 0.20) or 0.20):
                return None
        except Exception:
            return None
        sig = str(signal_type or "").upper()
        if sig not in {"BUY", "SELL"}:
            sig = "BUY" if sig in {"LONG", "CE"} else "SELL" if sig in {"SHORT", "PE"} else sig
        if sig not in {"BUY", "SELL"}:
            return None

        late_reclaim_ctx = self._late_session_reclaim_context(instrument, timeframe, sig, signal_timestamp)
        if late_reclaim_ctx:
            return late_reclaim_ctx

        cascade_ctx = self._one_way_cascade_context(instrument, timeframe, sig, signal_timestamp)
        if cascade_ctx:
            return cascade_ctx

        market_ctx = self._market_wide_reversal_context(instrument, timeframe, sig, signal_timestamp)
        if market_ctx:
            ctx = dict(market_ctx)
            ctx["type"] = "cross_index_rollover" if sig == "SELL" else "cross_index_reversal"
            return ctx

        # The weakest branch in this chain, and the one that fires most: 653 of 1327
        # re-admissions across every session log (49%), against 3 from the strict
        # directional-thrust branch below. It asks only "is the regime trending, and does
        # it point the same way as the signal" — no price, volume or structure test at
        # all — so it re-admits a flickering arrow on a condition that is true for most of
        # any trending session. Override-admitted signals ran a 39% win rate against 50%
        # for clean ones with a median of -151, though at N=56 that gap is not
        # statistically significant (p=0.21), which is why dropping this branch is opt-in
        # rather than the default.
        if not self._setting_enabled(
            getattr(settings, "stabilization_override_drop_regime_flip", False), False
        ):
            reg = str(regime or getattr(self, "latest_regimes", {}).get(instrument, "") or "").upper()
            if reg and is_trending_regime(reg) and regime_aligns(reg, sig):
                return {
                    "type": "regime_flip",
                    "reason": f"regime flip aligns with {sig} ({reg})",
                    "regime": reg,
                }

        thrust = self._candle_thrust_metrics(instrument, timeframe, sig, as_of=signal_timestamp)
        if thrust:
            min_range = float(getattr(settings, "reversal_entry_thrust_min_range_atr_ratio", 1.20) or 1.20)
            min_close = float(getattr(settings, "reversal_entry_thrust_min_close_location", 0.62) or 0.62)
            min_vol = float(getattr(settings, "reversal_entry_thrust_min_volume_ratio", 1.20) or 1.20)
            if (
                float(thrust.get("range_atr_ratio", 0.0) or 0.0) >= min_range
                and float(thrust.get("close_location", 0.0) or 0.0) >= min_close
                and float(thrust.get("volume_ratio", 0.0) or 0.0) >= min_vol
            ):
                return {
                    "type": "directional_thrust",
                    "reason": (
                        f"{sig} thrust confirmed: range {thrust['range_atr_ratio']:.2f}x ATR, "
                        f"volume {thrust['volume_ratio']:.2f}x"
                    ),
                    "metrics": thrust,
                }

        vwap_ctx = self._vwap_break_context(instrument, timeframe, sig, as_of=signal_timestamp)
        if vwap_ctx:
            return vwap_ctx
        return self._structure_break_context(instrument, timeframe, sig, as_of=signal_timestamp)

    def _latched_cascade_override(
        self, candidate, ctx: Optional[Dict[str, Any]]
    ) -> Optional[Dict[str, Any]]:
        """Hold a confirmed cascade for the rest of this signal's stabilization window.

        A one-way cascade is evidence about a move that ALREADY happened — a synchronised
        multi-index thrust with breadth and volume behind it. Re-proving it on every scan
        asks a different question: "is the thrust still printing this instant?", and the
        answer goes false the moment volume ticks under its ratio, even though nothing
        about the original evidence changed.

        2026-08-11 09:15, MIDCPNIFTY 15min SHORT — the correct side on the only hour of
        the day that moved:

            Re-admitting: arrow flickered but one-way downside cascade:
                          core 3/3, total 4, volume 4>=3 at 1.40x
            Re-admitting: (same)
            Rejected:     UT1 arrow vanished after 13.7s

        Re-admitted twice on maximal confirmation, then killed anyway. Across that
        session 252 signals entered the buffer and 48 matured — 19%.

        The latch does NOT weaken the FLIP check: _stabilization_repaint_override_context
        returns None on a FLIPPED arrow before this is ever reached, so a signal the
        source has CONTRADICTED still dies. This only covers an arrow that went QUIET,
        which is exactly the distinction that function's own docstring draws.
        """
        settings = get_settings()
        if not self._setting_enabled(
            getattr(settings, "stabilization_cascade_latch_enabled", True), True
        ):
            return ctx
        if ctx:
            try:
                latched = dict(ctx)
                latched["latched"] = True
                latched["reason"] = (
                    f"{ctx.get('reason', ctx.get('type', 'confirmed cascade'))} (held)"
                )
                setattr(candidate, "_stabilization_cascade_latch", latched)
            except Exception:
                pass
            return ctx
        prior = getattr(candidate, "_stabilization_cascade_latch", None)
        if isinstance(prior, dict) and prior:
            self._diag_inc("stabilization", "cascade_latch_held")
            return prior
        return None

    def _stabilization_repaint_override_context(
        self,
        candidate: TradeCandidate,
        sig_timestamp=None,
    ) -> Optional[Dict[str, Any]]:
        """Re-admit a flickered intrabar signal if market context still confirms thrust."""
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "stabilization_momentum_override_enabled", True), True):
            return None
        signal_type = self._repaint_signal_type(candidate)
        signal_ts = sig_timestamp or getattr(candidate, "signal_timestamp", None)
        if self._repaint_signal_status(candidate, signal_ts) == "FLIPPED":
            # The bar now prints the OPPOSITE arrow. This override exists to rescue a
            # signal whose evidence went QUIET, not one the source has contradicted:
            # every branch below asks "does context still support this side", and the
            # weakest of them (regime_flip, 49% of all re-admissions) asks only whether
            # a slow-moving regime label happens to agree. A regime label lags the bar
            # that just flipped, so without this check the override re-admits a BUY at
            # the exact moment UT1 switched to SELL — and at the post-entry site it
            # HOLDS a live position open against the printed reversal.
            return None
        late_reclaim_ctx = self._late_session_reclaim_context(
            getattr(candidate, "instrument", ""),
            getattr(candidate, "timeframe", ""),
            signal_type,
            signal_ts,
        )
        cascade_ctx = self._one_way_cascade_context(
            getattr(candidate, "instrument", ""),
            getattr(candidate, "timeframe", ""),
            signal_type,
            signal_ts,
        )
        try:
            ts = (
                signal_ts.astimezone(IST).replace(tzinfo=None)
                if getattr(signal_ts, "tzinfo", None) is not None
                else signal_ts
            )
            in_late_reclaim_window = bool(
                ts is not None
                and self._time_in_window(
                    ts.time(),
                    self._configured_session_time("late_session_reclaim_start", "14:25"),
                    self._configured_session_time("late_session_reclaim_end", "15:10"),
                )
            )
        except Exception:
            in_late_reclaim_window = False
        if signal_type == "SELL" or in_late_reclaim_window:
            # Generic relief must not re-admit flickering shorts. Late-session
            # flickers are stricter on both sides: require the 1m+5m, breadth,
            # reclaim and volume basket instead of trusting a stale regime flip.
            return self._latched_cascade_override(candidate, late_reclaim_ctx or cascade_ctx)
        return self._entry_reversal_relief_context(
            getattr(candidate, "instrument", ""),
            getattr(candidate, "timeframe", ""),
            signal_type,
            signal_ts,
            regime=str(getattr(self, "latest_regimes", {}).get(getattr(candidate, "instrument", ""), "") or ""),
            confidence=float(getattr(candidate, "confidence", 0.0) or 0.0),
        )

    def _post_entry_repaint_override_context(
        self,
        candidate: TradeCandidate,
        sig_timestamp=None,
    ) -> Optional[Dict[str, Any]]:
        """Keep post-entry repaint checks aligned with stabilization overrides."""
        if not bool(getattr(candidate, "stabilization_momentum_override", False)):
            return None
        return self._stabilization_repaint_override_context(candidate, sig_timestamp)

    @staticmethod
    def _repaint_abort_exit_reason(candidate: TradeCandidate) -> Tuple[str, str]:
        if bool(getattr(candidate, "stabilization_momentum_override", False)):
            return (
                "MOMENTUM_OVERRIDE_FAILED",
                "Momentum override failed after entry",
            )
        return "REPAINT_ABORT", "Signal repainted"

    def _late_session_entry_block_reason(self, candidate: TradeCandidate) -> str:
        """Avoid fresh choppy option entries when there is not enough runway."""
        if getattr(self, "mode", "") == "HISTORICAL":
            return ""
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "late_session_choppy_entry_guard_enabled", True), True):
            return ""
        if str(getattr(candidate, "inst_type", "") or "").upper() != "OPT":
            return ""
        signal_time = getattr(candidate, "signal_timestamp", None) or datetime.now(IST).replace(tzinfo=None)
        mins = self._minutes_to_force_exit(signal_time)
        window = float(getattr(settings, "late_session_choppy_min_runway_minutes", 30.0) or 30.0)
        if mins < 0.0 or mins > window:
            return ""
        if getattr(candidate, "one_way_cascade_entry", False):
            self._set_scalp_lock(candidate, False)
            return ""
        if (
            getattr(candidate, "power_move", False)
            or getattr(candidate, "volume_spike_entry", False)
            or getattr(candidate, "market_wide_reversal_entry", False)
            or getattr(candidate, "late_session_reclaim_entry", False)
            or getattr(candidate, "quad_union_entry", False)
            or getattr(candidate, "raw_union_entry", False)
        ):
            self._set_scalp_lock(candidate, True)
            return ""
        regime = str(getattr(self, "latest_regimes", {}).get(getattr(candidate, "instrument", ""), "UNKNOWN") or "UNKNOWN")
        if not is_risky_regime(regime):
            return ""
        signal_type = "BUY" if str(getattr(candidate, "direction", "") or "").upper() == "LONG" else "SELL"
        relief = self._entry_reversal_relief_context(
            getattr(candidate, "instrument", ""),
            getattr(candidate, "timeframe", ""),
            signal_type,
            signal_time,
            regime=regime,
            confidence=float(getattr(candidate, "confidence", 0.0) or 0.0),
        )
        if relief:
            setattr(candidate, "late_session_momentum_scalp", True)
            self._set_scalp_lock(candidate, True)
            try:
                candidate.reasons = list(candidate.reasons or []) + [
                    f"Late-session reversal scalp allowed: {relief.get('reason', relief.get('type', 'confirmed'))}"
                ]
            except Exception:
                pass
            return ""
        return (
            f"late-session choppy option blocked: {mins:.0f}m runway before square-off "
            "without confirmed momentum scalp"
        )

    def _candidate_quote_ready_for_lifecycle(self, candidate: TradeCandidate) -> bool:
        """Quote-unverified option candidates must not become accepted lifecycle rows."""
        if getattr(self, "mode", "") == "HISTORICAL":
            return True
        if str(getattr(candidate, "inst_type", "") or "").upper() != "OPT":
            return True
        status = str(getattr(candidate, "status", "") or "").upper()
        source = str(getattr(candidate, "quote_source", "") or "").lower()
        if status == "QUOTE UNAVAILABLE" or source == "contract_ltp_unavailable":
            return False
        if getattr(candidate, "quote_verified", True) is False:
            return False
        return True

    def _detect_volume_spike_entry(
        self,
        instrument: str,
        timeframe: str,
        signal_type: str,
        adx_value: float = 0.0,
        intel_score: float = 0.0,
        power_move: bool = False,
        as_of=None,
        depth_context: Optional[Dict[str, Any]] = None,
    ) -> Optional[Dict[str, float]]:
        """Confirm a fast 1min/5min directional volume-spike entry — live AND historical.

        Computes the thrust metrics for the signal candle and defers the all-three-factor
        decision (volume surge + range expansion + close near the directional edge) to the
        shared policy, so live and backtest agree. For 1min, when L1 depth is usable,
        OFR must align with signal direction. Returns the metrics dict when the candle
        qualifies (the caller uses it for sizing/stops/annotation), or ``None`` otherwise.
        """
        try:
            settings = get_settings()
            if not self._setting_enabled(getattr(settings, "volume_spike_entry_enabled", True), True):
                return None
            if str(timeframe or "").lower() == "1min" and not self._setting_enabled(
                getattr(settings, "one_min_scalping_enabled", True),
                True,
            ):
                return None
            if str(timeframe or "").lower() not in {"1min", "5min"}:
                return None
            metrics = self._candle_thrust_metrics(instrument, timeframe, signal_type, as_of=as_of)
            if not metrics:
                return None
            depth = depth_context if isinstance(depth_context, dict) else {}
            if not depth and str(timeframe or "").lower() == "1min":
                try:
                    cfg = (getattr(self, "config", {}) or {}).get("indices", {}).get(
                        str(instrument or "").split()[0].upper(), {}
                    )
                    depth = self._get_depth_context(str(instrument or "").split()[0].upper(), cfg or {})
                except Exception:
                    depth = {}
            ofr = 0.0
            depth_usable = bool(depth.get("usable"))
            try:
                ofr = float(depth.get("ofr") or 0.0)
            except Exception:
                ofr = 0.0
            confirmed = SignalProcessor._volume_spike_entry_confirmed(
                timeframe=timeframe,
                volume_ratio=metrics["volume_ratio"],
                range_atr_ratio=metrics["range_atr_ratio"],
                close_location=metrics["close_location"],
                adx_value=float(adx_value or 0.0),
                intel_score=float(intel_score or 0.0),
                power_move=bool(power_move),
                settings=settings,
                signal_type=str(signal_type or ""),
                depth_usable=depth_usable,
                ofr=ofr,
                volume_basis=str(metrics.get("volume_basis", "TRADED")),
                surge_percentile=float(metrics.get("surge_percentile", -1.0)),
            )
            if not confirmed:
                return None
            metrics = dict(metrics)
            metrics["depth_usable"] = depth_usable
            metrics["ofr"] = ofr
            metrics["depth_aligned"] = True
            depth_note = (
                f", OFR {ofr:.2f} aligned"
                if depth_usable
                else ", depth n/a"
            )
            self.log_event(
                f"⚡ VOLUME-SPIKE entry confirmed: {instrument} {timeframe} {signal_type} "
                f"(vol {metrics['volume_ratio']:.1f}x, range {metrics['range_atr_ratio']:.1f}x ATR, "
                f"close {metrics['close_location']:.0%} of range{depth_note}).",
                "trade",
            )
            return metrics
        except Exception as exc:
            logger.debug(f"Volume-spike entry detection failed for {instrument} {timeframe}: {exc}")
            return None

    def _power_move_late_cutoff_ok(self, signal_time) -> bool:
        """Whether a power-move may still enter past the 15:00 cutoff (before the hard cutoff)."""
        try:
            label = str(getattr(get_settings(), "power_move_late_hard_cutoff", "15:15") or "15:15")
            parts = label.split(":")
            hard = dtime(int(parts[0]), int(parts[1]))
            t = signal_time.time() if hasattr(signal_time, "time") else signal_time
            return t <= hard
        except Exception:
            return False

    def _profit_lock_min_peak(
        self,
        scalp_mode: bool = False,
        initial_risk_rs: float = 0.0,
        timeframe: str = "",
        now=None,
        trade_like=None,
    ) -> float:
        """Minimum peak P&L before SMART_PROFIT_LOCK can arm."""
        settings = get_settings()
        base_peak = float(getattr(settings, "profit_lock_min_peak_rs", 500.0) or 500.0)
        min_peak = base_peak
        risk = abs(float(initial_risk_rs or 0.0))
        normal_r_mult = float(getattr(settings, "profit_lock_min_r_multiple", 0.20) or 0.20)
        if scalp_mode:
            r_mult = float(getattr(settings, "scalp_profit_lock_min_r_multiple", 0.50) or 0.50)
            min_peak = base_peak
            regime_text = str(getattr(trade_like, "market_regime", "") or "").upper()
            choppy_scalp = bool(getattr(trade_like, "fifteen_min_choppy_scalp_entry", False)) or (
                bool(trade_like is not None)
                and (
                    is_risky_regime(regime_text)
                    or regime_text in {"RANGING", "CHOPPY", "VOLATILE", "MEAN_REVERTING"}
                )
            )
            if choppy_scalp:
                min_peak = float(getattr(settings, "fifteen_min_choppy_scalp_min_peak_rs", 250.0) or 250.0)
            if (
                str(timeframe or "").lower() == "15min"
                and bool(getattr(trade_like, "fifteen_min_choppy_scalp_entry", False))
            ):
                r_mult = float(getattr(settings, "fifteen_min_choppy_scalp_profit_lock_r_multiple", 0.20) or 0.20)
            if risk > 0 and r_mult > 0:
                min_peak = max(min_peak, min(risk * r_mult, Scanner._profit_lock_arm_cap_rs(self, trade_like)))
        else:
            # The non-scalp base is its own setting. Measured over 12 sessions the shared
            # Rs.500 base beat risk*r_mult on only 5 of 59 non-scalp rows, so the
            # R-multiple below is what actually sets this arm and the base is the
            # backstop under it. See config/settings.py profit_lock_min_r_multiple.
            #
            # Applied OUTSIDE the let_winners_run test on purpose: that flag adds the
            # R-multiple DELAY, so gating the base on it too would make switching
            # let-winners-run OFF arm later than leaving it on.
            min_peak = float(
                getattr(settings, "profit_lock_nonscalp_min_peak_rs", 250.0) or 250.0
            )
            if self._setting_enabled(getattr(settings, "let_winners_run", True), True):
                r_mult = normal_r_mult
                if risk > 0 and r_mult > 0:
                    # Delay only the small-tier lock; never past the major-win threshold
                    # (>= Rs.3000), so a big win is always protected by MAJOR_WIN_GUARD.
                    min_peak = max(min_peak, min(risk * r_mult, Scanner._profit_lock_arm_cap_rs(self, trade_like)))
        # EOD-proximity (Fix 2): within the square-off window a trade cannot run to
        # 1R, so collapse the arm to a small peak so protection engages in time
        # instead of letting a winner round-trip until the forced EOD kill.
        if now is not None and self._eod_protect_active(now):
            eod_r_raw = getattr(settings, "eod_protect_arm_r_multiple", 0.0)
            eod_min_raw = getattr(settings, "eod_protect_min_peak_rs", 1.0)
            eod_r = float(eod_r_raw if eod_r_raw is not None else 0.0)
            eod_min = float(eod_min_raw if eod_min_raw is not None else 1.0)
            eod_arm = max(eod_min, risk * eod_r) if risk > 0 else eod_min
            min_peak = min(min_peak, eod_arm)
        # Same floor as the give-back arm: the EOD collapse above can drive this to
        # Rs.1, and a lock armed below the round-trip cost banks less than it pays.
        return max(min_peak, Scanner._profit_protect_cost_floor_rs(self, trade_like))

    def _smart_lock_floor_collapse(
        self, peak_pnl: float, current_pnl_rs: float, retention_ratio: float = 0.0
    ) -> bool:
        """Whether the absolute keep-floor may cut this trade.

        The keep-floor is COLLAPSE protection, not a profit cap: it may only fire
        on a trade that actually earned MORE than the floor and then gave it back.

        2026-08-12: the non-scalp lock arms at Rs.250 (profit_lock_nonscalp_min_peak_rs)
        while the keep-floor is Rs.450, so `current < floor` was true by construction
        the instant the lock armed — the arm sits BELOW the floor. Four winners were
        market-exited at their own peak (current == peak, no give-back at all) 18-194s
        after entry for Rs.170-212 net; the same signals in restore_point_51 ran to
        Rs.1,749 and Rs.3,124. Every large win must cross the Rs.250-450 band on its
        way up, so nothing may cut a trade inside that band. Give-backs below the
        floor stay owned by _peak_giveback_or_reversal_exit, which has the arm
        ladder, the round-trip cost floor and the trend-runner exemption.
        """
        floor = float(getattr(get_settings(), "profit_lock_abs_floor_rs", 450.0) or 450.0)
        peak = float(peak_pnl or 0.0)
        current = float(current_pnl_rs or 0.0)
        if not (peak > floor and current < floor):
            return False
        # Crossing an absolute rupee line is not a collapse. 2026-08-13, after the
        # peak>floor gate above was in place, three winners were still cut because
        # each had peaked just ABOVE Rs.450, so an ordinary pullback carried it back
        # across: SENSEX peak Rs.458 -> Rs.399 is a 13% giveback, cut three seconds
        # after entry; NIFTY Rs.572 -> Rs.413 is 28%. Any trade whose peak lands near
        # the floor sits in a band where noise reads as collapse.
        #
        # The retention ladder already knows what a real giveback is for THIS trade
        # and this regime, so the floor may only fire on one the ladder itself calls
        # a breach. A ratio of 0 means the ladder had no reading, and absent is not a
        # reason to invent one — the peak>floor gate stands alone there.
        ratio = float(retention_ratio or 0.0)
        if ratio > 0.0 and current >= peak * ratio:
            return False
        return True

    def _smart_lock_backstop_ratio(self, lock_ratio: float, scalp_mode: bool) -> float:
        """Peak retention at which the P&L-space backstop may fire.

        The backstop exists for the case where the price-space lock stop was delayed
        or clamped (option breathing room) and so never registered as a stop hit. It
        must never fire BEFORE the ladder it backs up: _profit_lock_floor already
        returns the retention it chose, tiered by peak and loosened to 0.38 in
        VOLATILE/BREAKOUT where the median winner gives back 49% and survives
        (_first_rung_regime_retention).

        2026-08-12: the session path gated on a flat 0.65 while the ladder floor is
        0.50 (0.38 fast regimes), and the live path used a hard-coded 0.45 — the same
        faded winner was cut in signal mode and held in auto. Worse, signal mode
        booked the exit at the ladder's floor price, BELOW the mark the trade was
        actually trading at. The ladder's own ratio now drives both paths, so the
        backstop fires exactly when the trade is below its trail and not one tick
        earlier. The constants remain only for the no-floor case, where lock_stop is
        0 too and nothing but a floor collapse can exit.
        """
        ratio = float(lock_ratio or 0.0)
        if ratio > 0:
            return ratio
        return 0.70 if scalp_mode else 0.65

    def _first_rung_regime_retention(self, trade_like=None, timeframe: str = "") -> float:
        """Retention for the sub-Rs.1,000 rung, by the regime the trade lives in.

        lock_ratio is the fraction of peak RETAINED, so the floor sits at ratio x peak
        and BREATHING is 1 - ratio. Loosening therefore means a LOWER number, not a
        higher one. Returned into a min(), so this can only ever loosen the 0.50
        schedule; regimes not listed return 1.0 and leave it untouched.

        Measured heat as a fraction of peak, across every winner in 47 stored sessions:

            TRENDING_UP    8%     RANGING        35%
            TRENDING_DOWN 28%     BREAKOUT_DOWN  43%
                                  BREAKOUT_UP    47%
                                  VOLATILE       49%

        At a 0.50 floor a trade is stopped once it gives back half its peak. In VOLATILE
        the MEDIAN winner gives back 49% — so the floor sits directly on top of the
        pullback those winners routinely make and survive, and roughly half of them are
        cut at movement that was never a reversal. 0.38 (62% breathing) clears the
        measured median with room to spare while still banking a third of the peak.

        TRENDING_UP is deliberately excluded: 8% heat against a median peak of Rs.3,070
        means the existing leash is nowhere near binding, and loosening it there would
        give back real money for nothing.
        """
        settings = get_settings()
        if not Scanner._setting_enabled(
            getattr(settings, "first_rung_regime_retention_enabled", True), True
        ):
            return 1.0
        if trade_like is None:
            return 1.0
        try:
            regime = str(Scanner._get_trade_regime(self, trade_like, default="")).upper()
        except Exception:
            return 1.0
        if regime not in {"VOLATILE", "BREAKOUT_UP", "BREAKOUT_DOWN"}:
            return 1.0
        try:
            loose = float(getattr(settings, "first_rung_fast_regime_retention", 0.38) or 0.38)
        except (TypeError, ValueError):
            loose = 0.38
        # Bounded: under 0.30 the lock stops protecting anything, and at/over 0.50 the
        # min() in the caller makes it a no-op — so the band is where it can still act.
        return max(0.30, min(0.50, loose))

    def _profit_lock_arm_cap_rs(self, trade_like=None) -> float:
        """Ceiling on how late the profit lock may arm, in rupees.

        Hardcoded Rs.3000, matching the ladder's major-win rung so a big win is always
        protected. It is an absolute figure applied to a position of any size, so a
        10-lot trade arms its lock at the same Rs.3000 peak as a 1-lot trade -- a tenth
        of the move, in R terms, before protection starts tightening.

        It scales per lot under the SAME switch that already makes the ladder read per
        lot. One flag, one coherent basis: turning per-lot on and leaving this absolute
        would put the arming threshold and the tier it feeds on different scales.
        """
        base = 3000.0
        settings = get_settings()
        if not Scanner._setting_enabled(
            getattr(settings, "profit_lock_per_lot_basis", False), False
        ):
            return base
        counter = getattr(self, "_profit_lock_lot_count", None)
        lots = counter(trade_like, 0) if callable(counter) else Scanner._profit_lock_lot_count(trade_like, 0)
        return base * float(max(1, lots))

    def _profit_lock_ratio_floor(self) -> float:
        """Least of a peak the ladder may lock — the LOOSEST breathing space allowed.

        Bounded to [0.40, the ceiling] so a misconfigured floor can never sit above the
        ceiling and inverts the band.
        """
        try:
            value = float(getattr(get_settings(), "profit_lock_min_ratio", 0.75) or 0.75)
        except (TypeError, ValueError):
            value = 0.75
        return max(0.40, min(Scanner._profit_lock_ratio_ceiling(self), value))

    def _profit_lock_ratio_ceiling(self) -> float:
        """Most of a peak the ladder may lock, as a fraction.

        Bounded to [0.50, 0.99]. 1.0 is deliberately unreachable: it places the floor on
        the peak price itself, which the next tick breaches by definition, so the lock
        stops trailing anything and becomes a fixed take-profit.
        """
        try:
            value = float(
                getattr(get_settings(), "profit_lock_max_ratio", 0.80) or 0.80
            )
        except (TypeError, ValueError):
            value = 0.95
        return max(0.50, min(0.99, value))

    def _profit_lock_floor(
        self,
        entry_price: float,
        direction: str,
        qty: int,
        peak_pnl: float,
        scalp_mode: bool = False,
        inst_mult: float = 1.0,
        initial_risk_rs: float = 0.0,
        timeframe: str = "",
        now=None,
        trade_like=None,
    ) -> Tuple[float, str, float]:
        """Convert peak P&L retention into a protective price floor/ceiling.

        Tiered lock — bigger peaks are protected more aggressively (let small wins
        breathe, lock big wins hard), with retention rising smoothly across tiers:
            peak  Rs.500-1000 : 50% -> 65%
            peak Rs.1000-2000 : 65% -> 75%
            peak Rs.2000-3000 : 75% -> 85%
            peak >=    Rs.3000 : 85%   (runner trailing then captures further upside)

        Let-winners-run: a non-scalp trade does NOT arm the lock until its peak reaches
        profit_lock_min_r_multiple x initial risk (Rs), so it has room to develop
        instead of being scalped on the first pullback. True scalps are also R-aware
        through scalp_profit_lock_min_r_multiple, so a Rs.500 blip cannot cap a trade
        that still has several thousand rupees of configured stop risk.
        """
        settings = get_settings()
        min_peak_func = getattr(self, "_profit_lock_min_peak", None)
        if callable(min_peak_func):
            min_peak = min_peak_func(scalp_mode, initial_risk_rs, timeframe, now, trade_like=trade_like)
        else:
            min_peak = Scanner._profit_lock_min_peak(self, scalp_mode, initial_risk_rs, timeframe, now, trade_like=trade_like)
        if entry_price <= 0 or qty <= 0 or peak_pnl < min_peak or inst_mult <= 0:
            return 0.0, "", 0.0

        # The ladder below is written in absolute rupees, and its thresholds were tuned
        # on single-lot trades. On a 3-lot position a Rs.3000 peak is Rs.1000 PER LOT --
        # a modest win treated as a major one, locking 90% and scalping a trade that has
        # barely developed. Reading the ladder per lot keeps the tuning intact as size
        # scales.
        #
        # Default OFF, deliberately: per-lot is more principled but LOOSER, since a
        # multi-lot winner lands on a lower tier and is allowed to give back more before
        # the lock fires. That is a real risk increase on live money, so it is the
        # operator's call rather than a silent change of exit behaviour.
        ladder_pnl = peak_pnl
        if self._setting_enabled(
            getattr(settings, "profit_lock_per_lot_basis", False), False
        ):
            # Resolved defensively, exactly as _profit_lock_arm_cap_rs does. Partial
            # scanners are a real pattern here, and while the switch was OFF by default
            # this line never ran for them; turning it on made an unbound lookup reachable
            # on every profit-lock evaluation.
            counter = getattr(self, "_profit_lock_lot_count", None)
            lots = (
                counter(trade_like, qty)
                if callable(counter)
                else Scanner._profit_lock_lot_count(trade_like, qty)
            )
            if lots > 1:
                ladder_pnl = peak_pnl / float(lots)
        # ladder_pnl selects the TIER. peak_pnl stays the real figure, because the price
        # floor below is derived from it -- dividing that by the lot count would understate
        # every floor rather than just moving the trade to a different tier.
        # Unbound: partial scanners are a real pattern here and this now runs on EVERY
        # tier, not just the major-win branch, so a stub that never reached the old
        # call site reaches this one.
        ceiling_band = Scanner._profit_lock_ratio_ceiling(self)
        if ladder_pnl >= 3000.0:
            # Major wins tighten from 85% at Rs.3000 toward the ceiling at Rs.5000+.
            # (Read 90% until 2026-08-11 — stale since the tier base was re-tuned to
            # 0.85; the trailing line of this block already stated the real figure.)
            #
            # That ceiling used to be 1.0, and a ratio of exactly 1.0 puts the floor ON
            # the peak price. Price has to come off the peak for any later tick to exist,
            # so the floor is breached by the first one: the ladder stopped being a
            # trailing lock and became a hard take-profit at Rs.5000. It also contradicts
            # this function's own docstring, which promises the runner keeps trailing
            # above Rs.3000. Trend options already dodged it via
            # option_major_win_trend_lock_ratio_cap (0.95); everything else did not.
            #
            # It gets worse with size, which is where this is heading. At 10 NIFTY lots
            # (750 qty) Rs.5000 of peak is under Rs.7 of premium movement -- every decent
            # winner would be closed almost as soon as it started working.
            # 15% breathing at Rs.3,000 tightening to 10% by Rs.5,000+.
            lock_ratio = min(ceiling_band, 0.85 + 0.05 * (ladder_pnl - 3000.0) / 2000.0)
        elif ladder_pnl >= 2000.0:
            # 25% -> 20%
            lock_ratio = 0.75 + 0.05 * (ladder_pnl - 2000.0) / 1000.0
        elif ladder_pnl > 1000.0:
            # 35% -> 30%. Strictly ABOVE Rs.1,000: the operator's schedule reads "up to
            # Rs.1,000 gets 50%", so the boundary itself belongs to the loose tier below.
            lock_ratio = 0.65 + 0.05 * (ladder_pnl - 1000.0) / 1000.0
        else:
            # Below Rs.1,000 a winner is barely out of the noise. On an index option a
            # Rs.600 peak is a handful of premium points, and a 20-25% leash there was
            # closing trades on ordinary bid/ask breathing before the move developed.
            # 50% is the operator's schedule (2026-08-08) and supersedes the flat band.
            lock_ratio = 0.50
            # ...except that 50% is measured to sit ON TOP of normal breathing in the
            # fast regimes. Heat as a fraction of peak, taken from every winner in 47
            # stored sessions:
            #     TRENDING_UP 8%   TRENDING_DOWN 28%   RANGING 35%
            #     BREAKOUT_DOWN 43%   BREAKOUT_UP 47%   VOLATILE 49%
            # A 50% floor in VOLATILE or BREAKOUT therefore fires at roughly the median
            # pullback those winners always make — it cuts them at movement that was
            # never a reversal. TRENDING_UP is left alone: 8% heat against a median peak
            # of Rs.3,070 means the existing leash is nowhere near binding there.
            lock_ratio = min(lock_ratio, Scanner._first_rung_regime_retention(self, trade_like, timeframe))
        reason = "MAJOR_WIN_GUARD" if ladder_pnl >= 3000.0 else "SMART_PROFIT_LOCK"
        if reason == "MAJOR_WIN_GUARD" and trade_like is not None:
            inst_type = str(getattr(trade_like, "inst_type", "") or "").upper()
            grade = str(getattr(trade_like, "grade", "") or "").upper()
            grade_score = {"B+": 3, "A": 4, "A+": 5}.get(grade, 0)
            trend_option = (
                inst_type == "OPT"
                and str(timeframe or getattr(trade_like, "timeframe", "") or "").lower() in {"5min", "15min"}
                and (bool(getattr(trade_like, "runner_mode", False)) or grade_score >= 3)
            )
            if trend_option:
                cap = max(
                    0.75,
                    min(
                        1.0,
                        float(getattr(settings, "option_major_win_trend_lock_ratio_cap", 0.95) or 0.95),
                    ),
                )
                lock_ratio = min(lock_ratio, cap)
        # Clamp into the operator's breathing band. The tiers above still order the
        # trades — more gain, tighter lock — but the ladder may no longer leave a big
        # winner on a 5% leash nor hand a small one back nearly half its gain.
        # profit_lock_min_ratio is a guard against a misconfigured floor, not a claim
        # that 50% breathing is enough everywhere — and left as a hard clamp it silently
        # undid the regime rung above, which is measured to need 62% in the fast regimes.
        # It yields to that rule and to nothing else: _first_rung_regime_retention
        # returns 1.0 for every other regime, so this min() is a no-op there.
        ratio_floor = min(
            Scanner._profit_lock_ratio_floor(self),
            Scanner._first_rung_regime_retention(self, trade_like, timeframe),
        )
        lock_ratio = max(ratio_floor, min(ceiling_band, lock_ratio))
        lock_ratio = round(lock_ratio, 4)
        locked_points = (peak_pnl * lock_ratio) / (qty * inst_mult)
        if str(direction).upper() == "SHORT":
            return float(entry_price) - locked_points, reason, lock_ratio
        return float(entry_price) + locked_points, reason, lock_ratio

    def _minutes_to_force_exit(self, now) -> float:
        """Minutes from `now` until the configured square-off; large if unknown."""
        if now is None:
            return 1e9
        try:
            fx = self._configured_session_time("ut_force_exit_time", "15:25")
            now_naive = (
                now.astimezone(IST).replace(tzinfo=None)
                if getattr(now, "tzinfo", None) is not None
                else now
            )
            fx_dt = datetime.combine(now_naive.date(), fx)
            return (fx_dt - now_naive).total_seconds() / 60.0
        except Exception:
            return 1e9

    def _eod_protect_active(self, now) -> bool:
        """Whether we are inside the EOD-proximity profit-protection window (Fix 2)."""
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "eod_protect_enabled", True), True):
            return False
        window = float(getattr(settings, "eod_protect_window_minutes", 30.0) or 30.0)
        mins = self._minutes_to_force_exit(now)
        return 0.0 <= mins <= window

    def _profit_giveback_arm(
        self, initial_risk_rs: float, now=None, nontrend_scope: bool = False,
        trade_like=None,
    ) -> float:
        """Peak P&L (Rs) at which the sub-1R give-back guard becomes active (Fix 1).
        Near square-off the arm is lowered further so modest peaks are protected.
        Non-trend sessions use a lower arm: at 1-lot size the Rs.500 floor sits
        above 0.40R, so the guard could mathematically never arm (2026-07-03:
        four sub-0.5R peaks round-tripped to full stops under that floor).

        Whatever the ladders say, the arm never drops below what a round trip costs.
        2026-08-11 15:11: PROFIT_GIVEBACK_GUARD closed BANKNIFTY 57400PE to protect a
        peak of Rs.36 and booked -Rs.44, because the position paid Rs.80 to open and
        close. Inside the EOD window the arm collapses to eod_protect_min_peak_rs
        (Rs.1), so any trivial blip armed a protective exit that could not come out
        ahead. The loss side of peak-threat already refuses on exactly this reasoning
        (see _round_trip_cost_rs); the profit side had no such floor."""
        settings = get_settings()
        min_rs = float(getattr(settings, "profit_giveback_min_peak_rs", 500.0) or 500.0)
        r_mult = float(getattr(settings, "profit_giveback_arm_r_multiple", 0.40) or 0.40)
        if nontrend_scope:
            min_rs = float(getattr(settings, "profit_giveback_nontrend_min_peak_rs", 300.0) or 300.0)
            r_mult = float(getattr(settings, "profit_giveback_nontrend_arm_r_multiple", 0.30) or 0.30)
        risk = abs(float(initial_risk_rs or 0.0))
        arm = max(min_rs, risk * r_mult) if risk > 0 else min_rs
        if now is not None and self._eod_protect_active(now):
            eod_r_raw = getattr(settings, "eod_protect_arm_r_multiple", 0.0)
            eod_min_raw = getattr(settings, "eod_protect_min_peak_rs", 1.0)
            eod_r = float(eod_r_raw if eod_r_raw is not None else 0.0)
            eod_min = float(eod_min_raw if eod_min_raw is not None else 1.0)
            arm = min(arm, max(eod_min, risk * eod_r) if risk > 0 else eod_min)
        return max(arm, Scanner._profit_protect_cost_floor_rs(self, trade_like))

    # Measured peak potential by regime — the median PEAK of every winning trade in the
    # 47 stored sessions, normalised against RANGING (Rs.809):
    #   TRENDING_UP Rs.3,070 (3.8x)   BREAKOUT_UP Rs.1,608 (2.0x)   VOLATILE Rs.1,064 (1.3x)
    #   RANGING     Rs.  809 (1.0x)   TRENDING_DOWN Rs.605 (0.7x)   BREAKOUT_DOWN Rs.562 (0.7x)
    # Deliberately compressed into a narrow band rather than used raw: the raw ratios
    # come from as few as 3 winners in some cells, and a 3.8x arm in TRENDING_UP would
    # stop PEAK_THREAT_EXIT arming there at all — the opposite of the intent.
    _REGIME_PEAK_SCALE = {
        "TRENDING_UP": 1.25,
        "BREAKOUT_UP": 1.15,
        "VOLATILE": 1.00,
        "RANGING": 0.85,
        "TRENDING_DOWN": 0.85,
        "BREAKOUT_DOWN": 0.85,
    }

    def _profit_threshold_scale(self, trade_like=None, initial_risk_rs: float = 0.0) -> float:
        """Multiplier on the ABSOLUTE rupee floors of every profit-side exit.

        Those floors — Rs.750 peak-threat, Rs.500/250 lock, Rs.500 give-back — are fixed
        rupees, while the moves they are meant to catch scale with volatility. When the
        market quietened from a 0.97% median daily range (W30) to 0.64% (W33), the share
        of trades ever reaching a Rs.750 peak fell 43% -> 4%, and PEAK_THREAT_EXIT — which
        banks 87% of peak on big trades — fired once in a week. The floors did not move,
        so the best exit in the system simply went dormant and LOSS_THREAT_EXIT rose from
        30% to 50% of all exits. Win rate followed: 47.8% -> 12.5%.

        Note what is NOT being changed. Each arm is max(absolute_floor, risk x r_multiple)
        and the R-multiple half ALREADY scales — initial_risk_rs is an ATR-derived stop
        distance times quantity. Only the floor is blind, and the max() makes it dominate
        precisely when risk is small, i.e. exactly in the quiet markets where it hurts.

        Volatility term: the trade's own risk against a reference, which needs no new
        plumbing and captures instrument, timeframe and size at once. Regime term: the
        measured peak potential of the regime, so a trend is allowed to develop before
        the lock arms while chop banks sooner. Bounded hard in both directions — this
        tunes an existing threshold, it does not remove one.
        """
        settings = get_settings()
        if not Scanner._setting_enabled(
            getattr(settings, "profit_threshold_scaling_enabled", True), True
        ):
            return 1.0
        try:
            reference = float(getattr(settings, "profit_threshold_reference_risk_rs", 1000.0) or 1000.0)
            lo = float(getattr(settings, "profit_threshold_scale_min", 0.35) or 0.35)
            hi = float(getattr(settings, "profit_threshold_scale_max", 2.00) or 2.00)
        except (TypeError, ValueError):
            return 1.0
        if reference <= 0 or lo <= 0 or hi < lo:
            return 1.0
        scale = 1.0
        try:
            risk = abs(float(initial_risk_rs or 0.0))
        except (TypeError, ValueError):
            risk = 0.0
        if risk > 0:
            # Absent risk is not evidence of a quiet market — the floor stands unscaled.
            scale *= risk / reference
        if Scanner._setting_enabled(
            getattr(settings, "profit_threshold_regime_scaling_enabled", True), True
        ) and trade_like is not None:
            try:
                regime = str(Scanner._get_trade_regime(self, trade_like, default="")).upper()
            except Exception:
                regime = ""
            scale *= Scanner._REGIME_PEAK_SCALE.get(regime, 1.0)
        return max(lo, min(hi, scale))

    def _profit_protect_cost_floor_rs(self, trade_like=None) -> float:
        """Smallest peak worth protecting: the round trip it costs to take the profit.

        A protective exit below this is value-destroying by construction — it pays a
        full round trip to bank less than the round trip. Returns 0.0 when disabled or
        when the cost cannot be established, so it can only ever raise an arm.

        Every internal call is made through the class rather than `self`, because the
        arm helpers are deliberately callable with a duck-typed self (see
        _profit_lock_floor's getattr dance) and a bound lookup raises there.
        """
        settings = get_settings()
        if not Scanner._setting_enabled(
            getattr(settings, "profit_protect_cost_floor_enabled", True), True
        ):
            return 0.0
        try:
            multiple = max(
                0.0,
                float(getattr(settings, "profit_protect_min_cost_multiple", 1.0) or 0.0),
            )
        except (TypeError, ValueError):
            multiple = 1.0
        if multiple <= 0:
            return 0.0
        try:
            return Scanner._round_trip_cost_rs(self, trade_like) * multiple
        except Exception:
            return 0.0

    def _current_day_type(self, instrument: str) -> str:
        """Latest session-context day classification for an instrument ('UNDECIDED' when unknown).

        Blends the horizons: with session_mood_dynamic_enabled (default ON) the
        rolling effective phase (day + 1h + 15m pockets from session_context)
        wins — but ONLY at/above session_mood_min_confidence; below the floor,
        or with the toggle OFF, the sticky full-day opening label is returned so
        exit guards do not flap on low-conviction pockets. The minute/second
        horizon is deliberately not read here — the market LTP shock detector
        and directional census own that band.
        """
        try:
            base = str(instrument or "").split()[0].upper()
            intel = self._cached_timeframe_intel(base, "5min", allow_fallback=True) or {}
            ctx = intel.get("session_context", {}) if isinstance(intel, dict) else {}
            if not isinstance(ctx, dict):
                return "UNDECIDED"
            settings = get_settings()
            use_dynamic = self._setting_enabled(
                getattr(settings, "session_mood_dynamic_enabled", True), True
            )
            opening = str(
                ctx.get("opening_day_type") or ctx.get("day_type") or "UNDECIDED"
            ).upper()
            if not use_dynamic:
                return opening or "UNDECIDED"
            min_conf = float(
                getattr(settings, "session_mood_min_confidence", 0.55) or 0.55
            )
            phase_conf = float(
                ctx.get("phase_confidence")
                if ctx.get("phase_confidence") is not None
                else ctx.get("confidence") or 0.0
            )
            if phase_conf < min_conf:
                return opening or "UNDECIDED"
            for key in ("effective_day_type", "market_phase", "intraday_phase"):
                val = str(ctx.get(key) or "").upper()
                if val and val not in {"", "UNDECIDED"}:
                    # Normalize mood labels for callers that only understand TREND_*
                    if val == "MOOD_DUMP":
                        return "TREND_DAY_DOWN"
                    if val == "MOOD_RALLY":
                        return "TREND_DAY_UP"
                    if val == "MOOD_TRANSITION":
                        continue
                    return val
            return opening or "UNDECIDED"
        except Exception:
            return "UNDECIDED"

    @staticmethod
    def _regime_opposes_direction(view: str, regime) -> bool:
        """True when a directional regime runs against the trade's view (Fix 3)."""
        view = str(view or "").upper()
        if view not in {"LONG", "SHORT"}:
            return False
        opposing = "SELL" if view == "LONG" else "BUY"
        try:
            return bool(regime_aligns(regime, opposing))
        except Exception:
            return False

    @staticmethod
    def _trade_direction_view(
        trade_like,
        *,
        inst_type: str = "",
        option_type: str = "",
        direction: str = "",
    ) -> str:
        inst = str(inst_type or getattr(trade_like, "inst_type", "") or "").upper()
        opt = str(option_type or getattr(trade_like, "option_type", "") or "").upper()
        symbol = str(
            getattr(trade_like, "option_symbol", "")
            or getattr(trade_like, "trading_symbol", "")
            or ""
        ).upper()
        if not opt and symbol:
            if symbol.endswith("CE"):
                opt = "CE"
            elif symbol.endswith("PE"):
                opt = "PE"
        if inst == "OPT" and opt in {"CE", "PE"}:
            return "LONG" if opt == "CE" else "SHORT"
        trade_side = str(getattr(trade_like, "trade_side", "") or "").upper()
        if "CE" in trade_side:
            return "LONG"
        if "PE" in trade_side:
            return "SHORT"
        return str(
            direction
            or getattr(trade_like, "underlying_direction", "")
            or getattr(trade_like, "direction", "")
            or ""
        ).upper()

    def _trade_like_market_intelligence_context(self, trade_like) -> Dict[str, Any]:
        ctx = getattr(trade_like, "market_intelligence_context", None)
        if isinstance(ctx, dict) and ctx:
            return ctx
        try:
            intel = self._cached_timeframe_intel(
                str(getattr(trade_like, "instrument", "") or "").split()[0],
                getattr(trade_like, "timeframe", "5min"),
                allow_fallback=True,
            )
        except Exception:
            intel = None
        if not isinstance(intel, dict):
            return {}
        return {
            "aggregate": intel.get("aggregate", {}) if isinstance(intel.get("aggregate"), dict) else {},
            "order_flow": intel.get("order_flow", {}) if isinstance(intel.get("order_flow"), dict) else {},
            "volume": intel.get("volume", {}) if isinstance(intel.get("volume"), dict) else {},
            "oi": intel.get("oi", {}) if isinstance(intel.get("oi"), dict) else {},
            "pcr": intel.get("pcr", {}) if isinstance(intel.get("pcr"), dict) else {},
            "regime": intel.get("regime", {}) if isinstance(intel.get("regime"), dict) else {},
            "session_context": intel.get("session_context", {}) if isinstance(intel.get("session_context"), dict) else {},
            "anchor_regime": intel.get("anchor_regime", {}) if isinstance(intel.get("anchor_regime"), dict) else {},
            "breadth_context": intel.get("breadth_context", {}) if isinstance(intel.get("breadth_context"), dict) else {},
            "top_down_context": intel.get("top_down_context", {}) if isinstance(intel.get("top_down_context"), dict) else {},
        }

    def _trade_like_signed_intelligence(self, trade_like, ctx: Optional[Dict[str, Any]] = None) -> float:
        try:
            signed = float(getattr(trade_like, "intelligence_score", 0.0) or 0.0)
        except Exception:
            signed = 0.0
        if abs(signed) >= 1e-9:
            if abs(signed) > 1.5:
                return normalize_intelligence_score(signed)
            return max(-1.0, min(1.0, signed))
        ctx = ctx if isinstance(ctx, dict) else self._trade_like_market_intelligence_context(trade_like)
        try:
            aggregate = ctx.get("aggregate", {}) if isinstance(ctx, dict) and isinstance(ctx.get("aggregate"), dict) else {}
            return aggregate_intelligence_score(aggregate)
        except Exception:
            return 0.0

    @staticmethod
    def _direction_signal_for_view(view: str) -> str:
        view = str(view or "").upper()
        if view == "LONG":
            return "BUY"
        if view == "SHORT":
            return "SELL"
        return ""

    @staticmethod
    def _view_aligned_intel_score(view: str, signed_intel: float) -> float:
        view = str(view or "").upper()
        try:
            score = float(signed_intel or 0.0)
        except Exception:
            score = 0.0
        if view == "SHORT":
            return -score
        if view == "LONG":
            return score
        return 0.0

    @staticmethod
    def _regime_conviction_vector_from_context(trade_like, ctx: Dict[str, Any]) -> Dict[str, float]:
        direct = getattr(trade_like, "regime_conviction_vector", None)
        if isinstance(direct, dict) and direct:
            source = direct
        else:
            source = {}
            if isinstance(ctx, dict):
                for key in ("regime_context", "anchor_regime", "aggregate"):
                    item = ctx.get(key, {})
                    if isinstance(item, dict):
                        vec = item.get("conviction_vector") or item.get("regime_conviction_vector")
                        if isinstance(vec, dict) and vec:
                            source = vec
                            break
        out: Dict[str, float] = {}
        for key, value in (source or {}).items():
            try:
                out[str(key)] = float(value or 0.0)
            except Exception:
                continue
        return out

    def _choppy_profit_lock_bypass_peak_threshold(
        self,
        trade_like,
        *,
        regime_text: str,
        latest_time: Optional[datetime],
        entry_price: float,
        qty: int,
        peak_pnl: float,
    ) -> Tuple[float, str]:
        """Adaptive minimum peak before option breathing may stop diluting a lock.

        The lock price itself is still computed by _profit_lock_floor. This only
        decides whether a scalp/chop option has shown enough evidence to keep that
        floor instead of relaxing it back under entry for premium noise.
        """
        settings = get_settings()
        base_peak = max(0.0, float(getattr(settings, "choppy_profit_lock_bypass_peak_rs", 1000.0) or 1000.0))
        low_peak = max(0.0, float(getattr(settings, "choppy_profit_lock_low_move_peak_rs", 750.0) or 750.0))
        urgent_peak = max(0.0, float(getattr(settings, "choppy_profit_lock_urgent_peak_rs", 500.0) or 500.0))
        threshold = base_peak
        reasons: List[str] = []

        ctx = self._trade_like_market_intelligence_context(trade_like)
        session_ctx = ctx.get("session_context", {}) if isinstance(ctx.get("session_context"), dict) else {}
        vector = self._regime_conviction_vector_from_context(trade_like, ctx)
        view = self._trade_direction_view(
            trade_like,
            inst_type=getattr(trade_like, "inst_type", ""),
            option_type=getattr(trade_like, "option_type", ""),
            direction=getattr(trade_like, "direction", ""),
        )
        desired_signal = self._direction_signal_for_view(view)

        low_motion = False
        try:
            range_vs_10day = float(session_ctx.get("range_vs_10day", 0.0) or 0.0)
        except Exception:
            range_vs_10day = 0.0
        if 0.0 < range_vs_10day <= float(getattr(settings, "choppy_profit_lock_low_range_vs_10day", 0.65) or 0.65):
            low_motion = True
            reasons.append(f"quiet range {range_vs_10day:.2f}x")
        phase, phase_conf = self._intraday_phase_from_session_context(session_ctx)
        if phase == "RANGE_PHASE" and phase_conf >= 0.60:
            reasons.append("range phase")
        if float(vector.get("volatility_expansion_prob", 1.0) or 0.0) <= 0.25:
            low_motion = True
            reasons.append("low volatility expansion")

        pressure = 0
        aggregate = ctx.get("aggregate", {}) if isinstance(ctx.get("aggregate"), dict) else {}
        signed_intel = self._trade_like_signed_intelligence(trade_like, ctx)
        intel_present = (
            abs(signed_intel) >= 1e-9
            or "score" in aggregate
            or bool(aggregate.get("signal") or aggregate.get("bias"))
        )
        aligned_intel = self._view_aligned_intel_score(view, signed_intel)
        adverse_intel = float(getattr(settings, "choppy_profit_lock_adverse_intel", 0.65) or 0.65)
        if intel_present:
            if aligned_intel <= -adverse_intel:
                pressure += 2
                reasons.append(f"adverse intel {aligned_intel:.2f}")
            elif aligned_intel <= 0.05:
                pressure += 1
                reasons.append(f"weak intel {aligned_intel:.2f}")

        agg_signal = str(aggregate.get("signal", "") or aggregate.get("bias", "") or "").upper()
        if desired_signal and agg_signal:
            if agg_signal in {"BUY", "SELL"} and agg_signal != desired_signal:
                pressure += 2
                reasons.append(f"intel signal {agg_signal} opposes")
            elif agg_signal in {"HOLD", "NEUTRAL", "MIXED"}:
                pressure += 1
                reasons.append("intel neutral")

        try:
            live_ctx = self._live_direction_context(trade_like, view, regime_text)
        except Exception:
            live_ctx = {}
        if live_ctx.get("adverse") or self._regime_opposes_direction(view, regime_text):
            pressure += 2
            reasons.append("trend/regime adverse")

        if view == "LONG":
            adverse_trend_prob = max(float(vector.get("trend_down_prob", 0.0) or 0.0), float(vector.get("breakout_down_prob", 0.0) or 0.0))
        elif view == "SHORT":
            adverse_trend_prob = max(float(vector.get("trend_up_prob", 0.0) or 0.0), float(vector.get("breakout_up_prob", 0.0) or 0.0))
        else:
            adverse_trend_prob = 0.0
        if adverse_trend_prob >= 0.55 or float(vector.get("reversal_prob", 0.0) or 0.0) >= 0.65:
            pressure += 2
            reasons.append("regime vector adverse")

        current_price = float(getattr(trade_like, "current_price", 0.0) or 0.0)
        if current_price > 0 and entry_price > 0 and qty > 0 and peak_pnl > 0:
            current_pnl = (current_price - entry_price) * qty
            if current_pnl <= 0.0:
                pressure += 2
                reasons.append("premium below entry")
            else:
                melt_ratio = float(getattr(settings, "choppy_profit_lock_premium_melt_ratio", 0.45) or 0.45)
                fade_ratio = float(getattr(settings, "choppy_profit_lock_premium_fade_ratio", 0.65) or 0.65)
                if current_pnl <= peak_pnl * melt_ratio:
                    pressure += 2
                    reasons.append(f"premium melt {current_pnl / peak_pnl:.0%}")
                elif current_pnl <= peak_pnl * fade_ratio:
                    pressure += 1
                    reasons.append(f"premium fade {current_pnl / peak_pnl:.0%}")

        try:
            volume_ratio = float(getattr(trade_like, "volume_ratio", 0.0) or 0.0)
        except Exception:
            volume_ratio = 0.0
        if volume_ratio <= 0.0:
            volume_ctx = aggregate.get("volume", {}) if isinstance(aggregate.get("volume"), dict) else {}
            for key in ("display_volume_ratio", "relative_volume_ratio", "volume_ratio"):
                try:
                    volume_ratio = float(volume_ctx.get(key, 0.0) or 0.0)
                except Exception:
                    volume_ratio = 0.0
                if volume_ratio > 0:
                    break
        weak_volume = float(getattr(settings, "choppy_profit_lock_weak_volume_ratio", 1.05) or 1.05)
        if 0.0 < volume_ratio < weak_volume:
            pressure += 1
            reasons.append(f"weak volume {volume_ratio:.2f}x")

        if latest_time is not None and self._eod_protect_active(latest_time):
            pressure += 1
            reasons.append("session-end pressure")
            try:
                final_window = float(getattr(settings, "eod_profit_final_window_minutes", 10.0) or 10.0)
                if self._minutes_to_force_exit(latest_time) <= final_window:
                    pressure += 1
                    reasons.append("final runway")
            except Exception:
                pass

        entry_time = getattr(trade_like, "signal_timestamp", getattr(trade_like, "entry_time", None))
        if latest_time is not None and entry_time is not None and peak_pnl > 0:
            try:
                ref = entry_time.astimezone(IST).replace(tzinfo=None) if getattr(entry_time, "tzinfo", None) is not None else entry_time
                now = latest_time.astimezone(IST).replace(tzinfo=None) if getattr(latest_time, "tzinfo", None) is not None else latest_time
                age_minutes = max(0.0, (now - ref).total_seconds() / 60.0)
                stagnation_minutes = max(1.0, float(getattr(settings, "trade_stagnation_minutes", 20.0) or 20.0))
                if age_minutes >= stagnation_minutes:
                    pressure += 1
                    reasons.append(f"stagnant {age_minutes:.0f}m")
            except Exception:
                pass

        if low_motion:
            threshold = min(threshold, low_peak)
        if pressure >= 3 or (low_motion and pressure >= 2):
            threshold = min(threshold, urgent_peak)
        elif pressure >= 1:
            threshold = min(threshold, low_peak)
        context = ", ".join(dict.fromkeys(reasons)) if reasons else "base"
        return max(0.0, threshold), context

    def _live_direction_context(self, trade_like, view: str, regime: str) -> Dict[str, Any]:
        base = str(getattr(trade_like, "instrument", "") or "").split()[0].upper()
        try:
            live_regime = (getattr(self, "latest_regimes", {}) or {}).get(base)
        except Exception:
            live_regime = None
        # The TRADE'S OWN timeframe wins. `regime` is what every caller passes, and they
        # derive it from _get_trade_regime(trade); `latest_regimes` is keyed by INSTRUMENT
        # with no timeframe and is written on the 5-minute pass, so reading it first meant
        # a 15-minute trade was always judged on the 5-minute label.
        #
        # That cost money in both directions. A 5-minute flip against a profitable
        # 15-minute position fired LIVE_REVERSAL_EXIT and cut a winner its own timeframe
        # still supported; conversely a 5-minute label that merely looked aligned relaxed
        # the end-of-day give-back on evidence belonging to a different chart. The
        # borrowed-label rule stated elsewhere in this file is explicit that a sampled
        # cross-timeframe regime "must NOT be used to grant a privilege".
        live_regime = str(regime or live_regime or getattr(trade_like, "market_regime", "") or "UNKNOWN")
        view = str(view or "").upper()
        if view == "LONG":
            aligned_side = "BUY"
        elif view == "SHORT":
            aligned_side = "SELL"
        else:
            aligned_side = ""
        aligned = False
        if aligned_side:
            try:
                aligned = bool(regime_aligns(live_regime, aligned_side))
            except Exception:
                aligned = False
        opposed = self._regime_opposes_direction(view, live_regime)

        cross_opp = cross_aligned = cross_peers = 0
        if view in {"LONG", "SHORT"}:
            try:
                cross_opp, cross_aligned, cross_peers = self._cross_index_reversal_against(view, base)
            except Exception:
                pass
        try:
            min_opp = int(getattr(get_settings(), "cross_index_reversal_min_opposing", 2) or 2)
        except Exception:
            min_opp = 2
        cross_adverse = cross_peers > 0 and cross_opp >= min_opp
        supportive = bool(aligned and not opposed and not cross_adverse)
        adverse = bool(opposed or cross_adverse)
        return {
            "base": base,
            "live_regime": live_regime,
            "aligned": aligned,
            "opposed": opposed,
            "cross_opp": int(cross_opp),
            "cross_aligned": int(cross_aligned),
            "cross_peers": int(cross_peers),
            "cross_adverse": cross_adverse,
            "supportive": supportive,
            "adverse": adverse,
        }

    def _eod_profit_giveback_ratio(
        self,
        trade_like,
        *,
        base_ratio: float,
        view: str,
        latest_time,
        regime: str,
    ) -> Tuple[float, str]:
        settings = get_settings()
        if (
            latest_time is None
            or not self._eod_protect_active(latest_time)
            or not self._setting_enabled(getattr(settings, "eod_profit_adaptive_peak_enabled", True), True)
        ):
            return base_ratio, "base"

        ctx = self._live_direction_context(trade_like, view, regime)
        mins = self._minutes_to_force_exit(latest_time)
        if ctx.get("adverse"):
            ratio = max(
                base_ratio,
                float(getattr(settings, "eod_profit_adverse_exit_ratio", 0.75) or 0.75),
            )
            return ratio, (
                f"EOD adverse context: regime={ctx.get('live_regime')}, "
                f"peers {ctx.get('cross_opp')}/{ctx.get('cross_peers')} oppose"
            )
        final_window = max(0.0, float(getattr(settings, "eod_profit_final_window_minutes", 10.0) or 10.0))
        if mins <= final_window and not ctx.get("supportive"):
            ratio = max(
                base_ratio,
                float(getattr(settings, "eod_profit_neutral_exit_ratio", 0.65) or 0.65),
            )
            return ratio, f"EOD neutral final runway {mins:.1f}m"
        if ctx.get("supportive"):
            ratio = min(
                base_ratio,
                float(getattr(settings, "eod_profit_supportive_exit_ratio", 0.45) or 0.45),
            )
            return ratio, f"EOD supportive context: regime={ctx.get('live_regime')}"
        return base_ratio, "EOD base"

    @staticmethod
    def _intel_signal_opposes_view(signal: str, view: str) -> bool:
        signal = str(signal or "").upper()
        view = str(view or "").upper()
        bullish = {"BUY", "BULLISH", "BULLISH_VOLUME", "LONG", "UP", "BREAKOUT_UP", "TRENDING_UP"}
        bearish = {"SELL", "BEARISH", "BEARISH_VOLUME", "SHORT", "DOWN", "BREAKOUT_DOWN", "TRENDING_DOWN"}
        if view == "LONG":
            return signal in bearish
        if view == "SHORT":
            return signal in bullish
        return False

    @staticmethod
    def _intel_signal_aligns_view(signal: str, view: str) -> bool:
        signal = str(signal or "").upper()
        view = str(view or "").upper()
        bullish = {"BUY", "BULLISH", "BULLISH_VOLUME", "LONG", "UP", "BREAKOUT_UP", "TRENDING_UP"}
        bearish = {"SELL", "BEARISH", "BEARISH_VOLUME", "SHORT", "DOWN", "BREAKOUT_DOWN", "TRENDING_DOWN"}
        if view == "LONG":
            return signal in bullish
        if view == "SHORT":
            return signal in bearish
        return False

    @staticmethod
    def _clear_exit_confirmation(trade_like, attr_name: str) -> None:
        """Drop a named exit-confirmation latch."""
        try:
            setattr(trade_like, attr_name, None)
        except Exception:
            pass

    def _exit_confirmation_ready(
        self,
        trade_like,
        attr_name: str,
        signature,
        latest_time,
        confirm_seconds: float,
    ) -> Tuple[bool, str]:
        """Require two distinct observations separated by a bounded interval.

        Ported from restore_point_51, which confirms BOTH sides of the near-peak
        guard through this one helper. This build had it on the loss side only
        (inline), so a single high-scoring tick cut a winner outright.

        Scanner cycles can run several times against the same market timestamp, so
        counting calls would manufacture persistence — the latch advances only when
        the observation clock advances. Callers drop it on every path that stops
        short of an exit, so a confirmation can never be assembled from observations
        taken minutes apart under different conditions.
        """
        try:
            observed = latest_time
            if getattr(observed, "tzinfo", None) is None:
                observed = pd.Timestamp(observed).tz_localize(IST)
            else:
                observed = pd.Timestamp(observed).tz_convert(IST)
            observed_ts = float(observed.timestamp())
        except Exception:
            Scanner._clear_exit_confirmation(trade_like, attr_name)
            return False, "invalid confirmation clock"

        required = max(0.5, float(confirm_seconds or 0.0))
        canonical = (
            tuple(signature) if isinstance(signature, (list, tuple, set)) else (str(signature),)
        )
        state = getattr(trade_like, attr_name, None)
        if not isinstance(state, dict) or tuple(state.get("signature", ())) != canonical:
            try:
                setattr(
                    trade_like,
                    attr_name,
                    {
                        "signature": list(canonical),
                        "first_at": observed_ts,
                        "last_at": observed_ts,
                        "observations": 1,
                    },
                )
            except Exception:
                return True, "confirmation state unavailable"
            return False, f"confirmation 1/2 (0.0/{required:.1f}s)"

        first_at = float(state.get("first_at", observed_ts) or observed_ts)
        last_at = float(state.get("last_at", first_at) or first_at)
        observations = max(1, int(state.get("observations", 1) or 1))
        if observed_ts > last_at:
            observations += 1
            state["last_at"] = observed_ts
            state["observations"] = observations
        elapsed = max(0.0, observed_ts - first_at)
        if observations >= 2 and elapsed >= required:
            Scanner._clear_exit_confirmation(trade_like, attr_name)
            return True, f"confirmed {observations} observations over {elapsed:.1f}s"
        return False, f"confirming {observations}/2 ({elapsed:.1f}/{required:.1f}s)"

    @staticmethod
    def _clear_loss_threat_confirmation(trade_like) -> None:
        """Drop the LOSS_THREAT confirmation latch.

        Called on EVERY path that stops short of an exit, so a confirmation can never be
        assembled out of observations taken minutes apart under different conditions. A
        latch that survives its own preconditions is worse than none: it would let a
        stale first sighting complete against an unrelated second one.
        """
        try:
            setattr(trade_like, "_loss_threat_confirmation", None)
        except Exception:
            pass

    def _round_trip_cost_rs(self, trade_like, inst_type: str = "") -> float:
        """What it costs to open and close this position, in rupees.

        Any exit taken to avoid a loss SMALLER than this figure is value-destroying
        before it is anything else. The dashboard's own per-trade cost settings are the
        source, so the floor moves with whatever the operator has configured.
        """
        settings = get_settings()
        kind = str(inst_type or getattr(trade_like, "inst_type", "") or "OPT").upper()
        try:
            flat = max(0.0, float(
                getattr(settings, "opt_cost", 80.0) if kind == "OPT"
                else getattr(settings, "fut_cost", 200.0)
            ) or 0.0)
        except (TypeError, ValueError):
            flat = 0.0
        # The flat configured cost is the real round trip (Rs.68-86 measured across the
        # four indices, configured 80). estimate_trade_charges would add ~Rs.90 of MODELED
        # SLIPPAGE on top, which would make this floor roughly twice the true cost of
        # closing and suppress exits that are genuinely worth taking.
        return flat

    def _position_is_underwater(self, trade_like, net_pnl_rs: float) -> bool:
        """Whether the MARKET has moved against this position.

        Net P&L at the instant of entry is minus the round trip the trade owes in
        brokerage and taxes, so `net < 0` is true for every trade the moment it
        opens and says nothing about direction. The relaxed 2-vote OI/PCR reversal
        bar exists for a trade the market has actually turned on; handed to every
        newborn trade it becomes a coin-flip exit on the first intel sample after
        entry, at the bar meant for confirmed losers.

        2026-08-12 09:15:27: MIDCPNIFTY 14975CE (A+, 95%) was entered at 09:15:03
        with no option chain fetched yet — PCR still read 0 at 09:15:10. The
        session's FIRST chain arrived at 09:15:26 and voted 2/2 bearish, closing the
        trade flat 24s after entry for -Rs.80. At the 3-vote winner bar those same
        two votes hold. Same reasoning the loss side of peak-threat already applies
        through _round_trip_cost_rs: the cost is identical for every trade and
        carries no directional information, so it may not decide direction.
        """
        cost = abs(float(Scanner._round_trip_cost_rs(self, trade_like) or 0.0))
        return float(net_pnl_rs or 0.0) < -cost

    @staticmethod
    def _trade_like_age_seconds(trade_like, latest_time) -> Optional[float]:
        """Seconds since the fill, or None when it cannot be established.

        None means "cannot tell" and callers must NOT treat it as old — the same
        never-conclude-from-absence rule the repaint guard now follows. A candle clock
        BEHIND the entry also yields None: direction-safety, so an inconsistent clock
        cannot manufacture an age (see test_the_age_helper_is_direction_safe).
        """
        if latest_time is None:
            return None
        entered = (
            getattr(trade_like, "entry_time", None)
            or getattr(trade_like, "entry_timestamp", None)
            or getattr(trade_like, "signal_time", None)
        )
        if entered is None:
            return None
        try:
            start = pd.Timestamp(entered)
            now = pd.Timestamp(latest_time)
            if start.tzinfo is not None:
                start = start.tz_convert(IST).tz_localize(None)
            if now.tzinfo is not None:
                now = now.tz_convert(IST).tz_localize(None)
            age = float((now - start).total_seconds())
        except Exception:
            return None
        if age != age or age < 0:
            return None
        return age

    def _peak_threat_flow_points(self, trade_like, order_flow, view: str) -> Tuple[int, str]:
        """Threat points from the order-flow pillar: (points, reason).

        `or 0.0` followed by `if flow_ratio > 0` read a genuine 0.0 as absent, so the
        most sell-heavy tape the pillar can report — every trade on the sell side —
        contributed nothing to a LONG's threat score, while a merely missing feed
        reached the same conclusion for the opposite reason. Unknown now scores
        nothing explicitly and a real extreme scores, per this function's own rule
        that "'Unclear' is not 'against'".
        """
        flow_ratio = Scanner._first_present_number(order_flow, "ratio", "buy_sell_ratio")
        if flow_ratio is None:
            return 0, ""
        if str(view or "").upper() == "LONG" and flow_ratio < 0.75:
            return 1, f"sell-heavy flow {flow_ratio:.2f}"
        if str(view or "").upper() == "SHORT" and flow_ratio > 1.25:
            return 1, f"buy-heavy flow {flow_ratio:.2f}"
        return 0, ""

    def _peak_threat_exit_decision(
        self,
        trade_like,
        *,
        current_price: float,
        current_pnl_rs: float,
        peak_pnl: float,
        initial_risk_rs: float,
        latest_time,
        regime: str,
        inst_type: str = "",
        option_type: str = "",
        direction: str = "",
    ) -> Tuple[bool, str, str]:
        """Exit near peak when broad evidence says the trade is about to be eaten.

        This is intentionally separate from target/profit-lock/giveback:
        - profitable trades need a meaningful peak and high retention, so we only
          cut near-peak winners on strong reversal evidence;
        - losing trades use a stricter score and a small-loss cap, so this can
          reduce damage when the market flips hard without becoming a blind stop.
        """
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "peak_threat_exit_enabled", True), True):
            return False, "", "disabled"
        if latest_time is None:
            return False, "", "missing time"

        current_pnl = float(current_pnl_rs or 0.0)
        peak = max(0.0, float(peak_pnl or 0.0))
        risk = abs(float(initial_risk_rs or 0.0))
        view = self._trade_direction_view(
            trade_like,
            inst_type=inst_type,
            option_type=option_type,
            direction=direction,
        )
        if view not in {"LONG", "SHORT"}:
            return False, "", "unknown trade view"

        # The Rs.750 floor is what went dormant as the market quietened: across the
        # stored sessions the share of trades ever reaching it fell 43% -> 4% while this
        # number stayed fixed, and PEAK_THREAT_EXIT — the 87%-capture exit — stopped
        # firing. Scaled by volatility and regime; the r-multiple term already scaled.
        min_peak = max(
            0.0,
            float(getattr(settings, "peak_threat_exit_min_peak_rs", 750.0) or 750.0)
            * Scanner._profit_threshold_scale(self, trade_like, risk),
            risk * float(getattr(settings, "peak_threat_exit_min_peak_r", 0.35) or 0.35),
        )
        retention = (current_pnl / peak) if peak > 0.0 else 0.0
        min_retention = max(
            0.05,
            min(1.0, float(getattr(settings, "peak_threat_exit_min_retention", 0.72) or 0.72)),
        )
        # P&L reaching here is GROSS/executable-mark in both the session and
        # TradeManager paths, so an exactly-flat premium is not a loss — it only
        # becomes one once the eventual row adds the round trip. restore_point_51
        # draws the line at < -1e-9 for that reason; this build called flat a loss
        # and routed it to the loss branch's bookkeeping.
        loss_mode = current_pnl < -1e-9
        if not loss_mode:
            # Back above water: any half-built loss confirmation is void.
            self._clear_loss_threat_confirmation(trade_like)
            # Winner-side minimum age, ported from restore_point_51: "gap/synthetic
            # marks at the open can manufacture an instant peak that arms this exit
            # on a seconds-old position (2026-07-15; ledger rows exited 1-22s after
            # entry)". This build kept the loss-side hold below and lost this one, so
            # the profit branch could fire before any post-entry tape existed. The
            # opening window is escalated because that is where a synthetic mark is
            # most likely to invent the peak in the first place.
            #
            # An age of None means "cannot tell" and must not block — the same
            # never-conclude-from-absence rule _trade_like_age_seconds states, and
            # what the old build meant by "only enforceable when an actual entry
            # clock exists; legacy rows keep the old behavior".
            if self._setting_enabled(
                getattr(settings, "peak_threat_exit_min_age_enabled", True), True
            ):
                age_seconds = Scanner._trade_like_age_seconds(trade_like, latest_time)
                if age_seconds is not None:
                    min_age = max(
                        0.0,
                        float(getattr(settings, "peak_threat_exit_min_age_seconds", 45.0) or 45.0),
                    )
                    try:
                        latest_ref = (
                            latest_time.astimezone(IST).replace(tzinfo=None)
                            if getattr(latest_time, "tzinfo", None) is not None
                            else latest_time
                        )
                        parts = str(
                            getattr(settings, "peak_threat_exit_open_window_end", "09:30") or "09:30"
                        ).split(":")
                        if dtime(9, 15) <= latest_ref.time() <= dtime(int(parts[0]), int(parts[1])):
                            min_age = max(
                                min_age,
                                float(
                                    getattr(
                                        settings,
                                        "peak_threat_exit_open_window_min_age_seconds",
                                        120.0,
                                    )
                                    or 120.0
                                ),
                            )
                    except Exception:
                        pass
                    if age_seconds < min_age:
                        Scanner._clear_exit_confirmation(trade_like, "_peak_threat_confirmation")
                        return False, "", (
                            f"near-peak threat observing post-entry tape "
                            f"{age_seconds:.1f}s/{min_age:.1f}s"
                        )
            if peak < min_peak:
                Scanner._clear_exit_confirmation(trade_like, "_peak_threat_confirmation")
                return False, "", f"peak Rs.{peak:.0f} below near-peak arm Rs.{min_peak:.0f}"
            if retention < min_retention:
                Scanner._clear_exit_confirmation(trade_like, "_peak_threat_confirmation")
                return False, "", f"retention {retention:.0%} below near-peak threshold {min_retention:.0%}"
        else:
            if not self._setting_enabled(getattr(settings, "peak_threat_exit_loss_enabled", True), True):
                self._clear_loss_threat_confirmation(trade_like)
                return False, "", "loss threat exit disabled"
            # A position is negative from its first tick, because the entry pays the ask
            # and the mark is the LTP/bid. Cutting there costs a full round trip to avoid
            # a loss smaller than that round trip, which cannot come out ahead.
            round_trip = self._round_trip_cost_rs(trade_like, inst_type=inst_type)
            cost_multiple = max(
                0.0,
                float(getattr(settings, "peak_threat_exit_loss_min_cost_multiple", 1.0) or 0.0),
            )
            cost_floor = round_trip * cost_multiple
            if cost_floor > 0 and abs(current_pnl) < cost_floor:
                self._clear_loss_threat_confirmation(trade_like)
                return False, "", (
                    f"loss Rs.{abs(current_pnl):.0f} is under the Rs.{cost_floor:.0f} "
                    "round-trip cost; exiting here cannot beat the spread"
                )
            # Nor before the trade has had time to print anything of its own.
            min_hold = max(0.0, float(getattr(settings, "peak_threat_exit_min_hold_seconds", 60.0) or 0.0))
            if min_hold > 0:
                held = self._trade_like_age_seconds(trade_like, latest_time)
                # latest_time is the CANDLE clock, and an intracandle entry is stamped
                # AFTER the bar it fired inside — a fill at 15:09:36 against the 15:05:00
                # bar computes -276s, which the helper correctly refuses as an
                # inconsistent clock. But INTRACANDLE is the default fire mode, so that
                # refusal was the NORMAL case, and None reaching the test below meant the
                # 60s hold never applied: 54 of 98 LOSS_THREAT_EXITs fired inside it, 16
                # within five seconds, together -Rs.11,869.
                #
                # The helper's contract is right and stays as it is. What this guard
                # actually needs is how long the POSITION has been open, which the wall
                # clock knows exactly. Live only — in a replay "now" is meaningless, so
                # HISTORICAL keeps the candle-derived answer and its None.
                if held is None and str(getattr(self, "mode", "") or "").upper() != "HISTORICAL":
                    held = self._trade_like_age_seconds(trade_like, datetime.now(IST))
                # A still-unknown age does NOT block: refusing a row with no entry stamp
                # would disarm the exit entirely (test_an_unknowable_age_does_not_block_
                # the_guard, 2026-08-10).
                if held is not None and held < min_hold:
                    self._clear_loss_threat_confirmation(trade_like)
                    return False, "", (
                        f"held {held:.0f}s, under the {min_hold:.0f}s minimum before a "
                        "loss-threat exit may fire"
                    )
            max_loss_r = max(
                0.05,
                float(getattr(settings, "peak_threat_exit_loss_max_loss_r", 0.35) or 0.35),
            )
            if risk > 0 and abs(current_pnl) > risk * max_loss_r:
                self._clear_loss_threat_confirmation(trade_like)
                return False, "", f"loss Rs.{current_pnl:.0f} beyond peak-threat loss cap {max_loss_r:.2f}R"

        score = 0
        reasons: List[str] = []
        severe = False
        # WHICH kinds of evidence spoke, not just how much they scored. Ported from the
        # restore_point_51 build, whose loss arm required at least two distinct domains
        # with `price` among them before it would cut. Without it, five soft intel votes
        # look identical to a real price break — which is how 2026-08-10 produced nine
        # exits with no price evidence in them at all.
        evidence_domains: set = set()

        context_price = float(current_price or 0.0)
        try:
            spot = float(self.candles.get_latest_price(getattr(trade_like, "instrument", "")) or 0.0)
            if spot > 0:
                context_price = spot
        except Exception:
            pass

        price_ctx = self._profit_guard_reversal_context(
            trade_like,
            context_price,
            latest_time,
            timeframe=getattr(trade_like, "timeframe", "5min"),
        )
        if price_ctx.get("has_context"):
            if price_ctx.get("fast_reversal"):
                score += 3
                severe = True
                reasons.append(f"fast reversal ({price_ctx.get('reason')})")
            if price_ctx.get("one_min_emergency"):
                score += 2
                severe = True
                reasons.append("1min emergency")
            if not price_ctx.get("trend_supportive"):
                score += 2
                evidence_domains.add("price")
                reasons.append(f"trend support lost ({price_ctx.get('reason')})")
            elif int(price_ctx.get("trend_votes", 0) or 0) <= 1:
                score += 1
                reasons.append(f"weak trend votes {int(price_ctx.get('trend_votes', 0) or 0)}/3")
        else:
            reasons.append(str(price_ctx.get("reason", "no price context")))

        try:
            live_ctx = self._live_direction_context(trade_like, view, regime)
        except Exception:
            live_ctx = {}
        if live_ctx.get("adverse"):
            score += 2
            evidence_domains.add("live_market")
            reasons.append(
                f"live context adverse regime={live_ctx.get('live_regime')} "
                f"peers {live_ctx.get('cross_opp')}/{live_ctx.get('cross_peers')}"
            )
        elif live_ctx.get("supportive") and not severe:
            reasons.append(f"live context supportive regime={live_ctx.get('live_regime')}")

        ctx = self._trade_like_market_intelligence_context(trade_like)
        aggregate = ctx.get("aggregate", {}) if isinstance(ctx.get("aggregate"), dict) else {}
        order_flow = ctx.get("order_flow", {}) if isinstance(ctx.get("order_flow"), dict) else {}
        volume = ctx.get("volume", {}) if isinstance(ctx.get("volume"), dict) else {}
        oi = ctx.get("oi", {}) if isinstance(ctx.get("oi"), dict) else {}
        pcr = ctx.get("pcr", {}) if isinstance(ctx.get("pcr"), dict) else {}
        vector = self._regime_conviction_vector_from_context(trade_like, ctx)

        signed_intel = self._trade_like_signed_intelligence(trade_like, ctx)
        aligned_intel = self._view_aligned_intel_score(view, signed_intel)
        adverse_intel = max(
            0.0,
            float(getattr(settings, "peak_threat_exit_adverse_intel", 0.55) or 0.55),
        )
        if aligned_intel <= -adverse_intel:
            score += 2
            evidence_domains.add("fresh_intel")
            reasons.append(f"adverse intel {aligned_intel:.2f}")
        elif aligned_intel <= -0.15:
            score += 1
            evidence_domains.add("fresh_intel")
            reasons.append(f"soft adverse intel {aligned_intel:.2f}")

        for label, payload, points in (
            ("aggregate", aggregate, 2),
            ("order-flow", order_flow, 1),
            ("volume", volume, 1),
            ("OI", oi, 2),
            ("PCR", pcr, 1),
        ):
            signal = str(payload.get("signal") or payload.get("bias") or "").upper()
            if not signal:
                continue
            if self._intel_signal_opposes_view(signal, view):
                score += points
                evidence_domains.add("fresh_intel")
                reasons.append(f"{label} {signal} opposes {view}")
            elif self._intel_signal_aligns_view(signal, view):
                reasons.append(f"{label} {signal} supports")
            elif signal in {"HOLD", "NEUTRAL", "MIXED"}:
                # "Unclear" is not "against". These two pillars used to contribute 2 of
                # the 6 points an exit needs, so a merely uninformative tape could carry
                # a third of the case for closing a position on its own.
                if self._setting_enabled(
                    getattr(settings, "peak_threat_exit_neutral_counts", False), False
                ):
                    score += 1 if label in {"aggregate", "order-flow"} else 0
                reasons.append(f"{label} neutral")

        flow_points, flow_reason = Scanner._peak_threat_flow_points(self, trade_like, order_flow, view)
        score += flow_points
        if flow_reason:
            reasons.append(flow_reason)

        volume_ratio = 0.0
        try:
            volume_ratio = float(getattr(trade_like, "volume_ratio", 0.0) or 0.0)
        except Exception:
            volume_ratio = 0.0
        if volume_ratio <= 0.0:
            for key in ("display_volume_ratio", "relative_volume_ratio", "volume_ratio", "buy_sell_ratio"):
                try:
                    volume_ratio = float(volume.get(key, 0.0) or 0.0)
                except Exception:
                    volume_ratio = 0.0
                if volume_ratio > 0:
                    break
        weak_volume = max(
            0.0,
            float(getattr(settings, "peak_threat_exit_weak_volume_ratio", 1.05) or 1.05),
        )
        if 0.0 < volume_ratio < weak_volume:
            score += 1
            reasons.append(f"weak volume {volume_ratio:.2f}x")

        if view == "LONG":
            adverse_prob = max(
                float(vector.get("trend_down_prob", 0.0) or 0.0),
                float(vector.get("breakout_down_prob", 0.0) or 0.0),
            )
        else:
            adverse_prob = max(
                float(vector.get("trend_up_prob", 0.0) or 0.0),
                float(vector.get("breakout_up_prob", 0.0) or 0.0),
            )
        reversal_prob = float(vector.get("reversal_prob", 0.0) or 0.0)
        if adverse_prob >= 0.55 or reversal_prob >= 0.65:
            score += 2
            evidence_domains.add("regime")
            reasons.append(f"regime vector adverse {adverse_prob:.2f}/reversal {reversal_prob:.2f}")

        verdict = str(getattr(trade_like, "price_action_verdict", "") or "").upper()
        try:
            pa_score = float(getattr(trade_like, "price_action_score", 0.0) or 0.0)
        except Exception:
            pa_score = 0.0
        if verdict == "ADVERSE":
            score += 1
            reasons.append("price action adverse")
        elif pa_score <= float(getattr(settings, "price_action_adverse_threshold", -0.50) or -0.50):
            score += 1
            reasons.append(f"price-action score {pa_score:.2f}")

        if not loss_mode and peak > 0:
            if retention <= 0.80:
                score += 2
                reasons.append(f"premium fade {retention:.0%}")
            elif retention <= 0.90:
                score += 1
                reasons.append(f"early premium fade {retention:.0%}")

        if latest_time is not None and self._eod_protect_active(latest_time):
            score += 1
            reasons.append("EOD pressure")

        if loss_mode:
            min_score = max(1, int(getattr(settings, "peak_threat_exit_loss_min_score", 6) or 6))
            # ── domain breadth, with price mandatory ──────────────────────────
            # A score alone cannot distinguish "the tape broke" from "five soft intel
            # votes agree it might". Cutting a live position is a price decision, so
            # price evidence is required and at least one other domain must corroborate.
            min_domains = max(
                1, int(getattr(settings, "peak_threat_exit_loss_min_domains", 2) or 2)
            )
            domains_ready = "price" in evidence_domains and len(evidence_domains) >= min_domains
            if score < min_score or not domains_ready:
                self._clear_loss_threat_confirmation(trade_like)
                return False, "", (
                    f"loss threat score {score}/{min_score}, domains "
                    f"{len(evidence_domains)}/{min_domains}"
                    + ("" if "price" in evidence_domains else " (no price evidence)")
                    + "; " + "; ".join(dict.fromkeys(reasons))
                )

            # ── the same evidence, twice, on a clock that actually moved ──────
            # Scanner cycles can run several times against one market timestamp, so
            # counting calls would manufacture persistence. The observation clock must
            # advance, and the SIGNATURE (which domains spoke) must match — a different
            # mix of evidence restarts the count rather than completing it.
            try:
                latest_aware = (
                    latest_time
                    if getattr(latest_time, "tzinfo", None) is not None
                    else IST.localize(latest_time)
                )
                observation_ts = float(latest_aware.timestamp())
            except Exception:
                self._clear_loss_threat_confirmation(trade_like)
                return False, "", "loss threat awaiting a valid confirmation clock"

            confirm_seconds = max(
                0.0,
                float(getattr(settings, "peak_threat_exit_loss_confirm_seconds", 3.0) or 0.0),
            )
            signature = tuple(sorted(evidence_domains))
            confirmation = getattr(trade_like, "_loss_threat_confirmation", None)
            if (
                not isinstance(confirmation, dict)
                or tuple(confirmation.get("signature", ())) != signature
            ):
                setattr(
                    trade_like,
                    "_loss_threat_confirmation",
                    {"signature": signature, "first_at": observation_ts, "last_at": observation_ts},
                )
                if confirm_seconds > 0:
                    return False, "", (
                        f"loss threat confirmation 1/2; score {score}; domains "
                        f"{','.join(signature)}; adverse Rs.{abs(current_pnl):.0f}"
                    )
            else:
                first_at = float(confirmation.get("first_at", observation_ts) or observation_ts)
                last_at = float(confirmation.get("last_at", first_at) or first_at)
                if confirm_seconds > 0 and (
                    observation_ts <= last_at or observation_ts - first_at < confirm_seconds
                ):
                    confirmation["last_at"] = max(last_at, observation_ts)
                    return False, "", (
                        f"loss threat confirming {max(0.0, observation_ts - first_at):.1f}s/"
                        f"{confirm_seconds:.1f}s; score {score}; domains {','.join(signature)}"
                    )

            self._clear_loss_threat_confirmation(trade_like)
            return True, "LOSS_THREAT_EXIT", (
                f"confirmed threat score {score}>={min_score}; domains "
                f"{','.join(signature)}; adverse Rs.{abs(current_pnl):.0f}; "
                + "; ".join(dict.fromkeys(reasons))
            )

        base_score = max(1, int(getattr(settings, "peak_threat_exit_min_score", 5) or 5))
        severe_score = max(1, int(getattr(settings, "peak_threat_exit_severe_score", 4) or 4))
        required = severe_score if severe and retention >= 0.90 else base_score
        if score >= required:
            # Same two-observation rule the loss branch above already applies. A
            # winner is not cut on one tick's reading of the tape.
            confirmed, confirm_detail = self._exit_confirmation_ready(
                trade_like,
                "_peak_threat_confirmation",
                tuple(sorted(evidence_domains)),
                latest_time,
                float(getattr(settings, "peak_threat_exit_confirm_seconds", 5.0) or 5.0),
            )
            if not confirmed:
                return False, "", (
                    f"near-peak threat {confirm_detail}; score {score}>={required}; "
                    f"retained {retention:.0%}"
                )
            return True, "PEAK_THREAT_EXIT", (
                f"near-peak threat score {score}>={required}; retained {retention:.0%} "
                f"of peak Rs.{peak:.0f}, current Rs.{current_pnl:.0f}; "
                + "; ".join(dict.fromkeys(reasons))
            )
        Scanner._clear_exit_confirmation(trade_like, "_peak_threat_confirmation")
        return False, "", (
            f"peak threat score {score}<{required}; retained {retention:.0%}; "
            + "; ".join(dict.fromkeys(reasons))
        )

    def _confirmed_trend_runner(
        self, trade_like, *, regime: str, peak_pnl: float, initial_risk_rs: float
    ) -> bool:
        """A with-trend PROVEN winner in a confirmed strong-trend regime rides the
        runner lock (10% give-back) rather than the tighter give-back guard. Requires
        the feature enabled, a genuine trend regime, the trade aligned WITH the trend,
        and a peak that already cleared the arming R-multiple (so a small blip cannot
        promote a chop trade into runner mode). The caller still preserves EOD and
        unconfirmed-repaint protection."""
        settings = get_settings()
        if not self._setting_enabled(
            getattr(settings, "trend_runner_let_winners_run_enabled", True), True
        ):
            return False
        reg = str(regime or "").upper()
        if reg not in {"TRENDING_UP", "TRENDING_DOWN", "BREAKOUT_UP", "BREAKOUT_DOWN"}:
            return False
        # Never grant runner mode on a BORROWED regime. _get_trade_regime falls back to
        # the 5-minute label for any timeframe, so a 15-minute trade could otherwise ride
        # the looser runner trail on a 5-minute reading — and sampled 5m/15m regimes
        # disagree in 83% of same-timestamp pairs. Deny rather than assume; the tighter
        # give-back ladder still protects the trade.
        if self._setting_enabled(
            getattr(settings, "trend_runner_require_own_timeframe_regime", True), True
        ) and not self._trade_regime_is_own_timeframe(trade_like):
            return False
        sig = self._trade_signal_type_for_cascade(trade_like)
        if sig == "BUY" and not reg.endswith("_UP"):
            return False
        if sig == "SELL" and not reg.endswith("_DOWN"):
            return False
        if sig not in {"BUY", "SELL"}:
            return False
        risk = float(initial_risk_rs or 0.0)
        if risk <= 0:
            return False
        min_r = float(getattr(settings, "trend_runner_min_peak_r_multiple", 1.0) or 1.0)
        return float(peak_pnl or 0.0) >= min_r * risk

    def _dynamic_runner_lock_pct(self, base_pct: float, regime: str) -> float:
        """Flex the runner profit-lock with volatility/regime: give a trending premium
        MORE room in fast/volatile tape (lock the looser high-vol pct) so noise does not
        shake the runner out, and tighten toward the base lock in calm regimes. Bounded
        [0.25, 0.98]; returns the base lock unchanged when disabled."""
        settings = get_settings()
        try:
            base = float(base_pct or 0.90)
        except Exception:
            base = 0.90
        base = min(0.98, max(0.25, base))
        if not self._setting_enabled(
            getattr(settings, "trend_runner_dynamic_lock_enabled", True), True
        ):
            return base
        reg = str(regime or "").upper()
        if reg in {"VOLATILE", "BREAKOUT_UP", "BREAKOUT_DOWN"}:
            loose = float(getattr(settings, "trend_runner_lock_pct_high_vol", 0.85) or 0.85)
            return min(0.98, max(0.25, min(base, loose)))
        return base

    @staticmethod
    def _trade_gain_in_r(trade_like, current_move_pts: float) -> float:
        """Current favourable move expressed as a multiple of the trade's INITIAL risk
        (entry->initial stop), in the trade's own price space (premium for OPT, spot for
        FUT). 0 when risk is unknown."""
        entry = float(
            getattr(trade_like, "entry_price", 0.0)
            or getattr(trade_like, "price", 0.0)
            or 0.0
        )
        istop = float(
            getattr(trade_like, "initial_stop", 0.0)
            or getattr(trade_like, "trailing_stop", 0.0)
            or 0.0
        )
        risk = abs(entry - istop)
        if risk <= 0:
            return 0.0
        return max(0.0, float(current_move_pts or 0.0)) / risk

    def _big_move_expected(self, trade_like, *, gain_r: float, regime: str) -> Tuple[bool, str]:
        """Decide whether to RIDE a winner for a bigger move vs bank a small gain.

        The ride (and, later, the pullback hedge) must NEVER engage on a small gain — a
        few % of R makes no sense to hedge. It engages ONLY when: the gain has already
        proven itself (>= trend_runner_min_peak_r_multiple x R), the position is WITH a
        confirmed strong-trend regime, and trend strength (ADX) says the move still has
        room. Everything else falls through to normal profit-taking / exit-and-re-enter."""
        settings = get_settings()
        if not self._setting_enabled(
            getattr(settings, "trend_runner_let_winners_run_enabled", True), True
        ):
            return False, "disabled"
        try:
            gr = float(gain_r or 0.0)
        except Exception:
            gr = 0.0
        min_r = float(getattr(settings, "trend_runner_min_peak_r_multiple", 1.0) or 1.0)
        if gr < min_r:
            return False, f"gain {gr:.2f}R < {min_r:.2f}R (small move — bank it)"
        reg = str(regime or "").upper()
        if reg not in {"TRENDING_UP", "TRENDING_DOWN", "BREAKOUT_UP", "BREAKOUT_DOWN"}:
            return False, f"regime {reg or 'unknown'} not a confirmed trend"
        sig = self._trade_signal_type_for_cascade(trade_like)
        if sig == "BUY" and not reg.endswith("_UP"):
            return False, "counter-trend"
        if sig == "SELL" and not reg.endswith("_DOWN"):
            return False, "counter-trend"
        if sig not in {"BUY", "SELL"}:
            return False, "no directional bias"
        adx = float(getattr(trade_like, "adx_value", 0.0) or 0.0)
        min_adx = float(getattr(settings, "trend_runner_big_move_min_adx", 25.0) or 0.0)
        # Only block when ADX is KNOWN and weak; unknown ADX (0) does not veto.
        if min_adx > 0 and adx > 0 and adx < min_adx:
            return False, f"ADX {adx:.1f} < {min_adx:.1f} (move losing strength)"
        return True, f"{reg} {gr:.2f}R adx={adx:.1f}: ride for bigger move"

    def _pullback_hedge_arm(
        self,
        trade_like,
        *,
        current_premium: float,
        peak_premium: float,
        gain_r: float,
        regime: str,
        hedges_used: int = 0,
        runner_stop: float = 0.0,
    ) -> Tuple[bool, str]:
        """Arm a FRESH-ATM opposite leg when a riding runner starts pulling back.

        Only a proven big-move runner (>= the 0.4R crossover, with-trend, strong ADX)
        can hedge — a small gain must never pay two premiums. The hedge is armed EARLY
        (a few % off peak, before the runner lock's give-back would trigger) so it
        captures the pullback the lock otherwise concedes."""
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "pullback_hedge_enabled", False), False):
            return False, "disabled"
        # Options only: an opposite OPTION leg keeps an OPT-locked book pure and has
        # defined risk. A futures hedge would add margin/short exposure — out of scope.
        if str(getattr(trade_like, "inst_type", "") or "").upper() != "OPT":
            return False, "hedge supported for OPT only"
        max_hedges = int(getattr(settings, "pullback_hedge_max_per_trade", 2) or 2)
        if int(hedges_used or 0) >= max_hedges:
            return False, f"hedge cap {max_hedges} reached"
        big_ok, big_reason = self._big_move_expected(trade_like, gain_r=gain_r, regime=regime)
        if not big_ok:
            return False, f"not a hedgeable runner ({big_reason})"
        peak = float(peak_premium or 0.0)
        cur = float(current_premium or 0.0)
        if peak <= 0 or cur <= 0:
            return False, "premium unavailable"
        retrace = peak - cur
        giveback_pct = retrace / peak * 100.0
        # Primary trigger: fraction of the peak->runner-stop distance already retraced.
        # This always arms BEFORE the parent's lock exits (a fixed premium % cannot —
        # the lock sits only ~4-5% below peak).
        stop_px = float(runner_stop or 0.0)
        if stop_px > 0 and peak > stop_px:
            frac_needed = float(
                getattr(settings, "pullback_hedge_trigger_lock_fraction", 0.5) or 0.5
            )
            frac_done = retrace / (peak - stop_px)
            if frac_done < frac_needed:
                return False, (
                    f"pullback {frac_done:.0%} of lock distance < {frac_needed:.0%}"
                )
        else:
            return False, "runner stop unavailable"
        floor_pct = float(getattr(settings, "pullback_hedge_trigger_giveback_pct", 0.0) or 0.0)
        if floor_pct > 0 and giveback_pct < floor_pct:
            return False, f"pullback {giveback_pct:.1f}% < floor {floor_pct:.1f}%"
        return True, f"pullback {giveback_pct:.1f}% off peak {peak:.2f}: arm fresh-ATM hedge"

    def _pullback_hedge_release(
        self,
        *,
        current_premium: float,
        peak_premium: float,
        pullback_low: float,
        minutes_held: float = 0.0,
    ) -> Tuple[bool, str]:
        """Release the hedge once the move RESUMES (so the runner keeps riding), or the
        hold cap expires. The parent exiting also closes the hedge — enforced by the
        caller so a hedge can never outlive its parent as a naked leg."""
        settings = get_settings()
        cap = float(getattr(settings, "pullback_hedge_max_hold_minutes", 15.0) or 15.0)
        if cap > 0 and float(minutes_held or 0.0) >= cap:
            return True, f"hedge hold cap {cap:.0f}m reached"
        peak = float(peak_premium or 0.0)
        low = float(pullback_low or 0.0)
        cur = float(current_premium or 0.0)
        depth = peak - low
        if depth <= 0 or cur <= 0:
            return False, "no measurable pullback yet"
        recovered_pct = (cur - low) / depth * 100.0
        need = float(getattr(settings, "pullback_hedge_resume_recovery_pct", 50.0) or 50.0)
        if recovered_pct >= need:
            return True, f"move resumed ({recovered_pct:.0f}% of pullback recovered): release hedge"
        return False, f"pullback intact ({recovered_pct:.0f}% recovered < {need:.0f}%)"

    def _peak_giveback_or_reversal_exit(
        self,
        trade_like,
        *,
        current_pnl_rs: float,
        peak_pnl: float,
        initial_risk_rs: float,
        smart_min_peak: float,
        latest_time,
        regime: str,
        inst_type: str,
        option_type: str,
        direction: str,
    ) -> Tuple[bool, str, str]:
        """Profit guards that catch a fading winner the tiered lock misses.
        Both are SPECIAL-case (they do not fire on a normal trade's routine pullback):
        (1) sub-1R give-back guard — only near square-off or on a scalp/late entry;
        (2) live regime-reversal profit-taker — own-instrument OR a broad cross-index
        reversal against the position. A trade that already proved a meaningful peak
        is allowed to exit at a small loss if it round-trips through breakeven; the
        full hard stop should not own that late failure."""
        settings = get_settings()
        view = self._trade_direction_view(
            trade_like,
            inst_type=inst_type,
            option_type=option_type,
            direction=direction,
        )
        # (1) Sub-1R give-back guard — SPECIAL contexts only. A normal (non-scalp,
        # not-near-EOD) trade keeps let-winners-run below the 1R lock arm; only a
        # scalp/late entry or the square-off window arms this blunt protection.
        if self._setting_enabled(getattr(settings, "profit_giveback_guard_enabled", True), True):
            special_only = self._setting_enabled(
                getattr(settings, "profit_giveback_guard_special_only", True), True
            )
            special = self._eod_protect_active(latest_time) or bool(
                getattr(trade_like, "scalp_lock_mode", False)
            )
            # An intracandle entry whose repaint check has not yet passed is
            # structurally unconfirmed — let-winners-run does not apply to it, so
            # peak give-back protection arms during that window (2026-07-02: a
            # 990-peak trade faded negative before its repaint abort fired).
            repaint_window = (
                self._setting_enabled(
                    getattr(settings, "repaint_window_giveback_guard_enabled", True), True
                )
                and bool(getattr(trade_like, "entered_intracandle", False))
                and not bool(getattr(trade_like, "repaint_guard_checked", False))
            )
            # Non-trend session phase: chop round-trips are the norm, so every
            # trade gets give-back protection at the lower non-trend arm.
            # Confirmed trend days keep full let-winners-run (2026-07-03: four
            # sub-0.5R peaks rode to full stops on a MIXED day).
            nontrend_scope = False
            if (
                not special
                and not repaint_window
                and special_only
                and self._setting_enabled(
                    getattr(settings, "profit_giveback_nontrend_all_trades", True), True
                )
            ):
                day_type = self._current_day_type(getattr(trade_like, "instrument", ""))
                nontrend_scope = day_type not in {"TREND_DAY_UP", "TREND_DAY_DOWN"}
            # Confirmed live trend keeps let-winners-run even when the session day-type
            # classifier lags or scalp-lock was armed (2026-07-24: strong-ADX trends
            # mislabelled RANGE_DAY armed the give-back and cut winners ~70%). A with-
            # trend proven winner rides the runner lock only. EOD and unconfirmed-repaint
            # protection are still applied and are never suppressed here.
            trend_runner_active = (
                self._confirmed_trend_runner(
                    trade_like,
                    regime=regime,
                    peak_pnl=peak_pnl,
                    initial_risk_rs=initial_risk_rs,
                )
                and not (latest_time is not None and self._eod_protect_active(latest_time))
                and not repaint_window
            )
            if (
                special or repaint_window or nontrend_scope or not special_only
            ) and not trend_runner_active:
                gb_arm = self._profit_giveback_arm(
                    initial_risk_rs, now=latest_time, nontrend_scope=nontrend_scope,
                    trade_like=trade_like,
                )
                base_gb_ratio = float(getattr(settings, "profit_giveback_exit_ratio", 0.50) or 0.50)
                gb_ratio, gb_ratio_context = self._eod_profit_giveback_ratio(
                    trade_like,
                    base_ratio=base_gb_ratio,
                    view=view,
                    latest_time=latest_time,
                    regime=regime,
                )
                if (
                    peak_pnl >= gb_arm
                    and peak_pnl < float(smart_min_peak or 0.0)
                    and current_pnl_rs <= peak_pnl * gb_ratio
                ):
                    reason = (
                        "REPAINT_GIVEBACK_GUARD"
                        if repaint_window and not special and special_only
                        else "PROFIT_GIVEBACK_GUARD"
                    )
                    return True, reason, (
                        f"peak Rs.{peak_pnl:.0f} faded to Rs.{current_pnl_rs:.0f} "
                        f"(arm Rs.{gb_arm:.0f}, keep >= {gb_ratio:.0%}; {gb_ratio_context})"
                    )
        # (2) Live regime-reversal profit-taker: an open, profitable, fading trade
        # whose OWN instrument regime has flipped against it, OR whose peer indices
        # (post-entry cross-index read) have broadly turned against it.
        if (
            self._setting_enabled(getattr(settings, "live_reversal_exit_enabled", True), True)
            and current_pnl_rs > 0.0
        ):
            base = str(getattr(trade_like, "instrument", "") or "").split()[0]
            try:
                live_regime = (getattr(self, "latest_regimes", {}) or {}).get(base)
            except Exception:
                live_regime = None
            # Same precedence fix as _live_direction_context: the trade's OWN timeframe
            # wins. latest_regimes is instrument-keyed and written on the 5-minute pass,
            # so reading it first let a 5-minute flip fire LIVE_REVERSAL_EXIT against a
            # profitable 15-minute position its own chart still supported.
            live_regime = regime or live_regime
            rev_arm = self._profit_giveback_arm(
                initial_risk_rs, now=latest_time, trade_like=trade_like
            )
            fade_ratio = float(getattr(settings, "live_reversal_exit_fade_ratio", 0.85) or 0.85)
            if peak_pnl >= rev_arm and current_pnl_rs < peak_pnl * fade_ratio:
                if self._regime_opposes_direction(view, live_regime):
                    return True, "LIVE_REVERSAL_EXIT", (
                        f"live regime {live_regime} opposes {view}; peak Rs.{peak_pnl:.0f} "
                        f"-> Rs.{current_pnl_rs:.0f}"
                    )
                if self._setting_enabled(
                    getattr(settings, "cross_index_reversal_exit_enabled", True), True
                ):
                    cross_opp, _, cross_peers = self._cross_index_reversal_against(view, base)
                    min_opp = int(getattr(settings, "cross_index_reversal_min_opposing", 2) or 2)
                    if cross_peers > 0 and cross_opp >= min_opp:
                        return True, "CROSS_INDEX_REVERSAL_EXIT", (
                            f"{cross_opp}/{cross_peers} peer indices oppose {view}; peak "
                            f"Rs.{peak_pnl:.0f} -> Rs.{current_pnl_rs:.0f}"
                        )
        return False, "", ""

    def _eod_loss_minimize_exit(
        self,
        trade_like,
        *,
        current_pnl_rs: float,
        initial_risk_rs: float,
        latest_time,
        regime: str = "",
    ) -> Tuple[bool, str]:
        """Late-session losing-trade guard.

        Winners use the peak/giveback guards above. Losers need a different rule:
        inside the final runway, remember the best reduced-loss mark and exit if the
        trade reaches near-breakeven, starts giving that reduced loss back, or has
        only a few minutes left before square-off.
        """
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "eod_loss_minimize_enabled", True), True):
            return False, "disabled"
        if latest_time is None or float(current_pnl_rs or 0.0) >= 0.0:
            return False, "not losing"

        mins = self._minutes_to_force_exit(latest_time)
        window = max(0.0, float(getattr(settings, "eod_loss_minimize_window_minutes", 20.0) or 20.0))
        if mins < 0.0 or mins > window:
            return False, f"outside EOD loss window ({mins:.1f}m)"

        entry_time = getattr(trade_like, "entry_time", None) or getattr(trade_like, "signal_timestamp", None)
        if entry_time is not None:
            try:
                entry_check = (
                    entry_time.astimezone(IST).replace(tzinfo=None)
                    if getattr(entry_time, "tzinfo", None) is not None
                    else entry_time
                )
                now_check = (
                    latest_time.astimezone(IST).replace(tzinfo=None)
                    if getattr(latest_time, "tzinfo", None) is not None
                    else latest_time
                )
                min_age = max(0.0, float(getattr(settings, "eod_loss_minimize_min_age_minutes", 3.0) or 3.0))
                age_minutes = max(0.0, (now_check - entry_check).total_seconds() / 60.0)
                if age_minutes < min_age:
                    return False, f"age {age_minutes:.1f}m below {min_age:.1f}m"
            except Exception:
                pass

        risk = abs(float(initial_risk_rs or 0.0))
        current = float(current_pnl_rs or 0.0)
        view = self._trade_direction_view(trade_like)
        ctx = self._live_direction_context(
            trade_like,
            view,
            str(regime or getattr(trade_like, "market_regime", "") or ""),
        )
        loss_r = abs(current) / risk if risk > 0 else 0.0
        prior_best = getattr(trade_like, "_eod_loss_best_pnl", None)
        try:
            best = float(prior_best)
        except (TypeError, ValueError):
            best = current
        if current > best:
            best = current
            try:
                setattr(trade_like, "_eod_loss_best_pnl", best)
            except Exception:
                pass
        elif prior_best is None:
            try:
                setattr(trade_like, "_eod_loss_best_pnl", best)
            except Exception:
                pass

        near_be = max(0.0, float(getattr(settings, "eod_loss_minimize_near_breakeven_rs", 250.0) or 250.0))
        if abs(current) <= near_be:
            return True, f"EOD reduced-loss exit near breakeven Rs.{current:.0f} (<= Rs.{near_be:.0f})"

        hard_minutes = max(0.0, float(getattr(settings, "eod_loss_minimize_hard_exit_minutes", 5.0) or 5.0))
        max_hard_minutes = max(
            hard_minutes,
            float(getattr(settings, "eod_loss_minimize_max_hard_exit_minutes", 10.0) or 10.0),
        )
        material_loss_r = max(
            0.0,
            float(getattr(settings, "eod_loss_minimize_material_loss_r", 0.45) or 0.45),
        )
        severe_loss_r = max(
            material_loss_r,
            float(getattr(settings, "eod_loss_minimize_severe_loss_r", 0.75) or 0.75),
        )
        hard_basis = []
        if ctx.get("adverse"):
            hard_minutes = max(hard_minutes, min(max_hard_minutes, hard_minutes + 3.0))
            hard_basis.append(
                f"adverse context regime={ctx.get('live_regime')} peers {ctx.get('cross_opp')}/{ctx.get('cross_peers')}"
            )
        if loss_r >= severe_loss_r:
            hard_minutes = max_hard_minutes
            hard_basis.append(f"severe loss {loss_r:.2f}R")
        elif loss_r >= material_loss_r:
            hard_minutes = max(hard_minutes, min(max_hard_minutes, hard_minutes + 2.0))
            hard_basis.append(f"material loss {loss_r:.2f}R")
        if ctx.get("supportive") and loss_r < material_loss_r:
            hard_minutes = min(
                hard_minutes,
                max(0.0, float(getattr(settings, "eod_loss_minimize_hard_exit_minutes", 5.0) or 5.0)),
            )
            hard_basis.append(f"supportive context regime={ctx.get('live_regime')}")
        if mins <= hard_minutes:
            basis = "; ".join(hard_basis) if hard_basis else "base"
            return True, (
                f"EOD adaptive runway {mins:.1f}m <= {hard_minutes:.1f}m; "
                f"closing loser Rs.{current:.0f} ({basis})"
            )

        giveback_abs = max(0.0, float(getattr(settings, "eod_loss_minimize_giveback_rs", 250.0) or 250.0))
        giveback_r = max(
            0.0,
            float(getattr(settings, "eod_loss_minimize_giveback_r_multiple", 0.12) or 0.12),
        )
        giveback_threshold = max(giveback_abs, risk * giveback_r) if risk > 0 else giveback_abs
        deterioration = max(0.0, best - current)
        if best < 0.0 and deterioration >= giveback_threshold:
            return True, (
                f"EOD loss-minimize: best Rs.{best:.0f} worsened to Rs.{current:.0f} "
                f"(giveback Rs.{deterioration:.0f} >= Rs.{giveback_threshold:.0f})"
            )

        return False, (
            f"EOD loss watch: Rs.{current:.0f}, best Rs.{best:.0f}, "
            f"{mins:.1f}m left"
        )

    def _loss_recovery_watch_decision(
        self,
        trade_like,
        *,
        current_price: float,
        current_pnl_rs: float,
        peak_pnl: float,
        initial_risk_rs: float,
        latest_time,
        regime: str = "",
        proposed_exit_reason: str = "",
    ) -> Tuple[str, str]:
        """Track a former winner that briefly slips negative inside normal noise.

        Returns:
          HOLD - keep monitoring with a virtual reduced-loss trail.
          EXIT - close now with RECOVERY_WATCH_EXIT.
          NONE - not eligible; let the normal guard/stop proceed.
        """
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "loss_recovery_watch_enabled", True), True):
            return "NONE", "disabled"
        if latest_time is None:
            return "NONE", "missing time"
        if self._eod_protect_active(latest_time):
            return "NONE", "EOD guard owns final runway"

        current_pnl = float(current_pnl_rs or 0.0)
        peak = float(peak_pnl or 0.0)
        risk = abs(float(initial_risk_rs or 0.0))
        if current_pnl >= 0.0:
            for attr in (
                "_loss_recovery_watch_started_at",
                "_loss_recovery_best_pnl",
                "_loss_recovery_worst_pnl",
                "_loss_recovery_floor_pnl",
            ):
                try:
                    setattr(trade_like, attr, None)
                except Exception:
                    pass
            return "NONE", "trade recovered non-negative"

        min_peak = max(
            float(getattr(settings, "loss_recovery_watch_min_peak_rs", 500.0) or 500.0),
            risk * float(getattr(settings, "loss_recovery_watch_min_peak_r", 0.25) or 0.25),
        )
        if peak < min_peak:
            return "NONE", f"peak Rs.{peak:.0f} below recovery arm Rs.{min_peak:.0f}"

        max_loss_r = max(0.05, float(getattr(settings, "loss_recovery_watch_max_loss_r", 0.45) or 0.45))
        max_loss_rs_r = risk * max_loss_r if risk > 0 else 0.0
        # Former-winner rupee breathing: allow -500..-700 when trend holds even if
        # R-cap is tighter (wide option risk made R-caps too loose/too tight).
        max_loss_rs_abs = max(
            0.0,
            float(getattr(settings, "loss_recovery_watch_max_loss_rs", 700.0) or 700.0),
        )
        soft_loss_rs = max(
            0.0,
            float(getattr(settings, "loss_recovery_watch_soft_loss_rs", 500.0) or 500.0),
        )
        if max_loss_rs_r > 0 and max_loss_rs_abs > 0:
            max_loss_rs = min(max_loss_rs_r, max_loss_rs_abs)
        elif max_loss_rs_abs > 0:
            max_loss_rs = max_loss_rs_abs
        else:
            max_loss_rs = max_loss_rs_r if max_loss_rs_r > 0 else abs(current_pnl)
        # Soft band 0..-500: always eligible for hold if other checks pass.
        # Hard breathing edge -700: beyond this recovery cannot HOLD.
        if abs(current_pnl) > max_loss_rs and max_loss_rs > 0:
            if getattr(trade_like, "_loss_recovery_watch_started_at", None) is not None:
                return "EXIT", (
                    f"recovery loss Rs.{current_pnl:.0f} beyond breathing cap "
                    f"Rs.{max_loss_rs:.0f} (soft Rs.{soft_loss_rs:.0f})"
                )
            return "NONE", f"loss Rs.{current_pnl:.0f} beyond recovery cap Rs.{max_loss_rs:.0f}"

        entry = float(getattr(trade_like, "price", getattr(trade_like, "entry_price", 0.0)) or 0.0)
        current = float(current_price or 0.0)
        qty = max(
            1,
            int(getattr(trade_like, "lots", 1) or 1)
            * int(getattr(trade_like, "lot_size", getattr(trade_like, "quantity", 1)) or 1),
        )
        if entry <= 0 or current <= 0:
            return "NONE", "missing entry/current price"

        inst_type = str(getattr(trade_like, "inst_type", "") or "").upper()
        if inst_type == "OPT":
            breathing = self._option_breathing_distance(trade_like, regime=regime, entry_price=entry)
            breathing_mult = max(
                0.25,
                float(getattr(settings, "loss_recovery_watch_breathing_mult", 1.0) or 1.0),
            )
            adverse_points = max(0.0, entry - current)
            if breathing <= 0 or adverse_points > breathing * breathing_mult:
                if getattr(trade_like, "_loss_recovery_watch_started_at", None) is not None:
                    return "EXIT", (
                        f"premium loss {adverse_points:.2f} broke recovery breathing "
                        f"{breathing * breathing_mult:.2f}"
                    )
                return "NONE", (
                    f"premium loss {adverse_points:.2f} outside recovery breathing "
                    f"{breathing * breathing_mult:.2f}"
                )

        context_price = current
        try:
            spot = float(self.candles.get_latest_price(getattr(trade_like, "instrument", "")) or 0.0)
            if spot > 0:
                context_price = spot
        except Exception:
            pass
        context = self._profit_guard_reversal_context(
            trade_like,
            context_price,
            latest_time,
            timeframe=getattr(trade_like, "timeframe", "5min"),
        )
        if not context.get("has_context"):
            return "NONE", context.get("reason", "missing support context")
        if context.get("fast_reversal"):
            if getattr(trade_like, "_loss_recovery_watch_started_at", None) is not None:
                return "EXIT", f"recovery failed: fast adverse reversal ({context.get('reason')})"
            return "NONE", f"fast adverse reversal ({context.get('reason')})"
        if not context.get("trend_supportive"):
            if getattr(trade_like, "_loss_recovery_watch_started_at", None) is not None:
                return "EXIT", f"recovery support broke ({context.get('reason')})"
            return "NONE", f"support not confirmed ({context.get('reason')})"

        view = self._trade_direction_view(
            trade_like,
            inst_type=inst_type,
            option_type=getattr(trade_like, "option_type", ""),
            direction=getattr(trade_like, "direction", ""),
        )
        try:
            live_ctx = self._live_direction_context(trade_like, view, regime)
        except Exception:
            live_ctx = {}
        if live_ctx.get("adverse"):
            if getattr(trade_like, "_loss_recovery_watch_started_at", None) is not None:
                return "EXIT", f"recovery context adverse: regime={live_ctx.get('live_regime')}"
            return "NONE", f"adverse live context: regime={live_ctx.get('live_regime')}"

        ctx = self._trade_like_market_intelligence_context(trade_like)
        signed_intel = self._trade_like_signed_intelligence(trade_like, ctx)
        aligned_intel = self._view_aligned_intel_score(view, signed_intel)
        adverse_intel = max(
            0.0,
            float(getattr(settings, "loss_recovery_watch_adverse_intel", 0.65) or 0.65),
        )
        if aligned_intel <= -adverse_intel:
            if getattr(trade_like, "_loss_recovery_watch_started_at", None) is not None:
                return "EXIT", f"recovery intel adverse {aligned_intel:.2f}"
            return "NONE", f"adverse intel {aligned_intel:.2f}"

        verdict = str(getattr(trade_like, "price_action_verdict", "") or "").upper()
        try:
            pa_score = float(getattr(trade_like, "price_action_score", 0.0) or 0.0)
        except Exception:
            pa_score = 0.0
        if verdict == "ADVERSE" or pa_score <= float(getattr(settings, "price_action_adverse_threshold", -0.50) or -0.50):
            pa_label = verdict if verdict else f"{pa_score:.2f}"
            if getattr(trade_like, "_loss_recovery_watch_started_at", None) is not None:
                return "EXIT", f"price action support broke ({pa_label})"
            return "NONE", f"price action adverse ({pa_label})"

        started_at = getattr(trade_like, "_loss_recovery_watch_started_at", None)
        if started_at is None:
            started_at = latest_time
            try:
                setattr(trade_like, "_loss_recovery_watch_started_at", started_at)
            except Exception:
                pass
        try:
            best = float(getattr(trade_like, "_loss_recovery_best_pnl", current_pnl))
        except Exception:
            best = current_pnl
        try:
            worst = float(getattr(trade_like, "_loss_recovery_worst_pnl", current_pnl))
        except Exception:
            worst = current_pnl
        best = max(best, current_pnl)
        worst = min(worst, current_pnl)
        giveback = max(
            float(getattr(settings, "loss_recovery_watch_giveback_rs", 250.0) or 250.0),
            risk * float(getattr(settings, "loss_recovery_watch_giveback_r_multiple", 0.10) or 0.10),
        )
        floor = best - giveback
        try:
            setattr(trade_like, "_loss_recovery_best_pnl", best)
            setattr(trade_like, "_loss_recovery_worst_pnl", worst)
            setattr(trade_like, "_loss_recovery_floor_pnl", floor)
        except Exception:
            pass

        try:
            ref = started_at.astimezone(IST).replace(tzinfo=None) if getattr(started_at, "tzinfo", None) is not None else started_at
            now = latest_time.astimezone(IST).replace(tzinfo=None) if getattr(latest_time, "tzinfo", None) is not None else latest_time
            watch_minutes = max(0.0, (now - ref).total_seconds() / 60.0)
        except Exception:
            watch_minutes = 0.0
        max_minutes = max(1.0, float(getattr(settings, "loss_recovery_watch_max_minutes", 8.0) or 8.0))
        if watch_minutes >= max_minutes:
            return "EXIT", (
                f"recovery watch timed out {watch_minutes:.1f}m >= {max_minutes:.1f}m; "
                f"best Rs.{best:.0f}, current Rs.{current_pnl:.0f}"
            )
        if current_pnl <= floor and best > current_pnl:
            return "EXIT", (
                f"recovery reduced-loss trail hit: best Rs.{best:.0f}, "
                f"floor Rs.{floor:.0f}, current Rs.{current_pnl:.0f}"
            )

        basis = str(proposed_exit_reason or "LOSS_RECOVERY_WATCH")
        return "HOLD", (
            f"{basis} deferred: former peak Rs.{peak:.0f} now Rs.{current_pnl:.0f}; "
            f"best Rs.{best:.0f}, trail floor Rs.{floor:.0f}; "
            f"{context.get('reason', 'supportive context')}"
        )

    def _cross_index_reversal_against(self, view: str, base_instrument: str):
        """Post-entry cross-index correlation read: count active peer indices whose
        live regime opposes / aligns with the trade view. Correlation is not assumed
        — peers with a non-directional (ranging/unknown) regime simply do not vote."""
        active = list(getattr(self, "active_indices", []) or []) or [
            "NIFTY", "BANKNIFTY", "SENSEX", "MIDCPNIFTY"
        ]
        regimes = getattr(self, "latest_regimes", {}) or {}
        base = str(base_instrument or "").split()[0].upper()
        aligning_side = "BUY" if str(view or "").upper() == "LONG" else "SELL"
        opposing = aligned = peers = 0
        for inst in active:
            if str(inst).upper() == base:
                continue
            reg = regimes.get(inst)
            if reg is None:
                continue
            peers += 1
            if self._regime_opposes_direction(view, reg):
                opposing += 1
            elif regime_aligns(reg, aligning_side):
                aligned += 1
        return opposing, aligned, peers

    def _late_entry_scalp_active(self, candidate) -> bool:
        """Whether an entry is late enough to force protect-first-profit (Fix 4)."""
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "late_entry_scalp_enabled", True), True):
            return False
        window = float(getattr(settings, "late_entry_scalp_window_minutes", 30.0) or 30.0)
        mins = self._minutes_to_force_exit(getattr(candidate, "signal_timestamp", None))
        return 0.0 <= mins <= window

    def _set_scalp_lock(self, candidate, value: bool) -> None:
        """Set scalp_lock_mode, honoring a late-entry protect-first-profit override."""
        if bool(getattr(candidate, "one_way_cascade_entry", False)):
            setattr(candidate, "scalp_lock_mode", bool(value))
            return
        late = bool(getattr(candidate, "_late_entry_scalp", False))
        special_15m_scalp = bool(getattr(candidate, "fifteen_min_choppy_scalp_entry", False))
        setattr(candidate, "scalp_lock_mode", bool(value) or late or special_15m_scalp)

    def _repaint_abort_held_for_profit(self, candidate, current_price) -> bool:
        """Whether to HOLD a repainted signal instead of force-exiting it, because the
        position is already in profit. On a fast trend the UT signal can flicker/repaint
        while price keeps running our way; aborting a working entry locks a needless
        loss of opportunity. The trade then continues as a normally tracked/stopped row."""
        if not self._setting_enabled(
            getattr(get_settings(), "repaint_abort_skip_when_profitable", True), True
        ):
            return False
        try:
            return self._candidate_gross_pnl(candidate, float(current_price)) > 0
        except Exception:
            return False

    @staticmethod
    def _timeframe_seconds(timeframe: str) -> int:
        tf = str(timeframe or "").lower()
        if tf.endswith("min"):
            try:
                return max(60, int(tf[:-3]) * 60)
            except Exception:
                return 300
        return 300

    def _thrust_scaled_stabilization_seconds(self, candidate, base_seconds: float) -> float:
        """Shorten the stabilization wait when the bar itself is moving hard.

        A flat 30s on a 5-minute candle demands 10% of that candle's life as stillness,
        and the UT1 arrow is least stable exactly when price is moving fastest — so the
        wait is longest precisely where the opportunity is shortest. 2026-08-11: 252
        signals entered the buffer, 48 matured (19%), and 63 of the deaths came inside
        the first two seconds.

        Deliberately a STEP, not a ramp: a proportional scale invites tuning a curve on
        noise, while the question here is binary — is this bar an ordinary drift or a
        thrust? The thresholds reuse the same range/ATR and volume-ratio measures the
        surge gates already run on, so there is one definition of "thrust" in the system.

        Can only ever SHORTEN, never extend, and never below the floor.
        """
        settings = get_settings()
        if not self._setting_enabled(
            getattr(settings, "stabilization_thrust_scaling_enabled", True), True
        ):
            return base_seconds
        try:
            base = float(base_seconds or 0.0)
            floor = float(getattr(settings, "stabilization_thrust_min_seconds", 10.0) or 10.0)
            if base <= floor:
                return base
            range_atr = float(getattr(candidate, "range_atr_ratio", 0.0) or 0.0)
            vol_ratio = float(getattr(candidate, "volume_ratio", 0.0) or 0.0)
            min_range = float(getattr(settings, "stabilization_thrust_range_atr", 1.50) or 1.50)
            min_vol = float(getattr(settings, "stabilization_thrust_volume_ratio", 1.50) or 1.50)
        except (TypeError, ValueError):
            return base_seconds
        # Absent metrics are not evidence of a thrust — the full wait stands.
        thrust = (min_range > 0 and range_atr >= min_range) or (
            min_vol > 0 and vol_ratio >= min_vol
        )
        if not thrust:
            return base
        self._diag_inc("stabilization", "thrust_shortened")
        return max(floor, min(base, floor))

    def _live_signal_stabilization_requirements(self, candidate: TradeCandidate) -> Tuple[float, int, bool]:
        """Return live buffer seconds and stable-scan count before a forming signal may mature."""
        settings = get_settings()
        timeframe = str(getattr(candidate, "timeframe", "") or "")
        if timeframe == "15min":
            base_seconds = float(getattr(settings, "live_signal_stabilization_seconds_15min", 30.0) or 30.0)
        elif timeframe == "5min":
            base_seconds = float(getattr(settings, "live_signal_stabilization_seconds_5min", 30.0) or 30.0)
        else:
            base_seconds = float(getattr(settings, "live_signal_stabilization_seconds", 30.0) or 30.0)
        inst_type = str(getattr(candidate, "inst_type", "") or "").upper()
        # Own-timeframe regime; latest_regimes[instrument] is the 5-minute label.
        regime = self._get_trade_regime(candidate, default="UNKNOWN")
        # Fast 1m chassis (SPIKE and/or pure SNAPBACK): short stable window so the
        # move is not gone before entry. Aggressive buffer default 3s (floor 3 /
        # max 15) with two confirming scans. 5m/15m non-spike keep 30–60s.
        _fast_1m = bool(getattr(candidate, "volume_spike_entry", False)) or bool(
            getattr(candidate, "is_reversion_scalp", False)
        )
        if _fast_1m:
            # Floor/ceiling from settings so advanced UI cannot zero-out repaint
            # protection or set absurd waits. Pure SNAPBACK reuses spike stab
            # knobs (same 1m anti-repaint chassis).
            spike_seconds = float(
                getattr(settings, "volume_spike_entry_stabilization_seconds", 3.0) or 3.0
            )
            spike_min = float(
                getattr(settings, "volume_spike_entry_stabilization_seconds_min", 3.0) or 3.0
            )
            spike_max = float(
                getattr(settings, "volume_spike_entry_stabilization_seconds_max", 15.0) or 15.0
            )
            spike_min = max(1.0, spike_min)
            spike_max = max(spike_min, spike_max)
            return max(spike_min, min(spike_max, spike_seconds)), 2, True
        # Market-wide LTP shock / synchronized reverse: short 5–10s buffer so a
        # multi-index dump/rally can enter before the move is gone.
        if (
            bool(getattr(candidate, "market_ltp_shock_entry", False))
            or bool(getattr(candidate, "market_wide_reversal_entry", False))
            # A one-way cascade is the SAME class of evidence as a market-wide reversal —
            # a synchronised multi-index thrust with breadth and volume behind it — and
            # until 2026-08-11 it drew the full 30s while the reversal drew 8. That
            # difference is the whole of that session: the cascade-confirmed SHORT on the
            # only hour that moved sat in the buffer and died at 13.7s.
            or bool(getattr(candidate, "one_way_cascade_entry", False))
        ):
            shock_seconds = float(
                getattr(settings, "market_ltp_shock_stabilization_seconds", 8.0) or 8.0
            )
            return max(5.0, min(10.0, shock_seconds)), 2, True
        base_seconds = self._thrust_scaled_stabilization_seconds(candidate, base_seconds)
        risky_option = inst_type == "OPT" and is_risky_regime(regime)
        if (
            str(getattr(candidate, "instrument", "") or "").split()[0].upper() == self.MIDCAP_CORRELATED_INDEX
            and timeframe == "15min"
            and risky_option
        ):
            volume_ratio = self._candidate_volume_ratio_for_burst(candidate)
            intel_abs = abs(self._candidate_signed_intelligence(candidate))
            min_volume = float(
                getattr(settings, "midcap_15min_risky_stabilization_min_volume_ratio", 1.05) or 1.05
            )
            min_intel = float(
                getattr(settings, "midcap_15min_risky_stabilization_min_intel_score", 0.25) or 0.25
            )
            weak_volume = volume_ratio <= 0.0 or volume_ratio < min_volume
            weak_intel = intel_abs < min_intel
            if weak_volume or weak_intel:
                seconds = float(
                    getattr(settings, "midcap_15min_risky_stabilization_seconds", 60.0) or 60.0
                )
                scans = max(2, int(getattr(settings, "midcap_15min_risky_stabilization_min_scans", 3) or 3))
                return max(base_seconds, seconds), scans, True
        if timeframe == "5min" and risky_option:
            return max(base_seconds, 30.0), 2, True
        if risky_option:
            return max(base_seconds, 30.0), 1, True
        return base_seconds, 1, False

    @staticmethod
    def _stabilization_ready(
        elapsed: float,
        stable_seconds: float,
        stable_scans: int,
        min_stable_scans: int,
        adaptive_stability: bool,
    ) -> bool:
        """Whether a live signal has completed its anti-repaint buffer.

        Stable scans confirm the signal did not flicker, but they must never shorten
        the operator-configured time buffer for normal 5min/15min entries.
        """
        try:
            elapsed = float(elapsed or 0.0)
            stable_seconds = float(stable_seconds or 0.0)
            stable_scans = int(stable_scans or 0)
            min_stable_scans = max(1, int(min_stable_scans or 1))
        except Exception:
            return False
        if elapsed < stable_seconds:
            return False
        if adaptive_stability:
            return stable_scans >= min_stable_scans
        return True

    @staticmethod
    def _stabilization_preflight_window_seconds(stable_seconds: float) -> float:
        """Read-only preflight opens during the last 10 seconds of stabilization."""
        try:
            stable_seconds = float(stable_seconds or 0.0)
        except Exception:
            stable_seconds = 0.0
        if stable_seconds <= 0.0:
            return 0.0
        return min(10.0, stable_seconds)

    def _stabilization_preflight_fingerprint(self, candidate: TradeCandidate) -> Tuple[Any, ...]:
        """Fingerprint fields that must still match before cached preflight is applied."""

        def clean_ts(value):
            if value is None:
                return ""
            try:
                if getattr(value, "tzinfo", None) is not None:
                    value = value.astimezone(IST).replace(tzinfo=None)
                return value.isoformat(timespec="seconds")
            except Exception:
                return str(value)

        instrument = str(getattr(candidate, "instrument", "") or "").split()[0].upper()
        engines = tuple(str(v) for v in (getattr(candidate, "source_engines", []) or []))
        return (
            instrument,
            str(getattr(candidate, "timeframe", "") or ""),
            str(getattr(candidate, "direction", "") or "").upper(),
            str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper(),
            clean_ts(getattr(candidate, "signal_timestamp", None)),
            clean_ts(getattr(candidate, "source_signal_timestamp", None)),
            str(getattr(candidate, "source_signal_type", "") or ""),
            str(getattr(candidate, "grade", "") or ""),
            round(float(getattr(candidate, "confidence", 0.0) or 0.0), 6),
            str(getattr(candidate, "inst_type", "") or "").upper(),
            str(getattr(candidate, "option_type", "") or "").upper(),
            str(getattr(candidate, "source_engine", "") or ""),
            engines,
            str(getattr(candidate, "source_lane", "") or ""),
            bool(getattr(candidate, "quad_union_entry", False)),
            bool(getattr(candidate, "raw_union_entry", False)),
            bool(getattr(candidate, "volume_spike_entry", False)),
            bool(getattr(candidate, "market_ltp_shock_entry", False)),
            bool(getattr(candidate, "one_way_cascade_entry", False)),
            str(getattr(self, "inst_pref", getattr(get_settings(), "inst_pref", "AUTO")) or "AUTO").upper(),
            str(getattr(self, "latest_regimes", {}).get(instrument, "") or "").upper(),
        )

    def _maybe_prepare_stabilization_preflight(
        self,
        key: str,
        candidate: TradeCandidate,
        elapsed: float,
        stable_seconds: float,
    ) -> bool:
        """Warm static/product work near maturity without touching live trade state."""
        try:
            remaining = float(stable_seconds or 0.0) - float(elapsed or 0.0)
        except Exception:
            return False
        window = self._stabilization_preflight_window_seconds(stable_seconds)
        if window <= 0.0 or remaining > window:
            return False
        if str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper() != "ENTRY":
            return False

        cache = getattr(self, "_signal_preflight_cache", None)
        if not isinstance(cache, dict):
            self._signal_preflight_cache = {}
            cache = self._signal_preflight_cache

        fingerprint = self._stabilization_preflight_fingerprint(candidate)
        cached = cache.get(key)
        if cached and cached.get("fingerprint") == fingerprint:
            return False

        self._diag_inc("stabilization", "preflight_started")
        try:
            prepared = copy.deepcopy(candidate)
            prepared_rows = [prepared]
            prepared_rows = self._apply_strict_instrument_pref_to_entries(prepared_rows)
            prepared_rows = self._resolve_unbuilt_opt_entries(prepared_rows)
            if not prepared_rows:
                return False
            prepared = prepared_rows[0]
            try:
                self._subscribe_candidate_quote(prepared, context="stabilization_preflight")
            except Exception:
                pass
            cache[key] = {
                "fingerprint": fingerprint,
                "candidate": prepared,
                "prepared_at": datetime.now(IST).replace(tzinfo=None),
            }
            self._diag_inc("stabilization", "preflight_ready")
            logger.info(
                f"[STABILIZATION] Preflight ready for {candidate.instrument} "
                f"{candidate.timeframe} {candidate.direction} with {max(0.0, remaining):.1f}s left."
            )
            return True
        except Exception as exc:
            cache.pop(key, None)
            self._diag_inc("stabilization", "preflight_failed")
            logger.debug(f"Stabilization preflight skipped for {key}: {exc}")
            return False

    def _apply_stabilization_preflight(
        self,
        key: str,
        candidate: TradeCandidate,
    ) -> bool:
        """Apply prepared contract/quote fields after the final stability gate passes."""
        cache = getattr(self, "_signal_preflight_cache", {}) or {}
        cached = cache.get(key)
        if not cached:
            return False
        fingerprint = self._stabilization_preflight_fingerprint(candidate)
        if cached.get("fingerprint") != fingerprint:
            self._diag_inc("stabilization", "preflight_cache_stale")
            cache.pop(key, None)
            return False
        prepared = cached.get("candidate")
        if prepared is None:
            cache.pop(key, None)
            return False

        copy_fields = (
            "inst_type",
            "option_type",
            "atm_strike",
            "multiplier",
            "trading_symbol",
            "symbol_token",
            "price",
            "current_price",
            "stop",
            "target",
            "initial_stop",
            "spot_stop",
            "spot_target",
            "entry_spot",
            "lots",
            "lot_size",
            "rr",
            "quote_verified",
            "quote_source",
            "execution_bid_price",
            "execution_ask_price",
            "execution_touch_source",
            "execution_touch_age_seconds",
            "execution_touch_usable",
            "execution_touch_reason",
        )
        for field_name in copy_fields:
            if hasattr(prepared, field_name):
                setattr(candidate, field_name, copy.deepcopy(getattr(prepared, field_name)))

        existing_reasons = list(getattr(candidate, "reasons", []) or [])
        for reason in list(getattr(prepared, "reasons", []) or []):
            if reason not in existing_reasons:
                existing_reasons.append(reason)
        candidate.reasons = existing_reasons
        setattr(candidate, "stabilization_preflight_applied", True)
        self._diag_inc("stabilization", "preflight_cache_hit")
        cache.pop(key, None)
        return True

    def _option_breathing_distance(
        self,
        trade_like,
        regime: str = "",
        entry_price: Optional[float] = None,
        initial_stop: Optional[float] = None,
    ) -> float:
        """Minimum premium-space breathing room before option stops may tighten."""
        if str(getattr(trade_like, "inst_type", "") or "").upper() != "OPT":
            return 0.0
        entry = float(entry_price if entry_price is not None else getattr(trade_like, "price", getattr(trade_like, "entry_price", 0.0)) or 0.0)
        if entry <= 0:
            return 0.0

        if initial_stop is not None:
            try:
                initial = float(initial_stop or 0.0)
            except Exception:
                initial = 0.0
        else:
            initial = self._ensure_trade_like_initial_stop(trade_like)

        if initial > 0 and self._risk_stop_valid(entry, initial, "LONG"):
            initial_risk = abs(entry - initial)
        else:
            try:
                sl_pct = float(getattr(self, "options_sl_pct", getattr(get_settings(), "options_sl_pct", 15.0)) or 15.0)
            except Exception:
                sl_pct = 15.0
            initial_risk = max(entry * (sl_pct / 100.0), entry * 0.08)

        timeframe = str(getattr(trade_like, "timeframe", "") or "").lower()
        risk_fraction = 0.65 if timeframe == "15min" else 0.55
        absolute_floor = max(12.0 if entry >= 100.0 else 3.0, entry * 0.04)
        floor = max(entry * 0.04, initial_risk * risk_fraction, absolute_floor)
        if is_risky_regime(regime):
            floor = max(floor * 1.15, initial_risk * 0.75, entry * 0.06)

        cap = max(entry * 0.08, min(initial_risk * 0.90, entry * 0.18))
        return round(max(0.05, min(floor, cap)), 2)

    def _apply_option_stop_breathing_room(
        self,
        trade_like,
        proposed_stop: float,
        latest_time: Optional[datetime] = None,
        regime: str = "",
        profit_lock_reason: str = "",
    ) -> Tuple[float, float, bool]:
        """Clamp premature option stop tightening so normal premium noise is not treated as failure."""
        if str(getattr(trade_like, "inst_type", "") or "").upper() != "OPT":
            return float(proposed_stop or 0.0), 0.0, False
        stop = float(proposed_stop or 0.0)
        entry = float(getattr(trade_like, "price", getattr(trade_like, "entry_price", 0.0)) or 0.0)
        if entry <= 0 or stop <= 0:
            return stop, 0.0, False

        breathing = self._option_breathing_distance(trade_like, regime=regime, entry_price=entry)
        if breathing <= 0:
            return stop, breathing, False

        qty = int(getattr(trade_like, "lots", 1) or 1) * int(getattr(trade_like, "lot_size", 1) or 1)
        qty = max(1, qty)
        peak_pnl = max(0.0, float(getattr(trade_like, "peak_pnl", 0.0) or 0.0))
        peak_points = peak_pnl / qty
        reason = str(profit_lock_reason or "").upper()
        regime_text = str(regime or getattr(trade_like, "market_regime", "") or "").upper()
        min_bypass_peak, bypass_context = self._choppy_profit_lock_bypass_peak_threshold(
            trade_like,
            regime_text=regime_text,
            latest_time=latest_time,
            entry_price=entry,
            qty=qty,
            peak_pnl=peak_pnl,
        )
        choppy_profit_lock = (
            reason in {"SMART_PROFIT_LOCK", "MAJOR_WIN_GUARD"}
            and stop >= entry
            and bool(getattr(trade_like, "scalp_lock_mode", False))
            and (
                is_risky_regime(regime_text)
                or regime_text in {"RANGING", "CHOPPY", "VOLATILE", "MEAN_REVERTING"}
            )
            and peak_pnl >= min_bypass_peak
        )
        if choppy_profit_lock:
            if getattr(trade_like, "_last_profit_lock_bypass_log", "") != f"{reason}:{min_bypass_peak:.0f}:{int(peak_pnl)}":
                setattr(trade_like, "_last_profit_lock_bypass_log", f"{reason}:{min_bypass_peak:.0f}:{int(peak_pnl)}")
                try:
                    self.log_event(
                        f"Option smart-lock kept for {getattr(trade_like, 'instrument', '')} "
                        f"{getattr(trade_like, 'timeframe', '')}: peak Rs.{peak_pnl:.0f} >= "
                        f"adaptive arm Rs.{min_bypass_peak:.0f} ({bypass_context}).",
                        "info",
                    )
                except Exception:
                    pass
            return stop, breathing, False

        entry_time = getattr(trade_like, "signal_timestamp", getattr(trade_like, "entry_time", None))
        age_seconds = None
        if latest_time is not None and entry_time is not None:
            try:
                ref = entry_time.astimezone(IST).replace(tzinfo=None) if getattr(entry_time, "tzinfo", None) is not None else entry_time
                now = latest_time.astimezone(IST).replace(tzinfo=None) if getattr(latest_time, "tzinfo", None) is not None else latest_time
                age_seconds = max(0.0, (now - ref).total_seconds())
            except Exception:
                age_seconds = None

        maturity_seconds = self._timeframe_seconds(getattr(trade_like, "timeframe", "5min"))
        signal_matured = age_seconds is not None and age_seconds >= maturity_seconds
        proved_move = peak_points >= breathing * 1.8
        max_early_stop = entry - breathing

        # Do not let 5m/15m option rows become petty scalps. A profit-side stop
        # is allowed only after the source move has matured and proved enough
        # premium distance; until then the stop can tighten only inside the
        # original risk room.
        if stop >= entry and peak_pnl > 0 and signal_matured and proved_move:
            return stop, breathing, False
        if stop >= entry and peak_pnl > 0:
            return max(0.05, max_early_stop), breathing, True

        if stop > max_early_stop and not (signal_matured and proved_move):
            return max(0.05, max_early_stop), breathing, True
        return stop, breathing, False

    def _should_defer_option_intel_exit(
        self,
        trade_like,
        current_price: float,
        latest_time: Optional[datetime],
        reason_text: str,
        regime: str = "",
        intel_result: Optional[Dict] = None,
    ) -> Tuple[bool, str]:
        """Debounce intelligence exits for fresh option signals inside normal premium noise."""
        inst_type = str(getattr(trade_like, "inst_type", "") or "").upper()
        if inst_type not in ("OPT", "FUT"):
            return False, ""

        entry = float(getattr(trade_like, "price", getattr(trade_like, "entry_price", 0.0)) or 0.0)
        current = float(current_price or 0.0)
        if entry <= 0 or current <= 0:
            return False, ""

        context_fn = getattr(self, "_profit_guard_reversal_context", None)
        ctx = {}
        if context_fn:
            ctx = context_fn(
                trade_like,
                current,
                latest_time,
                reason_text,
                timeframe=getattr(trade_like, "timeframe", "1min"),
                regime=regime,
                intel_result=intel_result,
            )
        
        has_context = ctx.get("has_context", False)
        trend_supportive = ctx.get("trend_supportive", False)
        ctx_reason = ctx.get("reason", "")

        adverse_points = max(0.0, entry - current)

        if has_context and trend_supportive:
            if "pullback" in ctx_reason.lower() or "noise" in ctx_reason.lower():
                if inst_type == "FUT" and "index noise" in ctx_reason.lower():
                    sl_pct = float(getattr(self, "futures_sl_pct", 0.2))
                    max_adverse = entry * (sl_pct / 100.0)
                    if adverse_points <= max_adverse:
                        return True, f"deferred: normal_noise ({ctx_reason})"

                if inst_type == "OPT" and "pullback" in ctx_reason.lower():
                    peak_pnl = float(getattr(trade_like, "peak_pnl", 0.0))
                    if peak_pnl > 0.0 and current > entry:
                        inst_mult = 1.0
                        qty = int(getattr(trade_like, "lots", 1)) * int(getattr(trade_like, "lot_size", 15))
                        initial_risk = self._trade_like_initial_risk_rs(
                            trade_like,
                            qty=qty,
                            inst_mult=inst_mult,
                        )
                        
                        lock_stop, lock_reason, lock_ratio = getattr(self, "_profit_lock_floor", lambda *a, **k: (0.0, "", 0.0))(
                            entry,
                            "LONG",
                            qty,
                            peak_pnl,
                            bool(getattr(trade_like, "scalp_lock_mode", False)),
                            inst_mult,
                            initial_risk,
                            getattr(trade_like, "timeframe", ""),
                        )
                        
                        if lock_stop > 0.0 and current <= lock_stop:
                            # broken the floor, do not defer
                            return False, ""
                        else:
                            return True, "deferred: protected profit room"
                    
                    breathing = getattr(self, "_option_breathing_distance", lambda *a, **k: 0.0)(trade_like, regime=regime, entry_price=entry)
                    if adverse_points <= breathing:
                        return True, f"deferred: configured normal-noise room ({ctx_reason})"

        if inst_type != "OPT":
            return False, ""

        entry_time = getattr(trade_like, "signal_timestamp", getattr(trade_like, "entry_time", None))
        if latest_time is None or entry_time is None:
            return False, ""
        try:
            ref = entry_time.astimezone(IST).replace(tzinfo=None) if getattr(entry_time, "tzinfo", None) is not None else entry_time
            now = latest_time.astimezone(IST).replace(tzinfo=None) if getattr(latest_time, "tzinfo", None) is not None else latest_time
            age_seconds = max(0.0, (now - ref).total_seconds())
        except Exception:
            return False, ""

        breathing = getattr(self, "_option_breathing_distance", lambda *a, **k: 0.0)(trade_like, regime=regime, entry_price=entry)
        severe_adverse = adverse_points >= breathing * 1.25 if breathing > 0 else False
        min_hold_seconds = getattr(self, "_timeframe_seconds", lambda t: 300)(getattr(trade_like, "timeframe", "5min"))
        votes = 0
        match = re.search(r"votes=(\d+)", str(reason_text or ""))
        if match:
            try:
                votes = int(match.group(1))
            except Exception:
                votes = 0
        severe_votes = votes >= 3 and adverse_points >= breathing * 0.75 if breathing > 0 else votes >= 3

        if age_seconds < min_hold_seconds and not severe_adverse and not severe_votes:
            return True, (
                f"within {age_seconds:.0f}s of {getattr(trade_like, 'timeframe', '5min')} signal "
                f"and adverse {adverse_points:.2f} < breathing {breathing:.2f}"
            )
        return False, ""

    def _should_defer_option_repaint_abort(
        self,
        trade_like,
        current_price: float,
        latest_time: Optional[datetime],
        is_candle_closed: bool,
        regime: str = "",
    ) -> Tuple[bool, str]:
        """Hold fresh option entries through normal intrabar repaint flicker."""
        settings = get_settings()
        if not self._setting_enabled(
            getattr(settings, "option_repaint_abort_defer_until_close", True),
            True,
        ):
            return False, ""
        if is_candle_closed:
            return False, ""
        if str(getattr(trade_like, "inst_type", "") or "").upper() != "OPT":
            return False, ""

        entry = float(getattr(trade_like, "price", getattr(trade_like, "entry_price", 0.0)) or 0.0)
        current = float(current_price or 0.0)
        if entry <= 0 or current <= 0:
            return False, ""

        adverse_points = max(0.0, entry - current)
        breathing = self._option_breathing_distance(trade_like, regime=regime, entry_price=entry)
        severe_mult = max(
            0.5,
            float(getattr(settings, "option_repaint_abort_severe_breathing_mult", 1.25) or 1.25),
        )
        severe_threshold = breathing * severe_mult if breathing > 0 else 0.0
        if severe_threshold > 0 and adverse_points >= severe_threshold:
            return False, (
                f"adverse {adverse_points:.2f} >= severe repaint threshold "
                f"{severe_threshold:.2f}"
            )

        absent_checks = max(1, int(getattr(trade_like, "_repaint_absent_checks", 1) or 1))
        max_deferred_checks = max(
            0,
            int(getattr(settings, "option_repaint_abort_max_deferred_checks", 2) or 0),
        )
        if max_deferred_checks and absent_checks > max_deferred_checks:
            return False, (
                f"persistent repaint: vanished for {absent_checks} consecutive checks "
                f"> max deferred {max_deferred_checks}"
            )

        first_absent = getattr(trade_like, "_repaint_first_absent_at", None)
        max_deferred_seconds = max(
            0.0,
            float(getattr(settings, "option_repaint_abort_max_deferred_seconds", 55.0) or 0.0),
        )
        if max_deferred_seconds and first_absent is not None and latest_time is not None:
            try:
                first_check = (
                    first_absent.astimezone(IST).replace(tzinfo=None)
                    if getattr(first_absent, "tzinfo", None) is not None
                    else first_absent
                )
                now_check = (
                    latest_time.astimezone(IST).replace(tzinfo=None)
                    if getattr(latest_time, "tzinfo", None) is not None
                    else latest_time
                )
                absent_seconds = max(0.0, (now_check - first_check).total_seconds())
                if absent_seconds >= max_deferred_seconds:
                    return False, (
                        f"persistent repaint: vanished for {absent_seconds:.0f}s "
                        f">= max deferred {max_deferred_seconds:.0f}s"
                    )
            except Exception:
                pass

        sig_ts = getattr(trade_like, "signal_timestamp", None)
        seconds_to_close = 0.0
        if sig_ts is not None and latest_time is not None:
            try:
                sig_check = sig_ts.astimezone(IST).replace(tzinfo=None) if getattr(sig_ts, "tzinfo", None) is not None else sig_ts
                now_check = latest_time.astimezone(IST).replace(tzinfo=None) if getattr(latest_time, "tzinfo", None) is not None else latest_time
                tf_seconds = self._timeframe_seconds(getattr(trade_like, "timeframe", "5min"))
                seconds_to_close = max(0.0, (sig_check + timedelta(seconds=tf_seconds) - now_check).total_seconds())
            except Exception:
                seconds_to_close = 0.0

        return True, (
            f"option repaint flicker deferred until candle close; check {absent_checks}/{max_deferred_checks or '∞'}, "
            f"adverse {adverse_points:.2f} "
            f"< severe {severe_threshold:.2f}, closes in {seconds_to_close:.0f}s"
        )

    def _profit_guard_reversal_context(
        self,
        trade_like,
        current_price: float,
        latest_time: Optional[datetime],
        *_args,
        timeframe: Optional[str] = None,
        **_kwargs,
    ) -> Dict[str, Any]:
        """Read recent own-timeframe price action to distinguish pullback from fast reversal."""
        context = {
            "has_context": False,
            "fast_reversal": False,
            "trend_supportive": False,
            "reason": "no timeframe context",
        }
        tf = str(timeframe or getattr(trade_like, "timeframe", "") or "1min").lower()
        if tf not in {"1min", "5min", "15min"}:
            tf = "1min"
        try:
            df = self.candles.get_candles(getattr(trade_like, "instrument", ""), tf)
        except Exception:
            return context
        if df is None or len(df) < 4:
            return context

        work = df.copy()
        if not isinstance(work.index, pd.DatetimeIndex):
            if "timestamp" not in work.columns:
                return context
            work["timestamp"] = pd.to_datetime(work["timestamp"], errors="coerce")
            work = work.dropna(subset=["timestamp"]).set_index("timestamp")
        if work.empty:
            return context
        work = work.sort_index()
        if latest_time is not None:
            latest_ts = pd.Timestamp(latest_time)
            if latest_ts.tzinfo is not None:
                latest_ts = latest_ts.tz_convert(IST).tz_localize(None)
            work = work[work.index <= latest_ts]
        if len(work) < 4:
            return context

        tail = work.tail(12)
        opens = tail["open"].astype(float)
        highs = tail["high"].astype(float)
        lows = tail["low"].astype(float)
        closes = tail["close"].astype(float)
        # The level these candles are measured on. `closes` is the INDEX frame, so this is
        # the only correct basis for any threshold expressed as a fraction of price —
        # current_price may be an option premium, which is ~100x smaller.
        index_close = float(closes.iloc[-1])
        ranges = (highs - lows).abs()
        median_range = float(ranges.iloc[:-1].median() if len(ranges) > 1 else ranges.iloc[-1])
        if not math.isfinite(median_range) or median_range <= 0:
            # Same basis rule: a fallback range derived from a premium is meaningless
            # against index candles.
            median_range = max(
                (index_close if index_close > 0 else float(current_price or 0.0)) * 0.0002,
                1.0,
            )

        last_open = float(opens.iloc[-1])
        last_close = float(closes.iloc[-1])
        last_high = float(highs.iloc[-1])
        last_low = float(lows.iloc[-1])
        prev_close = float(closes.iloc[-2])
        direction = str(getattr(trade_like, "direction", "") or "").upper()
        # OPT: map CE→LONG / PE→SHORT for index-direction PA (premium-long still
        # uses option_type when present).
        if str(getattr(trade_like, "inst_type", "") or "").upper() == "OPT":
            opt = str(getattr(trade_like, "option_type", "") or "").upper()
            if opt == "PE":
                direction = "SHORT"
            elif opt == "CE":
                direction = "LONG"

        if direction == "SHORT":
            adverse_body = max(0.0, last_close - last_open)
            adverse_close_move = max(0.0, last_close - prev_close)
        else:
            adverse_body = max(0.0, last_open - last_close)
            adverse_close_move = max(0.0, prev_close - last_close)

        # These floors say "an adverse candle smaller than ~2.5-3.5 bps of the INDEX is
        # not a reversal", and they are compared against index candle bodies. Fed an
        # option premium instead they collapse to nothing and stop being floors at all.
        #
        # NIFTY 24500, bought PE at 217.50, lunchtime lull with a 3.0-point median range:
        #   intended  max(3.0*1.20, 24500*0.00025) = 6.125 body / 8.575 close
        #   with premium  max(3.60, 217.50*0.00025 = 0.054) = 3.60 body / 4.50 close
        # so the guard fires on exactly the index wiggles the floor was written to ignore.
        #
        # I looked at this earlier and called it harmless on the reasoning that max()
        # would pick the median_range term anyway. That is true only when the tape is
        # busy. In quiet tape the floor is meant to WIN, and it cannot.
        noise_basis = index_close if index_close > 0 else float(current_price or 0.0)
        fast_body_threshold = max(median_range * 1.20, noise_basis * 0.00025)
        fast_close_threshold = max(median_range * 1.50, noise_basis * 0.00035)
        fast_reversal = adverse_body >= fast_body_threshold or adverse_close_move >= fast_close_threshold

        # ── Gap1: rejection wick (pin / shooting-star) without PA module ──
        full_range = max(1e-9, last_high - last_low)
        upper_wick = max(0.0, last_high - max(last_open, last_close))
        lower_wick = max(0.0, min(last_open, last_close) - last_low)
        body_size = abs(last_close - last_open)
        settings = get_settings()
        wick_enabled = self._setting_enabled(
            getattr(settings, "loss_guard_rejection_wick_enabled", True), True
        )
        wick_min = max(
            0.25,
            float(getattr(settings, "loss_guard_rejection_wick_min_ratio", 0.45) or 0.45),
        )
        # Close location in bar: 0=at low, 1=at high. Real rejection needs the
        # close to finish near the adverse extreme (not a symmetric range bar).
        close_loc = (last_close - last_low) / full_range
        if direction == "LONG":
            # Shooting-star style: long upper wick + close in lower half.
            rejection_wick_ratio = upper_wick / full_range
            rejection_wick = bool(
                wick_enabled
                and rejection_wick_ratio >= wick_min
                and upper_wick >= max(body_size * 1.5, median_range * 0.35)
                and close_loc <= 0.40
            )
        else:
            # Hammer-style against shorts: long lower wick + close in upper half.
            rejection_wick_ratio = lower_wick / full_range
            rejection_wick = bool(
                wick_enabled
                and rejection_wick_ratio >= wick_min
                and lower_wick >= max(body_size * 1.5, median_range * 0.35)
                and close_loc >= 0.60
            )
        if rejection_wick:
            fast_reversal = True

        # ── Gap4: multi-bar grind reverse (slow bleed, not one big candle) ──
        grind_bars = max(2, int(getattr(settings, "loss_guard_grind_bars", 3) or 3))
        grind_mult = max(
            0.5, float(getattr(settings, "loss_guard_grind_range_mult", 1.50) or 1.50)
        )
        adverse_streak = 0
        cumulative_adverse = 0.0
        n_closes = len(closes)
        for i in range(n_closes - 1, max(0, n_closes - grind_bars - 1) - 1, -1):
            o_i = float(opens.iloc[i])
            c_i = float(closes.iloc[i])
            if direction == "LONG":
                bar_adverse = c_i < o_i and (i == 0 or c_i <= float(closes.iloc[i - 1]))
                move = max(0.0, o_i - c_i)
            else:
                bar_adverse = c_i > o_i and (i == 0 or c_i >= float(closes.iloc[i - 1]))
                move = max(0.0, c_i - o_i)
            if not bar_adverse:
                break
            adverse_streak += 1
            cumulative_adverse += move
        grind_reverse = bool(
            adverse_streak >= grind_bars
            and cumulative_adverse >= grind_mult * median_range
        )
        if grind_reverse:
            fast_reversal = True

        ema9 = float(closes.ewm(span=9, adjust=False).mean().iloc[-1])
        ema21 = float(closes.ewm(span=21, adjust=False).mean().iloc[-1])
        slope = float(closes.iloc[-1] - closes.iloc[max(0, len(closes) - 4)])
        # ema9/ema21 are computed from `closes`, which is the INDEX frame. current_price
        # for an option trade is the PREMIUM — tens to low hundreds of rupees against an
        # index in the tens of thousands. So `premium <= ema9` was unconditionally True
        # for every PE and `premium >= ema9` unconditionally False for every CE: vote #1
        # was a constant, not a measurement, on the only instrument this system trades.
        #
        # A free vote on every PE also makes trend_supportive (>= 1) permanently True,
        # which makes `rejection_wick and not trend_supportive` and the `trend_votes == 0`
        # arm of the big_reversal test dead code for PE trades — the strictest exits stop
        # existing on exactly the side that most needs them. CE trades lose a vote they
        # have earned and get cut on ordinary noise.
        #
        # Some callers already convert (they pass spot / entry_spot in as current_price);
        # several do not. Rather than trust the caller, take the price on the same basis
        # as the EMAs whenever the one handed in plainly is not.
        trend_price = float(current_price or 0.0)
        if index_close > 0 and not (0.5 * index_close <= trend_price <= 1.5 * index_close):
            trend_price = index_close
        if direction == "SHORT":
            trend_votes = sum((trend_price <= ema9, ema9 <= ema21, slope <= 0))
        else:
            trend_votes = sum((trend_price >= ema9, ema9 >= ema21, slope >= 0))
        trend_supportive = trend_votes >= 1

        # Classify small pullback vs big reversal for loss/profit guards.
        body_ratio = adverse_body / max(1e-9, fast_body_threshold)
        close_ratio = adverse_close_move / max(1e-9, fast_close_threshold)
        if grind_reverse or (
            fast_reversal and (body_ratio >= 1.8 or close_ratio >= 1.8 or trend_votes == 0)
        ):
            pullback_class = "big_reversal"
        elif rejection_wick and not trend_supportive:
            pullback_class = "big_reversal"
        elif rejection_wick:
            pullback_class = "reversal"
        elif fast_reversal:
            pullback_class = "reversal"
        elif trend_supportive and body_ratio < 0.80 and close_ratio < 0.80 and not grind_reverse:
            pullback_class = "noise"
        elif trend_supportive and not grind_reverse:
            pullback_class = "small_pullback"
        else:
            pullback_class = "structure_break"

        context.update(
            {
                "has_context": True,
                "fast_reversal": bool(fast_reversal),
                "trend_supportive": bool(trend_supportive),
                "trend_votes": int(trend_votes),
                "pullback_class": pullback_class,
                "body_ratio": float(body_ratio),
                "close_ratio": float(close_ratio),
                "rejection_wick": bool(rejection_wick),
                "rejection_wick_ratio": float(rejection_wick_ratio),
                "grind_reverse": bool(grind_reverse),
                "adverse_streak": int(adverse_streak),
                "cumulative_adverse": float(cumulative_adverse),
                "reason": (
                    f"{tf} class={pullback_class} fast={bool(fast_reversal)} "
                    f"wick={bool(rejection_wick)}({rejection_wick_ratio:.0%}) "
                    f"grind={bool(grind_reverse)}({adverse_streak}b) "
                    f"trend_supportive={bool(trend_supportive)} "
                    f"trend_votes={trend_votes}/3 "
                    f"body={adverse_body:.2f}/{fast_body_threshold:.2f} "
                    f"close_move={adverse_close_move:.2f}/{fast_close_threshold:.2f}"
                ),
                "timeframe": tf,
                "adverse_body": adverse_body,
                "adverse_close_move": adverse_close_move,
                "fast_body_threshold": fast_body_threshold,
                "fast_close_threshold": fast_close_threshold,
                "median_range": median_range,
                # median_range is measured on THIS frame, which is the index, so callers
                # that want it as a fraction need the price it was measured against.
                # Dividing it by an option premium instead is off by roughly 100x.
                "reference_price": float(closes.iloc[-1]),
            }
        )
        if tf != "1min":
            one_min_context = self._profit_guard_reversal_context(
                trade_like,
                current_price,
                latest_time,
                timeframe="1min",
            )
            if one_min_context.get("has_context"):
                body_threshold = max(0.01, float(one_min_context.get("fast_body_threshold", 0.0) or 0.0))
                close_threshold = max(0.01, float(one_min_context.get("fast_close_threshold", 0.0) or 0.0))
                body_ratio = float(one_min_context.get("adverse_body", 0.0) or 0.0) / body_threshold
                close_ratio = float(one_min_context.get("adverse_close_move", 0.0) or 0.0) / close_threshold
                one_min_votes = int(one_min_context.get("trend_votes", 0) or 0)
                one_min_fast = bool(one_min_context.get("fast_reversal"))
                # HTF (5m/15m) runners must not exit on mere 1m noise (trend_votes==0).
                # Require size-threshold emergency OR multi-TF structure break.
                size_emergency = body_ratio >= 1.80 or close_ratio >= 1.80
                one_min_wick_emergency = bool(one_min_context.get("rejection_wick")) and (
                    float(one_min_context.get("rejection_wick_ratio", 0.0) or 0.0) >= 0.55
                )
                one_min_big_reversal = bool(
                    (one_min_fast and size_emergency)
                    or one_min_wick_emergency
                    or bool(one_min_context.get("grind_reverse"))
                )
                multi_tf_shift = (
                    not bool(one_min_context.get("trend_supportive"))
                    and not bool(context.get("trend_supportive"))
                    and one_min_votes == 0
                    and int(context.get("trend_votes", 0) or 0) == 0
                )
                context["one_min_context"] = one_min_context
                context["one_min_emergency"] = bool(one_min_big_reversal or multi_tf_shift)
                if one_min_big_reversal:
                    context["fast_reversal"] = True
                    context["trend_supportive"] = False
                    context["pullback_class"] = "big_reversal"
                    context["reason"] = (
                        f"{context['reason']}; 1min emergency adverse reversal "
                        f"({one_min_context.get('reason')})"
                    )
                elif multi_tf_shift:
                    context["trend_supportive"] = False
                    if context.get("pullback_class") in {"noise", "small_pullback"}:
                        context["pullback_class"] = "structure_break"
                    context["reason"] = (
                        f"{context['reason']}; 1min+{tf} trend shift "
                        f"({one_min_context.get('reason')})"
                    )
                else:
                    # 1m noise alone does not override intact HTF structure.
                    context["reason"] = (
                        f"{context['reason']}; 1min watch "
                        f"({one_min_context.get('reason')})"
                    )
        return context

    def _intel_age_seconds(
        self,
        intel_result: Optional[Dict[str, Any]],
        instrument: str = "",
        latest_time=None,
    ) -> Optional[float]:
        """Age of intel snapshot in seconds; None if unknown.

        Every timestamp here is reduced to a TRUE epoch before subtracting. The
        naive values this codebase passes as `latest_time` are IST wall clocks, and
        pd.Timestamp(naive).timestamp() reads them as UTC — which inflated the epoch
        by the 19800s IST offset. _cache_timeframe_intel stores `as_of = time.time()`,
        a true epoch, so that offset landed straight in the age: on 2026-08-12 two
        EARLY_LOSS_CUT decisions were taken against `intel stale 19804s>90s` and
        `19801s>90s` when the intel was in fact 4 and 1 seconds old.

        The datetime-candidate branch below made the same naive-as-UTC assumption, so
        its error cancelled and those readings were correct. That inconsistency is
        why this survived — the function was right on one path and wrong on the
        other. Localise, never assume.
        """
        now_ts = None
        try:
            if latest_time is not None:
                lt = pd.Timestamp(latest_time)
                if lt.tzinfo is None:
                    lt = lt.tz_localize(IST)
                now_ts = float(lt.timestamp())
            else:
                now_ts = float(datetime.now(IST).timestamp())
        except Exception:
            now_ts = time.time()

        # Prefer embedded timestamps on the intel dict / pillars.
        candidates = []
        if isinstance(intel_result, dict):
            for key in (
                "as_of",
                "timestamp",
                "captured_at",
                "updated_at",
                "age_seconds",
            ):
                if key in intel_result and intel_result.get(key) is not None:
                    candidates.append(intel_result.get(key))
            for pillar in ("aggregate", "oi", "pcr", "volume", "order_flow"):
                payload = intel_result.get(pillar)
                if isinstance(payload, dict):
                    for key in ("as_of", "timestamp", "captured_at", "age_seconds"):
                        if payload.get(key) is not None:
                            candidates.append(payload.get(key))

        for raw in candidates:
            try:
                if isinstance(raw, (int, float)):
                    val = float(raw)
                    if val > 1e9:  # epoch seconds
                        return max(0.0, now_ts - val)
                    if 0 <= val <= 7200:  # already age_seconds
                        return val
                    continue
                ts = pd.Timestamp(raw)
                if ts.tzinfo is None:
                    # Naive intel stamps are IST wall clock, same as latest_time.
                    ts = ts.tz_localize(IST)
                return max(0.0, now_ts - float(ts.timestamp()))
            except Exception:
                continue

        # Fall back to last fetch wall-clock for this instrument.
        try:
            last = float((getattr(self, "_last_intel_fetch", {}) or {}).get(instrument, 0.0) or 0.0)
            if last > 0:
                return max(0.0, time.time() - last)
        except Exception:
            pass
        return None

    def _decaying_intel_points(self, instrument: str, reasons: list, settings) -> int:
        """Severity points for intelligence that has been sliding, not merely low.

        Zero whenever the trend cannot be established — too few snapshots, no history
        yet, the feature switched off. "Cannot say" must never read as "deteriorating",
        or every trade in the first minutes of a session would be penalised for the
        store being empty.
        """
        if not Scanner._setting_enabled(
            getattr(settings, "loss_guard_intel_decay_enabled", False), False
        ):
            return 0
        store = getattr(self, "intel_snapshots", None)
        trend_fn = getattr(store, "score_trend", None)
        if not callable(trend_fn):
            return 0
        try:
            window = float(getattr(settings, "loss_guard_intel_decay_window_seconds", 900.0) or 900.0)
            slope = trend_fn(str(instrument or "").upper(), window)
        except Exception as exc:
            logger.debug(f"Intel decay trend unavailable for {instrument}: {exc}")
            return 0
        if slope is None:
            return 0
        try:
            floor = float(getattr(settings, "loss_guard_intel_decay_min_slope", -1.0) or -1.0)
        except (TypeError, ValueError):
            floor = -1.0
        if slope > floor:
            return 0
        points = max(1, int(getattr(settings, "loss_guard_intel_decay_severity", 1) or 1))
        reasons.append(f"intelligence decaying {slope:.2f}/min over the last window")
        return points

    def _loss_guard_severity(
        self,
        trade_like,
        *,
        current_price: float,
        latest_time,
        regime: str = "",
        current_pnl_rs: float = 0.0,
    ) -> Tuple[int, List[str], Dict[str, Any]]:
        """Score how severe an adverse move is (0 = pullback noise, high = big reverse).

        Combines price-action classification with OI / PCR / volume / order-flow so
        the loss-guard can cut earlier than base 0.8R only on confirmed reversals.
        """
        settings = get_settings()
        price_points = 0
        intel_points = 0
        reasons: List[str] = []
        is_losing = float(current_pnl_rs or 0.0) < 0.0
        price_ctx = self._profit_guard_reversal_context(
            trade_like,
            float(current_price or 0.0),
            latest_time,
            timeframe=getattr(trade_like, "timeframe", "5min"),
        )
        pullback_class = str(price_ctx.get("pullback_class") or "unknown")
        if price_ctx.get("has_context"):
            if pullback_class == "big_reversal" or price_ctx.get("one_min_emergency"):
                price_points += 3
                reasons.append(f"price {pullback_class}/emergency")
            elif pullback_class == "reversal" or price_ctx.get("fast_reversal"):
                price_points += 2
                reasons.append(f"price {pullback_class}")
            elif pullback_class == "structure_break":
                price_points += 2
                reasons.append("structure break")
            elif pullback_class in {"noise", "small_pullback"}:
                reasons.append(f"price {pullback_class} (not accelerated)")
            if price_ctx.get("rejection_wick"):
                price_points += 2
                reasons.append(
                    f"rejection wick {float(price_ctx.get('rejection_wick_ratio', 0.0) or 0.0):.0%}"
                )
            if price_ctx.get("grind_reverse"):
                price_points += 2
                reasons.append(
                    f"grind reverse {int(price_ctx.get('adverse_streak', 0) or 0)} bars"
                )
            if not price_ctx.get("trend_supportive") and pullback_class not in {
                "noise",
                "small_pullback",
            }:
                price_points += 1
                reasons.append("trend not supportive")

        # OPT premium melt without index reverse
        if str(getattr(trade_like, "inst_type", "") or "").upper() == "OPT":
            try:
                entry_prem = float(getattr(trade_like, "entry_price", 0.0) or 0.0)
                prem_now = float(current_price or getattr(trade_like, "current_price", 0.0) or 0.0)
                melt_pct = float(getattr(settings, "loss_guard_opt_premium_melt_pct", 8.0) or 8.0)
                if entry_prem > 0 and prem_now > 0:
                    drop_pct = max(0.0, (entry_prem - prem_now) / entry_prem * 100.0)
                    if drop_pct >= melt_pct:
                        pts = max(
                            1,
                            int(getattr(settings, "loss_guard_opt_premium_melt_severity", 2) or 2),
                        )
                        price_points += pts
                        reasons.append(f"OPT premium melt {drop_pct:.1f}% (≥{melt_pct:.0f}%)")
                        if pullback_class in {"noise", "small_pullback", "unknown"}:
                            pullback_class = "premium_melt"
            except Exception:
                pass

        intel_result = None
        try:
            get_intel = getattr(self, "_get_trade_intel", None)
            if callable(get_intel):
                intel_result = get_intel(trade_like)
            if not isinstance(intel_result, dict):
                intel_result = self._trade_like_market_intelligence_context(trade_like)
        except Exception:
            intel_result = {}

        instrument = str(getattr(trade_like, "instrument", "") or "").split()[0]
        # DECAYING evidence, not just weak evidence. Every pillar below is a
        # point-in-time reading; none of them says whether the case for this trade has
        # been strengthening or falling apart over the last quarter hour. The snapshot
        # store has held that history all session and only a chart overlay ever read it.
        #
        # A trade whose intelligence has been sliding steadily is deteriorating even
        # while price sits still, and that is exactly the trade worth cutting before the
        # stop does it. Default OFF: it makes exits stricter.
        price_points += self._decaying_intel_points(instrument, reasons, settings)

        intel_age = self._intel_age_seconds(intel_result, instrument, latest_time)
        max_age = max(
            15.0,
            float(getattr(settings, "loss_guard_intel_max_age_seconds", 90.0) or 90.0),
        )
        # R5: unknown age is NOT treated as fresh — half-weight like mild stale.
        intel_unknown = intel_age is None
        intel_stale = bool(intel_age is not None and intel_age > max_age)
        half_intel = intel_stale or (
            intel_unknown
            and self._setting_enabled(
                getattr(settings, "loss_guard_unknown_intel_age_half_weight", True), True
            )
        )
        if intel_stale:
            reasons.append(f"intel stale {intel_age:.0f}s>{max_age:.0f}s")
        elif intel_unknown and half_intel:
            reasons.append("intel age unknown (half-weight)")

        direction = str(getattr(trade_like, "direction", "") or "").upper()
        if str(getattr(trade_like, "inst_type", "") or "").upper() == "OPT":
            opt = str(getattr(trade_like, "option_type", "") or "").upper()
            if opt == "PE":
                direction = "SHORT"
            elif opt == "CE":
                direction = "LONG"

        try:
            rev = self._intel_reversal_reason(
                direction, intel_result, is_losing=is_losing
            )
        except Exception:
            rev = None
        if rev and not self._intel_exit_blocked_by_trend(trade_like, regime):
            if half_intel:
                intel_points += 1
                reasons.append(f"discounted {str(rev)[:60]}")
            else:
                intel_points += 3
                reasons.append(str(rev)[:80])

        try:
            view = "LONG" if direction == "LONG" else "SHORT"
            signed = self._trade_like_signed_intelligence(trade_like, intel_result or {})
            aligned = self._view_aligned_intel_score(view, signed)
            scale = 0.5 if half_intel else 1.0
            if aligned <= -0.55:
                intel_points += max(1, int(round(2 * scale)))
                reasons.append(f"adverse intel {aligned:.2f}")
            elif aligned <= -0.25:
                intel_points += max(0, int(round(1 * scale)))
                reasons.append(f"soft adverse intel {aligned:.2f}")
        except Exception:
            pass

        for label, key, pts in (
            ("OI", "oi", 2),
            ("PCR", "pcr", 1),
            ("volume", "volume", 1),
            ("order_flow", "order_flow", 1),
        ):
            payload = (intel_result or {}).get(key, {}) if isinstance(intel_result, dict) else {}
            if not isinstance(payload, dict):
                continue
            signal = str(
                payload.get("signal")
                or payload.get("bias")
                or payload.get("contrarian_signal")
                or ""
            ).upper()
            if not signal:
                continue
            add_pts = max(1, int(round(pts * (0.5 if half_intel else 1.0))))
            try:
                opposes = self._intel_signal_opposes_view(
                    signal, "LONG" if direction == "LONG" else "SHORT"
                )
            except Exception:
                opposes = (
                    direction == "LONG" and signal in {"BEARISH", "STRONG_BEARISH", "SELL"}
                ) or (
                    direction == "SHORT" and signal in {"BULLISH", "STRONG_BULLISH", "BUY"}
                )
            if opposes:
                intel_points += add_pts
                reasons.append(f"{label} {signal} opposes")

        from engine.loss_guard_policy import cap_loss_guard_severity

        severity = cap_loss_guard_severity(
            price_points + intel_points,
            price_points=price_points,
            intel_points=intel_points,
            max_total=int(getattr(settings, "loss_guard_severity_max_total", 8) or 8),
            max_price=int(getattr(settings, "loss_guard_severity_max_price", 5) or 5),
            max_intel=int(getattr(settings, "loss_guard_severity_max_intel", 5) or 5),
        )

        return severity, reasons, {
            "pullback_class": pullback_class,
            "price_ctx": price_ctx,
            "intel": intel_result if isinstance(intel_result, dict) else {},
            "intel_age_seconds": intel_age,
            "intel_stale": intel_stale,
            "intel_unknown_age": intel_unknown,
            "is_losing": is_losing,
            "price_points": price_points,
            "intel_points": intel_points,
        }

    def _loss_guard_decision(
        self,
        trade_like,
        *,
        current_pnl_rs: float,
        initial_risk_rs: float,
        latest_time,
        regime: str = "",
        current_price: float = 0.0,
    ) -> Tuple[bool, str, float]:
        """Decide whether to cut a losing trade early.

        Base threshold = 0.8R. When intel + price action confirm a big reversal,
        threshold drops to soft (0.55R) or severe (0.35R). Small pullbacks keep 0.8R.
        """
        settings = get_settings()
        is_opt = str(getattr(trade_like, "inst_type", "FUT") or "FUT").upper() == "OPT"
        if is_opt and not bool(getattr(settings, "opt_early_loss_cut_enabled", True)):
            return False, "opt loss cut disabled", 0.8
        if (not is_opt) and not bool(getattr(settings, "fut_early_loss_cut_enabled", True)):
            return False, "fut loss cut disabled", 0.8

        pnl = float(current_pnl_rs or 0.0)
        risk = abs(float(initial_risk_rs or 0.0))
        if pnl >= 0.0:
            return False, "winner — loss guard idle", 0.8
        if risk <= 0.0:
            # Fall back to TradeManager stop distance when risk not provided.
            try:
                if self.trades._early_loss_cut_hit(trade_like):
                    return True, "EARLY_LOSS_CUT (fallback TM)", float(
                        getattr(settings, "opt_loss_cut_r" if is_opt else "fut_loss_cut_r", 0.8) or 0.8
                    )
            except Exception:
                pass
            return False, "no initial risk", 0.8

        from engine.loss_guard_policy import cut_r_from_severity

        base_r = float(
            getattr(settings, "opt_loss_cut_r" if is_opt else "fut_loss_cut_r", 0.8) or 0.8
        )
        base_r = max(0.05, min(1.0, base_r))
        cut_r = base_r
        loss_r = abs(pnl) / risk
        label = "base"
        reasons: List[str] = []
        pullback_class = ""
        severity = 0

        accel = self._setting_enabled(
            getattr(settings, "loss_guard_intel_accelerated_enabled", True), True
        )
        if accel:
            severity, reasons, meta = self._loss_guard_severity(
                trade_like,
                current_price=float(current_price or 0.0),
                latest_time=latest_time,
                regime=regime,
                current_pnl_rs=pnl,
            )
            pullback_class = str((meta or {}).get("pullback_class") or "")
            cut_r, label = cut_r_from_severity(
                severity,
                base_r=base_r,
                min_r=float(getattr(settings, "loss_guard_intel_min_r", 0.35) or 0.35),
                soft_r=float(getattr(settings, "loss_guard_soft_intel_r", 0.55) or 0.55),
                big_thr=int(getattr(settings, "loss_guard_big_reversal_severity", 5) or 5),
                soft_thr=int(getattr(settings, "loss_guard_soft_reversal_severity", 3) or 3),
                pullback_class=pullback_class,
            )

        detail = (
            f"loss={loss_r:.2f}R thr={cut_r:.2f}R class={pullback_class or 'n/a'} "
            f"sev={severity} {label}"
        )
        if reasons:
            detail += f" [{'; '.join(reasons[:4])}]"

        # R2: publish threshold so TradeManager backstop uses the same cut_r.
        try:
            setattr(trade_like, "loss_guard_cut_r", float(cut_r))
            setattr(trade_like, "loss_guard_cut_label", str(label))
        except Exception:
            pass

        if loss_r + 1e-9 >= cut_r:
            return True, f"EARLY_LOSS_CUT {detail}", cut_r
        return False, f"hold {detail}", cut_r

    @staticmethod
    def _freefall_flag_groups(flags: List[str]) -> List[str]:
        """Collapse raw freefall flags into distinct evidence groups.

        Groups: price (fast_reversal / 1min_emergency / pullback_*),
        context (live_context_opposite / regime_opposite / trend_broken),
        repaint (post_close_repaint / repaint_flag), velocity (spike_*),
        intel (price_action_adverse / adverse_intel_*). Severity echoes
        (sev:* / high_severity_*) are informational — the severity gate already
        counts them — so they never form a group of their own.
        """
        groups: List[str] = []
        for flag in flags or []:
            f = str(flag or "")
            if f in {"fast_reversal", "1min_emergency"} or f.startswith("pullback_"):
                group = "price"
            elif f in {"live_context_opposite", "regime_opposite", "trend_broken"}:
                group = "context"
            elif f in {"post_close_repaint", "repaint_flag"}:
                group = "repaint"
            elif f.startswith("spike_"):
                group = "velocity"
            elif f == "price_action_adverse" or f.startswith("adverse_intel_"):
                group = "intel"
            else:
                continue  # sev:* / high_severity_* / unknown — not a group
            if group not in groups:
                groups.append(group)
        return groups

    def _rupee_loss_band_freefall_flags(
        self,
        trade_like,
        *,
        current_pnl_rs: float,
        latest_time=None,
        regime: str = "",
        current_price: float = 0.0,
        severity: int = 0,
        severity_reasons: Optional[List[str]] = None,
        severity_meta: Optional[Dict[str, Any]] = None,
        scale: float = 1.0,
    ) -> Tuple[List[str], Dict[str, Any]]:
        """Detect special freefall occasions (not plain slow bleed)."""
        settings = get_settings()
        flags: List[str] = []
        meta: Dict[str, Any] = dict(severity_meta or {})
        view = self._trade_direction_view(trade_like)
        context_price = float(current_price or 0.0)
        try:
            spot = float(self.candles.get_latest_price(getattr(trade_like, "instrument", "")) or 0.0)
            if spot > 0:
                context_price = spot
        except Exception:
            pass

        # 1) Sudden reverse / 1m emergency / wick dump
        try:
            px_ctx = self._profit_guard_reversal_context(
                trade_like,
                context_price,
                latest_time,
                timeframe=getattr(trade_like, "timeframe", "5min"),
            )
            meta["price_ctx"] = px_ctx
            if px_ctx.get("has_context"):
                if px_ctx.get("fast_reversal"):
                    flags.append("fast_reversal")
                if px_ctx.get("one_min_emergency"):
                    flags.append("1min_emergency")
                if not px_ctx.get("trend_supportive"):
                    flags.append("trend_broken")
        except Exception:
            pass

        # 2) Live market suddenly opposite the trade
        try:
            live_ctx = self._live_direction_context(trade_like, view, regime)
            meta["live_ctx"] = live_ctx
            if live_ctx.get("adverse"):
                flags.append("live_context_opposite")
            live_reg = str(live_ctx.get("live_regime") or regime or "")
            if self._regime_opposes_direction(view, live_reg):
                flags.append("regime_opposite")
        except Exception:
            pass

        # 3) Post-close repaint / source signal vanished after candle close
        try:
            sig_ts = getattr(trade_like, "signal_timestamp", None) or getattr(
                trade_like, "entry_time", None
            )
            tf = str(getattr(trade_like, "timeframe", "5min") or "5min")
            if sig_ts is not None and latest_time is not None:
                if self._repaint_close_check_in_window(sig_ts, tf, latest_time):
                    still = True
                    try:
                        # Definite absence only — an empty scan cache must not raise a
                        # post_close_repaint severity flag on "cannot tell".
                        still = not self._repaint_absence_is_definite(trade_like, sig_ts)
                    except Exception:
                        still = not bool(getattr(trade_like, "_repaint_aborted", False))
                    if not still:
                        flags.append("post_close_repaint")
                if bool(getattr(trade_like, "_repaint_aborted", False)) or bool(
                    getattr(trade_like, "repaint_abort_pending", False)
                ):
                    flags.append("repaint_flag")
        except Exception:
            pass

        # 4) Sudden spike freefall (adverse Rs/min since entry or last mark)
        try:
            entry_ts = getattr(trade_like, "entry_time", None) or getattr(
                trade_like, "signal_timestamp", None
            )
            if entry_ts is not None and latest_time is not None:
                et = entry_ts
                lt = latest_time
                if getattr(et, "tzinfo", None) is not None:
                    et = et.astimezone(IST).replace(tzinfo=None)
                if getattr(lt, "tzinfo", None) is not None:
                    lt = lt.astimezone(IST).replace(tzinfo=None)
                mins = max(0.25, (lt - et).total_seconds() / 60.0)
                loss = abs(min(0.0, float(current_pnl_rs or 0.0)))
                vel = loss / mins
                spike_thr = max(
                    50.0,
                    float(getattr(settings, "rupee_loss_band_spike_rs_per_min", 400.0) or 400.0)
                    * max(1.0, float(scale or 1.0)),
                )
                meta["loss_velocity_rs_per_min"] = round(vel, 1)
                if vel >= spike_thr:
                    flags.append(f"spike_{vel:.0f}rs_per_min")
        except Exception:
            pass

        # 5) Intel / PA hard against (other filters may have missed the exit)
        try:
            verdict = str(getattr(trade_like, "price_action_verdict", "") or "").upper()
            if verdict == "ADVERSE":
                flags.append("price_action_adverse")
        except Exception:
            pass
        try:
            ctx = self._trade_like_market_intelligence_context(trade_like)
            signed = self._trade_like_signed_intelligence(trade_like, ctx)
            aligned = self._view_aligned_intel_score(view, signed)
            if aligned <= -0.55:
                flags.append(f"adverse_intel_{aligned:.2f}")
        except Exception:
            pass

        # 6) Loss-guard severity already says big reverse (class=reversal)
        pullback = str((meta or {}).get("pullback_class") or "").lower()
        if "reversal" in pullback or "wick" in pullback:
            flags.append(f"pullback_{pullback}")
        if int(severity or 0) >= 5:
            flags.append(f"high_severity_{int(severity)}")
        for reason in list(severity_reasons or [])[:6]:
            text = str(reason or "").lower()
            if any(k in text for k in ("reversal", "spike", "emergency", "opposite", "repaint", "dump")):
                flags.append(f"sev:{text[:40]}")

        # Dedupe preserving order
        seen = set()
        uniq: List[str] = []
        for f in flags:
            if f not in seen:
                seen.add(f)
                uniq.append(f)
        return uniq, meta

    def _rupee_loss_band_track_slow_bleed(
        self,
        trade_like,
        *,
        loss: float,
        start_rs: float,
        latest_time,
    ) -> Dict[str, Any]:
        """Track time-past-arm and new-low progression for slow-bleed detection."""
        state: Dict[str, Any] = {}
        try:
            now = latest_time
            if now is not None and getattr(now, "tzinfo", None) is not None:
                now = now.astimezone(IST).replace(tzinfo=None)
            first_at = getattr(trade_like, "_ladder_arm_first_at", None)
            if first_at is not None and getattr(first_at, "tzinfo", None) is not None:
                first_at = first_at.astimezone(IST).replace(tzinfo=None)
            worst = float(getattr(trade_like, "_ladder_arm_worst_loss", 0.0) or 0.0)
            best_since = float(getattr(trade_like, "_ladder_arm_best_loss", loss) or loss)

            if loss + 1e-9 < start_rs:
                # Recovered above arm — reset bleed clock.
                try:
                    setattr(trade_like, "_ladder_arm_first_at", None)
                    setattr(trade_like, "_ladder_arm_worst_loss", 0.0)
                    setattr(trade_like, "_ladder_arm_best_loss", 0.0)
                except Exception:
                    pass
                return {"armed": False, "minutes": 0.0, "worsen": 0.0, "recovery": 0.0}

            if first_at is None and now is not None:
                first_at = now
                try:
                    setattr(trade_like, "_ladder_arm_first_at", first_at)
                    setattr(trade_like, "_ladder_arm_first_loss", float(loss))
                    setattr(trade_like, "_ladder_arm_worst_loss", float(loss))
                    setattr(trade_like, "_ladder_arm_best_loss", float(loss))
                except Exception:
                    pass
                worst = loss

            worst = max(worst, loss)
            try:
                setattr(trade_like, "_ladder_arm_worst_loss", float(worst))
            except Exception:
                pass

            minutes = 0.0
            if first_at is not None and now is not None:
                minutes = max(0.0, (now - first_at).total_seconds() / 60.0)
            try:
                first_loss = float(getattr(trade_like, "_ladder_arm_first_loss", 0.0) or 0.0)
            except Exception:
                first_loss = 0.0
            if first_loss <= 0:
                first_loss = max(start_rs, loss)
                try:
                    setattr(trade_like, "_ladder_arm_first_loss", float(first_loss))
                except Exception:
                    pass
            worsen = max(0.0, worst - first_loss)
            recovery = max(0.0, worst - loss)  # bounce off the worst print

            state = {
                "armed": True,
                "minutes": round(minutes, 2),
                "worsen": round(worsen, 1),
                "recovery": round(recovery, 1),
                "worst": round(worst, 1),
                "first_loss": round(first_loss, 1),
            }
        except Exception:
            state = {"armed": loss >= start_rs, "minutes": 0.0, "worsen": 0.0, "recovery": 0.0}
        return state

    def _rupee_loss_band_guard_decision(
        self,
        trade_like,
        *,
        current_pnl_rs: float,
        latest_time=None,
        regime: str = "",
        current_price: float = 0.0,
    ) -> Tuple[bool, str, str]:
        """Deep-red ladder: freefall specials OR confirmed slow bleed.

        Crossing OPT -1000 / FUT -1500 alone is not enough for an instant cut.
        Exit when either:
          (A) FREEFALL — sudden opposite market, post-close repaint, spike, etc.
          (B) SLOW BLEED — past arm for N minutes, loss keeps making new lows,
              no meaningful bounce (easy, reliable detector).
        Absolute catastrophe force is last resort when loss is extreme.
        """
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "rupee_loss_band_enabled", True), True):
            return False, "", "disabled"
        inst = str(getattr(trade_like, "inst_type", "FUT") or "FUT").upper()
        is_opt = inst in {"OPT", "CE", "PE"}
        if self._setting_enabled(getattr(settings, "rupee_loss_band_opt_only", False), False) and not is_opt:
            return False, "", "fut skipped"
        pnl = float(current_pnl_rs or 0.0)
        if pnl >= 0.0:
            # Reset bleed tracker on green.
            try:
                setattr(trade_like, "_ladder_arm_first_at", None)
                setattr(trade_like, "_ladder_arm_worst_loss", 0.0)
                setattr(trade_like, "_ladder_arm_best_loss", 0.0)
                setattr(trade_like, "_ladder_arm_first_loss", 0.0)
            except Exception:
                pass
            return False, "", "winner"
        loss = abs(pnl)

        if is_opt:
            start_rs = float(
                getattr(settings, "rupee_loss_band_start_rs_opt", None)
                if getattr(settings, "rupee_loss_band_start_rs_opt", None) is not None
                else getattr(settings, "rupee_loss_band_start_rs", 1000.0)
            )
            step = float(
                getattr(settings, "rupee_loss_band_size_rs_opt", None)
                if getattr(settings, "rupee_loss_band_size_rs_opt", None) is not None
                else getattr(settings, "rupee_loss_band_size_rs", 500.0)
            )
            need_sev = int(
                getattr(settings, "rupee_loss_band_min_severity_opt", None)
                if getattr(settings, "rupee_loss_band_min_severity_opt", None) is not None
                else getattr(settings, "rupee_loss_band_min_severity", 4)
            )
            force_loss = float(getattr(settings, "rupee_loss_band_force_loss_rs_opt", 3000.0) or 3000.0)
            product = "OPT"
        else:
            start_rs = float(
                getattr(settings, "rupee_loss_band_start_rs_fut", None)
                if getattr(settings, "rupee_loss_band_start_rs_fut", None) is not None
                else getattr(settings, "rupee_loss_band_start_rs", 1500.0)
            )
            step = float(
                getattr(settings, "rupee_loss_band_size_rs_fut", None)
                if getattr(settings, "rupee_loss_band_size_rs_fut", None) is not None
                else getattr(settings, "rupee_loss_band_size_rs", 500.0)
            )
            need_sev = int(
                getattr(settings, "rupee_loss_band_min_severity_fut", None)
                if getattr(settings, "rupee_loss_band_min_severity_fut", None) is not None
                else getattr(settings, "rupee_loss_band_min_severity", 4)
            )
            force_loss = float(getattr(settings, "rupee_loss_band_force_loss_rs_fut", 4000.0) or 4000.0)
            product = "FUT"

        start_rs = max(1.0, float(start_rs or 1000.0))
        step = max(1.0, float(step or 500.0))
        need_sev = max(1, int(need_sev or 4))
        force_loss = max(start_rs + step, float(force_loss or 0.0))

        # ── Lot/size scaling (2026-07-10) ──
        # The rupee arms are PER LOT: a 2-lot book breathes 2× before the ladder
        # arms, so bigger size is never cut on 1-lot premium noise. MIDCPNIFTY
        # (largest lot: 120 vs NIFTY 65 / BANKNIFTY 30 / SENSEX 20) gets an
        # extra relaxation on top.
        ladder_scale = 1.0
        if self._setting_enabled(
            getattr(settings, "rupee_loss_band_scale_per_lot", True), True
        ):
            try:
                ladder_scale = float(max(1, int(getattr(trade_like, "lots", 1) or 1)))
            except Exception:
                ladder_scale = 1.0
        base_index = str(getattr(trade_like, "instrument", "") or "").split()[0].upper()
        if base_index == self.MIDCAP_CORRELATED_INDEX:
            relax_pct = float(
                getattr(settings, "rupee_loss_band_midcap_relax_pct", 20.0) or 0.0
            )
            ladder_scale *= 1.0 + max(0.0, relax_pct) / 100.0
        if ladder_scale != 1.0:
            start_rs *= ladder_scale
            step *= ladder_scale
            force_loss *= ladder_scale

        bleed = self._rupee_loss_band_track_slow_bleed(
            trade_like, loss=loss, start_rs=start_rs, latest_time=latest_time
        )

        if loss + 1e-9 < start_rs:
            return False, "", f"{product} loss Rs.{loss:.0f} < ladder start Rs.{start_rs:.0f}"

        rung = int((loss - start_rs) // step)
        band_lo = int(start_rs + rung * step)
        band_hi = int(band_lo + step)
        band_name = f"{product}_HARD_{band_lo}_{band_hi}"

        severity, sev_reasons, sev_meta = 0, [], {}
        try:
            severity, sev_reasons, sev_meta = self._loss_guard_severity(
                trade_like,
                current_price=float(current_price or 0.0),
                latest_time=latest_time,
                regime=regime,
                current_pnl_rs=pnl,
            )
        except Exception:
            severity, sev_reasons, sev_meta = 0, [], {}

        flags, ff_meta = self._rupee_loss_band_freefall_flags(
            trade_like,
            current_pnl_rs=pnl,
            latest_time=latest_time,
            regime=regime,
            current_price=float(current_price or 0.0),
            severity=int(severity or 0),
            severity_reasons=list(sev_reasons or []),
            severity_meta=dict(sev_meta or {}),
            scale=ladder_scale,
        )
        min_flags = max(1, int(getattr(settings, "rupee_loss_band_min_freefall_flags", 2) or 2))
        # Count DISTINCT evidence groups, not raw flags: one underlying reversal
        # used to mint fast_reversal + pullback_* + sev:* and self-confirm, and
        # trend_broken/live_context_opposite are near-automatic for any loser.
        flag_groups = self._freefall_flag_groups(flags)

        # Catastrophe last resort.
        if loss >= force_loss:
            detail = (
                f"{product} CATASTROPHE loss Rs.{loss:.0f} >= force Rs.{force_loss:.0f} "
                f"band={band_name}"
            )
            if flags:
                detail += f" flags={','.join(flags[:5])}"
            return True, "RUPEE_LOSS_BAND_EXIT", detail

        freefall_on = self._setting_enabled(
            getattr(settings, "rupee_loss_band_freefall_enabled", True), True
        )
        # Legacy: freefall_only=True still allows freefall path (and slow bleed if enabled).
        freefall_hit = False
        if freefall_on:
            if len(flag_groups) >= min_flags:
                if (
                    int(severity or 0) >= need_sev
                    or any(f.startswith("spike_") for f in flags)
                    or "post_close_repaint" in flags
                    or "1min_emergency" in flags
                ):
                    freefall_hit = True

        # Path B — slow bleed (easy detector): past arm long enough, still grinding
        # worse, no meaningful recovery off the worst print.
        slow_on = self._setting_enabled(
            getattr(settings, "rupee_loss_band_slow_bleed_enabled", True), True
        )
        slow_hit = False
        slow_detail = ""
        if slow_on and bleed.get("armed"):
            need_min = max(
                0.5,
                float(getattr(settings, "rupee_loss_band_slow_bleed_minutes", 4.0) or 4.0),
            )
            need_worsen = max(
                0.0,
                float(getattr(settings, "rupee_loss_band_slow_bleed_worsen_rs", 150.0) or 150.0),
            ) * ladder_scale
            max_recovery = max(
                0.0,
                float(getattr(settings, "rupee_loss_band_slow_bleed_max_recovery_rs", 80.0) or 80.0),
            ) * ladder_scale
            minutes = float(bleed.get("minutes") or 0.0)
            worsen = float(bleed.get("worsen") or 0.0)
            recovery = float(bleed.get("recovery") or 0.0)
            slow_detail = (
                f"bleed {minutes:.1f}m worsen Rs.{worsen:.0f} recovery Rs.{recovery:.0f} "
                f"(need >={need_min:.1f}m +{need_worsen:.0f} rec<={max_recovery:.0f})"
            )
            if minutes + 1e-9 >= need_min and worsen + 1e-9 >= need_worsen and recovery <= max_recovery + 1e-9:
                slow_hit = True

        if freefall_hit:
            detail = (
                f"{product} FREEFALL loss Rs.{loss:.0f} band={band_name} "
                f"arm Rs.{start_rs:.0f} sev={severity} flags={','.join(flags[:6])}"
            )
            if sev_reasons:
                detail += f" [{'; '.join(list(dict.fromkeys(sev_reasons))[:3])}]"
            vel = ff_meta.get("loss_velocity_rs_per_min")
            if vel is not None:
                detail += f" vel={vel}/min"
            return True, "RUPEE_LOSS_BAND_EXIT", detail

        if slow_hit:
            detail = (
                f"{product} SLOW_BLEED loss Rs.{loss:.0f} band={band_name} "
                f"arm Rs.{start_rs:.0f} {slow_detail}"
            )
            if flags:
                detail += f" flags={','.join(flags[:4])}"
            return True, "RUPEE_LOSS_BAND_EXIT", detail

        return False, "", (
            f"hold {product} loss Rs.{loss:.0f} band={band_name} "
            f"freefall_flags={len(flags)}/{min_flags} sev={severity} "
            f"{slow_detail or 'bleed not armed'}"
        )

    def _should_exit_major_win_guard(
        self,
        trade_like,
        current_price: float,
        peak_pnl: float,
        current_pnl: float,
        latest_time: Optional[datetime],
    ) -> Tuple[bool, str]:
        """Major-win guard exits on real reversal, not normal same-trend breathing."""
        if peak_pnl <= 0:
            return True, "invalid peak"
        retention = current_pnl / peak_pnl
        if retention <= 0.60:
            return True, f"hard giveback floor hit ({retention:.0%} of peak)"

        context = self._profit_guard_reversal_context(
            trade_like,
            current_price,
            latest_time,
            timeframe=getattr(trade_like, "timeframe", "1min"),
        )
        if not context.get("has_context"):
            return True, context.get("reason", "no context")
        if context.get("fast_reversal"):
            return True, f"fast adverse reversal ({context.get('reason')})"
        if not context.get("trend_supportive"):
            return True, f"trend no longer supportive ({context.get('reason')})"
        return False, f"same-trend pullback deferred ({retention:.0%} of peak; {context.get('reason')})"

    @staticmethod
    def _profit_lock_lot_count(trade_like, qty: int) -> int:
        """Lots behind a position, for reading the retention ladder per lot."""
        lots = 0
        try:
            lots = int(getattr(trade_like, "lots", 0) or 0)
        except (TypeError, ValueError):
            lots = 0
        if lots > 0:
            return lots
        try:
            lot_size = int(getattr(trade_like, "lot_size", 0) or 0)
            if lot_size > 0:
                return max(1, int(qty) // lot_size)
        except (TypeError, ValueError, ZeroDivisionError):
            pass
        return 1

    def _armed_broker_stop_for(self, trade_like) -> float:
        """The trigger this contract actually has RESTING at the exchange, or 0.0.

        Deferral is a local decision, but ensure_broker_protection has already pushed
        trade.current_stop to Kite as an SL-M and tightens it every time the stop trails.
        So by the time a profit lock is deferred, the exchange may already hold a trigger
        at the very level being deferred.
        """
        symbol = str(getattr(trade_like, "trading_symbol", "") or "").upper()
        instrument = str(getattr(trade_like, "instrument", "") or "").split()
        instrument = instrument[0].upper() if instrument else ""
        timeframe = str(getattr(trade_like, "timeframe", "") or "")
        try:
            trades = list(getattr(self.trades, "open_trades", {}).values())
        except Exception:
            return 0.0
        # Exact contract first: two trades can sit on one index at different strikes.
        for trade in trades:
            if symbol and str(getattr(trade, "trading_symbol", "") or "").upper() == symbol:
                return float(getattr(trade, "protective_trigger", 0.0) or 0.0)
        for trade in trades:
            row_inst = str(getattr(trade, "instrument", "") or "").split()
            row_inst = row_inst[0].upper() if row_inst else ""
            if row_inst == instrument and str(getattr(trade, "timeframe", "") or "") == timeframe:
                return float(getattr(trade, "protective_trigger", 0.0) or 0.0)
        return 0.0

    def _armed_broker_stop_crossed(self, trade_like, current_price: float) -> bool:
        """Has the mark crossed a stop that is ALREADY armed at the exchange?

        Such a stop is a hard boundary and must never be deferred by any local policy.
        Deferring it does not keep the position open -- Kite fires the SL-M regardless --
        it only means the broker closes the position while this process goes on managing
        a trade that no longer exists, re-arming stops and holding a slot against it.
        """
        armed = self._armed_broker_stop_for(trade_like)
        if armed <= 0:
            return False
        try:
            mark = float(current_price or 0.0)
        except (TypeError, ValueError):
            return False
        if mark <= 0:
            return False
        direction = str(getattr(trade_like, "direction", "LONG") or "LONG").upper()
        if self._is_premium_long_candidate(trade_like) or direction == "LONG":
            return mark <= armed
        return mark >= armed

    def _should_defer_trend_option_profit_lock(
        self,
        trade_like,
        current_price: float,
        lock_stop: float,
        current_pnl: float,
        peak_pnl: float,
        latest_time: Optional[datetime],
        regime: str = "",
    ) -> Tuple[bool, str]:
        """Let strong trend-aligned option winners breathe through normal premium pullbacks."""
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "trend_option_profit_lock_defer", True), True):
            return False, "disabled"
        if str(getattr(trade_like, "inst_type", "") or "").upper() != "OPT":
            return False, "not option"
        if str(getattr(trade_like, "timeframe", "") or "").lower() not in {"5min", "15min"}:
            return False, "not 5min/15min"

        grade = str(getattr(trade_like, "grade", "") or "").upper()
        if {"B+": 3, "A": 4, "A+": 5}.get(grade, 0) < 3:
            return False, "grade below B+"
        if peak_pnl <= 0 or current_pnl <= 0:
            return False, "not profitable"
        # A stop already RESTING at the exchange outranks every local policy. This is the
        # one check that has to come before the rest: the others decide whether holding is
        # a good idea, and this decides whether holding is even possible.
        #
        # Fetched defensively because partially-constructed scanners are a real pattern
        # here — recovery paths and tests call this with a stub `self`, and an
        # AttributeError would turn a missing convenience into a broken exit decision.
        armed_check = getattr(self, "_armed_broker_stop_crossed", None)
        if callable(armed_check) and armed_check(trade_like, current_price):
            return False, "exchange stop already armed at this level and crossed"
        retention = float(current_pnl) / float(peak_pnl)
        severe_retention = max(
            0.20,
            min(0.80, float(getattr(settings, "trend_option_profit_lock_severe_retention", 0.50) or 0.50)),
        )
        if retention <= severe_retention:
            return False, f"severe giveback {retention:.0%} <= {severe_retention:.0%}"

        direction = str(getattr(trade_like, "direction", "") or "").upper()
        side = "SELL" if direction == "SHORT" else "BUY"
        regime_text = str(
            regime
            or getattr(trade_like, "market_regime", "")
            or self._get_trade_regime(trade_like, "")
            or ""
        )
        regime_aligned = bool(is_trending_regime(regime_text) and regime_aligns(regime_text, side))

        spot_price = 0.0
        try:
            spot_price = float(self.candles.get_latest_price(getattr(trade_like, "instrument", "")) or 0.0)
        except Exception:
            spot_price = 0.0
        if spot_price <= 0:
            spot_price = float(getattr(trade_like, "entry_spot", 0.0) or 0.0)
        if spot_price <= 0:
            spot_price = float(current_price or 0.0)

        context = self._profit_guard_reversal_context(
            trade_like,
            spot_price,
            latest_time,
            timeframe=getattr(trade_like, "timeframe", "5min"),
        )
        has_context = bool(context.get("has_context"))
        fast_reversal = bool(context.get("fast_reversal"))
        trend_votes = int(context.get("trend_votes", 0) or 0)
        trend_supportive = bool(context.get("trend_supportive")) and trend_votes >= 2
        if fast_reversal:
            return False, f"fast adverse reversal ({context.get('reason', '')})"
        if not (regime_aligned or trend_supportive):
            return False, f"trend not aligned ({regime_text or context.get('reason', 'no context')})"

        entry = float(getattr(trade_like, "price", getattr(trade_like, "entry_price", 0.0)) or 0.0)
        breathing = self._option_breathing_distance(trade_like, regime=regime_text, entry_price=entry)
        floor_break = max(0.0, float(lock_stop or 0.0) - float(current_price or 0.0))
        if breathing > 0 and floor_break >= breathing:
            return False, f"protected floor broken by {floor_break:.2f} >= breathing {breathing:.2f}"

        ctx = context.get("reason", "no context") if has_context else "regime aligned"
        return True, (
            f"trend option profit-lock deferred; retention {retention:.0%}, "
            f"floor_break {floor_break:.2f}/{breathing:.2f}, "
            f"regime={regime_text or 'UNKNOWN'}, {ctx}"
        )

    def _stagnation_exit_decision(
        self,
        trade_like,
        current_pnl: float,
        peak_pnl: float,
        latest_time: Optional[datetime],
        regime: str = "",
    ) -> Tuple[bool, str]:
        """Scale stagnation exits by initial risk, index noise, and current trend."""
        if latest_time is None or peak_pnl <= 0 or current_pnl <= 0:
            return False, "not a profitable stagnation candidate"

        entry_time = getattr(trade_like, "entry_time", None) or getattr(trade_like, "signal_timestamp", None)
        if entry_time is None:
            return False, "missing entry time"
        try:
            entry_check = (
                entry_time.astimezone(IST).replace(tzinfo=None)
                if getattr(entry_time, "tzinfo", None) is not None
                else entry_time
            )
            now_check = (
                latest_time.astimezone(IST).replace(tzinfo=None)
                if getattr(latest_time, "tzinfo", None) is not None
                else latest_time
            )
            age_minutes = max(0.0, (now_check - entry_check).total_seconds() / 60.0)
        except Exception:
            return False, "invalid entry time"

        settings = get_settings()
        base_minutes = max(1.0, float(getattr(settings, "trade_stagnation_minutes", 20.0) or 20.0))
        max_extra = max(0.0, float(getattr(settings, "trade_stagnation_max_extra_minutes", 10.0) or 10.0))

        entry = float(getattr(trade_like, "price", getattr(trade_like, "entry_price", 0.0)) or 0.0)
        qty = max(
            1,
            int(getattr(trade_like, "lots", 1) or 1)
            * int(getattr(trade_like, "lot_size", 1) or 1),
        )
        initial_risk_rs = self._trade_like_initial_risk_rs(trade_like, qty=qty, inst_mult=1.0)
        min_peak_r = max(0.0, float(getattr(settings, "trade_stagnation_min_peak_r", 0.50) or 0.50))
        min_peak_rs = max(300.0, initial_risk_rs * min_peak_r)
        if peak_pnl < min_peak_rs:
            return False, f"peak Rs.{peak_pnl:.0f} below meaningful threshold Rs.{min_peak_rs:.0f}"

        current_price = float(
            getattr(
                trade_like,
                "current_price",
                getattr(trade_like, "price", getattr(trade_like, "entry_price", 0.0)),
            )
            or 0.0
        )
        context = self._profit_guard_reversal_context(
            trade_like,
            current_price,
            latest_time,
            timeframe=getattr(trade_like, "timeframe", "1min"),
        )
        median_range = float(context.get("median_range", 0.0) or 0.0)
        baseline_bps = {
            "NIFTY": 4.0,
            "BANKNIFTY": 5.0,
            "SENSEX": 4.0,
            "MIDCPNIFTY": 5.0,
        }.get(str(getattr(trade_like, "instrument", "") or "").upper(), 4.5)
        # median_range is measured on the INDEX candles, so the bps denominator has to be
        # the index too. It used to be current_price, which for an option is the PREMIUM:
        # ~20 index points over a Rs.217 premium reads as 919 bps against a 4 bps
        # baseline, so volatility_ratio pinned to its 3.0 ceiling on EVERY option trade.
        # Pinned there, extra_minutes was always the full 10 and retention_floor always
        # the loosest 68% — the "volatility-adjusted" stagnation exit did no adjusting at
        # all for the instrument type this system actually trades.
        reference_price = float(context.get("reference_price", 0.0) or 0.0)
        if reference_price <= 0:
            reference_price = float(getattr(trade_like, "entry_spot", 0.0) or 0.0)
        if reference_price <= 0:
            reference_price = current_price
        observed_bps = (
            (median_range / reference_price) * 10000.0
            if median_range > 0 and reference_price > 0
            else baseline_bps
        )
        volatility_ratio = max(0.5, min(3.0, observed_bps / baseline_bps))
        extra_minutes = max(0.0, min(max_extra, (volatility_ratio - 1.0) * 5.0))
        if str(regime or "").upper() in {"VOLATILE", "CHOPPY", "MEAN_REVERTING"}:
            extra_minutes = max(extra_minutes, min(max_extra, 5.0))
        required_minutes = base_minutes + extra_minutes
        if age_minutes < required_minutes:
            return False, f"age {age_minutes:.1f}m below volatility-adjusted {required_minutes:.1f}m"

        retention_floor = max(0.68, min(0.85, 0.85 - max(0.0, volatility_ratio - 1.0) * 0.10))
        retention = current_pnl / peak_pnl
        if retention >= retention_floor:
            return False, f"retention {retention:.0%} remains above {retention_floor:.0%}"
        if context.get("has_context") and int(context.get("trend_votes", 0) or 0) >= 2 and not context.get("fast_reversal"):
            return False, f"trend still supportive despite {retention:.0%} retention"
        return True, (
            f"age {age_minutes:.1f}m/{required_minutes:.1f}m, retention {retention:.0%} "
            f"< {retention_floor:.0%}, volatility {volatility_ratio:.2f}x; "
            f"{context.get('reason', 'no trend context')}"
        )

    def _candidate_candle_extreme_price(self, candidate: TradeCandidate, latest_time: Optional[datetime]) -> float:
        """Estimate the best reached trade price from 1m candle extremes since entry."""
        if getattr(self, "_is_premium_long_candidate", lambda x: False)(candidate):
            return 0.0
        # `or candidate.price` here meant an OPT candidate with no entry_spot was measured
        # against its own PREMIUM as if it were an index level.
        entry_spot = float(getattr(candidate, "entry_spot", 0.0) or 0.0)
        if entry_spot <= 0:
            return 0.0
        try:
            df = self.candles.get_candles(candidate.instrument, "1min")
        except Exception:
            return 0.0
        if df is None or len(df) == 0:
            return 0.0
        work = df.copy()
        if not isinstance(work.index, pd.DatetimeIndex):
            if "timestamp" not in work.columns:
                return 0.0
            work["timestamp"] = pd.to_datetime(work["timestamp"], errors="coerce")
            work = work.dropna(subset=["timestamp"]).set_index("timestamp")
        if work.empty:
            return 0.0
        work = work.sort_index()
        entry_ts = (
            getattr(candidate, "entry_timestamp", None)
            or getattr(candidate, "signal_timestamp", None)
        )
        if entry_ts is not None:
            entry_ts = pd.Timestamp(entry_ts)
            if entry_ts.tzinfo is not None:
                entry_ts = entry_ts.tz_convert(IST).tz_localize(None)
            # A candidate accepted at 13:02:41 cannot claim the 13:02 candle's
            # high/low because most of that candle happened before entry. Start
            # peak reconstruction with the next one-minute candle, matching the
            # broker-trade path below.
            entry_minute = entry_ts.replace(second=0, microsecond=0)
            work = work[work.index > entry_minute]
        if latest_time is not None:
            latest_ts = pd.Timestamp(latest_time)
            if latest_ts.tzinfo is not None:
                latest_ts = latest_ts.tz_convert(IST).tz_localize(None)
            work = work[work.index <= latest_ts]
        if work.empty:
            return 0.0
        if str(getattr(candidate, "direction", "") or "").upper() == "SHORT":
            if "low" not in work.columns:
                return 0.0
            favorable_spot = float(work["low"].astype(float).min())
        else:
            if "high" not in work.columns:
                return 0.0
            favorable_spot = float(work["high"].astype(float).max())
        if favorable_spot <= 0:
            return 0.0
        return float(candidate.price) + (favorable_spot - entry_spot)

    def _trade_candle_extreme_price(self, trade, latest_time: Optional[datetime]) -> float:
        """Estimate best reached active trade price from 1m candle extremes since entry."""
        inst_type = str(getattr(trade, "inst_type", "FUT") or "FUT").upper()
        entry_price = float(getattr(trade, "entry_price", 0.0) or 0.0)
        if entry_price <= 0:
            return 0.0
        try:
            df = self.candles.get_candles(trade.instrument, "1min")
        except Exception:
            return 0.0
        if df is None or len(df) == 0:
            return 0.0
        work = df.copy()
        if not isinstance(work.index, pd.DatetimeIndex):
            if "timestamp" not in work.columns:
                return 0.0
            work["timestamp"] = pd.to_datetime(work["timestamp"], errors="coerce")
            work = work.dropna(subset=["timestamp"]).set_index("timestamp")
        if work.empty:
            return 0.0
        work = work.sort_index()
        entry_ts = getattr(trade, "entry_time", None)
        if entry_ts is not None:
            entry_ts = pd.Timestamp(entry_ts)
            if entry_ts.tzinfo is not None:
                entry_ts = entry_ts.tz_convert(IST).tz_localize(None)
            
            # ─────────────────────────────────────────────────────────────
            # FIX: Exclude the entry minute candle entirely from the peak!
            # ─────────────────────────────────────────────────────────────
            entry_minute = entry_ts.replace(second=0, microsecond=0)
            work = work[work.index > entry_minute]
            
        if latest_time is not None:
            latest_ts = pd.Timestamp(latest_time)
            if latest_ts.tzinfo is not None:
                latest_ts = latest_ts.tz_convert(IST).tz_localize(None)
            work = work[work.index <= latest_ts]
        if work.empty:
            return 0.0
        direction = str(getattr(trade, "direction", "") or "").upper()
        if direction == "SHORT":
            if "low" not in work.columns:
                return 0.0
            favorable_spot = float(work["low"].astype(float).min())
        else:
            if "high" not in work.columns:
                return 0.0
            favorable_spot = float(work["high"].astype(float).max())
        if favorable_spot <= 0:
            return 0.0
        if inst_type == "OPT":
            multiplier = float(getattr(trade, "instrument_multiplier", 0.0) or 0.0)
            entry_spot = float(getattr(trade, "entry_spot", 0.0) or 0.0)
            if entry_spot <= 0 or multiplier == 0:
                return 0.0
            return max(1.0, entry_price + ((favorable_spot - entry_spot) * multiplier))
        return self._fut_price_from_spot_level(trade, favorable_spot)

    def _candidate_stop_hit(self, candidate: TradeCandidate, current_price: float) -> bool:
        stop = float(getattr(candidate, "stop", 0.0) or 0.0)
        if stop <= 0:
            return False
        if self._is_premium_long_candidate(candidate) or candidate.direction == "LONG":
            return current_price <= stop
        return current_price >= stop

    def _candidate_target_hit(self, candidate: TradeCandidate, current_price: float) -> bool:
        target = float(getattr(candidate, "target", 0.0) or 0.0)
        if target <= 0:
            return False
        if self._is_premium_long_candidate(candidate) or candidate.direction == "LONG":
            return current_price >= target
        return current_price <= target

    def _candidate_exit_resolution(
        self,
        candidate: TradeCandidate,
        observed_price: float,
        default_reason: str,
        default_text: str,
    ) -> Tuple[float, str, str]:
        """Clamp manual/live exits to already-breached SL/TP before using a later signal price."""
        semantic_exit_reasons = {
            "REPAINT_ABORT",
            "OPPOSITE_SIGNAL",
            "OI_PCR_REVERSAL",
            "INTEL_FLIP",
            "LOW_GAIN_PROTECT",
            "STAGNATION_EXIT",
            "EOD_LOSS_MINIMIZE",
            "SMART_PROFIT_LOCK",
            "MAJOR_WIN_GUARD",
            "BROKER_UNAVAILABLE",
            "QUOTE_INVALID",
            "MANUAL_EXIT",
            "KILL_ALL",
        }
        if str(default_reason or "").upper() in semantic_exit_reasons:
            return observed_price, default_reason, default_text
        if self._candidate_stop_hit(candidate, observed_price):
            return observed_price, "STOP_HIT", "Stoploss hit"
        if self._candidate_target_hit(candidate, observed_price):
            return observed_price, "TARGET_HIT", "Target hit"
        return observed_price, default_reason, default_text

    def _normalize_loaded_exit_candidate(self, candidate: TradeCandidate) -> bool:
        return normalize_loaded_exit_candidate(
            candidate,
            futures_sl_pct=float(getattr(self, "futures_sl_pct", 0.2) or 0.2),
            options_sl_pct=float(getattr(self, "options_sl_pct", 15.0) or 15.0),
            candidate_exit_resolution=self._candidate_exit_resolution,
            candidate_net_pnl=self._candidate_net_pnl,
        )

    def _candidate_history_key(self, candidate: TradeCandidate) -> str:
        """Stable per-session key so refreshed signal rows update in place.
        Buckets to the minute to prevent jitter between live signals and backfill."""
        ts = getattr(candidate, "signal_timestamp", None)
        if ts is None:
            ts = datetime.now(IST).replace(tzinfo=None)
            candidate.signal_timestamp = ts
        elif getattr(ts, "tzinfo", None) is not None:
            ts = ts.astimezone(IST).replace(tzinfo=None)
            candidate.signal_timestamp = ts

        ts_minute = ts.replace(second=0, microsecond=0)
        return "|".join([
            candidate.instrument,
            candidate.timeframe,
            getattr(candidate, "action", "ENTRY") or "ENTRY",
            candidate.direction,
            ts_minute.isoformat(),
        ])

    def _candidate_lifecycle_key(self, candidate: TradeCandidate) -> str:
        """Pair one accepted entry with its later exit without using execution time."""
        source_ts = (
            getattr(candidate, "source_signal_timestamp", None)
            or getattr(candidate, "signal_timestamp", None)
        )
        if source_ts is None:
            source_ts = datetime.min
        elif getattr(source_ts, "tzinfo", None) is not None:
            source_ts = source_ts.astimezone(IST).replace(tzinfo=None)
        return "|".join([
            str(getattr(candidate, "instrument", "") or ""),
            str(getattr(candidate, "timeframe", "") or ""),
            str(getattr(candidate, "direction", "") or ""),
            source_ts.isoformat(),
        ])

    @staticmethod
    def _candidate_direction(candidate: TradeCandidate) -> str:
        return str(getattr(candidate, "direction", "") or "").upper()

    @staticmethod
    def _same_trade_side(candidate: TradeCandidate, previous: TradeCandidate) -> bool:
        fields = ("direction", "timeframe", "inst_type", "option_type")
        return all(
            str(getattr(candidate, field, "") or "").upper()
            == str(getattr(previous, field, "") or "").upper()
            for field in fields
        )

    @staticmethod
    def _explicit_reversal_context(candidate: TradeCandidate) -> bool:
        if bool(getattr(candidate, "market_wide_reversal_entry", False)):
            return True
        if bool(getattr(candidate, "market_wide_reversal_context", None)):
            return True
        mode = str(getattr(candidate, "strategy_direction_mode", "") or "").upper()
        if "REVERS" in mode:
            return True
        reasons = " ".join(str(item) for item in (getattr(candidate, "reasons", []) or []))
        return "reversal" in reasons.lower()

    def _should_supersede_session_entry(self, candidate: TradeCandidate, previous: TradeCandidate) -> bool:
        candidate_direction = self._candidate_direction(candidate)
        previous_direction = self._candidate_direction(previous)
        if candidate_direction and previous_direction:
            if candidate_direction == previous_direction:
                return False
            return {candidate_direction, previous_direction} == {"LONG", "SHORT"}
        if not self._explicit_reversal_context(candidate):
            return False
        return float(getattr(candidate, "confidence", 0.0) or 0.0) > float(
            getattr(previous, "confidence", 0.0) or 0.0
        )

    def _refresh_same_direction_session_lifecycle(self, candidate: TradeCandidate, previous: TradeCandidate) -> bool:
        """Treat same-side refreshes as the same live idea, not an exit reason."""
        if not self._same_trade_side(candidate, previous):
            return False
        source_ts = (
            getattr(previous, "source_signal_timestamp", None)
            or getattr(previous, "signal_timestamp", None)
        )
        if source_ts is not None:
            setattr(candidate, "source_signal_timestamp", source_ts)
            setattr(candidate, "signal_timestamp", source_ts)
        entry_ts = getattr(previous, "entry_timestamp", None)
        if entry_ts is not None:
            setattr(candidate, "entry_timestamp", entry_ts)
        for attr in (
            "price",
            "stop",
            "target",
            "spot_stop",
            "spot_target",
            "initial_stop",
            "entry_spot",
            "accepted_by_gate",
        ):
            if hasattr(previous, attr):
                setattr(candidate, attr, getattr(previous, attr))
        return True

    @staticmethod
    def _candidate_minute_bucket(value) -> Optional[datetime]:
        if value is None:
            return None
        if getattr(value, "tzinfo", None) is not None:
            value = value.astimezone(IST).replace(tzinfo=None)
        return value.replace(second=0, microsecond=0)

    def _same_side_refresh_identity(self, candidate: TradeCandidate) -> tuple:
        return (
            str(getattr(candidate, "instrument", "") or "").upper(),
            str(getattr(candidate, "timeframe", "") or "").upper(),
            str(getattr(candidate, "direction", "") or "").upper(),
            str(getattr(candidate, "inst_type", "") or "").upper(),
            str(getattr(candidate, "option_type", "") or "").upper(),
        )

    def _repair_same_side_superseded_session_rows(self) -> bool:
        """Remove legacy same-side refresh rows that were closed as SUPERSEDED_SIGNAL."""
        store = getattr(self, "_session_trade_candidates", {}) or {}
        repaired = False
        for instrument, book in list(store.items()):
            if not book:
                continue
            entry_by_lifecycle = {}
            entry_by_side_minute = {}
            for key, row in list(book.items()):
                if str(getattr(row, "action", "ENTRY") or "ENTRY").upper() != "ENTRY":
                    continue
                entry_by_lifecycle[self._candidate_lifecycle_key(row)] = key
                side_key = self._same_side_refresh_identity(row)
                minute_key = self._candidate_minute_bucket(getattr(row, "signal_timestamp", None))
                if minute_key is not None:
                    entry_by_side_minute[(side_key, minute_key)] = key

            remove_keys = set()
            for key, row in list(book.items()):
                if str(getattr(row, "action", "ENTRY") or "ENTRY").upper() != "EXIT":
                    continue
                if str(getattr(row, "exit_reason", "") or "").upper() != "SUPERSEDED_SIGNAL":
                    continue
                exit_ts = getattr(row, "exit_timestamp", None) or getattr(row, "signal_timestamp", None)
                minute_key = self._candidate_minute_bucket(exit_ts)
                if minute_key is None:
                    continue
                refresh_key = entry_by_side_minute.get((self._same_side_refresh_identity(row), minute_key))
                old_entry_key = entry_by_lifecycle.get(self._candidate_lifecycle_key(row))
                if refresh_key is None or refresh_key == old_entry_key:
                    continue
                remove_keys.add(key)
                if old_entry_key:
                    remove_keys.add(old_entry_key)

            if remove_keys:
                for key in remove_keys:
                    book.pop(key, None)
                repaired = True
                logger.info(
                    f"Repaired {len(remove_keys)} legacy same-side SUPERSEDED_SIGNAL session row(s) for {instrument}"
                )
        return repaired

    def _absorb_same_direction_session_refresh(self, candidate: TradeCandidate) -> bool:
        """Keep a same-side fresh signal inside the active lifecycle instead of re-entering."""
        if not candidate or getattr(self, "mode", "") == "HISTORICAL":
            return False
        if str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper() == "EXIT":
            return False
        signal_ts = getattr(candidate, "signal_timestamp", None)
        if signal_ts is None:
            return False
        for previous in self._active_session_entry_candidates(candidate.instrument):
            prev_ts = getattr(previous, "signal_timestamp", None)
            if not prev_ts or signal_ts <= prev_ts:
                continue
            if self._candidate_history_key(previous) == self._candidate_history_key(candidate):
                continue
            if not self._same_trade_side(candidate, previous):
                continue
            self._refresh_same_direction_session_lifecycle(candidate, previous)
            self.log_event(
                f"Same-direction refresh absorbed: {candidate.instrument} {candidate.timeframe} "
                f"{candidate.direction}; existing lifecycle retained.",
                "trade",
            )
            return True
        return False

    @staticmethod
    def _candidate_chronology_valid(candidate: TradeCandidate) -> bool:
        if str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper() != "EXIT":
            return True
        entry_ts = getattr(candidate, "entry_timestamp", None)
        exit_ts = getattr(candidate, "exit_timestamp", None)
        if not entry_ts or not exit_ts:
            return True
        if getattr(entry_ts, "tzinfo", None) is not None:
            entry_ts = entry_ts.astimezone(IST).replace(tzinfo=None)
        if getattr(exit_ts, "tzinfo", None) is not None:
            exit_ts = exit_ts.astimezone(IST).replace(tzinfo=None)
        return exit_ts >= entry_ts

    def _inherit_exit_entry_metadata(
        self,
        exit_candidate: TradeCandidate,
        entry_candidate: Optional[TradeCandidate],
    ) -> None:
        """Keep source-candle and accepted-entry clocks intact on an exit row."""
        if not exit_candidate or not entry_candidate:
            return
        source_ts = (
            getattr(entry_candidate, "source_signal_timestamp", None)
            or getattr(entry_candidate, "signal_timestamp", None)
        )
        if source_ts is not None:
            setattr(exit_candidate, "source_signal_timestamp", source_ts)
            exit_candidate.signal_timestamp = source_ts
        entry_ts = getattr(entry_candidate, "entry_timestamp", None)
        if entry_ts is not None:
            setattr(exit_candidate, "entry_timestamp", entry_ts)
        for attr in (
            "source_engine",
            "source_lane",
            "quad_union_entry",
            "raw_union_entry",
            "scalp_lock_mode",
            "market_wide_reversal_entry",
            "one_way_cascade_entry",
            "one_way_cascade_context",
            "power_move",
            "volume_spike_entry",
            "fifteen_min_choppy_scalp_entry",
            "fifteen_min_choppy_scalp_context",
            "volume_ratio",
            "range_atr_ratio",
            "close_location",
            "quote_verified",
            "quote_source",
            "entry_quote_verified",
            "entry_quote_source",
            "execution_bid_price",
            "execution_ask_price",
            "execution_touch_source",
            "execution_touch_age_seconds",
            "execution_touch_usable",
            "execution_touch_reason",
            "market_regime",
            "intelligence_score",
            "strategy_revision",
            "strategy_direction_mode",
            "data_provenance",
            "price_action_verdict",
            "price_action_score",
            "adx_value",
            "impulse_confirmed",
            "is_explosive_bypass",
            "entry_spot",
            "initial_stop",
            "source_lane",
            "location_risk",
            "location_position_pct",
            "location_decision",
        ):
            if hasattr(entry_candidate, attr):
                setattr(exit_candidate, attr, getattr(entry_candidate, attr))
        if hasattr(entry_candidate, "source_engines"):
            setattr(exit_candidate, "source_engines", list(getattr(entry_candidate, "source_engines", []) or []))
        # Copied, not referenced: the entry row keeps accumulating samples on some exit
        # routes, and a shared list would let the recorded path grow after the exit.
        if hasattr(entry_candidate, "pnl_path"):
            setattr(exit_candidate, "pnl_path", list(getattr(entry_candidate, "pnl_path", []) or []))
        # The intel that produced the ENTRY, carried onto the exit row so the outcome
        # and the conditions that preceded it land in the same record.
        if getattr(entry_candidate, "entry_intel", None):
            setattr(exit_candidate, "entry_intel", dict(getattr(entry_candidate, "entry_intel") or {}))

    def _get_current_session_day(self) -> str:
        now_ist = datetime.now(IST)
        if now_ist.hour < 9 or (now_ist.hour == 9 and now_ist.minute < 15):
            return (now_ist - timedelta(days=1)).date().isoformat()
        else:
            return now_ist.date().isoformat()

    def _session_candidates_path(self) -> List[Path]:
        """Return list of session candidate file paths to load.
        In HISTORICAL mode with backtest_days > 1, returns multiple date files.
        In REAL mode or 1-day backtest, returns single day file."""
        if getattr(self, "mode", "") == "HISTORICAL":
            backtest_days = getattr(self, "backtest_days", 1)
            if backtest_days <= 1:
                # For 1-day backtest, load yesterday's session (most recent trading day)
                day = self._get_current_session_day()
                candidate_path = self._session_candidate_dir / f"{day}.json"
                if candidate_path.exists():
                    return [candidate_path]
                return [self._session_candidate_dir / "historical.json"]
            
            # For multi-day backtest, load the last N session files
            # Get all available session files sorted by date
            all_files = sorted(
                [f for f in self._session_candidate_dir.glob("*.json") if f.name != "historical.json"],
                key=lambda x: x.name
            )
            # Take the last backtest_days files
            return all_files[-backtest_days:] if len(all_files) >= backtest_days else all_files
        
        # REAL mode: load today's session file
        day = getattr(self, "_session_candidate_day", None) or self._get_current_session_day()
        return [self._session_candidate_dir / f"{day}.json"]

    def _latest_session_candidate_file(self, require_candidates: bool = False) -> Optional[Path]:
        """Most recent persisted session ledger, used for weekend/holiday display."""
        try:
            files = sorted(
                [f for f in self._session_candidate_dir.glob("*.json") if f.name != "historical.json"],
                key=lambda x: x.name,
            )
            if require_candidates:
                files = [
                    f for f in files
                    if len(json.loads(f.read_text(encoding="utf-8")).get("candidates", []) or []) > 0
                ]
            return files[-1] if files else None
        except Exception:
            return None

    def _candidate_from_payload(self, payload: Dict[str, Any]) -> Optional[TradeCandidate]:
        try:
            raw_ts = (
                payload.get("signal_timestamp")
                or payload.get("source_signal_timestamp")
                or payload.get("timestamp")
            )
            signal_ts = None
            if raw_ts:
                signal_ts = datetime.fromisoformat(str(raw_ts))
                if signal_ts.tzinfo is not None:
                    signal_ts = signal_ts.astimezone(IST).replace(tzinfo=None)
            reasons = list(payload.get("reasons") or [])
            exit_reason = str(payload.get("exit_reason") or "")
            if exit_reason.upper() == "STOP_HIT" and any(
                "repainted" in str(reason).lower()
                for reason in reasons
            ):
                exit_reason = "REPAINT_ABORT"
            candidate = TradeCandidate(
                instrument=str(payload.get("instrument", "")),
                direction=str(payload.get("direction", "")),
                price=float(payload.get("price") or 0.0),
                stop=float(payload.get("current_stop") or payload.get("stop") or 0.0),
                target=float(payload.get("current_target") or payload.get("target") or 0.0),
                lots=int(payload.get("lots") or 1),
                lot_size=int(payload.get("lot_size") or 1),
                grade=str(payload.get("grade") or "B+"),
                confidence=float(payload.get("confidence") or 0.0),
                timeframe=str(payload.get("timeframe") or "5min"),
                inst_type=str(payload.get("inst_type") or ""),
                option_type=str(payload.get("option_type") or ""),
                atm_strike=float(payload.get("atm_strike") or 0.0),
                multiplier=float(payload.get("multiplier") or 1.0),
                trading_symbol=str(payload.get("trading_symbol") or ""),
                symbol_token=str(payload.get("symbol_token") or ""),
                rr=float(payload.get("rr") or 1.5),
                score=float(payload.get("score") or 0.0),
                reasons=reasons,
                spot_stop=float(payload.get("spot_stop") or 0.0),
                spot_target=float(payload.get("spot_target") or 0.0),
                signal_timestamp=signal_ts,
                current_price=float(payload.get("current_price") or payload.get("price") or 0.0),
                pnl=float(payload.get("pnl") or 0.0),
                status=str(payload.get("status") or "TRADE SIGNAL"),
                action=str(payload.get("action") or "ENTRY"),
                exit_reason=exit_reason,
                adx_value=float(payload.get("adx_value") or 0.0),
                impulse_confirmed=bool(payload.get("impulse_confirmed") or False),
                is_explosive_bypass=bool(payload.get("is_explosive_bypass") or False),
                power_move=bool(payload.get("power_move") or False),
                fifteen_min_choppy_scalp_entry=bool(payload.get("fifteen_min_choppy_scalp_entry") or False),
                source_engine=str(payload.get("source_engine") or ""),
                source_engines=list(payload.get("source_engines") or []),
                source_lane=str(payload.get("source_lane") or ""),
                quad_union_entry=bool(payload.get("quad_union_entry") or False),
                raw_union_entry=bool(payload.get("raw_union_entry") or False),
                scalp_lock_mode=bool(payload.get("scalp_lock_mode") or False),
                one_way_cascade_entry=bool(payload.get("one_way_cascade_entry") or False),
            )
            setattr(candidate, "peak_pnl", float(payload.get("peak_pnl") or 0.0))
            setattr(candidate, "max_drawdown", float(payload.get("max_drawdown") or 0.0))
            setattr(candidate, "pnl_path", [
                (float(row[0]), float(row[1]))
                for row in (payload.get("pnl_path") or [])
                if isinstance(row, (list, tuple)) and len(row) >= 2
            ])
            setattr(candidate, "trade_id", str(payload.get("id") or payload.get("trade_id") or ""))
            setattr(candidate, "runner_mode", bool(payload.get("runner_mode") or False))
            setattr(candidate, "initial_stop", float(payload.get("initial_stop") or 0.0))
            self._ensure_trade_like_initial_stop(candidate)
            setattr(candidate, "display_stop", float(payload.get("display_stop") or payload.get("stop") or candidate.stop or 0.0))
            setattr(candidate, "display_target", float(payload.get("display_target") or payload.get("target") or candidate.target or 0.0))
            setattr(candidate, "entry_spot", float(payload.get("entry_spot") or 0.0))
            setattr(candidate, "scalp_lock_mode", bool(payload.get("scalp_lock_mode") or False))
            setattr(candidate, "location_risk", str(payload.get("location_risk") or ""))
            setattr(candidate, "location_position_pct", float(payload.get("location_position_pct") or 0.0))
            setattr(candidate, "location_decision", str(payload.get("location_decision") or "ALLOW"))
            setattr(candidate, "accepted_by_gate", bool(payload.get("accepted_by_gate") or False))
            setattr(candidate, "watch_only", bool(payload.get("watch_only") or False))
            setattr(candidate, "market_wide_reversal_entry", bool(payload.get("market_wide_reversal_entry") or False))
            setattr(candidate, "one_way_cascade_entry", bool(payload.get("one_way_cascade_entry") or False))
            cascade_ctx = payload.get("one_way_cascade_context") or {}
            setattr(candidate, "one_way_cascade_context", cascade_ctx if isinstance(cascade_ctx, dict) else {})
            setattr(candidate, "fifteen_min_choppy_scalp_entry", bool(payload.get("fifteen_min_choppy_scalp_entry") or False))
            scalp_ctx = payload.get("fifteen_min_choppy_scalp_context") or {}
            setattr(candidate, "fifteen_min_choppy_scalp_context", scalp_ctx if isinstance(scalp_ctx, dict) else {})
            setattr(candidate, "source_engine", str(payload.get("source_engine") or ""))
            setattr(candidate, "source_engines", list(payload.get("source_engines") or []))
            setattr(candidate, "source_lane", str(payload.get("source_lane") or ""))
            setattr(candidate, "quad_union_entry", bool(payload.get("quad_union_entry") or False))
            setattr(candidate, "raw_union_entry", bool(payload.get("raw_union_entry") or False))
            setattr(candidate, "quote_verified", bool(payload.get("quote_verified") or False))
            setattr(candidate, "quote_source", str(payload.get("quote_source") or ""))
            setattr(candidate, "entry_quote_verified", bool(payload.get("entry_quote_verified", payload.get("quote_verified")) or False))
            setattr(candidate, "entry_quote_source", str(payload.get("entry_quote_source") or ""))
            setattr(candidate, "live_quote_stale", bool(payload.get("live_quote_stale") or False))
            setattr(candidate, "execution_bid_price", float(payload.get("execution_bid_price") or 0.0))
            setattr(candidate, "execution_ask_price", float(payload.get("execution_ask_price") or 0.0))
            setattr(candidate, "execution_touch_source", str(payload.get("execution_touch_source") or ""))
            setattr(candidate, "execution_touch_age_seconds", float(payload.get("execution_touch_age_seconds") or 0.0))
            setattr(candidate, "execution_touch_usable", bool(payload.get("execution_touch_usable") or False))
            setattr(candidate, "execution_touch_reason", str(payload.get("execution_touch_reason") or ""))
            # Advanced telemetry — round-tripped so restored session candidates keep
            # the regime/intel/strategy/price-action context shown on the dashboard.
            setattr(candidate, "market_regime", str(payload.get("market_regime") or ""))
            mi_ctx = payload.get("market_intelligence_context") or {}
            if isinstance(mi_ctx, dict):
                setattr(candidate, "market_intelligence_context", mi_ctx)
            setattr(candidate, "intelligence_score", float(payload.get("intelligence_score") or 0.0))
            setattr(candidate, "strategy_revision", str(payload.get("strategy_revision") or ""))
            setattr(candidate, "strategy_direction_mode", str(payload.get("strategy_direction_mode") or ""))
            setattr(candidate, "data_provenance", str(payload.get("data_provenance") or ""))
            setattr(candidate, "price_action_verdict", str(payload.get("price_action_verdict") or ""))
            setattr(candidate, "price_action_score", float(payload.get("price_action_score") or 0.0))
            setattr(
                candidate,
                "signal_fire_mode",
                str(payload.get("signal_fire_mode") or "INTRACANDLE"),
            )
            setattr(
                candidate,
                "entered_intracandle",
                bool(payload.get("entered_intracandle", True)),
            )
            raw_entry_ts = payload.get("entry_timestamp") or payload.get("timestamp")
            if raw_entry_ts:
                try:
                    entry_ts = datetime.fromisoformat(str(raw_entry_ts))
                    if entry_ts.tzinfo is not None:
                        entry_ts = entry_ts.astimezone(IST).replace(tzinfo=None)
                    setattr(candidate, "entry_timestamp", entry_ts)
                except Exception:
                    pass
            if signal_ts is not None:
                setattr(candidate, "source_signal_timestamp", signal_ts)
            setattr(
                candidate,
                "source_signal_type",
                str(
                    payload.get("source_signal_type")
                    or ("BUY" if candidate.direction == "LONG" else "SELL")
                ),
            )
            raw_exit_ts = payload.get("exit_timestamp")
            exit_ts = None
            if raw_exit_ts:
                exit_ts = datetime.fromisoformat(str(raw_exit_ts))
                if exit_ts.tzinfo is not None:
                    exit_ts = exit_ts.astimezone(IST).replace(tzinfo=None)
            if exit_ts:
                setattr(candidate, "exit_timestamp", exit_ts)
            if str(getattr(candidate, "action", "ENTRY") or "").upper() == "EXIT":
                exit_price = float(payload.get("exit_price") or candidate.current_price or candidate.price or 0.0)
                if exit_price > 0:
                    candidate.current_price = exit_price
                    setattr(candidate, "exit_price", exit_price)
            return candidate
        except Exception as exc:
            logger.debug(f"Skipping invalid session candidate payload: {exc}")
            return None

    def _active_session_entry_candidates(self, instrument: str, timeframe: Optional[str] = None, as_of: Optional[datetime] = None) -> List[TradeCandidate]:
        """Return remembered entry rows that do not already have a later exit row."""
        rows = self._get_session_trade_candidates(instrument)
        exit_cutoffs: Dict[str, datetime] = {}
        for row in rows:
            if getattr(row, "action", "ENTRY") != "EXIT":
                continue
            key = self._candidate_lifecycle_key(row)
            exit_ts = getattr(row, "exit_timestamp", None) or getattr(row, "signal_timestamp", None)
            if not exit_ts:
                continue
            if as_of and exit_ts > as_of:
                continue
            if key not in exit_cutoffs or exit_ts > exit_cutoffs[key]:
                exit_cutoffs[key] = exit_ts

        active = []
        for row in rows:
            if getattr(row, "action", "ENTRY") in ("EXIT", "NO_ENTRY"):
                continue
            if timeframe and row.timeframe != timeframe:
                continue
            entry_ts = getattr(row, "signal_timestamp", None)
            if as_of and entry_ts and entry_ts > as_of:
                continue
            exit_ts = exit_cutoffs.get(self._candidate_lifecycle_key(row))
            if exit_ts and entry_ts and exit_ts >= entry_ts:
                continue
            active.append(row)
        return active

    def _candidate_valid_for_live_restore(self, candidate: TradeCandidate) -> bool:
        """Strict startup quarantine for stale REAL-mode signal rows."""
        if getattr(self, "mode", "") == "HISTORICAL" or not self._intracandle_signals_enabled():
            return True
        if not self._candidate_matches_live_session_day(candidate):
            return False
        action = str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper()
        if action == "NO_ENTRY":
            return False
        if action == "EXIT":
            return True
        if bool(getattr(candidate, "accepted_by_gate", False)):
            return True
        signal_ts = getattr(candidate, "signal_timestamp", None)
        if not signal_ts:
            return False
        if not self._live_signal_candle_has_closed(candidate, signal_ts, self._session_squareoff_clock()):
            return False
        if not self._signal_in_restart_recovery_window(signal_ts, getattr(candidate, "timeframe", "5min")):
            return False
        return True

    def _signal_in_restart_recovery_window(
        self,
        signal_ts,
        timeframe: str,
        now: Optional[datetime] = None,
    ) -> bool:
        """Allow only the most recent just-closed candle after a live restart."""
        if getattr(self, "mode", "") == "HISTORICAL" or signal_ts is None:
            return False

        started_at = getattr(self, "_process_started_at", None)
        if not started_at:
            return False

        sig_check = signal_ts.astimezone(IST).replace(tzinfo=None) if getattr(signal_ts, "tzinfo", None) is not None else signal_ts
        start_check = started_at.astimezone(IST).replace(tzinfo=None) if getattr(started_at, "tzinfo", None) is not None else started_at
        now = now or self._session_squareoff_clock()
        now_check = now.astimezone(IST).replace(tzinfo=None) if getattr(now, "tzinfo", None) is not None else now

        expires_at = self._live_signal_processing_deadline(signal_ts, timeframe)
        if expires_at is None:
            return False

        # A pre-start signal is recoverable only if the app restarted before
        # the recovery window expired, and the current scan is still inside it.
        if sig_check >= start_check:
            return now_check <= expires_at
        return start_check <= expires_at and now_check <= expires_at

    def _live_signal_processing_deadline(
        self,
        signal_ts,
        timeframe: str,
    ) -> Optional[datetime]:
        """Deadline for admitting a finalized live signal into stabilization."""
        if signal_ts is None:
            return None
        sig_check = signal_ts.astimezone(IST).replace(tzinfo=None) if getattr(signal_ts, "tzinfo", None) is not None else signal_ts
        started_at = getattr(self, "_process_started_at", None)
        start_check = (
            started_at.astimezone(IST).replace(tzinfo=None)
            if getattr(started_at, "tzinfo", None) is not None
            else started_at
        )
        tf_minutes = {"1min": 1, "5min": 5, "15min": 15}.get(str(timeframe or ""), 5)
        grace_seconds = max(0.0, float(getattr(get_settings(), "live_restart_recovery_grace_seconds", 120.0) or 120.0))
        close_time = sig_check + timedelta(minutes=tf_minutes)
        timeframe_name = str(timeframe or "")
        if timeframe_name in {"5min", "15min"} and start_check is not None:
            if start_check <= close_time:
                # Scanner was already running when the candle closed: allow a
                # slow-refresh grace so a busy scan can still finish processing it.
                grace_setting = (
                    "live_signal_post_close_grace_seconds_15min"
                    if timeframe_name == "15min"
                    else "live_signal_post_close_grace_seconds_5min"
                )
                grace_seconds = max(
                    grace_seconds,
                    float(
                        getattr(
                            get_settings(),
                            grace_setting,
                            300.0,
                        )
                        or 300.0
                    ),
                )
            else:
                # Scanner RESTARTED after the candle closed. Recover only the most
                # recent just-closed candle, for a fixed per-timeframe window measured
                # from candle close: 180s (5min) / 360s (15min). Older candles fall
                # past their deadline and are ignored. (Without this, a 15min signal
                # that closed >120s before a restart was dropped as a stale echo.)
                restart_setting = (
                    "live_restart_recovery_grace_seconds_15min"
                    if timeframe_name == "15min"
                    else "live_restart_recovery_grace_seconds_5min"
                )
                restart_default = 360.0 if timeframe_name == "15min" else 180.0
                grace_seconds = max(
                    grace_seconds,
                    float(getattr(get_settings(), restart_setting, restart_default) or restart_default),
                )
        return close_time + timedelta(seconds=grace_seconds)

    def _load_session_trade_candidates(self) -> None:
        """Load session candidates from SQLite on startup to prevent dashboard amnesia."""
        desired_session_day = (
            self.historical_session_cutoff_date().isoformat()
            if getattr(self, "mode", "") == "HISTORICAL"
            else getattr(self, "_session_candidate_day", self._get_current_session_day())
        )
        if (
            getattr(self, "mode", "") == "HISTORICAL"
            and getattr(self, "_hist_candidates_loaded", False)
            and getattr(self, "_loaded_session_candidate_day", "") == desired_session_day
        ):
            return
        
        self._session_trade_candidates = {}
        session_day = desired_session_day
        self._loaded_session_candidate_day = session_day
        
        try:
            payloads = db.load_session_signals(session_day)
            self._loaded_session_payload_count = len(payloads)
            count = 0
            for item in payloads:
                candidate = self._candidate_from_payload(item)
                if not candidate or not candidate.instrument:
                    continue
                if not self._candidate_valid_for_live_restore(candidate):
                    logger.info(
                        f"Quarantined stale session candidate on startup: "
                        f"{candidate.instrument} {candidate.timeframe} {candidate.direction} "
                        f"{getattr(candidate, 'signal_timestamp', None)}"
                    )
                    continue
                self._normalize_loaded_exit_candidate(candidate)
                self._resubscribe_loaded_candidate_quote(candidate)
                book = self._session_trade_candidates.setdefault(candidate.instrument, {})
                book[self._candidate_history_key(candidate)] = candidate
                count += 1
                
            if count:
                logger.info(f"Restored {count} session signal row(s) from SQLite for {session_day}")
            if self._repair_same_side_superseded_session_rows():
                self._persist_session_trade_candidates()
            # Mid-session restart wipes in-memory diagnostics. Rebuild exit/reject
            # counters from the restored day ledger so the Diagnostics panel is
            # not stuck empty while the engine continues trading.
            if getattr(self, "mode", "") != "HISTORICAL":
                self._rehydrate_live_diagnostics_from_session(session_day)
        except Exception as exc:
            logger.warning(f"Could not restore session signal ledger from DB: {exc}")
        
        # Mark as loaded in HISTORICAL mode
        if getattr(self, "mode", "") == "HISTORICAL":
            self._hist_candidates_loaded = True

    def _rehydrate_live_diagnostics_from_session(self, session_day: str) -> None:
        """Rebuild in-memory diagnostics after a live mid-session process restart.

        Reject/exit counters live only in RAM. After a Fyers token refresh force-
        restart they start empty even though SQLite still has today's session
        rows and signal decisions. Replace (not add) from the day ledger so a
        second load of the same session day cannot double-count.
        """
        if getattr(self, "mode", "") == "HISTORICAL":
            return
        day = str(session_day or "")
        if not day:
            return
        if getattr(self, "_diagnostics_rehydrated_day", "") == day:
            return

        diagnostics = getattr(self, "_diagnostics", None)
        if not isinstance(diagnostics, dict):
            self._diagnostics = {}
            diagnostics = self._diagnostics

        restored_exit_reasons: Dict[str, int] = {}
        exit_seeded = 0
        for book in list((getattr(self, "_session_trade_candidates", {}) or {}).values()):
            for cand in list(book.values()):
                action = str(getattr(cand, "action", "") or "").upper()
                is_exit = action == "EXIT" or bool(getattr(cand, "is_exit", False))
                if not is_exit:
                    continue
                reason = str(getattr(cand, "exit_reason", "") or "").strip() or "UNKNOWN_EXIT"
                restored_exit_reasons[reason] = int(restored_exit_reasons.get(reason, 0) or 0) + 1
                exit_seeded += 1

        restored_rejects: Dict[str, int] = {}
        reject_seeded = 0
        try:
            decisions = db.load_signal_decisions(day) or []
        except Exception as exc:
            logger.debug(f"Could not rehydrate reject diagnostics from signal_decisions: {exc}")
            decisions = []
        for row in decisions:
            status = str((row or {}).get("status") or "").upper()
            if status not in {"REJECTED", "MISSED", "BLOCKED"}:
                continue
            reason = str((row or {}).get("reason") or "").strip() or "Unknown"
            # Keep labels short for the panel (same style as live _emit_signal_decision).
            if len(reason) > 120:
                reason = reason[:117] + "..."
            restored_rejects[reason] = int(restored_rejects.get(reason, 0) or 0) + 1
            reject_seeded += 1

        # Replace buckets from durable day state. Live counters that fire after
        # this point continue to increment normally via _diag_inc.
        diagnostics["exit_reasons"] = restored_exit_reasons
        diagnostics["rejects"] = restored_rejects
        self._diagnostics_rehydrated_day = day

        if exit_seeded or reject_seeded:
            logger.info(
                f"Rehydrated live diagnostics for {day}: "
                f"{exit_seeded} exit reason(s), {reject_seeded} reject/block decision(s)."
            )

    def _record_live_reject(self, reason: str, *, identity: str = "", log_message: str = "") -> None:
        """Count a live-session block in diagnostics (and optionally the activity tape)."""
        label = str(reason or "Unknown").strip() or "Unknown"
        if identity:
            self._diag_inc_unique("rejects", label, str(identity))
        else:
            self._diag_inc("rejects", label)
        if log_message:
            # log_event also mirrors reject-like phrases into signal_decisions.
            self.log_event(log_message, "trade")

    def _resubscribe_loaded_candidate_quote(self, candidate: TradeCandidate) -> None:
        """Restore live quote subscriptions for current-day persisted signal rows."""
        self._subscribe_candidate_quote(candidate, context="restore")

    def _subscribe_candidate_quote(self, candidate: TradeCandidate, context: str = "live") -> None:
        """Subscribe accepted option/future candidates to live contract ticks."""
        if getattr(self, "mode", "") == "HISTORICAL":
            return
        if str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper() != "ENTRY":
            return
        token = str(getattr(candidate, "symbol_token", "") or "").strip()
        if not token or not getattr(self, "data", None) or not hasattr(self.data, "subscribe_tokens"):
            return
        inst_type = str(getattr(candidate, "inst_type", "") or "").upper()
        if inst_type not in {"OPT", "FUT"}:
            return
        exchange_type = 3 if str(getattr(candidate, "instrument", "") or "").upper() == "SENSEX" else 2
        try:
            self.data.subscribe_tokens([token], exchange_type=exchange_type)
        except Exception as exc:
            logger.debug(
                "Could not %s live quote subscription for %s %s (%s): %s",
                context,
                getattr(candidate, "instrument", ""),
                getattr(candidate, "trading_symbol", ""),
                token,
                exc,
            )

    def _loaded_session_is_current_day(self) -> bool:
        return (
            getattr(self, "_loaded_session_candidate_day", getattr(self, "_session_candidate_day", "")) 
            == getattr(self, "_session_candidate_day", self._get_current_session_day())
        )

    def _persist_session_trade_candidates(self) -> None:
        """Persist today's dashboard signal ledger to SQLite.
        In HISTORICAL mode, does nothing."""
        if getattr(self, "mode", "") == "HISTORICAL":
            return
        
        try:
            rows = []
            self._repair_same_side_superseded_session_rows()
            for book in getattr(self, "_session_trade_candidates", {}).values():
                for candidate in book.values():
                    self._normalize_loaded_exit_candidate(candidate)
                    rows.append(self._serialize_trade_candidate(candidate))
            
            session_day = getattr(self, "_session_candidate_day", self._get_current_session_day())
            
            # Sort chronologically before insert
            rows.sort(key=lambda r: r.get("timestamp") or "", reverse=True)
            if not rows:
                loaded_day = getattr(self, "_loaded_session_candidate_day", "")
                loaded_count = int(getattr(self, "_loaded_session_payload_count", 0) or 0)
                marker = f"{session_day}|{loaded_day}|{loaded_count}"
                if marker != getattr(self, "_last_empty_session_persist_skip", ""):
                    self._last_empty_session_persist_skip = marker
                    if loaded_day == session_day and loaded_count > 0:
                        logger.info(
                            f"Skipped empty session ledger save for {session_day}; "
                            f"{loaded_count} persisted row(s) remain protected."
                        )
                    else:
                        logger.debug(f"Skipped empty session ledger save for {session_day}.")
                return
            try:
                loop = asyncio.get_running_loop()
            except RuntimeError:
                db.save_session_signals(session_day, rows)
                return

            self._session_persist_pending = (session_day, rows)
            task = getattr(self, "_session_persist_task", None)
            if task is None or task.done():
                self._session_persist_task = loop.create_task(
                    self._flush_session_trade_candidates()
                )
            
        except Exception as exc:
            logger.debug(f"Failed to persist session trade candidates to DB: {exc}")

    async def _flush_session_trade_candidates(self) -> None:
        """Coalesce ledger updates and perform SQLite writes outside the event loop."""
        while True:
            pending = getattr(self, "_session_persist_pending", None)
            if pending is None:
                return
            self._session_persist_pending = None
            session_day, rows = pending
            try:
                await asyncio.to_thread(db.save_session_signals, session_day, rows)
            except Exception as exc:
                logger.debug(f"Failed to persist session trade candidates to DB: {exc}")

    def _cleanup_old_session_candidates(self) -> None:
        """Remove session candidate files older than 30 days to manage disk space."""
        try:
            if not self._session_candidate_dir.exists():
                return
            
            cutoff_date = datetime.now(IST) - timedelta(days=30)
            cutoff_str = cutoff_date.strftime("%Y-%m-%d")
            
            for file_path in self._session_candidate_dir.glob("*.json"):
                # Extract date from filename (format: YYYY-MM-DD.json)
                file_date_str = file_path.stem
                if file_date_str < cutoff_str:
                    try:
                        file_path.unlink()
                        logger.info(f"🗑️ Cleaned up old session candidate file: {file_path.name}")
                    except Exception as exc:
                        logger.debug(f"Failed to delete old session file {file_path.name}: {exc}")
        except Exception as exc:
            logger.debug(f"Failed to cleanup old session candidates: {exc}")

    def _ensure_session_candidate_day(self) -> None:
        if getattr(self, "mode", "") == "HISTORICAL":
            desired_session_day = self.historical_session_cutoff_date().isoformat()
            # In HISTORICAL mode, load once per completed-session cutoff.
            if (
                not getattr(self, "_hist_candidates_loaded", False)
                or getattr(self, "_loaded_session_candidate_day", "") != desired_session_day
            ):
                self._load_session_trade_candidates()
                self._hist_candidates_loaded = True
            return
        today = self._get_current_session_day()
        if today == getattr(self, "_session_candidate_day", today):
            loaded_day = getattr(self, "_loaded_session_candidate_day", None)
            if loaded_day is not None and loaded_day != today:
                self._load_session_trade_candidates()
            return
        logger.info(f"Session candidate day rolling over from {self._session_candidate_day} to {today}")
        self._session_candidate_day = today
        self._hist_candidates_loaded = False
        self._load_session_trade_candidates()

    def _remember_trade_candidates(self, candidates: List[TradeCandidate]) -> None:
        """Keep session signal rows visible after later signals arrive."""
        if not candidates:
            return
        for candidate in list(candidates):
            self._rtracker_record_candidate(
                candidate,
                decision=self._rtracker_candidate_decision(candidate),
                reason=str(getattr(candidate, "exit_reason", "") or ""),
                source="session_candidate",
            )
        # Filter out NO_ENTRY candidates from persistence
        candidates = [c for c in candidates if getattr(c, "action", "ENTRY") != "NO_ENTRY"]
        if not candidates:
            return
        self._ensure_session_candidate_day()
        live_counter_mode = str(getattr(self, "mode", "") or "").upper() != "HISTORICAL"
        if live_counter_mode:
            self._reset_daily_counters()
        counted_outcomes = getattr(self, "_counted_outcome_signatures", None)
        if not isinstance(counted_outcomes, set):
            self._counted_outcome_signatures = set()
            counted_outcomes = self._counted_outcome_signatures
        new_exit_outcomes = []
        store = getattr(self, "_session_trade_candidates", None)
        if store is None:
            self._session_trade_candidates = {}
            store = self._session_trade_candidates

        for candidate in candidates:
            action = str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper()
            if action == "ENTRY":
                self._ensure_trade_like_initial_stop(candidate)
            book = store.setdefault(candidate.instrument, {})
            history_key = self._candidate_history_key(candidate)
            existing = book.get(history_key)
            if (
                existing is not None
                and str(getattr(existing, "action", "ENTRY") or "ENTRY").upper() == "ENTRY"
                and str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper() == "ENTRY"
                and bool(getattr(existing, "accepted_by_gate", False))
            ):
                # An accepted signal is an immutable execution snapshot. Re-scans of
                # the same source candle must not replace its contract, entry, or
                # instrument type after settings/quote availability changes.
                continue
            book[history_key] = candidate
            if action == "EXIT" and live_counter_mode:
                signature = self._closed_outcome_signature(candidate)
                if signature not in counted_outcomes:
                    new_exit_outcomes.append(candidate)
            if bool(getattr(candidate, "accepted_by_gate", False)):
                self._subscribe_candidate_quote(candidate)
            if len(book) > 150:
                ordered_keys = sorted(
                    book,
                    key=lambda k: getattr(book[k], "signal_timestamp", None) or datetime.min,
                    reverse=True,
                )
                for old_key in ordered_keys[150:]:
                    book.pop(old_key, None)

        new_exit_outcomes.sort(key=self._closed_outcome_time)
        for outcome in new_exit_outcomes:
            signature = self._closed_outcome_signature(outcome)
            if signature in counted_outcomes:
                continue
            counted_outcomes.add(signature)
            instrument = str(getattr(outcome, "instrument", "") or "").split()[0]
            streak = self._record_consecutive_loss_outcome(
                instrument,
                float(getattr(outcome, "pnl", 0.0) or 0.0),
                str(getattr(outcome, "timeframe", "") or ""),
            )
            exit_time = self._closed_outcome_time(outcome)
            if exit_time != datetime.min:
                self._last_exit_time[instrument] = exit_time
            self._note_index_exit_direction(instrument, outcome)
            logger.info(
                f"📊 {instrument} Exit Tape: uninterrupted same-index losses={streak}"
            )
        self._persist_session_trade_candidates()

    async def _publish_trade_payload_now(self) -> None:
        """Publish an accepted entry without waiting for the scan-cycle epilogue."""
        snapshot = dict(getattr(self, "latest_results", {}) or {})
        snapshot["trades"] = self._build_dashboard_trade_payload()
        snapshot["timestamp"] = datetime.now(IST).isoformat()
        self.latest_results = snapshot
        self._update_dashboard_cache(snapshot)
        if self.on_update:
            try:
                await self.on_update(snapshot)
            except Exception as exc:
                logger.error(f"Failed to publish accepted signal immediately: {exc}")

    def _candidate_matches_live_session_day(self, candidate: TradeCandidate) -> bool:
        """REAL/manual dashboard rows must belong to the active session day."""
        if getattr(self, "mode", "") != "REAL":
            return True
        trade_id = str(getattr(candidate, "trade_id", "") or getattr(candidate, "id", "") or "")
        if trade_id.startswith(("H_", "EOD_")):
            return False
        if not getattr(self, "_process_started_at", None):
            return True
        signal_ts = getattr(candidate, "signal_timestamp", None)
        if not signal_ts:
            return True
        if getattr(signal_ts, "tzinfo", None) is not None:
            signal_day = signal_ts.astimezone(IST).date().isoformat()
        else:
            signal_day = signal_ts.date().isoformat()
        session_day = getattr(self, "_session_candidate_day", self._get_current_session_day())
        return signal_day == session_day

    def _rtracker_record_candidate(
        self,
        candidate: TradeCandidate,
        *,
        decision: str = "",
        reason: str = "",
        source: str = "scanner",
        extra: Optional[Dict[str, Any]] = None,
    ) -> None:
        tracker = getattr(self, "rtracker", None)
        if tracker is None:
            return
        # Record what the gate actually judged. Measured over the 66,027-row
        # archive: volume.volume_ratio populated on 19 rows (0.0%), regime.adx
        # 5.1%, aggregate.score_norm 1.0%, and entry_intel on 0 of 65,423 REJECTED
        # rows. Every volume/ADX/intel/PCR threshold in this system is argued from
        # that archive, and the rejected population — "what did the gate turn away,
        # and was it right" — is exactly the one gate tuning needs.
        #
        # Deliberately NOT entry_intel: that field means "the intel that existed
        # when this entry was ACCEPTED" and is taken once (see
        # test_the_snapshot_is_taken_once). Stamping it at rejection time would
        # rewrite that meaning. Observation only, and it must never be able to cost
        # a record — a failed snapshot leaves the row to be written without it.
        try:
            if not getattr(candidate, "decision_intel", None) and self._setting_enabled(
                getattr(get_settings(), "entry_intel_snapshot_enabled", True), True
            ):
                setattr(candidate, "decision_intel", self._entry_intel_snapshot(candidate))
        except Exception as exc:
            logger.debug(f"Decision intel snapshot skipped: {exc}")
        try:
            tracker.record_candidate(
                candidate,
                decision=decision,
                reason=reason,
                source=source,
                extra=extra,
            )
        except Exception as exc:
            logger.debug(f"rtracker candidate record skipped: {exc}")

    @staticmethod
    def _rtracker_candidate_decision(candidate: TradeCandidate) -> str:
        action = str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper()
        status = str(getattr(candidate, "status", "") or "").upper()
        if action == "EXIT":
            return "EXIT"
        if action == "NO_ENTRY" or "REJECT" in status or "NO ENTRY" in status:
            return "REJECTED"
        if bool(getattr(candidate, "accepted_by_gate", False)):
            return "ACCEPTED"
        if status in {"ORDER PENDING", "ENTRY_PENDING", "ENTRY_SUBMITTED"}:
            return "SUBMITTED"
        return "CANDIDATE"

    def _remember_filtered_candidate(self, candidate: TradeCandidate) -> None:
        """Keep recent display-only rejected rows visible without making them executable."""
        if not candidate or not getattr(candidate, "instrument", ""):
            return
        self._rtracker_record_candidate(
            candidate,
            decision="REJECTED",
            reason=str(getattr(candidate, "exit_reason", "") or (candidate.reasons[-1] if getattr(candidate, "reasons", None) else getattr(candidate, "status", "")) or ""),
            source="filtered_candidate",
        )
        store = getattr(self, "_latest_filtered_candidates", None)
        if store is None:
            self._latest_filtered_candidates = {}
            store = self._latest_filtered_candidates
        rows = list(store.get(candidate.instrument, []))
        key = self._candidate_history_key(candidate)
        rows = [row for row in rows if self._candidate_history_key(row) != key]
        rows.insert(0, candidate)
        store[candidate.instrument] = rows[:50]
        self._remember_missed_reentry_seed(
            candidate,
            reason=str(
                getattr(candidate, "exit_reason", "")
                or (candidate.reasons[-1] if getattr(candidate, "reasons", None) else getattr(candidate, "status", ""))
                or ""
            ),
            source="filtered_candidate",
        )

    # (deduped 2026-07-10: a second _candidate_signal_type below shadowed an
    # earlier richer copy here — the ACTIVE definition lives near
    # _directional_bias; behavior unchanged by removing the dead one.)

    @staticmethod
    def _naive_ist(value) -> Optional[datetime]:
        if value is None:
            return None
        if getattr(value, "tzinfo", None) is not None:
            return value.astimezone(IST).replace(tzinfo=None)
        return value

    def _missed_reentry_blocked_reason(
        self,
        candidate: TradeCandidate,
        *,
        reason: str = "",
        source: str = "",
    ) -> str:
        """Return why a rejected candidate must not be considered for re-entry."""
        text = " ".join(
            [
                str(source or ""),
                str(reason or ""),
                str(getattr(candidate, "status", "") or ""),
                " ".join(str(item) for item in (getattr(candidate, "reasons", []) or [])[-3:]),
            ]
        ).upper()
        hard_blocks = {
            "BROKER",
            "QUOTE",
            "UNAVAILABLE",
            "MARKET CLOSED",
            "CUTOFF",
            "MAX TRADES",
            "CAPITAL",
            "RISK HALT",
            "HALTED",
            "CONSECUTIVE LOSSES",
            "COOLDOWN",
            "EXISTING ACTIVE",
            "EXISTING OPPOSITE",
            "OPPOSITE SIGNAL",
            "SAME-SIDE",
            "REFRESH",
            "CONCURRENCY",
            "CORRELATION",
            "BUCKET",
            "STALE",
            "REPAINT",
            "FUTURE",
            "BLACKOUT",
        }
        for token in hard_blocks:
            if token in text:
                return token.title()

        action = str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper()
        status = str(getattr(candidate, "status", "") or "").upper()
        if action == "EXIT":
            return "Exit row"
        if action == "NO_ENTRY" or "REJECT" in status or "BLOCK" in text:
            soft_blocks = {
                "QUALITY",
                "LOW CONFIDENCE",
                "SESSION TREND",
                "PRICE ACTION",
                "REGIME VETO",
                "COUNTER CENSUS",
                "LOCATION",
                "LIVE TRADE READINESS",
                "5MIN",
                "5MIN QUALITY",
                "CHOPPY CONFIRMATION",
                "OPT GATE",
                "EXHAUSTION",
            }
            if any(token in text for token in soft_blocks):
                return ""
            return "Non-reentry rejection"
        return ""

    def _drop_missed_reentry_seed(self, candidate, reason: str = "") -> bool:
        """Withdraw a signal from the missed-signal re-entry pool.

        The stabilization gate discards a candidate when its UT1 arrow VANISHES or
        FLIPS — the indicator withdrawing its own claim. That discard already cleans up
        _last_signal_identity, _candidate_process_cache and _raw_utbot_activity_keys, but
        it never removed the re-entry SEED, so the same signal could be re-admitted from
        the pool moments later.

        Measured live on 2026-08-10:

            12:55:51  [STABILIZATION] Rejected MIDCPNIFTY 5min LONG: UT1 arrow vanished
            12:55:57  Live Gate: missed-signal re-entry admitting MIDCPNIFTY 5min LONG,
                      age 355s

        Six seconds apart, on a signal already six minutes old. _missed_reentry_blocked_
        reason does list "REPAINT" as a hard block, but it matches on the reason TEXT of
        the original soft rejection — which was written long before the arrow vanished
        and says nothing about repainting. The block was real and simply never consulted
        about this event, so the seed has to be withdrawn at the source.
        """
        store = getattr(self, "_missed_reentry_candidates", None)
        if not isinstance(store, dict) or not candidate:
            return False
        instrument = str(getattr(candidate, "instrument", "") or "").upper()
        rows = store.get(instrument)
        if not rows:
            return False
        try:
            key = self._candidate_history_key(candidate)
        except Exception:
            return False
        kept = [row for row in rows if self._candidate_history_key(row) != key]
        if len(kept) == len(rows):
            return False
        store[instrument] = kept
        logger.info(
            f"[STABILIZATION] Withdrew {instrument} {getattr(candidate, 'timeframe', '')} "
            f"{getattr(candidate, 'direction', '')} from the missed-signal re-entry pool: "
            f"{reason or 'arrow withdrawn'}."
        )
        self._diag_inc("stabilization", "reentry_seed_withdrawn")
        return True

    def _remember_missed_reentry_seed(
        self,
        candidate: TradeCandidate,
        *,
        reason: str = "",
        source: str = "scanner",
    ) -> None:
        """Keep a bounded pool of recent soft-rejected signals that may be rechecked."""
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "missed_signal_reentry_enabled", True), True):
            return
        if getattr(self, "mode", "") == "HISTORICAL" or not candidate:
            return
        instrument = str(getattr(candidate, "instrument", "") or "").upper()
        if not instrument:
            return
        if self._candidate_signal_type(candidate) not in {"BUY", "SELL"}:
            return
        if float(getattr(candidate, "confidence", 0.0) or 0.0) <= 0:
            return
        blocked = self._missed_reentry_blocked_reason(candidate, reason=reason, source=source)
        if blocked:
            return
        # Retrack seeds: default 1min + 5min + 15min (20s → 360s window).
        try:
            allow_tfs = getattr(settings, "missed_signal_reentry_timeframes", None)
            if allow_tfs is None:
                allow_tfs = ["1min", "5min", "15min"]
            if allow_tfs:
                tf_set = {str(t).lower() for t in list(allow_tfs) if str(t or "").strip()}
                cand_tf = str(getattr(candidate, "timeframe", "") or "").lower()
                if tf_set and cand_tf and cand_tf not in tf_set:
                    return
        except Exception:
            pass

        try:
            seed = copy.deepcopy(candidate)
        except Exception:
            seed = candidate
        now = self._session_squareoff_clock() if hasattr(self, "_session_squareoff_clock") else datetime.now(IST)
        now = self._naive_ist(now) or datetime.now(IST).replace(tzinfo=None)
        setattr(seed, "missed_reentry_seed_reason", str(reason or ""))
        setattr(seed, "missed_reentry_seed_source", str(source or "scanner"))
        setattr(seed, "missed_reentry_recorded_at", now)
        store = getattr(self, "_missed_reentry_candidates", None)
        if store is None:
            self._missed_reentry_candidates = {}
            store = self._missed_reentry_candidates
        rows = list(store.get(instrument, []) or [])
        key = self._candidate_history_key(seed)
        rows = [row for row in rows if self._candidate_history_key(row) != key]
        rows.insert(0, seed)
        max_age = max(1.0, float(getattr(settings, "missed_signal_reentry_max_age_minutes", 6.0) or 6.0))
        cutoff = now - timedelta(minutes=max_age)
        pruned = []
        for row in rows:
            row_ts = self._naive_ist(
                getattr(row, "source_signal_timestamp", None)
                or getattr(row, "signal_timestamp", None)
                or getattr(row, "missed_reentry_recorded_at", None)
            )
            if row_ts is None or row_ts >= cutoff:
                pruned.append(row)
        store[instrument] = pruned[:20]

    def _missed_reentry_age_seconds(self, seed: TradeCandidate, now: datetime) -> Optional[float]:
        source_ts = self._naive_ist(
            getattr(seed, "source_signal_timestamp", None)
            or getattr(seed, "signal_timestamp", None)
            or getattr(seed, "missed_reentry_recorded_at", None)
        )
        if source_ts is None:
            return None
        return max(0.0, (now - source_ts).total_seconds())

    def _missed_reentry_current_spot(self, instrument: str, timeframe: str = "5min", as_of=None) -> float:
        candles = getattr(self, "candles", None)
        if candles is None:
            return 0.0
        try:
            price = float(candles.get_latest_price(instrument) or 0.0)
            if price > 0:
                return price
        except Exception:
            pass
        try:
            frame = candles.get_candles(instrument, timeframe)
            if frame is not None and as_of is not None:
                frame = frame[frame.index <= as_of]
            if frame is not None and len(frame) and "close" in frame.columns:
                return float(frame["close"].iloc[-1] or 0.0)
        except Exception:
            return 0.0
        return 0.0

    def _missed_reentry_atr(self, instrument: str, timeframe: str = "5min", as_of=None) -> float:
        try:
            frame = self.candles.get_candles(instrument, timeframe)
            if frame is None or len(frame) < 4:
                return 0.0
            if as_of is not None:
                frame = frame[frame.index <= as_of]
            if frame is None or len(frame) < 4:
                return 0.0
            high = frame["high"].astype(float)
            low = frame["low"].astype(float)
            close = frame["close"].astype(float)
            prev_close = close.shift(1)
            tr = pd.concat(
                [(high - low).abs(), (high - prev_close).abs(), (low - prev_close).abs()],
                axis=1,
            ).max(axis=1)
            value = float(tr.tail(14).mean() or 0.0)
            return value if value > 0 else 0.0
        except Exception:
            return 0.0

    def _missed_reentry_chase_check(
        self,
        seed: TradeCandidate,
        signal_type: str,
        now: datetime,
        cascade_confirmed: bool = False,
    ) -> Tuple[bool, str, Dict[str, float]]:
        settings = get_settings()
        instrument = str(getattr(seed, "instrument", "") or "").upper()
        timeframe = str(getattr(seed, "timeframe", "") or "5min")
        source_price = float(
            getattr(seed, "source_signal_price", 0.0)
            or getattr(seed, "entry_spot", 0.0)
            or 0.0
        )
        current_spot = self._missed_reentry_current_spot(instrument, timeframe, as_of=now)
        atr = self._missed_reentry_atr(instrument, timeframe, as_of=now)
        if source_price <= 0 or current_spot <= 0:
            return False, "missing spot/source price", {"source": source_price, "current": current_spot, "atr": atr}
        if atr <= 0:
            atr = max(1.0, abs(current_spot) * 0.001)
        moved = current_spot - source_price if signal_type == "BUY" else source_price - current_spot
        chase_atr = max(0.0, float(getattr(settings, "missed_signal_reentry_max_chase_atr", 0.75) or 0.75))
        if cascade_confirmed:
            # A CONFIRMED one-way cascade (3+ indices synchronized impulse) moves
            # past the normal chase cap before it can even confirm — the 0.75 ATR
            # limit kept the 2026-07-08 13:35 SENSEX seed out of a -1,185pt
            # crash. Cascade seeds may chase further; entry stays scalp-locked.
            chase_atr = max(
                chase_atr,
                float(getattr(settings, "missed_signal_reentry_cascade_max_chase_atr", 2.0) or 2.0),
            )
        max_chase = max(1.0, atr * chase_atr)
        pullback_allowance = max(0.5, atr * 0.25)
        details = {
            "source": source_price, "current": current_spot, "atr": atr,
            "moved": moved, "max_chase": max_chase, "cascade_confirmed": bool(cascade_confirmed),
        }
        if moved < -pullback_allowance:
            return False, "move no longer in signal direction", details
        if moved > max_chase:
            return False, "move already extended beyond re-entry chase limit", details
        return True, "", details

    def _missed_reentry_same_index_exposure(self, instrument: str, as_of: Optional[datetime] = None) -> bool:
        trades = getattr(getattr(self, "trades", None), "open_trades", {}) or {}
        trade_rows = trades.values() if isinstance(trades, dict) else trades
        for trade in list(trade_rows or []):
            if str(getattr(trade, "instrument", "") or "").upper() == str(instrument or "").upper():
                if str(getattr(trade, "status", "OPEN") or "OPEN").upper() == "OPEN":
                    return True
        try:
            return bool(self._active_session_entry_candidates(instrument, as_of=as_of))
        except Exception:
            return False

    def _missed_reentry_support_context(
        self,
        seed: TradeCandidate,
        now: datetime,
    ) -> Tuple[bool, str, Dict[str, Any]]:
        settings = get_settings()
        signal_type = self._candidate_signal_type(seed)
        if signal_type not in {"BUY", "SELL"}:
            return False, "missing signal side", {}
        age = self._missed_reentry_age_seconds(seed, now)
        if age is None:
            return False, "missing source timestamp", {}
        min_age = max(0.0, float(getattr(settings, "missed_signal_reentry_min_age_seconds", 20.0) or 20.0))
        max_age = max(min_age, float(getattr(settings, "missed_signal_reentry_max_age_minutes", 6.0) or 6.0) * 60.0)
        if age < min_age:
            self._diag_inc("missed_reentry_fail", "age_too_new")
            return False, "too new for re-entry", {"age_seconds": age}
        if age > max_age:
            self._diag_inc("missed_reentry_fail", "age_expired")
            return False, "missed signal expired", {"age_seconds": age}
        confidence = float(getattr(seed, "confidence", 0.0) or 0.0)
        min_conf = float(getattr(settings, "missed_signal_reentry_min_confidence", 0.55) or 0.55)
        if confidence < min_conf and not self._setting_enabled(
            getattr(settings, "missed_signal_reentry_scored_mode_enabled", False), False
        ):
            # In scored mode confidence is one of the six counted conditions rather than
            # a hard gate, so it must not short-circuit before the score is computed.
            self._diag_inc("missed_reentry_fail", "confidence")
            return False, f"confidence below re-entry floor {min_conf:.0%}", {"confidence": confidence}
        try:
            force_exit = self._configured_session_time("ut_force_exit_time", "15:25")
            remaining = (
                datetime.combine(now.date(), force_exit)
                - now
            ).total_seconds() / 60.0
            min_remaining = float(getattr(settings, "missed_signal_reentry_min_remaining_minutes", 8.0) or 8.0)
            if remaining < min_remaining:
                self._diag_inc("missed_reentry_fail", "no_runway")
                return False, "not enough runway for missed re-entry", {"remaining_minutes": remaining}
        except Exception:
            pass

        instrument = str(getattr(seed, "instrument", "") or "").upper()
        timeframe = str(getattr(seed, "timeframe", "") or "5min")
        cascade = self._one_way_cascade_context(instrument, timeframe, signal_type, now)
        support_type = ""
        support_reason = ""
        if cascade:
            support_type = "one_way_cascade"
            support_reason = str(cascade.get("reason") or "one-way cascade confirmed")
        else:
            allow_trend = self._setting_enabled(
                getattr(settings, "missed_signal_reentry_allow_trend_context", True),
                True,
            )
            regime = str(
                getattr(seed, "market_regime", "")
                or getattr(self, "latest_regimes", {}).get(instrument, "")
                or ""
            ).upper()
            adx = float(getattr(seed, "adx_value", 0.0) or 0.0)
            intel = float(normalize_intelligence_score(getattr(seed, "intelligence_score", 0.0) or 0.0))
            min_adx = float(getattr(settings, "missed_signal_reentry_min_trend_adx", 24.0) or 24.0)
            min_intel = float(getattr(settings, "missed_signal_reentry_min_intel_score", 0.20) or 0.20)
            intel_ok = intel >= min_intel if signal_type == "BUY" else intel <= -min_intel
            # Every condition is counted, not short-circuited, so the diagnostics can say
            # WHICH one kills a seed rather than only that something did. Three trades
            # came through this path in 19 sessions against 60,425 rejections, and with a
            # short-circuit chain there was no way to see where they died.
            checks = {
                "confidence": confidence >= min_conf,
                "trending_regime": bool(is_trending_regime(regime)),
                "regime_aligns": bool(regime_aligns(regime, signal_type)),
                "adx": adx >= min_adx,
                "intel": bool(intel_ok),
                "cascade": bool(cascade),
            }
            for name, ok in checks.items():
                if not ok:
                    self._diag_inc("missed_reentry_fail", name)
            met = sum(1 for ok in checks.values() if ok)
            strict_ok = bool(
                allow_trend and checks["trending_regime"] and checks["regime_aligns"]
                and checks["adx"] and checks["intel"]
            )
            scored_mode = self._setting_enabled(
                getattr(settings, "missed_signal_reentry_scored_mode_enabled", False), False
            )
            try:
                need = int(getattr(settings, "missed_signal_reentry_min_conditions", 5) or 5)
            except (TypeError, ValueError):
                need = 5
            need = max(1, min(len(checks), need))
            if strict_ok:
                support_type = "trend_regime_intel"
                support_reason = f"{regime} aligns, ADX {adx:.1f}, intel {intel:+.2f}"
            elif scored_mode and met >= need:
                # A/B lever. The strict path demands FOUR conditions simultaneously on a
                # signal already rejected once, and is_trending_regime alone fails on the
                # ~62% of labels that read RANGING — so the other three are rarely even
                # reached. Scored mode asks for N of 6 instead of all of one branch.
                support_type = "scored_reentry"
                support_reason = (
                    f"{met}/{len(checks)} re-entry conditions met "
                    f"({', '.join(k for k, ok in checks.items() if ok)})"
                )
                self._diag_inc("missed_reentry_fail", f"admitted_scored_{met}of{len(checks)}")
            else:
                return False, "no fresh cascade/trend-intel support", {
                    "regime": regime,
                    "adx": adx,
                    "intel": intel,
                    "cascade": bool(cascade),
                    "conditions_met": met,
                    "conditions_needed": need if scored_mode else len(checks),
                    "failed": [k for k, ok in checks.items() if not ok],
                }

        chase_ok, chase_reason, chase = self._missed_reentry_chase_check(
            seed, signal_type, now,
            cascade_confirmed=(support_type == "one_way_cascade"),
        )
        if not chase_ok:
            self._diag_inc("missed_reentry_fail", "chase")
            return False, chase_reason, chase
        return True, support_reason, {
            "type": support_type,
            "signal_type": signal_type,
            "age_seconds": age,
            "support": cascade or {},
            "chase": chase,
        }

    def _build_missed_reentry_candidate(
        self,
        seed: TradeCandidate,
        context: Dict[str, Any],
        now: datetime,
    ) -> Optional[TradeCandidate]:
        settings = get_settings()
        instrument = str(getattr(seed, "instrument", "") or "").upper()
        timeframe = str(getattr(seed, "timeframe", "") or "5min")
        signal_type = str(context.get("signal_type") or self._candidate_signal_type(seed))
        direction = "LONG" if signal_type == "BUY" else "SHORT"
        cfg = (getattr(self, "config", {}) or {}).get("indices", {}).get(instrument, {})
        if not cfg and instrument in (getattr(self, "config", {}) or {}):
            cfg = (getattr(self, "config", {}) or {}).get(instrument, {})
        spot = self._missed_reentry_current_spot(instrument, timeframe, as_of=now)
        if spot <= 0:
            return None
        rr = max(1.0, float(getattr(settings, "missed_signal_reentry_rr", 1.5) or 1.5))
        prefer_options = self._setting_enabled(getattr(settings, "missed_signal_reentry_prefer_options", True), True)
        # Strict lock: FUT/OPT preference always wins over prefer_options.
        inst_pref = self._strict_instrument_pref()
        if inst_pref == "OPT":
            inst_type = "OPT"
        elif inst_pref == "FUT":
            inst_type = "FUT"
        else:
            inst_type = "OPT" if prefer_options else "FUT"
        source_ts = self._naive_ist(getattr(seed, "source_signal_timestamp", None) or getattr(seed, "signal_timestamp", None))
        source_price = float(getattr(seed, "source_signal_price", 0.0) or spot)
        reason = str(getattr(seed, "missed_reentry_seed_reason", "") or "recent missed signal")
        base_reasons = list(getattr(seed, "reasons", []) or [])
        base_reasons.append(
            "Missed-signal re-entry: "
            f"{context.get('type', 'support')} confirmed; {reason}; "
            f"chase {float((context.get('chase') or {}).get('moved', 0.0) or 0.0):.2f}/"
            f"{float((context.get('chase') or {}).get('max_chase', 0.0) or 0.0):.2f}"
        )

        if inst_type == "FUT":
            info = getattr(self, "market_info", {}).get(instrument, {}) or {}
            symbol = str(info.get("current_fut", "") or "")
            token = str(info.get("current_fut_token", "") or "")
            if not symbol or not token:
                return None
            exchange = cfg.get("exchange", "BFO" if instrument == "SENSEX" else "NFO")
            try:
                fut_price = float(self.data.get_ltp(exchange, symbol, token) or 0.0)
            except Exception:
                fut_price = 0.0
            if fut_price <= 0:
                fut_price = spot
            sl_pct = max(0.0, float(getattr(settings, "missed_signal_reentry_futures_sl_pct", 0.05) or 0.05))
            risk = max(0.5, fut_price * (sl_pct / 100.0))
            stop = fut_price - risk if direction == "LONG" else fut_price + risk
            target = fut_price + (risk * rr) if direction == "LONG" else fut_price - (risk * rr)
            candidate = TradeCandidate(
                instrument=instrument,
                direction=direction,
                price=fut_price,
                stop=stop,
                target=target,
                lots=min(
                    max(1, int(getattr(get_settings(), "fut_lots_hard_cap", 1) or 1)),
                    max(1, int((getattr(self, "user_lots_fut", {}) or {}).get(instrument, getattr(seed, "lots", 1) or 1))),
                ),
                lot_size=max(1, int(cfg.get("lot_size", getattr(seed, "lot_size", 1) or 1))),
                grade=str(getattr(seed, "grade", "B+") or "B+"),
                confidence=float(getattr(seed, "confidence", 0.0) or 0.0),
                timeframe=timeframe,
                inst_type="FUT",
                option_type="",
                atm_strike=0.0,
                multiplier=1.0,
                trading_symbol=symbol,
                symbol_token=token,
                rr=rr,
                score=float(getattr(seed, "score", getattr(seed, "confidence", 0.0)) or 0.0),
                reasons=base_reasons,
                signal_timestamp=now,
                current_price=fut_price,
                status="MISSED RE-ENTRY SIGNAL",
                action="ENTRY",
                adx_value=float(getattr(seed, "adx_value", 0.0) or 0.0),
                impulse_confirmed=True,
            )
            setattr(candidate, "tight_stop_pct", sl_pct)
        else:
            option_type = "CE" if direction == "LONG" else "PE"
            data = getattr(self, "data", None)
            if data is None:
                return None
            strike_interval = float(cfg.get("strike_interval", 50) or 50)
            strike = round(float(spot) / strike_interval) * strike_interval
            try:
                opt_info = data.get_option_token(instrument, strike, option_type)
            except Exception:
                opt_info = None
            if not opt_info:
                return None
            exchange = cfg.get("option_exchange", "BFO" if instrument == "SENSEX" else "NFO")
            try:
                premium = float(data.get_ltp(exchange, opt_info["symbol"], opt_info["token"]) or 0.0)
            except Exception:
                premium = 0.0
            if premium <= 0:
                return None
            sl_pct = max(0.0, float(getattr(settings, "missed_signal_reentry_options_sl_pct", 5.0) or 5.0))
            risk = max(0.5, premium * (sl_pct / 100.0))
            multiplier = 0.5 if option_type == "CE" else -0.5
            spot_risk = max(1.0, risk / abs(multiplier))
            spot_stop = spot - spot_risk if direction == "LONG" else spot + spot_risk
            spot_target = spot + (spot_risk * rr) if direction == "LONG" else spot - (spot_risk * rr)
            candidate = TradeCandidate(
                instrument=instrument,
                direction=direction,
                price=premium,
                stop=max(0.05, premium - risk),
                target=premium + (risk * rr),
                lots=max(1, int((getattr(self, "user_lots", {}) or {}).get(instrument, getattr(seed, "lots", 1) or 1))),
                lot_size=max(1, int(cfg.get("lot_size", getattr(seed, "lot_size", 1) or 1))),
                grade=str(getattr(seed, "grade", "B+") or "B+"),
                confidence=float(getattr(seed, "confidence", 0.0) or 0.0),
                timeframe=timeframe,
                inst_type="OPT",
                option_type=option_type,
                atm_strike=float(strike),
                multiplier=multiplier,
                trading_symbol=str(opt_info["symbol"]),
                symbol_token=str(opt_info["token"]),
                rr=rr,
                score=float(getattr(seed, "score", getattr(seed, "confidence", 0.0)) or 0.0),
                reasons=base_reasons,
                spot_stop=spot_stop,
                spot_target=spot_target,
                signal_timestamp=now,
                current_price=premium,
                status="MISSED RE-ENTRY SIGNAL",
                action="ENTRY",
                adx_value=float(getattr(seed, "adx_value", 0.0) or 0.0),
                impulse_confirmed=True,
                quote_verified=True,
                quote_source="broker_ltp",
            )
            setattr(candidate, "tight_stop_pct", sl_pct)

        setattr(candidate, "missed_signal_reentry", True)
        setattr(candidate, "missed_signal_reentry_context", dict(context))
        setattr(candidate, "source_signal_type", signal_type)
        setattr(candidate, "source_signal_price", source_price)
        if source_ts is not None:
            setattr(candidate, "source_signal_timestamp", source_ts)
        setattr(candidate, "entry_spot", spot)
        # Own-timeframe regime, not the 5-minute one. latest_regimes is keyed by
        # INSTRUMENT and its own declaration calls it "5min instrument regime", so a 1min
        # or 15min candidate was being graded on a label computed from 5-minute candles.
        # _timeframe_regimes has held the per-timeframe answer all along and
        # _get_trade_regime already does the right cascade — own timeframe, then the 5min
        # label, then UNKNOWN — it was simply never used at the ENTRY seam, only for
        # managing trades already open.
        setattr(
            candidate,
            "market_regime",
            getattr(seed, "market_regime", None) or self._get_trade_regime(candidate, default=""),
        )
        setattr(candidate, "intelligence_score", float(getattr(seed, "intelligence_score", 0.0) or 0.0))
        setattr(candidate, "source_engine", str(getattr(seed, "source_engine", "") or "missed_reentry"))
        setattr(candidate, "source_engines", list(getattr(seed, "source_engines", []) or []))
        setattr(candidate, "source_lane", str(getattr(seed, "source_lane", "") or "missed_reentry"))
        setattr(candidate, "quad_union_entry", False)
        setattr(candidate, "raw_union_entry", False)
        if context.get("type") == "one_way_cascade":
            setattr(candidate, "one_way_cascade_entry", True)
            setattr(candidate, "one_way_cascade_context", dict(context.get("support") or {}))
            candidate.scalp_lock_mode = False
        return candidate

    def _collect_missed_signal_reentries(
        self,
        existing_candidates: Optional[List[TradeCandidate]] = None,
    ) -> List[TradeCandidate]:
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "missed_signal_reentry_enabled", True), True):
            return []
        if getattr(self, "mode", "") == "HISTORICAL":
            return []
        try:
            if not self.data.is_market_open() and not getattr(self, "is_warmup", False):
                return []
        except Exception:
            return []
        now = self._naive_ist(self._session_squareoff_clock()) or datetime.now(IST).replace(tzinfo=None)
        existing_keys = {
            (
                str(getattr(item, "instrument", "") or "").upper(),
                self._candidate_signal_type(item),
            )
            for item in list(existing_candidates or [])
        }
        selected: List[TradeCandidate] = []
        store = getattr(self, "_missed_reentry_candidates", {}) or {}
        for instrument, rows in list(store.items()):
            if self._missed_reentry_same_index_exposure(instrument, as_of=now):
                continue
            best_item = None
            best_score = -1.0
            retained = []
            for seed in list(rows or []):
                age = self._missed_reentry_age_seconds(seed, now)
                max_age = float(getattr(settings, "missed_signal_reentry_max_age_minutes", 6.0) or 6.0) * 60.0
                if age is not None and age <= max_age:
                    retained.append(seed)
                ok, reason, context = self._missed_reentry_support_context(seed, now)
                if not ok:
                    continue
                side_key = (instrument, str(context.get("signal_type") or self._candidate_signal_type(seed)))
                if side_key in existing_keys:
                    continue
                candidate = self._build_missed_reentry_candidate(seed, context, now)
                if candidate is None:
                    continue
                score = (
                    float(getattr(candidate, "confidence", 0.0) or 0.0)
                    + min(1.0, float(((context.get("support") or {}).get("total_votes", 0) or 0)) / 4.0)
                    - (float(context.get("age_seconds", 0.0) or 0.0) / 3600.0)
                )
                if score > best_score:
                    best_score = score
                    best_item = candidate
            store[instrument] = retained[:20]
            if best_item is not None:
                selected.append(best_item)
                self.log_signal_decision_once(
                    (
                        f"{best_item.instrument}|{best_item.timeframe}|"
                        f"{best_item.direction}|{best_item.signal_timestamp.isoformat(timespec='seconds')}|missed-reentry"
                    ),
                    (
                        f"Missed signal re-entry armed: {best_item.instrument} {best_item.direction} "
                        f"{best_item.timeframe}; {best_item.reasons[-1] if best_item.reasons else 'support confirmed'}"
                    ),
                    "trade",
                )
        return selected

    def _forget_signal_display_rows(self, candidate: TradeCandidate) -> None:
        """Remove display-only rows tied to a live signal that later repainted or expired."""
        if not candidate or not getattr(candidate, "instrument", ""):
            return
        key = self._candidate_history_key(candidate)
        for attr in ("_latest_filtered_candidates", "_latest_trade_candidates"):
            store = getattr(self, attr, None)
            if not isinstance(store, dict):
                continue
            rows = list(store.get(candidate.instrument, []) or [])
            rows = [row for row in rows if self._candidate_history_key(row) != key]
            if rows:
                store[candidate.instrument] = rows
            else:
                store.pop(candidate.instrument, None)

        # Also clean up from session history so it doesn't linger as a ghost
        session_store = getattr(self, "_session_trade_candidates", {})
        if candidate.instrument in session_store:
            book = session_store[candidate.instrument]
            if key in book:
                book.pop(key)
                if not book:
                    session_store.pop(candidate.instrument)
                self._persist_session_trade_candidates()

    @staticmethod
    def _is_quad_union_raw_historical_signal(settings, signal) -> bool:
        """Return True when historical replay should mirror live quad raw entry flow."""
        try:
            # Engine 10 v2 delegates to the proven engines and its signals are
            # NEVER raw-union arrows — only the quad modes mirror raw flow here.
            return str(getattr(settings, "scanner_engine", "") or "").lower() in {"quad_union", "quad_prime"}
        except Exception:
            return False

    @staticmethod
    def _is_quality_hybrid_route_entry(
        settings,
        signal,
        *,
        confidence: float = 0.0,
        grade_rank: int = 0,
        timeframe: str = "",
        trend_15m_agrees: bool = False,
        explosive_move: bool = False,
    ) -> bool:
        """Engine 12 relief for data-confirmed route signals, not a raw bypass."""
        try:
            if str(getattr(settings, "scanner_engine", "") or "").lower() != "quality_hybrid":
                return False
            route = (
                str(getattr(signal, "quality_hybrid_stream", "") or "")
                or str(getattr(signal, "quality_hybrid_route", "") or "")
            ).strip().lower()
            route_aliases = {
                "volume_thrust": "quality_thrust",
                "broad_non_atr": "quality_breakout",
                "consensus_core": "quality_core",
                "chop_strict_consensus": "quality_core",
                "vote_flip": "quality_core",
            }
            route = route_aliases.get(route, route)
            if route not in {"quality_thrust", "quality_breakout", "quality_pullback"}:
                return False
            agreement = int(getattr(signal, "trend_agreement", 0) or 0)
            vote_abs = abs(float(getattr(signal, "quality_hybrid_vote_score", 0.0) or 0.0))
            adx_value = float(getattr(signal, "adx_value", 0.0) or 0.0)
            trend_adx = float(getattr(settings, "quality_hybrid_trend_adx", 22.0) or 22.0)
            conf = float(confidence or 0.0)
            grade_ok = int(grade_rank or 0) >= 1 or conf >= 0.70
            if not grade_ok:
                return False
            conf_ok = conf >= 0.60 or bool(trend_15m_agrees) or bool(explosive_move)
            proof_ok = agreement >= 5 or vote_abs >= 4.0 or adx_value >= max(24.0, trend_adx)
            tf_text = str(timeframe or "").lower()
            is_5min = "5" in tf_text
            if route == "quality_thrust":
                return conf_ok and proof_ok
            if route == "quality_breakout":
                if is_5min and not (bool(trend_15m_agrees) or bool(explosive_move)):
                    return False
                return conf_ok and (agreement >= 5 or vote_abs >= 4.0)
            if route == "quality_pullback":
                if is_5min and not bool(trend_15m_agrees):
                    return False
                return (
                    (bool(trend_15m_agrees) or bool(explosive_move))
                    and agreement >= 5
                    and vote_abs >= 3.0
                )
        except Exception:
            return False
        return False

    def _record_historical_reject(
        self,
        signal,
        instrument: str,
        timeframe: str,
        direction: str,
        grade: str,
        confidence: float,
        reason: str,
        inst_type: str,
        lot_size: int,
        atm_strike: float,
        option_type: str = "",
        target: float = 0.0,
        regime: str = "",
    ) -> None:
        """Publish filtered backtest candidates so the signal panel does not look idle."""
        try:
            signal_ts = getattr(signal, "timestamp", None)
            identity = "|".join(
                [
                    str(instrument),
                    str(timeframe),
                    str(signal_ts),
                    str(direction),
                    str(inst_type),
                    str(reason or "Unknown"),
                ]
            )
            self._diag_inc_unique("rejects", str(reason or "Unknown"), identity)
            candidate = TradeCandidate(
                instrument=instrument,
                direction=direction,
                price=float(getattr(signal, "price", 0.0) or 0.0),
                stop=float(getattr(signal, "trailing_stop", 0.0) or 0.0),
                target=float(target or 0.0),
                lots=0,
                lot_size=int(lot_size or 1),
                grade=str(grade or "C"),
                confidence=float(confidence or 0.0),
                timeframe=timeframe,
                inst_type=str(inst_type or "FUT"),
                option_type=str(option_type or ""),
                atm_strike=float(atm_strike or 0.0),
                multiplier=1.0,
                trading_symbol="",
                symbol_token="",
                rr=0.0,
                score=float(confidence or 0.0),
                reasons=[reason],
                spot_stop=float(getattr(signal, "trailing_stop", 0.0) or 0.0),
                spot_target=float(target or 0.0),
                signal_timestamp=getattr(signal, "timestamp", None),
                current_price=float(getattr(signal, "price", 0.0) or 0.0),
                pnl=0.0,
                status=f"NO ENTRY - {reason}",
                action="NO_ENTRY",
            )
            hist_regime = str(regime or "").upper()
            if hist_regime:
                setattr(candidate, "market_regime", hist_regime)
                setattr(
                    candidate,
                    "market_intelligence_context",
                    {
                        "regime": {
                            "regime": hist_regime,
                            "smoothed_regime": hist_regime,
                            "conviction_label": hist_regime.replace("_", " ").title(),
                        },
                        "aggregate": {"regime": hist_regime},
                    },
                )
            self._remember_filtered_candidate(candidate)
        except Exception as exc:
            logger.debug(f"Failed to record filtered historical row: {exc}")

    @staticmethod
    def _configured_session_time(setting_name: str, default: str) -> dtime:
        label = str(getattr(get_settings(), setting_name, default) or default)
        return datetime.strptime(label, "%H:%M").time()

    def _entry_cutoff_allows_candidate(self, candidate: TradeCandidate, session_now: datetime) -> bool:
        """Allow a by-cutoff signal to finish the small live stabilization grace."""
        timeframe = str(getattr(candidate, "timeframe", "") or "5min")
        settings = get_settings()
        cutoff = self._configured_session_time(
            "ut_no_entry_after" if timeframe == "15min" else "ut_5min_no_entry_after",
            "15:00" if timeframe == "15min" else "15:15",
        )
        signal_ts = getattr(candidate, "signal_timestamp", None)
        if signal_ts is None:
            return session_now.time() < cutoff
        if getattr(signal_ts, "tzinfo", None) is not None:
            signal_ts = signal_ts.astimezone(IST).replace(tzinfo=None)
        now_naive = session_now.astimezone(IST).replace(tzinfo=None) if session_now.tzinfo else session_now
        cutoff_dt = datetime.combine(signal_ts.date(), cutoff)
        if timeframe == "15min":
            if signal_ts > cutoff_dt:
                return False
            grace_seconds = max(
                0.0,
                float(getattr(settings, "live_15min_entry_cutoff_grace_seconds", 90.0) or 0.0),
            )
            return now_naive <= cutoff_dt + timedelta(seconds=grace_seconds)

        tf_minutes = {"1min": 1, "5min": 5, "15min": 15}.get(timeframe, 5)
        candle_close = signal_ts + timedelta(minutes=tf_minutes)
        cutoff_dt = datetime.combine(candle_close.date(), cutoff)
        if candle_close > cutoff_dt:
            return False
        stable_seconds, _, _ = self._live_signal_stabilization_requirements(candidate)
        return now_naive <= cutoff_dt + timedelta(seconds=stable_seconds + 10.0)

    def _is_stale_realtime_entry_candidate(self, candidate: TradeCandidate) -> bool:
        """Block REAL-mode startup/backfill signals from becoming fresh entries."""
        if getattr(self, "mode", "") == "HISTORICAL":
            return False
        if str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper() != "ENTRY":
            return False
        signal_ts = getattr(candidate, "signal_timestamp", None)
        started_at = getattr(self, "_process_started_at", None)
        if not signal_ts or not started_at:
            return False
        if getattr(signal_ts, "tzinfo", None) is not None:
            signal_ts = signal_ts.astimezone(IST).replace(tzinfo=None)
        if getattr(started_at, "tzinfo", None) is not None:
            started_at = started_at.astimezone(IST).replace(tzinfo=None)
        if signal_ts >= started_at:
            return False
        return not self._signal_in_restart_recovery_window(signal_ts, getattr(candidate, "timeframe", "5min"))

    def _session_squareoff_clock(self) -> datetime:
        """Use the strongest IST clock available for session-end exits."""
        wall_now = datetime.now(IST)
        try:
            market_ts = self.candles.get_max_timestamp()
            if market_ts is not None:
                if getattr(market_ts, "tzinfo", None) is None:
                    market_now = IST.localize(market_ts)
                else:
                    market_now = market_ts.astimezone(IST)
                max_skew = max(
                    30.0,
                    float(getattr(get_settings(), "clock_skew_max_seconds", 180.0) or 180.0),
                )
                if market_now.date() == wall_now.date() and abs((market_now - wall_now).total_seconds()) > max_skew:
                    return market_now
                if market_now > wall_now:
                    return market_now
        except Exception as exc:
            logger.debug(f"Session squareoff clock fallback to wall time: {exc}")
        return wall_now

    def _live_clock_is_sane(self) -> bool:
        """Fail closed for new live entries when market-data time disagrees with the host."""
        if getattr(self, "mode", "HISTORICAL") == "HISTORICAL":
            return True
        wall_now = datetime.now(IST)
        if not (dtime(9, 0) <= wall_now.time() <= dtime(15, 45)):
            return True
        try:
            market_ts = self.candles.get_max_timestamp()
            if market_ts is None:
                return False
            market_now = (
                IST.localize(market_ts)
                if getattr(market_ts, "tzinfo", None) is None
                else market_ts.astimezone(IST)
            )
            max_skew = max(
                30.0,
                float(getattr(get_settings(), "clock_skew_max_seconds", 180.0) or 180.0),
            )
            sane = (
                market_now.date() == wall_now.date()
                and abs((market_now - wall_now).total_seconds()) <= max_skew
            )
            if not sane:
                self.log_signal_decision_once(
                    f"clock-skew|{wall_now.date().isoformat()}",
                    f"Live entries blocked: host/market clock skew exceeds {max_skew:.0f}s "
                    f"(host={wall_now.isoformat()}, market={market_now.isoformat()})",
                    "error",
                )
            return sane
        except Exception as exc:
            logger.error(f"Live clock sanity check failed: {exc}")
            return False

    def _force_exit_session_candidates_at_eod(self, now: Optional[datetime] = None) -> int:
        """Close manual/live signal-ledger rows at the configured hard square-off."""
        if getattr(self, "mode", "") == "HISTORICAL":
            return 0

        now = now or self._session_squareoff_clock()
        if now.tzinfo is None:
            now = IST.localize(now)
        else:
            now = now.astimezone(IST)

        trigger_time = self._configured_session_time("ut_force_exit_time", "15:25")
        exit_time = trigger_time

        # Each row is closed at ITS OWN session's square-off, not at today's.
        #
        # This used to return early unless now.time() >= trigger_time, and then skip any
        # row whose date was not today's. Together those confined the sweep to one window:
        # square-off until midnight, on the day the row was created. Miss that window and
        # the row could never be closed again -- after midnight the early return fires on
        # every cycle (00:05 < 15:15) and the date filter rejects yesterday's rows anyway.
        #
        # Missing the window is not exotic; it is what a crash does. On 2026-08-14 the
        # process was down from before 15:15 until after midnight, so a 12:37 BANKNIFTY
        # entry whose exit had been recorded under a different lifecycle key was still
        # being rendered as a live intraday signal the next day, marking P&L against a
        # dead position.
        #
        # Per-row keeps the intraday guarantee exactly as it was -- a row from today is
        # untouched until today's square-off passes -- and adds the one this lacked: a
        # row from any earlier session is closed at the first scan after restart, whenever
        # that happens to be.
        exits: List[TradeCandidate] = []
        for instrument in list((getattr(self, "_session_trade_candidates", {}) or {}).keys()):
            for previous in self._active_session_entry_candidates(instrument):
                prev_ts = getattr(previous, "signal_timestamp", None)
                if not prev_ts:
                    continue
                prev_ist = IST.localize(prev_ts) if prev_ts.tzinfo is None else prev_ts.astimezone(IST)
                # The square-off belonging to the row's own session day.
                exit_ts = IST.localize(datetime.combine(prev_ist.date(), exit_time))
                if prev_ist >= exit_ts or now < exit_ts:
                    continue

                dedupe_key = f"EOD_{instrument}_{previous.timeframe}_{previous.direction}_{prev_ist.isoformat()}"
                if self._last_opposite_exit_signal_time.get(dedupe_key) == exit_ts:
                    continue

                # check if an exit candidate already exists in today's ledger!
                store = getattr(self, "_session_trade_candidates", {}) or {}
                book = store.get(instrument, {})
                hist_key = self._candidate_history_key(previous)
                if hist_key in book and getattr(book[hist_key], "action", "") == "EXIT":
                    continue

                proposed_exit_px = previous.current_price or previous.price
                exit_px, exit_reason, reason_text = self._candidate_exit_resolution(
                    previous,
                    proposed_exit_px,
                    "FORCE_EOD_KILL",
                    f"Hard square-off at {trigger_time.strftime('%H:%M')} IST",
                )
                calc_pnl = self._candidate_net_pnl(previous, exit_px)

                exit_candidate = TradeCandidate(
                    instrument=previous.instrument,
                    direction=previous.direction,
                    price=previous.price,
                    stop=previous.stop,
                    target=previous.target,
                    lots=previous.lots,
                    lot_size=previous.lot_size,
                    grade=previous.grade,
                    confidence=previous.confidence,
                    timeframe=previous.timeframe,
                    inst_type=previous.inst_type,
                    option_type=previous.option_type,
                    atm_strike=previous.atm_strike,
                    multiplier=previous.multiplier,
                    trading_symbol=previous.trading_symbol,
                    symbol_token=previous.symbol_token,
                    rr=previous.rr,
                    score=previous.score,
                    reasons=list(previous.reasons or []) + [f"{reason_text} at {exit_px:.2f}"],
                    spot_stop=previous.spot_stop,
                    spot_target=previous.spot_target,
                    signal_timestamp=prev_ts,
                    current_price=exit_px,
                    pnl=calc_pnl,
                    status="EXIT SIGNAL",
                    action="EXIT",
                    exit_reason=exit_reason,
                )
                setattr(exit_candidate, "exit_timestamp", exit_ts.replace(tzinfo=None))
                setattr(exit_candidate, "exit_price", float(exit_px))
                self._inherit_exit_entry_metadata(exit_candidate, previous)
                exits.append(exit_candidate)
                self._last_opposite_exit_signal_time[dedupe_key] = exit_ts

        if not exits:
            return 0

        for exit_candidate in exits:
            self._refresh_trade_candidates(
                [exit_candidate],
                self.config.get("indices", {}).get(exit_candidate.instrument, {}),
            )
            self._latest_exit_candidates[exit_candidate.instrument] = [exit_candidate]
        self._remember_trade_candidates(exits)
        self.log_event(
            f"Force EOD exit applied to {len(exits)} manual signal row(s) at {trigger_time.strftime('%H:%M')} IST",
            "warning",
        )
        return len(exits)

    def _close_superseded_session_entries(self, candidates: List[TradeCandidate]) -> None:
        """In manual mode, a fresh index signal closes older active manual rows for clean P&L."""
        if not candidates or getattr(self, "mode", "") == "HISTORICAL":
            return

        exits: List[TradeCandidate] = []
        for candidate in candidates:
            if getattr(candidate, "action", "ENTRY") == "EXIT":
                continue
            signal_ts = getattr(candidate, "signal_timestamp", None)
            if not signal_ts:
                continue
            for previous in self._active_session_entry_candidates(candidate.instrument):
                prev_ts = getattr(previous, "signal_timestamp", None)
                if not prev_ts or signal_ts <= prev_ts:
                    continue
                if self._candidate_history_key(previous) == self._candidate_history_key(candidate):
                    continue

                if self._refresh_same_direction_session_lifecycle(candidate, previous):
                    continue
                if not self._should_supersede_session_entry(candidate, previous):
                    continue

                dedupe_key = f"SUPERSEDE_{candidate.instrument}_{previous.timeframe}_{previous.direction}_{signal_ts.isoformat()}"
                if self._last_opposite_exit_signal_time.get(dedupe_key) == signal_ts:
                    continue

                # check if an exit candidate already exists in today's ledger!
                store = getattr(self, "_session_trade_candidates", {}) or {}
                book = store.get(candidate.instrument, {})
                hist_key = self._candidate_history_key(previous)
                if hist_key in book and getattr(book[hist_key], "action", "") == "EXIT":
                    continue

                # Calculate immediate exit price and P&L
                if previous.inst_type == "OPT":
                    proposed_exit_px = self._get_live_premium_cached(previous) or previous.current_price or previous.price
                else:
                    proposed_exit_px = candidate.price
                exit_px, exit_reason, reason_text = self._candidate_exit_resolution(
                    previous,
                    float(proposed_exit_px),
                    "SUPERSEDED_SIGNAL",
                    f"Superseded by {candidate.direction} {candidate.timeframe} signal",
                )
                calc_pnl = self._candidate_net_pnl(previous, exit_px)

                exit_candidate = TradeCandidate(
                    instrument=previous.instrument,
                    direction=previous.direction,
                    price=previous.price,
                    stop=previous.stop,
                    target=previous.target,
                    lots=previous.lots,
                    lot_size=previous.lot_size,
                    grade=previous.grade,
                    confidence=previous.confidence,
                    timeframe=previous.timeframe,
                    inst_type=previous.inst_type,
                    option_type=previous.option_type,
                    atm_strike=previous.atm_strike,
                    multiplier=previous.multiplier,
                    trading_symbol=previous.trading_symbol,
                    symbol_token=previous.symbol_token,
                    rr=previous.rr,
                    score=previous.score,
                    reasons=list(previous.reasons or []) + [f"{reason_text} at {signal_ts:%H:%M}"],
                    spot_stop=previous.spot_stop,
                    spot_target=previous.spot_target,
                    signal_timestamp=prev_ts,
                    current_price=exit_px,
                    pnl=calc_pnl,
                    status="EXIT SIGNAL",
                    action="EXIT",
                    exit_reason=exit_reason,
                )
                setattr(exit_candidate, "exit_timestamp", signal_ts)
                setattr(exit_candidate, "exit_price", float(exit_px))
                self._inherit_exit_entry_metadata(exit_candidate, previous)
                exits.append(exit_candidate)
                self._last_opposite_exit_signal_time[dedupe_key] = signal_ts

        if exits:
            for exit_candidate in exits:
                self._refresh_trade_candidates([exit_candidate], self.config.get("indices", {}).get(exit_candidate.instrument, {}))
                self._latest_exit_candidates[exit_candidate.instrument] = [exit_candidate]
            self._remember_trade_candidates(exits)

    def _get_session_trade_candidates(self, instrument: str) -> List[TradeCandidate]:
        self._ensure_session_candidate_day()
        store = getattr(self, "_session_trade_candidates", {})
        book = store.get(instrument, {})
        if self._repair_same_side_superseded_session_rows():
            book = store.get(instrument, {})
            self._persist_session_trade_candidates()
        for candidate in book.values():
            self._normalize_loaded_exit_candidate(candidate)
        entries_by_lifecycle = {
            self._candidate_lifecycle_key(candidate): candidate
            for candidate in book.values()
            if getattr(candidate, "action", "ENTRY") == "ENTRY"
        }
        repaired = False
        for candidate in book.values():
            if getattr(candidate, "action", "ENTRY") != "EXIT":
                continue
            entry = entries_by_lifecycle.get(self._candidate_lifecycle_key(candidate))
            old_entry_ts = getattr(candidate, "entry_timestamp", None)
            self._inherit_exit_entry_metadata(candidate, entry)
            if getattr(candidate, "entry_timestamp", None) != old_entry_ts:
                repaired = True
        if repaired:
            self._persist_session_trade_candidates()
        rows = [
            candidate for candidate in book.values()
            if self._candidate_matches_live_session_day(candidate)
            and self._candidate_chronology_valid(candidate)
        ]
        for candidate in book.values():
            if not self._candidate_chronology_valid(candidate):
                setattr(candidate, "status", "QUARANTINED - INVALID CHRONOLOGY")
                setattr(candidate, "invalid_chronology", True)
        return sorted(
            rows,
            key=lambda c: (
                getattr(c, "entry_timestamp", None)
                or getattr(c, "signal_timestamp", None)
                or datetime.min
            ),
            reverse=True,
        )

    def _build_dashboard_trade_payload(self) -> Dict[str, Any]:
        """Return trade-manager rows plus the persisted manual/live signal ledger."""
        payload = build_dashboard_trade_payload(self)
        meta = payload.get("meta") if isinstance(payload, dict) else None
        if isinstance(meta, dict) and "futures_shadow_enabled" in meta:
            # dashboard.server currently compares historical-cache context fields
            # through string coercion; plain ``False`` would become ``""`` there.
            # Keep the cache key explicit until that legacy comparator is retired.
            meta["futures_shadow_enabled"] = (
                "True" if self._setting_enabled(meta.get("futures_shadow_enabled"), False) else "False"
            )
        return payload

    def _has_opposite_exposure(self, instrument: str, signal, timeframe: str) -> bool:
        """Whether any open trade or active session candidate opposes this signal."""
        cross_timeframe = str(getattr(get_settings(), "scanner_engine", "") or "").lower() == "quad_prime"
        for trade in list(getattr(self.trades, "open_trades", {}).values()):
            if str(getattr(trade, "instrument", "") or "").split()[0] != instrument:
                continue
            if not cross_timeframe and str(getattr(trade, "timeframe", "") or "") != timeframe:
                continue
            if (trade.direction == "LONG" and signal.signal_type == "SELL") or (
                trade.direction == "SHORT" and signal.signal_type == "BUY"
            ):
                return True
        row_timeframe = None if cross_timeframe else timeframe
        for row in self._active_session_entry_candidates(instrument, timeframe=row_timeframe):
            if not cross_timeframe and getattr(row, "timeframe", "") != timeframe:
                continue
            if (getattr(row, "direction", "") == "LONG" and signal.signal_type == "SELL") or (
                getattr(row, "direction", "") == "SHORT" and signal.signal_type == "BUY"
            ):
                return True
        return False

    def _combo_solo_utbot_exit_blocked(self, signal) -> bool:
        """In a combo engine, a SOLO UT1 opposite-flip must not exit a live trade by
        itself. UT1 is the jumpy source, so its exits need the partner (ema/consensus)
        to confirm — and the partner emits its OWN opposite signal (source ema/consensus,
        or "both" when they agree) when it flips, so ignoring utbot-tagged exits simply
        rides the trade on the partner's slower, reliable judgement plus the protective
        stop. Entries are unaffected. Applies in live and backtest so the behaviour is
        A/B-able. No effect outside combo modes (single-engine signals are untagged)."""
        try:
            if not bool(getattr(get_settings(), "combo_partner_confirms_exit", True)):
                return False
            mode = str(getattr(get_settings(), "scanner_engine", "") or "").lower()
            if mode not in ("utbot_ema", "utbot_consensus"):
                return False
            return str(getattr(signal, "source_engine", "") or "").lower() == "utbot"
        except Exception:
            return False

    @staticmethod
    def _quad_union_sources(signal) -> set:
        raw = getattr(signal, "source_engines", None)
        sources = []
        if isinstance(raw, (list, tuple, set)):
            sources.extend(str(item).lower() for item in raw if str(item or "").strip())
        elif isinstance(raw, str) and raw.strip():
            sources.append(raw.lower())
        src = str(getattr(signal, "source_engine", "") or "").lower()
        if src and src not in {"multi", "both"}:
            sources.append(src)
        if src == "both" and not sources:
            sources.extend(["utbot", "partner"])
        cleaned = []
        for item in sources:
            for part in str(item).replace("+", ",").replace("/", ",").split(","):
                part = part.strip().lower()
                if part and part not in {"multi", "both", "partner", "adaptive_hybrid", "adaptive_dual", "quality_hybrid"} and part not in cleaned:
                    cleaned.append(part)
        return set(cleaned)

    def _market_wide_candidate_quality(self, candidate: TradeCandidate) -> Tuple[bool, str]:
        """Minimum local quality required before cross-index relief is considered.

        Ported back from restore_point_51, where the raw-entry floor read
        `market_wide and market_wide_ok`. This build had lost the helper entirely,
        leaving the flag bare, so a market-wide reversal carried ANY signal past the
        quality floor — 2026-08-12 admitted grade C at 12% and 13%, both dead inside
        90 seconds, while the same gate refused a B+ at 67% minutes later.

        Peer names live under `core_indices`/`indices` in this build's context
        (restore_point_51 called them `peer_indices`); all three are read so the
        guard travels with either shape. A context that names no OTHER index is not
        evidence of a market-wide move — but an absent/malformed context is missing
        evidence, not disproof, so it leaves the grade and confidence bars to decide
        rather than blocking outright.
        """
        settings = get_settings()
        try:
            confidence = float(getattr(candidate, "confidence", 0.0) or 0.0)
        except (TypeError, ValueError):
            confidence = 0.0
        grade = str(getattr(candidate, "grade", "") or "")
        min_grade = str(getattr(settings, "market_wide_reversal_min_grade", "B+") or "B+").upper()
        min_conf = float(getattr(settings, "market_wide_reversal_min_confidence", 0.60) or 0.60)

        context = getattr(candidate, "market_wide_reversal_context", None)
        if isinstance(context, dict):
            peers: List[Any] = []
            for key in ("peer_indices", "core_indices", "indices"):
                value = context.get(key)
                if isinstance(value, (list, tuple, set)):
                    peers.extend(value)
            candidate_base = str(getattr(candidate, "instrument", "") or "").split()[0].upper()
            independent = {
                str(peer or "").split()[0].upper()
                for peer in peers
                if str(peer or "").strip()
            } - {candidate_base}
            if not independent:
                return False, "market-wide reversal lacks an independently confirmed peer"
        if SignalProcessor._grade_rank(grade) < SignalProcessor._grade_rank(min_grade):
            return False, f"market-wide reversal needs {min_grade}+ local grade"
        if confidence < min_conf:
            return False, f"market-wide reversal needs >= {min_conf:.0%} local confidence"
        return True, "market-wide reversal quality confirmed"

    def _quad_prime_raw_entry_decision(
        self,
        candidate: TradeCandidate,
        *,
        regime: str,
        confidence: float,
        risky_regime: bool,
        momentum_override: bool,
    ) -> Tuple[bool, bool, str]:
        """Classify Quad Prime raw entries before they bypass the normal live gate.

        Quad Prime's value is letting multiple raw engines contribute entries. The
        bug was treating every raw entry as both "admitted" and "scalp", including
        solo low-confidence flips. This keeps rare raw entries alive, while forcing
        weak solo flips back out and letting trend-quality raw entries run.
        """
        settings = get_settings()
        sources = self._quad_union_sources(candidate)
        source_count = len(sources)
        grade = str(getattr(candidate, "grade", "") or "")
        grade_rank = SignalProcessor._grade_rank(grade)
        timeframe = str(getattr(candidate, "timeframe", "") or "")
        try:
            adx_val = float(getattr(candidate, "adx_value", 0.0) or 0.0)
        except Exception:
            adx_val = 0.0
        try:
            intel_abs = abs(float(getattr(candidate, "intelligence_score", 0.0) or 0.0))
        except Exception:
            intel_abs = 0.0

        min_conf = float(getattr(settings, "quad_prime_raw_min_confidence", 0.50) or 0.50)
        multi_min_conf = float(
            getattr(settings, "quad_prime_raw_multi_source_min_confidence", 0.55) or 0.55
        )
        runner_min_conf = float(
            getattr(settings, "quad_prime_raw_runner_min_confidence", 0.70) or 0.70
        )
        trend_15m_agrees = self._candidate_15m_trend_agrees(candidate)
        volume_spike = bool(getattr(candidate, "volume_spike_entry", False))
        power_move = bool(getattr(candidate, "power_move", False))
        market_wide = bool(getattr(candidate, "market_wide_reversal_entry", False))
        one_way_cascade = bool(getattr(candidate, "one_way_cascade_entry", False))
        multi_confirmed = source_count >= 2 and grade_rank >= 2 and confidence >= multi_min_conf
        high_grade = grade_rank >= SignalProcessor._grade_rank("A") and confidence >= runner_min_conf
        b_grade_ok = SignalProcessor._b_grade_entry_allowed(
            confidence,
            regime,
            trend_15m_agrees=trend_15m_agrees,
            adx_value=adx_val,
            settings=settings,
        )
        # The intelligence leg has to point the SAME WAY as the trade. It read
        # `intel_abs >= 0.70` -- abs() of a SIGNED score -- so intelligence of -0.80,
        # i.e. strongly bearish, satisfied the bar for a LONG. It sits in an OR beside
        # adx and trend_15m_agrees, so it could carry the whole leg on its own, and
        # exceptional_spike has no grade floor: a C-grade at the 50% minimum with a
        # volume spike and intelligence arguing the opposite way was admitted.
        #
        # The sibling site at 20417 uses the same abs() safely because it is AND-ed
        # with trend_agrees, which already establishes direction. This one had nothing.
        # Signed comparison per the convention at 22511 and 22583.
        spike_min_intel = float(
            getattr(settings, "quad_prime_raw_spike_min_intel_score", 0.70) or 0.70
        )
        signed_intel = self._candidate_signed_intelligence(candidate)
        intel_aligned = (
            signed_intel >= spike_min_intel
            if self._candidate_signal_type(candidate) == "BUY"
            else signed_intel <= -spike_min_intel
        )
        exceptional_spike = bool(
            (power_move or volume_spike or momentum_override)
            and confidence >= min_conf
            and (adx_val >= 25.0 or intel_aligned or trend_15m_agrees)
        )
        # A market-wide reversal / one-way cascade is CONTEXT: it answers "may we be
        # positioned this way right now", which is why it was introduced — to relax
        # the opposite-EXPOSURE block for a cycle. It says nothing about whether this
        # particular signal is worth trading, so it may not also serve as the quality
        # floor. Every other term here already carries a confidence bar (0.70 / 0.55 /
        # 0.50 / 0.50); these two carried none, so any flip admitted anything.
        #
        # 2026-08-12 12:42: NIFTY (C, 12%) and SENSEX (C, 13%), solo-source, trend15
        # disagreeing, both admitted on this flag alone and both dead inside 90s for
        # -Rs.268 and -Rs.155. At 12:44 the same gate refused MIDCPNIFTY at B+/67%
        # with ADX 30 and trend15 agreeing. exceptional_spike is the template: a
        # special context that still has to clear quad_prime_raw_min_confidence.
        market_wide_ok, _market_wide_note = self._market_wide_candidate_quality(candidate)
        cascade_entry = bool(one_way_cascade and confidence >= min_conf)
        allowed = bool(
            high_grade
            or multi_confirmed
            or b_grade_ok
            or (market_wide and market_wide_ok)
            or cascade_entry
            or exceptional_spike
        )
        if not allowed:
            context = (
                f"solo_sources={source_count}, grade={grade}, conf={confidence:.0%}, "
                f"adx={adx_val:.1f}, intel={signed_intel:+.2f}, "
                f"trend15={trend_15m_agrees}, risky={risky_regime}"
            )
            return False, True, f"quad-prime raw quality floor failed ({context})"

        strong_momentum_context = bool(
            trend_15m_agrees
            and (
                is_trending_regime(regime)
                or adx_val >= float(getattr(settings, "momentum_override_threshold", 25.0) or 25.0)
                or confidence >= 0.85
            )
        )
        trend_runner = bool(
            self._setting_enabled(getattr(settings, "trend_entry_skip_scalp_lock", True), True)
            and strong_momentum_context
        )
        runner_quality = bool(high_grade or (multi_confirmed and confidence >= multi_min_conf))
        runner = bool(
            runner_quality
            and (trend_runner or timeframe == "15min" or not risky_regime)
            and not (market_wide or one_way_cascade or (exceptional_spike and not high_grade))
        )
        if one_way_cascade:
            return True, False, (
                f"quad-prime one-way cascade runner entry ({source_count} source(s), "
                f"{grade}, {confidence:.0%})"
            )
        if runner:
            return True, False, (
                f"quad-prime runner raw entry ({source_count} source(s), "
                f"{grade}, {confidence:.0%}, trend15={trend_15m_agrees})"
            )

        return True, True, (
            f"quad-prime scalp raw entry ({source_count} source(s), "
            f"{grade}, {confidence:.0%}, trend15={trend_15m_agrees})"
        )

    def _quad_union_pnl_context(self, row, current_price: float) -> Tuple[float, float, float]:
        try:
            price = float(current_price or 0.0)
            inst_type = str(getattr(row, "inst_type", "FUT") or "FUT").upper()
            if hasattr(row, "entry_price"):
                entry = float(getattr(row, "entry_price", 0.0) or 0.0)
                qty = int(getattr(row, "lots", 1) or 1) * int(getattr(row, "lot_size", 1) or 1)
                mult = 1.0 if inst_type == "OPT" else float(getattr(row, "instrument_multiplier", 1.0) or 1.0)
                contract_direction = "LONG" if inst_type == "OPT" else str(getattr(row, "direction", "LONG") or "LONG").upper()
                gross = (
                    (price - entry) * qty * mult
                    if contract_direction == "LONG"
                    else (entry - price) * qty * mult
                )
                settings = get_settings()
                charges = (
                    float(getattr(settings, "opt_cost", 80.0) or 80.0)
                    if inst_type == "OPT"
                    else float(getattr(settings, "fut_cost", 200.0) or 200.0)
                )
                net = gross - charges
            else:
                gross = self._candidate_gross_pnl(row, price)
                net = self._candidate_net_pnl(row, price)
            peak = max(float(getattr(row, "peak_pnl", 0.0) or 0.0), gross, 0.0)
            return float(gross), float(net), float(peak)
        except Exception:
            return 0.0, 0.0, 0.0

    def _quad_union_profit_threatened(self, row, net_pnl: float, peak_pnl: float) -> bool:
        if peak_pnl <= 0:
            return False
        inst_type = str(getattr(row, "inst_type", "FUT") or "FUT").upper()
        settings = get_settings()
        cost_floor = (
            float(getattr(settings, "opt_cost", 80.0) or 80.0)
            if inst_type == "OPT"
            else float(getattr(settings, "fut_cost", 200.0) or 200.0)
        )
        if peak_pnl >= 3000.0:
            floor = peak_pnl * 0.80
        elif peak_pnl >= 2000.0:
            floor = peak_pnl * 0.70
        elif peak_pnl >= 1000.0:
            floor = peak_pnl * 0.60
        elif peak_pnl >= max(cost_floor * 2.0, 250.0):
            floor = max(cost_floor, peak_pnl * 0.50)
        else:
            return net_pnl <= 0
        return net_pnl < floor

    def _quad_union_tighten_on_warning(
        self,
        row,
        current_price: float,
        sources: set,
        net_pnl: float,
        peak_pnl: float,
    ) -> None:
        try:
            inst_type = str(getattr(row, "inst_type", "FUT") or "FUT").upper()
            entry = float(getattr(row, "entry_price", getattr(row, "price", 0.0)) or 0.0)
            price = float(current_price or 0.0)
            if entry <= 0 or price <= 0:
                return
            contract_direction = "LONG" if inst_type == "OPT" else str(getattr(row, "direction", "LONG") or "LONG").upper()
            favorable = (price - entry) if contract_direction == "LONG" else (entry - price)
            if favorable <= 0:
                return
            if "supertrend" in sources:
                lock_ratio = 0.65
            elif "ema" in sources:
                lock_ratio = 0.50
            else:
                lock_ratio = 0.35
            lock_price = entry + (favorable * lock_ratio) if contract_direction == "LONG" else entry - (favorable * lock_ratio)
            if contract_direction == "LONG" and lock_price >= price:
                return
            if contract_direction == "SHORT" and lock_price <= price:
                return

            changed = False
            if hasattr(row, "current_stop"):
                current_stop = float(getattr(row, "current_stop", 0.0) or getattr(row, "trailing_stop", 0.0) or 0.0)
                if contract_direction == "LONG" and lock_price > current_stop:
                    row.current_stop = float(lock_price)
                    changed = True
                elif contract_direction == "SHORT" and (current_stop <= 0 or lock_price < current_stop):
                    row.current_stop = float(lock_price)
                    changed = True
                if changed and hasattr(self.trades, "save_state"):
                    self.trades.save_state()
            else:
                current_stop = float(getattr(row, "stop", 0.0) or 0.0)
                if contract_direction == "LONG" and lock_price > current_stop:
                    row.stop = float(lock_price)
                    changed = True
                elif contract_direction == "SHORT" and (current_stop <= 0 or lock_price < current_stop):
                    row.stop = float(lock_price)
                    changed = True
                if changed:
                    self._remember_trade_candidates([row])

            if changed:
                marker = f"{getattr(row, 'instrument', '')}|{getattr(row, 'timeframe', '')}|{','.join(sorted(sources))}|{lock_price:.2f}"
                if getattr(row, "_last_quad_union_warning", "") != marker:
                    setattr(row, "_last_quad_union_warning", marker)
                    self.log_event(
                        f"Quad-union opposite {','.join(sorted(sources))} warning for "
                        f"{getattr(row, 'instrument', '')} {getattr(row, 'timeframe', '')}: "
                        f"protected stop tightened to {lock_price:.2f} "
                        f"(net Rs.{net_pnl:.0f}, peak Rs.{peak_pnl:.0f}).",
                        "trade",
                    )
        except Exception as exc:
            logger.debug(f"Quad-union warning tighten skipped: {exc}")

    def _quad_union_opposite_exit_allowed(self, row, signal, current_price: float) -> bool:
        try:
            mode = str(getattr(get_settings(), "scanner_engine", "") or "").lower()
            if mode not in {"quad_union", "quad_prime"}:
                return True
            sources = self._quad_union_sources(signal)
            if not sources:
                return True
            _, net_pnl, peak_pnl = self._quad_union_pnl_context(row, float(current_price or 0.0))
            if mode == "quad_prime":
                trend_sources = sources & {"ema", "supertrend", "consensus"}
                has_utbot = "utbot" in sources
                has_trend_stack = bool(trend_sources)
                strong_trend_stack = "consensus" in trend_sources or len(trend_sources) >= 2
                if has_utbot and has_trend_stack:
                    return True
                if net_pnl <= 0 and (strong_trend_stack or has_utbot):
                    return True
                if self._quad_union_profit_threatened(row, net_pnl, peak_pnl):
                    return True
                self._quad_union_tighten_on_warning(row, float(current_price or 0.0), sources, net_pnl, peak_pnl)
                return False
            if len(sources) >= 4:
                return True
            if len(sources) >= 2 or "consensus" in sources:
                return True
            if net_pnl <= 0:
                return True
            if self._quad_union_profit_threatened(row, net_pnl, peak_pnl):
                return True
            self._quad_union_tighten_on_warning(row, float(current_price or 0.0), sources, net_pnl, peak_pnl)
            return False
        except Exception as exc:
            logger.debug(f"Quad-union opposite-exit policy failed open: {exc}")
            return True

    def _opposite_flip_quality_verdict(self, instrument: str, signal, timeframe: str = "") -> str:
        """Intel + move sanity read once a flip's confirm window has elapsed.

        Returns:
          "confirm"     — flip followed through; exit + reverse may proceed.
          "adverse"     — the flip's own move mean-reverted beyond tolerance;
                          hold (and cancel at the max window — not a reversal).
          "intel_block" — strong opposing market intelligence; hold until the
                          max window, then price decides.
        Fail-open: any data gap confirms (never brick protective exits).
        """
        settings = get_settings()
        if not self._setting_enabled(
            getattr(settings, "opposite_flip_intel_filter_enabled", True), True
        ):
            return "confirm"
        base = str(instrument or "").split()[0].upper()
        sig_type = str(getattr(signal, "signal_type", "") or "").upper()
        if sig_type not in {"BUY", "SELL"}:
            return "confirm"

        # 1) Move follow-through: flip that immediately mean-reverts is noise.
        adverse_cap = max(
            0.0,
            float(getattr(settings, "opposite_flip_max_adverse_move_pct", 0.10) or 0.10),
        )
        if adverse_cap > 0:
            try:
                live = float(self.candles.get_latest_price(base) or 0.0)
                ref = float(getattr(signal, "price", 0.0) or 0.0)
                if live > 0 and ref > 0:
                    signed_move_pct = (
                        (live - ref) / ref * 100.0 * (1.0 if sig_type == "BUY" else -1.0)
                    )
                    if signed_move_pct < -abs(adverse_cap):
                        return "adverse"
            except Exception:
                pass

        # 2) Market-intelligence read: strong opposing intel delays the flip.
        thr = max(
            0.0,
            float(getattr(settings, "opposite_flip_intel_block_threshold", 0.55) or 0.55),
        )
        if thr > 0:
            try:
                view = "LONG" if sig_type == "BUY" else "SHORT"
                tf = str(timeframe or getattr(signal, "timeframe", "") or "5min")
                if tf not in {"1min", "5min", "15min"}:
                    tf = "5min"
                intel = self._cached_timeframe_intel(base, tf, allow_fallback=True) or {}
                aggregate = (
                    intel.get("aggregate", {})
                    if isinstance(intel, dict) and isinstance(intel.get("aggregate"), dict)
                    else {}
                )
                signed = aggregate_intelligence_score(aggregate)
                aligned = self._view_aligned_intel_score(view, signed)
                if aligned <= -abs(thr):
                    return "intel_block"
            except Exception:
                pass
        return "confirm"

    def _opposite_exit_confirm_ready(self, instrument: str, signal, timeframe: str) -> bool:
        """Confirm an opposite UT1 flip before it may exit a live trade.

        The flip must persist for the confirm window (repaint_recheck_seconds
        clamped into [opposite_flip_confirm_min_seconds,
        opposite_flip_confirm_max_seconds], default 30–60s → 30s) AND pass an
        intel/move sanity read (``_opposite_flip_quality_verdict``) before it
        exits the live trade and hands the slot to the reverse entry. A flip
        that repaints (vanishes) never confirms; a flip whose move mean-reverts
        is cancelled at the max window; strong opposing intel delays confirm to
        the max window, then price decides. The timer starts at the flip's
        first appearance so it runs in parallel with entry stabilization.
        HISTORICAL mode is immediate to preserve exact backtest parity.
        Multi-index LTP shock force-exit bypasses this window entirely.
        """
        # Combo: a solo UT1 opposite-flip never confirms an exit — the partner must
        # flip (or both agree) to knock a live trade out. Checked before the HISTORICAL
        # short-circuit so live and backtest behave identically (A/B-able).
        if self._combo_solo_utbot_exit_blocked(signal):
            return False
        if getattr(self, "mode", "") == "HISTORICAL":
            return True
        # Only debounce when there is an actual opposite position to protect.
        # With no exposure, drop any lingering confirm timers for this index/TF so
        # a stale timer from an already-exited trade can never fast-track an
        # un-confirmed exit of a future position.
        if not self._has_opposite_exposure(instrument, signal, timeframe):
            cross_timeframe = str(getattr(get_settings(), "scanner_engine", "") or "").lower() == "quad_prime"
            stale_prefix = f"{instrument}|" if cross_timeframe else f"{instrument}|{timeframe}|"
            for stale in [k for k in self._pending_opposite_exit if k.startswith(stale_prefix)]:
                self._pending_opposite_exit.pop(stale, None)
            return True
        settings = get_settings()
        # Uniform confirm window for both 5min and 15min opposite flips:
        # repaint_recheck_seconds clamped into the 30–60s operator band.
        min_s = max(
            5.0,
            float(getattr(settings, "opposite_flip_confirm_min_seconds", 30.0) or 30.0),
        )
        max_s = max(
            min_s,
            float(getattr(settings, "opposite_flip_confirm_max_seconds", 60.0) or 60.0),
        )
        buffer_seconds = min(
            max_s,
            max(min_s, float(getattr(settings, "repaint_recheck_seconds", 20.0) or 20.0)),
        )
        sig_ts = getattr(signal, "timestamp", None)
        identity = (
            f"{instrument}|{timeframe}|{getattr(signal, 'signal_type', '')}|"
            f"{sig_ts.isoformat() if sig_ts is not None else ''}"
        )
        pending = self._pending_opposite_exit
        now = time.monotonic()
        first_seen = pending.get(identity)
        if first_seen is None:
            # A different identity for this index/TF means the prior flip changed
            # or repainted — drop its stale timer so it can never confirm.
            for stale in [k for k in pending if k.startswith(f"{instrument}|{timeframe}|") and k != identity]:
                pending.pop(stale, None)
            pending[identity] = now
            self.log_event(
                f"Opposite {signal.signal_type} on {instrument} {timeframe} pending "
                f"{buffer_seconds:.0f}s repaint-confirm before exit.",
                "trade",
            )
            return False
        elapsed = now - first_seen
        if elapsed < buffer_seconds:
            return False
        # Window elapsed — intel/move sanity read decides the hand-off.
        verdict = self._opposite_flip_quality_verdict(instrument, signal, timeframe)
        if verdict == "confirm":
            pending.pop(identity, None)
            return True
        if elapsed >= max_s:
            # Max window reached: an adverse (mean-reverted) flip is cancelled —
            # it was noise, the live trade continues. An intel-only hold expires
            # and price action wins: the flip confirms.
            pending.pop(identity, None)
            if verdict == "adverse":
                self.log_event(
                    f"Opposite {getattr(signal, 'signal_type', '')} on {instrument} "
                    f"{timeframe} cancelled at {max_s:.0f}s: move mean-reverted "
                    "(flip did not follow through).",
                    "trade",
                )
                return False
            return True
        return False

    def _market_ltp_shock_force_exit_opposite(
        self,
        instrument: str,
        signal,
        timeframe: str,
    ) -> bool:
        """True when multi-index LTP shock should force-exit opposite exposure now.

        Setting: ``market_ltp_shock_force_exit_opposite`` (default True).
        Evaluates shock live so it works even when the signal is not yet tagged
        (process_best_signal runs opposite-exit before late taggers).
        """
        settings = get_settings()
        if not self._setting_enabled(
            getattr(settings, "market_ltp_shock_force_exit_opposite", True), True
        ):
            return False
        if not self._setting_enabled(
            getattr(settings, "market_ltp_shock_enabled", True), True
        ):
            return False
        sig_type = str(getattr(signal, "signal_type", "") or "").upper()
        if sig_type not in {"BUY", "SELL"}:
            return False
        if not self._has_opposite_exposure(instrument, signal, timeframe):
            return False
        if bool(getattr(signal, "market_ltp_shock_entry", False)):
            return True
        # Market-wide candle reverse is the same multi-index intent.
        if bool(getattr(signal, "market_wide_reversal_entry", False)):
            return True
        try:
            ctx = self._evaluate_market_ltp_shock(
                instrument,
                sig_type,
                getattr(signal, "timestamp", None),
                timeframe=str(timeframe or ""),
            )
        except Exception:
            ctx = None
        if not ctx:
            return False
        try:
            setattr(signal, "market_ltp_shock_entry", True)
            setattr(signal, "market_ltp_shock_context", ctx)
        except Exception:
            pass
        return True

    def _handle_opposite_signal_exit(self, instrument: str, signal, timeframe: str) -> bool:
        """Exit/notify on raw opposite UT signals before entry filters can block them."""
        if signal.signal_type not in ("BUY", "SELL"):
            return False
        cross_timeframe = str(getattr(get_settings(), "scanner_engine", "") or "").lower() == "quad_prime"

        # Multi-index LTP shock: force-exit opposite books immediately — skip the
        # ~20s repaint-confirm wait so reverse PE/CE can enter the same cycle.
        force_shock_exit = False
        try:
            force_shock_exit = bool(
                self._market_ltp_shock_force_exit_opposite(instrument, signal, timeframe)
            )
        except Exception as exc:
            logger.debug(f"LTP shock force-exit check skipped for {instrument}: {exc}")
            force_shock_exit = False

        if force_shock_exit:
            try:
                pending = getattr(self, "_pending_opposite_exit", None)
                if isinstance(pending, dict):
                    prefix = f"{instrument}|{timeframe}|"
                    for stale in [k for k in list(pending.keys()) if str(k).startswith(prefix)]:
                        pending.pop(stale, None)
                self.log_event(
                    f"LTP shock force-exit opposite: {instrument} {timeframe} "
                    f"{getattr(signal, 'signal_type', '')} — skipping repaint wait",
                    "trade",
                )
            except Exception:
                pass
        else:
            # Live repaint-confirm: hold the exit until the opposite flip survives the
            # stabilization buffer; a flip that repaints within the window is ignored
            # and the existing trade continues.
            if not self._opposite_exit_confirm_ready(instrument, signal, timeframe):
                return False

        signal_ts = signal.timestamp
        handled = False
        exit_reason_code = "LTP_SHOCK_OPPOSITE" if force_shock_exit else "OPPOSITE_SIGNAL"
        for trade_id, trade in list(getattr(self.trades, "open_trades", {}).items()):
            if str(getattr(trade, "instrument", "") or "").split()[0] != instrument:
                continue
            if not cross_timeframe and str(getattr(trade, "timeframe", "") or "") != timeframe:
                continue
            is_opposite = (
                (trade.direction == "LONG" and signal.signal_type == "SELL")
                or (trade.direction == "SHORT" and signal.signal_type == "BUY")
            )
            if not is_opposite:
                continue
            dedupe_key = f"BROKER_{trade_id}_{signal_ts.isoformat()}"
            if self._last_opposite_exit_signal_time.get(dedupe_key) == signal_ts:
                continue
            exit_price = (
                self._get_live_premium_cached(trade)
                if str(getattr(trade, "inst_type", "") or "").upper() == "OPT"
                else self.candles.get_latest_price(instrument)
            )
            exit_price = float(exit_price or getattr(trade, "current_price", 0.0) or signal.price)
            if not self._quad_union_opposite_exit_allowed(trade, signal, exit_price):
                continue
            self._close_and_record(
                trade_id,
                exit_price,
                exit_reason_code,
                exit_time=signal_ts,
            )
            self._last_opposite_exit_signal_time[dedupe_key] = signal_ts
            handled = True

        latest_rows = list(getattr(self, "_latest_trade_candidates", {}).get(instrument, []) or [])
        row_timeframe = None if cross_timeframe else timeframe
        session_rows = self._active_session_entry_candidates(instrument, timeframe=row_timeframe, as_of=signal_ts)
        candidates_by_key: Dict[str, TradeCandidate] = {}
        for candidate in latest_rows + session_rows:
            candidates_by_key[self._candidate_history_key(candidate)] = candidate

        for previous in candidates_by_key.values():
            if not cross_timeframe and previous.timeframe != timeframe:
                continue
            if getattr(previous, "action", "ENTRY") in ("EXIT", "NO_ENTRY"):
                continue
            prev_ts = getattr(previous, "signal_timestamp", None)
            if not prev_ts or signal_ts <= prev_ts:
                continue
            is_opposite = (
                (previous.direction == "LONG" and signal.signal_type == "SELL") or
                (previous.direction == "SHORT" and signal.signal_type == "BUY")
            )
            if not is_opposite:
                continue

            dedupe_key = f"MANUAL_{instrument}_{previous.timeframe}_{previous.direction}_{prev_ts.isoformat()}"
            if self._last_opposite_exit_signal_time.get(dedupe_key) == signal_ts:
                continue

            existing_exit = any(
                getattr(row, "action", "ENTRY") == "EXIT"
                and getattr(row, "timeframe", "") == previous.timeframe
                and getattr(row, "direction", "") == previous.direction
                and getattr(row, "signal_timestamp", None) == prev_ts
                for row in self._get_session_trade_candidates(instrument)
            )
            if existing_exit:
                continue

            # Calculate immediate exit price and P&L
            if previous.inst_type == "OPT":
                proposed_exit_px = self._get_live_premium_cached(previous) or previous.current_price or previous.price
            else:
                proposed_exit_px = signal.price
            if not self._quad_union_opposite_exit_allowed(previous, signal, float(proposed_exit_px or 0.0)):
                continue
            exit_px, exit_reason, reason_text = self._candidate_exit_resolution(
                previous,
                float(proposed_exit_px),
                exit_reason_code,
                (
                    f"LTP shock force-exit opposite {signal.signal_type}"
                    if force_shock_exit
                    else f"Opposite {signal.signal_type} signal"
                ),
            )
            calc_pnl = self._candidate_net_pnl(previous, exit_px)

            exit_candidate = TradeCandidate(
                instrument=previous.instrument,
                direction=previous.direction,
                price=previous.price,
                stop=previous.stop,
                target=previous.target,
                lots=previous.lots,
                lot_size=previous.lot_size,
                grade=previous.grade,
                confidence=previous.confidence,
                timeframe=previous.timeframe,
                inst_type=previous.inst_type,
                option_type=previous.option_type,
                atm_strike=previous.atm_strike,
                multiplier=previous.multiplier,
                trading_symbol=previous.trading_symbol,
                symbol_token=previous.symbol_token,
                rr=previous.rr,
                score=previous.score,
                reasons=list(previous.reasons or []) + [f"{reason_text} at {signal_ts:%H:%M}"],
                spot_stop=previous.spot_stop,
                spot_target=previous.spot_target,
                signal_timestamp=prev_ts or signal_ts,
                current_price=exit_px,
                pnl=calc_pnl,
                status="EXIT SIGNAL",
                action="EXIT",
                exit_reason=exit_reason,
                source_engine=str(getattr(previous, "source_engine", "") or ""),
                source_engines=list(getattr(previous, "source_engines", []) or []),
                source_lane=str(getattr(previous, "source_lane", "") or ""),
                quad_union_entry=bool(getattr(previous, "quad_union_entry", False)),
                raw_union_entry=bool(getattr(previous, "raw_union_entry", False)),
            )
            setattr(exit_candidate, "exit_timestamp", signal_ts)
            setattr(exit_candidate, "exit_price", float(exit_px))
            self._inherit_exit_entry_metadata(exit_candidate, previous)

            self._refresh_trade_candidates([exit_candidate], self.config.get("indices", {}).get(instrument, {}))
            self._latest_exit_candidates[instrument] = [exit_candidate]
            self._remember_trade_candidates([exit_candidate])
            self._last_opposite_exit_signal_time[dedupe_key] = signal_ts
            self.log_event(
                f"Manual EXIT {previous.direction} {instrument} ({previous.timeframe} closed by {exit_reason})",
                "trade",
            )
            self._notify(
                f"MANUAL EXIT {previous.direction} {instrument} @ {exit_candidate.current_price:.2f} | {previous.timeframe} closed by {exit_reason}",
                "sell",
            )
            handled = True

        return handled

    def _passes_timeframe_entry_policy(self, candidate: TradeCandidate) -> bool:
        """Return whether a candidate may become a fresh live/manual entry.

        PRIMARY_15 only restricts plain 5min structure entries. 1min SPIKE /
        SNAPBACK (and other fast 1m chassis flags) are never blocked here —
        those paths are governed solely by their own settings toggles.
        """
        if getattr(self, "mode", "") == "HISTORICAL":
            return True

        if self._is_quad_prime_raw_candidate(candidate):
            return True

        timeframe = str(getattr(candidate, "timeframe", "") or "")
        # Fast 1m paths: independent of TF policy / engine.
        if timeframe == "1min" and (
            bool(getattr(candidate, "volume_spike_entry", False))
            or bool(getattr(candidate, "is_reversion_scalp", False))
            or bool(getattr(candidate, "market_ltp_shock_entry", False))
            or bool(getattr(candidate, "market_wide_reversal_entry", False))
        ):
            return True

        policy = str(getattr(get_settings(), "ut_timeframe_entry_policy", "PRIMARY_15") or "PRIMARY_15").upper()
        if policy == "PRIMARY_15" and timeframe == "5min":
            return self._gate_block(
                candidate,
                f"Live Gate: blocked {candidate.instrument} {timeframe} {candidate.direction}; "
                "15M MAIN policy treats 5min as timing/exit-only.",
            )
        return True

    def _market_location_entry_gate(self, candidate: TradeCandidate) -> Tuple[bool, str]:
        """Classify live entries that are badly located inside the intraday structure."""
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "ut_market_location_gate", True), True):
            return True, ""
        if getattr(self, "mode", "") == "HISTORICAL":
            return True, ""

        try:
            df = self.candles.get_candles(candidate.instrument, "1min")
        except Exception as exc:
            logger.debug(f"Market location gate skipped for {candidate.instrument}: candle read failed: {exc}")
            return True, ""
        if df is None or len(df) < 12:
            return True, ""

        work = df.copy()
        if not isinstance(work.index, pd.DatetimeIndex):
            if "timestamp" not in work.columns:
                return True, ""
            work["timestamp"] = pd.to_datetime(work["timestamp"], errors="coerce")
            work = work.dropna(subset=["timestamp"]).set_index("timestamp")
        if work.empty or "close" not in work.columns:
            return True, ""

        work = work.sort_index()
        signal_ts = getattr(candidate, "signal_timestamp", None)
        if signal_ts is not None:
            signal_ts = pd.Timestamp(signal_ts)
            if signal_ts.tzinfo is not None:
                signal_ts = signal_ts.tz_convert(IST).tz_localize(None)
            work = work[work.index <= signal_ts]
        if len(work) < 12:
            return True, ""

        try:
            closes = work["close"].astype(float)
            highs = work["high"].astype(float) if "high" in work.columns else closes
            lows = work["low"].astype(float) if "low" in work.columns else closes
            opens = work["open"].astype(float) if "open" in work.columns else closes
        except Exception:
            return True, ""

        close = float(closes.iloc[-1])
        if close <= 0:
            return True, ""
        setattr(candidate, "entry_spot", close)
        day_high = float(highs.max())
        day_low = float(lows.min())
        day_range = max(day_high - day_low, close * 0.0001)
        position_pct = (close - day_low) / day_range
        ema9 = float(closes.ewm(span=9, adjust=False).mean().iloc[-1])
        ema21 = float(closes.ewm(span=21, adjust=False).mean().iloc[-1])
        prior = float(closes.iloc[-6]) if len(closes) >= 6 else float(closes.iloc[0])
        impulse_pct = ((close - prior) / close) * 100.0
        last_open = float(opens.iloc[-1])
        prev_close = float(closes.iloc[-2]) if len(closes) >= 2 else close
        direction = str(getattr(candidate, "direction", "") or "").upper()
        timeframe = str(getattr(candidate, "timeframe", "") or "")

        bullish_reversal = (
            position_pct <= 0.38
            and close > ema9
            and close > last_open
            and close > prev_close
        )
        bearish_reversal = (
            position_pct >= 0.62
            and close < ema9
            and close < last_open
            and close < prev_close
        )
        long_structure_ok = close >= ema21 and ema9 >= ema21
        short_structure_ok = close <= ema21 and ema9 <= ema21
        risk_reason = ""

        if direction == "LONG":
            if not long_structure_ok and not bullish_reversal:
                risk_reason = (
                    f"Market location risk LONG: spot {close:.2f} below/against EMA structure "
                    f"(EMA9 {ema9:.2f}, EMA21 {ema21:.2f}, day-pos {position_pct:.0%})"
                )
            if timeframe == "5min" and position_pct >= 0.78 and impulse_pct >= 0.18 and not bullish_reversal:
                risk_reason = (
                    f"Market location risk LONG chase: day-pos {position_pct:.0%}, "
                    f"last-5m impulse {impulse_pct:.2f}%"
                )
        elif direction == "SHORT":
            if not short_structure_ok and not bearish_reversal:
                risk_reason = (
                    f"Market location risk SHORT: spot {close:.2f} above/against EMA structure "
                    f"(EMA9 {ema9:.2f}, EMA21 {ema21:.2f}, day-pos {position_pct:.0%})"
                )
            if timeframe == "5min" and position_pct <= 0.22 and impulse_pct <= -0.18 and not bearish_reversal:
                risk_reason = (
                    f"Market location risk SHORT chase: day-pos {position_pct:.0%}, "
                    f"last-5m impulse {impulse_pct:.2f}%"
                )

        if risk_reason:
            setattr(candidate, "location_risk", risk_reason)
            setattr(candidate, "location_position_pct", float(position_pct))
            inst_type = str(getattr(candidate, "inst_type", "") or "").upper()
            # Own-timeframe regime; latest_regimes[instrument] is the 5-minute label.
            regime = self._get_trade_regime(candidate, default="UNKNOWN")
            reasons_text = " | ".join(str(reason) for reason in (getattr(candidate, "reasons", []) or [])).lower()
            try:
                intel_abs = abs(float(getattr(candidate, "intelligence_score", 0.0) or 0.0))
            except Exception:
                intel_abs = 0.0
            try:
                adx_val = float(getattr(candidate, "adx_value", 0.0) or 0.0)
            except Exception:
                adx_val = 0.0
            settings = get_settings()
            momentum_threshold = float(getattr(settings, "momentum_override_threshold", 25.0) or 25.0)
            trend_agrees = self._candidate_15m_trend_agrees(candidate)
            # A 15m-aligned entry in a trending regime is a trend pullback, NOT a scalp:
            # forcing scalp_lock_mode arms the tightest profit-lock and chokes the runner.
            # Let such entries run; everything else keeps the cautious scalp lock.
            trend_pullback_entry = (
                is_trending_regime(regime)
                and trend_agrees
                # Releasing the scalp lock is a PRIVILEGE: it loosens the tightest
                # profit lock and lets the runner run. A borrowed 5-minute label must
                # not buy that for a 15-minute candidate. Missing own-TF label keeps
                # the cautious lock, which is the conservative direction.
                and self._trade_regime_is_own_timeframe(candidate)
                and self._setting_enabled(getattr(settings, "trend_entry_skip_scalp_lock", True), True)
            )
            setattr(candidate, "scalp_lock_mode", not trend_pullback_entry)
            strict_option_exception = bool(
                getattr(candidate, "impulse_confirmed", False)
                and trend_agrees
                and (
                    intel_abs >= 0.70
                    or "institutional volume/oi confirmed" in reasons_text
                    or (
                        bool(getattr(candidate, "is_explosive_bypass", False))
                        and adx_val >= momentum_threshold + 10.0
                    )
                )
            )
            if bool(getattr(candidate, "one_way_cascade_entry", False)):
                self._set_scalp_lock(candidate, False)
                setattr(candidate, "location_decision", "REDUCED_RISK")
                ctx = getattr(candidate, "one_way_cascade_context", None)
                move_label = "one-way cascade"
                if isinstance(ctx, dict):
                    move_label = str(ctx.get("move_label") or move_label)
                return True, (
                    f"{risk_reason}; synchronized {move_label} confirmed "
                    "(tight entry risk, runner trail)"
                )
            if bool(getattr(candidate, "late_session_reclaim_entry", False)):
                self._set_scalp_lock(candidate, True)
                setattr(candidate, "location_decision", "REDUCED_RISK")
                move_label = "directional move"
                ctx = getattr(candidate, "late_session_reclaim_context", None)
                if isinstance(ctx, dict):
                    move_label = str(ctx.get("move_label") or move_label)
                return True, (
                    f"{risk_reason}; late-session synchronized {move_label} confirmed "
                    "(tight scalp risk)"
                )
            if inst_type == "OPT" and is_risky_regime(regime):
                reduced_risk = strict_option_exception
            else:
                reduced_risk = bool(
                    getattr(candidate, "impulse_confirmed", False)
                    and trend_agrees
                )
            setattr(candidate, "location_decision", "REDUCED_RISK" if reduced_risk else "BLOCK")
            return reduced_risk, risk_reason

        setattr(candidate, "scalp_lock_mode", False)
        setattr(candidate, "location_decision", "ALLOW")
        return True, ""

    def _candidate_15m_trend_agrees(self, candidate: TradeCandidate) -> bool:
        """Return whether the live 15m position supports this candidate's direction."""
        stored = getattr(candidate, "trend_15m_agrees", None)
        if stored is not None:
            return bool(stored)
        expected = 1 if str(getattr(candidate, "direction", "") or "").upper() == "LONG" else -1
        key = f"{getattr(candidate, 'instrument', '')}_15min"
        try:
            engine = getattr(getattr(self, "mtf", None), "engines", {}).get(key)
            state = engine.get_state(key) if engine else None
            position = int(getattr(state, "position", 0) or 0)
            agrees = position == expected
            setattr(candidate, "trend_15m_agrees", agrees)
            return agrees
        except Exception:
            return False

    def _passes_candidate_grade_preference(self, candidate: TradeCandidate) -> Tuple[bool, str]:
        """Apply grade preference without undoing an explicit 5m/15m agreement."""
        settings = get_settings()
        grade_pref = self._normalize_signal_grade_preference(
            getattr(settings, "signal_grade_preference", "auto")
        )
        grade_hierarchy = {"C": 0, "B": 1, "B+": 2, "A": 3, "A+": 4}
        raw_grade = str(getattr(candidate, "grade", "") or "")
        base_grade = raw_grade.split()[0] if raw_grade else "C"
        sig_rank = grade_hierarchy.get(base_grade, 0)

        if getattr(candidate, "quad_union_entry", False) or getattr(candidate, "raw_union_entry", False):
            return True, "quad-union raw entry after repaint buffer"

        if getattr(candidate, "power_move", False):
            return True, "power-move override (data-confirmed)"
        if getattr(candidate, "one_way_cascade_entry", False):
            return True, "one-way cascade runner override"
        if getattr(candidate, "missed_signal_reentry", False):
            return True, "missed-signal re-entry support override"
        if getattr(candidate, "late_session_reclaim_entry", False):
            return True, "late-session synchronized directional-move override"
        if getattr(candidate, "market_wide_reversal_entry", False):
            return True, "market-wide reversal override"

        if str(getattr(candidate, "timeframe", "") or "") == "5min" and self._candidate_15m_trend_agrees(candidate):
            return True, "15min trend agreement override"

        # The candidate's OWN timeframe, not the instrument-keyed 5-minute label.
        # latest_regimes[instrument] IS the 5-minute regime (see its declaration), and
        # 5m/15m labels disagree in 83% of same-timestamp pairs.
        current_regime = self._get_trade_regime(candidate, default="UNKNOWN")

        # Qualifying B-grade (trending + 15m alignment + ADX momentum) bypasses the
        # grade-preference floor; the strict live gate still enforces the full rule.
        #
        # This is a PRIVILEGE — it admits a B-band signal that the floor would refuse —
        # so it must rest on the candidate's own-timeframe regime. _get_trade_regime
        # falls back to the 5-minute label so tightening always has something to work
        # with, and _trade_regime_is_own_timeframe exists precisely to stop that
        # borrowed label granting anything: "it must NOT be used to grant a privilege:
        # a 15-minute trade could otherwise enter runner mode on a 5-minute regime."
        # The rule was enforced for runner mode and not here.
        if self._trade_regime_is_own_timeframe(candidate) and SignalProcessor._b_grade_entry_allowed(
            float(getattr(candidate, "confidence", 0.0) or 0.0),
            current_regime,
            trend_15m_agrees=self._candidate_15m_trend_agrees(candidate),
            adx_value=float(getattr(candidate, "adx_value", 0.0) or 0.0),
            settings=settings,
        ):
            return True, "qualifying B-grade (trending+align+ADX)"
        regime_adaptation = self._setting_enabled(getattr(settings, "ut_regime_adaptation", True), True)
        is_choppy = regime_adaptation and current_regime in {
            "CHOPPY",
            "SIDEWAYS",
            "MEAN_REVERTING",
            "RANGING",
            "VOLATILE",
            "UNKNOWN",
        }
        if grade_pref == "B":
            min_rank = 1 if candidate.inst_type == "FUT" else 2
        elif grade_pref == "B+":
            min_rank = 2
        elif grade_pref == "A":
            min_rank = 3
        elif grade_pref == "A+":
            min_rank = 4
        else:
            min_rank = 3 if is_choppy else 2

        if sig_rank >= min_rank or "Recovered" in raw_grade or "EOD" in raw_grade:
            return True, ""
        reason = f"Low Grade: {raw_grade}" if sig_rank < 1 else f"Below Grade Pref ({grade_pref})"
        return False, reason

    def _gate_block(self, candidate: TradeCandidate, message: str) -> bool:
        """Reject a candidate at a live entry gate, logging the reason to BOTH the
        file log and the dashboard live tape (deduped once per signal) so a
        detected signal never disappears from the tape without a verdict."""
        logger.info(message)
        # Tape logging must never alter the gate's decision (e.g. bare test
        # instances without an activity log). Fail closed to the file log only.
        try:
            ts = getattr(candidate, "signal_timestamp", None)
            key = (
                f"livegate|{getattr(candidate, 'instrument', '')}|"
                f"{getattr(candidate, 'timeframe', '')}|{getattr(candidate, 'direction', '')}|"
                f"{ts.isoformat(timespec='seconds') if ts is not None else ''}"
            )
            tape_msg = message.replace("Live Gate: blocked ", "Signal rejected: ")
            self.log_signal_decision_once(key, tape_msg, "trade")
        except Exception as exc:
            logger.debug(f"Live-gate tape log skipped: {exc}")
        return False

    def _passes_live_trade_ready_gate(self, candidate: TradeCandidate) -> bool:
        """Final live/manual gate before a signal is allowed into the session ledger."""
        if getattr(self, "mode", "") == "HISTORICAL":
            return True

        settings = get_settings()

        # Macro-event blackout (RBI/budget etc.) — user-maintained windows in
        # data_store/event_blackouts.json; gated DEFAULT OFF. Blocks fresh
        # ENTRIES only; exits/trailing on open trades are never touched.
        if self._setting_enabled(getattr(settings, "event_blackout_enabled", False), False):
            try:
                from data.market_calendar import load_event_blackout_windows, active_event_blackout
                label = active_event_blackout(
                    datetime.now(IST).replace(tzinfo=None),
                    load_event_blackout_windows(),
                )
                if label:
                    self.log_signal_decision_once(
                        f"{candidate.instrument}|{candidate.timeframe}|{candidate.direction}|event-blackout|{label}",
                        f"Signal rejected: {candidate.instrument} {candidate.direction} "
                        f"{candidate.timeframe} - macro-event blackout active ({label})",
                        "trade",
                    )
                    return False
            except Exception as exc:
                logger.debug(f"Event blackout check skipped: {exc}")
        # Fix 4: an entry taken in the final minutes has no runway to run — mark it
        # protect-first-profit so the scalp-lock arming applies for the rest of the day.
        setattr(candidate, "_late_entry_scalp", self._late_entry_scalp_active(candidate))
        confidence = float(getattr(candidate, "confidence", 0.0) or 0.0)
        # Own-timeframe regime; latest_regimes[instrument] is the 5-minute label. Here it
        # drives the choppy VETO, so a borrowed label is conservative in one direction but
        # can also fail to veto a chop-bound 15-minute entry when the 5-minute pocket trends.
        regime = self._get_trade_regime(candidate, default="UNKNOWN")
        # Intraday Momentum Override
        adx_val = getattr(candidate, "adx_value", 0.0)
        momentum_threshold = float(getattr(settings, "momentum_override_threshold", 25.0) or 25.0)
        momentum_override = bool(
            getattr(candidate, "impulse_confirmed", False)
            and getattr(candidate, "is_explosive_bypass", False)
            and float(adx_val or 0.0) >= momentum_threshold
        )
        choppy_regimes = {"CHOPPY", "SIDEWAYS", "MEAN_REVERTING", "RANGING", "VOLATILE", "UNKNOWN"}
        regime_adaptation = self._setting_enabled(getattr(settings, "ut_regime_adaptation", True), True)
        risky_regime = regime_adaptation and (regime in choppy_regimes)
        is_choppy = risky_regime and not momentum_override
        if momentum_override and risky_regime:
            logger.info(f"🚀 [OVERRIDE] Live Choppy regime bypassed due to strong ADX ({adx_val:.1f} >= {momentum_threshold})")
        timeframe = str(getattr(candidate, "timeframe", "") or "")
        inst_type = str(getattr(candidate, "inst_type", "") or "").upper()

        if not self._passes_timeframe_entry_policy(candidate):
            return False

        late_guard = getattr(self, "_late_session_entry_block_reason", None)
        late_block_reason = late_guard(candidate) if callable(late_guard) else ""
        if late_block_reason:
            return self._gate_block(
                candidate,
                f"Live Gate: blocked {candidate.instrument} {timeframe} {candidate.direction}; {late_block_reason}.",
            )

        choppy_scalp_guard = getattr(self, "_fifteen_min_choppy_scalp_context", None)
        choppy_scalp_ok, choppy_scalp_reason = (
            choppy_scalp_guard(candidate, regime)
            if callable(choppy_scalp_guard)
            else (True, "")
        )
        if not choppy_scalp_ok:
            return self._gate_block(
                candidate,
                f"Live Gate: blocked {candidate.instrument} {timeframe} {candidate.direction}; {choppy_scalp_reason}.",
            )

        if getattr(candidate, "quad_union_entry", False) or getattr(candidate, "raw_union_entry", False):
            source = str(getattr(candidate, "source_engine", "") or "quad_union")
            raw_allowed, raw_scalp, raw_reason = self._quad_prime_raw_entry_decision(
                candidate,
                regime=regime,
                confidence=confidence,
                risky_regime=risky_regime,
                momentum_override=momentum_override,
            )
            if not raw_allowed:
                return self._gate_block(
                    candidate,
                    f"Live Gate: blocked {candidate.instrument} {timeframe} {candidate.direction}; {raw_reason}.",
                )
            location_ok, location_reason = self._market_location_entry_gate(candidate)
            location_scalp = bool(getattr(candidate, "scalp_lock_mode", False)) if location_reason else False
            if location_reason:
                try:
                    candidate.reasons = list(candidate.reasons or []) + [location_reason]
                    if raw_scalp or location_scalp:
                        candidate.reasons.append("Scalp lock mode: protect first profit fast")
                except Exception:
                    pass
                if not location_ok:
                    return self._gate_block(
                        candidate,
                        f"Live Gate: blocked {candidate.instrument} {timeframe} {candidate.direction}; "
                        f"{location_reason}",
                    )
                logger.info(
                    f"Live Gate: allowing raw entry {candidate.instrument} {timeframe} "
                    f"{candidate.direction} with reduced-risk location handling; {location_reason}"
                )
            self._set_scalp_lock(
                candidate,
                bool(raw_scalp or location_scalp or getattr(candidate, "fifteen_min_choppy_scalp_entry", False)),
            )
            logger.info(
                f"Live Gate: raw entry admitting {candidate.instrument} "
                f"{timeframe} {candidate.direction} from {source} "
                f"({candidate.grade}, {confidence:.0%}) after repaint buffer; "
                f"{raw_reason}; scalp_lock={bool(getattr(candidate, 'scalp_lock_mode', False))}."
            )
            return True

        if getattr(candidate, "one_way_cascade_entry", False):
            logger.info(
                f"Live Gate: one-way cascade override admitting {candidate.instrument} "
                f"{timeframe} {candidate.direction} ({candidate.grade}, {confidence:.0%}) "
                "with tight entry risk and runner trailing."
            )
            self._set_scalp_lock(candidate, False)
            return True

        if getattr(candidate, "missed_signal_reentry", False):
            reentry_ctx = getattr(candidate, "missed_signal_reentry_context", {}) or {}
            is_runner = str(reentry_ctx.get("type") or "") == "one_way_cascade"
            logger.info(
                f"Live Gate: missed-signal re-entry admitting {candidate.instrument} "
                f"{timeframe} {candidate.direction} ({candidate.grade}, {confidence:.0%}); "
                f"{reentry_ctx.get('type', 'support')} support, "
                f"age {float(reentry_ctx.get('age_seconds', 0.0) or 0.0):.0f}s."
            )
            self._set_scalp_lock(candidate, not is_runner)
            return True

        if getattr(candidate, "market_wide_reversal_entry", False):
            logger.info(
                f"Live Gate: market-wide reversal override admitting {candidate.instrument} "
                f"{timeframe} {candidate.direction} ({candidate.grade}, {confidence:.0%}) "
                "with scalp-lock risk."
            )
            self._set_scalp_lock(candidate, True)
            return True

        if getattr(candidate, "late_session_reclaim_entry", False):
            logger.info(
                f"Live Gate: late-session directional-move override admitting {candidate.instrument} "
                f"{timeframe} {candidate.direction} ({candidate.grade}, {confidence:.0%}) "
                "with tight scalp risk."
            )
            self._set_scalp_lock(candidate, True)
            return True

        # Data-confirmed power move: bypass grade/regime/confidence floors and the
        # market-location chase guard (it IS a confirmed directional thrust). It still
        # respects the timeframe entry policy above and the hard late cutoff (applied
        # at signal resolution), and enters in tight scalp-lock mode.
        if getattr(candidate, "power_move", False):
            logger.info(
                f"Live Gate: ⚡ power-move override admitting {candidate.instrument} {timeframe} "
                f"{candidate.direction} ({candidate.grade}, {confidence:.0%}) in scalp-lock mode."
            )
            self._set_scalp_lock(candidate, True)
            return True

        if regime == "UNKNOWN" and confidence < SignalProcessor._grade_min_confidence("A"):
            return self._gate_block(candidate, f"Live Gate: blocked {candidate.instrument} {timeframe} {candidate.direction}; UNKNOWN regime requires A/A+ (confidence >= 0.70).")

        location_ok, location_reason = self._market_location_entry_gate(candidate)
        # Fix 4: a late entry protects first profit even when well-located.
        self._set_scalp_lock(candidate, bool(getattr(candidate, "scalp_lock_mode", False)))
        if location_reason:
            try:
                candidate.reasons = list(candidate.reasons or []) + [location_reason, "Scalp lock mode: protect first profit fast"]
            except Exception:
                pass
            if not location_ok:
                return self._gate_block(
                    candidate,
                    f"Live Gate: blocked {candidate.instrument} {timeframe} {candidate.direction}; "
                    f"{location_reason}",
                )
            logger.info(
                f"Live Gate: allowing confirmed impulse {candidate.instrument} {timeframe} "
                f"{candidate.direction} in reduced-risk scalp-lock mode; {location_reason}"
            )

        # Dedicated B-grade path: a B-band signal (conf 0.40-0.55) may trade ONLY in a
        # trending/breakout regime with 15m alignment and ADX momentum (>=25), FUT or OPT.
        # Higher tiers (B+/A/A+) skip this and use the standard floors below.
        if confidence < SignalProcessor._grade_min_confidence("B+"):
            if SignalProcessor._b_grade_entry_allowed(
                confidence,
                regime,
                trend_15m_agrees=self._candidate_15m_trend_agrees(candidate),
                adx_value=float(adx_val or 0.0),
                settings=settings,
            ):
                return True
            return self._gate_block(
                candidate,
                f"Live Gate: blocked {candidate.instrument} {timeframe} {candidate.direction}; "
                f"B-grade requires trending regime + 15m alignment + ADX>=25 at confidence>=0.50 "
                f"({candidate.grade}, {confidence:.0%}).",
            )

        # 5min is a timing/exit timeframe in live mode. It must be exceptional to become a trade signal.
        if timeframe == "5min":
            min_conf = SignalProcessor._relaxed_threshold(
                float(getattr(settings, "ut_5min_option_min_confidence", 0.70) or 0.70),
                settings,
            )
            trend_15m_agrees = self._candidate_15m_trend_agrees(candidate)
            grade_conf_ok = confidence >= max(SignalProcessor._grade_min_confidence("A"), min_conf)
            if risky_regime and inst_type == "OPT":
                risky_min_conf = max(min_conf, 0.70)
                impulse_confirmed = bool(getattr(candidate, "impulse_confirmed", False))
                if confidence < risky_min_conf or not (trend_15m_agrees or impulse_confirmed):
                    return self._gate_block(
                        candidate,
                        f"Live Gate: blocked {candidate.instrument} {timeframe} option; "
                        f"{regime} requires >= {risky_min_conf:.0%} plus 15min agreement "
                        f"or confirmed impulse ({candidate.grade}, {confidence:.0%}, "
                        f"agree={trend_15m_agrees}, impulse={impulse_confirmed}).",
                    )
            if not (grade_conf_ok or trend_15m_agrees):
                return self._gate_block(
                    candidate,
                    f"Live Gate: blocked {candidate.instrument} {timeframe} {candidate.direction}; "
                    f"needs A/A+ with >= {min_conf:.0%}, or 15min trend agreement "
                    f"({candidate.grade}, {confidence:.0%}, agree={trend_15m_agrees}).",
                )
            if is_choppy and not (grade_conf_ok or trend_15m_agrees):
                return self._gate_block(
                    candidate,
                    f"Live Gate: blocked {candidate.instrument} {timeframe} {candidate.direction}; "
                    f"choppy regime needs A/A+ with >= {min_conf:.0%}, or 15min trend agreement.",
                )

        # Options decay badly in range-bound sessions, so choppy options need A/A+ or very high confidence.
        if is_choppy and inst_type == "OPT" and confidence < min(max(SignalProcessor._grade_min_confidence("A"), SignalProcessor._relaxed_threshold(0.72, settings)), SignalProcessor._relaxed_threshold(SignalProcessor._choppy_confidence_gate(settings), settings)):
            return self._gate_block(
                candidate,
                f"Live Gate: blocked {candidate.instrument} {inst_type} {candidate.direction}; "
                f"range/choppy regime allows only A/A+ option setups or very high confidence.",
            )

        # Never promote weak B-grade live/manual rows in choppy markets unless confidence is exceptional.
        # Baseline parity before leniency: confidence >= 0.72 for A/A+ choppy setups.
        # Baseline parity before leniency: confidence >= 0.72 or exceptional confidence bypasses choppy options.
        if is_choppy and confidence < min(SignalProcessor._grade_min_confidence("A"), SignalProcessor._relaxed_threshold(SignalProcessor._choppy_confidence_gate(settings), settings)):
            return self._gate_block(
                candidate,
                f"Live Gate: blocked {candidate.instrument} {candidate.direction}; "
                f"grade {candidate.grade} is too weak for {regime}.",
            )

        return True

    def _get_live_data_health_label(self, now_ts: Optional[float] = None, is_live: bool = True) -> str:
        """Classify live feed freshness for dashboard health reporting."""
        if not is_live:
            return "HISTORICAL"
        now_ts = float(now_ts if now_ts is not None else time.time())

        last_ltp_time = float(getattr(getattr(self, "data", None), "_last_ltp_time", 0.0) or 0.0)
        if last_ltp_time > 0 and now_ts - last_ltp_time <= 60.0:
            return "OK"

        candles = getattr(self, "candles", None)
        status = {}
        latest = None
        try:
            status = candles.get_status() if candles and hasattr(candles, "get_status") else {}
        except Exception:
            status = {}
        try:
            latest = candles.get_max_timestamp() if candles and hasattr(candles, "get_max_timestamp") else None
        except Exception:
            latest = None

        has_candles = any(
            int(count or 0) > 0
            for tf_counts in (status or {}).values()
            for count in (tf_counts or {}).values()
        )
        if has_candles and latest is not None:
            latest_ts = latest.timestamp() if hasattr(latest, "timestamp") else 0.0
            if latest_ts and now_ts - latest_ts <= 120.0:
                return "OK"

        if not has_candles and last_ltp_time <= 0:
            return "WARMING"
        return "STALE"

    def _get_candidate_ltp_cached(self, candidate: TradeCandidate) -> Optional[float]:
        """Use in-memory candle prices for display rows; broker REST is a throttled fallback."""
        ttl = 10.0
        key = f"{candidate.instrument}:{candidate.symbol_token}"
        now = time.time()
        cached = self._candidate_ltp_cache.get(key)
        if cached and now - cached.get("time", 0.0) <= ttl:
            return cached.get("price")

        prefer_contract_quote = (
            str(getattr(candidate, "inst_type", "") or "").upper() == "FUT"
            and bool(candidate.trading_symbol and candidate.symbol_token)
        )
        exchange = "BFO" if candidate.instrument == "SENSEX" else "NFO"
        if prefer_contract_quote:
            try:
                price = self.data.get_ltp(exchange, candidate.trading_symbol, candidate.symbol_token)
                if price and price > 0:
                    self._candidate_ltp_cache[key] = {"price": float(price), "time": now}
                    return float(price)
            except Exception as e:
                logger.debug(f"Candidate futures price refresh failed for {candidate.trading_symbol}: {e}")

        candle_price = self.candles.get_latest_price(candidate.instrument)
        if candle_price and candle_price > 0:
            return float(candle_price)

        if not (candidate.trading_symbol and candidate.symbol_token):
            return None

        if not prefer_contract_quote:
            try:
                price = self.data.get_ltp(exchange, candidate.trading_symbol, candidate.symbol_token)
                if price and price > 0:
                    self._candidate_ltp_cache[key] = {"price": float(price), "time": now}
                    return float(price)
            except Exception as e:
                logger.debug(f"Candidate futures price refresh failed for {candidate.trading_symbol}: {e}")
        return cached.get("price") if cached else None

    def _refresh_trade_candidates(self, candidates: List[TradeCandidate], cfg: Dict):
        """Refresh live candidate prices so manual-mode signals do not freeze.
        In HISTORICAL mode, skip refreshing - session candidates already have correct prices."""
        if not candidates:
            return
        
        if getattr(self, "mode", "") != "HISTORICAL" and not self._loaded_session_is_current_day():
            return

        # In HISTORICAL mode, don't refresh prices - they're already correct from session files
        if getattr(self, "mode", "") == "HISTORICAL":
            return

        for candidate in candidates:
            if getattr(candidate, "action", "ENTRY") == "EXIT":
                frozen_exit_price = float(getattr(candidate, "exit_price", 0.0) or 0.0)
                if frozen_exit_price > 0:
                    candidate.current_price = frozen_exit_price
                    continue

            current = None
            if candidate.inst_type == "OPT":
                current = self._get_live_premium_cached(candidate)
                if not current or current <= 0:
                    # A refresh failure AFTER acceptance is feed staleness, not an
                    # entry-integrity failure. Overwriting quote_verified/status
                    # here destroyed the entry-time verification evidence on the
                    # 2026-07-03 session (7/8 rows mislabeled QUOTE UNAVAILABLE).
                    setattr(candidate, "live_quote_stale", True)
                    if not bool(getattr(candidate, "accepted_by_gate", False)):
                        # Pre-acceptance rows must carry the marker so the
                        # lifecycle gate can reject them.
                        setattr(candidate, "quote_verified", False)
                        setattr(candidate, "quote_source", "contract_ltp_unavailable")
                        if str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper() == "ENTRY":
                            candidate.status = "QUOTE UNAVAILABLE"
                    continue
                setattr(candidate, "live_quote_stale", False)
            elif candidate.trading_symbol and candidate.symbol_token:
                current = self._get_candidate_ltp_cached(candidate)

            if candidate.inst_type != "OPT" and (not current or current <= 0):
                current = self.candles.get_latest_price(candidate.instrument)

            if not current or current <= 0:
                current = candidate.current_price or candidate.price

            candidate.current_price = float(current)
            candidate.pnl = self._candidate_net_pnl(candidate, candidate.current_price)
            if (
                str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper() == "ENTRY"
                and str(getattr(candidate, "status", "") or "").upper() == "QUOTE UNAVAILABLE"
            ):
                candidate.status = "TRADE SIGNAL"
            if getattr(candidate, "action", "ENTRY") == "EXIT":
                setattr(candidate, "exit_price", float(candidate.current_price or candidate.price or 0.0))

    def _refresh_session_signal_payloads(self, results: Dict) -> None:
        """Rebuild dashboard signal rows after the final trade-ready gate has run."""
        self._prune_session_trade_candidates_for_live_gate()
        instruments = results.get("instruments", {}) if isinstance(results, dict) else {}
        for name, ui_data in instruments.items():
            if not isinstance(ui_data, dict):
                continue
            display_candidates = self._get_session_trade_candidates(name)
            cfg = self.config.get("indices", {}).get(name, {})
            self._refresh_trade_candidates(display_candidates, cfg)
            
            # Check for SL/TP breaches on manual session candidates
            self._check_session_candidates_breaches(name)
            
            # Fetch the final display candidates list (including any newly created exits)
            final_display_candidates = self._get_session_trade_candidates(name)
            self._refresh_trade_candidates(final_display_candidates, cfg)
            
            ui_data["trade_candidates"] = [self._serialize_trade_candidate(c) for c in final_display_candidates]

    def _check_session_candidates_breaches(self, instrument: str) -> None:
        """Serialize session exit evaluation across scan and fallback publishers."""
        with self._session_breach_lock:
            self._check_session_candidates_breaches_locked(instrument)

    def _check_session_candidates_breaches_locked(self, instrument: str) -> None:
        """Apply live trade-management parity to manual/session signal rows."""
        if getattr(self, "mode", "") == "HISTORICAL":
            return

        if not self._loaded_session_is_current_day():
            return

        active_entries = self._active_session_entry_candidates(instrument)
        if not active_entries:
            return

        latest_time = (
            datetime.now(IST).replace(tzinfo=None)
            if getattr(self, "mode", "") != "HISTORICAL"
            else self.candles.get_max_timestamp()
        )
        if latest_time is not None:
            if getattr(latest_time, "tzinfo", None) is not None:
                latest_time = latest_time.astimezone(IST).replace(tzinfo=None)
            else:
                latest_time = latest_time.replace(tzinfo=None)
        else:
            latest_time = datetime.now(IST).replace(tzinfo=None)

        exits_to_create = []
        changed = False

        def create_exit(previous: TradeCandidate, exit_px: float, exit_reason: str, reason_text: str) -> None:
            nonlocal changed
            self._diag_inc("exit_reasons", exit_reason)
            calc_pnl = self._candidate_net_pnl(previous, exit_px)
            # Record WHY. The reason string carries the threat score and the individual
            # votes behind it, and none of it was ever written down — on 2026-08-10 nine
            # LOSS_THREAT_EXITs fired and the log held only the downstream reversion line,
            # so the decision could not be reconstructed from the logs at all.
            logger.info(
                f"[EXIT {exit_reason}] {previous.instrument} {previous.timeframe} "
                f"{previous.direction} @ {exit_px:.2f} net Rs.{calc_pnl:.0f} — {reason_text}"
            )

            exit_candidate = TradeCandidate(
                instrument=previous.instrument,
                direction=previous.direction,
                price=previous.price,
                stop=previous.stop,
                target=previous.target,
                lots=previous.lots,
                lot_size=previous.lot_size,
                grade=previous.grade,
                confidence=previous.confidence,
                timeframe=previous.timeframe,
                inst_type=previous.inst_type,
                option_type=previous.option_type,
                atm_strike=previous.atm_strike,
                multiplier=previous.multiplier,
                trading_symbol=previous.trading_symbol,
                symbol_token=previous.symbol_token,
                rr=previous.rr,
                score=previous.score,
                reasons=list(previous.reasons or []) + [f"{reason_text} at {latest_time:%H:%M:%S}"],
                spot_stop=previous.spot_stop,
                spot_target=previous.spot_target,
                signal_timestamp=previous.signal_timestamp,
                current_price=exit_px,
                pnl=calc_pnl,
                status="EXIT SIGNAL",
                action="EXIT",
                exit_reason=exit_reason,
            )
            setattr(exit_candidate, "exit_timestamp", latest_time)
            setattr(exit_candidate, "exit_price", float(exit_px))
            self._inherit_exit_entry_metadata(exit_candidate, previous)
            setattr(exit_candidate, "peak_pnl", float(getattr(previous, "peak_pnl", 0.0) or 0.0))
            setattr(exit_candidate, "max_drawdown", float(getattr(previous, "max_drawdown", 0.0) or 0.0))
            setattr(exit_candidate, "entry_spot", float(getattr(previous, "entry_spot", 0.0) or 0.0))
            setattr(exit_candidate, "scalp_lock_mode", bool(getattr(previous, "scalp_lock_mode", False)))
            setattr(exit_candidate, "location_risk", str(getattr(previous, "location_risk", "") or ""))
            setattr(exit_candidate, "location_position_pct", float(getattr(previous, "location_position_pct", 0.0) or 0.0))
            exits_to_create.append(exit_candidate)
            changed = True

            self.log_event(
                f"Manual/session exit for {previous.instrument} {previous.direction} ({previous.timeframe}): {reason_text} @ {exit_px:.2f}",
                "warning",
            )
            self._notify(
                f"MANUAL EXIT {previous.direction} {previous.instrument} ({previous.timeframe}): {reason_text} @ {exit_px:.2f}",
                "sell",
            )
            # Virtual/manual mode: candidate exits arm the reversion window too —
            # the size-of-event gate inside still decides if it actually opens.
            self._maybe_arm_reversion_from_exit(
                previous.instrument,
                exited_like=previous,
                reason=exit_reason,
                pnl=float(calc_pnl or 0.0),
                source_tf=str(getattr(previous, "timeframe", "") or ""),
                when=latest_time,
            )

        for previous in active_entries:
            if (
                str(getattr(previous, "inst_type", "") or "").upper() == "OPT"
                and not bool(getattr(previous, "quote_verified", False))
            ):
                marker = f"{latest_time:%H:%M}:option-quote-unverified"
                if getattr(previous, "_last_unverified_option_exit_skip", "") != marker:
                    setattr(previous, "_last_unverified_option_exit_skip", marker)
                    self.log_event(
                        f"Held {previous.instrument} {previous.timeframe}: exact option LTP unavailable; "
                        "session exit checks skipped until contract quote refreshes.",
                        "warning",
                    )
                    self._diag_inc("quote_guard", "option_exit_skipped_unverified")
                continue
            current_price = previous.current_price or previous.price
            if not current_price or current_price <= 0:
                continue

            triggered = False
            exit_px = current_price
            exit_reason = ""
            reason_text = ""

            self._ensure_trade_like_initial_stop(previous)

            settings = get_settings()
            regime = self._get_trade_regime(previous)

            # Intelligence early exit: manual rows get the same directional flip guard,
            # but only as a session exit/alert, never a broker action.
            # Gap6: session/historical path shares loss-guard + 1m emergency richness.
            try:
                session_pnl = float(
                    self._candidate_net_pnl(previous, float(current_price))
                    if hasattr(self, "_candidate_net_pnl")
                    else 0.0
                )
            except Exception:
                session_pnl = 0.0
            try:
                initial_risk_sess = float(
                    self._trade_like_initial_risk_rs(previous)
                    if hasattr(self, "_trade_like_initial_risk_rs")
                    else 0.0
                )
            except Exception:
                initial_risk_sess = abs(
                    float(previous.price or 0.0) - float(getattr(previous, "stop", 0.0) or 0.0)
                ) * max(1, int(getattr(previous, "lots", 1) or 1) * int(getattr(previous, "lot_size", 1) or 1))

            if getattr(settings, "ut_intel_early_exit", False):
                intel_result = self._get_trade_intel(previous)
                if intel_result:
                    reversal_reason = self._intel_reversal_reason(
                        previous.direction,
                        intel_result,
                        is_losing=self._position_is_underwater(previous, session_pnl),
                    )
                    if reversal_reason:
                        fresh, stale_text = self._intel_reversal_is_new_evidence(
                            previous, previous.direction, intel_result
                        )
                        if not fresh:
                            marker = f"{latest_time:%H:%M}:noflip"
                            if getattr(previous, "_last_stale_intel_exit", "") != marker:
                                setattr(previous, "_last_stale_intel_exit", marker)
                                self.log_event(
                                    f"Held {previous.instrument} {previous.timeframe} through OI/PCR flip; "
                                    f"not a reversal ({stale_text}).",
                                    "info",
                                )
                            reversal_reason = None
                    if reversal_reason and self._intel_exit_blocked_by_trend(previous, regime):
                        marker = f"{latest_time:%H:%M}:trendskip"
                        if getattr(previous, "_last_trend_skip_intel_exit", "") != marker:
                            setattr(previous, "_last_trend_skip_intel_exit", marker)
                            self.log_event(
                                f"Held {previous.instrument} {previous.timeframe} through contrarian OI/PCR flip; "
                                f"regime {regime} aligned with {previous.direction}.",
                                "info",
                            )
                        reversal_reason = None
                    if reversal_reason:
                        defer_exit, defer_text = self._should_defer_option_intel_exit(
                            previous,
                            float(current_price),
                            latest_time,
                            reversal_reason,
                            regime=regime,
                        )
                        if defer_exit:
                            marker = f"{latest_time:%H:%M}:{reversal_reason}"
                            if getattr(previous, "_last_deferred_intel_exit", "") != marker:
                                setattr(previous, "_last_deferred_intel_exit", marker)
                                self.log_event(
                                    f"Deferred intelligence exit for {previous.instrument} {previous.timeframe}: {reversal_reason}; {defer_text}.",
                                    "info",
                                )
                        else:
                            create_exit(previous, float(current_price), "OI_PCR_REVERSAL", reversal_reason)
                            continue
                    score = (intel_result.get("aggregate", {}) or {}).get("score", 0.0)
                    if previous.direction == "LONG" and float(score or 0.0) < -40.0:
                        reason = f"Intelligence flip score {score:.1f}"
                        defer_exit, defer_text = self._should_defer_option_intel_exit(
                            previous,
                            float(current_price),
                            latest_time,
                            reason,
                            regime=regime,
                        )
                        if defer_exit:
                            marker = f"{latest_time:%H:%M}:{reason}"
                            if getattr(previous, "_last_deferred_intel_exit", "") != marker:
                                setattr(previous, "_last_deferred_intel_exit", marker)
                                self.log_event(
                                    f"Deferred intelligence exit for {previous.instrument} {previous.timeframe}: {reason}; {defer_text}.",
                                    "info",
                                )
                        else:
                            create_exit(previous, float(current_price), "INTEL_FLIP", reason)
                            continue
                    if previous.direction == "SHORT" and float(score or 0.0) > 40.0:
                        reason = f"Intelligence flip score {score:.1f}"
                        defer_exit, defer_text = self._should_defer_option_intel_exit(
                            previous,
                            float(current_price),
                            latest_time,
                            reason,
                            regime=regime,
                        )
                        if defer_exit:
                            marker = f"{latest_time:%H:%M}:{reason}"
                            if getattr(previous, "_last_deferred_intel_exit", "") != marker:
                                setattr(previous, "_last_deferred_intel_exit", marker)
                                self.log_event(
                                    f"Deferred intelligence exit for {previous.instrument} {previous.timeframe}: {reason}; {defer_text}.",
                                    "info",
                                )
                        else:
                            create_exit(previous, float(current_price), "INTEL_FLIP", reason)
                            continue

            # Smart trailing parity for manual/session rows.
            new_stop = float(previous.stop or 0.0)
            price_direction = self._candidate_price_direction(previous)
            
            def map_spot_to_inst(spot_val: float) -> float:
                return self._candidate_price_from_spot_level(previous, spot_val)

            if getattr(settings, "ut_smart_trailing", False):
                key_tf = f"{previous.instrument}_{previous.timeframe}"
            else:
                key_tf = f"{previous.instrument}_1min"
            engine_tf = getattr(getattr(self, "mtf", None), "engines", {}).get(key_tf)
            if engine_tf:
                try:
                    state_tf = engine_tf.get_state(key_tf)
                    raw_ts = float(getattr(state_tf, "trailing_stop", 0.0) or 0.0)
                    if is_trending_regime(regime) and raw_ts > 0:
                        mapped_ts = map_spot_to_inst(raw_ts)
                        if (
                            self._candidate_trailing_stop_is_valid(previous, mapped_ts, current_price)
                            and price_direction == "LONG"
                        ):
                            new_stop = max(new_stop, mapped_ts)
                        elif self._candidate_trailing_stop_is_valid(previous, mapped_ts, current_price):
                            new_stop = min(new_stop, mapped_ts)
                except Exception:
                    pass

            if uses_tight_trailing(regime):
                try:
                    df_1m = self.candles.get_candles(previous.instrument, "1min")
                    if df_1m is not None and len(df_1m) > 2:
                        spot_barrier = (
                            float(df_1m["low"].iloc[-2])
                            if previous.direction == "LONG"
                            else float(df_1m["high"].iloc[-2])
                        )
                        mapped_ts = map_spot_to_inst(spot_barrier)
                        if self._candidate_trailing_stop_is_valid(previous, mapped_ts, current_price):
                            if price_direction == "LONG":
                                new_stop = max(new_stop, mapped_ts)
                            else:
                                new_stop = min(new_stop, mapped_ts)
                except Exception:
                    pass

            initial_stop = self._ensure_trade_like_initial_stop(previous)
            risk_dist = abs(float(previous.price) - initial_stop)
            current_profit_pts = (
                float(current_price) - float(previous.price)
                if price_direction == "LONG"
                else float(previous.price) - float(current_price)
            )
            cascade_ctx = self._trade_one_way_cascade_context(previous, latest_time)
            cascade_runner = bool(cascade_ctx and current_profit_pts > 0)
            if cascade_runner:
                setattr(previous, "one_way_cascade_entry", True)
                setattr(previous, "one_way_cascade_context", dict(cascade_ctx or {}))
                setattr(previous, "scalp_lock_mode", False)
                if not bool(getattr(previous, "runner_mode", False)):
                    setattr(previous, "runner_mode", True)
                    previous.target = 0.0
                    changed = True
                    marker = f"{latest_time:%H:%M}:{previous.instrument}:{previous.timeframe}"
                    if getattr(previous, "_last_one_way_runner_log", "") != marker:
                        setattr(previous, "_last_one_way_runner_log", marker)
                        self.log_event(
                            f"One-way cascade runner enabled for {previous.instrument} {previous.timeframe}: "
                            f"{cascade_ctx.get('reason', 'broad directional cascade')}.",
                            "trade",
                        )
            if risk_dist > 0 and current_profit_pts > risk_dist:
                buffer = float(previous.price) * 0.0005
                if price_direction == "LONG":
                    new_stop = max(new_stop, float(previous.price) + buffer)
                else:
                    new_stop = min(new_stop, float(previous.price) - buffer)

            if previous.target > 0 or getattr(previous, "runner_mode", False):
                rr_settings = get_settings()
                runner_unlock_ratio = min(1.0, max(0.50, float(getattr(rr_settings, "dynamic_rr_runner_unlock_ratio", 0.95) or 0.95)))
                runner_lock_pct = self._dynamic_runner_lock_pct(
                    float(getattr(rr_settings, "dynamic_rr_runner_lock_pct", 0.90) or 0.90),
                    regime,
                )
                if cascade_runner and isinstance(cascade_ctx, dict):
                    runner_lock_pct = min(
                        0.98,
                        max(0.50, float(cascade_ctx.get("runner_lock_pct", runner_lock_pct) or runner_lock_pct)),
                    )
                is_runner = bool(getattr(previous, "runner_mode", False))
                if not is_runner and previous.target > 0:
                    target_distance = abs(float(previous.target) - float(previous.price))
                    current_move = abs(float(current_price) - float(previous.price))
                    is_correct_direction = (
                        (price_direction == "LONG" and current_price > previous.price)
                        or (price_direction == "SHORT" and current_price < previous.price)
                    )
                    reached_t1 = (
                        is_correct_direction
                        and target_distance > 0
                        and current_move >= target_distance * runner_unlock_ratio
                    )
                    # Big-move ride: engage the runner EARLY (before the fixed target) for
                    # a proven winner in a strong trend, so a big directional move is not
                    # cut by the fixed target. Small gains never qualify (see _big_move_expected).
                    big_move_ok = False
                    big_reason = ""
                    if (
                        is_correct_direction
                        and not reached_t1
                        and self._setting_enabled(
                            getattr(settings, "trend_runner_engage_before_target_enabled", True), True
                        )
                    ):
                        big_move_ok, big_reason = self._big_move_expected(
                            previous,
                            gain_r=self._trade_gain_in_r(previous, current_move),
                            regime=regime,
                        )
                    if reached_t1 or big_move_ok:
                        setattr(previous, "runner_mode", True)
                        previous.target = 0.0
                        changed = True
                        self.log_event(
                            f"Runner lock enabled for manual/session {previous.instrument}: "
                            + ("Target 1 reached" if reached_t1 else big_reason),
                            "trade",
                        )

                if getattr(previous, "runner_mode", False):
                    # SIGNED, not abs(). price_direction is always "LONG" for an option
                    # (options are bought, so profit is a premium RISE), and abs() turned
                    # an adverse move into a "gain": premium 165.05 -> 158 gave
                    # |158-165.05| = 7.05 of "gain", locked a stop ABOVE entry, and the
                    # exit was then booked at that stop and recorded as a profit lock on
                    # a trade that was down. A retracement must lock nothing.
                    current_gain_pts = max(
                        0.0,
                        (float(current_price) - float(previous.price))
                        if price_direction == "LONG"
                        else (float(previous.price) - float(current_price)),
                    )
                    locked_gain_pts = current_gain_pts * runner_lock_pct
                    new_runner_stop = (
                        float(previous.price) + locked_gain_pts
                        if price_direction == "LONG"
                        else float(previous.price) - locked_gain_pts
                    )
                    if price_direction == "LONG":
                        new_stop = max(new_stop, new_runner_stop)
                    else:
                        new_stop = min(new_stop, new_runner_stop)

            if new_stop > 0:
                adjusted_stop, breathing, clamped = self._apply_option_stop_breathing_room(
                    previous,
                    new_stop,
                    latest_time=latest_time,
                    regime=regime,
                )
                if clamped:
                    marker = f"{latest_time:%H:%M}:{adjusted_stop:.2f}"
                    if getattr(previous, "_last_breathing_stop_log", "") != marker:
                        setattr(previous, "_last_breathing_stop_log", marker)
                        self.log_event(
                            f"Option breathing room kept {previous.instrument} {previous.timeframe} stop at {adjusted_stop:.2f} "
                            f"(floor {breathing:.2f}) instead of {new_stop:.2f}.",
                            "info",
                        )
                    new_stop = adjusted_stop

            if new_stop > 0 and abs(new_stop - float(previous.stop or 0.0)) > 1e-9:
                previous.stop = float(new_stop)
                changed = True

            current_pnl_rs = self._candidate_gross_pnl(previous, float(current_price))
            previous.pnl = self._candidate_net_pnl(previous, float(current_price))
            candle_extreme_price = self._candidate_candle_extreme_price(previous, latest_time)
            candle_extreme_pnl = (
                self._candidate_gross_pnl(previous, candle_extreme_price)
                if candle_extreme_price > 0
                else 0.0
            )
            previous_peak = max(float(getattr(previous, "peak_pnl", 0.0) or 0.0), current_pnl_rs, candle_extreme_pnl)
            if abs(previous_peak - float(getattr(previous, "peak_pnl", 0.0) or 0.0)) > 1e-9:
                setattr(previous, "peak_pnl", previous_peak)
                changed = True
            # Ordered samples behind peak_pnl/max_drawdown. Those are maxima and cannot
            # say whether the trough came before or after the peak, which is exactly what
            # decides whether a tighter trail would have kept more. Sampled on the
            # CANDIDATE because that is the object rtracker records. Gross, matching
            # peak_pnl above rather than the net previous.pnl, so the path and the peak
            # it explains are on one basis.
            sample_pnl_path(
                previous,
                pnl=current_pnl_rs,
                entry_time=getattr(previous, "entry_timestamp", None),
            )
            self._ensure_trade_like_initial_stop(previous)
            qty = int(previous.lots or 1) * int(previous.lot_size or 1)
            c_mult = getattr(previous, "multiplier", 1.0) if getattr(previous, "inst_type", "FUT") != "OPT" else 1.0
            initial_risk_prev = self._trade_like_initial_risk_rs(previous, qty=qty, inst_mult=c_mult)

            def handle_recovery_watch(proposed_reason: str) -> bool:
                nonlocal changed
                action, recovery_ctx = self._loss_recovery_watch_decision(
                    previous,
                    current_price=float(current_price),
                    current_pnl_rs=current_pnl_rs,
                    peak_pnl=previous_peak,
                    initial_risk_rs=initial_risk_prev,
                    latest_time=latest_time,
                    regime=regime,
                    proposed_exit_reason=proposed_reason,
                )
                if action == "HOLD":
                    marker = f"{latest_time:%H:%M}:{current_pnl_rs:.0f}:{proposed_reason}"
                    if getattr(previous, "_last_loss_recovery_hold_log", "") != marker:
                        setattr(previous, "_last_loss_recovery_hold_log", marker)
                        self.log_event(
                            f"Recovery watch holding {previous.instrument} {previous.timeframe}: {recovery_ctx}.",
                            "info",
                        )
                    changed = True
                    return True
                if action == "EXIT":
                    create_exit(previous, float(current_price), "RECOVERY_WATCH_EXIT", recovery_ctx)
                    return True
                return False

            # Gap6: same loss-guard (0.8→0.55→0.35R + wick/grind/intel) on session rows.
            try:
                should_cut, cut_detail, cut_r = self._loss_guard_decision(
                    previous,
                    current_pnl_rs=current_pnl_rs,
                    initial_risk_rs=initial_risk_prev,
                    latest_time=latest_time,
                    regime=regime,
                    current_price=float(current_price),
                )
                if should_cut and current_pnl_rs < 0.0:
                    if handle_recovery_watch("EARLY_LOSS_CUT"):
                        continue
                    create_exit(
                        previous,
                        float(current_price),
                        "EARLY_LOSS_CUT",
                        f"{cut_detail} thr={cut_r:.2f}R",
                    )
                    continue
            except Exception as exc:
                logger.debug(f"Session loss-guard skipped for {previous.instrument}: {exc}")

            # Rupee loss ladder: OPT from -1000, FUT from -1500 (product arms).
            try:
                band_exit, band_reason, band_ctx = self._rupee_loss_band_guard_decision(
                    previous,
                    current_pnl_rs=current_pnl_rs,
                    latest_time=latest_time,
                    regime=regime,
                    current_price=float(current_price),
                )
                if band_exit and current_pnl_rs < 0.0:
                    if handle_recovery_watch(band_reason):
                        continue
                    create_exit(previous, float(current_price), band_reason, band_ctx)
                    continue
            except Exception as exc:
                logger.debug(f"Session rupee loss-band skipped for {previous.instrument}: {exc}")

            threat_exit, threat_reason, threat_ctx = self._peak_threat_exit_decision(
                previous,
                current_price=float(current_price),
                current_pnl_rs=current_pnl_rs,
                peak_pnl=previous_peak,
                initial_risk_rs=initial_risk_prev,
                latest_time=latest_time,
                regime=regime,
                inst_type=getattr(previous, "inst_type", ""),
                option_type=getattr(previous, "option_type", ""),
                direction=getattr(previous, "direction", ""),
            )
            if threat_exit:
                create_exit(previous, float(current_price), threat_reason, threat_ctx)
                continue

            lock_stop, lock_reason, lock_ratio = self._profit_lock_floor(
                float(previous.price or 0.0),
                price_direction,
                qty,
                previous_peak,
                bool(getattr(previous, "scalp_lock_mode", False)),
                inst_mult=c_mult,
                initial_risk_rs=initial_risk_prev,
                timeframe=getattr(previous, "timeframe", ""),
                now=latest_time,
                trade_like=previous,
            )
            if lock_stop > 0 and self._candidate_net_pnl(previous, lock_stop) <= 0:
                lock_stop = 0.0
                lock_reason = ""
            if lock_reason and cascade_runner and current_pnl_rs > 0.0:
                lock_stop = 0.0
                lock_reason = ""
                marker = f"{latest_time:%H:%M}:{previous_peak:.0f}:{current_pnl_rs:.0f}"
                if getattr(previous, "_last_one_way_profit_lock_defer_log", "") != marker:
                    setattr(previous, "_last_one_way_profit_lock_defer_log", marker)
                    self.log_event(
                        f"Deferred profit lock for {previous.instrument} {previous.timeframe}: "
                        f"{cascade_ctx.get('reason', 'one-way cascade still aligned')}.",
                        "info",
                    )
            if (
                lock_reason == "MAJOR_WIN_GUARD"
                and str(getattr(previous, "inst_type", "FUT") or "FUT").upper() == "FUT"
            ):
                should_exit_major, guard_context = self._should_exit_major_win_guard(
                    previous,
                    float(current_price),
                    previous_peak,
                    current_pnl_rs,
                    latest_time,
                )
                if not should_exit_major:
                    lock_stop = 0.0
                    lock_reason = ""
                    marker = f"{latest_time:%H:%M}:{previous_peak:.0f}:{current_pnl_rs:.0f}"
                    if getattr(previous, "_last_major_win_defer_log", "") != marker:
                        setattr(previous, "_last_major_win_defer_log", marker)
                        self.log_event(
                            f"Deferred major-win lock for {previous.instrument} {previous.timeframe}: {guard_context}.",
                            "info",
                        )
            if lock_stop > 0:
                old_stop = float(previous.stop or 0.0)
                if price_direction == "LONG":
                    new_stop = max(float(previous.stop or 0.0), lock_stop)
                else:
                    new_stop = min(float(previous.stop or lock_stop), lock_stop)
                new_stop, breathing, clamped = self._apply_option_stop_breathing_room(
                    previous,
                    new_stop,
                    latest_time=latest_time,
                    regime=regime,
                    profit_lock_reason=lock_reason,
                )
                if clamped:
                    marker = f"{latest_time:%H:%M}:{new_stop:.2f}"
                    if getattr(previous, "_last_breathing_stop_log", "") != marker:
                        setattr(previous, "_last_breathing_stop_log", marker)
                        self.log_event(
                            f"Option breathing room delayed profit-lock stop for {previous.instrument} {previous.timeframe}; "
                            f"floor {breathing:.2f}.",
                            "info",
                        )
                if self._candidate_net_pnl(previous, new_stop) <= 0:
                    lock_stop = 0.0
                    lock_reason = ""
                    new_stop = old_stop
                if abs(new_stop - old_stop) > 1e-9:
                    previous.stop = float(new_stop)
                    changed = True
            previous_dd = max(
                float(getattr(previous, "max_drawdown", 0.0) or 0.0),
                previous_peak - current_pnl_rs,
            )
            if abs(previous_dd - float(getattr(previous, "max_drawdown", 0.0) or 0.0)) > 1e-9:
                setattr(previous, "max_drawdown", previous_dd)
                changed = True

            entry_value = abs(float(previous.price or 0.0)) * int(previous.lots or 1) * int(previous.lot_size or 1)
            peak_gain_pct = (previous_peak / entry_value) * 100.0 if entry_value > 0 else 0.0
            current_gain_pct = (current_pnl_rs / entry_value) * 100.0 if entry_value > 0 else 0.0

            if lock_reason and self._candidate_stop_hit(previous, current_price):
                if lock_reason in {"SMART_PROFIT_LOCK", "MAJOR_WIN_GUARD"}:
                    defer_lock, defer_reason = self._should_defer_trend_option_profit_lock(
                        previous,
                        float(current_price),
                        float(previous.stop or current_price),
                        current_pnl_rs,
                        previous_peak,
                        latest_time,
                        regime=regime,
                    )
                    if defer_lock:
                        marker = f"{latest_time:%H:%M}:{previous_peak:.0f}:{current_pnl_rs:.0f}"
                        if getattr(previous, "_last_trend_profit_lock_defer_log", "") != marker:
                            setattr(previous, "_last_trend_profit_lock_defer_log", marker)
                            self.log_event(
                                f"Deferred {lock_reason} for {previous.instrument} {previous.timeframe}: {defer_reason}.",
                                "info",
                            )
                        lock_reason = ""
                    else:
                        setattr(previous, "_last_trend_profit_lock_defer_reason", defer_reason)

                if lock_reason:
                    if current_pnl_rs < 0.0 and handle_recovery_watch(lock_reason):
                        continue
                    locked_pnl = self._candidate_gross_pnl(previous, float(previous.stop or current_price))
                    create_exit(
                        previous,
                        float(previous.stop or current_price),
                        lock_reason,
                        f"Profit lock stop hit ({lock_ratio:.0%} of peak Rs.{previous_peak:.0f}, locked Rs.{locked_pnl:.0f})",
                    )
                    continue

            if peak_gain_pct >= 10.0 and (current_gain_pct < peak_gain_pct * 0.40 or current_gain_pct < 2.0):
                create_exit(previous, float(current_price), "LOW_GAIN_PROTECT", f"Low-gain protection peak {peak_gain_pct:.1f}%, current {current_gain_pct:.1f}%")
                continue

            ladder_peak = Scanner._profit_ladder_pnl(self, previous, previous_peak, qty)
            if ladder_peak >= 3000.0 and current_pnl_rs < previous_peak * 0.75:
                should_exit, guard_context = (
                    self._should_exit_major_win_guard(
                        previous,
                        float(current_price),
                        previous_peak,
                        current_pnl_rs,
                        latest_time,
                    )
                    if str(getattr(previous, "inst_type", "FUT") or "FUT").upper() == "FUT"
                    else (True, "option major-win guard")
                )
                if should_exit:
                    exit_floor = float(lock_stop or current_price)
                    create_exit(
                        previous,
                        exit_floor,
                        "MAJOR_WIN_GUARD",
                        f"Major win guard peak Rs.{previous_peak:.0f}, current Rs.{current_pnl_rs:.0f}; {guard_context}",
                    )
                    continue
                marker = f"{latest_time:%H:%M}:{previous_peak:.0f}:{current_pnl_rs:.0f}"
                if getattr(previous, "_last_major_win_defer_log", "") != marker:
                    setattr(previous, "_last_major_win_defer_log", marker)
                    self.log_event(
                        f"Deferred major-win exit for {previous.instrument} {previous.timeframe}: {guard_context}.",
                        "info",
                    )

            scalp_mode = bool(getattr(previous, "scalp_lock_mode", False))
            smart_min_peak = self._profit_lock_min_peak(
                scalp_mode,
                initial_risk_prev,
                getattr(previous, "timeframe", ""),
                latest_time,
                trade_like=previous,
            )
            smart_ratio = self._smart_lock_backstop_ratio(lock_ratio, scalp_mode)
            abs_floor_rs = float(getattr(get_settings(), "profit_lock_abs_floor_rs", 450.0) or 450.0)
            floor_collapse = self._smart_lock_floor_collapse(
                previous_peak, current_pnl_rs, smart_ratio
            )
            if smart_min_peak <= previous_peak and ladder_peak < 3000.0 and (current_pnl_rs < previous_peak * smart_ratio or floor_collapse):
                exit_floor = float(lock_stop or 0.0)
                if exit_floor > 0 and self._candidate_net_pnl(previous, exit_floor) > 0:
                    create_exit(previous, exit_floor, "SMART_PROFIT_LOCK", f"Smart profit lock peak Rs.{previous_peak:.0f}, current Rs.{current_pnl_rs:.0f}")
                    continue
                if floor_collapse:
                    if current_pnl_rs < 0.0 and handle_recovery_watch("SMART_PROFIT_LOCK"):
                        continue
                    create_exit(
                        previous,
                        float(current_price),
                        "PROFIT_GIVEBACK_GUARD",
                        (
                            f"Smart lock floor unavailable after peak Rs.{previous_peak:.0f}; "
                            f"current Rs.{current_pnl_rs:.0f} <= keep-floor Rs.{abs_floor_rs:.0f}"
                        ),
                    )
                    continue

            # Fix 1/3: sub-1R give-back guard + live regime-reversal profit-taker.
            # Below the full lock arm, protect a fading winner from round-tripping
            # into a loss, and take profit when the live regime flips against us.
            gb_exit, gb_reason, gb_ctx = self._peak_giveback_or_reversal_exit(
                previous,
                current_pnl_rs=current_pnl_rs,
                peak_pnl=previous_peak,
                initial_risk_rs=initial_risk_prev,
                smart_min_peak=smart_min_peak,
                latest_time=latest_time,
                regime=regime,
                inst_type=getattr(previous, "inst_type", ""),
                option_type=getattr(previous, "option_type", ""),
                direction=getattr(previous, "direction", ""),
            )
            if gb_exit:
                if current_pnl_rs < 0.0 and handle_recovery_watch(gb_reason):
                    continue
                create_exit(previous, float(current_price), gb_reason, gb_ctx)
                continue

            eod_loss_exit, eod_loss_ctx = self._eod_loss_minimize_exit(
                previous,
                current_pnl_rs=current_pnl_rs,
                initial_risk_rs=initial_risk_prev,
                latest_time=latest_time,
                regime=regime,
            )
            if eod_loss_exit:
                create_exit(previous, float(current_price), "EOD_LOSS_MINIMIZE", eod_loss_ctx)
                continue

            should_stagnate, stagnation_context = self._stagnation_exit_decision(
                previous,
                current_pnl_rs,
                previous_peak,
                latest_time,
                regime=regime,
            )
            if should_stagnate:
                create_exit(previous, float(current_price), "STAGNATION_EXIT", stagnation_context)
                continue

            # ── REPAINT GUARD EXIT ──────────────────────────────────────
            # If the source candle has fully closed, verify the UT Bot
            # signal that originally triggered this trade is still present.
            # For 15min trades, we also check periodically (every 2 mins)
            # while the candle is still forming to abort earlier.
            sig_ts = getattr(previous, "signal_timestamp", None)
            repaint_checked = bool(getattr(previous, "repaint_guard_checked", False))
            if not bool(getattr(previous, "entered_intracandle", True)):
                setattr(previous, "repaint_guard_checked", True)
                repaint_checked = True
                changed = True
            if sig_ts and not repaint_checked:
                is_candle_closed = self._live_signal_candle_has_closed(previous, sig_ts, latest_time)
                
                # Intra-candle and Edge-case handling for 15min and 5min timeframes
                if previous.timeframe in ("15min", "5min"):
                    check_ts = sig_ts
                    if getattr(check_ts, "tzinfo", None) is not None:
                        check_ts = check_ts.astimezone(IST).replace(tzinfo=None)
                        
                    tf_mins = 15 if previous.timeframe == "15min" else 5
                    candle_end = check_ts + timedelta(minutes=tf_mins)
                    
                    # 1. Edge Case: Signal generated in last 1 min of candle
                    is_last_minute = getattr(previous, "_is_last_minute_entry", None)
                    if is_last_minute is None:
                        # If the time we first start monitoring it is >= candle_end - 1min
                        # FIX H2: use check_ts instead of latest_time
                        is_last_minute = check_ts >= (candle_end - timedelta(minutes=1))
                        setattr(previous, "_is_last_minute_entry", is_last_minute)
                        
                    if is_last_minute:
                        # Extend the "closed" definition by 1 minute into the next candle
                        is_candle_closed = latest_time >= (candle_end + timedelta(minutes=1))
                        
                    # 2. Periodic intra-candle re-checks (every repaint_check_interval_seconds,
                    #    default 30s) until the candle closes — applies to both 5min and 15min.
                    if not is_candle_closed:
                        interval_seconds = max(
                            5.0,
                            float(getattr(get_settings(), "repaint_check_interval_seconds", 30.0) or 30.0),
                        )
                        interval = timedelta(seconds=interval_seconds)
                        next_check = getattr(previous, "_next_repaint_check", None)
                        if next_check is None:
                            # Start clock from the first time we monitor it (post-buffer)
                            next_check = latest_time + interval
                            setattr(previous, "_next_repaint_check", next_check)

                        if latest_time >= next_check:
                            still_present = not self._repaint_absence_is_definite(previous, sig_ts)
                            self._diag_inc("repaint_guard", "checked")
                            if still_present:
                                setattr(previous, "_repaint_absent_checks", 0)
                                setattr(previous, "_repaint_first_absent_at", None)
                            else:
                                absent_checks = int(getattr(previous, "_repaint_absent_checks", 0) or 0) + 1
                                setattr(previous, "_repaint_absent_checks", absent_checks)
                                if getattr(previous, "_repaint_first_absent_at", None) is None:
                                    setattr(previous, "_repaint_first_absent_at", latest_time)
                                override_ctx = self._post_entry_repaint_override_context(previous, sig_ts)
                                if override_ctx:
                                    setattr(previous, "_repaint_absent_checks", 0)
                                    setattr(previous, "_repaint_first_absent_at", None)
                                    still_present = True
                                    reason = override_ctx.get("reason", override_ctx.get("type", "confirmed momentum"))
                                    marker = f"{latest_time:%H:%M}:{reason}"
                                    if getattr(previous, "_last_repaint_override_hold_log", "") != marker:
                                        setattr(previous, "_last_repaint_override_hold_log", marker)
                                        self.log_event(
                                            f"Repaint guard held {previous.instrument} {previous.timeframe}: "
                                            f"stabilization override still confirms {reason}.",
                                            "info",
                                        )
                                    self._diag_inc("repaint_guard", "momentum_override_held")
                            defer_repaint_abort = False
                            defer_repaint_text = ""
                            if not still_present and not self._repaint_abort_held_for_profit(previous, current_price):
                                defer_repaint_abort, defer_repaint_text = self._should_defer_option_repaint_abort(
                                    previous,
                                    float(current_price),
                                    latest_time,
                                    is_candle_closed,
                                    regime=regime,
                                )
                            if (
                                not still_present
                                and not defer_repaint_abort
                                and not self._repaint_abort_held_for_profit(previous, current_price)
                            ):
                                exit_reason, reason_prefix = self._repaint_abort_exit_reason(previous)
                                self._diag_inc("repaint_guard", "aborted")
                                logger.warning(
                                    f"🚨 [INTRA-CANDLE {exit_reason}] Signal for {previous.instrument} {previous.direction} "
                                    f"({previous.timeframe}) at {sig_ts} failed during {interval_seconds:.0f}s check. Force-exiting."
                                )
                                self._mark_post_repaint_recheck(
                                    previous,
                                    sig_ts,
                                    latest_time,
                                    source="intra_candle_repaint_abort",
                                )
                                create_exit(previous, float(current_price), exit_reason,
                                            f"{reason_prefix} ({interval_seconds:.0f}s check)")
                                continue
                            if defer_repaint_abort:
                                marker = f"{latest_time:%H:%M}:{defer_repaint_text}"
                                if getattr(previous, "_last_repaint_defer_log", "") != marker:
                                    setattr(previous, "_last_repaint_defer_log", marker)
                                    self.log_event(
                                        f"Repaint flicker deferred for {previous.instrument} "
                                        f"{previous.timeframe}: {defer_repaint_text}.",
                                        "info",
                                    )
                                self._diag_inc("repaint_guard", "deferred_option")
                            if not still_present and not defer_repaint_abort:
                                marker = f"{latest_time:%H:%M}"
                                if getattr(previous, "_last_repaint_hold_log", "") != marker:
                                    setattr(previous, "_last_repaint_hold_log", marker)
                                    self.log_event(
                                        f"Repaint flicker ignored (intra-candle) for {previous.instrument} "
                                        f"{previous.timeframe}: position in profit, holding the working entry.",
                                        "info",
                                    )
                                self._diag_inc("repaint_guard", "held_profit")
                            else:
                                self._diag_inc("repaint_guard", "passed")
                            setattr(previous, "_next_repaint_check", next_check + interval)
                            changed = True

                # Final close check — repaint is an INTRABAR concept. We only make
                # the repaint determination at the close moment (within a short grace
                # so a live scan can run). If the guard is first evaluated well after
                # close, the candle has long confirmed: the signal is no longer
                # intrabar and the trade is a NORMAL tracked/trailed position — never
                # repaint-aborted afterwards.
                if is_candle_closed:
                    setattr(previous, "repaint_guard_checked", True)
                    setattr(previous, "_next_repaint_check", None)  # FIX H1
                    changed = True  # persist the flag so we don't re-check
                    if not self._repaint_close_check_in_window(sig_ts, previous.timeframe, latest_time):
                        self.log_event(
                            f"Repaint guard: {previous.instrument} {previous.timeframe} signal at {sig_ts} "
                            f"confirmed (candle closed before guard could evaluate); now a normal tracked trade.",
                            "info",
                        )
                        self._diag_inc("repaint_guard", "passed")
                    else:
                        still_present = not self._repaint_absence_is_definite(previous, sig_ts)
                        self._diag_inc("repaint_guard", "checked")
                        if not still_present:
                            override_ctx = self._post_entry_repaint_override_context(previous, sig_ts)
                            if override_ctx:
                                still_present = True
                                reason = override_ctx.get("reason", override_ctx.get("type", "confirmed momentum"))
                                self.log_event(
                                    f"Repaint guard confirmed {previous.instrument} {previous.timeframe} at close: "
                                    f"stabilization override still confirms {reason}; now a normal tracked trade.",
                                    "info",
                                )
                                self._diag_inc("repaint_guard", "momentum_override_held")
                        if not still_present and not self._repaint_abort_held_for_profit(previous, current_price):
                            exit_reason, reason_prefix = self._repaint_abort_exit_reason(previous)
                            self._diag_inc("repaint_guard", "aborted")
                            logger.warning(
                                f"🚨 [{exit_reason}] Signal for {previous.instrument} {previous.direction} "
                                f"({previous.timeframe}) at {sig_ts} failed at candle close. Force-exiting."
                            )
                            self._mark_post_repaint_recheck(
                                previous,
                                sig_ts,
                                latest_time,
                                source="close_repaint_abort",
                            )
                            create_exit(previous, float(current_price), exit_reason,
                                        f"{reason_prefix} at candle close")
                            continue
                        if not still_present:
                            marker = f"{latest_time:%H:%M}:close"
                            if getattr(previous, "_last_repaint_hold_log", "") != marker:
                                setattr(previous, "_last_repaint_hold_log", marker)
                                self.log_event(
                                    f"Repaint flicker ignored (candle close) for {previous.instrument} "
                                    f"{previous.timeframe}: position in profit, now a normal tracked trade.",
                                    "info",
                                )
                            self._diag_inc("repaint_guard", "held_profit")
                        else:
                            self._diag_inc("repaint_guard", "passed")
            # ── END REPAINT GUARD ──────────────────────────────────────

            if self._candidate_stop_hit(previous, current_price):
                if handle_recovery_watch("STOP_HIT"):
                    continue
                triggered = True
                exit_px = current_price
                exit_reason = "STOP_HIT"
                reason_text = "Stoploss hit"
            elif self._candidate_target_hit(previous, current_price):
                triggered = True
                exit_px = current_price
                exit_reason = "TARGET_HIT"
                reason_text = "Target hit"

            if triggered:
                create_exit(previous, float(exit_px), exit_reason, reason_text)

        if exits_to_create:
            self._remember_trade_candidates(exits_to_create)
            for exit_candidate in exits_to_create:
                self._latest_exit_candidates[exit_candidate.instrument] = [exit_candidate]
            changed = True
            
        if changed:
            self._persist_session_trade_candidates()

    def _prune_session_trade_candidates_for_live_gate(self) -> None:
        """Remove pre-gate/weak rows left in today's manual ledger from older builds."""
        if getattr(self, "mode", "") == "HISTORICAL":
            return

        if not self._loaded_session_is_current_day():
            return

        store = getattr(self, "_session_trade_candidates", {}) or {}
        changed = False
        for instrument, book in list(store.items()):
            removed_entries = set()
            repaired_entries = set()
            for key, candidate in list(book.items()):
                if not self._candidate_matches_live_session_day(candidate):
                    book.pop(key, None)
                    changed = True
                    continue
                if self._looks_like_synthetic_option_entry(candidate):
                    entry_ts = getattr(candidate, "signal_timestamp", None)
                    entry_key = (
                        candidate.instrument,
                        candidate.timeframe,
                        candidate.direction,
                        candidate.trading_symbol or "",
                        entry_ts.isoformat(timespec="seconds") if entry_ts else "",
                    )
                    if str(getattr(candidate, "action", "ENTRY") or "ENTRY").upper() == "EXIT":
                        continue
                    verified_premium = self._get_live_premium_cached(candidate)
                    if verified_premium and self._rebase_option_candidate_to_verified_quote(
                        candidate,
                        verified_premium,
                    ):
                        repaired_entries.add(entry_key)
                        changed = True
                        self.log_signal_decision_once(
                            (
                                f"{candidate.instrument}|{candidate.timeframe}|"
                                f"{candidate.trading_symbol}|synthetic-option-entry-repaired"
                            ),
                            (
                                f"Option ledger signal repaired: {candidate.instrument} "
                                f"{candidate.trading_symbol} rebased to verified premium "
                                f"{float(verified_premium):.2f}"
                            ),
                            "info",
                        )
                        continue
                    book.pop(key, None)
                    removed_entries.add(entry_key)
                    changed = True
                    self.log_signal_decision_once(
                        (
                            f"{candidate.instrument}|{candidate.timeframe}|"
                            f"{candidate.trading_symbol}|synthetic-option-entry-pruned"
                        ),
                        (
                            f"Invalid option ledger row removed: {candidate.instrument} "
                            f"{candidate.trading_symbol} used the retired spot-based premium estimate"
                        ),
                        "warning",
                    )
                    continue
                action = getattr(candidate, "action", "ENTRY")
                if action == "EXIT":
                    continue
                if action == "NO_ENTRY":
                    book.pop(key, None)
                    changed = True
                    continue
                if bool(getattr(candidate, "accepted_by_gate", False)):
                    continue
                if self._passes_live_trade_ready_gate(candidate):
                    continue
                entry_ts = getattr(candidate, "signal_timestamp", None)
                removed_entries.add((
                    candidate.instrument,
                    candidate.timeframe,
                    candidate.direction,
                    candidate.trading_symbol or "",
                    entry_ts.isoformat(timespec="seconds") if entry_ts else "",
                ))
                book.pop(key, None)
                changed = True

            if removed_entries or repaired_entries:
                for key, candidate in list(book.items()):
                    if getattr(candidate, "action", "ENTRY") != "EXIT":
                        continue
                    entry_ts = getattr(candidate, "signal_timestamp", None)
                    entry_key = (
                        candidate.instrument,
                        candidate.timeframe,
                        candidate.direction,
                        candidate.trading_symbol or "",
                        entry_ts.isoformat(timespec="seconds") if entry_ts else "",
                    )
                    if entry_key in removed_entries or entry_key in repaired_entries:
                        book.pop(key, None)
                        changed = True

            if not book:
                store.pop(instrument, None)
                changed = True

        if changed:
            self._persist_session_trade_candidates()

    def _is_aplus_setup(self, item) -> bool:
        # Single definition shared with trading/trade_manager.py — see is_top_tier_setup.
        return is_top_tier_setup(getattr(item, "grade", ""), getattr(item, "confidence", 0.0))

    def _force_candidate_instrument_type(self, candidate: TradeCandidate, target_type: str) -> bool:
        """Convert a same-index cross-TF candidate to the complementary instrument type."""
        target_type = (target_type or "").upper()
        if target_type == candidate.inst_type:
            return True

        # entry_spot ONLY. candidate.price is the CONTRACT price -- a futures LTP on a
        # FUT candidate (spot plus the basis, so a strike two steps off) or an option
        # PREMIUM on an OPT one (~120, which rounds to a NIFTY "strike" of 100 and then
        # gets snapped to the lowest listed contract). A strike must be derived from a
        # genuine index level or not at all.
        spot = float(getattr(candidate, "entry_spot", 0.0) or 0.0)
        candles = getattr(self, "candles", None)
        if candles is not None and hasattr(candles, "get_latest_price"):
            try:
                spot = candles.get_latest_price(candidate.instrument) or spot
            except Exception as e:
                logger.debug(f"Concurrency Guard: latest price unavailable for {candidate.instrument}: {e}")
        # Guarded ONCE, here, so nothing downstream needs an `or candidate.price` escape.
        # That escape was the bug: candidate.price is the CONTRACT price, so converting an
        # OPT candidate to FUT took its premium (~120) as a futures price, and converting
        # a FUT candidate to OPT rounded the futures LTP into a strike two steps off the
        # true ATM. Without a genuine index level there is nothing safe to convert.
        if not spot or float(spot) <= 0:
            logger.warning(
                f"Concurrency Guard: no index spot for {candidate.instrument}; refusing "
                "to convert instrument type from a contract price."
            )
            return False
        spot = float(spot)
        rr = max(1.1, float(candidate.rr or 1.5))

        if target_type == "FUT":
            market_info = getattr(self, "market_info", {}) or {}
            info = market_info.get(candidate.instrument, {})
            symbol = info.get("current_fut", "")
            token = info.get("current_fut_token", "")
            if not symbol or not token:
                logger.warning(f"Concurrency Guard: cannot convert {candidate.instrument} to FUT; missing futures token.")
                return False

            exchange = "BFO" if candidate.instrument == "SENSEX" else "NFO"
            fut_price = 0.0
            data = getattr(self, "data", None)
            try:
                fut_price = float(data.get_ltp(exchange, symbol, token) or 0.0) if data is not None else 0.0
            except Exception as e:
                logger.debug(f"FUT conversion LTP fallback for {symbol}: {e}")
            if fut_price <= 0:
                fut_price = spot

            risk = max(1.0, fut_price * (float(getattr(self, "futures_sl_pct", 0.2) or 0.2) / 100.0))
            candidate.inst_type = "FUT"
            candidate.option_type = ""
            candidate.atm_strike = 0.0
            candidate.multiplier = 1.0
            candidate.trading_symbol = symbol
            candidate.symbol_token = token
            candidate.price = fut_price
            candidate.current_price = fut_price
            if candidate.direction == "LONG":
                candidate.stop = fut_price - risk
                candidate.target = fut_price + (risk * rr)
            else:
                candidate.stop = fut_price + risk
                candidate.target = fut_price - (risk * rr)
            candidate.reasons = list(candidate.reasons or []) + ["Concurrency Guard forced FUT complement"]
            return True

        if target_type == "OPT":
            data = getattr(self, "data", None)
            if data is None:
                logger.warning(f"Concurrency Guard: cannot convert {candidate.instrument} to OPT; market data provider unavailable.")
                return False
            config = getattr(self, "config", {}) or {}
            strike_interval = config.get("indices", {}).get(candidate.instrument, {}).get("strike_interval", 50)
            strike = round(spot / strike_interval) * strike_interval
            option_type = "CE" if candidate.direction == "LONG" else "PE"
            opt_info = data.get_option_token(candidate.instrument, strike, option_type)
            if not opt_info:
                logger.warning(f"Concurrency Guard: cannot convert {candidate.instrument} to OPT; missing option token.")
                return False

            premium = 0.0
            exchange = "BFO" if candidate.instrument == "SENSEX" else "NFO"
            try:
                premium = float(data.get_ltp(exchange, opt_info["symbol"], opt_info["token"]) or 0.0)
            except Exception as e:
                logger.debug(f"OPT conversion LTP fallback for {opt_info.get('symbol')}: {e}")
            if premium <= 0:
                premium = max(1.0, spot * 0.012)

            risk = Scanner._option_premium_stop_distance_for_candidate(self, premium, candidate)
            candidate.inst_type = "OPT"
            candidate.option_type = option_type
            candidate.atm_strike = strike
            candidate.multiplier = 0.5 if option_type == "CE" else -0.5
            candidate.trading_symbol = opt_info["symbol"]
            candidate.symbol_token = opt_info["token"]
            candidate.price = premium
            candidate.current_price = premium
            candidate.stop = premium - risk
            candidate.target = premium + (risk * rr)
            candidate.reasons = list(candidate.reasons or []) + ["Concurrency Guard forced OPT complement"]
            return True

        return False

    @staticmethod
    def _is_quad_prime_raw_candidate(candidate: TradeCandidate) -> bool:
        try:
            # Engine 10 v2 candidates never carry raw flags; only quad_prime
            # mode produces raw candidates needing this hygiene path.
            if str(getattr(get_settings(), "scanner_engine", "") or "").lower() != "quad_prime":
                return False
            return bool(
                getattr(candidate, "quad_union_entry", False)
                or getattr(candidate, "raw_union_entry", False)
            )
        except Exception:
            return False

    def _quad_prime_duplicate_active(self, candidate: TradeCandidate, existing: List[Any]) -> bool:
        candidate_sources = self._quad_union_sources(candidate)
        candidate_tf = str(getattr(candidate, "timeframe", "") or "")
        candidate_direction = str(getattr(candidate, "direction", "") or "").upper()
        for item in existing:
            if str(getattr(item, "direction", "") or "").upper() != candidate_direction:
                continue
            if str(getattr(item, "timeframe", "") or "") != candidate_tf:
                continue
            item_sources = self._quad_union_sources(item)
            if not candidate_sources or not item_sources or bool(candidate_sources & item_sources):
                return True
        return False

    @staticmethod
    def _candidate_quality_tuple(item) -> Tuple[int, float]:
        try:
            rank = SignalProcessor._grade_rank(getattr(item, "grade", ""))
        except Exception:
            rank = 0
        try:
            confidence = float(getattr(item, "confidence", 0.0) or 0.0)
        except Exception:
            confidence = 0.0
        return rank, confidence

    def _candidate_quality_same_or_better(self, candidate, existing: List[Any]) -> bool:
        """Second same-index entry must be same grade/confidence or better."""
        candidate_rank, candidate_conf = self._candidate_quality_tuple(candidate)
        for item in existing:
            existing_rank, existing_conf = self._candidate_quality_tuple(item)
            if candidate_rank < existing_rank:
                return False
            if candidate_rank == existing_rank and candidate_conf + 1e-9 < existing_conf:
                return False
        return True

    def _candidate_volume_ratio_for_burst(self, candidate: TradeCandidate) -> float:
        try:
            volume_ratio = float(getattr(candidate, "volume_ratio", 0.0) or 0.0)
        except Exception:
            volume_ratio = 0.0
        if volume_ratio > 0:
            return volume_ratio
        try:
            signal_type = "BUY" if str(getattr(candidate, "direction", "") or "").upper() == "LONG" else "SELL"
            metrics = self._candle_thrust_metrics(
                getattr(candidate, "instrument", ""),
                getattr(candidate, "timeframe", ""),
                signal_type,
                as_of=getattr(candidate, "signal_timestamp", None),
            )
            return float((metrics or {}).get("volume_ratio", 0.0) or 0.0)
        except Exception:
            return 0.0

    def _candidate_signed_intelligence(self, candidate: TradeCandidate) -> float:
        try:
            signed = float(getattr(candidate, "intelligence_score", 0.0) or 0.0)
        except Exception:
            signed = 0.0
        if abs(signed) >= 1e-9:
            return signed
        try:
            ctx = self._candidate_market_intelligence_context(candidate)
            aggregate = ctx.get("aggregate", {}) if isinstance(ctx, dict) and isinstance(ctx.get("aggregate"), dict) else {}
            return aggregate_intelligence_score(aggregate)
        except Exception:
            return 0.0

    def _entry_intelligence_reading(
        self, candidate: TradeCandidate, timeframe: Optional[str] = None
    ) -> Tuple[bool, float, float, str]:
        """(available, signed score, adx, source) for an entry-policy decision.

        Availability is reported SEPARATELY from the score because 0.0 is a
        legitimate measurement — a balanced book — and also what every failure path
        returns. _candidate_signed_intelligence collapses the two, so a guard
        reading it cannot tell "the book is neutral" from "there is no book".

        2026-08-12 14:36 and 14:55, mid-reversal, the 15-minute guard refused
        MIDCPNIFTY with "signed intelligence -0.00 not aligned for BUY" and again at
        -0.01. Those are not bearish readings; they are the absence of one, and the
        entry died for it. Same defect as the order-flow pillar reading an absent
        ratio as a real 0.0 (see _first_present_number).

        Contract and semantics follow restore_point_51's
        _fresh_entry_intelligence_metrics: read the EXACT timeframe with no
        fallback — a 5-minute reading is not evidence about a 15-minute entry —
        and bound it by the age this codebase already calls stale for entry
        acceleration. Built on this build's own primitives rather than porting that
        build's cache readers, which this one does not have.

        A scanner with no intelligence cache at all is a bare test double, not a
        starved production scanner; it keeps the candidate's own snapshot, exactly
        as the ported build does.
        """
        instrument = str(getattr(candidate, "instrument", "") or "").split()[0].upper()
        tf = str(timeframe or getattr(candidate, "timeframe", "5min") or "5min").lower()

        exact = None
        try:
            exact = self._cached_timeframe_intel(instrument, tf, allow_fallback=False)
        except Exception:
            exact = None

        if isinstance(exact, dict) and exact:
            try:
                age = self._intel_age_seconds(exact, instrument)
            except Exception:
                age = None
            max_age = float(
                getattr(get_settings(), "loss_guard_intel_max_age_seconds", 90.0) or 90.0
            )
            # None means the age could not be established — missing evidence about
            # freshness, not evidence of staleness.
            if age is not None and max_age > 0 and float(age) > max_age:
                return False, 0.0, 0.0, (
                    f"exact {tf} intelligence stale ({float(age):.0f}s > {max_age:.0f}s)"
                )
            aggregate = exact.get("aggregate") if isinstance(exact.get("aggregate"), dict) else {}
            regime_payload = exact.get("regime") if isinstance(exact.get("regime"), dict) else {}
            # aggregate_intelligence_score knows the aggregate's unit;
            # normalize_intelligence_score infers scale from magnitude and must
            # never be pointed at an aggregate payload (test_intel_score_unit_is_explicit).
            try:
                signed = aggregate_intelligence_score(aggregate)
            except Exception:
                signed = 0.0
            adx = Scanner._first_present_number(regime_payload, "adx")
            if adx is None:
                adx = Scanner._first_present_number(aggregate, "adx")
            return True, float(signed), float(adx or 0.0), "fresh_exact_intelligence"

        if hasattr(self, "_intel_cache"):
            return False, 0.0, 0.0, f"exact {tf} intelligence unavailable"

        try:
            signed = normalize_intelligence_score(
                float(getattr(candidate, "intelligence_score", 0.0) or 0.0)
            )
        except (TypeError, ValueError):
            signed = 0.0
        try:
            adx = float(getattr(candidate, "adx_value", 0.0) or 0.0)
        except (TypeError, ValueError):
            adx = 0.0
        return True, float(signed), float(adx), "candidate_snapshot"

    @staticmethod
    def _candidate_signal_type(candidate: TradeCandidate) -> str:
        source = str(getattr(candidate, "source_signal_type", "") or "").upper()
        if source in {"BUY", "SELL"}:
            return source
        return "BUY" if str(getattr(candidate, "direction", "") or "").upper() == "LONG" else "SELL"

    @staticmethod
    def _directional_bias(signal_type: str) -> str:
        return "BULLISH" if str(signal_type or "").upper() == "BUY" else "BEARISH"

    @staticmethod
    def _bias_opposes_signal(value: str, signal_type: str) -> bool:
        bias = str(value or "").upper()
        if bias not in {"BULLISH", "BEARISH", "TRENDING_UP", "TRENDING_DOWN", "BREAKOUT_UP", "BREAKOUT_DOWN"}:
            return False
        bullish = bias in {"BULLISH", "TRENDING_UP", "BREAKOUT_UP"}
        wants_buy = str(signal_type or "").upper() == "BUY"
        return bullish != wants_buy

    @staticmethod
    def _bias_aligns_signal(value: str, signal_type: str) -> bool:
        bias = str(value or "").upper()
        if bias in {"BULLISH", "TRENDING_UP", "BREAKOUT_UP"}:
            return str(signal_type or "").upper() == "BUY"
        if bias in {"BEARISH", "TRENDING_DOWN", "BREAKOUT_DOWN"}:
            return str(signal_type or "").upper() == "SELL"
        return False

    def _candidate_market_intelligence_context(self, candidate: TradeCandidate) -> Dict[str, Any]:
        ctx = getattr(candidate, "market_intelligence_context", None)
        if isinstance(ctx, dict) and ctx:
            return ctx
        try:
            intel = self._cached_timeframe_intel(
                getattr(candidate, "instrument", ""),
                getattr(candidate, "timeframe", "5min"),
                allow_fallback=True,
            )
        except Exception:
            intel = None
        if not isinstance(intel, dict):
            return {}
        return {
            "aggregate": intel.get("aggregate", {}) if isinstance(intel.get("aggregate"), dict) else {},
            "order_flow": intel.get("order_flow", {}) if isinstance(intel.get("order_flow"), dict) else {},
            "session_context": intel.get("session_context", {}) if isinstance(intel.get("session_context"), dict) else {},
            "anchor_regime": intel.get("anchor_regime", {}) if isinstance(intel.get("anchor_regime"), dict) else {},
            "breadth_context": intel.get("breadth_context", {}) if isinstance(intel.get("breadth_context"), dict) else {},
            "top_down_context": intel.get("top_down_context", {}) if isinstance(intel.get("top_down_context"), dict) else {},
        }

    def _micro_timeframe_direction_confirmed(
        self,
        candidate: TradeCandidate,
        signal_type: str,
        max_skew: float,
    ) -> Tuple[bool, Dict[str, Any]]:
        instrument = str(getattr(candidate, "instrument", "") or "").split()[0].upper()
        ts = getattr(candidate, "signal_timestamp", None)
        if not instrument or ts is None:
            return False, {"reason": "missing timestamp"}
        sig = str(signal_type or "").upper()
        min_close = float(getattr(get_settings(), "fifteen_min_choppy_scalp_min_close_location", 0.55) or 0.55)
        details: Dict[str, Any] = {}
        for tf in ("1min", "5min"):
            sig_ref, skew = self._cached_signal_near(instrument, tf, sig, ts, max_skew)
            ref_ts = getattr(sig_ref, "timestamp", ts) if sig_ref is not None else ts
            metrics = self._candle_thrust_metrics(instrument, tf, sig, as_of=ref_ts) or {}
            reclaim = self._directional_reclaim_snapshot(instrument, tf, sig, as_of=ref_ts) or {}
            close_location = max(
                float(metrics.get("close_location", 0.0) or 0.0),
                float(reclaim.get("close_location", 0.0) or 0.0),
            )
            confirmed = bool(sig_ref is not None) or bool(reclaim.get("reclaimed"))
            if close_location < min_close and not bool(reclaim.get("reclaimed")):
                confirmed = False
            details[tf] = {
                "cached_signal": bool(sig_ref is not None),
                "skew_seconds": float(skew or 0.0),
                "close_location": close_location,
                "reclaimed": bool(reclaim.get("reclaimed")),
                "volume_ratio": float(metrics.get("volume_ratio", 0.0) or 0.0),
                "confirmed": confirmed,
            }
            if not confirmed:
                return False, details
        return True, details

    def _fifteen_min_choppy_scalp_context(self, candidate: TradeCandidate, regime: str) -> Tuple[bool, str]:
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "fifteen_min_choppy_scalp_guard_enabled", True), True):
            return True, ""
        timeframe = str(getattr(candidate, "timeframe", "") or "")
        inst_type = str(getattr(candidate, "inst_type", "") or "").upper()
        if timeframe != "15min" or inst_type != "OPT" or not is_risky_regime(regime):
            return True, ""
        if bool(getattr(candidate, "power_move", False)) or bool(getattr(candidate, "volume_spike_entry", False)):
            return True, ""
        if bool(getattr(candidate, "late_session_reclaim_entry", False)):
            return True, ""
        # A synchronised multi-index reversal is the same class of exemption as the
        # power-move and volume-spike lanes above: the move itself is the evidence.
        # These are fast-tracked through a 5-10s stabilization buffer precisely
        # because the whole market turned, and were then vetoed here for lacking a
        # single instrument's intel alignment — 2026-08-12 14:36, three MIDCPNIFTY
        # 15min LONGs refused mid-reversal on a -0.00 reading. A market-wide entry
        # has already cleared B+ grade, 60% confidence and an independently
        # confirmed peer (_market_wide_candidate_quality), which is more evidence
        # than this guard asks of anything else it lets through.
        if (
            bool(getattr(candidate, "market_wide_reversal_entry", False))
            or bool(getattr(candidate, "market_ltp_shock_entry", False))
            or bool(getattr(candidate, "one_way_cascade_entry", False))
        ):
            return True, ""
        if bool(getattr(candidate, "quad_union_entry", False) or getattr(candidate, "raw_union_entry", False)):
            try:
                trend_15m_agrees = bool(self._candidate_15m_trend_agrees(candidate))
            except Exception:
                trend_15m_agrees = bool(getattr(candidate, "trend_15m_agrees", False))
            try:
                grade_rank = SignalProcessor._grade_rank(getattr(candidate, "grade", ""))
            except Exception:
                grade_rank = 0
            try:
                confidence = float(getattr(candidate, "confidence", 0.0) or 0.0)
            except Exception:
                confidence = 0.0
            if (
                trend_15m_agrees
                and grade_rank >= SignalProcessor._grade_rank("A")
                and confidence >= SignalProcessor._grade_min_confidence("A")
            ):
                return True, ""

        signal_type = self._candidate_signal_type(candidate)
        # Availability first: a missing reading is not a bearish one.
        intel_available, signed_intel, fresh_adx, intel_reason = (
            self._entry_intelligence_reading(candidate, "15min")
        )
        if not intel_available:
            return False, f"15min choppy scalp guard: {intel_reason}"
        try:
            setattr(candidate, "intelligence_score", float(signed_intel))
            if float(fresh_adx or 0.0) > 0.0:
                setattr(candidate, "adx_value", float(fresh_adx))
        except Exception:
            pass
        min_intel = float(getattr(settings, "fifteen_min_choppy_scalp_min_intel_score", 0.20) or 0.20)
        intel_ok = signed_intel >= min_intel if signal_type == "BUY" else signed_intel <= -min_intel
        if not intel_ok:
            return False, f"15min choppy scalp guard: signed intelligence {signed_intel:+.2f} not aligned for {signal_type}"

        volume_ratio = self._candidate_volume_ratio_for_burst(candidate)
        min_volume = float(getattr(settings, "fifteen_min_choppy_scalp_min_volume_ratio", 1.05) or 1.05)
        if 0.0 < volume_ratio < min_volume:
            return False, f"15min choppy scalp guard: volume {volume_ratio:.2f}x below {min_volume:.2f}x"

        max_skew = max(
            0.0,
            float(getattr(settings, "fifteen_min_choppy_scalp_micro_max_skew_seconds", 240.0) or 240.0),
        )
        micro_ok, micro_details = self._micro_timeframe_direction_confirmed(candidate, signal_type, max_skew)
        if not micro_ok:
            return False, "15min choppy scalp guard: missing 1min/5min same-side reclaim confirmation"
        effective_volume = max(
            volume_ratio,
            float((micro_details.get("1min") or {}).get("volume_ratio", 0.0) or 0.0),
            float((micro_details.get("5min") or {}).get("volume_ratio", 0.0) or 0.0),
        )
        if effective_volume < min_volume:
            return False, f"15min choppy scalp guard: volume {effective_volume:.2f}x below {min_volume:.2f}x"

        setattr(candidate, "fifteen_min_choppy_scalp_entry", True)
        setattr(
            candidate,
            "fifteen_min_choppy_scalp_context",
            {
                "signal_type": signal_type,
                "regime": str(regime or ""),
                "signed_intelligence": signed_intel,
                "volume_ratio": effective_volume,
                "micro": micro_details,
            },
        )
        self._set_scalp_lock(candidate, True)
        try:
            candidate.rr = min(float(getattr(candidate, "rr", 1.5) or 1.5), 1.5)
        except Exception:
            candidate.rr = 1.5
        reason = (
            f"15min choppy scalp mode: {signal_type} micro-confirmed "
            f"(intel {signed_intel:+.2f}, volume {effective_volume:.2f}x)"
        )
        self._tag_candidate_reason(candidate, reason)
        return True, reason

    def _rare_burst_market_intelligence_ok(
        self,
        candidate: TradeCandidate,
        signal_type: str,
    ) -> Tuple[bool, str]:
        settings = get_settings()
        intel_ctx = self._candidate_market_intelligence_context(candidate)
        if not intel_ctx:
            return False, "market intelligence unavailable"

        aggregate = intel_ctx.get("aggregate", {}) if isinstance(intel_ctx.get("aggregate"), dict) else {}
        session_ctx = intel_ctx.get("session_context", {}) if isinstance(intel_ctx.get("session_context"), dict) else {}
        anchor = intel_ctx.get("anchor_regime", {}) if isinstance(intel_ctx.get("anchor_regime"), dict) else {}
        breadth = intel_ctx.get("breadth_context", {}) if isinstance(intel_ctx.get("breadth_context"), dict) else {}
        order_flow = intel_ctx.get("order_flow", {}) if isinstance(intel_ctx.get("order_flow"), dict) else {}
        top_down = intel_ctx.get("top_down_context", {}) if isinstance(intel_ctx.get("top_down_context"), dict) else {}

        try:
            signed_intel = float(getattr(candidate, "intelligence_score", 0.0) or 0.0)
        except Exception:
            signed_intel = 0.0
        if abs(signed_intel) < 1e-9:
            signed_intel = aggregate_intelligence_score(aggregate)
        min_intel = float(getattr(settings, "rare_burst_min_intel_score", 0.70) or 0.70)
        intel_aligns = signed_intel >= min_intel if signal_type == "BUY" else signed_intel <= -min_intel
        if not intel_aligns:
            return False, f"signed intel {signed_intel:+.2f} not aligned >= {min_intel:.2f}"

        phase, phase_conf = self._intraday_phase_from_session_context(session_ctx)
        if (
            self._setting_enabled(getattr(settings, "rare_burst_block_range_phase", True), True)
            and phase == "RANGE_PHASE"
            and phase_conf >= float(getattr(settings, "dynamic_trade_budget_min_day_confidence", 0.60) or 0.60)
        ):
            return False, f"range-phase intelligence conf {phase_conf:.0%}"

        session_bias = str(session_ctx.get("bias") or "").upper()
        if self._bias_opposes_signal(session_bias, signal_type):
            return False, f"session bias {session_bias} opposes"
        if (
            self._setting_enabled(getattr(settings, "rare_burst_require_session_bias", True), True)
            and not self._bias_aligns_signal(session_bias, signal_type)
        ):
            return False, f"session bias {session_bias or 'missing'} not aligned"

        delta_ctx = session_ctx.get("session_delta", {}) if isinstance(session_ctx.get("session_delta"), dict) else {}
        delta_bias = str(delta_ctx.get("bias") or "").upper()
        try:
            delta_ratio = abs(float(delta_ctx.get("delta_ratio", 0.0) or 0.0))
        except Exception:
            delta_ratio = 0.0
        if delta_ratio >= 0.15 and self._bias_opposes_signal(delta_bias, signal_type):
            return False, f"session delta {delta_bias} opposes"

        try:
            vix_change = float(session_ctx.get("vix_change_pct", 0.0) or 0.0)
        except Exception:
            vix_change = 0.0
        if signal_type == "BUY" and vix_change > 2.0:
            return False, f"VIX rising {vix_change:.1f}% against BUY"
        if signal_type == "SELL" and vix_change < -2.0:
            return False, f"VIX falling {vix_change:.1f}% against SELL"

        anchor_regime = str(anchor.get("regime") or "").upper()
        if self._setting_enabled(getattr(settings, "rare_burst_require_hourly_anchor", True), True):
            if not anchor_regime:
                return False, "60min anchor missing"
            if not regime_aligns(anchor_regime, signal_type):
                return False, f"60min anchor {anchor_regime} not aligned"

        breadth_bias = str(breadth.get("bias") or "").upper()
        try:
            breadth_votes = int(float(breadth.get("aligned_count", 0) or 0))
        except Exception:
            breadth_votes = 0
        min_votes = int(getattr(settings, "rare_burst_min_breadth_votes", 3) or 3)
        if breadth_votes < min_votes or not self._bias_aligns_signal(breadth_bias, signal_type):
            return False, f"breadth {breadth_bias or 'missing'} {breadth_votes}/{min_votes} not aligned"

        flow_signal = str(order_flow.get("signal") or "").upper()
        if self._bias_opposes_signal(flow_signal, signal_type):
            return False, f"order-flow {flow_signal} opposes"

        try:
            top_down_adjustment = float(
                aggregate.get("top_down_adjustment", top_down.get("score_adjustment", 0.0)) or 0.0
            )
        except Exception:
            top_down_adjustment = 0.0
        if signal_type == "BUY" and top_down_adjustment < -0.03:
            return False, f"top-down {top_down_adjustment:+.2f} opposes BUY"
        if signal_type == "SELL" and top_down_adjustment > 0.03:
            return False, f"top-down {top_down_adjustment:+.2f} opposes SELL"

        return True, (
            f"intel {signed_intel:+.2f}, session {session_bias}, "
            f"anchor {anchor_regime}, breadth {breadth_bias} {breadth_votes}, "
            f"top-down {top_down_adjustment:+.2f}"
        )

    def _rare_burst_context(self, candidate: TradeCandidate) -> Tuple[bool, str]:
        """Permit the 3rd same-index slot only on a hard all-index impulse."""
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "rare_burst_third_trade_enabled", True), True):
            return False, "disabled"
        # The rare 4x3 stretch is deliberately available only when the operator has
        # relaxed the ordinary concurrency guard. Guard ON remains capped at 4x2.
        if self._setting_enabled(getattr(settings, "ut_concurrency_guard", True), True):
            return False, "guard-on cap"
        try:
            confidence = float(getattr(candidate, "confidence", 0.0) or 0.0)
        except Exception:
            confidence = 0.0
        min_conf = float(getattr(settings, "rare_burst_min_confidence", 0.95) or 0.95)
        if confidence < min_conf:
            return False, f"conf {confidence:.0%} < {min_conf:.0%}"
        try:
            adx_value = float(getattr(candidate, "adx_value", 0.0) or 0.0)
        except Exception:
            adx_value = 0.0
        min_adx = float(getattr(settings, "rare_burst_min_adx", 35.0) or 35.0)
        if adx_value < min_adx:
            return False, f"ADX {adx_value:.1f} < {min_adx:.1f}"
        volume_ratio = self._candidate_volume_ratio_for_burst(candidate)
        min_volume = float(getattr(settings, "rare_burst_min_volume_ratio", 3.5) or 3.5)
        if volume_ratio < min_volume:
            return False, f"volume {volume_ratio:.1f}x < {min_volume:.1f}x"

        signal_type = self._candidate_signal_type(candidate)
        intel_ok, intel_reason = self._rare_burst_market_intelligence_ok(candidate, signal_type)
        if not intel_ok:
            return False, intel_reason

        active = [str(x).upper() for x in (getattr(self, "active_indices", []) or []) if str(x or "").strip()]
        if not active:
            active = ["NIFTY", "BANKNIFTY", "SENSEX", "MIDCPNIFTY"]
        regimes = getattr(self, "latest_regimes", {}) or {}
        aligned = []
        missing = []
        for inst in active:
            regime = str(regimes.get(inst) or "").upper()
            if not regime:
                missing.append(inst)
                continue
            if regime_aligns(regime, signal_type):
                aligned.append(inst)
        if len(aligned) < len(active):
            not_aligned = [inst for inst in active if inst not in aligned and inst not in missing]
            detail = []
            if missing:
                detail.append("missing " + "/".join(missing))
            if not_aligned:
                detail.append("not aligned " + "/".join(not_aligned))
            return False, "; ".join(detail) or "all-index alignment missing"
        return True, (
            f"all-index {signal_type} alignment, conf {confidence:.0%}, "
            f"volume {volume_ratio:.1f}x, ADX {adx_value:.1f}, {intel_reason}"
        )

    @staticmethod
    def _tag_candidate_reason(candidate, reason: str) -> None:
        try:
            reasons = list(getattr(candidate, "reasons", []) or [])
            if reason not in reasons:
                reasons.append(reason)
            candidate.reasons = reasons
        except Exception:
            pass

    def _apply_rare_burst_fast_tracking(self, candidate: TradeCandidate, reason: str) -> None:
        setattr(candidate, "rare_burst_entry", True)
        setattr(candidate, "rare_burst_fast_tracking", True)
        self._set_scalp_lock(candidate, True)
        self._tag_candidate_reason(
            candidate,
            f"Rare burst concurrency: {reason}; scalp-lock fast tracking enabled",
        )

    def _active_index_trade_cap(self, candidate: TradeCandidate, existing_count: int = 0) -> Tuple[int, str]:
        settings = get_settings()
        normal_cap = max(1, int(getattr(settings, "max_concurrent_trades_per_index", 2) or 2))
        # Cascade-only multi-TF stack: core 1m+5m+15m (+ dual); midcap solo 2 / dual 2+1.
        if (
            bool(getattr(candidate, "one_way_cascade_entry", False))
            and self._setting_enabled(
                getattr(settings, "cascade_multi_tf_stack_enabled", True), True
            )
        ):
            inst = str(getattr(candidate, "instrument", "") or "").split()[0].upper()
            core_set = self._cascade_multi_tf_core_set()
            midcap_name = str(
                getattr(self, "MIDCAP_CORRELATED_INDEX", "MIDCPNIFTY") or "MIDCPNIFTY"
            ).upper()
            if inst == midcap_name or inst not in core_set:
                solo = max(1, int(getattr(settings, "cascade_midcap_solo_max_tf", 2) or 2))
                dual_main = max(1, int(getattr(settings, "cascade_midcap_dual_main_max", 2) or 2))
                dual_addon = max(0, int(getattr(settings, "cascade_midcap_dual_addon_max", 1) or 1))
                cascade_cap = max(solo, dual_main + dual_addon)  # solo 2 or dual 2+1=3
                return cascade_cap, f"cascade midcap stack (solo {solo} / dual {dual_main}+{dual_addon})"
            primary = max(1, int(getattr(settings, "cascade_primary_max_tf", 3) or 3))
            dual_addon = max(0, int(getattr(settings, "cascade_dual_addon_max", 2) or 2))
            cascade_cap = primary + dual_addon
            return cascade_cap, f"cascade multi-TF stack (primary {primary}+dual {dual_addon})"
        # Dual modes: 2 primary + 1 dual addon max per index (non-cascade).
        dual_cap = max(
            normal_cap,
            int(getattr(settings, "dual_mode_max_per_index", 3) or 3),
        )
        if (
            str(getattr(settings, "scanner_engine", "") or "").lower() == "adaptive_dual"
            and self._setting_enabled(getattr(settings, "dual_lane_enabled", True), True)
            and self._source_lane(candidate) == "B"
        ):
            if existing_count < dual_cap:
                return dual_cap, "dual-mode 2+1"
        if existing_count < normal_cap:
            return normal_cap, "normal"
        rare_cap = max(normal_cap, int(getattr(settings, "rare_burst_max_concurrent_trades_per_index", 3) or 3))
        rare_ok, rare_reason = self._rare_burst_context(candidate)
        if rare_ok:
            self._apply_rare_burst_fast_tracking(candidate, rare_reason)
            return rare_cap, f"rare-burst: {rare_reason}"
        return normal_cap, rare_reason

    @staticmethod
    def _source_lane(item) -> str:
        lane = str(getattr(item, "source_lane", "") or "").upper()
        if lane in {"A", "B"}:
            return lane
        source = str(getattr(item, "source_engine", "") or "").lower()
        if source in {"flow_burst", "apex_hybrid"}:
            return "B"
        return ""

    @staticmethod
    def _parse_trade_timestamp(value) -> Optional[datetime]:
        if value is None:
            return None
        if isinstance(value, datetime):
            ts = value
        else:
            text = str(value or "").strip()
            if not text:
                return None
            try:
                ts = datetime.fromisoformat(text.replace("Z", "+00:00"))
            except Exception:
                return None
        if getattr(ts, "tzinfo", None) is not None:
            ts = ts.astimezone(IST).replace(tzinfo=None)
        return ts

    def _candidate_bar_gap(self, candidate, existing) -> int:
        cand_ts = self._parse_trade_timestamp(getattr(candidate, "signal_timestamp", None))
        existing_ts = self._parse_trade_timestamp(
            getattr(existing, "source_signal_timestamp", None)
            or getattr(existing, "signal_timestamp", None)
            or getattr(existing, "entry_timestamp", None)
            or getattr(existing, "entry_time", None)
        )
        if cand_ts is not None and existing_ts is not None:
            seconds = max(1, self._timeframe_seconds(getattr(candidate, "timeframe", "")))
            return max(0, int(abs((cand_ts - existing_ts).total_seconds()) // seconds))
        try:
            cand_bar = int(getattr(candidate, "source_signal_bar_index", -1) or -1)
            existing_bar = int(getattr(existing, "source_signal_bar_index", -1) or -1)
            if cand_bar >= 0 and existing_bar >= 0:
                return max(0, abs(cand_bar - existing_bar))
        except Exception:
            pass
        return 0

    def _trade_like_open_r_multiple(self, item) -> float:
        entry = self._trade_like_entry_price(item)
        current = float(
            getattr(item, "current_price", 0.0)
            or getattr(item, "price", 0.0)
            or getattr(item, "entry_price", 0.0)
            or entry
        )
        risk = self._trade_like_initial_risk_rs(item)
        if entry <= 0 or current <= 0 or risk <= 0:
            return 0.0
        qty = self._trade_like_quantity(item)
        inst_type = str(getattr(item, "inst_type", "") or "").upper()
        if inst_type == "OPT":
            gross = (current - entry) * qty
        else:
            mult = float(getattr(item, "multiplier", 1.0) or 1.0)
            direction = str(getattr(item, "direction", "LONG") or "LONG").upper()
            gross = (entry - current) * qty * mult if direction == "SHORT" else (current - entry) * qty * mult
        return float(gross or 0.0) / float(risk or 1.0)

    def _candidate_projected_risk_rs(self, candidate) -> float:
        entry = self._trade_like_entry_price(candidate)
        stop = self._ensure_trade_like_initial_stop(candidate)
        if entry <= 0 or stop <= 0:
            return 0.0
        qty = self._trade_like_quantity(candidate)
        mult = 1.0 if str(getattr(candidate, "inst_type", "") or "").upper() == "OPT" else float(getattr(candidate, "multiplier", 1.0) or 1.0)
        return abs(entry - stop) * qty * max(0.0, mult)

    @staticmethod
    def _reason_tokens(item) -> set:
        reasons = getattr(item, "reasons", []) or []
        if isinstance(reasons, str):
            text = reasons
        else:
            text = " ".join(str(reason) for reason in reasons)
        tokens = set(re.findall(r"[a-z0-9_]+", text.lower()))
        return {
            token
            for token in tokens
            if len(token) > 2 and token not in {"the", "and", "for", "with", "entry", "signal"}
        }

    def _dual_lane_jaccard(self, candidate, existing) -> float:
        left = self._reason_tokens(candidate)
        right = self._reason_tokens(existing)
        if not left or not right:
            return 0.0
        return len(left & right) / max(1, len(left | right))

    @staticmethod
    def _dual_lane_fresh_independent_trigger(candidate) -> bool:
        if str(getattr(candidate, "source_engine", "") or "").lower() in {"flow_burst", "apex_hybrid"}:
            return True
        return any(
            bool(getattr(candidate, attr, False))
            for attr in (
                "volume_spike_entry",
                "power_move",
                "market_wide_reversal_entry",
                "market_wide_reversal_context",
                "vwap_break_context",
            )
        )

    def _apply_dual_lane_size_fraction(self, candidate, reason: str) -> None:
        settings = get_settings()
        fraction = max(0.05, min(1.0, float(getattr(settings, "dual_lane_size_fraction", 0.65) or 0.65)))
        original_lots = max(1, int(getattr(candidate, "lots", 1) or 1))
        reduced_lots = max(1, int(math.floor(original_lots * fraction)))
        candidate.lots = reduced_lots
        setattr(candidate, "dual_lane_entry", True)
        setattr(candidate, "dual_lane_size_fraction", fraction)
        self._set_scalp_lock(candidate, True)
        if reduced_lots < original_lots:
            reason = f"{reason}; lots {original_lots}->{reduced_lots}"
        else:
            reason = f"{reason}; one-lot floor"
        self._tag_candidate_reason(candidate, f"Adaptive Dual Lane B add-on: {reason}; scalp-lock enabled")

    def _candidate_signal_ts(self, item) -> Optional[datetime]:
        """Best-effort naive IST timestamp for clone-reduction window checks."""
        for attr in (
            "signal_timestamp",
            "source_signal_timestamp",
            "entry_timestamp",
            "entry_time",
            "timestamp",
        ):
            ts = self._parse_trade_timestamp(getattr(item, attr, None))
            if ts is not None:
                return ts
        return None

    def _dual_clone_within_window(self, a, b, window_seconds: Optional[float] = None) -> bool:
        """True when a and b are same-TF clones within the dual reduction window."""
        settings = get_settings()
        if not self._setting_enabled(
            getattr(settings, "dual_clone_reduction_enabled", True), True
        ):
            return False
        tf_a = str(getattr(a, "timeframe", "") or "")
        tf_b = str(getattr(b, "timeframe", "") or "")
        if not tf_a or tf_a != tf_b:
            return False
        win = float(
            window_seconds
            if window_seconds is not None
            else (getattr(settings, "dual_clone_reduction_window_seconds", 60) or 60)
        )
        win = max(0.0, win)
        ts_a = self._candidate_signal_ts(a)
        ts_b = self._candidate_signal_ts(b)
        if ts_a is None and ts_b is None:
            # Both missing stamps in same selection wave → treat as same-candle clone
            return True
        if ts_a is None or ts_b is None:
            # One stamped, one not — only clone if we cannot prove independence
            return True
        return abs((ts_a - ts_b).total_seconds()) <= win

    def _apply_dual_clone_reduction(
        self, selected: List[TradeCandidate]
    ) -> List[TradeCandidate]:
        """Same index+TF dual engines within 1 min → keep only the FIRST (earliest).

        Later clone (second engine on same TF) is dropped. Different TFs unaffected.
        """
        settings = get_settings()
        if not self._setting_enabled(
            getattr(settings, "dual_clone_reduction_enabled", True), True
        ):
            return selected
        if not selected:
            return selected

        # Group by timeframe; within each TF keep earliest only if multiple lanes
        by_tf: Dict[str, List[TradeCandidate]] = {}
        for c in selected:
            tf = str(getattr(c, "timeframe", "") or "") or "?"
            by_tf.setdefault(tf, []).append(c)

        kept: List[TradeCandidate] = []
        for tf, rows in by_tf.items():
            if len(rows) <= 1:
                kept.extend(rows)
                continue
            # Sort by timestamp ascending (first wins); missing ts last
            def _sort_key(row):
                ts = self._candidate_signal_ts(row)
                return (ts is None, ts or datetime.max)

            ordered = sorted(rows, key=_sort_key)
            first = ordered[0]
            kept.append(first)
            for other in ordered[1:]:
                if self._dual_clone_within_window(first, other):
                    try:
                        other.reasons = list(other.reasons or []) + [
                            f"Dual clone reduction: same {tf} within 1m — kept first only"
                        ]
                        other.status = "REJECTED - Dual Clone Reduction"
                    except Exception:
                        pass
                    logger.info(
                        f"Dual clone reduction: drop {getattr(other, 'instrument', '')} "
                        f"{tf} lane {self._source_lane(other) or '?'} "
                        f"(kept first lane {self._source_lane(first) or '?'})"
                    )
                else:
                    # Outside window — keep both (true dual add-on later)
                    kept.append(other)
        # Preserve original relative order among kept
        kept_ids = {id(c) for c in kept}
        return [c for c in selected if id(c) in kept_ids]

    def _dual_lane_concurrency_decision(
        self,
        candidate,
        existing: List[Any],
        *,
        adjust_size: bool = True,
    ) -> Tuple[Optional[bool], str]:
        settings = get_settings()
        if str(getattr(settings, "scanner_engine", "") or "").lower() != "adaptive_dual":
            return None, ""
        if not self._setting_enabled(getattr(settings, "dual_lane_enabled", True), True):
            return None, ""
        if self._source_lane(candidate) != "B":
            return None, ""

        lane_a = [item for item in (existing or []) if self._source_lane(item) == "A"]
        if not lane_a:
            return None, ""

        # Clone reduction: same TF as any open lane within 1 minute → block B (keep first)
        cand_tf = str(getattr(candidate, "timeframe", "") or "")
        for item in existing or []:
            if str(getattr(item, "timeframe", "") or "") != cand_tf:
                continue
            if self._dual_clone_within_window(item, candidate):
                return (
                    False,
                    f"dual clone reduction: same {cand_tf} within "
                    f"{int(getattr(settings, 'dual_clone_reduction_window_seconds', 60) or 60)}s "
                    f"— keep first only",
                )

        try:
            confidence = float(getattr(candidate, "confidence", 0.0) or 0.0)
        except Exception:
            confidence = 0.0
        min_conf = float(getattr(settings, "dual_lane_min_lane_b_confidence", 0.70) or 0.70)
        if confidence < min_conf:
            return False, f"Lane B confidence {confidence:.0%} < {min_conf:.0%}"

        if not self._dual_lane_fresh_independent_trigger(candidate):
            return False, "Lane B lacks a fresh independent trigger"

        candidate_direction = str(getattr(candidate, "direction", "") or "").upper()
        same_direction_rows = []
        for item in lane_a:
            item_direction = str(getattr(item, "direction", "") or "").upper()
            if item_direction and candidate_direction and item_direction != candidate_direction:
                reason = f"opposite Lane B {candidate_direction} versus Lane A {item_direction}"
                self._tag_candidate_reason(candidate, f"Adaptive Dual Lane B reversal: {reason}")
                setattr(candidate, "dual_lane_entry", True)
                return True, reason
            same_direction_rows.append(item)

        min_gap = max(0, int(getattr(settings, "dual_lane_same_dir_min_bars_gap", 3) or 3))
        min_r = float(getattr(settings, "dual_lane_same_dir_min_lane_a_r", 0.50) or 0.50)
        max_jaccard = float(getattr(settings, "dual_lane_jaccard_alert_threshold", 0.30) or 0.30)
        exposure_cap = float(getattr(settings, "dual_lane_max_index_exposure_rs", 12000.0) or 12000.0)
        reasons = []
        for item in same_direction_rows:
            gap = self._candidate_bar_gap(candidate, item)
            if gap < min_gap:
                return False, f"same-direction Lane B too soon: {gap} bars < {min_gap}"
            lane_a_r = self._trade_like_open_r_multiple(item)
            if lane_a_r < min_r:
                return False, f"Lane A progress {lane_a_r:.2f}R < {min_r:.2f}R"
            overlap = self._dual_lane_jaccard(candidate, item)
            if overlap > max_jaccard:
                return False, f"Lane A/B reason overlap {overlap:.0%} > {max_jaccard:.0%}"
            reasons.append(f"{gap} bars, Lane A {lane_a_r:.2f}R")

        if exposure_cap > 0:
            projected = self._candidate_projected_risk_rs(candidate)
            projected += sum(self._trade_like_initial_risk_rs(item) for item in lane_a)
            if projected <= 0:
                return False, "dual-lane projected risk unavailable"
            if projected > exposure_cap:
                return False, f"dual-lane projected risk Rs.{projected:.0f} > cap Rs.{exposure_cap:.0f}"

        reason = "; ".join(reasons) or "same-direction proof passed"
        if adjust_size:
            self._apply_dual_lane_size_fraction(candidate, reason)
        return True, reason

    def _opposite_direction_stack_block(self, candidate, existing: List[Any]) -> str:
        """Reason to refuse a LONG while a SHORT is live on the same index, or vice versa.

        Every other branch of the concurrency guard reasons about timeframe, lane,
        instrument type and count — not one of them looks at DIRECTION. With
        ut_concurrency_guard off (the live setting) the guard short-circuits to True
        after the per-index cap, so the only thing standing between the book and a
        NIFTY long CE sitting next to a NIFTY long PE is max_trades_per_index=10.

        That pairing is not a hedge. Options here are always BOUGHT, so it is two
        premiums, two spreads and theta bleeding both legs, assembled by accident out
        of two independent signals that each looked fine alone. A real hedge is armed
        deliberately against a specific runner and is exempted below.

        Reversals are NOT blocked: an opposite signal that arrives after the first
        trade exits sees an empty `existing` and passes untouched. This only refuses
        holding both sides AT THE SAME TIME.
        """
        settings = get_settings()
        if not self._setting_enabled(
            getattr(settings, "block_opposite_direction_stack", True), True
        ):
            return ""
        direction = str(getattr(candidate, "direction", "") or "").upper()
        if direction not in {"LONG", "SHORT"}:
            return ""
        # A deliberately armed leg is the one case where holding both sides is the intent
        # rather than an accident. rare_burst_entry belongs here too: it already demands
        # A+ grade, ~95%+ confidence, high ADX, a volume burst AND all-index regime
        # agreement, so it is the system saying the whole market just turned. Refusing
        # that entry because two stale legs have not stopped out yet would forfeit the
        # best trade of the move to protect the worst.
        for flag in (
            "pullback_hedge_leg", "hedge_leg", "dual_lane_entry",
            "opposite_leg_entry", "rare_burst_entry",
        ):
            if bool(getattr(candidate, flag, False)):
                return ""
        for item in existing or []:
            if bool(getattr(item, "is_ghost", False)):
                continue
            for flag in ("pullback_hedge_leg", "hedge_leg", "opposite_leg_entry"):
                if bool(getattr(item, flag, False)):
                    break
            else:
                item_direction = str(getattr(item, "direction", "") or "").upper()
                if item_direction in {"LONG", "SHORT"} and item_direction != direction:
                    return (
                        f"opposite {direction} while {item_direction} is live on "
                        f"{str(getattr(item, 'instrument', '') or '').split()[0]} "
                        f"({getattr(item, 'timeframe', '?')}) — both sides at once is a "
                        "straddle nobody armed"
                    )
        return ""

    def _offer_cascade_add(self, candidate) -> Tuple[bool, str]:
        """Turn a blocked same-chart duplicate into one more lot on the running trade.

        The operator's rule: when the quad/dual scanners fire more than one signal in the
        SAME index and SAME timeframe, do not open a second trade at another strike — add
        a lot to the one already working. Until now the duplicate was simply discarded by
        the concurrency guard, and on a non-overlapping quad source it could instead open
        that second trade, which is the outcome the rule exists to prevent.

        Matching is deliberately strict: same base index, same timeframe, same direction.
        A different timeframe is a different idea and keeps its own trade; the opposite
        direction is a reversal, not a reinforcement.

        Everything about WHETHER to add belongs to scale_in_trade — profit, trend, add
        cap, lot ceiling, rupee budget, in-flight guard. This only decides when to ask,
        and returns its refusal so the operator can see why in the decision log.
        """
        try:
            adder = getattr(getattr(self, "trades", None), "scale_in_trade", None)
            if not callable(adder):
                return False, ""
            base = str(getattr(candidate, "instrument", "") or "").split()[0].upper()
            timeframe = str(getattr(candidate, "timeframe", "") or "")
            direction = str(getattr(candidate, "direction", "") or "").upper()
            if not base or not timeframe or direction not in {"LONG", "SHORT"}:
                return False, ""

            for trade_id, trade in list(getattr(self.trades, "open_trades", {}).items()):
                # Reconstructed session-ledger rows are inserted into open_trades with
                # status OPEN at startup, and dict order puts them AHEAD of anything
                # opened later. Every sibling guard filters them (_opposite_direction
                # _stack_block, _is_live_book_trade, _bucket_open_count,
                # _effective_max_positions) — this loop did not. Because the loop
                # RETURNS on its first match, a matching ghost consumed the single
                # cascade offer and the live position behind it was never asked, while
                # the log reported a successful add.
                if bool(getattr(trade, "is_ghost", False)):
                    continue
                if str(getattr(trade, "instrument", "") or "").split()[0].upper() != base:
                    continue
                if str(getattr(trade, "timeframe", "") or "") != timeframe:
                    continue
                if str(getattr(trade, "direction", "") or "").upper() != direction:
                    continue
                price = float(
                    getattr(trade, "current_price", 0.0)
                    or getattr(trade, "entry_price", 0.0)
                    or 0.0
                )
                ok, why = adder(trade_id, None, price, "CASCADE_ADD")
                if ok:
                    logger.success(
                        f"Cascade add: {base} {timeframe} {direction} duplicate signal "
                        f"added a lot to {getattr(trade, 'trading_symbol', trade_id)} "
                        f"instead of opening a second trade."
                    )
                    self.log_event(
                        f"Cascade add: extra lot on {base} {timeframe} {direction} "
                        "from a duplicate same-chart signal.",
                        "trade",
                    )
                return bool(ok), str(why or "")
        except Exception as exc:
            logger.debug(f"Cascade add skipped for {getattr(candidate, 'instrument', '?')}: {exc}")
        return False, ""

    def _prepare_candidate_for_concurrency(self, candidate: TradeCandidate) -> bool:
        """Per-index concurrency guard.

        Guard ON enforces cross-timeframe complementary entries. Guard OFF relaxes
        the complement rule, but still caps normal exposure at two trades per
        index; a third slot needs the rare-burst evidence gate.
        """
        guard_on = self._setting_enabled(getattr(get_settings(), "ut_concurrency_guard", True), True)

        base_inst = candidate.instrument.split()[0]
        existing = [t for t in self.trades.open_trades.values() if t.instrument.split()[0] == base_inst]
        if not existing:
            # Check manual/live session candidate signals as well for concurrency matching
            session_entries = self._active_session_entry_candidates(candidate.instrument, as_of=candidate.signal_timestamp)
            if session_entries:
                existing = session_entries

        if not existing:
            return True

        def _block(reason: str) -> bool:
            # logger + diagnostics only. Do not also log_event here: that path
            # re-counts rejects via _persist_rejected_signal_event and would
            # double-fill the Top Reject panel after mid-session restarts.
            detail = f"Concurrency Guard: blocked {candidate.instrument}; {reason}"
            logger.info(detail)
            sig_ts = getattr(candidate, "signal_timestamp", None)
            identity = "|".join(
                str(part or "")
                for part in (
                    getattr(candidate, "instrument", ""),
                    getattr(candidate, "timeframe", ""),
                    getattr(candidate, "direction", ""),
                    sig_ts.isoformat() if hasattr(sig_ts, "isoformat") else sig_ts,
                    reason,
                )
            )
            self._record_live_reject(f"Concurrency: {reason}", identity=identity)
            return False

        if bool(getattr(candidate, "missed_signal_reentry", False)):
            return _block("missed-signal re-entry allows only one active trade per index")

        # Operator rule (2026-07-10): at most ONE concurrent FUT position per
        # index — a second futures entry never stacks on a live futures book.
        if (
            str(getattr(candidate, "inst_type", "") or "").upper() == "FUT"
            and self._setting_enabled(
                getattr(get_settings(), "fut_one_position_per_index", True), True
            )
        ):
            fut_open = [
                t
                for t in existing
                if str(getattr(t, "inst_type", "") or "").upper() == "FUT"
                and not bool(getattr(t, "is_ghost", False))
            ]
            if fut_open:
                return _block("one concurrent FUT position per index (operator rule)")

        if self._is_quad_prime_raw_candidate(candidate):
            if self._quad_prime_duplicate_active(candidate, existing):
                return _block("quad-prime duplicate source/timeframe already active")
            logger.info(
                f"Concurrency Guard: quad-prime raw entry applying normal same-TF/cross-TF "
                f"complement rules for {candidate.instrument} {candidate.timeframe}."
            )

        index_cap, cap_basis = self._active_index_trade_cap(candidate, len(existing))
        if len(existing) >= index_cap:
            return _block(f"max {index_cap} concurrent trades per index ({cap_basis})")

        dual_allowed, dual_reason = self._dual_lane_concurrency_decision(candidate, existing)
        if dual_allowed is not None:
            if not dual_allowed:
                return _block(f"adaptive dual lane guard: {dual_reason}")
            logger.info(
                f"Concurrency Guard: adaptive dual lane entry allowed for "
                f"{candidate.instrument}: {dual_reason}."
            )
            return True

        opposite_block = self._opposite_direction_stack_block(candidate, existing)
        if opposite_block:
            return _block(opposite_block)

        # Cascade multi-TF stack: allow 1m+5m+15m (and dual TFs) on the same
        # index without forced FUT/OPT complement. Cap already applied above.
        settings = get_settings()
        if (
            bool(getattr(candidate, "one_way_cascade_entry", False))
            and self._setting_enabled(
                getattr(settings, "cascade_multi_tf_stack_enabled", True), True
            )
        ):
            cand_tf = str(getattr(candidate, "timeframe", "") or "")
            cand_lane = self._source_lane(candidate) or "A"
            same_slot = [
                t for t in existing
                if str(getattr(t, "timeframe", "") or "") == cand_tf
                and (self._source_lane(t) or "A") == cand_lane
            ]
            if same_slot:
                return _block(f"cascade same-TF {cand_tf} lane {cand_lane} already active")
            logger.info(
                f"Concurrency Guard: cascade multi-TF stack allows "
                f"{candidate.instrument} {cand_tf} lane {cand_lane} "
                f"({len(existing)+1}/{index_cap})."
            )
            return True

        existing_trade = existing[0]
        # UNCONDITIONAL. This test used to sit BELOW `if not guard_on: return True`, and
        # .env sets UT_CONCURRENCY_GUARD='False', so it was dead at runtime: a second
        # signal on a chart that already has a working trade opened a SECOND position at
        # another strike instead of adding a lot to the first — exactly the outcome
        # requirement 3 exists to prevent, and the case _offer_cascade_add was written
        # for. Blocking here is what routes the duplicate to the add path.
        #
        # ut_concurrency_guard still governs everything below: the cross-timeframe
        # complement rules, the grade comparison and the instrument-preference logic.
        if getattr(existing_trade, "timeframe", "") == candidate.timeframe:
            return _block("same timeframe already active")

        if not guard_on:
            return True

        if not self._candidate_quality_same_or_better(candidate, existing):
            return _block("cross-TF setup is not same grade/confidence or better")

        target_type = "OPT" if getattr(existing_trade, "inst_type", "FUT") == "FUT" else "FUT"
        if candidate.inst_type != target_type:
            inst_pref = (getattr(self, "inst_pref", "AUTO") or "AUTO").upper()
            if inst_pref in {"FUT", "OPT"} and inst_pref != target_type:
                return _block(f"fixed preference prevents {target_type} complement")
            return self._force_candidate_instrument_type(candidate, target_type)
        return True

    def _passes_correlated_index_guard(self, candidate: TradeCandidate, direction: str) -> bool:
        """Limit concentrated same-direction exposure across the core indices.

        NIFTY, BANKNIFTY and SENSEX are deliberately treated as one correlated
        risk bucket. MIDCPNIFTY remains independent, and any overflow beyond
        the normal bucket cap must come through the rare-burst evidence gate.
        """
        settings = get_settings()
        if not self._setting_enabled(getattr(settings, "ut_correlated_index_guard", True), True):
            return True

        candidate_base = str(getattr(candidate, "instrument", "") or "").split()[0].upper()
        if candidate_base not in self.CORE_CORRELATED_INDICES:
            return True

        # ut_correlated_core_limit is what this guard is FOR — "maximum simultaneous
        # same-direction NIFTY/BANKNIFTY/SENSEX exposures", set to 2. It had no consumer:
        # the limit came from _active_bucket_cap('CORE'), which answers 6 normally and 9
        # on a rare burst. Three times the configured number on the concentration control
        # that matters most as size grows, and silently, because the setting looked live.
        #
        # The bucket cap is a different quantity (total CORE positions, any direction) and
        # still applies as a ceiling; this takes the tighter of the two.
        limit = max(1, self._active_bucket_cap("CORE", candidate))
        exposures = self._correlated_same_direction_exposures(direction, bucket="CORE")
        configured = self._correlated_core_limit(candidate, exposures)
        if configured > 0:
            limit = min(limit, configured)
        if len(exposures) < limit:
            return True

        logger.info(
            f"Correlation Guard: blocked {candidate_base} {direction}; "
            f"{len(exposures)} same-direction core exposures already active (limit {limit})."
        )
        return False

    def _correlated_core_limit(self, candidate, exposures: List[Any]) -> int:
        """Configured cap on same-direction CORE exposures, 0 when unset.

        ut_correlated_allow_aplus_override describes the one documented escape: "permit a
        third core exposure only when every setup is A+". Both settings sat unread, so
        neither the limit nor its escape existed. The escape is deliberately strict —
        EVERY exposure already on, plus the incoming one, has to be A+, so one weak leg in
        the basket closes it.
        """
        settings = get_settings()
        try:
            limit = int(getattr(settings, "ut_correlated_core_limit", 0) or 0)
        except (TypeError, ValueError):
            return 0
        if limit <= 0:
            return 0
        if not Scanner._setting_enabled(
            getattr(settings, "ut_correlated_allow_aplus_override", True), True
        ):
            return limit
        grades = [str(getattr(item, "grade", "") or "").upper() for item in (exposures or [])]
        grades.append(str(getattr(candidate, "grade", "") or "").upper())
        if grades and all(g == "A+" for g in grades):
            return limit + 1
        return limit

    def _correlated_index_bucket(self, instrument: str) -> str:
        base = str(instrument or "").split()[0].upper()
        if base == self.MIDCAP_CORRELATED_INDEX:
            return "MIDCAP"
        return "CORE"

    def _active_bucket_cap(self, bucket: str, candidate=None) -> int:
        """Concurrent-position cap for a correlation bucket.

        Normal cap is 4 indices x 2 trades. A candidate can unlock the 4 x 3
        rare-burst cap only with all-index alignment, 95%+ confidence, 3.5x+
        volume, and ADX 35+ while the concurrency guard is OFF.

        Cascade multi-TF stack (R4): raise CORE/MIDCAP caps so late indices in
        a cascade wave are not starved by the normal 6/2 bucket.
        """
        s = get_settings()
        guard_on = self._setting_enabled(getattr(s, "ut_concurrency_guard", True), True)
        bucket_name = str(bucket).upper()
        if candidate is not None and not guard_on:
            rare_ok, rare_reason = self._rare_burst_context(candidate)
            if rare_ok:
                self._apply_rare_burst_fast_tracking(candidate, rare_reason)
                if bucket_name == "MIDCAP":
                    return int(getattr(s, "rare_burst_midcap_bucket_max_positions", 3) or 3)
                return int(getattr(s, "rare_burst_core_bucket_max_positions", 9) or 9)

        # Cascade-aware expansion (applies even when concurrency guard is ON)
        cascade_entry = bool(
            candidate is not None
            and getattr(candidate, "one_way_cascade_entry", False)
            and self._setting_enabled(
                getattr(s, "cascade_multi_tf_stack_enabled", True), True
            )
        )
        if bucket_name == "MIDCAP":
            base = int(
                getattr(s, "midcap_bucket_max_positions_guarded", 2)
                if guard_on
                else getattr(s, "midcap_bucket_max_positions", 2)
            )
            if cascade_entry:
                casc = max(1, int(getattr(s, "cascade_midcap_bucket_max_positions", 3) or 3))
                return max(base, casc)
            return base
        base = int(
            getattr(s, "core_bucket_max_positions_guarded", 6)
            if guard_on
            else getattr(s, "core_bucket_max_positions", 6)
        )
        if cascade_entry:
            casc = max(1, int(getattr(s, "cascade_core_bucket_max_positions", 12) or 12))
            return max(base, casc)
        return base

    def _bucket_open_count(self, bucket: str) -> int:
        """Live (non-ghost) open trades currently in a correlation bucket."""
        return sum(
            1 for t in getattr(self.trades, "open_trades", {}).values()
            if not getattr(t, "is_ghost", False)
            and self._correlated_index_bucket(getattr(t, "instrument", "")) == bucket
        )

    def _bucket_capacity_allows(self, candidate) -> bool:
        """True while the candidate's bucket is below its (guard-dependent) concurrent cap.
        This is what makes total capacity 8 normally and 12 only in rare burst mode."""
        bucket = self._correlated_index_bucket(getattr(candidate, "instrument", ""))
        return self._bucket_open_count(bucket) < self._active_bucket_cap(bucket, candidate)

    def _correlated_same_direction_exposures(self, direction: str, bucket: Optional[str] = None) -> List[Any]:
        """Return unique active/session entry exposures for a direction and bucket."""
        seen: Dict[Tuple[str, str, str], Any] = {}

        def add_exposure(obj):
            if str(getattr(obj, "direction", "") or "").upper() != str(direction or "").upper():
                return
            instrument = str(getattr(obj, "instrument", "") or "").split()[0].upper()
            timeframe = str(getattr(obj, "timeframe", "") or "")
            key = (instrument, timeframe, str(getattr(obj, "inst_type", "") or ""))
            if bucket is None or self._correlated_index_bucket(instrument) == bucket:
                seen[key] = obj

        for trade in getattr(self.trades, "open_trades", {}).values():
            add_exposure(trade)

        if getattr(self, "mode", "") != "HISTORICAL":
            for instrument in getattr(self, "active_indices", []) or []:
                for row in self._active_session_entry_candidates(instrument):
                    add_exposure(row)

        return list(seen.values())

    def _correlated_same_direction_counts(self, direction: str) -> Tuple[int, int]:
        """Count active same-direction exposures, including manual session candidates."""
        return (
            len(self._correlated_same_direction_exposures(direction, bucket="CORE")),
            len(self._correlated_same_direction_exposures(direction, bucket="MIDCAP")),
        )

    def _select_correlated_batch(self, signals: List[TradeCandidate], direction: str) -> Tuple[List[TradeCandidate], List[TradeCandidate]]:
        """Preserve every simultaneous signal for independent eligibility checks."""
        return list(signals), []

    async def _process_instrument_async(self, name: str, cfg: Dict) -> Tuple[str, Dict]:
        """Async version of instrument processing for ultra-low latency"""
        try:
            # 1. Fetch Price & Update Candle State (I/O Bound)
            token = cfg.get("token", "")
            exchange = cfg.get("exchange", "NSE")

            # Fetch LTP directly from SmartAPI (Fast)
            spot = self.data.get_ltp(exchange, name, token)
            if spot and spot > 0:
                self.candles.update_latest_price(name, spot)

            # 2. Run Analysis Pipeline (Using cached data)
            ui_data, candidate = self._process_instrument(name, cfg)
            return name, (ui_data, candidate)
        except Exception as e:
            logger.error(f"â Œ Async error for {name}: {e}")
            return name, ({}, [])

    # â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â•
    # BEST SIGNAL SELECTION — across 5m and 15m TFs
    # â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â• â•
    # ====================================================================
    # LIVE/HISTORICAL PARITY HELPERS
    # --------------------------------------------------------------------
    # The historical backfill path used to call _grade_signal with
    # hardcoded confluence=0.5, intel=0.0 and a date-only VIX key (which
    # never matched the minute-level vix_history.json). That made backtest
    # grades drift from live for the same setup. These helpers reproduce
    # the live grading inputs as faithfully as the available data allows:
    #   * intel.analyze() runs on candles sliced at the signal timestamp
    #     (volume/regime/order-flow always recomputable; OI/PCR/Greeks
    #     degrade gracefully when historical option chain is unavailable
    #     -- exactly like the live aggregator's None-chain path)
    #   * confluence is reconstructed from each TF's signals up to ts
    #     using the same MTF weights as MultiTimeframeEngine
    #   * VIX uses the same minute key shape as the live path with a
    #     same-day fallback so older signals get a real reading instead of
    #     the 15.0 sentinel.
    # ====================================================================
    def _get_historical_vix(self, ts) -> float:
        """Resolve VIX at a historical timestamp.

        1) Exact minute key '%Y-%m-%d %H:%M:00' (matches vix_history.json)
        2) Latest minute on same date <= ts; else earliest of that date
        3) Fallback 15.0
        """
        if not isinstance(self._vix_data, dict) or not self._vix_data:
            return 15.0
        try:
            minute_key = ts.strftime("%Y-%m-%d %H:%M:00")
        except Exception:
            return 15.0
        cache = getattr(self, "_historical_vix_cache", None)
        if not isinstance(cache, dict):
            self._historical_vix_cache = {}
            cache = self._historical_vix_cache
        if minute_key in cache:
            return float(cache[minute_key])
        v = self._vix_data.get(minute_key)
        if v is not None:
            try:
                vf = float(v)
                if vf > 0:
                    cache[minute_key] = vf
                    return vf
            except Exception:
                pass
        date_prefix = ts.strftime("%Y-%m-%d ")
        try:
            ts_str = ts.strftime("%Y-%m-%d %H:%M:%S")
            day_cache = getattr(self, "_historical_vix_day_cache", None)
            if not isinstance(day_cache, dict):
                self._historical_vix_day_cache = {}
                day_cache = self._historical_vix_day_cache
            same_day = day_cache.get(date_prefix)
            if same_day is None:
                same_day = [
                    (k, val)
                    for k, val in self._vix_data.items()
                    if isinstance(k, str) and k.startswith(date_prefix)
                ]
                same_day.sort(key=lambda item: item[0])
                day_cache[date_prefix] = same_day
            if same_day:
                before = [(k, val) for k, val in same_day if k <= ts_str]
                if before:
                    _, val = before[-1]
                else:
                    _, val = same_day[0]
                vf = float(val)
                if vf > 0:
                    cache[minute_key] = vf
                    return vf
        except Exception:
            pass
        cache[minute_key] = 15.0
        return 15.0

    def _vix_percentile(self, value: float, as_of: Optional[datetime] = None) -> Optional[float]:
        """Empirical India VIX percentile using one closing observation per prior session."""
        try:
            value = float(value)
        except (TypeError, ValueError):
            return None
        if value <= 0 or not isinstance(self._vix_data, dict):
            return None
        daily_values: Dict[str, Tuple[str, float]] = {}
        as_of_ist = None
        if as_of is not None:
            as_of_ist = IST.localize(as_of) if as_of.tzinfo is None else as_of.astimezone(IST)
        cache_key = f"{round(value, 3)}|{as_of_ist.date().isoformat() if as_of_ist else ''}"
        pct_cache = getattr(self, "_vix_percentile_cache", None)
        if not isinstance(pct_cache, dict):
            self._vix_percentile_cache = {}
            pct_cache = self._vix_percentile_cache
        if cache_key in pct_cache:
            return pct_cache[cache_key]
        for key, raw in self._vix_data.items():
            try:
                ts = datetime.strptime(str(key), "%Y-%m-%d %H:%M:%S")
                ts = IST.localize(ts)
                # Daily VIX rows are timestamped at midnight but contain that
                # session's close. Exclude the entire current session to avoid
                # look-ahead in historical routing.
                if as_of_ist is not None and ts.date() >= as_of_ist.date():
                    continue
                parsed = float(raw)
                if parsed <= 0:
                    continue
                day_key = ts.date().isoformat()
                prior = daily_values.get(day_key)
                if prior is None or str(key) > prior[0]:
                    daily_values[day_key] = (str(key), parsed)
            except (TypeError, ValueError):
                continue
        values = [item[1] for item in daily_values.values()]
        minimum = max(
            5,
            int(getattr(get_settings(), "vix_percentile_min_sessions", 20) or 20),
        )
        if len(values) < minimum:
            pct_cache[cache_key] = None
            return None
        less_or_equal = sum(1 for item in values if item <= value)
        percentile = round(less_or_equal / len(values) * 100.0, 1)
        pct_cache[cache_key] = percentile
        return percentile

    def _instrument_iv_observations(
        self, instrument: str, as_of: Optional[datetime] = None
    ) -> List[float]:
        """Return this instrument's prior-session ATM IV values (look-ahead-safe).

        Only sessions strictly before ``as_of`` are returned so historical and
        live routing share the same no-look-ahead semantics as the VIX path.
        """
        data = getattr(self, "_instrument_iv_data", None)
        if not isinstance(data, dict):
            return []
        rows = data.get(str(instrument or "").upper())
        if not isinstance(rows, dict) or not rows:
            return []
        cutoff = None
        if as_of is not None:
            as_of_ist = IST.localize(as_of) if as_of.tzinfo is None else as_of.astimezone(IST)
            cutoff = as_of_ist.date()
        observations: List[float] = []
        for day_key, value in rows.items():
            try:
                if cutoff is not None and datetime.strptime(str(day_key), "%Y-%m-%d").date() >= cutoff:
                    continue
                parsed = float(value)
            except (TypeError, ValueError):
                continue
            if parsed > 0:
                observations.append(parsed)
        return observations

    def _record_instrument_iv(
        self, instrument: str, intel_result: Dict[str, Any], as_of: Optional[datetime] = None
    ) -> None:
        """Persist one real ATM-IV observation per session for IV-Rank history."""
        if self.mode == "HISTORICAL":
            return
        greeks = intel_result.get("greeks", {}) if isinstance(intel_result, dict) else {}
        if not isinstance(greeks, dict):
            return
        iv_value = greeks.get("instrument_iv")
        basis = str(greeks.get("iv_source", ""))
        if iv_value is None or basis.startswith("default"):
            return
        try:
            iv_value = float(iv_value)
        except (TypeError, ValueError):
            return
        if iv_value <= 0:
            return
        key = str(instrument or "").upper()
        if not key:
            return
        as_of = as_of or datetime.now(IST)
        day_key = (
            as_of.astimezone(IST) if as_of.tzinfo else IST.localize(as_of)
        ).date().isoformat()
        data = self._instrument_iv_data.setdefault(key, {})
        data[day_key] = round(iv_value, 2)
        self._persist_instrument_iv_history()

    def _persist_instrument_iv_history(self) -> None:
        now = time.monotonic()
        if now - float(getattr(self, "_last_instrument_iv_save", 0.0) or 0.0) < 60.0:
            return
        self._last_instrument_iv_save = now
        path = Path("data_store/instrument_iv_history.json")
        temp = path.with_suffix(".json.tmp")
        try:
            temp.write_text(json.dumps(self._instrument_iv_data, indent=2), encoding="utf-8")
            temp.replace(path)
        except Exception as exc:
            logger.debug(f"Instrument IV history persistence skipped: {exc}")

    def _persist_vix_history(self) -> None:
        now = time.monotonic()
        if now - float(getattr(self, "_last_vix_history_save", 0.0) or 0.0) < 60.0:
            return
        self._last_vix_history_save = now
        path = Path("data_store/vix_history.json")
        temp = path.with_suffix(".json.tmp")
        try:
            temp.write_text(json.dumps(self._vix_data, indent=2), encoding="utf-8")
            temp.replace(path)
        except Exception as exc:
            logger.debug(f"India VIX history persistence skipped: {exc}")

    def _get_live_volatility_context(self) -> Dict[str, Any]:
        settings = get_settings()
        ttl = max(15.0, float(getattr(settings, "vix_live_cache_seconds", 60.0) or 60.0))
        cached = self._premium_cache.get("INDIAVIX") if hasattr(self, "_premium_cache") else None
        value = 0.0
        if cached and time.time() - float(cached.get("time", 0.0) or 0.0) <= ttl:
            value = float(cached.get("price", 0.0) or 0.0)
        if value <= 0:
            try:
                value = float(self.data.get_ltp("NSE", "INDIAVIX", "99926017") or 0.0)
            except Exception as exc:
                logger.debug(f"India VIX live fetch failed: {exc}")
                value = 0.0
        if value > 0:
            self._premium_cache["INDIAVIX"] = {"price": value, "time": time.time()}
            key = datetime.now(IST).strftime("%Y-%m-%d %H:%M:00")
            self._vix_data[key] = value
            self._persist_vix_history()
        percentile = self._vix_percentile(value, datetime.now(IST)) if value > 0 else None
        return {
            "value": value if value > 0 else None,
            "percentile": percentile,
            "source": "india_vix_daily_percentile" if percentile is not None else "india_vix_insufficient_history",
        }

    def _historical_day_type_at(self, instrument: str, ts, tf: str = "5min") -> Tuple[str, float]:
        """At-timestamp (day_type, confidence) for historical grading parity.
        Triggers the intel computation when not cached yet."""
        try:
            ts_key = ts.isoformat() if hasattr(ts, "isoformat") else str(ts)
        except Exception:
            ts_key = str(ts)
        cache_key = (
            int(getattr(self, "simulation_id", 0) or 0),
            str(instrument or "").upper(),
            str(tf or "5min"),
            ts_key,
        )
        day_cache = getattr(self, "_historical_day_type_cache", None)
        if not isinstance(day_cache, dict) or cache_key not in day_cache:
            try:
                self._compute_historical_intel_at(instrument, ts, tf)
            except Exception:
                pass
            day_cache = getattr(self, "_historical_day_type_cache", {}) or {}
        value = day_cache.get(cache_key)
        if isinstance(value, tuple) and len(value) == 2:
            return str(value[0] or ""), float(value[1] or 0.0)
        return "", 0.0

    def _compute_historical_intel_at(self, instrument: str, ts, tf: str = "5min"):
        """Recompute intelligence score and regime at a historical timestamp.

        Slices cached candles to ``ts`` and runs the same
        ``IntelligenceAggregator.analyze`` used by the live path with
        ``options_chain=None``. Returns ``(intel_score in [-1,1], regime_str)``.
        On any failure returns ``(0.0, 'UNKNOWN')``.
        """
        try:
            ts_key = ts.isoformat() if hasattr(ts, "isoformat") else str(ts)
        except Exception:
            ts_key = str(ts)
        cache_key = (
            int(getattr(self, "simulation_id", 0) or 0),
            str(instrument or "").upper(),
            str(tf or "5min"),
            ts_key,
        )
        cache = getattr(self, "_historical_intel_at_cache", None)
        if not isinstance(cache, dict):
            self._historical_intel_at_cache = {}
            cache = self._historical_intel_at_cache
        if cache_key in cache:
            return cache[cache_key]

        def _slice_to(frame, cutoff):
            try:
                if getattr(frame.index, "is_monotonic_increasing", False):
                    return frame.loc[:cutoff]
            except Exception:
                pass
            return frame[frame.index <= cutoff]

        try:
            df_5m = self.candles.get_candles(instrument, "5min")
            df_1m = self.candles.get_candles(instrument, "1min")
            if df_5m is None or df_5m.empty:
                cache[cache_key] = (0.0, "UNKNOWN")
                return 0.0, "UNKNOWN"
            sub_5m = _slice_to(df_5m, ts)
            sub_1m = None
            if df_1m is not None and not df_1m.empty:
                sub_1m = _slice_to(df_1m, ts)
                if sub_1m.empty:
                    sub_1m = None
            if sub_5m.empty:
                cache[cache_key] = (0.0, "UNKNOWN")
                return 0.0, "UNKNOWN"
            spot = float(sub_5m["close"].iloc[-1])
            try:
                o = float(sub_5m["open"].iloc[-1])
                pct = ((spot - o) / o) * 100.0 if o > 0 else 0.0
            except Exception:
                pct = 0.0
            previous_close = self._previous_close_at(instrument, sub_5m, ts) or float(sub_5m["open"].iloc[0])
            if previous_close > 0:
                pct = ((spot - previous_close) / previous_close) * 100.0
            hist_vix = self._get_historical_vix(ts)
            hist_vix_percentile = self._vix_percentile(hist_vix, ts)
            contexts = self._build_intelligence_contexts(
                instrument,
                sub_5m,
                spot=spot,
                previous_close=previous_close,
                volatility_context={"value": hist_vix, "percentile": hist_vix_percentile},
                as_of=ts,
            )
            # Stash the at-timestamp day-type so historical grading can apply the
            # same range-day regime-pillar damp as live, without look-ahead.
            _hist_session_ctx = contexts.get("session_context", {}) or {}
            day_cache = getattr(self, "_historical_day_type_cache", None)
            if not isinstance(day_cache, dict):
                self._historical_day_type_cache = {}
                day_cache = self._historical_day_type_cache
            day_cache[cache_key] = (
                str(_hist_session_ctx.get("day_type") or ""),
                float(_hist_session_ctx.get("confidence") or 0.0),
            )
            if len(day_cache) > 8192:
                day_cache.clear()
            intel_res = self.intel.analyze(
                instrument=instrument,
                timeframe=tf,
                candle_df=sub_5m,
                candle_1min_df=sub_1m,
                options_chain=None,
                spot_price=spot,
                strike_interval=50,
                days_to_expiry=self._days_to_expiry_for(instrument, ts),
                price_change_pct=pct,
                chain_quality=None,
                volatility_value=hist_vix,
                volatility_percentile=hist_vix_percentile,
                volatility_source="india_vix_daily_percentile" if hist_vix_percentile is not None else "india_vix_insufficient_history",
                session_context=contexts.get("session_context"),
                anchor_regime=contexts.get("anchor_regime"),
                breadth_context=contexts.get("breadth_context"),
            )
            agg = intel_res.get("aggregate", {}) if isinstance(intel_res, dict) else {}
            intel_score = aggregate_intelligence_score(agg)
            regime = (intel_res.get("regime", {}) or {}).get("regime", "UNKNOWN")
            result = (intel_score, regime)
            cache[cache_key] = result
            return result
        except Exception as exc:
            logger.debug(f"_compute_historical_intel_at failed for {instrument} @ {ts}: {exc}")
            cache[cache_key] = (0.0, "UNKNOWN")
            return 0.0, "UNKNOWN"

    def _compute_historical_confluence_at(self, mtf_result, ts) -> float:
        """Reconstruct MTF confluence score at a historical timestamp.

        For each TF, finds the most recent signal flip <= ``ts`` and applies
        the same weights as ``MultiTimeframeEngine._compute_confluence``.
        Returns float in [-1.0, +1.0].
        """
        if mtf_result is None:
            return 0.0
        tf_weights = getattr(self.mtf, "tf_weights", {"1min": 0.15, "5min": 0.40, "15min": 0.45})

        def _naive(t):
            try:
                return t.replace(tzinfo=None) if getattr(t, "tzinfo", None) else t
            except Exception:
                return t

        naive_ts = _naive(ts)
        cache_key = (
            int(getattr(self, "simulation_id", 0) or 0),
            id(mtf_result),
            str(naive_ts),
        )
        result_cache = getattr(self, "_historical_confluence_at_cache", None)
        if not isinstance(result_cache, dict):
            self._historical_confluence_at_cache = {}
            result_cache = self._historical_confluence_at_cache
        if cache_key in result_cache:
            return float(result_cache[cache_key])

        index_cache = getattr(self, "_historical_confluence_index_cache", None)
        if not isinstance(index_cache, dict):
            self._historical_confluence_index_cache = {}
            index_cache = self._historical_confluence_index_cache
        score = 0.0
        total_weight = 0.0
        for tf, weight in tf_weights.items():
            if tf == "1min":
                res = getattr(mtf_result, "results_1min", None)
            elif tf == "5min":
                res = getattr(mtf_result, "results_5min", None)
            elif tf == "15min":
                res = getattr(mtf_result, "results_15min", None)
            else:
                res = None
            if not res:
                continue
            sigs = res.get("signals", []) or []
            index_key = (int(getattr(self, "simulation_id", 0) or 0), id(mtf_result), str(tf))
            timeline = index_cache.get(index_key)
            if timeline is None:
                pairs = []
                for signal in sigs:
                    signal_ts = _naive(signal.timestamp)
                    pos = 1 if signal.signal_type == "BUY" else (-1 if signal.signal_type == "SELL" else 0)
                    pairs.append((signal_ts, pos))
                pairs.sort(key=lambda item: item[0])
                timeline = ([item[0] for item in pairs], [item[1] for item in pairs])
                index_cache[index_key] = timeline
            times, positions = timeline
            if not times:
                continue
            try:
                idx = bisect.bisect_right(times, naive_ts) - 1
            except TypeError:
                idx = -1
                for i, signal_ts in enumerate(times):
                    if signal_ts <= naive_ts:
                        idx = i
                    else:
                        break
            if idx < 0:
                continue
            pos = positions[idx]
            score += pos * weight
            total_weight += weight
        if total_weight > 0:
            score = score / total_weight
        result = round(max(-1.0, min(1.0, score)), 3)
        result_cache[cache_key] = result
        return result

    @staticmethod
    def _historical_15m_trend_agrees(mtf_result, ts, direction: str) -> bool:
        """Resolve the latest 15m signal state available at a historical timestamp."""
        result = getattr(mtf_result, "results_15min", None) or {}
        signals = result.get("signals", []) or []
        if not signals:
            return False
        naive_ts = ts.replace(tzinfo=None) if getattr(ts, "tzinfo", None) else ts
        prior = []
        for signal in signals:
            signal_ts = signal.timestamp.replace(tzinfo=None) if getattr(signal.timestamp, "tzinfo", None) else signal.timestamp
            if signal_ts <= naive_ts:
                prior.append(signal)
        if not prior:
            return False
        latest = max(
            prior,
            key=lambda signal: signal.timestamp.replace(tzinfo=None)
            if getattr(signal.timestamp, "tzinfo", None)
            else signal.timestamp,
        )
        expected = "BUY" if str(direction or "").upper() == "LONG" else "SELL"
        return str(getattr(latest, "signal_type", "") or "").upper() == expected

    def _multi_signal_mixed_book_trigger(self, candidates: List[TradeCandidate]) -> bool:
        """True when dual-engine / multi-TF / multi-index wave should use 1-FUT + rest-OPT."""
        settings = get_settings()
        if not self._setting_enabled(
            getattr(settings, "multi_signal_mixed_book_enabled", True), True
        ):
            return False
        if not candidates:
            return False
        pref = str(getattr(self, "inst_pref", "AUTO") or "AUTO").upper()

        instruments = {
            str(getattr(c, "instrument", "") or "").split()[0].upper()
            for c in candidates
            if getattr(c, "action", "ENTRY") == "ENTRY"
        }
        timeframes = {
            str(getattr(c, "timeframe", "") or "")
            for c in candidates
            if getattr(c, "action", "ENTRY") == "ENTRY"
        }
        engines: set = set()
        for c in candidates:
            eng = str(getattr(c, "source_engine", "") or "").strip()
            if eng:
                engines.add(eng)
            for e in list(getattr(c, "source_engines", None) or []):
                if e:
                    engines.add(str(e))
            lane = str(getattr(c, "source_lane", "") or "").strip()
            if lane:
                engines.add(f"lane:{lane}")

        min_inst = max(2, int(getattr(settings, "multi_signal_min_instruments", 3) or 3))
        min_tf = max(2, int(getattr(settings, "multi_signal_min_timeframes", 2) or 2))
        min_eng = max(2, int(getattr(settings, "multi_signal_min_engines", 2) or 2))
        if len(instruments) >= min_inst:
            return True
        if len(instruments) >= 2 and len(timeframes) >= min_tf:
            return True
        if len(instruments) >= 2 and len(engines) >= min_eng:
            return True
        # Explicit cascade / multi-index thrust also qualifies
        if any(bool(getattr(c, "one_way_cascade_entry", False)) for c in candidates) and len(instruments) >= 2:
            return True
        return False

    def _candidate_rank_score(self, candidate: TradeCandidate) -> float:
        conf = float(getattr(candidate, "confidence", 0.0) or 0.0)
        grade = str(getattr(candidate, "grade", "") or "").split()[0]
        grade_bonus = {"A+": 0.08, "A": 0.05, "B+": 0.02, "B": 0.0}.get(grade, -0.05)
        tf = str(getattr(candidate, "timeframe", "") or "")
        tf_bonus = {"15min": 0.03, "5min": 0.01, "1min": -0.02}.get(tf, 0.0)
        return conf + grade_bonus + tf_bonus

    def _strict_instrument_pref(self) -> str:
        """Return FUT / OPT / AUTO from scanner+settings (operator product lock)."""
        return str(
            getattr(self, "inst_pref", None)
            or getattr(get_settings(), "inst_pref", "AUTO")
            or "AUTO"
        ).upper()

    def _resolve_unbuilt_opt_entries(
        self, candidates: List[TradeCandidate]
    ) -> List[TradeCandidate]:
        """Convert-or-drop ENTRY candidates claiming OPT without a real contract.

        Rare dual-TF sibling clones can flip a FUT winner's copy to
        inst_type=OPT while the futures symbol/token/levels are still attached.
        A hybrid like that must NEVER book or execute: its premium math would
        read the future's LTP. Convert properly (strike/premium/symbol) via
        _force_candidate_to_options, else reject the row.
        """
        kept: List[TradeCandidate] = []
        for c in list(candidates or []):
            if (
                str(getattr(c, "action", "ENTRY") or "ENTRY").upper() == "ENTRY"
                and str(getattr(c, "inst_type", "") or "").upper() == "OPT"
            ):
                sym = str(getattr(c, "trading_symbol", "") or "").upper()
                looks_option = sym.endswith("CE") or sym.endswith("PE")
                if float(getattr(c, "atm_strike", 0.0) or 0.0) <= 0 or not looks_option:
                    if not self._force_candidate_to_options(c):
                        try:
                            c.status = "REJECTED - OPT Contract Unresolved"
                            c.reasons = list(c.reasons or []) + [
                                "OPT candidate lacked a resolved option contract and conversion failed"
                            ]
                        except Exception:
                            pass
                        logger.warning(
                            f"OPT safety net dropped {getattr(c, 'instrument', '')} "
                            f"{getattr(c, 'timeframe', '')}: unresolved option contract "
                            f"(symbol={sym or 'none'})."
                        )
                        continue
            kept.append(c)
        return kept

    def _apply_strict_instrument_pref_to_entries(
        self, candidates: List[TradeCandidate]
    ) -> List[TradeCandidate]:
        """Rewrite/drop ENTRY candidates so product matches FUT-only or OPT-only.

        AUTO is a no-op. Used after mixed-book and for single-signal waves so no
        path can book the opposite product under a locked preference.
        """
        pref = self._strict_instrument_pref()
        if pref not in {"FUT", "OPT"} or not candidates:
            return candidates
        kept: List[TradeCandidate] = []
        for c in candidates:
            if str(getattr(c, "action", "ENTRY") or "ENTRY").upper() != "ENTRY":
                kept.append(c)
                continue
            ok, why = self._enforce_strict_instrument_pref_on_candidate(c)
            if ok:
                kept.append(c)
            else:
                try:
                    c.status = f"REJECTED - {pref} PREF ({why})"
                    c.reasons = list(c.reasons or []) + [
                        f"Strict instrument preference {pref}: {why}"
                    ]
                except Exception:
                    pass
                logger.info(
                    f"Strict pref {pref} dropped {getattr(c, 'instrument', '')} "
                    f"{getattr(c, 'timeframe', '')}: {why}"
                )
        return kept

    def _futures_blocked_for_index(self, instrument: str, *, for_auto_router: bool = True) -> bool:
        """AUTO-router futures blacklist (e.g. MIDCP).

        Explicit operator FUT-only is an override: never treat an index as
        futures-blocked when inst_pref is FUT. OPT-only never needs this gate.
        """
        pref = self._strict_instrument_pref()
        if pref == "FUT":
            # Operator demanded futures-only — do not soft-skip indices.
            return False
        if pref == "OPT":
            return True  # never select FUT under options-only
        if not for_auto_router:
            return False
        blocked = {
            str(item or "").upper()
            for item in (getattr(get_settings(), "auto_futures_blocked_indices", []) or [])
        }
        return str(instrument or "").split()[0].upper() in blocked

    def _resolve_futures_contract_fields(self, instrument: str, candidate: Optional[TradeCandidate] = None) -> Tuple[str, str]:
        """Best-effort futures symbol/token for strict FUT conversion."""
        inst = str(instrument or "").split()[0]
        info = (getattr(self, "market_info", {}) or {}).get(inst, {}) or {}
        trading_symbol = str(info.get("current_fut") or "").strip()
        symbol_token = str(info.get("current_fut_token") or "").strip()
        if candidate is not None and str(getattr(candidate, "inst_type", "") or "").upper() == "FUT":
            if not trading_symbol:
                trading_symbol = str(getattr(candidate, "trading_symbol", "") or "").strip()
            if not symbol_token:
                symbol_token = str(getattr(candidate, "symbol_token", "") or "").strip()
        # Optional provider helper when pre-market map is incomplete mid-session.
        if (not trading_symbol or not symbol_token) and getattr(self, "data", None) is not None:
            resolver = getattr(self.data, "get_futures_contract", None) or getattr(
                self.data, "resolve_futures_token", None
            )
            if callable(resolver):
                try:
                    resolved = resolver(inst) or {}
                    if isinstance(resolved, dict):
                        trading_symbol = trading_symbol or str(
                            resolved.get("symbol") or resolved.get("trading_symbol") or ""
                        ).strip()
                        symbol_token = symbol_token or str(
                            resolved.get("token") or resolved.get("symbol_token") or ""
                        ).strip()
                except Exception:
                    pass
        return trading_symbol, symbol_token

    def _force_candidate_to_futures_1lot(self, candidate: TradeCandidate) -> bool:
        """Convert candidate to a single-lot futures book (multi-signal mixed book)."""
        instrument = str(getattr(candidate, "instrument", "") or "").split()[0]
        pref = self._strict_instrument_pref()
        # Only AUTO hybrid router may refuse futures on blacklisted indices.
        if pref != "FUT" and self._futures_blocked_for_index(instrument, for_auto_router=True):
            return False
        trading_symbol, symbol_token = self._resolve_futures_contract_fields(instrument, candidate)
        if not trading_symbol or not symbol_token:
            if str(getattr(candidate, "inst_type", "") or "").upper() != "FUT":
                logger.warning(
                    f"FUT conversion failed for {instrument}: missing futures symbol/token "
                    f"(pref={pref}). Candidate rejected rather than flipped to OPT."
                )
                return False

        settings = get_settings()
        fut_lots = max(1, int(getattr(settings, "multi_signal_fut_lots", 1) or 1))
        # Operator rule (2026-07-10): futures are ALWAYS capped at the hard cap
        # (default 1 lot) no matter which path builds the contract.
        fut_lots = min(fut_lots, max(1, int(getattr(settings, "fut_lots_hard_cap", 1) or 1)))
        spot = float(
            getattr(candidate, "entry_spot", 0.0)
            or getattr(candidate, "price", 0.0)
            or 0.0
        )
        try:
            live_spot = float(self.candles.get_latest_price(instrument) or 0.0)
            if live_spot > 0:
                spot = live_spot
        except Exception:
            pass

        direction = str(getattr(candidate, "direction", "LONG") or "LONG").upper()
        # Prefer live futures LTP when available
        price = float(getattr(candidate, "price", 0.0) or 0.0)
        if str(getattr(candidate, "inst_type", "") or "").upper() == "FUT" and price > 0:
            pass
        else:
            price = spot if spot > 0 else price
        # Try broker LTP on the futures contract for a better entry mark.
        if trading_symbol and symbol_token and getattr(self, "data", None) is not None:
            try:
                cfg = (self.config.get("indices", {}) or {}).get(instrument, {})
                exchange = cfg.get("exchange", "BFO" if instrument == "SENSEX" else "NFO")
                fut_ltp = float(self.data.get_ltp(exchange, trading_symbol, symbol_token) or 0.0)
                if fut_ltp > 0:
                    price = fut_ltp
            except Exception:
                pass
        if price <= 0:
            logger.warning(f"FUT conversion failed for {instrument}: no usable futures price.")
            return False

        fut_sl_pct = float(getattr(self, "futures_sl_pct", 0.1) or 0.1)
        try:
            from engine.market_regime import futures_stop_tolerance_pct

            fut_sl_pct = futures_stop_tolerance_pct(
                fut_sl_pct,
                getattr(candidate, "market_regime", "") or self.latest_regimes.get(instrument, "UNKNOWN"),
            )
        except Exception:
            pass
        stop_dist = max(price * (fut_sl_pct / 100.0), 1.0)
        rr = float(getattr(candidate, "rr", 1.5) or 1.5)
        if direction == "LONG":
            stop = price - stop_dist
            target = price + stop_dist * rr
        else:
            stop = price + stop_dist
            target = price - stop_dist * rr

        candidate.inst_type = "FUT"
        candidate.option_type = ""
        candidate.atm_strike = 0.0
        candidate.multiplier = 1.0
        candidate.lots = fut_lots
        candidate.price = float(price)
        candidate.stop = float(stop)
        candidate.target = float(target)
        candidate.initial_stop = float(stop)
        if trading_symbol:
            candidate.trading_symbol = trading_symbol
        if symbol_token:
            candidate.symbol_token = symbol_token
        candidate.entry_spot = float(spot or price)
        try:
            role = "FUT-only preference" if pref == "FUT" else "sole FUT slot"
            candidate.reasons = list(candidate.reasons or []) + [
                f"Multi-signal mixed book: {role} ({fut_lots} lot)"
            ]
        except Exception:
            pass
        setattr(candidate, "multi_signal_mixed_book_role", "FUT")
        return True

    def _force_candidate_to_options(self, candidate: TradeCandidate) -> bool:
        """Convert candidate to options; CE/PE/TF stay direction/engine driven."""
        # Symmetric instrument-lock guard (mirrors _force_candidate_to_futures_1lot's
        # OPT refusal at 20411): never build an options leg under a FUT-only lock, so
        # the FUT invariant holds structurally instead of relying on caller discipline.
        if self._strict_instrument_pref() == "FUT":
            return False
        instrument = str(getattr(candidate, "instrument", "") or "").split()[0]
        direction = str(getattr(candidate, "direction", "LONG") or "LONG").upper()
        option_type = "CE" if direction == "LONG" else "PE"
        # Preserve engine-chosen option side if already set coherently
        existing_ot = str(getattr(candidate, "option_type", "") or "").upper()
        if existing_ot in {"CE", "PE"}:
            option_type = existing_ot

        cfg = (self.config.get("indices", {}) or {}).get(instrument, {})
        strike_interval = float(cfg.get("strike_interval", 50) or 50)
        spot = float(getattr(candidate, "entry_spot", 0.0) or 0.0)
        try:
            live_spot = float(self.candles.get_latest_price(instrument) or 0.0)
            if live_spot > 0:
                spot = live_spot
        except Exception:
            pass
        # No `or candidate.price` fallback: that is the contract price, not an index
        # level, and rounding it into a strike buys the wrong contract.
        if spot <= 0:
            return False

        strike = float(getattr(candidate, "atm_strike", 0.0) or 0.0)
        if strike <= 0:
            strike = round(spot / strike_interval) * strike_interval

        trading_symbol = str(getattr(candidate, "trading_symbol", "") or "")
        symbol_token = str(getattr(candidate, "symbol_token", "") or "")
        need_lookup = (
            str(getattr(candidate, "inst_type", "") or "").upper() != "OPT"
            or not symbol_token
            or existing_ot not in {"CE", "PE"}
        )
        if need_lookup:
            try:
                opt_info = self.data.get_option_token(instrument, strike, option_type)
            except Exception:
                opt_info = None
            if not opt_info:
                return False
            trading_symbol = str(opt_info.get("symbol") or "")
            symbol_token = str(opt_info.get("token") or "")
        if not symbol_token:
            return False

        premium = float(getattr(candidate, "price", 0.0) or 0.0)
        if str(getattr(candidate, "inst_type", "") or "").upper() != "OPT" or premium <= 0 or premium > spot * 0.15:
            # Re-mark premium from live LTP
            try:
                exchange = "BFO" if instrument == "SENSEX" else "NFO"
                ltp = float(
                    self.data.get_ltp(exchange, trading_symbol, symbol_token) or 0.0
                )
                if ltp > 0:
                    premium = ltp
            except Exception:
                pass
        if premium <= 0:
            premium = max(5.0, spot * 0.012)

        settings = get_settings()
        opt_sl = float(getattr(self, "options_sl_pct", 15.0) or 15.0)
        if bool(getattr(candidate, "one_way_cascade_entry", False)):
            opt_sl = float(getattr(settings, "one_way_cascade_options_sl_pct", opt_sl) or opt_sl)
        max_sl = max(0.5, premium * (opt_sl / 100.0))
        rr = float(getattr(candidate, "rr", 1.5) or 1.5)
        stop = max(0.05, premium - max_sl)
        target = premium + max_sl * rr

        # Lots: 1× settings default; cascade OPT 2–3×; heavy-trend OPT 2× only
        base_lots = max(1, int((getattr(self, "user_lots", {}) or {}).get(instrument, 1) or 1))
        cascade_on = bool(getattr(candidate, "one_way_cascade_entry", False))
        heavy_on = False
        if not cascade_on:
            try:
                heavy_on = bool(
                    self._heavy_trend_lot_scale_eligible(
                        instrument,
                        str(getattr(candidate, "direction", "") or ""),
                        str(getattr(candidate, "timeframe", "") or ""),
                    )
                )
            except Exception:
                heavy_on = False
        if cascade_on or heavy_on:
            from engine.position_sizing import resolve_trade_lots

            sized = resolve_trade_lots(
                settings=settings,
                inst_type="OPT",
                requested_lots=base_lots,
                lot_size=int(getattr(candidate, "lot_size", 1) or 1),
                entry_price=premium,
                stop_price=stop,
                cascade_scale=cascade_on,
                heavy_trend_scale=heavy_on and not cascade_on,
                # The compression cap is position_sizing's stated FINAL safety invariant:
                # "a quiet locked session is never enlarged by a caller accidentally
                # carrying cascade/heavy flags". This call omitted the state entirely, so
                # converting a candidate to options re-derived lots without the cap and
                # then overwrote the capped size at `candidate.lots =` below — 3 lots
                # where the sizer had said 1, on a cascade flag this path reads raw.
                # signal_processor stamps the state it sized under onto the candidate
                # (sizing_compression_state); read it back rather than re-deriving it.
                compression_state=str(
                    getattr(candidate, "sizing_compression_state", "") or ""
                ),
            )
            if sized.lots < 1:
                # A refusal is a refusal. `max(1, sized.lots or base_lots)` turned the
                # sizer's "one lot's risk exceeds the budget" back into a full-size
                # position — the one answer it must never be allowed to become.
                return False
            lots = int(sized.lots)
            if sized.mode in {"cascade", "heavy_trend"}:
                try:
                    candidate.reasons = list(candidate.reasons or []) + [sized.reason]
                except Exception:
                    pass
        else:
            lots = base_lots

        # Signed delta mult for PE/CE
        try:
            dte = self.expiry.get_dte(instrument, datetime.now(IST).date())
        except Exception:
            dte = 1
        try:
            mult = self.signal_processor._option_signed_delta(
                spot, strike, option_type, {}, dte,
                0.5 if option_type == "CE" else -0.5,
            )
        except Exception:
            mult = 0.5 if option_type == "CE" else -0.5

        candidate.inst_type = "OPT"
        candidate.option_type = option_type
        candidate.atm_strike = float(strike)
        candidate.trading_symbol = trading_symbol
        candidate.symbol_token = symbol_token
        candidate.price = float(premium)
        candidate.stop = float(stop)
        candidate.target = float(target)
        candidate.initial_stop = float(stop)
        candidate.lots = int(lots)
        candidate.multiplier = float(mult)
        candidate.entry_spot = float(spot)
        try:
            candidate.reasons = list(candidate.reasons or []) + [
                f"Multi-signal mixed book: OPT book ({option_type} {int(strike)}) "
                f"TF={getattr(candidate, 'timeframe', '')} engine="
                f"{getattr(candidate, 'source_engine', '') or 'n/a'}"
            ]
        except Exception:
            pass
        setattr(candidate, "multi_signal_mixed_book_role", "OPT")
        setattr(candidate, "quote_verified", bool(premium > 0 and symbol_token))
        return True

    def _wave_has_cascade(self, candidates: List[TradeCandidate]) -> bool:
        return any(bool(getattr(c, "one_way_cascade_entry", False)) for c in candidates)

    def _cascade_multi_tf_core_set(self) -> set:
        settings = get_settings()
        raw = getattr(settings, "cascade_multi_tf_core_indices", None)
        if not raw:
            return set(self.CORE_CORRELATED_INDICES)
        return {
            str(item or "").split()[0].upper()
            for item in list(raw)
            if str(item or "").strip()
        }

    def _pick_cascade_tf_stack_for_index(
        self,
        rows: List[TradeCandidate],
        *,
        primary_max: int,
        dual_addon_max: int,
    ) -> List[TradeCandidate]:
        """Same stack for every core index: 1m+5m+15m primary + dual 5/15."""
        primary_tfs = {"1min", "5min", "15min"}
        best_primary: Dict[str, TradeCandidate] = {}
        dual_rows: List[TradeCandidate] = []
        for c in rows:
            tf = str(getattr(c, "timeframe", "") or "")
            lane = self._source_lane(c)
            if lane == "B":
                dual_rows.append(c)
                continue
            if tf in primary_tfs:
                prev = best_primary.get(tf)
                if prev is None or self._candidate_rank_score(c) > self._candidate_rank_score(prev):
                    best_primary[tf] = c
        tf_order = ["15min", "5min", "1min"]
        primary_picked = [
            best_primary[tf] for tf in tf_order if tf in best_primary
        ][: max(1, primary_max)]
        dual_by_tf: Dict[str, TradeCandidate] = {}
        for c in dual_rows:
            tf = str(getattr(c, "timeframe", "") or "")
            if tf not in {"5min", "15min"}:
                continue
            prev = dual_by_tf.get(tf)
            if prev is None or self._candidate_rank_score(c) > self._candidate_rank_score(prev):
                dual_by_tf[tf] = c
        dual_picked = [
            dual_by_tf[tf] for tf in ("5min", "15min") if tf in dual_by_tf
        ][: max(0, dual_addon_max)]
        # Same TF dual+main within 1m → keep first only
        return self._apply_dual_clone_reduction(primary_picked + dual_picked)

    def _pick_cascade_tf_stack_for_midcap(
        self, rows: List[TradeCandidate]
    ) -> List[TradeCandidate]:
        """MIDCAP cascade stack (FUT blocked → OPT only).

        Solo engine: best 2 of {1min, 5min, 15min}.
        Dual / main-lane engine: best 2 main-lane + best 1 dual of {5min, 15min}
        (= 2+1).
        """
        settings = get_settings()
        solo_max = max(1, int(getattr(settings, "cascade_midcap_solo_max_tf", 2) or 2))
        dual_main_max = max(1, int(getattr(settings, "cascade_midcap_dual_main_max", 2) or 2))
        dual_addon_max = max(0, int(getattr(settings, "cascade_midcap_dual_addon_max", 1) or 1))

        primary_tfs = {"1min", "5min", "15min"}
        best_main: Dict[str, TradeCandidate] = {}
        dual_rows: List[TradeCandidate] = []
        for c in rows:
            tf = str(getattr(c, "timeframe", "") or "")
            lane = self._source_lane(c)
            if lane == "B":
                dual_rows.append(c)
                continue
            if tf in primary_tfs:
                prev = best_main.get(tf)
                if prev is None or self._candidate_rank_score(c) > self._candidate_rank_score(prev):
                    best_main[tf] = c

        # Rank main-lane candidates by score (not fixed TF order) → take top N
        main_ranked = sorted(
            best_main.values(), key=self._candidate_rank_score, reverse=True
        )

        if dual_rows:
            # Dual engine path: best 2 main + best 1 dual of 5/15
            main_picked = main_ranked[:dual_main_max]
            dual_by_tf: Dict[str, TradeCandidate] = {}
            for c in dual_rows:
                tf = str(getattr(c, "timeframe", "") or "")
                if tf not in {"5min", "15min"}:
                    continue
                prev = dual_by_tf.get(tf)
                if prev is None or self._candidate_rank_score(c) > self._candidate_rank_score(prev):
                    dual_by_tf[tf] = c
            dual_ranked = sorted(
                dual_by_tf.values(), key=self._candidate_rank_score, reverse=True
            )
            dual_picked = dual_ranked[:dual_addon_max]
            # Same TF dual+main within 1m → keep first only
            return self._apply_dual_clone_reduction(main_picked + dual_picked)

        # Solo engine: best 2 of 1/5/15
        return main_ranked[:solo_max]

    def _register_heavy_trend_vote(
        self,
        instrument: str,
        direction: str,
        timeframe: str = "",
        *,
        signal_ts=None,
    ) -> None:
        """Record a same-wave / same-session direction vote (kills lag-1 heavy-trend)."""
        inst = str(instrument or "").split()[0].upper()
        want = str(direction or "").upper()
        if not inst or want not in {"LONG", "SHORT"}:
            return
        ts = self._parse_trade_timestamp(signal_ts) or datetime.now(IST).replace(tzinfo=None)
        votes = getattr(self, "_heavy_trend_votes", None)
        if not isinstance(votes, dict):
            self._heavy_trend_votes = {}
            votes = self._heavy_trend_votes
        votes[inst] = {
            "direction": want,
            "timeframe": str(timeframe or ""),
            "ts": ts,
        }

    def _ingest_wave_heavy_trend_votes(self, candidates: List[TradeCandidate]) -> None:
        """Register all ENTRY candidates in the current execution wave as votes."""
        for c in list(candidates or []):
            if getattr(c, "action", "ENTRY") != "ENTRY":
                continue
            self._register_heavy_trend_vote(
                str(getattr(c, "instrument", "") or ""),
                str(getattr(c, "direction", "") or ""),
                str(getattr(c, "timeframe", "") or ""),
                signal_ts=getattr(c, "signal_timestamp", None),
            )

    def _count_aligned_index_trend(
        self,
        direction: str,
        timeframe: str = "",
        *,
        as_of=None,
        include_self: str = "",
    ) -> int:
        """How many active indices currently vote the same direction (trend+TF).

        Used for non-cascade heavy-trend OPT ×2 (needs ≥2/4).
        Sources (no lag-1 on same wave):
          0) same-wave / session direction votes registry
          1) open same-dir trades
          2) cached recent signals (last few within vote max-age)
          3) latest trade candidates + pending live signals
          4) optional include_self instrument always counts once
        """
        settings = get_settings()
        want = str(direction or "").upper()
        if want not in {"LONG", "SHORT"}:
            return 0
        signal_want = "BUY" if want == "LONG" else "SELL"
        max_age = max(
            30.0,
            float(getattr(settings, "heavy_trend_vote_max_age_seconds", 600.0) or 600.0),
        )
        now = self._parse_trade_timestamp(as_of) or datetime.now(IST).replace(tzinfo=None)

        def _fresh(ts) -> bool:
            parsed = self._parse_trade_timestamp(ts)
            if parsed is None:
                return True  # unknown age → still count (same-scan peers)
            return abs((now - parsed).total_seconds()) <= max_age

        tfs = []
        tf = str(timeframe or "")
        if tf in {"1min", "5min", "15min"}:
            tfs = [tf]
            if tf != "15min":
                tfs.append("15min")
            if tf != "5min":
                tfs.append("5min")
        else:
            tfs = ["15min", "5min"]

        aligned: set = set()
        active = [
            str(i or "").split()[0].upper()
            for i in (getattr(self, "active_indices", None) or list(self.CORE_CORRELATED_INDICES))
        ]

        # 0) Same-wave / session votes (registered as each index is graded)
        votes = getattr(self, "_heavy_trend_votes", None) or {}
        if isinstance(votes, dict):
            for inst, payload in votes.items():
                name = str(inst or "").split()[0].upper()
                if name not in active:
                    continue
                if str((payload or {}).get("direction") or "").upper() != want:
                    continue
                if _fresh((payload or {}).get("ts")):
                    aligned.add(name)

        # 1) Open trades
        for t in getattr(getattr(self, "trades", None), "open_trades", {}).values():
            if getattr(t, "is_ghost", False):
                continue
            inst = str(getattr(t, "instrument", "") or "").split()[0].upper()
            if inst not in active:
                continue
            if str(getattr(t, "direction", "") or "").upper() == want:
                if _fresh(getattr(t, "entry_time", None) or getattr(t, "entry_timestamp", None)):
                    aligned.add(inst)

        # 2) Cached scanner signals — last few within max_age (not only last tick)
        cache = getattr(self, "_cached_results", {}) or {}
        for inst in active:
            if inst in aligned:
                continue
            for check_tf in tfs:
                res = cache.get(f"{inst}_{check_tf}") or {}
                sigs = list(res.get("signals") or [])
                if not sigs:
                    continue
                for sig in reversed(sigs[-5:]):
                    if str(getattr(sig, "signal_type", "") or "").upper() != signal_want:
                        continue
                    if _fresh(getattr(sig, "timestamp", None)):
                        aligned.add(inst)
                        break
                if inst in aligned:
                    break

        # 3) Latest trade candidates + pending live buffer
        latest = getattr(self, "_latest_trade_candidates", {}) or {}
        for inst in active:
            if inst in aligned:
                continue
            for c in list(latest.get(inst) or []):
                if getattr(c, "action", "ENTRY") != "ENTRY":
                    continue
                if str(getattr(c, "direction", "") or "").upper() != want:
                    continue
                if _fresh(getattr(c, "signal_timestamp", None)):
                    aligned.add(inst)
                    break
        pending = getattr(self, "_pending_live_signals", None) or {}
        if isinstance(pending, dict):
            for data in pending.values():
                c = data.get("candidate") if isinstance(data, dict) else None
                if c is None:
                    continue
                inst = str(getattr(c, "instrument", "") or "").split()[0].upper()
                if inst not in active or inst in aligned:
                    continue
                if str(getattr(c, "direction", "") or "").upper() != want:
                    continue
                if _fresh(getattr(c, "signal_timestamp", None) or data.get("timestamp")):
                    aligned.add(inst)

        # 4) Explicit self (current signal being sized)
        self_inst = str(include_self or "").split()[0].upper()
        if self_inst and self_inst in active:
            aligned.add(self_inst)

        return len(aligned)

    def _heavy_trend_lot_scale_eligible(
        self,
        instrument: str,
        direction: str,
        timeframe: str = "",
    ) -> bool:
        """Non-cascade: ≥2/4 indices align trend+TF → OPT may size ×2.

        Current instrument always votes; peers from same-wave registry, open
        trades, fresh cache, and pending/latest candidates (no lag-1).
        """
        settings = get_settings()
        if not self._setting_enabled(
            getattr(settings, "heavy_trend_lot_scale_enabled", True), True
        ):
            return False
        min_n = max(2, int(getattr(settings, "heavy_trend_min_aligned_indices", 2) or 2))
        want = str(direction or "").upper()
        if want not in {"LONG", "SHORT"}:
            return False
        inst = str(instrument or "").split()[0].upper()
        # Register self vote immediately so later indices in this scan see us
        self._register_heavy_trend_vote(inst, want, timeframe)
        count = self._count_aligned_index_trend(
            direction, timeframe, include_self=inst
        )
        return count >= min_n

    def _select_mixed_book_entry_wave(
        self, entry_cands: List[TradeCandidate]
    ) -> List[TradeCandidate]:
        """Select entries for mixed book.

        Cascade multi-index (equal for NIFTY/BANKNIFTY/SENSEX):
          - Each core index: full multi-TF stack (1m/5m/15m) + dual addons
          - MIDCP (FUT blocked): solo best 2 of 1/5/15; dual = 2 main + 1 dual (2+1)
        Non-cascade / collapse-on: best TF per index (all indices treated equally).
        """
        settings = get_settings()
        cascade_wave = (
            self._wave_has_cascade(entry_cands)
            and self._setting_enabled(
                getattr(settings, "cascade_multi_tf_stack_enabled", True), True
            )
        )
        collapse = self._setting_enabled(
            getattr(settings, "multi_signal_collapse_best_tf_per_index", True), True
        )
        primary_max = max(1, int(getattr(settings, "cascade_primary_max_tf", 3) or 3))
        dual_addon_max = max(0, int(getattr(settings, "cascade_dual_addon_max", 2) or 2))
        core_set = self._cascade_multi_tf_core_set()
        midcap_name = str(getattr(self, "MIDCAP_CORRELATED_INDEX", "MIDCPNIFTY") or "MIDCPNIFTY").upper()

        # Group by instrument
        by_inst: Dict[str, List[TradeCandidate]] = {}
        for c in entry_cands:
            inst = str(getattr(c, "instrument", "") or "").split()[0].upper()
            by_inst.setdefault(inst, []).append(c)

        # Rank instruments by their best candidate (equity across all indices)
        inst_rank = {
            inst: max(rows, key=self._candidate_rank_score)
            for inst, rows in by_inst.items()
        }
        ordered_insts = sorted(
            inst_rank.keys(),
            key=lambda i: self._candidate_rank_score(inst_rank[i]),
            reverse=True,
        )

        selected: List[TradeCandidate] = []
        if not cascade_wave or not collapse:
            # Non-cascade, or collapse disabled: equal treatment — best TF/index
            # (or all TFs if collapse off).
            if collapse:
                selected = [inst_rank[i] for i in ordered_insts]
            else:
                for inst in ordered_insts:
                    selected.extend(
                        sorted(by_inst[inst], key=self._candidate_rank_score, reverse=True)
                    )
            return selected

        # Cascade: CORE full stack; MIDCAP solo best-2 / dual 2+1; other → midcap rules
        for inst in ordered_insts:
            rows = list(by_inst[inst])
            if inst in core_set:
                selected.extend(
                    self._pick_cascade_tf_stack_for_index(
                        rows, primary_max=primary_max, dual_addon_max=dual_addon_max
                    )
                )
            elif inst == midcap_name or inst not in core_set:
                selected.extend(self._pick_cascade_tf_stack_for_midcap(rows))
            else:
                selected.extend(self._pick_cascade_tf_stack_for_midcap(rows))
        return selected

    def _apply_multi_signal_mixed_book(
        self, candidates: List[TradeCandidate]
    ) -> List[TradeCandidate]:
        """When multi-engine/multi-TF/multi-index fires: 1×FUT (1 lot) + rest OPT.

        All indices compete equally for the sole FUT slot (rank score).
        Cascade: NIFTY/BN/SENSEX full multi-TF; MIDCAP best 2 solo or 2+1 dual.
        Only MIDCP is FUT-blocked. OPT cascade/heavy-trend mult applied on force.
        """
        entry_cands = [
            c for c in candidates
            if getattr(c, "action", "ENTRY") == "ENTRY"
        ]
        if not self._multi_signal_mixed_book_trigger(entry_cands):
            return candidates

        settings = get_settings()
        entry_cands = self._select_mixed_book_entry_wave(entry_cands)
        # Global rank for FUT assignment (equity across all indices — not NIFTY-only)
        entry_cands.sort(key=self._candidate_rank_score, reverse=True)
        pref = str(getattr(self, "inst_pref", "AUTO") or "AUTO").upper()
        max_opt = max(1, int(getattr(settings, "multi_signal_max_opt_instruments", 6) or 6))
        max_fut = max(0, int(getattr(settings, "multi_signal_max_fut", 1) or 1))

        if pref == "OPT":
            max_opt = max_opt + max_fut
            max_fut = 0
        elif pref == "FUT":
            # FUT-only: one FUT per index max (operator rule), so the wave can
            # never exceed the active index count.
            max_fut = min(max_fut + max_opt, max(1, len(self.active_indices)))
            max_opt = 0

        open_fut = 0
        open_fut_indices: set = set()
        for t in getattr(self.trades, "open_trades", {}).values():
            if getattr(t, "is_ghost", False):
                continue
            if str(getattr(t, "inst_type", "") or "").upper() == "FUT":
                open_fut += 1
                open_fut_indices.add(str(getattr(t, "instrument", "") or "").split()[0])

        fut_slots = max(0, max_fut - open_fut)
        selected: List[TradeCandidate] = []
        fut_assigned = 0

        # Sole FUT logic for AUTO
        fut_pick = None
        if pref == "AUTO" and fut_slots > 0:
            for c in entry_cands:
                inst = str(getattr(c, "instrument", "") or "").split()[0]
                if self._futures_blocked_for_index(inst):
                    continue
                fut_pick = c
                break

        for c in entry_cands:
            inst = str(getattr(c, "instrument", "") or "").split()[0]

            if pref == "FUT":
                # FUT-only: every accepted slot is futures (never OPT fallback).
                # One FUT per index (operator rule) — counting live positions.
                index_taken = inst in open_fut_indices or any(
                    str(getattr(row, "instrument", "") or "").split()[0] == inst
                    for row in selected
                    if str(getattr(row, "inst_type", "") or "").upper() == "FUT"
                )
                if index_taken:
                    try:
                        c.reasons = list(c.reasons or []) + [
                            "Multi-signal mixed book: FUT-only rejected (one FUT per index)"
                        ]
                        c.status = "REJECTED - FUT Only"
                    except Exception:
                        pass
                    continue
                if fut_assigned < fut_slots and self._force_candidate_to_futures_1lot(c):
                    selected.append(c)
                    fut_assigned += 1
                else:
                    why = (
                        f"FUT slots full ({max_fut})"
                        if fut_assigned >= fut_slots
                        else "futures contract/price unavailable"
                    )
                    try:
                        c.reasons = list(c.reasons or []) + [
                            f"Multi-signal mixed book: FUT-only rejected ({why})"
                        ]
                        c.status = "REJECTED - FUT Only"
                    except Exception:
                        pass
                continue

            if pref == "OPT":
                # OPT-only: never fall back to futures if option conversion fails.
                opt_count = sum(
                    1 for row in selected
                    if str(getattr(row, "inst_type", "") or "").upper() == "OPT"
                )
                if opt_count >= max_opt:
                    try:
                        c.reasons = list(c.reasons or []) + [
                            f"Multi-signal mixed book: OPT slots full ({max_opt})"
                        ]
                        c.status = "REJECTED - Mixed Book Cap"
                    except Exception:
                        pass
                    continue
                if self._force_candidate_to_options(c):
                    selected.append(c)
                else:
                    try:
                        c.reasons = list(c.reasons or []) + [
                            "Multi-signal mixed book: OPT-only rejected (option contract unavailable)"
                        ]
                        c.status = "REJECTED - OPT Only"
                    except Exception:
                        pass
                continue

            # AUTO / HYBRID: sole FUT then rest OPT (original mixed book).
            if fut_pick is not None and c is fut_pick and fut_assigned < fut_slots:
                if self._force_candidate_to_futures_1lot(c):
                    selected.append(c)
                    fut_assigned += 1
                    continue

            opt_count = sum(
                1 for row in selected
                if str(getattr(row, "inst_type", "") or "").upper() == "OPT"
            )
            if opt_count >= max_opt:
                try:
                    c.reasons = list(c.reasons or []) + [
                        f"Multi-signal mixed book: OPT slots full ({max_opt})"
                    ]
                    c.status = "REJECTED - Mixed Book Cap"
                except Exception:
                    pass
                continue

            if self._force_candidate_to_options(c):
                selected.append(c)
            elif fut_assigned < fut_slots and not self._futures_blocked_for_index(inst) and self._force_candidate_to_futures_1lot(c):
                # AUTO only: option map failed — allow FUT fill of remaining slot.
                selected.append(c)
                fut_assigned += 1

        logger.info(
            f"Multi-signal mixed book (pref={pref}): wave -> "
            f"{fut_assigned} FUT + "
            f"{sum(1 for row in selected if str(getattr(row, 'inst_type', '') or '').upper() == 'OPT')} OPT "
            f"({[f'{row.instrument}:{row.inst_type}:{row.timeframe}' for row in selected]})"
        )
        self.log_event(
            f"Mixed book ({pref}): "
            f"{fut_assigned} FUT + "
            f"{sum(1 for row in selected if str(getattr(row, 'inst_type', '') or '').upper() == 'OPT')} OPT "
            f"({len(selected)} accepted; cascade multi-TF="
            f"{self._wave_has_cascade(selected)})",
            "trade",
        )
        others = [c for c in candidates if getattr(c, "action", "ENTRY") != "ENTRY"]
        return others + selected

    def _resolve_instrument_type(
        self,
        instrument: str,
        grade: str,
        regime: str,
        intel_score: float = 0.0,
        signal_score: float = 0.0,
        confidence: float = 0.0,
        adx_value: float = 0.0,
        atr_value: float = 0.0,
        price: float = 0.0,
        signal_time: Optional[datetime] = None,
        iv_percentile: float = 50.0,
        existing_type: Optional[str] = None,
        timeframe: str = "",
        five_min_true_impulse: bool = False,
    ) -> str:
        """Resolve FUT/OPT once so backtest, recovery, and live use the same Hybrid rules."""
        pref = (self.inst_pref or "AUTO").upper()
        if pref == "FUT":
            return "FUT"
        if pref == "OPT":
            return "OPT"

        if existing_type in ("FUT", "OPT"):
            return "OPT" if existing_type == "FUT" else "FUT"

        grade = grade or ""
        regime = regime or "UNKNOWN"
        adx = float(adx_value or 0.0)
        atr_pct = (float(atr_value or 0.0) / float(price or 1.0)) * 100.0 if price else 0.0
        score = float(signal_score or 0.0)
        conf = float(confidence or 0.0)
        intel = abs(float(intel_score or 0.0))
        ivp = float(iv_percentile or 50.0)

        is_choppy = is_risky_regime(regime)

        high_grade = grade in {"A", "A+", "B+"}
        strong_momentum = high_grade and (conf >= 0.62 or score >= 0.45 or intel >= 0.55 or adx >= 28.0)
        high_iv = ivp >= 75.0
        high_spot_vol = atr_pct >= 0.65
        option_quality_ok = False
        try:
            option_quality_ok = self.signal_processor._option_grade_allowed(
                grade,
                conf,
                regime,
                adx_value=adx,
                intel_score=intel_score,
                signal_score=score,
                five_min_true_impulse=five_min_true_impulse,
                timeframe=timeframe,
            )
        except Exception:
            option_quality_ok = grade in {"A", "A+"} and conf >= 0.70
        more_results = (
            self._setting_enabled(getattr(get_settings(), "ut_backtest_more_results", True), True)
            and getattr(self, "mode", "") == "HISTORICAL"
        )
        # Lean routing: send loss-prone "soft FUT" outcomes (choppy regimes and the
        # ordinary catch-all) to defined-risk options, while genuine FUT cases
        # (high spot vol, high IV, 0DTE late) are preserved below.
        lean_routing = self._setting_enabled(
            getattr(get_settings(), "lean_routing_to_options", True), True
        )

        # Indices whose futures the AUTO router must never select (they would be
        # rejected downstream at the FUT stop gate). Explicit inst_pref="FUT"
        # remains an operator override and is returned before this point.
        blocked_fut = {
            str(item or "").upper()
            for item in (getattr(get_settings(), "auto_futures_blocked_indices", []) or [])
        }
        fut_blocked = str(instrument or "").split()[0].upper() in blocked_fut

        def choose(inst_type: str, reason: str) -> str:
            if inst_type == "FUT" and fut_blocked:
                inst_type = "OPT"
                reason = f"futures blocked for index -> options ({reason})"
            if getattr(self, "mode", "") != "HISTORICAL":
                logger.info(
                    f"Instrument Type Decision: {instrument} {grade} {conf:.0%} "
                    f"regime={regime} adx={adx:.1f} atr%={atr_pct:.2f} ivp={ivp:.1f} "
                    f"-> {inst_type} ({reason})"
                )
            return inst_type

        is_late_session = False
        is_0dte = False
        if signal_time is not None:
            is_late_session = signal_time.time() >= dtime(14, 0)
            try:
                is_0dte = self.expiry.is_expiry_day(instrument, signal_time.date())
            except Exception:
                is_0dte = False

        premium_momentum_confirmed = bool(
            option_quality_ok
            and high_grade
            and conf >= 0.85
            and score >= 0.45
            and (intel >= 0.55 or adx >= 35.0)
            and not high_spot_vol
        )

        # Expiry-day gamma mode, "futures" after-cutoff: once the morning gamma window
        # closes on expiry day, trade the index FUTURE (no theta) instead of options.
        if is_0dte and signal_time is not None:
            try:
                _s = get_settings()
                if (bool(getattr(_s, "expiry_day_trade_current_week", False))
                        and str(getattr(_s, "expiry_day_after_cutoff_mode", "rollover")).lower() == "futures"
                        and signal_time.time() >= self.expiry._parse_hhmm(getattr(_s, "expiry_day_gamma_cutoff", "13:00"))):
                    return choose("FUT", "expiry-day post-cutoff: futures mode (no theta)")
            except Exception:
                pass

        # Expiry-day gamma trade only makes sense on a strong, short-tenure move; without
        # momentum a current-expiry option just theta-bleeds, so route to FUT instead.
        if is_0dte and signal_time is not None and not strong_momentum:
            try:
                _s = get_settings()
                if (bool(getattr(_s, "expiry_day_gamma_require_momentum", True))
                        and self.expiry.in_gamma_window(instrument, signal_time)):
                    return choose("FUT", "expiry-day gamma needs momentum; weak signal -> futures")
            except Exception:
                pass

        if is_0dte and is_late_session and not strong_momentum:
            return choose("FUT", "0DTE late-session without strong momentum")
        if high_iv:
            return choose("FUT", "high IV; avoid inflated option premium")
        if is_choppy:
            if premium_momentum_confirmed:
                return choose("OPT", "risky regime but premium momentum confirmed")
            if not high_spot_vol:
                # lean routing ON (default): choppy soft-FUT -> defined-risk options.
                # lean routing OFF: honour the base rule and keep it in futures.
                if lean_routing:
                    return choose("OPT", "choppy regime -> defined-risk options")
                return choose("FUT", "choppy regime, lean routing off -> base futures")
            return choose("FUT", "choppy/volatile regime with high spot vol; prefer futures")
        if strong_momentum and option_quality_ok and not high_spot_vol:
            return choose("OPT", "strong momentum passed option-quality gate")
        if more_results and strong_momentum and not high_spot_vol:
            return choose("OPT", "historical exploratory strong momentum")
        # Qualifying B-grade routes to options like B+: option_quality_ok already
        # encodes the B rule (trending + conf>=0.50 + ADX>=25). 15m alignment is
        # enforced downstream by the entry gate.
        if str(grade or "").split()[0] == "B" and option_quality_ok and not high_spot_vol:
            return choose("OPT", "qualifying B-grade trend momentum -> options")
        if high_spot_vol:
            return choose("FUT", "high spot volatility; prefer linear futures tracking")
        if strong_momentum:
            return choose("OPT", "clean strong momentum")
        # Slow-grind trend: the move is real (aligned trending regime, ADX has a
        # floor) but thrust is absent and per-bar range is compressed — the case
        # where an option's slow delta gain loses to theta+spread while futures
        # track the grind linearly. Must sit before the lean catch-all so these
        # setups stop defaulting to options.
        if (
            self._setting_enabled(
                getattr(get_settings(), "slow_grind_futures_routing_enabled", True), True
            )
            and is_trending_regime(regime)
            and adx >= float(getattr(get_settings(), "slow_grind_min_adx", 18.0) or 18.0)
            and 0.0 < atr_pct <= float(getattr(get_settings(), "slow_grind_max_atr_pct", 0.38) or 0.38)
        ):
            return choose("FUT", "slow-grind trend: low-thrust directional move -> futures (no theta)")
        if not high_spot_vol:
            # lean routing ON (default): ordinary catch-all -> defined-risk options.
            # lean routing OFF: honour the base rule and keep it in futures.
            if lean_routing:
                return choose("OPT", "ordinary setup -> defined-risk options")
            return choose("FUT", "ordinary setup, lean routing off -> base futures")
        return choose("FUT", "default AUTO preference for ordinary setup with high spot vol")

    async def _track_repaint_until_candle_close(self, trade, candidate):
        """Continuously monitors if a signal repaints before its source candle closes."""
        if not bool(getattr(trade, "entered_intracandle", True)):
            setattr(trade, "repaint_guard_checked", True)
            return
        try:
            if not getattr(trade, "id", None) or trade.status != "OPEN":
                return
                
            sig_timestamp = getattr(candidate, "signal_timestamp", None)
            if not sig_timestamp:
                return
                
            tf_minutes = {"1min": 1, "5min": 5, "15min": 15}.get(str(getattr(candidate, "timeframe", "") or ""), 5)
            # Find the time when the candle closes
            sig_time_naive = sig_timestamp.replace(tzinfo=None) if sig_timestamp.tzinfo else sig_timestamp
            candle_close_time = sig_time_naive + timedelta(minutes=tf_minutes)
            
            recheck_seconds = max(
                5.0,
                float(getattr(get_settings(), "repaint_recheck_seconds", 20.0) or 20.0),
            )
            logger.info(
                f"🔍 Repaint Tracker Active for {trade.id} until candle closes at "
                f"{candle_close_time.time()} (re-check every {recheck_seconds:.0f}s)"
            )

            while trade.status == "OPEN":
                await asyncio.sleep(recheck_seconds) # Re-check for repaint (default 20s)

                now = datetime.now(IST).replace(tzinfo=None)
                # "Cannot tell" is NOT evidence of a repaint. _repaint_signal_status
                # returns UNKNOWN when the scan cache is empty, and the cache is cleared
                # out from under a live tracker by ordinary operator actions: a settings
                # save (configure), perform_system_recalibration, a scanner-engine switch
                # (invalidate_chart_caches) and the day rollover all call
                # _cached_results.clear(). The boolean wrapper collapsed UNKNOWN into
                # "vanished", so one of those clicks market-exited a real position on no
                # evidence at all.
                #
                # Only a DEFINITE absence may abort. UNKNOWN falls through to the
                # candle-close check below and re-reads in recheck_seconds, so a genuine
                # repaint is still caught on the next pass — a cleared cache costs one
                # 20s cycle instead of a forced exit. Read the status directly rather
                # than through _live_utbot_signal_still_present, whose True/False cannot
                # distinguish "gone" from "cannot see".
                absence_definite = Scanner._repaint_absence_is_definite(
                    self, candidate, sig_timestamp
                )
                # Keep the persistence counters the operator's two defer caps are made of.
                # _repaint_absent_checks / _repaint_first_absent_at were written ONLY on
                # session TradeCandidates, never on the real Trade this tracker holds, so
                # inside _should_defer_option_repaint_abort absent_checks was pinned at 1
                # and first_absent was always None: the "abort after 2 checks / 55s"
                # limits could not trip, and a genuinely repainted option rode to candle
                # close instead — up to 5 minutes on a 5min signal, 15 on a 15min one.
                #
                # Maintained here rather than by raising the default at the read site:
                # a higher default would trip the cap on the FIRST absent check and turn
                # the defer off entirely, the opposite of what the operator configured.
                if not absence_definite:
                    setattr(trade, "_repaint_absent_checks", 0)
                    setattr(trade, "_repaint_first_absent_at", None)
                else:
                    setattr(
                        trade,
                        "_repaint_absent_checks",
                        int(getattr(trade, "_repaint_absent_checks", 0) or 0) + 1,
                    )
                    if getattr(trade, "_repaint_first_absent_at", None) is None:
                        setattr(trade, "_repaint_first_absent_at", now)
                if absence_definite:
                    # Every configured repaint MITIGATION was unreachable from here. All
                    # call sites for the momentum override, the profit hold and the
                    # option defer sit in _check_session_candidates_breaches_locked, which
                    # manages dashboard/session rows and never a broker position. So the
                    # operator's policy — hold a repaint that is already in profit, let a
                    # fresh option ride normal intrabar flicker to its candle close,
                    # honour a stabilization momentum override — applied to the paper
                    # mirror while the real position was market-exited immediately.
                    mark = Scanner._repaint_abort_exit_price(self, trade, candidate)
                    hold_reason = ""
                    # Repaint is an INTRABAR verdict. _repaint_close_check_in_window is
                    # the policy that says so — source candle still forming, plus a
                    # grace at the close for the final check — and its docstring is
                    # explicit that afterwards a still-open trade is a NORMAL tracked
                    # position that "must never be repaint-aborted".
                    #
                    # It was consulted at 16338 and 21921, both session-mirror paths, and
                    # not here — the tracker that closes the REAL position. So a tracker
                    # spawned or resumed late could take its first absence reading long
                    # after the bar had confirmed and market-exit on it; a 15m signal was
                    # aborted eight minutes past confirmation. The loop ordering itself is
                    # right (the tick at/after candle close IS the authoritative final
                    # check) — what was missing is any bound on how far past it may go.
                    try:
                        within_repaint_window = Scanner._repaint_close_check_in_window(
                            self, sig_timestamp,
                            getattr(candidate, "timeframe", "5min"), now,
                        )
                    except Exception as exc:
                        logger.debug(f"Repaint window check unavailable for {trade.id}: {exc}")
                        # Unlike the mitigations below, this is a VALIDITY bound, not a
                        # reason to spare a genuine repaint. Not knowing whether the bar
                        # has confirmed makes exiting the dangerous move, not the safe
                        # one: a missed abort leaves the trade to its stop and target.
                        within_repaint_window = False
                    # Fail SAFE, not open: if a mitigation cannot be evaluated the abort
                    # proceeds, which is the behaviour that existed before they were
                    # wired. Partial scanner stubs are a real pattern here and this whole
                    # tracker sits under one `except Exception`, so an AttributeError
                    # raised in here would otherwise swallow the abort entirely — which
                    # an existing test caught on the first attempt.
                    try:
                        override_ctx = Scanner._post_entry_repaint_override_context(
                            self, candidate, sig_timestamp
                        )
                        if override_ctx:
                            # A confirming override restarts the persistence clock, exactly
                            # as the session mirror does — otherwise a held trade would
                            # accumulate absent checks and trip the cap on evidence the
                            # override already answered.
                            setattr(trade, "_repaint_absent_checks", 0)
                            setattr(trade, "_repaint_first_absent_at", None)
                            hold_reason = str(
                                override_ctx.get("reason")
                                or override_ctx.get("type")
                                or "confirmed momentum"
                            )
                        elif mark > 0 and Scanner._repaint_abort_profit_hold(self, trade, mark):
                            hold_reason = "position is already in profit"
                        elif mark > 0:
                            deferred, defer_text = Scanner._should_defer_option_repaint_abort(
                                self, trade, mark, now, now >= candle_close_time,
                            )
                            if deferred:
                                hold_reason = defer_text or "option repaint deferred to candle close"
                    except Exception as exc:
                        logger.debug(f"Repaint mitigation check unavailable for {trade.id}: {exc}")
                        hold_reason = ""
                    # After the mitigation block on purpose: its `except` resets
                    # hold_reason, and the window bound must not be cleared by a failure
                    # in an unrelated mitigation.
                    if not within_repaint_window:
                        hold_reason = (
                            "source candle already confirmed and the repaint grace window has passed"
                        )
                    if hold_reason:
                        # Fall through to the candle-close check rather than continue, so
                        # the tracker still finishes at the close instead of looping on.
                        marker_key = f"{trade.id}|repaint-hold"
                        if getattr(self, "_last_repaint_hold", "") != marker_key:
                            setattr(self, "_last_repaint_hold", marker_key)
                            logger.info(
                                f"REPAINT HOLD: {trade.id} arrow vanished but not aborting "
                                f"— {hold_reason}."
                            )
                            self.log_event(
                                f"Repaint hold for {candidate.instrument}: {hold_reason}.",
                                "info",
                            )
                        self._diag_inc("repaint", "abort_held")
                    else:
                        logger.warning(f"🚨 REPAINT ABORT: Signal vanished for {trade.id}! Exiting immediately.")
                        self.log_event(f"🚨 REPAINT ABORT: Signal vanished for {candidate.instrument}. Exiting.", "error")
                        marker = getattr(self, "_mark_post_repaint_recheck", None)
                        if callable(marker):
                            marker(candidate, sig_timestamp, now, source="async_repaint_abort")
                        # Force Exit
                        # Unbound: partial scanner stubs are a real pattern here, and this
                        # tracker's whole body sits under one `except Exception` — a missing
                        # attribute would be swallowed and the abort would silently not fire.
                        price = Scanner._repaint_abort_exit_price(self, trade, candidate)
                        if price <= 0:
                            logger.error(
                                f"REPAINT ABORT for {trade.id}: no usable mark for "
                                f"{getattr(trade, 'symbol', '')}; leaving the position to the "
                                "exit engines rather than booking a zero."
                            )
                            break
                        self._close_and_record(
                            trade.id,
                            float(price),
                            "REPAINT_ABORT",
                            exit_time=now,
                        )
                        break
                if now >= candle_close_time:
                    setattr(trade, "repaint_guard_checked", True)
                    logger.info(f"✅ Repaint Tracker complete for {trade.id} - final candle-close check passed.")
                    break
        except Exception as e:
            logger.error(f"Error in repaint tracker for {getattr(trade, 'id', 'unknown')}: {e}")

    async def _coordinate_and_execute(self, candidates: List[TradeCandidate], is_warmup: bool = False):
        """
        Coordinate every matured signal through independent eligibility checks.
        Same-time signals are never pre-dropped by a cross-index quota.
        """
        accepted_candidates: List[TradeCandidate] = []
        signal_fire_mode = self._signal_fire_mode()
        intrabar_enabled = signal_fire_mode == "INTRACANDLE"

        if self.mode != "HISTORICAL" and not is_warmup:
            settings = get_settings()
            if not self._live_clock_is_sane():
                self._pending_live_signals.clear()
                return accepted_candidates
            session_now = self._session_squareoff_clock()
            force_exit_time = self._configured_session_time("ut_force_exit_time", "15:25")
            final_entry_time = self._configured_session_time("ut_5min_no_entry_after", "15:15")
            if session_now.time() >= force_exit_time:
                if self.scan_count % 25 == 0:
                    logger.info(
                        f"Execution Gate: hard square-off window active after {force_exit_time.strftime('%H:%M')} IST."
                    )
                self._pending_live_signals.clear()
                return accepted_candidates

            if session_now.time() >= final_entry_time:
                pending_candidates = [
                    item.get("candidate")
                    for item in self._pending_live_signals.values()
                    if isinstance(item, dict) and item.get("candidate") is not None
                ]
                cutoff_eligible = any(
                    self._entry_cutoff_allows_candidate(candidate, session_now)
                    for candidate in list(candidates) + pending_candidates
                )
                if not cutoff_eligible:
                    if self.scan_count % 25 == 0:
                        logger.info(
                            f"Execution Gate: no eligible candle closed by "
                            f"{final_entry_time.strftime('%H:%M')} IST."
                        )
                    self._pending_live_signals.clear()
                    return accepted_candidates
        if self.mode != "HISTORICAL" and not is_warmup:
            source_now = self._session_squareoff_clock()
            timing_eligible = []
            for candidate in candidates:
                source_is_intrabar = self._candidate_source_is_intrabar(candidate, source_now)
                entered_intracandle = (
                    intrabar_enabled
                    and getattr(candidate, "action", "ENTRY") == "ENTRY"
                    and source_is_intrabar
                )
                setattr(candidate, "signal_fire_mode", signal_fire_mode)
                setattr(candidate, "entered_intracandle", entered_intracandle)
                if not intrabar_enabled and source_is_intrabar:
                    self.log_signal_decision_once(
                        f"{candidate.instrument}|{candidate.timeframe}|{getattr(candidate, 'signal_timestamp', '')}|closed-mode",
                        f"Signal waiting: {candidate.instrument} {candidate.timeframe} deferred until candle close.",
                        "trade",
                    )
                    continue
                # CANDLE_CLOSE only. In INTRACANDLE every candidate meets the entry cutoff
                # inside the stabilization block below, but that whole block is skipped in
                # closed-candle mode, leaving just the wave-level any() above — which is
                # not per candidate and only runs once the clock is already past
                # ut_5min_no_entry_after. A bar that closed inside the window but is
                # processed after it therefore entered unchecked.
                # Confined to this branch on purpose: applying the cutoff this early in
                # INTRACANDLE would reject candidates the buffer is still entitled to
                # mature, which is a live-path behaviour change this does not want.
                if not intrabar_enabled and not self._entry_cutoff_allows_candidate(
                    candidate, source_now
                ):
                    self.log_signal_decision_once(
                        f"{candidate.instrument}|{candidate.timeframe}|"
                        f"{getattr(candidate, 'signal_timestamp', '')}|closed-cutoff",
                        f"Entry cutoff: {candidate.instrument} {candidate.timeframe} "
                        f"candle closed past the no-entry policy.",
                        "trade",
                    )
                    continue
                timing_eligible.append(candidate)
            candidates = timing_eligible
            if not intrabar_enabled:
                self._pending_live_signals.clear()

        # ── Live Anti-Repaint Stabilization Buffer ──
        if self.mode != "HISTORICAL" and not is_warmup and intrabar_enabled:
            now = datetime.now(IST).replace(tzinfo=None)
            matured_candidates = []
            pending_changed = False

            # Step 1: Add new candidates to the buffer if not already present
            for c in candidates:
                if getattr(c, "action", "ENTRY") != "ENTRY":
                    continue
                # A signal whose SOURCE BAR HAS CLOSED does not belong in an anti-repaint
                # buffer. The buffer exists to let a forming bar's arrow settle; a final
                # bar's arrow cannot repaint, so the wait buys nothing and costs 30s of
                # drift before intelligence and the filters even see it.
                #
                # Worse, it was then run through the repaint gate below, which re-reads
                # the CURRENT latest signal. Once the cache rolls to the next bar the old
                # identity is gone, so a fully-confirmed closed-bar signal got discarded
                # as "arrow vanished" — a rejection reason that cannot logically apply to
                # a bar that is already final.
                #
                # entered_intracandle is computed for every candidate a few lines above
                # and, until now, read by nothing in this block.
                if not bool(getattr(c, "entered_intracandle", True)):
                    # Exempt from the anti-repaint WAIT — not from the session's entry
                    # policy. BOTH cutoff checks live further down this function: the
                    # pre-buffer one below, and the matured one inside the pending loop.
                    # `continue` skipped both, so a closed 15min bar could open a fresh
                    # index-option position after ut_no_entry_after with minutes left to
                    # the 15:25 force exit. The wave-level check above is an any() across
                    # all candidates, so it does not gate this one.
                    limit_time = (
                        self._configured_session_time("ut_no_entry_after", "15:00")
                        if c.timeframe == "15min"
                        else self._configured_session_time("ut_5min_no_entry_after", "15:15")
                    )
                    if not self._entry_cutoff_allows_candidate(c, session_now):
                        logger.info(
                            f"🚫 [LIVE GATE] Discarding closed-candle {c.instrument} "
                            f"{c.timeframe} {c.direction} due to entry policy ({limit_time})"
                        )
                        self._rtracker_record_candidate(
                            c,
                            decision="REJECTED",
                            reason=f"Entry cutoff policy {limit_time}",
                            source="entry_cutoff_gate",
                        )
                        continue
                    # A closed-bar arrow printing the OTHER way must still evict a stale
                    # opposite buffer. The repaint gate cannot do it: the cached signals
                    # list holds the whole session's flip history, so after a CROSS-BAR
                    # reversal the older arrow is still in that list and the stale side
                    # reads PRESENT. It then matures into a second bought leg — a long CE
                    # and a long PE on one chart, two premiums, theta against both.
                    sig_ts = getattr(c, "signal_timestamp", None)
                    if sig_ts is None:
                        cached_res = self._cached_results.get(f"{c.instrument}_{c.timeframe}")
                        if cached_res and cached_res.get("signals"):
                            target_type = "BUY" if c.direction == "LONG" else "SELL"
                            matching_sigs = [
                                s for s in cached_res["signals"] if s.signal_type == target_type
                            ]
                            if matching_sigs:
                                sig_ts = matching_sigs[-1].timestamp
                    self._evict_superseded_opposite_buffer(c, sig_ts)
                    matured_candidates.append(c)
                    self._diag_inc("stabilization", "closed_candle_direct")
                    self.log_signal_decision_once(
                        f"{c.instrument}|{c.timeframe}|{getattr(c, 'signal_timestamp', '')}|closed-direct",
                        f"{c.instrument} {c.timeframe} {c.direction}: source candle already "
                        "closed, going straight to analysis without the stabilization wait.",
                        "trade",
                    )
                    continue
                # Timeframe-Specific entry gate check
                c_time = session_now.time()
                limit_time = (
                    self._configured_session_time("ut_no_entry_after", "15:00")
                    if c.timeframe == "15min"
                    else self._configured_session_time("ut_5min_no_entry_after", "15:15")
                )
                if not self._entry_cutoff_allows_candidate(c, session_now):
                    logger.info(f"🚫 [LIVE GATE] Skipping buffering for {c.instrument} {c.timeframe} {c.direction} at {c_time} due to entry policy ({limit_time})")
                    continue

                key = f"{c.instrument}_{c.timeframe}_{c.direction}"
                if key not in self._pending_live_signals:
                    # Track the exact intrabar UT1 signal. This lets realtime
                    # signals form and repaint, but only mature if the same
                    # signal is still present after the stabilization delay.
                    sig_timestamp = getattr(c, "signal_timestamp", None)
                    cached_key = f"{c.instrument}_{c.timeframe}"
                    cached_res = self._cached_results.get(cached_key)
                    if sig_timestamp is None and cached_res and cached_res.get("signals"):
                        target_type = "BUY" if c.direction == "LONG" else "SELL"
                        matching_sigs = [s for s in cached_res["signals"] if s.signal_type == target_type]
                        if matching_sigs:
                            sig_timestamp = matching_sigs[-1].timestamp

                    self._pending_live_signals[key] = {
                        "timestamp": now,
                        "candidate": c,
                        "sig_timestamp": sig_timestamp,
                        "stable_scans": 0,
                    }
                    pending_changed = True
                    self._diag_inc("stabilization", "buffered")
                    self._evict_superseded_opposite_buffer(c, sig_timestamp)
                    stable_seconds, min_stable_scans, adaptive_stability = self._live_signal_stabilization_requirements(c)
                    scan_note = f" and {min_stable_scans} stable scans" if adaptive_stability and min_stable_scans > 1 else ""
                    logger.info(f"[STABILIZATION] Buffering {c.direction} signal for {c.instrument} {c.timeframe} for {stable_seconds:.0f}s{scan_note}...")
                    self.log_event(f"Buffering {c.direction} signal for {c.instrument} {c.timeframe} for {stable_seconds:.0f}s{scan_note}...", "system")

            if pending_changed:
                # A signal may mature before the normal 15-second checkpoint.
                # Persist immediately so a restart resumes this exact timer.
                self._save_warm_memory(force=True)

            # Step 2: Check which buffered signals have matured (held for >= 20 seconds)
            keys_to_remove = []
            for key, data in list(self._pending_live_signals.items()):
                c = data["candidate"]
                sig_timestamp = data.get("sig_timestamp")
                elapsed = (now - data["timestamp"]).total_seconds()
                tf_minutes = {"1min": 1, "5min": 5, "15min": 15}.get(str(getattr(c, "timeframe", "") or ""), 5)
                stable_seconds, min_stable_scans, adaptive_stability = self._live_signal_stabilization_requirements(c)
                max_pending_seconds = (tf_minutes * 60.0) + 90.0
                if sig_timestamp:
                    sig_time_check = sig_timestamp
                    if getattr(sig_time_check, "tzinfo", None) is not None:
                        sig_time_check = sig_time_check.astimezone(IST).replace(tzinfo=None)
                    clock_check = session_now
                    if getattr(clock_check, "tzinfo", None) is not None:
                        clock_check = clock_check.astimezone(IST).replace(tzinfo=None)
                    if sig_time_check > (clock_check + timedelta(seconds=5)):
                        logger.warning(
                            f"[STABILIZATION] Signal for {key} has future timestamp {sig_time_check} "
                            f"relative to scanner clock {clock_check}. Discarding."
                        )
                        self.log_event(f"Future-timestamp signal discarded: {key}", "warning")
                        self._diag_inc("stabilization", "discarded_future")
                        self._forget_signal_display_rows(c)
                        keys_to_remove.append(key)
                        dedup_key = f"{c.instrument}_{c.timeframe}"
                        self._last_live_signal_candle_time.pop(dedup_key, None)
                        continue

                if elapsed > max_pending_seconds:
                    logger.warning(
                        f"[STABILIZATION] Signal for {key} expired after {elapsed:.1f}s "
                        "without a stable scan cadence. Discarding stale candidate."
                    )
                    self.log_event(f"Stale buffered signal discarded: {key}", "warning")
                    self._diag_inc("stabilization", "discarded_stale")
                    self._forget_signal_display_rows(c)
                    keys_to_remove.append(key)
                    dedup_key = f"{c.instrument}_{c.timeframe}"
                    self._last_live_signal_candle_time.pop(dedup_key, None)
                    continue

                cached_key = f"{c.instrument}_{c.timeframe}"
                if data.get("recovered") and cached_key not in self._cached_results:
                    # Startup may restore the checkpoint before the first fresh
                    # indicator pass. Wait for that pass instead of declaring
                    # the restored arrow repainted from an empty cache.
                    self._diag_inc("stabilization", "waiting_fresh_scan_after_restart")
                    continue

                repaint_status = self._repaint_signal_status(c, sig_timestamp)
                still_present = repaint_status == "PRESENT"

                if not still_present:
                    override_ctx = self._stabilization_repaint_override_context(c, sig_timestamp)
                    if override_ctx:
                        setattr(c, "stabilization_momentum_override", True)
                        try:
                            c.reasons = list(c.reasons or []) + [
                                f"Repaint override: {override_ctx.get('reason', override_ctx.get('type', 'confirmed momentum'))}"
                            ]
                        except Exception:
                            pass
                        self._diag_inc("stabilization", "momentum_override")
                        logger.info(
                            f"[STABILIZATION] Re-admitting {c.instrument} {c.timeframe} {c.direction}: "
                            f"arrow flickered but {override_ctx.get('reason', 'momentum confirmed')}."
                        )
                        self.log_event(
                            f"Signal re-admitted: {c.instrument} {c.timeframe} {c.direction} "
                            f"after repaint flicker; {override_ctx.get('reason', 'momentum confirmed')}.",
                            "trade",
                        )
                    else:
                        flipped = repaint_status == "FLIPPED"
                        self._diag_inc(
                            "stabilization",
                            "discarded_flipped" if flipped else "discarded_repaint",
                        )
                        what = (
                            f"UT1 arrow FLIPPED to the opposite side after {elapsed:.1f}s"
                            if flipped
                            else f"UT1 arrow vanished after {elapsed:.1f}s"
                        )
                        logger.warning(
                            f"[STABILIZATION] Rejected {c.instrument} {c.timeframe} {c.direction}: {what}."
                        )
                        self.log_event(
                            (
                                f"Signal rejected: {c.instrument} {c.timeframe} {c.direction} "
                                f"flipped to the opposite side during the {stable_seconds:.0f}s "
                                "stabilization window; the momentum override does not apply to a reversal."
                            )
                            if flipped
                            else (
                                f"Signal rejected: {c.instrument} {c.timeframe} {c.direction} "
                                f"repainted during the {stable_seconds:.0f}s stabilization window."
                            ),
                            "warning",
                        )
                        self._rtracker_record_candidate(
                            c,
                            decision="REJECTED",
                            reason=(
                                f"Flipped to the opposite side during {stable_seconds:.0f}s "
                                "stabilization window"
                                if flipped
                                else f"Repainted during {stable_seconds:.0f}s stabilization window"
                            ),
                            source="stabilization_repaint_gate",
                        )
                        self._forget_signal_display_rows(c)
                        # The indicator has withdrawn this arrow. Withdraw it from the
                        # re-entry pool too, or the missed-signal path re-admits the same
                        # discarded signal within seconds.
                        self._drop_missed_reentry_seed(
                            c,
                            reason=(
                                "arrow flipped to the opposite side"
                                if flipped
                                else "arrow vanished during stabilization"
                            ),
                        )
                        keys_to_remove.append(key)
                        dedup_key = f"{c.instrument}_{c.timeframe}"
                        identity = f"{sig_timestamp.replace(tzinfo=None).isoformat()}|{getattr(c, 'source_signal_type', '')}" if sig_timestamp else ""
                        last_signal_identity = getattr(self, "_last_signal_identity", {})
                        if last_signal_identity.get(dedup_key) == identity:
                            last_signal_identity.pop(dedup_key, None)
                            self._last_signal_time[dedup_key] = sig_timestamp.replace(tzinfo=None) - timedelta(microseconds=1)
                        self._candidate_process_cache.pop(c.instrument, None)
                        raw_key = (
                            f"{c.instrument}|{c.timeframe}|{getattr(c, 'source_signal_type', '')}|"
                            f"{sig_timestamp.replace(tzinfo=None).isoformat(timespec='seconds')}"
                            if sig_timestamp
                            else ""
                        )
                        if raw_key:
                            getattr(self, "_raw_utbot_activity_keys", set()).discard(raw_key)
                        continue

                data["stable_scans"] = int(data.get("stable_scans") or 0) + 1
                stable_scans = int(data.get("stable_scans") or 0)

                if data.pop("recovered", False):
                    logger.info(
                        f"[STABILIZATION] Resumed {c.instrument} {c.timeframe} {c.direction} "
                        f"after restart with {elapsed:.1f}s already elapsed."
                    )
                    self.log_event(
                        f"Resumed signal buffer after restart: {c.instrument} {c.timeframe} "
                        f"{c.direction}, {elapsed:.1f}s already stable.",
                        "system",
                    )

                if not self._stabilization_ready(
                    elapsed,
                    stable_seconds,
                    stable_scans,
                    min_stable_scans,
                    adaptive_stability,
                ):
                    self._maybe_prepare_stabilization_preflight(
                        key,
                        c,
                        elapsed,
                        stable_seconds,
                    )
                    self._diag_inc("stabilization", "waiting_stability")
                    continue

                c_time = session_now.time()
                limit_time = (
                    self._configured_session_time("ut_no_entry_after", "15:00")
                    if c.timeframe == "15min"
                    else self._configured_session_time("ut_5min_no_entry_after", "15:15")
                )
                if not self._entry_cutoff_allows_candidate(c, session_now):
                    logger.info(f"🚫 [LIVE GATE] Discarding matured signal for {key} due to entry policy ({limit_time})")
                    self._rtracker_record_candidate(
                        c,
                        decision="REJECTED",
                        reason=f"Entry cutoff policy {limit_time}",
                        source="entry_cutoff_gate",
                    )
                    keys_to_remove.append(key)
                    dedup_key = f"{c.instrument}_{c.timeframe}"
                    self._last_live_signal_candle_time.pop(dedup_key, None)
                    continue

                logger.success(f"✅ [STABILIZATION] Signal for {key} matured after {elapsed:.1f}s. Proceeding to execute.")
                self._apply_stabilization_preflight(key, c)
                self._diag_inc("stabilization", "matured")
                # Record the SURVIVING side too. Rejections were already written here,
                # so rtracker held only the deaths and no survival rate was computable
                # from it — on 2026-08-11 the log showed 48 maturations against 9
                # ACCEPTED rows, because most matured signals are refused further down
                # and never reach an acceptance record. STABILIZED is its own decision
                # so it cannot be mistaken for an entry in the funnel arithmetic.
                if self._setting_enabled(
                    getattr(get_settings(), "stabilization_rtracker_logging_enabled", True), True
                ):
                    self._rtracker_record_candidate(
                        c,
                        decision="STABILIZED",
                        reason=(
                            f"Survived the {stable_seconds:.0f}s stabilization window "
                            f"in {elapsed:.1f}s"
                        ),
                        source="stabilization_gate",
                        extra={
                            "stabilization": {
                                "window_seconds": round(float(stable_seconds or 0.0), 1),
                                "elapsed_seconds": round(float(elapsed or 0.0), 1),
                                "momentum_override": bool(
                                    getattr(c, "stabilization_momentum_override", False)
                                ),
                                "cascade_latched": bool(
                                    getattr(c, "_stabilization_cascade_latch", None)
                                ),
                            }
                        },
                    )
                self.log_event(
                    f"UT1 {c.direction} {c.instrument} {c.timeframe} stayed valid for {elapsed:.1f}s. Running filters.",
                    "trade",
                )
                matured_candidates.append(c)
                keys_to_remove.append(key)
                if sig_timestamp:
                    dedup_key = f"{c.instrument}_{c.timeframe}"
                    self._last_signal_time[dedup_key] = max(self._last_signal_time.get(dedup_key, datetime.min), sig_timestamp)

            for key in keys_to_remove:
                self._pending_live_signals.pop(key, None)
                getattr(self, "_signal_preflight_cache", {}).pop(key, None)
            if keys_to_remove:
                # Prevent a rejected or matured buffer from being resurrected
                # if another restart happens before the periodic checkpoint.
                self._save_warm_memory(force=True)

            candidates = matured_candidates
            if not candidates:
                return accepted_candidates

        # â”€â”€ Institutional Execution Gate â”€â”€
        if not self.data.is_market_open() and not is_warmup:
            # Don't place new trades if market is closed (except in Historical mode)
            if self.mode != "HISTORICAL":
                if self.scan_count % 100 == 0:
                    logger.debug("â³ Execution Gate: Market is closed. Analysis only.")
                return accepted_candidates

        # Same-wave heavy-trend votes: register peers before mixed-book / sizing
        # so 2/4 align does not lag one scan cycle (R3).
        try:
            self._ingest_wave_heavy_trend_votes(list(candidates or []))
        except Exception:
            pass

        # Multi-engine / multi-TF / multi-index wave:
        # collapse best TF per index, assign at most 1× FUT (1 lot), rest OPT.
        try:
            candidates = self._apply_multi_signal_mixed_book(list(candidates or []))
        except Exception as mix_exc:
            logger.warning(f"Multi-signal mixed book skipped: {mix_exc}")

        # Final product lock: even single-index paths must honor FUT/OPT-only.
        try:
            candidates = self._apply_strict_instrument_pref_to_entries(list(candidates or []))
        except Exception as pref_exc:
            # Fail closed: this is the terminal product lock — never execute an
            # un-enforced wave. Under a FUT/OPT lock, drop every ENTRY whose product
            # does not already match the lock rather than passing the pre-gate list
            # through to open_trade. Exits/non-ENTRY rows are preserved.
            logger.warning(f"Strict instrument preference pass raised; failing closed: {pref_exc}")
            _lock = self._strict_instrument_pref()
            if _lock in {"FUT", "OPT"}:
                def _matches_lock(c):
                    if str(getattr(c, "action", "ENTRY") or "ENTRY").upper() != "ENTRY":
                        return True
                    it = str(getattr(c, "inst_type", "") or "").upper()
                    if it in {"CE", "PE"}:
                        it = "OPT"
                    return it == _lock
                candidates = [c for c in (candidates or []) if _matches_lock(c)]

        # OPT contract safety net: an ENTRY claiming OPT must carry a resolved
        # option contract (rare dual-TF clones can flip a FUT winner's sibling
        # to OPT with futures fields still attached).
        try:
            candidates = self._resolve_unbuilt_opt_entries(list(candidates or []))
        except Exception as _opt_net_exc:
            logger.warning(f"OPT contract safety net skipped: {_opt_net_exc}")

        # R4: arm global position ceiling for cascade multi-TF batch
        try:
            cascade_wave = any(
                bool(getattr(c, "one_way_cascade_entry", False))
                for c in (candidates or [])
                if getattr(c, "action", "ENTRY") == "ENTRY"
            )
            arm = getattr(getattr(self, "trades", None), "arm_cascade_wave_capacity", None)
            if callable(arm):
                arm(cascade_wave)
        except Exception:
            pass

        # Group candidates by direction
        by_dir = {"LONG": [], "SHORT": []}
        for c in candidates:
            by_dir[c.direction].append(c)

        for direction, signals in by_dir.items():
            if not signals: continue

            # Sort by Score/Confidence
            signals.sort(key=lambda x: x.confidence, reverse=True)
            open_count = len(self.trades.open_trades)

            # â•â•â• CROSS-INSTRUMENT CORRELATION GUARD â•â•â•
            # Rules:
            # 1. Max 2 concurrent trades per index.
            # 2. Every separate index receives its own complete eligibility pass.

            for i, sig in enumerate(signals):
                total_open = len(self.trades.open_trades)

                signal_type = "BUY" if str(getattr(sig, "direction", "") or "").upper() == "LONG" else "SELL"
                signal_time_for_reversal = getattr(sig, "signal_timestamp", None)
                one_way_cascade = self._one_way_cascade_context(
                    sig.instrument,
                    sig.timeframe,
                    signal_type,
                    signal_time_for_reversal,
                )
                if one_way_cascade:
                    setattr(sig, "one_way_cascade_entry", True)
                    setattr(sig, "one_way_cascade_context", one_way_cascade)
                    try:
                        sig.reasons = list(sig.reasons or []) + [
                            (
                                f"{one_way_cascade.get('reason', 'one-way cascade')}: "
                                f"{', '.join(one_way_cascade.get('indices', []))}"
                            )
                        ]
                    except Exception:
                        pass
                market_wide_reversal = self._market_wide_reversal_context(
                    sig.instrument,
                    sig.timeframe,
                    signal_type,
                    signal_time_for_reversal,
                )
                if market_wide_reversal:
                    setattr(sig, "market_wide_reversal_entry", True)
                    setattr(sig, "market_wide_reversal_context", market_wide_reversal)
                    try:
                        sig.reasons = list(sig.reasons or []) + [
                            (
                                f"{market_wide_reversal.get('reason', 'market-wide reversal')}: "
                                f"{', '.join(market_wide_reversal.get('indices', []))}"
                            )
                        ]
                    except Exception:
                        pass
                market_ltp_shock = self._evaluate_market_ltp_shock(
                    sig.instrument,
                    signal_type,
                    signal_time_for_reversal,
                    timeframe=str(getattr(sig, "timeframe", "") or ""),
                )
                if market_ltp_shock:
                    setattr(sig, "market_ltp_shock_entry", True)
                    setattr(sig, "market_ltp_shock_context", market_ltp_shock)
                    try:
                        sig.reasons = list(sig.reasons or []) + [
                            (
                                f"{market_ltp_shock.get('reason', 'market LTP shock')}: "
                                f"{', '.join(market_ltp_shock.get('indices', []))}"
                            )
                        ]
                    except Exception:
                        pass

                # â”€â”€ Grade Preference Filter â”€â”€
                settings = get_settings()
                grade_pref = self._normalize_signal_grade_preference(getattr(settings, "signal_grade_preference", "auto"))

                grade_hierarchy = {"C": 0, "B": 1, "B+": 2, "A": 3, "A+": 4}
                base_grade = sig.grade.split()[0] if isinstance(sig.grade, str) else "C"
                sig_rank = grade_hierarchy.get(base_grade, 0)

                # Dynamic Regime-Aware minimum grade preference
                current_regime = self.latest_regimes.get(sig.instrument, "UNKNOWN")
                regime_adaptation = self._setting_enabled(getattr(settings, "ut_regime_adaptation", True), True)
                is_choppy = regime_adaptation and current_regime in {"CHOPPY", "SIDEWAYS", "MEAN_REVERTING", "RANGING", "VOLATILE", "UNKNOWN"}

                if grade_pref == "B":
                    # Futures allow B (Rank 1), Options require B+ (Rank 2)
                    min_rank = 1 if sig.inst_type == "FUT" else 2
                elif grade_pref == "B+":
                    min_rank = 2
                elif grade_pref == "A":
                    min_rank = 3
                elif grade_pref == "A+":
                    min_rank = 4
                else: # auto
                    # Dynamic upgrade to A/A+ under chops, baseline is B+
                    min_rank = 3 if is_choppy else 2

                grade_allowed, grade_preference_reason = self._passes_candidate_grade_preference(sig)
                if not grade_allowed:
                    reason_str = ", ".join(sig.reasons) if sig.reasons else "Low confidence"
                    rejection_reason = grade_preference_reason
                    self.log_event(f"🚫 Signal Rejected: {sig.instrument} {sig.direction} ({sig.grade}) - {rejection_reason} | Reasons: {reason_str}", "trade")
                    logger.info(f"🚫 Signal Rejected: {sig.instrument} {sig.direction} ({sig.grade}) - {rejection_reason} | Reasons: {reason_str}")
                    self._rtracker_record_candidate(
                        sig,
                        decision="REJECTED",
                        reason=rejection_reason,
                        source="grade_preference_gate",
                    )
                    self._remember_missed_reentry_seed(
                        sig,
                        reason=rejection_reason,
                        source="grade_preference_gate",
                    )
                    continue

                signal_time = getattr(sig, "signal_timestamp", None) or datetime.now(IST).replace(tzinfo=None)
                if getattr(signal_time, "tzinfo", None) is not None:
                    signal_time = signal_time.astimezone(IST).replace(tzinfo=None)
                allowed, limit_reason = self._can_trade_instrument(
                    sig.instrument, signal_time,
                    direction=str(getattr(sig, "direction", "") or ""),
                    adx_value=float(getattr(sig, "adx_value", 0.0) or 0.0),
                )
                if not allowed:
                    self.log_signal_decision_once(
                        f"{sig.instrument}|{sig.timeframe}|{sig.direction}|{signal_time.isoformat()}|trade-limit",
                        f"Signal rejected: {sig.instrument} {sig.direction} - {limit_reason}",
                        "trade",
                    )
                    self._rtracker_record_candidate(
                        sig,
                        decision="REJECTED",
                        reason=limit_reason,
                        source="trade_limit_gate",
                    )
                    continue

                if not self._passes_live_trade_ready_gate(sig):
                    ts = getattr(sig, "signal_timestamp", None)
                    ts_key = ts.isoformat(timespec="seconds") if ts else ""
                    self.log_signal_decision_once(
                        f"{sig.instrument}|{sig.timeframe}|{sig.direction}|{ts_key}|live-ready",
                        f"Signal rejected: {sig.instrument} {sig.direction} {sig.timeframe} - live trade readiness gate blocked it",
                        "trade",
                    )
                    self._rtracker_record_candidate(
                        sig,
                        decision="REJECTED",
                        reason="Live trade readiness gate blocked it",
                        source="live_ready_gate",
                    )
                    self._remember_missed_reentry_seed(
                        sig,
                        reason="Live trade readiness gate blocked it",
                        source="live_ready_gate",
                    )
                    continue

                if not self._candidate_quote_ready_for_lifecycle(sig):
                    ts = getattr(sig, "signal_timestamp", None)
                    ts_key = ts.isoformat(timespec="seconds") if ts else ""
                    self.log_signal_decision_once(
                        f"{sig.instrument}|{sig.timeframe}|{sig.direction}|{ts_key}|quote-unverified",
                        (
                            f"Signal rejected: {sig.instrument} {sig.direction} {sig.timeframe} - "
                            "quote unavailable; waiting for verified option premium before lifecycle acceptance"
                        ),
                        "trade",
                    )
                    sig.status = "QUOTE UNAVAILABLE"
                    self._rtracker_record_candidate(
                        sig,
                        decision="REJECTED",
                        reason="Quote unavailable before lifecycle acceptance",
                        source="quote_ready_gate",
                    )
                    continue

                if self._absorb_same_direction_session_refresh(sig):
                    ts = getattr(sig, "signal_timestamp", None)
                    ts_key = ts.isoformat(timespec="seconds") if ts else ""
                    self.log_signal_decision_once(
                        f"{sig.instrument}|{sig.timeframe}|{sig.direction}|{ts_key}|same-side-refresh",
                        f"Signal refreshed existing {sig.instrument} {sig.direction} {sig.timeframe} lifecycle; no new entry submitted",
                        "trade",
                    )
                    self._rtracker_record_candidate(
                        sig,
                        decision="REFRESHED",
                        reason="Same-side lifecycle refresh; no new entry submitted",
                        source="same_side_refresh",
                    )
                    continue

                # Per-Instrument Safety (Cross-TF Complementary Rule)
                if not self._prepare_candidate_for_concurrency(sig):
                    # A duplicate on a chart that is already working is not noise to throw
                    # away — it is the cascade confirming itself. Before dropping it, offer
                    # it to the running trade as one more lot. scale_in_trade owns every
                    # rule about whether that is allowed (already in profit, still with
                    # trend, add cap, lot ceiling, rupee risk budget) and refuses with a
                    # reason when it is not; this only decides WHEN to ask.
                    #
                    # MANUAL MODE MUST NOT REACH THE BROKER. This call site sits 51 lines
                    # ABOVE the `if not self.auto_mode` gate that stops every ordinary
                    # entry, and nothing below it re-checks: trade_manager.py contains no
                    # reference to auto_mode at all, and scale_in_trade branches only on
                    # mode == "REAL" before placing a live BUY on the running contract.
                    # An operator with auto mode off, expecting to approve each entry from
                    # the toast, would have had a lot added to a live position with no
                    # approval. Inert today only because scale_in_enabled is False -- which
                    # is exactly the switch this feature exists to be turned on by.
                    if not self.auto_mode and not is_warmup:
                        self.log_signal_decision_once(
                            f"{sig.instrument}|{sig.timeframe}|{sig.direction}|manual-cascade",
                            f"{sig.instrument} {sig.timeframe} {sig.direction}: cascade add "
                            "available but manual mode is on — approve it yourself.",
                            "trade",
                        )
                        added, add_note = False, "manual mode: cascade add not auto-executed"
                    else:
                        added, add_note = self._offer_cascade_add(sig)
                    if added:
                        continue
                    ts = getattr(sig, "signal_timestamp", None)
                    ts_key = ts.isoformat(timespec="seconds") if ts else ""
                    if add_note:
                        self.log_signal_decision_once(
                            f"{sig.instrument}|{sig.timeframe}|{sig.direction}|{ts_key}|cascade-add",
                            f"{sig.instrument} {sig.timeframe} {sig.direction}: cascade add "
                            f"declined ({add_note})",
                            "trade",
                        )
                    self.log_signal_decision_once(
                        f"{sig.instrument}|{sig.timeframe}|{sig.direction}|{ts_key}|concurrency",
                        f"Signal rejected: {sig.instrument} {sig.direction} {sig.timeframe} - concurrency guard blocked it",
                        "trade",
                    )
                    self._rtracker_record_candidate(
                        sig,
                        decision="REJECTED",
                        reason="Concurrency guard blocked it",
                        source="concurrency_gate",
                    )
                    continue

                # Per-bucket concurrent capacity: normal 4x2, rare burst 4x3 only
                # with all-index 95%+/volume/ADX confirmation.
                if not self._bucket_capacity_allows(sig):
                    bucket = self._correlated_index_bucket(sig.instrument)
                    ts = getattr(sig, "signal_timestamp", None)
                    ts_key = ts.isoformat(timespec="seconds") if ts else ""
                    self.log_signal_decision_once(
                        f"{sig.instrument}|{sig.timeframe}|{sig.direction}|{ts_key}|bucket-capacity",
                        f"Signal rejected: {sig.instrument} {sig.direction} {sig.timeframe} - "
                        f"{bucket} bucket at capacity ({self._active_bucket_cap(bucket)} trades)",
                        "trade",
                    )
                    self._rtracker_record_candidate(
                        sig,
                        decision="REJECTED",
                        reason=f"{bucket} bucket at capacity",
                        source="bucket_capacity_gate",
                    )
                    continue

                # Every index receives an independent pass; only same-index overlap is restricted.
                can_take = self._passes_correlated_index_guard(sig, direction)

                if can_take:
                    self._ensure_trade_like_initial_stop(sig)
                    # â”€â”€â”€ Manual Signal Gate â”€â”€â”€
                    if not self.auto_mode and not is_warmup:
                        # The auto path reaches open_trade, which reprices via
                        # _execution_levels and validates the mark. This one does not, so
                        # the same question is asked here: is the price we are about to
                        # record still real? See _candidate_entry_mark_refusal.
                        stale_mark = self._candidate_entry_mark_refusal(sig)
                        if stale_mark:
                            sig.status = "NO ENTRY - Stale entry mark"
                            self.log_signal_decision_once(
                                f"{sig.instrument}|{sig.timeframe}|{sig.direction}|{ts_key}|stale-mark",
                                f"Signal rejected: {sig.instrument} {sig.direction} "
                                f"{sig.timeframe} - {stale_mark}",
                                "trade",
                            )
                            self._rtracker_record_candidate(
                                sig,
                                decision="REJECTED",
                                reason=f"Stale entry mark: {stale_mark}",
                                source="entry_mark_gate",
                            )
                            self._remember_trade_candidates([sig])
                            continue
                        self._close_superseded_session_entries([sig])
                        self._latest_trade_candidates[sig.instrument] = [sig]
                        setattr(sig, "accepted_by_gate", True)
                        self._mark_candidate_accepted_time(sig, datetime.now(IST))
                        self._remember_trade_candidates([sig])
                        accepted_candidates.append(sig)
                        self._record_accepted_entry(sig)
                        await self._publish_trade_payload_now()
                        if i == 0: # Only notify for the primary candidate
                            logger.info(f"📣 MANUAL SIGNAL: {sig.direction} {sig.instrument} @ {sig.price} (Auto Mode: Manual)")
                            self.log_event(f"🎯 Manual {sig.direction} Signal: {sig.instrument} @ {sig.price:.2f}", "trade")
                            self._notify(f"🎯 MANUAL SIGNAL: {sig.direction} {sig.instrument} @ {sig.price:.2f}. Auto-execution disabled.", "info")
                            
                            try:
                                nm = get_notification_manager(asyncio.get_running_loop())
                                execution_loop = asyncio.get_running_loop()
                                
                                def make_executor(candidate_sig, is_ghost=False):
                                    def do_execute():
                                        # Instrument-lock parity with execute_manual_signal (1320):
                                        # this deferred click may fire after the operator switched
                                        # the FUT/OPT preference, so re-enforce the lock at execution
                                        # time. Ghosts are virtual and never reach the broker.
                                        if not is_ghost:
                                            pref_ok, pref_why = self._enforce_strict_instrument_pref_on_candidate(candidate_sig)
                                            if not pref_ok:
                                                candidate_sig.status = f"BLOCKED - {self._strict_instrument_pref()} PREF ({pref_why})"
                                                return
                                        exec_price, exec_stop, exec_target = self._execution_levels(candidate_sig)
                                        if exec_price <= 0:
                                            candidate_sig.status = "QUOTE UNAVAILABLE"
                                            return
                                        execution_touch_quote = self._candidate_execution_touch_quote(candidate_sig)
                                        actual_spot = self.candles.get_latest_price(candidate_sig.instrument)
                                        
                                        def on_execution_result(executed_trade, accepted, candidate=candidate_sig):
                                            asyncio.run_coroutine_threadsafe(
                                                self._handle_broker_entry_result(candidate, executed_trade, accepted),
                                                execution_loop,
                                            )

                                        trade = self.trades.open_trade(
                                            instrument=candidate_sig.instrument, timeframe=candidate_sig.timeframe, direction=candidate_sig.direction,
                                            price=exec_price, trailing_stop=exec_stop,
                                            lots=candidate_sig.lots, lot_size=candidate_sig.lot_size, grade=candidate_sig.grade,
                                            atm_strike=candidate_sig.atm_strike, option_type=candidate_sig.option_type,
                                            target=exec_target,
                                            rr_ratio=candidate_sig.rr,
                                            confidence=candidate_sig.confidence,
                                            instrument_multiplier=candidate_sig.multiplier,
                                            trading_symbol=candidate_sig.trading_symbol,
                                            symbol_token=candidate_sig.symbol_token,
                                            inst_type=candidate_sig.inst_type,
                                            market_regime=str(getattr(candidate_sig, "market_regime", "") or ""),
                                            entry_momentum_urgency=self._entry_momentum_urgency(candidate_sig),
                                            exec_type="M",
                                            entry_spot=actual_spot,
                                            spot_stop=candidate_sig.stop,
                                            spot_target=candidate_sig.target,
                                            is_explosive_bypass=bool(getattr(candidate_sig, "is_explosive_bypass", False)),
                                            is_reversion_scalp=bool(getattr(candidate_sig, "is_reversion_scalp", False)),
                                            is_recovery=False,
                                            is_ghost=is_ghost,
                                            entry_time=datetime.now(IST),
                                            signal_time=getattr(candidate_sig, "signal_timestamp", None),
                                            signal_fire_mode=getattr(candidate_sig, "signal_fire_mode", signal_fire_mode),
                                            entered_intracandle=bool(getattr(candidate_sig, "entered_intracandle", False)),
                                            market_wide_reversal_entry=bool(getattr(candidate_sig, "market_wide_reversal_entry", False)),
                                            volume_spike_entry=bool(getattr(candidate_sig, "volume_spike_entry", False)),
                                            power_move=bool(getattr(candidate_sig, "power_move", False)),
                                            source_engine=str(getattr(candidate_sig, "source_engine", "") or ""),
                                            source_engines=list(getattr(candidate_sig, "source_engines", []) or []),
                                            source_lane=str(getattr(candidate_sig, "source_lane", "") or ""),
                                            quad_union_entry=bool(getattr(candidate_sig, "quad_union_entry", False)),
                                            raw_union_entry=bool(getattr(candidate_sig, "raw_union_entry", False)),
                                            initial_stop=exec_stop,
                                            scalp_lock_mode=bool(getattr(candidate_sig, "scalp_lock_mode", False)),
                                            execution_touch_quote=execution_touch_quote,
                                            on_execution_result=on_execution_result,
                                        )
                                        if trade:
                                            trade.is_live = (self.mode == "REAL")
                                            candidate_sig.status = "ORDER PENDING" if not is_ghost else "GHOST WATCH"
                                            asyncio.create_task(self._publish_trade_payload_now())
                                            
                                    return do_execute

                                def make_watcher(candidate_sig):
                                    def do_watch():
                                        candidate_sig.status = "WATCHING"
                                        setattr(candidate_sig, "watch_only", True)
                                        self._remember_trade_candidates([candidate_sig])
                                        self.log_event(
                                            f"Watching {candidate_sig.instrument} {candidate_sig.direction} "
                                            f"{candidate_sig.timeframe} without broker execution.",
                                            "trade",
                                        )
                                        asyncio.create_task(self._publish_trade_payload_now())

                                    return do_watch
                                
                                nm.send_trade_notification(
                                    signal_type="BUY" if sig.inst_type == "OPT" else ("BUY" if sig.direction == "LONG" else "SELL"),
                                    instrument=sig.instrument,
                                    entry_price=sig.price,
                                    target_price=sig.target,
                                    sl_price=sig.stop,
                                    rr_ratio=sig.rr,
                                    grade=sig.grade,
                                    confidence=getattr(sig, 'confidence', 0.0) * 100,
                                    timeframe=sig.timeframe,
                                    on_execute=make_executor(sig, is_ghost=False),
                                    on_watch=make_watcher(sig)
                                )
                            except Exception as e:
                                logger.error(f"Failed to dispatch toast notification: {e}")
                                
                        continue # Don't take the trade in manual mode

                    # TradeManager.open_trade is the single broker execution path.
                    actual_spot = self.candles.get_latest_price(sig.instrument)
                    
                    sig_ts = getattr(sig, "signal_timestamp", None)
                    sig_ts_str = sig_ts.strftime('%H:%M:%S') if sig_ts else "--:--:--"
                    exec_ts_str = datetime.now(IST).strftime('%H:%M:%S')
                    logger.info(f"⏱️ Exact Execution Trigger: Signal={sig_ts_str} + 20s Buffer + Latency -> Entry={exec_ts_str}")
                    
                    # Resolve entries in the traded contract's price space.
                    exec_price, exec_stop, exec_target = self._execution_levels(sig)
                    if exec_price <= 0:
                        sig.status = "QUOTE UNAVAILABLE"
                        self.log_event(
                            f"Signal blocked: {sig.instrument} {sig.trading_symbol} has no verified live premium",
                            "warning",
                        )
                        self._rtracker_record_candidate(
                            sig,
                            decision="REJECTED",
                            reason="No verified live premium at execution",
                            source="execution_quote_gate",
                        )
                        continue
                    execution_touch_quote = self._candidate_execution_touch_quote(sig)
                    spot_stop = sig.stop
                    spot_target = sig.target

                    execution_loop = asyncio.get_running_loop()

                    def on_execution_result(executed_trade, accepted, candidate=sig):
                        asyncio.run_coroutine_threadsafe(
                            self._handle_broker_entry_result(candidate, executed_trade, accepted),
                            execution_loop,
                        )

                    trade = self.trades.open_trade(
                        instrument=sig.instrument, timeframe=sig.timeframe, direction=sig.direction,
                        price=exec_price, trailing_stop=exec_stop,
                        lots=sig.lots, lot_size=sig.lot_size, grade=sig.grade,
                        atm_strike=sig.atm_strike, option_type=sig.option_type,
                        target=exec_target,
                        rr_ratio=sig.rr,
                        confidence=sig.confidence,
                        instrument_multiplier=sig.multiplier,
                        trading_symbol=sig.trading_symbol,
                        symbol_token=sig.symbol_token,
                        inst_type=sig.inst_type,
                        market_regime=str(getattr(sig, "market_regime", "") or ""),
                        entry_momentum_urgency=self._entry_momentum_urgency(sig),
                        exec_type="A",
                        entry_spot=actual_spot,
                        spot_stop=spot_stop,
                        spot_target=spot_target,
                        is_reversion_scalp=bool(getattr(sig, "is_reversion_scalp", False)),
                        # A fresh entry is NEVER a recovery. This passed is_warmup, which
                        # only means the scanner is still loading data — unrelated. When
                        # true, can_open_trade skips BOTH the orphan block and the
                        # max-concurrent-positions cap, and the trade is written
                        # execution_status="OPEN" with pending_execution=False, i.e.
                        # already established rather than awaiting a fill. Auto Mode is
                        # not persisted, so an operator re-enabling it seconds after a
                        # restart lands squarely inside _background_initial_setup.
                        # The other two open_trade call sites both pass False.
                        is_recovery=False,
                        entry_time=datetime.now(IST),
                        signal_time=getattr(sig, "signal_timestamp", None),
                        signal_fire_mode=getattr(sig, "signal_fire_mode", signal_fire_mode),
                        entered_intracandle=bool(getattr(sig, "entered_intracandle", False)),
                        market_wide_reversal_entry=bool(getattr(sig, "market_wide_reversal_entry", False)),
                        volume_spike_entry=bool(getattr(sig, "volume_spike_entry", False)),
                        power_move=bool(getattr(sig, "power_move", False)),
                        source_engine=str(getattr(sig, "source_engine", "") or ""),
                        source_engines=list(getattr(sig, "source_engines", []) or []),
                        source_lane=str(getattr(sig, "source_lane", "") or ""),
                        quad_union_entry=bool(getattr(sig, "quad_union_entry", False)),
                        raw_union_entry=bool(getattr(sig, "raw_union_entry", False)),
                        initial_stop=exec_stop,
                        scalp_lock_mode=bool(getattr(sig, "scalp_lock_mode", False)),
                        execution_touch_quote=execution_touch_quote,
                        on_execution_result=on_execution_result,
                    )

                    if trade:
                        trade.is_live = (self.mode == "REAL")
                        setattr(sig, "accepted_by_gate", False)
                        self._mark_candidate_accepted_time(sig, getattr(trade, "entry_time", None))
                        sig.status = "ORDER PENDING"
                        await self._publish_trade_payload_now()
                        open_count += 1
                        continue

                    if trade:
                        self._close_superseded_session_entries([sig])
                        self._latest_trade_candidates[sig.instrument] = [sig]
                        setattr(sig, "accepted_by_gate", True)
                        self._mark_candidate_accepted_time(sig, getattr(trade, "entry_time", None))
                        self._remember_trade_candidates([sig])
                        accepted_candidates.append(sig)
                        self._record_accepted_entry(sig, trade)
                        await self._publish_trade_payload_now()
                        open_count += 1

                        self._notify(
                            f"{'🟢' if sig.direction == 'LONG' else '🔴'} {sig.direction} {sig.instrument} "
                            f"@ {sig.price:.2f} | Conf: {sig.confidence:.0%} | TF: {sig.timeframe}",
                            "buy" if sig.direction == "LONG" else "sell"
                        )
                else:
                    ts = getattr(sig, "signal_timestamp", None)
                    ts_key = ts.isoformat(timespec="seconds") if ts else ""
                    self.log_signal_decision_once(
                        f"{sig.instrument}|{sig.timeframe}|{sig.direction}|{ts_key}|correlation",
                        f"Signal rejected: {sig.instrument} {sig.direction} {sig.timeframe} - correlated-index exposure limit reached",
                        "trade",
                    )
                    self._rtracker_record_candidate(
                        sig,
                        decision="REJECTED",
                        reason="Correlated-index exposure limit reached",
                        source="correlation_gate",
                    )
                    logger.info(
                        f"Correlation Guard rejected {sig.instrument} {sig.direction} "
                        f"(Current {direction} Exposure: {open_count})"
                    )

    # â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
    # CHART BUILDER — uses CACHED results (zero re-processing)
    # â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
        return accepted_candidates


    def _overbought_oversold(self, instrument: str) -> str:
        """RSI(14) overbought/oversold for the index — replaces the non-functional
        Adv/Dec 'market breadth' (which needs broad-market stock data this 4-index
        algo doesn't have). Computed on 5min closes, same RSI as the regime pillar."""
        try:
            df = self.candles.get_candles(instrument, "5min")
            if df is None or len(df) < 20 or "close" not in getattr(df, "columns", []):
                return "--"
            close = df["close"].astype(float)
            delta = close.diff()
            gain = delta.where(delta > 0, 0.0).rolling(14).mean()
            loss = (-delta.where(delta < 0, 0.0)).rolling(14).mean()
            rs = gain / loss
            last = rs.iloc[-1]
            rsi = float(100 - (100 / (1 + last))) if not pd.isna(last) else 50.0
            if rsi >= 70:
                state = "Overbought"
            elif rsi <= 30:
                state = "Oversold"
            else:
                state = "Neutral"
            return f"RSI {rsi:.0f} · {state}"
        except Exception:
            return "--"

    def _vwap_deviation(self, instrument: str) -> str:
        """Intraday VWAP deviation: how far price sits above/below the session VWAP
        (the institutional benchmark). Positive = price above VWAP (bullish control)."""
        try:
            df = self.candles.get_candles(instrument, "5min")
            if df is None or len(df) < 3 or "volume" not in getattr(df, "columns", []):
                return "--"
            day = df.index[-1].date()
            d = df[df.index.date == day]
            if len(d) < 2 or float(d["volume"].sum()) <= 0:
                return "--"
            tp = (d["high"].astype(float) + d["low"].astype(float) + d["close"].astype(float)) / 3.0
            vwap = (tp * d["volume"].astype(float)).cumsum() / d["volume"].astype(float).cumsum()
            last_vwap = float(vwap.iloc[-1])
            price = float(d["close"].iloc[-1])
            if last_vwap <= 0:
                return "--"
            dev = (price - last_vwap) / last_vwap * 100.0
            return f"{dev:+.2f}% {'above' if dev >= 0 else 'below'}"
        except Exception:
            return "--"

    def _market_status(self) -> Dict[str, Any]:
        """Operator-facing market status/reason for the dashboard (P2 observability)."""
        try:
            now_ist = datetime.now(IST)
            is_open = bool(self.data.is_market_open(now_ist)) if hasattr(self.data, "is_market_open") else False
        except Exception:
            now_ist = datetime.now(IST)
            is_open = False
        if is_open:
            reason = "Market open"
        elif now_ist.weekday() >= 5:
            reason = "Market closed (weekend)"
        elif self._is_real_mode_premarket_arm_window(now_ist):
            reason = "Pre-open arming window (REAL allowed; trading starts 09:18 IST)"
        elif now_ist.time() < dtime(9, 15):
            reason = "Pre-open (REAL arming starts 09:00:00 IST; market opens 09:15 IST)"
        elif now_ist.time() > dtime(15, 30):
            reason = "Market closed (after hours)"
        else:
            reason = "Market closed (holiday or feed unavailable)"
        return {"open": is_open, "reason": reason, "as_of": now_ist.isoformat()}

    def get_latest_results(self, include_full_charts: bool = False) -> Dict:
        """Return the latest dashboard payload, optionally rehydrating full chart history."""
        if not include_full_charts or not self.latest_results:
            snapshot = dict(self.latest_results or {})
            snapshot["market_status_detail"] = self._market_status()
            snapshot["calibration"] = self.outcome_calibration.validation_status()
            if not getattr(self, "chart_stream_enabled", True) and snapshot.get("instruments"):
                instruments = {}
                for name, ui_data in snapshot.get("instruments", {}).items():
                    if isinstance(ui_data, dict):
                        hydrated_ui = dict(ui_data)
                        hydrated_ui["chart"] = {}
                        instruments[name] = hydrated_ui
                    else:
                        instruments[name] = ui_data
                snapshot["instruments"] = instruments
            return snapshot

        active_inst = getattr(self, "active_chart_instrument", "NIFTY")
        active_tf = getattr(self, "active_chart_tf", "5min")

        snapshot = dict(self.latest_results)
        instruments = {}
        for name, ui_data in snapshot.get("instruments", {}).items():
            if not isinstance(ui_data, dict):
                instruments[name] = ui_data
                continue

            hydrated_ui = dict(ui_data)
            chart = dict(hydrated_ui.get("chart", {}))
            for tf in ["1min", "5min", "15min"]:
                if name == active_inst and tf == active_tf:
                    cached = getattr(self, f"chart_cache_{name}_{tf}", None)
                    if cached and cached.get("data"):
                        chart[tf] = cached["data"]
                else:
                    chart[tf] = {
                        "candles": [],
                        "trailing_stop": [],
                        "markers": [],
                        "state": {},
                        "intel_history": {}
                    }
            hydrated_ui["chart"] = chart
            instruments[name] = hydrated_ui

        snapshot["instruments"] = instruments
        snapshot["market_status_detail"] = self._market_status()
        snapshot["calibration"] = self.outcome_calibration.validation_status()
        return snapshot

    def generate_daily_signal_report(self, date_str: Optional[str] = None) -> Dict[str, Any]:
        """Build and save a daily missed/rejected signal report from SQLite and runtime logs."""
        date_str = str(date_str or datetime.now(IST).date().isoformat())
        report_dir = Path("data_store") / "reports"
        report_dir.mkdir(parents=True, exist_ok=True)

        decisions = list(db.load_signal_decisions(date_str))
        session_rows = list(db.load_session_signals(date_str))
        seen_messages = {
            str(item.get("message") or "").strip()
            for item in decisions
            if str(item.get("message") or "").strip()
        }
        match_terms = (
            "signal rejected",
            "entry blocked",
            "signal blocked",
            "discarded",
            "repainted during",
            "repaint guard",
            "signal waiting",
            "signal ignored",
            "concurrency guard: blocked",
            "live gate: blocked",
            "ghost guard",
        )

        def add_log_decision(raw_message: str, timestamp: str, source: str) -> None:
            message = str(raw_message or "").strip()
            lowered = message.lower()
            if not message or not any(term in lowered for term in match_terms):
                return
            if message in seen_messages:
                return
            seen_messages.add(message)
            instrument = next(
                (
                    name
                    for name in ("MIDCPNIFTY", "BANKNIFTY", "SENSEX", "NIFTY")
                    if re.search(rf"\b{name}\b", message, flags=re.IGNORECASE)
                ),
                "",
            )
            tf_match = re.search(r"\b(1min|5min|15min)\b", message, flags=re.IGNORECASE)
            direction_match = re.search(r"\b(LONG|SHORT|BUY|SELL)\b", message, flags=re.IGNORECASE)
            decisions.append(
                {
                    "id": str(uuid.uuid5(uuid.NAMESPACE_URL, f"{date_str}|{source}|{message}")),
                    "date": date_str,
                    "timestamp": timestamp,
                    "instrument": instrument,
                    "timeframe": tf_match.group(1).lower() if tf_match else "",
                    "direction": direction_match.group(1).upper() if direction_match else "",
                    "status": "REJECTED" if "reject" in lowered or "blocked" in lowered else "MISSED",
                    "reason": message.rsplit(" - ", 1)[-1] if " - " in message else message,
                    "message": message,
                    "source": source,
                }
            )

        for item in list(getattr(self, "activity_log", []) or []):
            raw = re.sub(r"^[^\w\[]+\s*", "", str(item.get("msg") or ""))
            add_log_decision(
                raw,
                f"{date_str}T{str(item.get('time') or '00:00:00')}",
                "activity_log",
            )

        target_day = datetime.fromisoformat(date_str).date()
        for log_path in sorted(Path(".").glob("runtime*.err.log")):
            try:
                if datetime.fromtimestamp(log_path.stat().st_mtime, tz=IST).date() != target_day:
                    continue
                with log_path.open("r", encoding="utf-8", errors="ignore") as handle:
                    handle.seek(0, 2)
                    size = handle.tell()
                    handle.seek(max(0, size - 4_000_000))
                    for line in handle:
                        lowered = line.lower()
                        if not any(term in lowered for term in match_terms):
                            continue
                        time_match = re.search(r"\b(\d{2}:\d{2}:\d{2})\b", line)
                        message = line.split("|", 2)[-1].strip()
                        add_log_decision(
                            message,
                            f"{date_str}T{time_match.group(1) if time_match else '00:00:00'}",
                            f"log:{log_path.name}",
                        )
            except Exception as exc:
                logger.debug(f"Signal report log scan skipped for {log_path}: {exc}")

        decisions.sort(key=lambda item: str(item.get("timestamp") or ""))
        reason_counts: Dict[str, int] = {}
        instrument_counts: Dict[str, int] = {}
        status_counts: Dict[str, int] = {}
        for item in decisions:
            reason = str(item.get("reason") or "Unknown")
            instrument = str(item.get("instrument") or "UNKNOWN")
            status = str(item.get("status") or "REJECTED")
            reason_counts[reason] = reason_counts.get(reason, 0) + 1
            instrument_counts[instrument] = instrument_counts.get(instrument, 0) + 1
            status_counts[status] = status_counts.get(status, 0) + 1

        accepted_rows = [
            row
            for row in session_rows
            if str(row.get("action") or "ENTRY").upper() == "ENTRY"
            and bool(row.get("accepted_by_gate"))
        ]
        exit_rows = [row for row in session_rows if str(row.get("action") or "").upper() == "EXIT"]

        def _reason_family(reason: str) -> str:
            text = str(reason or "").lower()
            if "counter-session-bias" in text or "counter census" in text:
                return "counter_session_bias"
            if "repaint" in text or "stabiliz" in text or "arrow vanished" in text:
                return "stabilization_repaint"
            if "price-action" in text or "resistance" in text or "support" in text:
                return "price_action_location"
            if "quote" in text or "premium" in text:
                return "quote_unavailable"
            if "grade" in text:
                return "grade_preference"
            if "confidence" in text or "quality" in text:
                return "confidence_quality"
            if "no-entry" in text or "late-session" in text or "square-off" in text:
                return "late_session"
            if "concurrency" in text or "capacity" in text:
                return "position_capacity"
            if "risk" in text or "circuit" in text:
                return "risk_guard"
            return "other"

        def _parse_report_timestamp(value: Any) -> Optional[pd.Timestamp]:
            try:
                ts = pd.to_datetime(value, errors="coerce")
                if pd.isna(ts):
                    return None
                if getattr(ts, "tzinfo", None) is not None:
                    ts = ts.tz_convert("Asia/Kolkata").tz_localize(None)
                return ts.to_pydatetime()
            except Exception:
                return None

        def _infer_direction(item: Dict[str, Any]) -> str:
            text = f"{item.get('direction', '')} {item.get('message', '')} {item.get('reason', '')}".upper()
            if "SHORT" in text or "SELL" in text or " BUY PE" in text:
                return "SHORT"
            if "LONG" in text or "BUY" in text or " BUY CE" in text:
                return "LONG"
            return ""

        def _infer_instrument(item: Dict[str, Any]) -> str:
            raw = str(item.get("instrument") or "").upper()
            if raw:
                return raw.split()[0]
            text = f"{item.get('message', '')} {item.get('reason', '')}".upper()
            for name in ("MIDCPNIFTY", "BANKNIFTY", "SENSEX", "NIFTY"):
                if re.search(rf"\b{name}\b", text):
                    return name
            return ""

        candle_cache: Dict[str, pd.DataFrame] = {}

        def _day_1min_candles(instrument: str) -> Optional[pd.DataFrame]:
            instrument = str(instrument or "").split()[0].upper()
            if not instrument:
                return None
            if instrument in candle_cache:
                return candle_cache[instrument]
            path = Path("data_store") / "candles" / f"{instrument}_1min.csv"
            if not path.exists():
                candle_cache[instrument] = pd.DataFrame()
                return candle_cache[instrument]
            try:
                frame = pd.read_csv(path)
                if "timestamp" not in frame.columns or "close" not in frame.columns:
                    candle_cache[instrument] = pd.DataFrame()
                    return candle_cache[instrument]
                frame["timestamp"] = pd.to_datetime(frame["timestamp"], errors="coerce")
                frame = frame.dropna(subset=["timestamp"])
                frame = frame[frame["timestamp"].dt.date == target_day]
                frame = frame.sort_values("timestamp").set_index("timestamp")
                candle_cache[instrument] = frame
            except Exception as exc:
                logger.debug(f"Replay scoring candle load skipped for {instrument}: {exc}")
                candle_cache[instrument] = pd.DataFrame()
            return candle_cache[instrument]

        def _score_rejected_decisions() -> Dict[str, Any]:
            scored: List[Dict[str, Any]] = []
            family_stats: Dict[str, Dict[str, Any]] = {}
            seen_clusters = set()
            force_exit_time = self._configured_session_time("ut_force_exit_time", "15:25")
            for item in decisions:
                status = str(item.get("status") or "").upper()
                if status not in {"REJECTED", "MISSED"}:
                    continue
                instrument = _infer_instrument(item)
                direction = _infer_direction(item)
                ts = _parse_report_timestamp(item.get("timestamp"))
                if not instrument or direction not in {"LONG", "SHORT"} or ts is None:
                    continue
                reason = str(item.get("reason") or item.get("message") or "Unknown")
                family = _reason_family(reason)
                cluster_minute = ts.replace(second=0, microsecond=0)
                cluster_key = (
                    instrument,
                    str(item.get("timeframe") or "").lower(),
                    direction,
                    cluster_minute.isoformat(),
                    family,
                )
                if cluster_key in seen_clusters:
                    continue
                seen_clusters.add(cluster_key)
                frame = _day_1min_candles(instrument)
                if frame is None or frame.empty:
                    continue
                post = frame[frame.index >= pd.Timestamp(ts)]
                if post.empty:
                    continue
                entry_time = post.index[0]
                entry = float(post.iloc[0]["close"])
                if entry <= 0:
                    continue
                h30 = post[post.index <= (entry_time + pd.Timedelta(minutes=30))]
                eod_dt = datetime.combine(entry_time.date(), force_exit_time)
                eod = post[post.index <= pd.Timestamp(eod_dt)]
                if h30.empty:
                    h30 = post.head(1)
                if eod.empty:
                    eod = post

                def _points(window: pd.DataFrame) -> Tuple[float, float, float]:
                    if direction == "LONG":
                        mfe = float(window["high"].max()) - entry
                        mae = float(window["low"].min()) - entry
                        follow = float(window.iloc[-1]["close"]) - entry
                    else:
                        mfe = entry - float(window["low"].min())
                        mae = entry - float(window["high"].max())
                        follow = entry - float(window.iloc[-1]["close"])
                    return round(mfe, 2), round(mae, 2), round(follow, 2)

                mfe_30, mae_30, follow_30 = _points(h30)
                mfe_eod, mae_eod, follow_eod = _points(eod)
                scored_item = {
                    "timestamp": entry_time.isoformat(),
                    "instrument": instrument,
                    "timeframe": str(item.get("timeframe") or ""),
                    "direction": direction,
                    "reason_family": family,
                    "reason": reason,
                    "entry_price": round(entry, 2),
                    "mfe_30m_points": mfe_30,
                    "mae_30m_points": mae_30,
                    "follow_30m_points": follow_30,
                    "mfe_eod_points": mfe_eod,
                    "mae_eod_points": mae_eod,
                    "follow_eod_points": follow_eod,
                    "source": str(item.get("source") or ""),
                }
                scored.append(scored_item)
                stat = family_stats.setdefault(
                    family,
                    {
                        "count": 0,
                        "positive_30m": 0,
                        "positive_eod": 0,
                        "total_mfe_30m_points": 0.0,
                        "total_follow_30m_points": 0.0,
                        "total_follow_eod_points": 0.0,
                    },
                )
                stat["count"] += 1
                stat["positive_30m"] += int(follow_30 > 0)
                stat["positive_eod"] += int(follow_eod > 0)
                stat["total_mfe_30m_points"] = round(stat["total_mfe_30m_points"] + mfe_30, 2)
                stat["total_follow_30m_points"] = round(stat["total_follow_30m_points"] + follow_30, 2)
                stat["total_follow_eod_points"] = round(stat["total_follow_eod_points"] + follow_eod, 2)

            for stat in family_stats.values():
                count = max(1, int(stat.get("count") or 0))
                stat["avg_mfe_30m_points"] = round(float(stat["total_mfe_30m_points"]) / count, 2)
                stat["avg_follow_30m_points"] = round(float(stat["total_follow_30m_points"]) / count, 2)
                stat["avg_follow_eod_points"] = round(float(stat["total_follow_eod_points"]) / count, 2)

            top = sorted(
                scored,
                key=lambda row: (
                    float(row.get("follow_30m_points", 0.0) or 0.0),
                    float(row.get("mfe_30m_points", 0.0) or 0.0),
                ),
                reverse=True,
            )[:25]
            return {
                "generated": True,
                "unique_rejected_clusters": len(seen_clusters),
                "scored_clusters": len(scored),
                "positive_30m": sum(1 for row in scored if float(row.get("follow_30m_points", 0.0) or 0.0) > 0),
                "positive_eod": sum(1 for row in scored if float(row.get("follow_eod_points", 0.0) or 0.0) > 0),
                "by_reason_family": dict(
                    sorted(
                        family_stats.items(),
                        key=lambda pair: float(pair[1].get("total_follow_30m_points", 0.0) or 0.0),
                        reverse=True,
                    )
                ),
                "top_rejected_opportunities": top,
            }

        replay_scored = _score_rejected_decisions()

        report = {
            "date": date_str,
            "generated_at": datetime.now(IST).isoformat(),
            "summary": {
                "missed_or_rejected": len(decisions),
                "accepted_signals": len(accepted_rows),
                "exits": len(exit_rows),
                "replay_scored_clusters": replay_scored.get("scored_clusters", 0),
                "replay_positive_30m": replay_scored.get("positive_30m", 0),
                "by_status": dict(sorted(status_counts.items())),
                "by_instrument": dict(sorted(instrument_counts.items())),
                "top_reasons": dict(
                    sorted(reason_counts.items(), key=lambda item: item[1], reverse=True)[:25]
                ),
            },
            "replay_scored": replay_scored,
            "decisions": decisions,
            "accepted_signals": accepted_rows,
            "exits": exit_rows,
        }

        json_path = report_dir / f"missed_rejected_signals_{date_str}.json"
        csv_path = report_dir / f"missed_rejected_signals_{date_str}.csv"
        json_path.write_text(json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8")
        with csv_path.open("w", newline="", encoding="utf-8-sig") as handle:
            writer = csv.DictWriter(
                handle,
                fieldnames=[
                    "timestamp",
                    "instrument",
                    "timeframe",
                    "direction",
                    "status",
                    "reason",
                    "source",
                    "message",
                ],
            )
            writer.writeheader()
            for item in decisions:
                writer.writerow({key: item.get(key, "") for key in writer.fieldnames})

        report["files"] = {"json": str(json_path), "csv": str(csv_path)}
        return report

    # Exits that must NEVER be delayed for any reason. Matched as substrings, so
    # "TRAILING_STOP", "SL_HIT" and "FORCE_EOD_KILL" all bypass. This list is the whole
    # safety property of the spread deferral below: everything protective leaves
    # immediately, and only a marginal PROFIT-taking exit can ever wait.
    _HARD_EXIT_MARKERS = (
        "STOP", "SL_HIT", "EARLY_LOSS", "LOSS_THREAT", "RUPEE_LOSS", "RECOVERY",
        "SESSION_END", "FORCE", "KILL", "EXPIRY", "REPAINT_ABORT", "LTP_SHOCK",
        "BROKER", "MANUAL", "SIGNAL_INVALIDATED",
    )
    # Only these may be held back, and only while the bid is eating the edge.
    _MARGINAL_EXIT_REASONS = {
        "SMART_PROFIT_LOCK", "MAJOR_WIN_GUARD", "PEAK_THREAT_EXIT", "LOW_GAIN_PROTECT",
        "OI_PCR_REVERSAL", "OPPOSITE_SIGNAL", "REGIME_REVERSAL_PROFIT",
        "LIVE_REVERSAL_EXIT", "CROSS_INDEX_REVERSAL_EXIT", "PROFIT_GIVEBACK",
        "PROFIT_GIVEBACK_GUARD", "REPAINT_GIVEBACK_GUARD", "TREND_FADE_EXIT",
    }

    def _spread_aware_exit_decision(
        self, trade, exit_price: float, reason: str
    ) -> Tuple[bool, str]:
        """Hold a MARGINAL profit-taking option exit while the bid would eat the edge.

        On an index option the quoted spread is frequently wider than the profit a
        marginal lock is trying to capture, so exiting at the bid converts a small win
        into a small loss. This waits a few seconds for the book to tighten.

        Everything that keeps the account safe bypasses it: any protective, loss, forced,
        expiry, broker or manual exit leaves immediately, as does any exit on a losing
        position. And an exchange stop that is already armed AND crossed outranks this
        entirely — Kite fires that SL-M regardless, so delaying locally would only
        desynchronise the book from the broker.
        """
        settings = get_settings()
        if (
            not self._setting_enabled(getattr(settings, "spread_aware_exit_enabled", False), False)
            or str(getattr(self, "mode", "") or "").upper() != "REAL"
            or str(getattr(trade, "inst_type", "") or "").upper() != "OPT"
            or bool(getattr(trade, "is_ghost", False))
        ):
            return False, "not_applicable"
        normalized = str(reason or "").upper().replace(" ", "_")
        if any(marker in normalized for marker in self._HARD_EXIT_MARKERS):
            return False, "hard_exit"
        if normalized not in self._MARGINAL_EXIT_REASONS:
            return False, "reason_not_marginal"

        armed_check = getattr(self, "_armed_broker_stop_crossed", None)
        if callable(armed_check) and armed_check(trade, exit_price):
            return False, "exchange_stop_armed"

        try:
            qty = max(
                1,
                int(getattr(trade, "broker_quantity", 0) or 0)
                or (int(getattr(trade, "lots", 1) or 1) * int(getattr(trade, "lot_size", 1) or 1)),
            )
            entry = float(getattr(trade, "entry_price", 0.0) or 0.0)
            mark = float(exit_price or 0.0)
            current_pnl = (mark - entry) * qty      # options here are always long premium
        except (TypeError, ValueError):
            return False, "unmeasurable"
        if current_pnl <= 0:
            # Never hold a losing position for a better price. That is how a small loss
            # becomes a large one.
            return False, "non_profitable"

        symbol = str(getattr(trade, "trading_symbol", "") or "")
        token = str(getattr(trade, "symbol_token", "") or "")
        quoter = getattr(getattr(self, "data", None), "get_contract_touch_quote", None)
        if not symbol or not token or not callable(quoter):
            return False, "quote_unavailable"
        instrument = str(getattr(trade, "instrument", "") or "").split()
        exchange = "BFO" if instrument and instrument[0].upper() in {"SENSEX", "BANKEX"} else "NFO"
        try:
            quote = quoter(
                exchange, symbol, token,
                max_age_seconds=float(
                    getattr(settings, "execution_touch_quote_max_age_seconds", 1.5) or 1.5
                ),
            )
        except Exception as exc:
            logger.debug(f"Spread-aware exit quote unavailable for {symbol}: {exc}")
            return False, "quote_unavailable"
        if not isinstance(quote, dict) or not quote.get("usable"):
            return False, f"quote_{str((quote or {}).get('reason') or 'unavailable')}"
        bid = float(quote.get("bid", 0.0) or 0.0)
        ask = float(quote.get("ask", 0.0) or 0.0)
        if bid <= 0 or ask < bid:
            return False, "invalid_book"
        mid = (bid + ask) / 2.0
        spread_pct = float(
            quote.get("spread_pct", 0.0) or ((ask - bid) / mid * 100.0 if mid > 0 else 0.0)
        )
        min_spread = max(0.0, float(getattr(settings, "spread_exit_deferral_min_spread_pct", 0.35) or 0.0))
        if spread_pct < min_spread:
            setattr(trade, "_spread_exit_defer_started", 0.0)
            return False, "spread_tight"

        executable_pnl = (bid - entry) * qty
        spread_cost = max(0.0, mid - bid) * qty
        min_net = max(0.0, float(getattr(settings, "spread_exit_min_net_profit_rs", 250.0) or 0.0))
        max_ratio = max(0.0, float(getattr(settings, "spread_exit_max_cost_to_profit_ratio", 0.35) or 0.0))
        cost_ratio = spread_cost / max(1.0, current_pnl)
        if not (executable_pnl <= min_net or cost_ratio >= max_ratio):
            setattr(trade, "_spread_exit_defer_started", 0.0)
            return False, "edge_survives_spread"

        # BOUNDED. Without a ceiling this becomes an open-ended hold on a position the
        # strategy has already decided to leave.
        now_mono = time.monotonic()
        started = float(getattr(trade, "_spread_exit_defer_started", 0.0) or 0.0)
        if started <= 0:
            started = now_mono
            setattr(trade, "_spread_exit_defer_started", started)
        max_seconds = max(0.0, float(getattr(settings, "spread_exit_deferral_max_seconds", 8.0) or 0.0))
        if now_mono - started >= max_seconds:
            setattr(trade, "_spread_exit_defer_started", 0.0)
            return False, f"timeout_release spread={spread_pct:.2f}%"
        return True, (
            f"spread={spread_pct:.2f}% bid={bid:.2f} ask={ask:.2f} "
            f"bidPnL=Rs.{executable_pnl:.0f} cost/edge={cost_ratio:.0%}"
        )

    def _repaint_abort_profit_hold(self, trade, mark: float) -> bool:
        """Whether a repainted LIVE position is already in profit and should be held.

        The session-side sibling `_repaint_abort_held_for_profit` cannot be reused here:
        it routes through `_candidate_gross_pnl`, which reads `candidate.price`. A Trade
        carries `entry_price`, so passing one raises inside that helper's try/except and
        it silently answers False — the mitigation would look wired and never fire.

        Honours the same operator setting, so both paths turn off together.
        """
        if not self._setting_enabled(
            getattr(get_settings(), "repaint_abort_skip_when_profitable", True), True
        ):
            return False
        try:
            entry = float(getattr(trade, "entry_price", 0.0) or 0.0)
            price = float(mark or 0.0)
            if entry <= 0 or price <= 0:
                return False
            # Options are always BOUGHT, so a bought PE profits on its own premium rising
            # exactly as a bought CE does. Direction only matters for a futures short.
            if str(getattr(trade, "inst_type", "") or "").upper() == "OPT":
                return price > entry
            if str(getattr(trade, "direction", "LONG") or "LONG").upper() == "SHORT":
                return price < entry
            return price > entry
        except (TypeError, ValueError):
            return False

    def _repaint_abort_exit_price(self, trade, candidate) -> float:
        """The mark to close at when a repaint aborts a just-entered position.

        `candidate.instrument` is the INDEX name, so `candles.get_latest_price(...)`
        returns the index SPOT. For a bought option that is the wrong instrument
        entirely, and nothing downstream checks the basis: `_close_and_record` takes
        whatever float it is handed.

        A NIFTY 25000CE bought at 120 with spot at 24850, 75 qty, would be recorded as
        exiting at 24850 — a fabricated (24850-120)*75 = Rs 18.5 lakh "profit" written
        into the trade book, and in manual mode shown to the operator on the confirm
        toast as the exit price to approve.

        Options mark on their own premium; the index path keeps its existing behaviour.
        Returns 0.0 when nothing usable is available, so the caller can decline to close
        rather than book a zero exit.
        """
        inst_type = str(getattr(trade, "inst_type", "") or "").upper()
        if inst_type == "OPT":
            for value in (
                getattr(trade, "current_price", None),
                getattr(trade, "entry_price", None),
            ):
                try:
                    price = float(value or 0.0)
                except (TypeError, ValueError):
                    continue
                if price > 0:
                    return price
            return 0.0

        # A FUTURES position marks on the FUTURES price, not on index spot. The two are
        # the same order of magnitude but differ by the basis, which is tens of points on
        # NIFTY and moves intraday — so booking a futures exit at spot misprices the
        # recorded P&L by basis x quantity on every repaint abort.
        #
        # This is the other half of the bug fixed for options today, where marking a
        # bought CE at the index spot booked a fabricated Rs.18.5 lakh. Less violent
        # here, but wrong in the same way: the exit loop already resolves FUT through
        # the live futures LTP and only falls back to a basis-adjusted spot.
        price = None
        try:
            live_fut = self._get_live_fut_ltp_cached(trade)
            if live_fut and float(live_fut) > 0:
                price = float(live_fut)
        except Exception:
            price = None
        if not price:
            try:
                spot = self.candles.get_latest_price(getattr(candidate, "instrument", ""))
            except Exception:
                spot = None
            if spot and float(spot) > 0:
                # Hold the entry basis rather than treating spot as the contract price.
                price = Scanner._fut_price_from_spot_level(trade, float(spot))
        if not price:
            price = getattr(trade, "current_price", None) or getattr(trade, "entry_price", 0.0)
        try:
            return max(0.0, float(price or 0.0))
        except (TypeError, ValueError):
            return 0.0

    def _close_and_record(self, tid: str, exit_price: float, reason: str, exit_time: Optional[datetime] = None):
        """Wraps trade closure to track over-trading metrics"""
        self._reset_daily_counters()
        trade = self.trades.open_trades.get(tid)
        if not trade: return
        defer, spread_context = self._spread_aware_exit_decision(trade, exit_price, reason)
        if defer:
            marker = f"{reason}|{spread_context}"
            if getattr(trade, "_last_spread_defer_log", "") != marker:
                setattr(trade, "_last_spread_defer_log", marker)
                self.log_event(
                    f"Held {reason} for {trade.instrument}: {spread_context}.", "info"
                )
            return
        if str(getattr(trade, "execution_status", "") or "").upper() == "RECOVERY_REQUIRED":
            self.trades.emergency_flatten_trade(
                trade,
                f"Strategy exit {reason} requested while broker recovery was required",
            )
            return

        instrument = str(trade.instrument or "").split()[0]

        # ─── Manual Exit Gate ───
        # In manual/sim mode we do NOT auto-close; we notify once and latch pending_exit
        # so strategy exits (PEAK_THREAT / profit-lock / etc.) cannot re-fire every tick.
        # Ghost/shadow trades are virtual — never park them behind the manual
        # confirmation gate (they latched EXIT_PENDING forever waiting for a
        # human to confirm a virtual exit; 2026-07-10: 24 premarket zombies).
        if (
            not self.auto_mode
            and reason not in ("STALE_SESSION_END",)
            and not bool(getattr(trade, "is_ghost", False))
        ):
            # One-shot for ANY reason once latched (do not re-notify on PEAK after MAJOR_WIN etc.)
            if bool(getattr(trade, "pending_exit", False)) or str(
                getattr(trade, "execution_status", "") or ""
            ).upper() in {"EXIT_PENDING", "PARTIAL_EXIT"}:
                return

            trade.pending_exit = True
            if not str(getattr(trade, "exit_reason", "") or "").strip():
                trade.exit_reason = str(reason or "")
            try:
                setattr(trade, "pending_exit_price", float(exit_price or 0.0))
                setattr(trade, "pending_exit_time", exit_time)
                setattr(trade, "execution_status", "EXIT_PENDING")
            except Exception:
                pass

            try:
                nm = get_notification_manager(asyncio.get_running_loop())
                def make_exit_executor(t_id, e_price, e_reason, e_time):
                    def do_exit():
                        self._close_and_record_internal(t_id, e_price, e_reason, e_time)
                    return do_exit
                
                qty = int(getattr(trade, "quantity", 0) or 0)
                if qty <= 0:
                    qty = max(1, int(getattr(trade, "lots", 1) or 1)) * max(
                        1, int(getattr(trade, "lot_size", 1) or 1)
                    )
                profit = (exit_price - trade.entry_price) if trade.direction == "LONG" else (trade.entry_price - exit_price)
                profit = profit * qty
                
                nm.send_trade_notification(
                    signal_type="EXIT",
                    instrument=trade.instrument,
                    entry_price=exit_price,
                    target_price=trade.target,
                    sl_price=trade.trailing_stop,
                    rr_ratio=trade.rr_ratio,
                    profit=profit,
                    exit_reason=reason,
                    on_execute=make_exit_executor(tid, exit_price, reason, exit_time)
                )
                logger.info(f"📣 MANUAL EXIT SIGNAL: {trade.instrument} @ {exit_price:.2f} (Reason: {reason})")
            except Exception as e:
                logger.error(f"Failed to dispatch manual exit toast: {e}")
            return
            
        self._close_and_record_internal(tid, exit_price, reason, exit_time)

    def _close_and_record_internal(self, tid: str, exit_price: float, reason: str, exit_time: Optional[datetime] = None):
        """Internal closure after manual gate"""
        self._reset_daily_counters()
        trade = self.trades.open_trades.get(tid)
        if not trade: return
        instrument = str(trade.instrument or "").split()[0]
        
        # Close the trade
        self.trades.close_trade(tid, exit_price, reason, exit_time=exit_time)
        # Immediately refresh the dashboard signal/trade panel on exit.
        self._notify_trade_event()

        # Track outcome
        closed_trade = next((t for t in self.trades.closed_trades if t.id == tid), None)
        if closed_trade:
            counted_outcomes = getattr(self, "_counted_outcome_signatures", None)
            if not isinstance(counted_outcomes, set):
                self._counted_outcome_signatures = set()
                counted_outcomes = self._counted_outcome_signatures
            signature = self._closed_outcome_signature(closed_trade)
            if signature not in counted_outcomes:
                counted_outcomes.add(signature)
                self._record_consecutive_loss_outcome(
                    instrument,
                    float(getattr(closed_trade, "pnl", 0.0) or 0.0),
                    str(getattr(closed_trade, "timeframe", "") or ""),
                )

            # Record exit time and direction for cooldown
            self._last_exit_time[instrument] = exit_time if exit_time else datetime.now(IST).replace(tzinfo=None)
            self._note_index_exit_direction(instrument, closed_trade)
            self._trades_today.setdefault(instrument, 0)
            logger.info(
                f"📊 {instrument} Tracker: Daily Trades={self._trades_today[instrument]}, "
                f"Uninterrupted Same-Index Losses={self._losses_today[instrument]}"
            )

            # --- REVERSION SCALP TRACKING (per-instrument, direction-aware) ---
            # Shared with the session-candidate exit path (create_exit): manual/
            # signal mode books virtual candidates that never reach TradeManager,
            # so arming ONLY here left the snapback engine inert in that mode
            # (2026-07-10 live audit: 4 token-matching exits, zero arm attempts).
            self._maybe_arm_reversion_from_exit(
                instrument,
                exited_like=closed_trade,
                reason=str(reason or ""),
                pnl=float(getattr(closed_trade, "pnl", 0.0) or 0.0),
                source_tf=str(getattr(closed_trade, "timeframe", "") or ""),
                when=self._last_exit_time.get(instrument),
            )

    def _update_active_trades(self, allow_blocking: bool = True):
        self._reset_daily_counters()
        for tid, trade in list(self.trades.open_trades.items()):
            # Skip closed / already-latched manual exits (prevents PEAK/exit spam)
            if str(getattr(trade, "status", "") or "").upper() == "CLOSED":
                continue
            # RECOVERY_REQUIRED trades await broker reconciliation / EOD flatten —
            # re-firing strategy exits on them only spams CRITICAL alerts
            # (2026-07-10: PEAK_THREAT loop at ~20/sec over stale rows).
            if bool(getattr(trade, "pending_exit", False)) or str(
                getattr(trade, "execution_status", "") or ""
            ).upper() in {"EXIT_PENDING", "PARTIAL_EXIT", "RECOVERY_REQUIRED"}:
                continue

            price = self.candles.get_latest_price(trade.instrument)
            if price is None or price <= 0: continue
            real_premium = None
            real_fut_price = None
            is_fut_trade = getattr(trade, "inst_type", "FUT") == "FUT"
            if getattr(trade, "inst_type", "FUT") == "OPT":
                real_premium = self._get_live_premium_cached(trade, allow_blocking=allow_blocking)
            elif is_fut_trade:
                real_fut_price = self._get_live_fut_ltp_cached(trade)
            
            # Update current_price
            trade_price = float(price)
            if is_fut_trade:
                if real_fut_price and real_fut_price > 0:
                    trade_price = float(real_fut_price)
                elif getattr(trade, "entry_spot", 0.0) > 0:
                    trade_price = self._fut_price_from_spot_level(trade, float(price))
                trade.current_price = trade_price
            elif getattr(trade, "inst_type", "FUT") == "OPT":
                mark, mark_source, quote_verified = self._active_option_decision_mark(
                    trade,
                    float(price),
                    real_premium,
                )
                trade.current_price = float(mark)
                setattr(trade, "quote_source", mark_source)
                setattr(trade, "quote_verified", bool(quote_verified))
                if real_premium is not None:
                    # Hand TradeManager the VETTED mark, not the raw LTP.
                    # _active_option_decision_mark exists to reject a stale contract
                    # quote and substitute a synthetic one, and this scanner honours it
                    # for its own stop check below. But update_trade was still being
                    # passed the raw premium, and trade_manager.py overwrites
                    # trade.current_price with it — its only guard there is an upper
                    # plausibility bound (~spot*0.12), not a staleness test, so a
                    # rejected quote sailed through and could trigger EARLY_LOSS_CUT or
                    # TRAILING_STOP at a price this function had already refused.
                    # Both directions cost money: a stale low stops out a winner, a
                    # stale high suppresses a stop that should fire.
                    real_premium = float(mark)

            opt_val = trade.current_price if getattr(trade, "inst_type", "FUT") == "OPT" else trade_price

            # Define conversion helpers for this trade
            def prem_to_spot(prem_val):
                if getattr(trade, "inst_type", "FUT") != "OPT":
                    return prem_val
                mult = abs(getattr(trade, "instrument_multiplier", 0.5)) or 0.5
                spot_dist = (trade.entry_price - prem_val) / mult
                if trade.direction == "LONG":
                    return trade.entry_spot - spot_dist
                else:
                    return trade.entry_spot + spot_dist

            def spot_to_prem(spot_val):
                if getattr(trade, "inst_type", "FUT") != "OPT":
                    return spot_val
                mult = getattr(trade, "instrument_multiplier", 0.5)
                spot_change = spot_val - trade.entry_spot
                return trade.entry_price + (spot_change * mult)

            regime = self._get_trade_regime(trade)
            latest_time = (
                datetime.now(IST).replace(tzinfo=None)
                if getattr(self, "mode", "") != "HISTORICAL"
                else self.candles.get_max_timestamp()
            )

            # Live unrealized for distress reversion + intel exit voting.
            try:
                live_unreal = float(
                    getattr(trade, "unrealized_pnl", None)
                    if getattr(trade, "unrealized_pnl", None) is not None
                    else getattr(trade, "pnl", 0.0) or 0.0
                )
            except Exception:
                live_unreal = 0.0
            if live_unreal == 0.0:
                try:
                    entry_px = float(getattr(trade, "entry_price", 0.0) or 0.0)
                    mark_px = float(opt_val or 0.0)
                    qty = float(
                        getattr(trade, "quantity", None)
                        or getattr(trade, "qty", None)
                        or getattr(trade, "lots", 1)
                        or 1
                    )
                    lot_mult = float(getattr(trade, "lot_size", 1) or 1)
                    if entry_px > 0 and mark_px > 0:
                        # Options are always BOUGHT, so a premium RISE is profit for a
                        # PE as much as a CE. Reading direction alone reported a winning
                        # PE as a loser, and live_unreal feeds the distress-reversion arm
                        # and the is_losing flag on the OI/PCR reversal vote.
                        signed = (mark_px - entry_px) if (
                            str(getattr(trade, "inst_type", "")).upper() == "OPT"
                            or str(getattr(trade, "direction", "")).upper() == "LONG"
                        ) else (entry_px - mark_px)
                        # OPT qty often already includes lot; keep simple Rs estimate.
                        live_unreal = signed * abs(qty) * (lot_mult if abs(qty) < 50 else 1.0)
                except Exception:
                    pass

            # Open-trade distress: underwater + reverse/fast opposite → reversion window.
            try:
                self._maybe_arm_open_distress_reversion(
                    trade,
                    unrealized_pnl=live_unreal,
                    latest_time=latest_time,
                )
            except Exception:
                pass

            # ── Intelligence-Based Early Exit (Patch) ──
            from config.settings import get_settings
            settings = get_settings()
            if getattr(settings, "ut_intel_early_exit", False):
                # allow_blocking=False means "you are on the 100ms scanner event loop".
                # It was threaded to the premium fetch and stopped there, so this call
                # went on recomputing the full intelligence bundle -- measured at 48ms
                # with a 40-strike chain -- inside a 100ms budget, every time the cache
                # expired. Read the cache on the fast path and let the next unhurried
                # pass do the work; an early exit that waits one cycle is not worse than
                # a scanner loop that misses its cadence.
                intel_result = (
                    self._get_trade_intel(trade)
                    if allow_blocking
                    else self._cached_timeframe_intel(
                        str(getattr(trade, "instrument", "") or "").upper(),
                        str(getattr(trade, "timeframe", "5min") or "5min").lower(),
                        allow_fallback=True,
                    )
                )
                if intel_result is not None and not allow_blocking:
                    # The cache read above has no age bound, and this result can CLOSE a
                    # live position via OI_PCR_REVERSAL. When the scan loop stalls — the
                    # exact condition the fast path exists for — the bundle stops
                    # refreshing while this 100ms loop keeps acting on it, so the exit
                    # fires on evidence that may have reverted minutes ago.
                    #
                    # loss_guard_intel_max_age_seconds (90s) is this codebase's existing
                    # answer to "too old to drive a decision" and sits well above the 30s
                    # recompute TTL, so a healthy loop is never affected. Dropping the
                    # read simply defers the exit to the next unhurried pass, which is
                    # what the comment above already intends.
                    try:
                        max_age = float(
                            getattr(get_settings(), "loss_guard_intel_max_age_seconds", 90.0)
                            or 90.0
                        )
                    except (TypeError, ValueError):
                        max_age = 90.0
                    age = Scanner._intel_age_seconds(
                        self,
                        intel_result,
                        str(getattr(trade, "instrument", "") or "").upper(),
                        latest_time,
                    )
                    if age is not None and age > max_age:
                        self._diag_inc("intel", "fast_path_stale_skipped")
                        intel_result = None
                if intel_result:
                    # is_losing uses live unrealized for 2-vote OI/PCR (gap2).
                    # unrealized_pnl is NET of estimated charges, so it opens at
                    # minus the round trip — see _position_is_underwater.
                    reversal_reason = self._intel_reversal_reason(
                        trade.direction,
                        intel_result,
                        is_losing=self._position_is_underwater(trade, live_unreal),
                    )
                    if reversal_reason:
                        fresh, stale_text = self._intel_reversal_is_new_evidence(
                            trade, trade.direction, intel_result
                        )
                        if not fresh:
                            marker = f"{latest_time:%H:%M}:noflip"
                            if getattr(trade, "_last_stale_intel_exit", "") != marker:
                                setattr(trade, "_last_stale_intel_exit", marker)
                                self.log_event(
                                    f"Held {trade.instrument} {trade.timeframe} through OI/PCR flip; "
                                    f"not a reversal ({stale_text}).",
                                    "info",
                                )
                            reversal_reason = None
                    if reversal_reason and self._intel_exit_blocked_by_trend(trade, regime):
                        marker = f"{latest_time:%H:%M}:trendskip"
                        if getattr(trade, "_last_trend_skip_intel_exit", "") != marker:
                            setattr(trade, "_last_trend_skip_intel_exit", marker)
                            self.log_event(
                                f"Held {trade.instrument} {trade.timeframe} through contrarian OI/PCR flip; "
                                f"regime {regime} aligned with {trade.direction}.",
                                "info",
                            )
                        reversal_reason = None
                    if reversal_reason:
                        defer_exit, defer_text = self._should_defer_option_intel_exit(
                            trade,
                            opt_val,
                            latest_time,
                            reversal_reason,
                            regime=regime,
                        )
                        if defer_exit:
                            self.log_event(
                                f"Deferred intelligence exit for {trade.instrument} {trade.timeframe}: {reversal_reason}; {defer_text}.",
                                "info",
                            )
                        else:
                            logger.info(f"🚨 OI/PCR Reversal Exit for {trade.instrument} {trade.direction}: {reversal_reason}")
                            self._close_and_record(tid, opt_val, "OI_PCR_REVERSAL", exit_time=latest_time)
                            continue
                    agg = intel_result.get("aggregate", {})
                    score = agg.get("score", 0.0)

                    if trade.direction == "LONG" and score < -40.0:
                        reason = f"Intelligence flip score {score:.1f}"
                        defer_exit, defer_text = self._should_defer_option_intel_exit(
                            trade,
                            opt_val,
                            latest_time,
                            reason,
                            regime=regime,
                        )
                        if defer_exit:
                            self.log_event(
                                f"Deferred intelligence exit for {trade.instrument} {trade.timeframe}: {reason}; {defer_text}.",
                                "info",
                            )
                        else:
                            logger.info(f"🚨 Intelligence Early Exit for {trade.instrument} LONG: Score={score}")
                            self._close_and_record(tid, opt_val, "INTEL_FLIP", exit_time=latest_time)
                            continue
                    elif trade.direction == "SHORT" and score > 40.0:
                        reason = f"Intelligence flip score {score:.1f}"
                        defer_exit, defer_text = self._should_defer_option_intel_exit(
                            trade,
                            opt_val,
                            latest_time,
                            reason,
                            regime=regime,
                        )
                        if defer_exit:
                            self.log_event(
                                f"Deferred intelligence exit for {trade.instrument} {trade.timeframe}: {reason}; {defer_text}.",
                                "info",
                            )
                        else:
                            logger.info(f"🚨 Intelligence Early Exit for {trade.instrument} SHORT: Score={score}")
                            self._close_and_record(tid, opt_val, "INTEL_FLIP", exit_time=latest_time)
                            continue

            # ── Smart Trailing Patch ──
            if getattr(settings, "ut_smart_trailing", False):
                key_tf = f"{trade.instrument}_{trade.timeframe}"
            else:
                key_tf = f"{trade.instrument}_1min"

            engine_tf = self.mtf.engines.get(key_tf)
            latest_time = self.candles.get_max_timestamp()
            if not engine_tf:
                logger.warning(f"Active trade guard running without UT engine state for {trade.instrument}; trailing skipped, P&L lock still active.")

            state_tf = engine_tf.get_state(key_tf) if engine_tf else None
            raw_ts = state_tf.trailing_stop if state_tf else 0.0

            # Initialize new_stop as spot index level
            if getattr(trade, "inst_type", "FUT") == "OPT":
                new_stop = prem_to_spot(trade.current_stop)
            else:
                new_stop = trade.current_stop

            # ── Adaptive Logic based on Market Regime ──
            # 1. TRENDING (Normal ATR Trailing)
            if is_trending_regime(regime):
                if raw_ts > 0:
                    trade_raw_ts = self._fut_price_from_spot_level(trade, raw_ts) if is_fut_trade else raw_ts
                    # Only move stop in favorable direction
                    if trade.direction == "LONG":
                        new_stop = max(new_stop, trade_raw_ts)
                    else:
                        new_stop = min(new_stop, trade_raw_ts)

            # 2. VOLATILE / REVERSAL / CHOPPY (Tight Trailing)
            elif uses_tight_trailing(regime):
                df_1m = self.candles.get_candles(trade.instrument, "1min")
                if df_1m is not None and len(df_1m) > 2:
                    last_low = df_1m['low'].iloc[-2]
                    last_high = df_1m['high'].iloc[-2]

                    if trade.direction == "LONG":
                        # Trail by last candle's low (Tight)
                        trade_last_low = self._fut_price_from_spot_level(trade, last_low) if is_fut_trade else last_low
                        new_stop = max(new_stop, trade_last_low)
                    else:
                        # Trail by last candle's high (Tight)
                        trade_last_high = self._fut_price_from_spot_level(trade, last_high) if is_fut_trade else last_high
                        new_stop = min(new_stop, trade_last_high)

            # 3. PROFIT PROTECTOR (Lock-in at 1:1 RR)
            # Use entry_spot for options so we compare Spot with Spot
            ref_entry = trade.entry_spot if trade.inst_type == "OPT" else trade.entry_price
            risk_dist = abs(ref_entry - prem_to_spot(trade.trailing_stop)) if trade.inst_type == "OPT" else abs(ref_entry - trade.trailing_stop)
            ref_current = price if trade.inst_type == "OPT" else trade_price
            current_profit_pts = (ref_current - ref_entry) if trade.direction == "LONG" else (ref_entry - ref_current)
            premium_profit_pts = (
                float(trade.current_price or 0.0) - float(trade.entry_price or 0.0)
                if trade.inst_type == "OPT"
                else current_profit_pts
            )
            cascade_ctx = self._trade_one_way_cascade_context(trade, latest_time)
            cascade_runner = bool(cascade_ctx and premium_profit_pts > 0)
            if cascade_runner:
                setattr(trade, "one_way_cascade_entry", True)
                setattr(trade, "one_way_cascade_context", dict(cascade_ctx or {}))
                setattr(trade, "scalp_lock_mode", False)
                if not bool(getattr(trade, "runner_mode", False)):
                    trade.runner_mode = True
                    trade.original_target_distance = abs(float(trade.target or 0.0) - float(trade.entry_price or 0.0))
                    trade.target = 0
                    marker = f"{latest_time:%H:%M}:{trade.instrument}:{trade.timeframe}"
                    if getattr(trade, "_last_one_way_runner_log", "") != marker:
                        setattr(trade, "_last_one_way_runner_log", marker)
                        self.log_event(
                            f"One-way cascade runner enabled for {trade.instrument} {trade.timeframe}: "
                            f"{cascade_ctx.get('reason', 'broad directional cascade')}.",
                            "trade",
                        )

            if current_profit_pts > risk_dist:
                buffer = ref_entry * 0.0005 # Tighten buffer (0.05%)
                old_stop = new_stop
                if trade.direction == "LONG":
                    new_stop = max(new_stop, ref_entry + buffer)
                else:
                    new_stop = min(new_stop, ref_entry - buffer)

                if new_stop != old_stop:
                    self.log_event(f"🛡️ Profit Protector: Locking BE for {trade.instrument}", "trade")

            # ── 4. TARGET TRAILING & RUNNER MODE (T1 -> T2 -> T3) ──
            if trade.target > 0 or getattr(trade, 'runner_mode', False):
                rr_settings = get_settings()
                runner_unlock_ratio = min(1.0, max(0.50, float(getattr(rr_settings, "dynamic_rr_runner_unlock_ratio", 0.95) or 0.95)))
                runner_lock_pct = self._dynamic_runner_lock_pct(
                    float(getattr(rr_settings, "dynamic_rr_runner_lock_pct", 0.90) or 0.90),
                    regime,
                )
                if cascade_runner and isinstance(cascade_ctx, dict):
                    runner_lock_pct = min(
                        0.98,
                        max(0.50, float(cascade_ctx.get("runner_lock_pct", runner_lock_pct) or runner_lock_pct)),
                    )
                # Use entry_spot for options so we compare Spot with Spot
                ref_entry = trade.entry_spot if trade.inst_type == "OPT" else trade.entry_price

                # Check if T1 was already hit and we are in runner mode
                is_runner = getattr(trade, 'runner_mode', False)

                if not is_runner and trade.target > 0:
                    # Logic to activate Runner Mode at T1 (or 90% of T1)
                    if trade.inst_type == "OPT":
                        target_distance = abs(trade.target - trade.entry_price)
                        threshold_t1 = target_distance * runner_unlock_ratio
                        current_move = abs(trade.current_price - trade.entry_price)
                        is_correct_direction = trade.current_price > trade.entry_price
                    else:
                        target_distance = abs(trade.target - ref_entry)
                        threshold_t1 = target_distance * runner_unlock_ratio
                        target_current = price if trade.inst_type == "OPT" else trade_price
                        current_move = abs(target_current - ref_entry)
                        is_correct_direction = (trade.direction == "LONG" and target_current > ref_entry) or                                              (trade.direction == "SHORT" and target_current < ref_entry)

                    reached_t1 = is_correct_direction and current_move >= threshold_t1
                    # Big-move ride: engage the runner EARLY (before target) for a proven
                    # winner in a strong trend so a big move is not cut at the fixed target.
                    # Small gains never qualify (see _big_move_expected).
                    big_move_ok = False
                    big_reason = ""
                    if (
                        is_correct_direction
                        and not reached_t1
                        and self._setting_enabled(
                            getattr(get_settings(), "trend_runner_engage_before_target_enabled", True), True
                        )
                    ):
                        big_move_ok, big_reason = self._big_move_expected(
                            trade,
                            gain_r=self._trade_gain_in_r(trade, current_move),
                            regime=regime,
                        )
                    if reached_t1 or big_move_ok:
                        trade.runner_mode = True
                        trade.original_target_distance = target_distance
                        trade.target = 0 # Remove hard target to let it run to T2/T3
                        lock_label = f"{runner_lock_pct * 100:.0f}%"
                        note = "TARGET 1 HIT" if reached_t1 else f"big-move ride ({big_reason})"
                        self.log_event(f"🚀 {note} for {trade.instrument}. Entering Runner Mode ({lock_label} Gain Lock).", "trade")
                        logger.success(f"🔥 Runner Mode Active: {trade.instrument}. Hard target removed, locking {lock_label} gains.")

                # ── Runner Mode Trailing (90% Gain Lock) ──
                if getattr(trade, 'runner_mode', False):
                    if trade.inst_type == "OPT":
                        current_gain_pts = max(0, (trade.current_price - trade.entry_price))
                    else:
                        current_gain_pts = max(0, abs(trade_price - trade.entry_price))

                    if cascade_runner:
                        locked_gain_pts = current_gain_pts * runner_lock_pct
                    else:
                        # Fixed trailing distance logic based on original target profit magnitude
                        orig_target_dist = getattr(trade, 'original_target_distance', 0)
                        if orig_target_dist <= 0:
                            orig_target_dist = abs(trade.entry_price - trade.trailing_stop) * trade.rr_ratio

                        trail_dist = orig_target_dist * (1.0 - runner_lock_pct)

                        # Lock the peak gain minus the fixed trail distance
                        locked_gain_pts = max(0, current_gain_pts - trail_dist)

                    if trade.inst_type == "OPT":
                        multiplier = abs(trade.instrument_multiplier) or 0.5
                        # Convert to spot: Spot = Entry Spot + (Gain / Multiplier) if Call, else Entry Spot - (Gain / Multiplier)
                        spot_gain = locked_gain_pts / multiplier
                        new_runner_stop = (trade.entry_spot + spot_gain) if trade.direction == "LONG" else (trade.entry_spot - spot_gain)
                    else:
                        new_runner_stop = (trade.entry_price + locked_gain_pts) if trade.direction == "LONG" else (trade.entry_price - locked_gain_pts)

                    # Update stop if the new locked gain is higher (trailing)
                    if trade.direction == "LONG":
                        new_stop = max(new_stop, new_runner_stop)
                    else:
                        new_stop = min(new_stop, new_runner_stop)

            # ── 5. SMART PROFIT LOCK & REVERSAL GUARD ──
            # Calculate absolute PnL in Rupees for institutional exit rules
            current_pnl_rs = 0.0
            entry_val = trade.entry_price
            # The CONFIRMED fill, not the intended size. `quantity` is lots * lot_size;
            # on a partial fill the broker confirms less and pnl_quantity carries that.
            # Its own docstring cites the case: 65 intended / 30 filled reported -860
            # against a true -440. This qty feeds current_pnl_rs, candle_extreme_pnl,
            # peak_pnl and initial_risk_live, so an overstatement arms the rupee loss
            # band (Rs.1,000/lot) and even the Rs.3,000 catastrophe force-exit on money
            # that was never at risk. Falls back to the intended size pre-fill.
            qty = getattr(trade, "pnl_quantity", None) or getattr(
                trade, "quantity", getattr(trade, "qty", 0)
            )
            inst_mult = getattr(trade, 'instrument_multiplier', 1.0)
            if trade.inst_type == "OPT":
                current_pnl_rs = (trade.current_price - entry_val) * qty
                current_gain_pct = (current_pnl_rs / (entry_val * qty)) * 100.0 if entry_val > 0 and qty > 0 else 0
            else:
                current_pnl_rs = (trade_price - entry_val) * qty if trade.direction == "LONG" else (entry_val - trade_price) * qty
                current_pnl_rs *= inst_mult
                current_gain_pct = (current_pnl_rs / (entry_val * qty * inst_mult)) * 100.0 if entry_val > 0 and qty > 0 and inst_mult > 0 else 0

            candle_extreme_price = self._trade_candle_extreme_price(trade, latest_time)
            if candle_extreme_price > 0:
                if trade.inst_type == "OPT":
                    # _trade_candle_extreme_price already returns premium space for options.
                    prem_extreme = float(candle_extreme_price)
                    prem_extreme = self._sanitize_option_mark(
                        trade,
                        prem_extreme,
                        float(price),
                        "intrabar peak reconstruction",
                    )
                    candle_extreme_pnl = (prem_extreme - entry_val) * qty
                else:
                    candle_extreme_pnl = (
                        (candle_extreme_price - entry_val) * qty
                        if trade.direction == "LONG"
                        else (entry_val - candle_extreme_price) * qty
                    )
                    candle_extreme_pnl *= inst_mult
            else:
                candle_extreme_pnl = 0.0

            # Update peak PnL from sampled LTP plus intrabar candle extremes.
            inst_mult_peak = getattr(trade, 'instrument_multiplier', 1.0) if getattr(trade, 'inst_type', 'FUT') != 'OPT' else 1.0
            trade.peak_pnl = max(getattr(trade, 'peak_pnl', 0.0), current_pnl_rs, candle_extreme_pnl)
            peak_gain_pct = (trade.peak_pnl / (entry_val * qty * inst_mult_peak)) * 100.0 if entry_val > 0 and qty > 0 and inst_mult_peak > 0 else 0

            lock_dir = "LONG" if trade.inst_type == "OPT" else trade.direction
            self._ensure_trade_like_initial_stop(trade)
            initial_risk_live = self._trade_like_initial_risk_rs(
                trade,
                qty=int(qty or 0),
                inst_mult=inst_mult_peak,
            )
            pre_profit_lock_stop = float(new_stop or 0.0)
            lock_stop, lock_reason, lock_ratio = self._profit_lock_floor(
                entry_val, lock_dir, int(qty or 0), trade.peak_pnl,
                bool(getattr(trade, "scalp_lock_mode", False)),
                inst_mult=inst_mult_peak, initial_risk_rs=initial_risk_live,
                timeframe=getattr(trade, "timeframe", ""),
                now=latest_time,
                trade_like=trade,
            )
            if lock_reason and cascade_runner and current_pnl_rs > 0.0:
                lock_stop = 0.0
                lock_reason = ""
                marker = f"{latest_time:%H:%M}:{trade.peak_pnl:.0f}:{current_pnl_rs:.0f}"
                if getattr(trade, "_last_one_way_profit_lock_defer_log", "") != marker:
                    setattr(trade, "_last_one_way_profit_lock_defer_log", marker)
                    self.log_event(
                        f"Deferred profit lock for {trade.instrument} {trade.timeframe}: "
                        f"{cascade_ctx.get('reason', 'one-way cascade still aligned')}.",
                        "info",
                    )
            if lock_reason == "MAJOR_WIN_GUARD" and trade.inst_type == "FUT":
                should_exit_major, guard_context = self._should_exit_major_win_guard(
                    trade,
                    float(trade_price),
                    trade.peak_pnl,
                    current_pnl_rs,
                    latest_time,
                )
                if not should_exit_major:
                    lock_stop = 0.0
                    lock_reason = ""
                    self.log_event(
                        f"Deferred major-win lock for {trade.instrument} {trade.timeframe}: {guard_context}.",
                        "info",
                    )
            
            lock_stop_spot = prem_to_spot(lock_stop) if lock_stop > 0 else 0.0
            if lock_stop_spot > 0:
                if trade.direction == "LONG":
                    new_stop = max(new_stop, lock_stop_spot)
                else:
                    new_stop = min(new_stop, lock_stop_spot)

            if trade.inst_type == "OPT":
                proposed_prem_stop = spot_to_prem(new_stop)
                adjusted_prem_stop, breathing, clamped = self._apply_option_stop_breathing_room(
                    trade,
                    proposed_prem_stop,
                    latest_time=latest_time,
                    regime=regime,
                    profit_lock_reason=lock_reason,
                )
                if clamped:
                    self.log_event(
                        f"Option breathing room kept live {trade.instrument} {trade.timeframe} stop at {adjusted_prem_stop:.2f} "
                        f"(floor {breathing:.2f}) instead of {proposed_prem_stop:.2f}.",
                        "info",
                    )
                    new_stop = prem_to_spot(adjusted_prem_stop)

            if lock_reason:
                lock_hit_price = price if trade.inst_type == "OPT" else trade_price
                lock_hit = (trade.direction == "LONG" and lock_hit_price <= new_stop) or (trade.direction == "SHORT" and lock_hit_price >= new_stop)
                if lock_hit:
                    exit_val = spot_to_prem(new_stop) if trade.inst_type == "OPT" else new_stop
                    if lock_reason in {"SMART_PROFIT_LOCK", "MAJOR_WIN_GUARD"}:
                        lock_check_price = float(opt_val if trade.inst_type == "OPT" else trade_price)
                        defer_lock, defer_reason = self._should_defer_trend_option_profit_lock(
                            trade,
                            lock_check_price,
                            float(exit_val or 0.0),
                            current_pnl_rs,
                            trade.peak_pnl,
                            latest_time,
                            regime=regime,
                        )
                        if defer_lock:
                            marker = f"{latest_time:%H:%M}:{trade.peak_pnl:.0f}:{current_pnl_rs:.0f}"
                            if getattr(trade, "_last_trend_profit_lock_defer_log", "") != marker:
                                setattr(trade, "_last_trend_profit_lock_defer_log", marker)
                                self.log_event(
                                    f"Deferred {lock_reason} for {trade.instrument} {trade.timeframe}: {defer_reason}.",
                                    "info",
                                )
                            lock_reason = ""
                            lock_stop = 0.0
                            new_stop = pre_profit_lock_stop
                            lock_hit = False
                        else:
                            setattr(trade, "_last_trend_profit_lock_defer_reason", defer_reason)
                    if lock_hit:
                        if trade.inst_type == "OPT":
                            locked_pnl = (exit_val - entry_val) * qty
                        else:
                            locked_pnl = (exit_val - entry_val) * qty if trade.direction == "LONG" else (entry_val - exit_val) * qty
                        logger.warning(
                            f"Profit Lock Stop Hit for {trade.instrument}: Peak Rs.{trade.peak_pnl:.0f}, "
                            f"Locked {lock_ratio:.0%} Rs.{locked_pnl:.0f}"
                        )
                        self._close_and_record(tid, exit_val, lock_reason, exit_time=latest_time)
                        continue

            # Rule 1: R-aware smart protection. The old hard-coded Rs.1000
            # threshold clipped option winners even when configured risk was
            # several thousand rupees.
            smart_min_peak_live = self._profit_lock_min_peak(
                bool(getattr(trade, "scalp_lock_mode", False)),
                initial_risk_live,
                getattr(trade, "timeframe", ""),
                latest_time,
                trade_like=trade,
            )

            def handle_live_recovery_watch(proposed_reason: str) -> str:
                action, recovery_ctx = self._loss_recovery_watch_decision(
                    trade,
                    current_price=float(opt_val),
                    current_pnl_rs=current_pnl_rs,
                    peak_pnl=trade.peak_pnl,
                    initial_risk_rs=initial_risk_live,
                    latest_time=latest_time,
                    regime=regime,
                    proposed_exit_reason=proposed_reason,
                )
                if action == "HOLD":
                    marker = f"{latest_time:%H:%M}:{current_pnl_rs:.0f}:{proposed_reason}"
                    if getattr(trade, "_last_loss_recovery_hold_log", "") != marker:
                        setattr(trade, "_last_loss_recovery_hold_log", marker)
                        self.log_event(
                            f"Recovery watch holding live {trade.instrument} {trade.timeframe}: {recovery_ctx}.",
                            "info",
                        )
                    return "HOLD"
                if action == "EXIT":
                    logger.warning(f"🚨 RECOVERY_WATCH_EXIT for {trade.instrument}: {recovery_ctx}")
                    self._close_and_record(tid, opt_val, "RECOVERY_WATCH_EXIT", exit_time=latest_time)
                    self.log_event(
                        f"🛟 Recovery watch exit: {trade.instrument} @ ₹{current_pnl_rs:.0f} ({recovery_ctx})",
                        "trade",
                    )
                    return "EXIT"
                return "NONE"

            # Early loss-guard (symmetric FUT/OPT): base 0.8R; accelerates to
            # 0.55R / 0.35R when intel + price action confirm a BIG reversal
            # (not a small pullback). Mirrors profit-lock on the downside.
            try:
                should_cut, cut_detail, cut_r = self._loss_guard_decision(
                    trade,
                    current_pnl_rs=current_pnl_rs,
                    initial_risk_rs=initial_risk_live,
                    latest_time=latest_time,
                    regime=regime,
                    current_price=float(opt_val if trade.inst_type == "OPT" else trade_price),
                )
                if should_cut and current_pnl_rs < 0.0:
                    recovery_action = handle_live_recovery_watch("EARLY_LOSS_CUT")
                    if recovery_action in {"HOLD", "EXIT"}:
                        continue
                    exit_val = float(opt_val if trade.inst_type == "OPT" else trade_price)
                    logger.warning(
                        f"Early Loss Cut for {trade.instrument}: {cut_detail} "
                        f"(PnL ₹{current_pnl_rs:.0f}, thr {cut_r:.2f}R)"
                    )
                    self._close_and_record(tid, exit_val, "EARLY_LOSS_CUT", exit_time=latest_time)
                    self.log_event(
                        f"Loss Guard: {trade.instrument} cut @ ₹{current_pnl_rs:.0f} ({cut_detail})",
                        "trade",
                    )
                    continue
            except Exception as exc:
                logger.debug(f"Early loss cut check skipped for {trade.instrument}: {exc}")

            # Rupee loss ladder: OPT from -1000, FUT from -1500 (product arms).
            try:
                live_px = float(opt_val if trade.inst_type == "OPT" else trade_price)
                band_exit, band_reason, band_ctx = self._rupee_loss_band_guard_decision(
                    trade,
                    current_pnl_rs=current_pnl_rs,
                    latest_time=latest_time,
                    regime=regime,
                    current_price=live_px,
                )
                if band_exit and current_pnl_rs < 0.0:
                    recovery_action = handle_live_recovery_watch(band_reason)
                    if recovery_action in {"HOLD", "EXIT"}:
                        continue
                    logger.warning(f"Rupee loss band exit for {trade.instrument}: {band_ctx}")
                    self._close_and_record(tid, live_px, band_reason, exit_time=latest_time)
                    self.log_event(
                        f"Loss Band: {trade.instrument} cut @ ₹{current_pnl_rs:.0f} ({band_ctx})",
                        "trade",
                    )
                    continue
            except Exception as exc:
                logger.debug(f"Live rupee loss-band skipped for {trade.instrument}: {exc}")

            threat_exit, threat_reason, threat_ctx = self._peak_threat_exit_decision(
                trade,
                current_price=float(opt_val if trade.inst_type == "OPT" else trade_price),
                current_pnl_rs=current_pnl_rs,
                peak_pnl=trade.peak_pnl,
                initial_risk_rs=initial_risk_live,
                latest_time=latest_time,
                regime=regime,
                inst_type=getattr(trade, "inst_type", ""),
                option_type=getattr(trade, "option_type", ""),
                direction=getattr(trade, "direction", ""),
            )
            if threat_exit:
                exit_val = float(opt_val if trade.inst_type == "OPT" else trade_price)
                # Log only if not already latched (manual mode one-shot)
                if not bool(getattr(trade, "pending_exit", False)):
                    logger.warning(f"🚨 {threat_reason} for {trade.instrument}: {threat_ctx}")
                    self.log_event(
                        f"💰 {threat_reason}: {trade.instrument} @ ₹{current_pnl_rs:.0f} ({threat_ctx})",
                        "trade",
                    )
                self._close_and_record(tid, exit_val, threat_reason, exit_time=latest_time)
                continue

            ladder_peak_live = Scanner._profit_ladder_pnl(self, trade, trade.peak_pnl, qty)
            if smart_min_peak_live <= trade.peak_pnl and ladder_peak_live < 3000.0:
                # Profit fell below the ladder's own retention, OR the trade earned more
                # than the keep-floor and gave it back. The floor is collapse protection,
                # never a cap on a trade still climbing through it — see
                # _smart_lock_floor_collapse (2026-08-12: auto mode carried the same
                # arm-below-floor defect that cut four signal-mode winners at their peak).
                # The retention comes from _smart_lock_backstop_ratio so auto and signal
                # mode cannot disagree about when a fading winner is done.
                backstop_ratio_live = self._smart_lock_backstop_ratio(
                    lock_ratio, bool(getattr(trade, "scalp_lock_mode", False))
                )
                if current_pnl_rs < (
                    trade.peak_pnl * backstop_ratio_live
                ) or self._smart_lock_floor_collapse(
                    trade.peak_pnl, current_pnl_rs, backstop_ratio_live
                ):
                    if current_pnl_rs < 0.0:
                        recovery_action = handle_live_recovery_watch("SMART_PROFIT_LOCK")
                        if recovery_action in {"HOLD", "EXIT"}:
                            continue
                    logger.warning(f"🚨 Smart Profit Lock Hit for {trade.instrument}: Peak ₹{trade.peak_pnl:.0f}, Current ₹{current_pnl_rs:.0f}")
                    self._close_and_record(tid, lock_stop if lock_stop > 0 else opt_val, "SMART_PROFIT_LOCK", exit_time=latest_time)
                    self.log_event(f"💰 Profit Locked: {trade.instrument} (Retention Guard Hit @ ₹{current_pnl_rs:.0f})", "trade")
                    continue

            # Fix 1/3: sub-1R give-back guard + live regime-reversal profit-taker.
            gb_exit, gb_reason, gb_ctx = self._peak_giveback_or_reversal_exit(
                trade,
                current_pnl_rs=current_pnl_rs,
                peak_pnl=trade.peak_pnl,
                initial_risk_rs=initial_risk_live,
                smart_min_peak=smart_min_peak_live,
                latest_time=latest_time,
                regime=regime,
                inst_type=getattr(trade, "inst_type", ""),
                option_type=getattr(trade, "option_type", ""),
                direction=getattr(trade, "direction", ""),
            )
            if gb_exit:
                if current_pnl_rs < 0.0:
                    recovery_action = handle_live_recovery_watch(gb_reason)
                    if recovery_action in {"HOLD", "EXIT"}:
                        continue
                logger.warning(f"🚨 {gb_reason} for {trade.instrument}: {gb_ctx}")
                self._close_and_record(tid, opt_val, gb_reason, exit_time=latest_time)
                self.log_event(f"💰 {gb_reason}: {trade.instrument} @ ₹{current_pnl_rs:.0f} ({gb_ctx})", "trade")
                continue

            eod_loss_exit, eod_loss_ctx = self._eod_loss_minimize_exit(
                trade,
                current_pnl_rs=current_pnl_rs,
                initial_risk_rs=initial_risk_live,
                latest_time=latest_time,
                regime=regime,
            )
            if eod_loss_exit:
                logger.warning(f"🚨 EOD_LOSS_MINIMIZE for {trade.instrument}: {eod_loss_ctx}")
                self._close_and_record(tid, opt_val, "EOD_LOSS_MINIMIZE", exit_time=latest_time)
                self.log_event(
                    f"🕒 EOD loss minimized: {trade.instrument} @ ₹{current_pnl_rs:.0f} ({eod_loss_ctx})",
                    "trade",
                )
                continue

            # Rule 2: Low-Gain Protection (If gain was > 10% but reversed)
            if peak_gain_pct >= 10.0:
                # If gain drops below 40% of peak or falls near BE (+2% floor)
                if current_gain_pct < (peak_gain_pct * 0.40) or current_gain_pct < 2.0:
                    logger.warning(f"🚨 Low-Gain Protection Hit for {trade.instrument}: Peak {peak_gain_pct:.1f}%, Current {current_gain_pct:.1f}%")
                    self._close_and_record(tid, opt_val, "LOW_GAIN_PROTECT", exit_time=latest_time)
                    continue

            # Rule 3: Major Win Protection (Peak >= Rs.3000)
            if Scanner._profit_ladder_pnl(self, trade, trade.peak_pnl, qty) >= 3000.0:
                if current_pnl_rs < (trade.peak_pnl * 0.75):
                    should_exit, guard_context = (
                        self._should_exit_major_win_guard(
                            trade,
                            float(trade_price),
                            trade.peak_pnl,
                            current_pnl_rs,
                            latest_time,
                        )
                        if str(getattr(trade, "inst_type", "FUT") or "FUT").upper() == "FUT"
                        else (True, "option major-win guard")
                    )
                    if should_exit:
                        logger.warning(
                            f"Major Win Guard for {trade.instrument}: Peak Rs.{trade.peak_pnl:.0f} "
                            f"-> Exit @ Rs.{current_pnl_rs:.0f}; {guard_context}"
                        )
                        self._close_and_record(
                            tid,
                            lock_stop if lock_stop > 0 else opt_val,
                            "MAJOR_WIN_GUARD",
                            exit_time=latest_time,
                        )
                        continue
                    self.log_event(
                        f"Deferred major-win exit for {trade.instrument} {trade.timeframe}: {guard_context}.",
                        "info",
                    )

            # Rule 4: Risk- and volatility-normalized stagnation protection.
            should_stagnate, stagnation_context = self._stagnation_exit_decision(
                trade,
                current_pnl_rs,
                trade.peak_pnl,
                latest_time,
                regime=regime,
            )
            if should_stagnate:
                logger.info(f"Stagnation Exit: {trade.instrument}; {stagnation_context}")
                self._close_and_record(tid, opt_val, "STAGNATION_EXIT", exit_time=latest_time)
                continue

            if False and trade.entry_time and current_pnl_rs >= 300.0:
                time_elapsed = (latest_time - trade.entry_time.replace(tzinfo=None)).total_seconds() / 60.0 if latest_time else 0
                # Exit if held > 20m and current profit is < 85% of peak (stalled)
                stagnation_minutes = max(
                    1.0,
                    float(getattr(settings, "trade_stagnation_minutes", 20.0) or 20.0),
                )
                if time_elapsed >= stagnation_minutes and current_pnl_rs < (trade.peak_pnl * 0.85):
                    logger.info(f"⏳ Stagnation Exit: {trade.instrument} held {time_elapsed:.0f}m, PnL ₹{current_pnl_rs:.0f}")
                    self._close_and_record(tid, opt_val, "STAGNATION_EXIT", exit_time=latest_time)
                    continue

            latest_time = self.candles.get_max_timestamp()

            # ── Live Trade Preservation Patch ──
            if getattr(trade, 'is_live', False) and self.mode == "HISTORICAL":
                triggered = False
                reason = ""
                if trade.inst_type == "OPT":
                    if trade.current_price <= trade.current_stop:
                        triggered = True
                        reason = "TRAILING_STOP"
                    elif trade.target > 0 and trade.current_price >= trade.target:
                        triggered = True
                        reason = "TARGET_HIT"
                else:
                    stop_check_price = trade_price
                    if trade.direction == "LONG":
                        if stop_check_price <= new_stop:
                            triggered = True
                            reason = "TRAILING_STOP"
                        elif stop_check_price >= trade.target and trade.target > 0:
                            triggered = True
                            reason = "TARGET_HIT"
                    else:
                        if stop_check_price >= new_stop:
                            triggered = True
                            reason = "TRAILING_STOP"
                        elif stop_check_price <= trade.target and trade.target > 0:
                            triggered = True
                            reason = "TARGET_HIT"

                if triggered:
                    msg = f"🚨 ALERT: Live Trade {trade.instrument} requires EXIT ({reason}) at {trade.current_price:.2f}!"
                    logger.warning(msg)
                    if self.on_notification:
                        self.on_notification(msg, "warning")

                # Update price and stop in memory so UI shows it, but do NOT close it!
                if trade.inst_type == "OPT":
                    # `new_stop` is SPOT space; trade.current_stop is PREMIUM space (it is
                    # compared against trade.current_price just above). Assigning new_stop
                    # here would store ~24,800 in a field tested against a ~150 premium, so
                    # `150 <= 24800` would fire a spurious TRAILING_STOP alert on every
                    # option, every tick. The old `pass` avoided that but froze the stop at
                    # whatever it held when the mode flipped, so a runner gave back its
                    # whole gain with the dashboard still showing the entry stop.
                    #
                    # Convert, then ratchet one way only. A bought option is always long
                    # premium, so the stop may only rise -- and spot_to_prem divides through
                    # entry_spot, which is a field this codebase has already had corrupted,
                    # so a monotonic guard keeps a bad conversion from LOOSENING a live stop.
                    try:
                        prem_stop = float(spot_to_prem(new_stop))
                    except Exception:
                        prem_stop = 0.0
                    if prem_stop > float(trade.current_stop or 0.0):
                        trade.current_stop = prem_stop
                else:
                    trade.current_stop = new_stop
                continue

            if not self.auto_mode:
                manual_trigger = ""
                if trade.inst_type == "OPT":
                    if trade.current_price <= trade.current_stop:
                        manual_trigger = "TRAILING_STOP"
                    elif trade.target > 0 and trade.current_price >= trade.target:
                        manual_trigger = "TARGET_HIT"
                elif trade.direction == "LONG":
                    if trade_price <= new_stop:
                        manual_trigger = "TRAILING_STOP"
                    elif trade.target > 0 and trade_price >= trade.target:
                        manual_trigger = "TARGET_HIT"
                else:
                    if trade_price >= new_stop:
                        manual_trigger = "TRAILING_STOP"
                    elif trade.target > 0 and trade_price <= trade.target:
                        manual_trigger = "TARGET_HIT"
                if manual_trigger:
                    recovery_action = handle_live_recovery_watch(manual_trigger)
                    if recovery_action in {"HOLD", "EXIT"}:
                        continue
                    marker = f"{manual_trigger}:{latest_time:%Y-%m-%dT%H:%M}"
                    if getattr(trade, "_manual_exit_alert_marker", "") != marker:
                        setattr(trade, "_manual_exit_alert_marker", marker)
                        self._close_and_record(
                            tid,
                            opt_val,
                            manual_trigger,
                            exit_time=latest_time,
                        )
                continue

            auto_stop_trigger = False
            if trade.inst_type == "OPT":
                auto_stop_trigger = trade.current_price <= trade.current_stop
            elif trade.direction == "LONG":
                auto_stop_trigger = trade_price <= new_stop
            else:
                auto_stop_trigger = trade_price >= new_stop
            if auto_stop_trigger:
                recovery_action = handle_live_recovery_watch("TRAILING_STOP")
                if recovery_action in {"HOLD", "EXIT"}:
                    continue

            # Audit #9: pass PREMIUM stop for OPT so TradeManager does not re-map via delta.
            tm_stop = spot_to_prem(new_stop) if trade.inst_type == "OPT" else new_stop
            self.trades.update_trade(
                tid,
                price,
                tm_stop,
                current_time=latest_time,
                real_premium=real_premium,
                real_fut_price=real_fut_price,
            )
            if tid not in self.trades.open_trades:
                # Trade was closed by update_trade (SL or Target)
                # Find it in closed_trades to record metrics
                closed_trade = next((t for t in self.trades.closed_trades if t.id == tid), None)
                if closed_trade:
                    counted_outcomes = getattr(self, "_counted_outcome_signatures", None)
                    if not isinstance(counted_outcomes, set):
                        self._counted_outcome_signatures = set()
                        counted_outcomes = self._counted_outcome_signatures
                    signature = self._closed_outcome_signature(closed_trade)
                    if signature not in counted_outcomes:
                        counted_outcomes.add(signature)
                        self._record_consecutive_loss_outcome(
                            trade.instrument,
                            float(getattr(closed_trade, "pnl", 0.0) or 0.0),
                            str(getattr(trade, "timeframe", "") or ""),
                        )
                    self._last_exit_time[trade.instrument] = latest_time if latest_time else datetime.now(IST).replace(tzinfo=None)
                    self._note_index_exit_direction(trade.instrument, trade)
                    self._trades_today.setdefault(trade.instrument, 0)
                    logger.info(
                        f"📊 {trade.instrument} Tracker (SL/TP): "
                        f"Daily Trades={self._trades_today[trade.instrument]}, "
                        f"Uninterrupted Same-Index Losses={self._losses_today[trade.instrument]}"
                    )

                self.log_event(f"🛑 Trade Closed: {trade.instrument} Stop Hit @ {price:.2f}", "trade")
                self._notify(f"🛑 STOP HIT {trade.direction} {trade.instrument} @ {price:.2f}", "sell")

    def _notify(self, message, msg_type="info"):
        if self.on_notification:
            try: self.on_notification(message, msg_type)
            except Exception as e: logger.debug(f"Ignored exception: {e}")

    def stop(self):
        self._save_warm_memory(force=True)
        try:
            self.generate_daily_signal_report()
        except Exception as exc:
            logger.debug(f"Final daily signal report save skipped: {exc}")
        self.is_running = False
        logger.info("Scanner stopped")

    def update_fyers_token(self, auth_code: str) -> Dict[str, Any]:
        """Update Fyers token and restart history sync if successful"""
        result = self.data.update_fyers_token_from_auth_code(auth_code)
        if result.get("status") == "ok":
            # Force a full history fetch to use the new Fyers token immediately
            self.log_event("âœ… Fyers Token Updated: Restarting Data Sync", "success")
            self.queue_full_recalculation("fyers-token-update")
        return result

    async def update_fyers_token_async(self, auth_code: str) -> Dict[str, Any]:
        """Async entry point used by the dashboard's Fyers auth callback.

        POST /api/fyers_auth awaits this on the scanner loop, so it must be a coroutine.
        The exchange itself performs blocking HTTP, so it runs in a worker thread rather
        than stalling the scanner loop; queue_full_recalculation is already thread-safe
        (it re-schedules onto the scanner loop when called from another thread)."""
        return await asyncio.to_thread(self.update_fyers_token, auth_code)
